-- Verdanturf / Fallarbor / Slateport / Lilycove lobbies only. Battle Tower
-- Teala (and PC 2F cable-club Teala) share gfx 85 with a NULL script pointer.
function Game3.isContestLobbyMap(map)
  if not map then return false end
  if map.contestLobby then return true end
  local g, n = tonumber(map.group), tonumber(map.index)
  if g == nil or n == nil then return false end
  for _, w in pairs(Game3.CONTEST_LOBBY_WARPS) do
    if w.group == g and w.num == n then return true end
  end
  return false
end

