local function loadGenerated(path)
  local CacheFs = require("src.import.CacheFs")
  return CacheFs.loadActive(path)
end

local function namedList(pokemon)
  local list = {}
  local byIndex = pokemon and pokemon.byIndex or {}
  local count = (pokemon and pokemon.count) or 0
  for index = 0, count - 1 do
    local row = byIndex[index]
    local name = row and row.name or ""
    if name ~= "" and not name:match("^[?%-]+$") then
      list[#list + 1] = { id = index, name = name }
    end
  end
  return list
end

function Game3.mapId(group, index)
  return ("g%d_%d"):format(group, index)
end

function Game3.collisionOf(cell)
  return math.floor((cell or 0) / 1024) % 4
end

function Game3.metatileOf(cell)
  return (cell or 0) % 1024
end

-- fieldmap.c MAPGRID_ELEVATION_MASK: bits 12-15. MapGridSetMetatileIdAt
-- keeps them so a setmetatile wall still draws at the cave's height.
function Game3.elevationBits(cell)
  return math.floor((cell or 0) / 4096) * 4096
end

function Game3.elevationOf(cell)
  return math.floor((cell or 0) / 4096) % 16
end

-- event_object_movement.c sObjectEventPriorities_08376060. Field BG1 is
-- OAM-pri 1; lower sprite pri draws in front (elevation 4 = cycling road).
Game3.Z_OAM_PRIORITY = {
  [0] = 2, 2, 2, 2, 1, 2, 1, 2, 1, 2, 1, 2, 1, 0, 0, 2,
}

function Game3.oamPriorityForZ(z)
  z = math.floor(tonumber(z) or 0)
  if z < 0 then z = 0 elseif z > 15 then z = 15 end
  return Game3.Z_OAM_PRIORITY[z] or 2
end

function Game3.spriteDrawsOverOverlay(z)
  return Game3.oamPriorityForZ(z) < 2
end

-- event_object_movement.c ObjectEventUpdateZCoord. 0xF on either tile
-- skips; map Z 0 does not overwrite previousElevation (draw Z).
function Game3:updateActorZCoord(actor, map, x, y, prevX, prevY)
  map = map or self.map
  if not (actor and map and map.grid) then return end
  local i = self:gridIndex(map, x, y)
  if not i then return end
  local pi = self:gridIndex(map, prevX or x, prevY or y) or i
  local z = Game3.elevationOf(map.grid[i])
  local z2 = Game3.elevationOf(map.grid[pi])
  if z == 15 or z2 == 15 then return end
  actor.currentElevation = z
  -- Mossdeep Gym floor belts are elevation 0 while walkways are 3/4.
  -- Keeping previousElevation from a raised tile while standing on ground
  -- made the sprite draw on the walkway layer and fight the belt below.
  if z == 0 then
    actor.previousElevation = 0
  elseif z ~= 0 then
    actor.previousElevation = z
  end
end

function Game3:updatePlayerZCoord()
  self:updateActorZCoord(self, self.map, self.playerX, self.playerY,
    self.walkFromX, self.walkFromY)
end

function Game3:updateNpcZCoord(npc, map)
  if not npc then return end
  self:updateActorZCoord(npc, map or self.map, npc.x, npc.y,
    npc.fromX, npc.fromY)
  if npc.currentElevation ~= nil then
    npc.elevation = npc.currentElevation
  end
end

function Game3:actorDrawElevation(a)
  if not a or a.kind == "player" then
    if self.previousElevation ~= nil then return self.previousElevation end
    return self.currentElevation or 0
  end
  local o = a.obj
  if not o then return 0 end
  if o.previousElevation ~= nil then return o.previousElevation end
  return o.elevation or 0
end

-- event_object_movement.c IsZCoordMismatchAt. 0 / 0xF on the map means
-- "any height"; object elevation 0 skips the check.
function Game3.zMismatch(z, mapZ)
  z = z or 0
  mapZ = mapZ or 0
  if z == 0 then return false end
  if mapZ == 0 or mapZ == 15 then return false end
  return mapZ ~= z
end

-- metatile_behavior.c MetatileBehavior_IsEast/West/North/SouthBlocked: a
-- cliff edge is a plain walkable metatile that additionally refuses entry
-- (or exit) from specific facings, independent of elevation. Without this
-- the player could walk straight through a cliff face from below since
-- collision and elevation on those tiles are otherwise unremarkable.
function Game3.behaviorBlocksEast(b)
  return b == Game3.MB_IMPASSABLE_EAST or b == Game3.MB_IMPASSABLE_NORTHEAST
    or b == Game3.MB_IMPASSABLE_SOUTHEAST or b == Game3.MB_IMPASSABLE_WEST_AND_EAST
end
function Game3.behaviorBlocksWest(b)
  return b == Game3.MB_IMPASSABLE_WEST or b == Game3.MB_IMPASSABLE_NORTHWEST
    or b == Game3.MB_IMPASSABLE_SOUTHWEST or b == Game3.MB_IMPASSABLE_WEST_AND_EAST
end
function Game3.behaviorBlocksNorth(b)
  return b == Game3.MB_IMPASSABLE_NORTH or b == Game3.MB_IMPASSABLE_NORTHEAST
    or b == Game3.MB_IMPASSABLE_NORTHWEST or b == Game3.MB_IMPASSABLE_SOUTH_AND_NORTH
end
function Game3.behaviorBlocksSouth(b)
  return b == Game3.MB_IMPASSABLE_SOUTH or b == Game3.MB_IMPASSABLE_SOUTHEAST
    or b == Game3.MB_IMPASSABLE_SOUTHWEST or b == Game3.MB_IMPASSABLE_SOUTH_AND_NORTH
end

-- event_object_movement.c IsMetatileDirectionallyImpassable: either the
-- tile being LEFT can refuse to be exited that way, or the tile being
-- ENTERED can refuse to be entered from that facing. dir is a Game3.DIR_*
-- value (SOUTH/NORTH/WEST/EAST); diagonals never block (pokeruby only
-- calls this for the four cardinal directions).
function Game3.directionallyImpassable(srcBehavior, dstBehavior, dir)
  if dir == Game3.DIR_SOUTH then
    return Game3.behaviorBlocksSouth(srcBehavior) or Game3.behaviorBlocksNorth(dstBehavior)
  elseif dir == Game3.DIR_NORTH then
    return Game3.behaviorBlocksNorth(srcBehavior) or Game3.behaviorBlocksSouth(dstBehavior)
  elseif dir == Game3.DIR_WEST then
    return Game3.behaviorBlocksWest(srcBehavior) or Game3.behaviorBlocksEast(dstBehavior)
  elseif dir == Game3.DIR_EAST then
    return Game3.behaviorBlocksEast(srcBehavior) or Game3.behaviorBlocksWest(dstBehavior)
  end
  return false
end

function Game3.walkable(map, x, y)
  if type(map) ~= "table" or type(map.grid) ~= "table" then return false end
  x = math.floor(tonumber(x) or 0)
  y = math.floor(tonumber(y) or 0)
  local w, h = map.width or 0, map.height or 0
  if x < 0 or y < 0 or x >= w or y >= h then return false end
  local cell = map.grid[y * w + x + 1]
  if cell == nil then return false end
  return Game3.collisionOf(cell) == 0
end

function Game3.warpAt(map, x, y)
  if type(map) ~= "table" or type(map.warps) ~= "table" then return nil end
  for i = 1, #map.warps do
    local w = map.warps[i]
    if w and w.x == x and w.y == y then return w end
  end
  return nil
end

function Game3.objectAt(map, x, y)
  if type(map) ~= "table" or type(map.objects) ~= "table" then return nil end
  for i = 1, #map.objects do
    local o = map.objects[i]
    if o and o.x == x and o.y == y then return o end
  end
  return nil
end

function Game3.bgAt(map, x, y)
  if type(map) ~= "table" or type(map.bgEvents) ~= "table" then return nil end
  for i = 1, #map.bgEvents do
    local e = map.bgEvents[i]
    if e and e.x == x and e.y == y then return e end
  end
end

function Game3.hiddenFlag(hiddenId)
  return Game3.FLAG_HIDDEN_ITEMS_START + (hiddenId or 0)
end

local BG_FACE = { [1] = "north", [2] = "south", [3] = "east", [4] = "west" }

function Game3.bgFacingOk(kind, facing)
  if not kind or kind == 0 then return true end
  local need = BG_FACE[kind]
  if not need then return true end
  return need == facing
end

-- Petalburg gym sliding doors sit on warp events and collision, but
-- field_control_avatar.c only bump-warps MB_ANIMATED_DOOR. The lock /
-- "go through?" scripts are bg signs: A-press, never walk-in.
function Game3.signBgAt(map, x, y)
  local ev = Game3.bgAt(map, x, y)
  if not ev then return nil end
  local kind = ev.kind or 0
  if kind == Game3.BG_HIDDEN_ITEM or kind == 5 or kind == 6
      or kind == Game3.BG_SECRET_BASE then
    return nil
  end
  if kind > 4 then return nil end
  return ev
end

function Game3.new()
  local self = setmetatable({
    speedOverride = nil,
    capturePath = nil,
    world = nil,
    status = nil,
    phase = "boot", -- boot | play | roster | battle
    input = Input,
    data = { pokemon = {}, constants = {}, header = {}, maps = {}, tilesets = {}, sprites = {}, encounters = {}, moves = {}, trainers = {}, items = {}, title = {} },
    scroll = 1,
    playerX = 0,
    playerY = 0,
    camX = 0,
    camY = 0,
    walkCooldown = 0,
    walkFromX = 0,
    walkFromY = 0,
    facing = "south",
    map = nil,
    ignoreWarp = false,
    atlasCache = {},
    spriteCache = {},
    npcByMap = {},
    tileBatches = {},
    tileWindows = {},
    borderFillCache = nil,
    gbaCanvas = nil,
    quads = {},
    balls = 0,
    bag = {},
    pcItems = {},
    pcMail = {},
    money = Game3.START_MONEY,
    party = {},
    pc = {},
    caught = {},
    seen = {},
    gender = Game3.GENDER_MALE,
    flags = {},
    saveExists = false,
    playSeconds = 0,
    customName = nil,
    options = { textSpeed = 2, battleScene = true, battleStyle = "shift",
      stereo = false, windowFrame = 0, zoom = 0, tilt = 0,
      speedOverworld = 1, speedBattle = 1, speedMenu = 1 },
    viewW = Game3.SCREEN_W,
    viewH = Game3.SCREEN_H,
    -- Dev force-shiny: respect --developer / POKEPORT_DEV (class default may
    -- already be set; instance field makes toggle + makeMon lookups local).
    forceShiny = (os.getenv("POKEPORT_DEV") == "1" or _G.POKEPORT_DEV_MODE == true),
  }, Game3)
  self:applyGender(Game3.GENDER_MALE)
  self:ensureTrainerId()
  self:resetBoot()
  return self
end

function Game3:lookupMap(group, index)
  local pack = self.data.maps
  if not pack or not pack.maps then return nil end
  return pack.maps[Game3.mapId(group, index)]
end

function Game3:lookupMapById(id)
  local pack = self.data.maps
  if not pack or not pack.maps or not id then return nil end
  return pack.maps[id]
end

-- pokeruby showobjectat LOCALID_PLAYER, MAP_DEWFORD_TOWN (and the
-- Route 104 / 109 returns) puts the sprite on Mr. Briney's boat.
function Game3:objectGfxXY(map, gfxId)
  local objs = map and map.objects or {}
  for i = 1, #objs do
    local o = objs[i]
    if o and o.graphicsId == gfxId then
      return o.x or 0, o.y or 0
    end
  end
end

function Game3.isTruckMap(map)
  if type(map) ~= "table" then return false end
  if map.connections and #map.connections > 0 then return false end
  local w, h = map.width or 0, map.height or 0
  if w < 4 or w > 8 or h < 4 or h > 8 then return false end
  local objs = map.objects or {}
  if #objs < 2 or #objs > 5 then return false end
  local hits = 0
  for i = 1, #objs do
    local o = objs[i]
    if o and o.x == 0 and o.y == 0 then hits = hits + 1 end
    if o and o.x == 0 and o.y == 3 then hits = hits + 1 end
    if o and o.x == 2 and o.y == 3 then hits = hits + 1 end
  end
  return hits >= 2
end

function Game3:findTruckMap()
  local maps = self.data.maps and self.data.maps.maps
  if type(maps) ~= "table" then return nil end
  for _, map in pairs(maps) do
    if Game3.isTruckMap(map) then return map end
  end
end

function Game3:birchLabMap()
  local preferred = self:lookupMap(Game3.LAB_GROUP, Game3.LAB_NUM)
  if preferred then return preferred end
  local maps = self.data.maps and self.data.maps.maps
  if type(maps) ~= "table" then return nil end
  for _, map in pairs(maps) do
    local objects = map and map.objects or {}
    for i = 1, #objects do
      local o = objects[i]
      if o and (o.graphicsId or 0) == Game3.GFX_BIRCH
          and o.x == Game3.LAB_X and o.y == Game3.LAB_Y - 1 then
        return map
      end
    end
  end
end

function Game3.clockEvent(map)
  local evs = map and map.bgEvents or {}
  for i = 1, #evs do
    local t = evs[i] and evs[i].text
    if type(t) == "string" and t:find("clock is stopped", 1, true) then
      return evs[i]
    end
  end
end

function Game3.isBedroomMap(map)
  return Game3.clockEvent(map) ~= nil
end

-- Downstairs Mom heals; upstairs Mom is a cinema slot with a NULL script
-- (FLAG_HIDE_MOM_UPSTAIRS). Never treat a bedroom as a heal stub map.
function Game3.isMomHealMap(map)
  if not map then return false end
  if map.momHeal then return true end
  if Game3.isBedroomMap(map) then return false end
  local g, n = tonumber(map.group), tonumber(map.index)
  if g == nil then
    local gs, ns = tostring(map.id or ""):match("^g(%d+)_(%d+)$")
    g, n = tonumber(gs), tonumber(ns)
  end
  if g ~= Game3.MAP_LITTLEROOT_INDOOR_GROUP then return false end
  return n == Game3.MAP_BRENDANS_HOUSE_1F_NUM
    or n == Game3.MAP_MAYS_HOUSE_1F_NUM
end

-- Centers and the League share MUS_POKE_CENTER. Every real nurse has a
-- ROM script; this only gates the no-script heal stub.
Game3.MUS_POKE_CENTER = 400
function Game3.isNurseHealMap(map)
  if not map then return false end
  if map.nurseHeal then return true end
  if tonumber(map.music) == Game3.MUS_POKE_CENTER then return true end
  local name = tostring(map.name or "")
  if name:find("POKeMON CENTER", 1, true) then return true end
  if name:find("PokemonCenter", 1, true) then return true end
  if name:find("PokemonLeague", 1, true) then return true end
  return false
end

function Game3.isBrendanBedroom(map)
  local ev = Game3.clockEvent(map)
  return ev ~= nil and (ev.x or 0) >= 4
end

-- Brendan clock BG is at x>=4; May's at x<4 (pokeruby map.json).
-- Only the gender-correct bedroom may own intro / mover flags.
function Game3:isPlayerBedroomMap(map)
  map = map or self.map
  if not Game3.isBedroomMap(map) then return false end
  return Game3.isBrendanBedroom(map) == (not self:isFemale())
end

function Game3:applyWallClockIntroFlags()
  self.flags = self.flags or {}
  self.scriptVars = self.scriptVars or {}
  self.flags[Game3.FLAG_SET_WALL_CLOCK] = true
  self.flags[Game3.FLAG_HIDE_MACHOKE_MOVER_1] = true
  self.flags[Game3.FLAG_HIDE_MACHOKE_MOVER_2] = true
  self.scriptVars[Game3.VAR_LITTLEROOT_INTRO_STATE] = 6
  -- Shared mover flags hide Machoke in both houses after the player clock.
  if self.map then
    self:resetNpcs(self.map)
  end
end

function Game3.coordAt(map, x, y)
  local events = map and map.coordEvents
  if type(events) ~= "table" then return nil end
  for i = 1, #events do
    local ev = events[i]
    if ev and ev.x == x and ev.y == y then return ev end
  end
end

function Game3:bedroomMap(wantBrendan)
  local maps = self.data.maps and self.data.maps.maps
  if type(maps) ~= "table" then return nil end
  local fallback
  for _, map in pairs(maps) do
    if Game3.isBedroomMap(map) then
      fallback = fallback or map
      if Game3.isBrendanBedroom(map) == wantBrendan then return map end
    end
  end
  return fallback
end

function Game3:playerBedroomMap()
  return self:bedroomMap(not self:isFemale())
end

function Game3:setHealLocation(id)
  id = tonumber(id) or 0
  local loc = Game3.HEAL_LOCATIONS[id]
  if not loc then return false end
  local dest = self:lookupMap(loc.group, loc.num)
  if not dest then
    if id == Game3.HEAL_LITTLEROOT_BRENDAN_2F then
      dest = self:bedroomMap(true)
    elseif id == Game3.HEAL_LITTLEROOT_MAY_2F then
      dest = self:bedroomMap(false)
    end
  end
  if not dest then return false end
  local x, y = loc.x, loc.y
  if id == Game3.HEAL_LITTLEROOT_BRENDAN_2F
      or id == Game3.HEAL_LITTLEROOT_MAY_2F then
    if not Game3.walkable(dest, x, y) then
      local spawn = dest.spawn or {}
      x, y = spawn.x or x, spawn.y or y
    end
  end
  self.lastHeal = {
    mapId = dest.id,
    x = x,
    y = y,
  }
  return true
end

function Game3:setBedroomHeal()
  return self:setHealLocation(self:isFemale()
    and Game3.HEAL_LITTLEROOT_MAY_2F or Game3.HEAL_LITTLEROOT_BRENDAN_2F)
end

function Game3:lastHealIsBedroom()
  local heal = self.lastHeal
  if not (heal and heal.mapId) then return false end
  local id = heal.mapId
  if id == "g1_1" or id == "g1_3" then return true end
  local m = self:lookupMapById(id)
  return m ~= nil and Game3.isBedroomMap(m)
end

function Game3:isLittlerootCatchment(map)
  map = map or self.map
  if not map then return false end
  if Game3.isBedroomMap(map) then return true end
  local g, n = tonumber(map.group), tonumber(map.index)
  if g == nil then
    local gs, ns = tostring(map.id or ""):match("^g(%d+)_(%d+)$")
    g, n = tonumber(gs), tonumber(ns)
  end
  if g == Game3.MAP_LITTLEROOT_INDOOR_GROUP then return true end
  return g == 0 and n == 9
end

function Game3:furthestVisitedHealId()
  local flags = self.flags
  if type(flags) ~= "table" then return nil end
  local rows = Game3.HEAL_FROM_VISITS
  local id
  local i = 1
  while i <= #rows do
    local row = rows[i]
    if flags[row.flag] then id = row.id end
    i = i + 1
  end
  return id
end

-- Bedroom lastHeal after a Center town was visited is the truck id-1/2
-- bug, not a real setrespawn. Hall of Fame really does write the bedroom.
function Game3:repairStaleBedroomHeal()
  if self.flags and self.flags[Game3.FLAG_SYS_GAME_CLEAR] then
    return false
  end
  if not self:lastHealIsBedroom() then return false end
  local id = self:furthestVisitedHealId()
  if not id then return false end
  return self:setHealLocation(id)
end

-- Overworld_SetWarpDestination. Unlike setdynamicwarp, which the engine
-- already stored, setwarp was parsed and then dropped. Its two callers are the
-- Lilycove link contest lobby and the Safari Zone's out-of-steps exit, and the
-- latter is reachable in a normal run.
function Game3:setWarpDestination(group, num, warpId, x, y)
  self.warpDestination = {
    mapGroup = tonumber(group) or 0,
    mapNum = tonumber(num) or 0,
    warpId = tonumber(warpId) or Game3.WARP_ID_NONE,
    x = tonumber(x) or 0,
    y = tonumber(y) or 0,
  }
  return true
end

function Game3:takeWarpDestination()
  local w = self.warpDestination
  self.warpDestination = nil
  return w
end

-- easy_chat_2.c sub_80EB7C4. Not an editor: it reads one of four stored word
-- boards, turns it into a string and shows it as a field message. VAR_0x8004
-- picks the board; the row and column shape differs per board because they are
-- laid out differently on the wall.
Game3.EC_BOARD_COUNT = 4
Game3.EC_BOARD_SHAPE = {
  [0] = { 2, 2 },
  [1] = { 3, 2 },
  [2] = { 3, 2 },
  [3] = { 3, 2 },
}

function Game3:easyChatBoard(index)
  index = tonumber(index) or 0
  if index < 0 or index >= Game3.EC_BOARD_COUNT then return nil end
  self.easyChatBoards = self.easyChatBoards or {}
  local board = self.easyChatBoards[index]
  if type(board) ~= "table" then
    board = {}
    self.easyChatBoards[index] = board
  end
  return board
end

-- ConvertEasyChatWordsToString lays the words out in rows; a word that has
-- never been set reads as nothing rather than as a blank slot.
function Game3:easyChatBoardText(index)
  local board = self:easyChatBoard(index)
  if not board then return nil end
  local shape = Game3.EC_BOARD_SHAPE[tonumber(index) or 0] or { 2, 2 }
  local cols, rows = shape[1], shape[2]
  local lines = {}
  for r = 0, rows - 1 do
    local parts = {}
    for c = 0, cols - 1 do
      local word = Game3.ecWordText(board[r * cols + c + 1] or 0)
      if word ~= "" then parts[#parts + 1] = word end
    end
    if #parts > 0 then lines[#lines + 1] = table.concat(parts, " ") end
  end
  return table.concat(lines, "\r\n")
end

-- The boards are written by other players over the link cable, so in a
-- single-player run they are empty and the cart shows an empty message. That
-- is reproduced rather than papered over with invented text.
function Game3:showEasyChatBoard()
  local index = (self.scriptVars and self.scriptVars[0x8004]) or 0
  if (tonumber(index) or 0) >= Game3.EC_BOARD_COUNT then return 0 end
  local text = self:easyChatBoardText(index)
  -- ShowFieldAutoScrollMessage puts the board on screen and the script carries
  -- on, so this queues the line the way every other printing special does.
  if text and text ~= "" then self:sayScript(text) end
  return 1
end

function Game3:setDynamicWarp(group, num, warpId, x, y)
  self.dynamicWarp = {
    mapGroup = tonumber(group) or 0,
    mapNum = tonumber(num) or 0,
    warpId = tonumber(warpId) or Game3.WARP_ID_NONE,
    x = tonumber(x) or 0,
    y = tonumber(y) or 0,
  }
  return true
end

-- field_control_avatar.c sub_8068C30: if the landing warp's dest is
-- MAP_DYNAMIC, saved_warp2_set the current map / source warp index /
-- player xy so stepping off an elevator can return. warpId 0 is a real
-- dest (Lilycove 1F → elevator warp 0); skip only NONE / DYNAMIC.
function Game3:maybeSetDynamicWarpFromDest(dest, destWarpId, srcWarp)
  destWarpId = tonumber(destWarpId) or 0
  if destWarpId == Game3.WARP_ID_NONE
      or destWarpId == Game3.WARP_ID_DYNAMIC then
    return
  end
  local landing = type(dest) == "table" and dest.warps
      and dest.warps[destWarpId + 1]
  if not landing then return end
  if (landing.mapGroup or 0) ~= Game3.MAP_DYNAMIC_GROUP then return end
  if (landing.mapNum or 0) ~= Game3.MAP_DYNAMIC_NUM then return end
  local m = self.map
  if type(m) ~= "table" then return end
  local srcId = 0
  if srcWarp and m.warps then
    for i = 1, #m.warps do
      if m.warps[i] == srcWarp then
        srcId = i - 1
        break
      end
    end
  end
  local group, num = tonumber(m.group), tonumber(m.index)
  if group == nil or num == nil then
    local gs, ns = tostring(m.id or ""):match("^g(%d+)_(%d+)$")
    group, num = tonumber(gs) or 0, tonumber(ns) or 0
  end
  self:setDynamicWarp(group, num, srcId, self.playerX, self.playerY)
end

-- event_data.c ClearTempFieldEventData: first 4 flag bytes (0x0–0x1F)
-- and first 0x20 var bytes (VAR_TEMP_0..F). FLAG_TEMP_20 (Victory Road
-- rock) is not temp. Indoor re-entry must drop FLAG_TEMP_2 or the
-- Lilycove elevator skips SetFloor. Sootopolis ice bits live in
-- VAR_TEMP_1..A and reset on warp the same way. Also FlagClear the
-- White/Black Flute rate flags, Strength, and CTRL_OBJ_DELETE.
function Game3:clearTempFlags()
  local flags = self.flags
  if type(flags) == "table" then
    for i = 0, Game3.FLAG_TEMP_1F do
      flags[i] = nil
    end
    flags[Game3.FLAG_SYS_ENC_UP_ITEM] = nil
    flags[Game3.FLAG_SYS_ENC_DOWN_ITEM] = nil
    flags[Game3.FLAG_SYS_USE_STRENGTH] = nil
    flags[Game3.FLAG_SYS_CTRL_OBJ_DELETE] = nil
  end
  local vars = self.scriptVars
  if type(vars) == "table" then
    for i = 0, 15 do
      vars[Game3.VARS_START + i] = nil
    end
  end
end

-- field_specials.c SetDepartmentStoreFloorVar: dynamicWarp.mapNum only.
-- 1F is 0 (Lua 0 is a valid floor). Rooftop is 15, not 5.
function Game3:setDepartmentStoreFloorVar()
  local d = self.dynamicWarp
  local num = d and tonumber(d.mapNum) or 0
  local floor = Game3.DEPT_STORE_FLOOR[num]
  if floor == nil then floor = 0 end
  self:setScriptVar(Game3.VAR_DEPT_STORE_FLOOR, floor)
end

function Game3:displayCurrentElevatorFloor()
  local floor = self:varGet(0x8005)
  local name = Game3.ELEVATOR_FLOOR_NAMES[floor]
  if not name then name = "1F" end
  if self.sayScript then
    self:sayScript("Now on: " .. name)
  end
end

-- ShakeScreenInElevator CreateTask then ScriptContext_Enable after 23
-- pans. Scripts follow with waitstate.
function Game3:shakeScreenInElevator()
  self:startCameraShake(0, 1, Game3.ELEVATOR_SHAKE_PERIOD,
    Game3.ELEVATOR_SHAKE_HITS, Game3.SE_ELEVATOR, Game3.SE_DING_DONG)
end

-- WaitWeather / sub_80818A4 / sub_80818FC / sub_8081924 / ShakeCamera.
-- Each CreateTask then ScriptContext_Enable on the next vblank or when
-- the effect finishes. Scripts follow with waitstate.
function Game3:waitWeather()
  self.waitWeatherLeft = Game3.WAIT_WEATHER_FRAMES
  self:beginScriptWait()
end

function Game3:orbOpenFrames()
  return Game3.ORB_OPEN_SETUP_FRAMES
    + Game3.flashAnimFrames(Game3.ORB_OPEN_FROM_R, Game3.ORB_OPEN_DEST_R,
      Game3.ORB_OPEN_DELTA)
end

function Game3:orbCutscene()
  local result = self:varGet(Gen3Script.VAR_RESULT)
  local pal, cx = 0, 104
  if result == 1 then
    pal, cx = 1, 104
  elseif result == 2 then
    pal, cx = 0, 120
  elseif result ~= 0 then
    pal, cx = 1, 120
  end
  self.orb = {
    stage = "open",
    pal = pal,
    cx = cx,
    cy = 80,
    r = Game3.ORB_OPEN_FROM_R,
    dest = Game3.ORB_OPEN_DEST_R,
    delta = Game3.ORB_OPEN_DELTA,
    phase = 0,
    left = self:orbOpenFrames(),
  }
  self:beginScriptWait()
end

function Game3:advanceOrbCutscene()
  local o = self.orb
  if not o then return end
  o.stage = "close"
  o.left = Game3.ORB_CLOSE_FRAMES
  o.r = Game3.ORB_OPEN_DEST_R
  self:beginScriptWait()
end

function Game3:startCameraShake(x, y, period, hits, se, dingSe)
  period = period or Game3.CAMERA_SHAKE_PERIOD
  hits = hits or Game3.CAMERA_SHAKE_HITS
  self.shake = {
    x = x or 0, y = y or 0, t = 0, hits = 0, sign = 1,
    period = period, maxHits = hits,
    left = period * hits,
    dingSe = dingSe,
  }
  self.cameraPanX, self.cameraPanY = 0, 0
  if se then self:playSe(se) end
  self:beginScriptWait()
end

function Game3:shakeCamera()
  self:startCameraShake(self:varGet(0x8004), self:varGet(0x8005),
    Game3.CAMERA_SHAKE_PERIOD, Game3.CAMERA_SHAKE_HITS, Game3.SE_M_STRENGTH)
end

function Game3:fadeOutMapMusicWait()
  local playing = Mp2kAudio.isPlaying()
  local frames = playing and Game3.OVERWORLD_FADE_MUSIC_FRAMES
    or Game3.WAIT_WEATHER_FRAMES
  if playing then self:fadeOutMapMusic(Game3.OVERWORLD_FADE_MUSIC_FRAMES) end
  self.fadeMusicLeft = frames
  self:beginScriptWait()
end

-- trainer_see.c EndTrainerApproach: replace the approach task, next
-- vblank DestroyTask + ScriptContext_Enable. Scripts follow with waitstate.
function Game3:endTrainerApproach()
  self.endApproachLeft = Game3.END_APPROACH_FRAMES
  self:beginScriptWait()
end

-- scrcmd.c gFieldEffectArguments[argNum] = (s16)VarGet(value).
function Game3:setFieldEffectArgument(index, value)
  self.fieldEffectArgs = self.fieldEffectArgs or {}
  self.fieldEffectArgs[tonumber(index) or 0] = tonumber(value) or 0
end

function Game3:fieldEffectArg(index)
  local args = self.fieldEffectArgs
  if not args then return 0 end
  return args[tonumber(index) or 0] or 0
end

-- PokeballGlowEffect_0 is 25 frames between balls (first is immediate),
-- then 184 frames of stages 1-6.
function Game3:hofRecordFrames()
  local n = #(self.party or {})
  if n < 1 then n = 1 end
  return Game3.HOF_RECORD_BALL_GAP * (n - 1) + 1 + Game3.HOF_RECORD_GLOW_FRAMES
end

function Game3.pokeballGlowPose(elapsed, n, ox, oy)
  elapsed = math.floor(tonumber(elapsed) or 0)
  n = tonumber(n) or 1
  if n < 1 then n = 1 elseif n > 6 then n = 6 end
  ox = ox or Game3.HOF_BALL_X
  oy = oy or Game3.HOF_BALL_Y
  local spawned = 0
  if elapsed >= 0 then
    spawned = math.floor(elapsed / Game3.HOF_RECORD_BALL_GAP) + 1
    if spawned > n then spawned = n end
  end
  local lastT = Game3.HOF_RECORD_BALL_GAP * (n - 1)
  local glowT = elapsed - lastT
  local balls = {}
  if glowT < Game3.HOF_BALL_LIVE then
    for i = 1, spawned do
      local d = Game3.POKEBALL_GLOW_DELTA[i]
      balls[i] = { ox + d[1], oy + d[2] }
    end
  end
  local monitorT = glowT - Game3.HOF_STAGE1_FRAMES
  local inMonitor = monitorT >= 0 and monitorT <= Game3.HOF_MONITOR_LIFE
  local blink = inMonitor
    and (math.floor(monitorT / Game3.HOF_MONITOR_BLINK) % 2 == 0)
  local pcFrame = 0
  if inMonitor then
    pcFrame = math.floor(monitorT / Game3.HOF_MONITOR_BLINK) % 2
  end
  local phase, stagger = Game3.glowPulsePhase(glowT)
  local pulse = 0
  if phase ~= nil then pulse = Game3.glowPulseFactor(phase) end
  return {
    balls = balls,
    spawned = spawned,
    monitors = blink,
    pcMonitor = inMonitor,
    pcFrame = pcFrame,
    glowT = glowT,
    pulse = pulse,
    pulsePhase = phase,
    pulseStagger = stagger and true or false,
  }
end

function Game3:pokecenterHealFrames()
  local n = #(self.party or {})
  if n < 1 then n = 1 end
  return Game3.FLDEFF_POKECENTER_BALL_GAP * (n - 1) + 1
    + Game3.FLDEFF_POKECENTER_GLOW
end

function Game3:fieldEffectDuration(id)
  id = tonumber(id) or 0
  if id == Game3.FLDEFF_SPARKLE then return Game3.FLDEFF_SPARKLE_FRAMES end
  if id == Game3.FLDEFF_NPCFLY_OUT then return Game3.FLDEFF_NPCFLY_FRAMES end
  if id == Game3.FLDEFF_HALL_OF_FAME_RECORD then
    return self:hofRecordFrames()
  end
  if id == Game3.FLDEFF_SECRET_BASE_PC_TURN_ON then
    return Game3.FLDEFF_SECRET_BASE_PC_FRAMES
  end
  if id == Game3.FLDEFF_POKECENTER_HEAL then
    return self:pokecenterHealFrames()
  end
  -- fldeff_secretpower.c: the pose, then a 40-frame entrance sprite.
  if Game3.isSecretPowerFieldEffect(id) then
    return Game3.FLDEFF_FIELD_MOVE_POSE_FRAMES
      + Game3.FLDEFF_SECRET_POWER_ENTRANCE_FRAMES
  end
  -- Cut / Rock Smash / Strength: oei_task_add pose + show-mon wait.
  if Game3.fieldEffectFollowedByWaitstate(id) then
    return Game3.FLDEFF_FIELD_MOVE_POSE_FRAMES
  end
  return Game3.FLDEFF_DEFAULT_FRAMES
end

function Game3:fieldEffectActive(id)
  id = tonumber(id) or 0
  local list = self.fieldEffects
  if not list then return false end
  for i = 1, #list do
    if list[i].id == id then return true end
  end
  return false
end

-- FieldEffectStart. Does not wait (ScrCmd_dofieldeffect returns FALSE).
function Game3:doFieldEffect(id)
  id = tonumber(id) or 0
  local left = self:fieldEffectDuration(id)
  local fx = {
    id = id,
    left = left,
    dur = left,
    x = self:fieldEffectArg(0),
    y = self:fieldEffectArg(1),
  }
  self.fieldEffects = self.fieldEffects or {}
  self.fieldEffects[#self.fieldEffects + 1] = fx
  if id == Game3.FLDEFF_NPCFLY_OUT then
    self:playSe(Game3.SE_M_FLY)
  end
  if id == Game3.FLDEFF_SECRET_BASE_PC_TURN_ON then
    local gx, gy = self:mapGridInFront()
    fx.gx, fx.gy, fx.t = gx, gy, 0
    self:beginScriptWait()
  end
  if id == Game3.FLDEFF_POKECENTER_HEAL then
    self:playFanfare(Game3.MUS_HEAL)
  end
  -- rom6.c FldEff_RockSmash: oei_task_add, then SE + Enable. Cut/Strength
  -- use the same waitstate. releaseWait lets stepFieldEffects Enable.
  if Game3.fieldEffectFollowedByWaitstate(id) then
    local fxX, fxY = self:facingCell()
    fx.gx, fx.gy = fxX, fxY
    fx.fieldMove = true
    if id == Game3.FLDEFF_USE_ROCK_SMASH then
      self:incrementGameStat(Game3.GAME_STAT_USED_ROCK_SMASH)
      self:playSe(Game3.SE_M_ROCK_THROW)
    elseif id == Game3.FLDEFF_USE_CUT_ON_TREE then
      self:playSe(Game3.SE_M_CUT)
    elseif id == Game3.FLDEFF_USE_STRENGTH then
      self:playSe(Game3.SE_M_STRENGTH)
    elseif Game3.isSecretPowerFieldEffect(id) then
      -- fldeff_secretpower.c: each entrance sprite plays its own SE on the
      -- first callback, then opens the tile partway through 40 frames --
      -- the caves and the shrub at 20, the tree only at the very end.
      -- The entrance sprite only starts after oei_task_add's pose, so its
      -- own 40-frame count is offset by the pose length.
      local pose = Game3.FLDEFF_FIELD_MOVE_POSE_FRAMES
      fx.gx, fx.gy = self:mapGridInFront()
      fx.t = 0
      if id == Game3.FLDEFF_USE_SECRET_POWER_CAVE then
        self:playSe(Game3.SE_M_ROCK_THROW)
        fx.openAt = pose + 20
      elseif id == Game3.FLDEFF_USE_SECRET_POWER_TREE then
        self:playSe(Game3.SE_M_SCRATCH)
        fx.openAt = pose + 40
      else
        self:playSe(Game3.SE_M_POISON_POWDER)
        fx.openAt = pose + 20
      end
    end
    fx.releaseWait = true
    self:beginScriptWait()
  end
end

-- field_move_scripts.inc: dofieldeffect then waitstate (not waitfieldeffect).
function Game3.fieldEffectFollowedByWaitstate(id)
  id = tonumber(id) or 0
  return id == Game3.FLDEFF_USE_ROCK_SMASH
    or id == Game3.FLDEFF_USE_CUT_ON_TREE
    or id == Game3.FLDEFF_USE_STRENGTH
    or Game3.isSecretPowerFieldEffect(id)
end

function Game3.isSecretPowerFieldEffect(id)
  id = tonumber(id) or 0
  return id == Game3.FLDEFF_USE_SECRET_POWER_CAVE
    or id == Game3.FLDEFF_USE_SECRET_POWER_TREE
    or id == Game3.FLDEFF_USE_SECRET_POWER_SHRUB
end

-- SetupNativeScript until !FieldEffectActiveListContains. A missing
-- effect is already inactive, so the script continues (no hang).
function Game3:waitFieldEffect(id)
  id = tonumber(id) or 0
  if self:fieldEffectActive(id) then
    self._waitFieldEffect = id
    self:beginScriptWait()
  end
end

-- The entrance sprite counts to 40 and swaps the tile to its open half on
-- the way past fx.openAt, exactly once.
function Game3:tickSecretPowerEntrance(fx, frames)
  if not fx or fx.opened then return end
  local t = (fx.t or 0) + (frames or 1)
  fx.t = t
  if t >= (fx.openAt or 20) then
    fx.opened = true
    self:setOpenedSecretBaseMetatile(fx.gx, fx.gy)
  end
end

function Game3:tickSecretBasePcOn(fx, frames)
  if not fx then return end
  local n = 1
  while n <= frames do
    local t = fx.t or 0
    if t == 4 or t == 12 or t == 20 then
      self:mapGridSetMetatileId(fx.gx, fx.gy,
        Game3.MT_SECRET_BASE_PC_ON + Game3.MAPGRID_COLLISION_MASK)
    elseif t == 8 or t == 16 then
      self:mapGridSetMetatileId(fx.gx, fx.gy,
        Game3.MT_SECRET_BASE_PC_OFF + Game3.MAPGRID_COLLISION_MASK)
    end
    fx.t = t + 1
    n = n + 1
  end
end

function Game3:stepFieldEffects(frames)
  local list = self.fieldEffects
  local pcDone = false
  local releasedWait = false
  local secretPowerDone = false
  if list then
    local i = 1
    while i <= #list do
      if list[i].id == Game3.FLDEFF_SECRET_BASE_PC_TURN_ON then
        self:tickSecretBasePcOn(list[i], frames)
      elseif Game3.isSecretPowerFieldEffect(list[i].id) then
        self:tickSecretPowerEntrance(list[i], frames)
      elseif list[i].note or list[i].door or list[i].balloon
          or list[i].glitter then
        self:tickSecretBaseDecorEffect(list[i], frames)
      end
      list[i].left = (list[i].left or 0) - frames
      if list[i].left <= 0 then
        if list[i].id == Game3.FLDEFF_SECRET_BASE_PC_TURN_ON then
          pcDone = true
        end
        if Game3.isSecretPowerFieldEffect(list[i].id) then
          secretPowerDone = true
        end
        if list[i].releaseWait then releasedWait = true end
        table.remove(list, i)
      else
        i = i + 1
      end
    end
    if #list < 1 then self.fieldEffects = nil end
  end
  local waitId = self._waitFieldEffect
  if waitId ~= nil and not self:fieldEffectActive(waitId) then
    self._waitFieldEffect = nil
    self:endCinemaWait()
  end
  if pcDone then self:endCinemaWait() end
  if releasedWait then self:endCinemaWait() end
  -- The waitstate after dofieldeffect is what EventScript_1A2CFA and its
  -- siblings resume behind, so the base is dug once the entrance opens.
  if secretPowerDone then self:finishSecretPowerEntrance() end
end

function Game3:cinemaHolding()
  if self.waitWeatherLeft then return true end
  if self.fadeMusicLeft then return true end
  if self.shake then return true end
  if self.endApproachLeft then return true end
  if self.wateringLeft then return true end
  if self.route128Fade then return true end
  if self._waitFieldEffect ~= nil then return true end
  if self.brailleWait then return true end
  if self.cableClubWarpLeft then return true end
  if self.waitButton then return true end
  if self:fieldEffectActive(Game3.FLDEFF_SECRET_BASE_PC_TURN_ON) then
    return true
  end
  if self.field and self.field.kind == "porthole" then return true end
  local o = self.orb
  return o ~= nil and (o.stage == "open" or o.stage == "close")
end

function Game3:endCinemaWait()
  if not self:cinemaHolding() then self:endScriptWait() end
end

function Game3:stepCinemaWaits(dt)
  local frames = math.floor((dt or 0) * 60 + 0.0001)
  self:stepOwCinema(dt or 0)
  if frames < 1 then return end
  self:stepFieldEffects(frames)
  self:stepLotteryLaptop(frames)
  self:stepBrailleWait(frames)
  self:stepHofCinema(frames)
  self:stepCreditsCinema(frames)
  self:stepPcBlink(frames)
  if self.waitButton then
    if Input:wasPressed("a") or Input:wasPressed("b") then
      self.waitButton = nil
      self._waitButtonDone = true
      self:endCinemaWait()
    end
  end
  if self.cableClubWarpLeft then
    self.cableClubWarpLeft = self.cableClubWarpLeft - frames
    if self.cableClubWarpLeft <= 0 then
      self.cableClubWarpLeft = nil
      self:warpToWarpDestination()
      self:endCinemaWait()
    end
  end
  if self.secretBaseWarpLeft then
    self.secretBaseWarpLeft = self.secretBaseWarpLeft - frames
    if self.secretBaseWarpLeft <= 0 then
      self.secretBaseWarpLeft = nil
      self:secretBaseEntryReposition()
      self:fadeInFromBlack()
      self:endCinemaWait()
    end
  end
  if self.secretBaseResetLeft then
    self.secretBaseResetLeft = self.secretBaseResetLeft - frames
    if self.secretBaseResetLeft <= 0 then
      self.secretBaseResetLeft = nil
      local exit = self.secretBaseExit
      self.secretBaseExit = nil
      local dest = exit and exit.mapId and self:lookupMapById(exit.mapId)
      if dest then self:enterMap(dest, exit.x, exit.y, true) end
      -- Backing out of a deferred move: the base you already owned is
      -- handed straight back, so looking at a new spot never costs you one.
      if self._secretBaseRestore then
        self.secretBase = self._secretBaseRestore
        self._secretBaseRestore = nil
        self:setCurrentSecretBaseVar()
      end
      self:fadeInFromBlack()
    end
  end
  if self.endApproachLeft then
    self.endApproachLeft = self.endApproachLeft - frames
    if self.endApproachLeft <= 0 then
      self.endApproachLeft = nil
      self:endCinemaWait()
    end
  end
  if self.waitWeatherLeft then
    self.waitWeatherLeft = self.waitWeatherLeft - frames
    if self.waitWeatherLeft <= 0 then
      self.waitWeatherLeft = nil
      self:endCinemaWait()
    end
  end
  if self.fadeMusicLeft then
    self.fadeMusicLeft = self.fadeMusicLeft - frames
    if self.fadeMusicLeft <= 0 or not Mp2kAudio.isPlaying() then
      self.fadeMusicLeft = nil
      self:endCinemaWait()
    end
  end
  local shake = self.shake
  if shake then
    shake.t = (shake.t or 0) + frames
    local period = shake.period or Game3.CAMERA_SHAKE_PERIOD
    local maxHits = shake.maxHits or Game3.CAMERA_SHAKE_HITS
    while (shake.t or 0) >= period and (shake.hits or 0) < maxHits do
      shake.t = shake.t - period
      shake.hits = (shake.hits or 0) + 1
      shake.sign = -(shake.sign or 1)
      self.cameraPanX = (shake.x or 0) * shake.sign
      self.cameraPanY = (shake.y or 0) * shake.sign
    end
    shake.left = (shake.left or 0) - frames
    if (shake.hits or 0) >= maxHits or shake.left <= 0 then
      if shake.dingSe then self:playSe(shake.dingSe) end
      self.cameraPanX, self.cameraPanY = 0, 0
      self.shake = nil
      self:endCinemaWait()
    end
  end
  if self.wateringLeft then
    self.wateringLeft = self.wateringLeft - frames
    local step = Game3.WATERING_STEP_FRAMES
    self.walkCooldown = ((self.wateringLeft % step) + 1) / 60
    if self.wateringLeft <= 0 then
      self.wateringLeft = nil
      self.walkCooldown = 0
      self:endCinemaWait()
    end
  end
  local fade = self.route128Fade
  if fade then
    fade.t = (fade.t or 0) + frames
    fade.left = (fade.left or 0) - frames
    if fade.left <= 0 then
      self.route128Fade = nil
      self:endCinemaWait()
    end
  end
  local o = self.orb
  if o and o.stage == "open" then
    local n = frames
    while n > 0 do
      if (o.phase or 0) == 0 then
        o.phase = 1
      else
        o.phase = 0
        o.r = (o.r or 0) + (o.delta or Game3.ORB_OPEN_DELTA)
        if o.r > (o.dest or Game3.ORB_OPEN_DEST_R) then
          o.r = o.dest or Game3.ORB_OPEN_DEST_R
          o.stage = "hold"
          o.left = nil
          self:endCinemaWait()
          break
        end
      end
      n = n - 1
    end
  elseif o and o.stage == "close" then
    o.left = (o.left or 0) - frames
    if o.left <= 0 then
      self.orb = nil
      self:endCinemaWait()
    end
  end
end

