}

-- DoTradeAnim_Cable. Slide is bg2hofs 0xB4 -= 3. Swap is case 72 after A.
Game3.TRADE_SLIDE = 60
Game3.TRADE_SEND_MSG = 80
Game3.TRADE_BYE = 80
Game3.TRADE_GBA_SEND = 40
Game3.TRADE_CABLE_OUT = 80
Game3.TRADE_CROSS = 80
Game3.TRADE_CABLE_IN = 80
Game3.TRADE_GBA_RECV = 40
Game3.TRADE_NEW_MON = 40
Game3.TRADE_SENT_MSG = 0xF0
Game3.TRADE_CARE_WAIT = 60
Game3.TRADE_WAIT_A = 60 + 80 + 80 + 40 + 80 + 80 + 80 + 40 + 40 + 0xF0 + 60
Game3.TRADE_BG2HOFS = 0xB4
Game3.TRADE_MON_X = 0x78
Game3.TRADE_MON_Y = 0x3C
-- TradeEvolutionScene CreateSprite(pre/post, 120, 64, 30).
Game3.TRADE_EVO_X = 120
Game3.TRADE_EVO_Y = 64
Game3.TRADE_BALL_Y = 0x20
Game3.TRADE_GLOW_X = 0x80
Game3.TRADE_CROSS_SENT_X = 0x3C
Game3.TRADE_CROSS_GOT_X = 0xB4
Game3.TRADE_BALL_SIZE = 16
Game3.TRADE_GLOW1_SIZE = 32
Game3.TRADE_GLOW2_W = 16
Game3.TRADE_GLOW2_H = 32
Game3.TRADE_CABLE_END_W = 16
Game3.TRADE_CABLE_END_H = 32
Game3.TRADE_GBA_SCREEN_W = 64
Game3.TRADE_GBA_SCREEN_H = 32

-- The pump has to tick at a steady 60 Hz no matter what the field logic is
-- doing, so it runs before update's boot-phase early return.
function Game3:updateMusic(dt)
  local step = 1 / 60
  self.audioAccum = math.min((self.audioAccum or 0) + (tonumber(dt) or 0), 0.25)
  while self.audioAccum >= step do
    self.audioAccum = self.audioAccum - step
    -- Sprite animation counts VBlanks on hardware, the same interrupt that
    -- drives the sound engine, so the two share this pump and cannot drift.
    self.vblank = ((self.vblank or 0) + 1) % 3600
    Mp2kAudio.update()
  end
end

function Game3:playSong(songId, loop)
  songId = tonumber(songId)
  if not songId then return nil end
  if songId == Game3.MUS_NONE then
    Mp2kAudio.stop()
    return nil
  end
  if songId == Game3.MUS_POSITION_DEPENDENT then return Mp2kAudio.currentSong() end
  return Mp2kAudio.playSong(self.data, songId, loop)
end

function Game3:mapMusic(map)
  map = map or self.map
  return tonumber(map and map.music) or Game3.MUS_NONE
end

-- Restarting the same song on every warp would retrigger the theme when
-- you step between two maps that share one, so this is a no-op then.
function Game3:playMapMusic(map)
  local song = self:mapMusic(map)
  if song == Game3.MUS_POSITION_DEPENDENT then return end
  if song ~= Game3.MUS_NONE and Mp2kAudio.currentSong() == song then return end
  self.savedBgm = nil
  self:playSong(song, true)
end

function Game3:fadeOutMapMusic(frames)
  Mp2kAudio.fadeOut(tonumber(frames) or Game3.MAP_MUSIC_FADE_FRAMES)
end

-- savebgm remembers a song so a later fadedefaultbgm can put it back.
function Game3:saveBgm(songId)
  self.savedBgm = tonumber(songId) or Mp2kAudio.currentSong()
end

-- Battle themes come from the registry's named ids rather than the map, and
-- deliberately do not touch savedBgm: the map theme is restored from the
-- header when the battle ends.
-- Song ids: pokeruby include/constants/songs.h + GetMUS_ForBattle
-- (pokemon_3.c).
Game3.MUS_VS_WILD = 457
Game3.MUS_VS_AQUA_MAGMA = 458
Game3.MUS_VS_TRAINER = 459
Game3.MUS_VS_GYM_LEADER = 460
Game3.MUS_VS_CHAMPION = 461
Game3.MUS_VS_REGI = 462
Game3.MUS_VS_KYOGRE_GROUDON = 463
Game3.MUS_VS_RIVAL = 464
Game3.MUS_VS_ELITE_FOUR = 465
Game3.MUS_VS_AQUA_MAGMA_LEADER = 466

Game3.BATTLE_SONGS = {
  wild = "vsWild",
  aquaMagma = "vsAquaMagma",
  trainer = "vsTrainer",
  gym = "vsGymLeader",
  champion = "vsChampion",
  regi = "vsRegi",
  kyogreGroudon = "vsKyogreGroudon",
  rival = "vsRival",
  eliteFour = "vsEliteFour",
  aquaMagmaLeader = "vsAquaMagmaLeader",
}

Game3.BATTLE_SONG_IDS = {
  wild = Game3.MUS_VS_WILD,
  aquaMagma = Game3.MUS_VS_AQUA_MAGMA,
  trainer = Game3.MUS_VS_TRAINER,
  gym = Game3.MUS_VS_GYM_LEADER,
  champion = Game3.MUS_VS_CHAMPION,
  regi = Game3.MUS_VS_REGI,
  kyogreGroudon = Game3.MUS_VS_KYOGRE_GROUDON,
  rival = Game3.MUS_VS_RIVAL,
  eliteFour = Game3.MUS_VS_ELITE_FOUR,
  aquaMagmaLeader = Game3.MUS_VS_AQUA_MAGMA_LEADER,
}

function Game3:namedSong(name)
  local audio = self.data and self.data.audio
  local named = audio and audio.named
  local id = named and named[name]
  if id then return id end
  -- Older extracts only shipped vsWild/vsTrainer in audio.named; map the
  -- rest from BATTLE_SONG_IDS so GetMUS_ForBattle themes still play.
  for kind, label in pairs(Game3.BATTLE_SONGS or {}) do
    if label == name then
      return Game3.BATTLE_SONG_IDS and Game3.BATTLE_SONG_IDS[kind]
    end
  end
  return nil
end

-- Resolve a battle BGM kind from flags / trainer class, matching
-- pokeruby GetMUS_ForBattle. hint is "wild" or "trainer" from the
-- call site; optional npc overrides self.battle.npc.
function Game3:battleMusicKind(hint, npc)
  local b = self.battle
  if (b and b.kyogreGroudon) then return "kyogreGroudon" end
  if (b and b.regi) then return "regi" end
  if hint ~= "trainer" and not (npc or (b and b.npc)) then
    return "wild"
  end
  npc = npc or (b and b.npc)
  local class = npc and tonumber(npc.trainerClass)
  if not class then
    local tr = npc and self:trainerRow(npc.trainerId or self.trainerBattleOpponent)
    class = tr and tonumber(tr.class)
  end
  if not class and type(npc and npc.trainerClass) == "number" then
    class = npc.trainerClass
  end
  if class == Game3.TRAINER_CLASS_AQUA_LEADER
      or class == Game3.TRAINER_CLASS_MAGMA_LEADER then
    return "aquaMagmaLeader"
  end
  if class == Game3.TRAINER_CLASS_TEAM_AQUA
      or class == Game3.TRAINER_CLASS_AQUA_ADMIN
      or class == Game3.TRAINER_CLASS_TEAM_MAGMA
      or class == Game3.TRAINER_CLASS_MAGMA_ADMIN then
    return "aquaMagma"
  end
  if class == Game3.TRAINER_CLASS_LEADER then return "gym" end
  if class == Game3.TRAINER_CLASS_CHAMPION then return "champion" end
  if class == Game3.TRAINER_CLASS_ELITE_FOUR then return "eliteFour" end
  if class == Game3.TRAINER_CLASS_POKEMON_TRAINER_3 then
    -- GetMUS_ForBattle: Wally keeps vsTrainer; Brendan/May get vsRival.
    local name = (npc and (npc.name or npc.trainerName)) or ""
    local tr = npc and self:trainerRow(npc.trainerId or self.trainerBattleOpponent)
    if tr and tr.name then name = tr.name end
    name = tostring(name):upper()
    if name:find("WALLY", 1, true) then return "trainer" end
    local tid = tonumber(npc and npc.trainerId) or tonumber(self.trainerBattleOpponent) or 0
    if tid == Game3.TRAINER_WALLY_VICTORY_ROAD then return "trainer" end
    return "rival"
  end
  if hint == "trainer" or npc then return "trainer" end
  return "wild"
end

function Game3:getMusForBattle(hint, npc)
  local kind = self:battleMusicKind(hint, npc)
  return Game3.BATTLE_SONG_IDS[kind] or Game3.MUS_VS_WILD, kind
end

function Game3:playBattleMusic(kind)
  -- Accept a resolved kind, or "wild"/"trainer" hints that re-resolve
  -- from battle flags / trainer class (GetMUS_ForBattle).
  local resolved = kind
  if kind == nil or kind == "wild" or kind == "trainer" then
    resolved = self:battleMusicKind(kind or "wild")
  end
  local name = Game3.BATTLE_SONGS[resolved] or Game3.BATTLE_SONGS.wild
  local song = self:namedSong(name)
      or Game3.BATTLE_SONG_IDS[resolved]
      or Game3.MUS_VS_WILD
  if song then self:playSong(song, true) end
  return resolved
end

-- Sound effects and fanfares are not a separate sound system in Ruby: they
-- are ordinary songs in the same table, just played on a different music
-- player. So playse and playfanfare take a song id exactly like playbgm,
-- and only differ in which voice they land on and whether they loop.
function Game3:playSe(songId)
  songId = tonumber(songId)
  if not songId or songId == Game3.MUS_NONE then return nil end
  return Mp2kAudio.playEffect(self.data, songId, "se", false)
end

-- pokeruby m4aSongNumStart(SE_LOW_HEALTH): looping SE until SongNumStop.
function Game3:playSeLoop(songId)
  songId = tonumber(songId)
  if not songId or songId == Game3.MUS_NONE then return nil end
  return Mp2kAudio.playEffect(self.data, songId, "se", true)
end

function Game3:stopSe()
  Mp2kAudio.stop("se")
end

function Game3:sePlaying()
  return Mp2kAudio.voicePlaying("se")
end

function Game3:waitSe()
  if not self:sePlaying() then return end
  self.waitingSe = true
  self:beginScriptWait()
end

-- Battle SE pack helpers (pokeruby battlescript / controllers / pokeball).
-- Effectiveness: atk0E_effectivenesssound. Faint: PlaySE12WithPanning(SE_FAINT).
-- Catch/send-out: pokeball.c + battle_anim_special.c. Low HP: HandleLowHpMusicChange.

function Game3:effectivenessSe(mul)
  mul = tonumber(mul) or 10
  if mul <= 0 then return nil end -- MOVE_RESULT_DOESNT_AFFECT_FOE: silent
  if mul > 10 then return self:playSe(Game3.SE_SUPER_EFFECTIVE) end
  if mul < 10 then return self:playSe(Game3.SE_NOT_EFFECTIVE) end
  return self:playSe(Game3.SE_EFFECTIVE)
end

-- Queue effectiveness SE for when moveAnim ends so SE_M_* impact is not cut.
function Game3:queueEffectivenessSe(mul)
  local b = self.battle
  if not b then return end
  mul = tonumber(mul) or 10
  if mul <= 0 then
    b.pendingHitSe = nil
    return
  end
  local se
  if mul > 10 then
    se = Game3.SE_SUPER_EFFECTIVE
  elseif mul < 10 then
    se = Game3.SE_NOT_EFFECTIVE
  else
    se = Game3.SE_EFFECTIVE
  end
  local ma = b.moveAnim
  -- Scripted SE_M_* plays at anim start; defer effectiveness until anim ends.
  -- Generic / battleScene-off: play the hit cue immediately.
  if ma and ma.ruby then
    b.pendingHitSe = se
  else
    b.pendingHitSe = nil
    self:playSe(se)
  end
end

function Game3:flushPendingHitSe()
  local b = self.battle
  if not b or not b.pendingHitSe then return end
  local se = b.pendingHitSe
  b.pendingHitSe = nil
  self:playSe(se)
end

function Game3:maybePlayFaintSeFromText(b)
  if not b then return end
  local t = b.printSrc or b.text
  if type(t) ~= "string" then return end
  if not t:find("fainted!", 1, true) then return end
  if b._faintSeText == t then return end
  b._faintSeText = t
  self:playSe(Game3.SE_FAINT)
end

function Game3:playIntroPhaseSe(phase)
  if not phase then return end
  if phase == "enemy_throw" or phase == "player_throw"
      or phase == "enemy2_throw" or phase == "player2_throw" then
    self:playSe(Game3.SE_BALL_THROW)
  elseif phase == "enemy_open" or phase == "player_open"
      or phase == "enemy2_open" or phase == "player2_open" then
    self:playSe(Game3.SE_BALL_OPEN)
  elseif phase == "enemy_recall" or phase == "player_recall"
      or phase == "enemy2_recall" or phase == "player2_recall" then
    -- Return ball: open + trade-ish suck-in (CreatePokeballSprite).
    self:playSe(Game3.SE_BALL_OPEN)
  end
end

-- Catch cinema SEs timed to catchAnim.t (pokeball.c / battle_anim_special.c).
function Game3:stepCatchSe(ca)
  if not ca then return end
  ca._se = ca._se or {}
  local se = ca._se
  local t = ca.t or 0
  local throw = ca.throw or Game3.CATCH_THROW
  local open = ca.open or 0
  local bounce = ca.bounce or 0
  local per = ca.perShake or Game3.CATCH_SHAKE
  local shakes = ca.shakes or 0
  if not se.throw then
    se.throw = true
    self:playSe(Game3.SE_BALL_THROW)
  end
  if t >= throw and not se.trade then
    se.trade = true
    self:playSe(Game3.SE_BALL_TRADE)
  end
  local bounceStart = throw + open
  if bounce > 0 and t >= bounceStart then
    local bounces = {
      Game3.SE_BALL_BOUNCE_1, Game3.SE_BALL_BOUNCE_2,
      Game3.SE_BALL_BOUNCE_3, Game3.SE_BALL_BOUNCE_4,
    }
    for i = 1, 4 do
      local key = "bounce" .. i
      local at = bounceStart + bounce * ((i - 1) / 4)
      if t >= at and not se[key] then
        se[key] = true
        self:playSe(bounces[i])
      end
    end
  end
  local shakeStart = bounceStart + bounce
  for i = 1, shakes do
    local key = "shake" .. i
    local at = shakeStart + (i - 1) * per
    if t >= at and not se[key] then
      se[key] = true
      self:playSe(Game3.SE_BALL)
    end
  end
  local afterShakes = shakeStart + shakes * per
  if ca.ok and (ca.stars or 0) > 0 and t >= afterShakes and not se.caught then
    se.caught = true
    -- pokeball.c PlaySE(MUS_EVOLVED) after m4aMPlayAllStop; fanfare ducks BGM.
    self:playFanfare(Game3.MUS_EVOLVED)
  end
  if (not ca.ok) and (ca.breakout or 0) > 0 and t >= afterShakes and not se.breakout then
    se.breakout = true
    self:playSe(Game3.SE_BALL_OPEN)
  end
end

-- HandleLowHpMusicChange: red HP bar (ratio <= 0.2 ~= GetHPBarLevel==1).
function Game3:updateLowHpSe()
  local b = self.battle
  if not b then
    self:stopLowHpSe()
    return
  end
  local function red(mon)
    if not mon then return false end
    local hp, maxHp = tonumber(mon.hp) or 0, tonumber(mon.maxHp) or 0
    return maxHp > 0 and hp > 0 and (hp / maxHp) <= 0.2
  end
  local want = red(b.player) or (b.doubles and red(b.player2))
  -- Pause the beep during catch cinema so ball SEs are not stomped every frame.
  if b.catchAnim then return end
  if want then
    b.lowHpSe = true
    -- Re-arm if a one-shot SE stole the voice (single SE channel).
    if not self:sePlaying() then
      self:playSeLoop(Game3.SE_LOW_HEALTH)
    end
  elseif b.lowHpSe then
    self:stopLowHpSe()
  end
end

function Game3:stopLowHpSe()
  local b = self.battle
  if b then b.lowHpSe = false end
  -- Mirror BattleStopLowHpSound / m4aSongNumStop(SE_LOW_HEALTH).
  self:stopSe()
end

function Game3:playFanfare(songId)
  songId = tonumber(songId)
  if not songId or songId == Game3.MUS_NONE then return nil end
  self.fanfareWaitAcc = 0
  return Mp2kAudio.playEffect(self.data, songId, "fanfare")
end

function Game3:playObtainFanfare(itemId)
  local pocket = self:itemPocket(itemId)
  if pocket == Game3.POCKET_TMHM then
    return self:playFanfare(Game3.MUS_OBTAIN_TMHM)
  end
  if pocket == Game3.POCKET_BERRIES then
    return self:playFanfare(Game3.MUS_OBTAIN_BERRY)
  end
  return self:playFanfare(Game3.MUS_OBTAIN_ITEM)
end

function Game3:fanfarePlaying()
  return Mp2kAudio.voicePlaying("fanfare")
end

function Game3:waitFanfare()
  if not self:fanfarePlaying() then return end
  self.waitingFanfare = true
  self.fanfareWaitAcc = 0
  self:beginScriptWait()
end

function Game3:beginScreenFade(mode)
  mode = tonumber(mode) or Game3.FADE_FROM_BLACK
  self.screenFade = {
    mode = mode,
    t = 0,
    dur = (self.FADE_FRAMES or 16) / 60,
    hold = mode == Game3.FADE_TO_BLACK,
  }
end

-- pokeruby CB2s (wall clock, berry bag, slots) FadeScreen FROM_BLACK after
-- the script's FADE_TO_BLACK. A held TO_BLACK veil is drawn over the whole
-- window, so skipping this leaves a permanent black screen.
function Game3:fadeInFromBlack()
  if self.screenFade then
    self:beginScreenFade(Game3.FADE_FROM_BLACK)
  end
end

-- A script's FADE_TO_BLACK holds until a CB2 fades back in. Most object
-- scripts never do that here (PC, wall clock, TV, item fanfares), so the
-- overworld stayed black while START / SAVE still drew on top.
--
-- Do NOT require !scriptWaiting(): waitstate stays armed for the whole
-- CB2 (clock, PC, bag), and leftover scriptWait after a broken special
-- used to pin the veil forever even when the player could open START.
function Game3:heldFadeShouldLift()
  local fade = self.screenFade
  if not fade or fade.mode ~= Game3.FADE_TO_BLACK then return false end
  if self.phase ~= "play" then return false end
  -- Still animating the fade-out; keep covering until opaque.
  if (fade.t or 0) < (fade.dur or 0) then return false end
  if self:scriptDelaying() then return false end
  local jobs = self.moveJobs
  if type(jobs) == "table" and #jobs > 0 then return false end
  local f = self.field
  if not f then
    -- Free roam. A stuck scriptWait with no field used to keep black;
    -- lift anyway so walking / START are visible.
    return true
  end
  local k = f.kind
  -- Script transition placeholders: keep black through the warp/CB2 gap.
  if k == "delay" or k == "wait" or k == "move" or k == "truck_seq" then return false end
  -- Any other field (talk, menu, clock, bag, PC, yes/no, …) is on-screen
  -- content the player must see.
  return true
end

function Game3:releaseHeldFade()
  if not self:heldFadeShouldLift() then return false end
  self:fadeInFromBlack()
  return true
end

function Game3:softResetToBoot()
  self:clearTransientOverlay()
  self.battle = nil
  self.phase = "boot"
  self:resetBoot()
end

function Game3:screenFadeAlpha()
  local f = self.screenFade
  if not f then return 0 end
  local dur = f.dur or 0
  local u = 1
  if dur > 0 then u = (f.t or 0) / dur end
  if u < 0 then u = 0 elseif u > 1 then u = 1 end
  if f.mode == Game3.FADE_TO_BLACK then return u end
  return 1 - u
end

function Game3:stepScreenFade(dt)
  local f = self.screenFade
  if not f then return end
  f.t = (f.t or 0) + (dt or 0)
  if f.mode == Game3.FADE_FROM_BLACK and f.t >= (f.dur or 0) then
    self.screenFade = nil
  end
end

function Game3:drawScreenFade(w, h)
  local a = self:screenFadeAlpha()
  if a <= 0 then return end
  w = w or Game3.SCREEN_W
  h = h or Game3.SCREEN_H
  love.graphics.setColor(0, 0, 0, a)
  love.graphics.rectangle("fill", 0, 0, w, h)
  love.graphics.setColor(1, 1, 1, 1)
end

function Game3:stepFanfareWait(dt)
  if not self.waitingFanfare then return end
  self.fanfareWaitAcc = (self.fanfareWaitAcc or 0) + (dt or 0)
  if not self:fanfarePlaying()
      or self.fanfareWaitAcc >= Game3.FANFARE_WAIT_MAX then
    self.waitingFanfare = nil
    self.fanfareWaitAcc = nil
    self:endScriptWait()
  end
end

-- Survey zoom / tilt live in Zoom.lua / Tilt.lua (same modules Gen 1/2 use).
-- Launcher options.lua supplies them when a save has not stored a value yet.
function Game3:applyDisplayOptions(opts)
  if type(opts) ~= "table" then
    opts = self.options or {}
    local ok, SaveData = pcall(require, "src.core.SaveData")
    if ok and type(SaveData) == "table" and SaveData.loadOptions then
      local got
      ok, got = pcall(SaveData.loadOptions)
      if ok and type(got) == "table" then
        if opts.zoom == nil then opts.zoom = got.zoom end
        if opts.tilt == nil then opts.tilt = got.tilt end
        if opts.speedOverworld == nil then opts.speedOverworld = got.speedOverworld end
        if opts.speedBattle == nil then opts.speedBattle = got.speedBattle end
        if opts.speedMenu == nil then opts.speedMenu = got.speedMenu end
        if opts.voidFill == nil then opts.voidFill = got.voidFill end
      end
    end
  end
  local Zoom = require("src.render.Zoom")
  local Tilt = require("src.render.Tilt")
  if opts.zoom ~= nil then Zoom.applyOptions(opts) end
  if opts.tilt ~= nil then Tilt.applyOptions(opts) end
  self.options = self.options or {}
  self.options.zoom = Zoom.offset
  self.options.tilt = Tilt.level
  self.options.speedOverworld = GameSpeed.clamp(self.options.speedOverworld)
  self.options.speedBattle = GameSpeed.clamp(self.options.speedBattle)
  self.options.speedMenu = GameSpeed.clamp(self.options.speedMenu)
  -- Cart OPTION rows do not carry the overlay; pull it from options.lua so a
  -- CONTINUE cannot drop the layout the launcher editor saved.
  self:applyTouchOptions()
end

-- Shared on-screen pad (src/core/TouchControls.lua).  Same module Gen 1/2
-- use; layouts and haptics live in options.lua, not the cart OPTION screen.
function Game3:applyTouchOptions(opts)
  if type(opts) ~= "table" then
    opts = {}
    local ok, SaveData = pcall(require, "src.core.SaveData")
    if ok and type(SaveData) == "table" and SaveData.loadOptions then
      local got
      ok, got = pcall(SaveData.loadOptions)
      if ok and type(got) == "table" then opts = got end
    end
  end
  if Input.applyBindings then Input:applyBindings(opts.bindings) end
  TouchControls:applyOptions({
    touchControls = opts.touchControls,
    haptics = opts.haptics,
  })
end

function Game3:persistDisplayOptions()
  local options = self.options or {}
  options.zoom = require("src.render.Zoom").offset
  options.tilt = require("src.render.Tilt").level
  self.options = options
  pcall(function()
    require("src.core.SaveData").saveOptions({
      zoom = options.zoom, tilt = options.tilt,
      speedOverworld = options.speedOverworld,
      speedBattle = options.speedBattle,
      speedMenu = options.speedMenu,
      voidFill = options.voidFill,
    })
  end)
end

-- Same descriptors stepOptionMenu and drawOptionMenu share. Cart rows
-- first, then the port's per-category GAME SPEED (RFC 0007 / Gen 1),
-- then ZOOM / TILT in the unused BUTTON MODE / FRAME slots.
Game3.OPTION_VISIBLE = 7

function Game3:optionMenuSpec()
  local opt = self.options or {}
  local Zoom = require("src.render.Zoom")
  local Tilt = require("src.render.Tilt")
  return {
    { "TEXT SPEED", ({ "SLOW", "MID", "FAST" })[opt.textSpeed or 2] or "FAST",
      "textSpeed" },
    { "BATTLE SCENE", opt.battleScene == false and "OFF" or "ON", "battleScene" },
    { "BATTLE STYLE", opt.battleStyle == "set" and "SET" or "SHIFT", "battleStyle" },
    { "SOUND", opt.stereo == false and "MONO" or "STEREO", "sound" },
    { "OVERWORLD SPEED", GameSpeed.levelLabel(opt.speedOverworld), "speedOverworld" },
    { "BATTLE SPEED", GameSpeed.levelLabel(opt.speedBattle), "speedBattle" },
    { "MENU SPEED", GameSpeed.levelLabel(opt.speedMenu), "speedMenu" },
    { "ZOOM", Zoom.offsetLabel(opt.zoom or Zoom.offset or 0), "zoom" },
    { "TILT", Tilt.levelLabel(opt.tilt or Tilt.level or 0), "tilt" },
    { "VOID FILL", Game3.voidFillLabel(opt.voidFill), "voidFill" },
    { "CANCEL", "", "cancel" },
  }
end

-- Gen 1 stack walk: a battle is battle, the overworld (including START /
-- talk overlays) is overworld, boot/title is menu.
function Game3:speedCategory()
  if self.phase == "battle" or self.phase == "battle_transition" then return "battle" end
  if self.phase == "play" then return "overworld" end
  return "menu"
end

function Game3:logicSpeed()
  if self.speedOverride then return GameSpeed.clamp(self.speedOverride) end
  local key = GameSpeed.optionKey(self:speedCategory())
  local opts = self.options or {}
  return GameSpeed.clamp(opts[key] or GameSpeed.DEFAULT)
end

function Game3:_cycleSpeed(dir)
  self.options = self.options or {}
  local key = GameSpeed.optionKey(self:speedCategory())
  self.options[key] = GameSpeed.cycle(self.options[key], dir)
  self:persistDisplayOptions()
end

-- Ruby's OPTION screen has no volume rows, because the ROM has none, so the
-- levels come from the launcher's shared settings rather than from
-- self.options like TEXT SPEED and FRAME do.
function Game3:applyAudioOptions(opts)
  if type(opts) ~= "table" then
    local ok, SaveData = pcall(require, "src.core.SaveData")
    if not (ok and type(SaveData) == "table" and SaveData.loadOptions) then return end
    local got
    ok, got = pcall(SaveData.loadOptions)
    if not (ok and type(got) == "table") then return end
    opts = got
  end
  Mp2kAudio.setVolumeLevel(tonumber(opts.musicVol) or 7)
  Mp2kAudio.setEffectVolumeLevel(tonumber(opts.sfxVol) or 7)
end

function Game3:fadeDefaultBgm()
  local song = self.savedBgm or self:mapMusic()
  self.savedBgm = nil
  if song and song ~= Game3.MUS_NONE and Mp2kAudio.currentSong() == song then
    return
  end
  self:playSong(song, true)
end

-- field_specials.c UpdateTrainerFanClubGameClear. Bit 7 of
-- VAR_FANCLUB_UNKNOWN_1 is "already ran". First Hall of Fame ORs
-- 0x80 / 0x100 / 0x400 / 0x2000, unhides the four NPCs, state 1.
function Game3:updateTrainerFanClubGameClear()
  local v = self:varGet(Game3.VAR_FANCLUB_UNKNOWN_1)
  if math.floor(v / 0x80) % 2 ~= 0 then return end
  self:setScriptVar(Game3.VAR_FANCLUB_UNKNOWN_1,
    v + 0x80 + 0x100 + 0x400 + 0x2000)
  self:setScriptVar(Game3.VAR_FANCLUB_UNKNOWN_2,
    math.floor((self.playSeconds or 0) / 3600))
  self:setScriptVar(Game3.VAR_LILYCOVE_FAN_CLUB_STATE, 1)
  self.flags = self.flags or {}
  self.flags[Game3.FLAG_HIDE_FANCLUB_OLD_LADY] = nil
  self.flags[Game3.FLAG_HIDE_FANCLUB_BOY] = nil
  self.flags[Game3.FLAG_HIDE_FANCLUB_LITTLE_BOY] = nil
  self.flags[Game3.FLAG_HIDE_FANCLUB_LADY] = nil
end

function Game3.xorInt(a, b)
  a = math.floor(tonumber(a) or 0)
  b = math.floor(tonumber(b) or 0)
  local n, p = 0, 1
  while a > 0 or b > 0 do
    if (a % 2) ~= (b % 2) then n = n + p end
    a = math.floor(a / 2)
    b = math.floor(b / 2)
    p = p * 2
  end
  return n
end

function Game3:playTimeHours()
  return math.floor((self.playSeconds or 0) / 3600)
end

function Game3:shouldMoveLilycoveFanClubMember()
  local bitn = self:varGet(0x8004)
  local v = self:varGet(Game3.VAR_FANCLUB_UNKNOWN_1)
  local n = math.floor(v / (2 ^ bitn)) % 2
  return n
end

function Game3:getNumMovedLilycoveFanClubMembers()
  local v = self:varGet(Game3.VAR_FANCLUB_UNKNOWN_1)
  local n = 0
  for i = 8, 15 do
    if math.floor(v / (2 ^ i)) % 2 ~= 0 then n = n + 1 end
  end
  return n
end

function Game3:bufferStreakTrainerText()
  local which = self:varGet(0x8004)
  local a, b = 0, 0
  if which == 10 then a, b = 0, 3
  elseif which == 11 then a, b = 0, 1
  elseif which == 12 then a, b = 1, 0
  elseif which == 13 then a, b = 0, 4
  elseif which == 14 then a, b = 1, 5
  end
  local name = Game3.FAN_STREAK_NAMES[b] or Game3.FAN_STREAK_NAMES[0]
  self:setStringVar(1, name)
  return a
end

function Game3:sub810FF48()
  local v = self:varGet(Game3.VAR_FANCLUB_UNKNOWN_1)
  self:setScriptVar(Game3.VAR_FANCLUB_UNKNOWN_1, v + (math.floor(v / 0x80) % 2 == 0 and 0x80 or 0))
end

function Game3:unmoveLilycoveFanClubMember()
  if self:getNumMovedLilycoveFanClubMembers() == 1 then return 0 end
  local v = self:varGet(Game3.VAR_FANCLUB_UNKNOWN_1)
  local bits = Game3.FANCLUB_UNMOVE_BITS
  local retval = 0
  for i = 1, 8 do
    local bitn = bits[i]
    if math.floor(v / (2 ^ bitn)) % 2 ~= 0 then
      retval = i - 1
      if (self:gbaRandom() % 2) ~= 0 then
        self:setScriptVar(Game3.VAR_FANCLUB_UNKNOWN_1, v - (2 ^ bitn))
        return retval
      end
    end
  end
  local bitn = bits[retval + 1]
  if math.floor(v / (2 ^ bitn)) % 2 ~= 0 then
    self:setScriptVar(Game3.VAR_FANCLUB_UNKNOWN_1, v - (2 ^ bitn))
  end
  return retval
end

function Game3:moveLilycoveFanClubMember()
  local v = self:varGet(Game3.VAR_FANCLUB_UNKNOWN_1)
  local bits = Game3.FANCLUB_MOVE_BITS
  local retval = 0
  for i = 1, 8 do
    local bitn = bits[i]
    if math.floor(v / (2 ^ bitn)) % 2 == 0 then
      retval = i - 1
      if (self:gbaRandom() % 2) ~= 0 then
        self:setScriptVar(Game3.VAR_FANCLUB_UNKNOWN_1, v + (2 ^ bitn))
        return retval
      end
    end
  end
  local bitn = bits[retval + 1]
  if math.floor(v / (2 ^ bitn)) % 2 == 0 then
    self:setScriptVar(Game3.VAR_FANCLUB_UNKNOWN_1, v + (2 ^ bitn))
  end
  return retval
end

function Game3:updateMovedLilycoveFanClubMembers()
  local hours = self:playTimeHours()
  if hours >= 999 then return end
  local i = 0
  while true do
    if self:getNumMovedLilycoveFanClubMembers() < 5 then
      self:setScriptVar(Game3.VAR_FANCLUB_UNKNOWN_2, hours)
      return
    end
    if i == 8 then return end
    local last = self:varGet(Game3.VAR_FANCLUB_UNKNOWN_2)
    if hours - last < 12 then return end
    self:unmoveLilycoveFanClubMember()
    self:setScriptVar(Game3.VAR_FANCLUB_UNKNOWN_2, last + 12)
    i = i + 1
  end
end

function Game3:sub810FA74()
  if math.floor(self:varGet(Game3.VAR_FANCLUB_UNKNOWN_1) / 0x80) % 2 == 0 then
    return
  end
  self:updateMovedLilycoveFanClubMembers()
  self:setScriptVar(Game3.VAR_FANCLUB_UNKNOWN_2, self:playTimeHours())
end

-- field_specials.c sub_810FB10 / sub_810FF60. 0x8004 0-3 add 2/1/2/1.
function Game3:fanClubScoreSpecial()
  local a0 = self:varGet(0x8004)
  local add = Game3.FANCLUB_SCORE_ADD[(a0 % 4) + 1] or 2
  local v = self:varGet(Game3.VAR_FANCLUB_UNKNOWN_1)
  if self:varGet(Game3.VAR_LILYCOVE_FAN_CLUB_STATE) == 2 then
    local low = v % 0x80
    if low + add >= 20 then
      if self:getNumMovedLilycoveFanClubMembers() < 3 then
        self:moveLilycoveFanClubMember()
        v = self:varGet(Game3.VAR_FANCLUB_UNKNOWN_1)
        v = v - (v % 0x80)
        self:setScriptVar(Game3.VAR_FANCLUB_UNKNOWN_1, v)
      else
        v = (v - (v % 0x80)) + 20
        self:setScriptVar(Game3.VAR_FANCLUB_UNKNOWN_1, v)
      end
    else
      self:setScriptVar(Game3.VAR_FANCLUB_UNKNOWN_1, v + add)
    end
  end
  return self:varGet(Game3.VAR_FANCLUB_UNKNOWN_1) % 0x80
end

function Game3:isEnigmaBerryValid()
  return 0
end

function Game3:getNameOfEnigmaBerryInParty()
  local party = self.party or {}
  for i = 1, #party do
    local mon = party[i]
    if mon and not mon.isEgg
        and (tonumber(mon.item) or 0) == Game3.ITEM_ENIGMA_BERRY then
      self:setStringVar(1, Game3.BERRY_NAMES[#Game3.BERRY_NAMES] or "ENIGMA")
      return 1
    end
  end
  return 0
end

function Game3:showDiploma()
  self:beginScriptWait()
  self.field = { kind = "diploma", scripted = true }
end

function Game3:closeDiploma()
  self.field = nil
  self:endScriptWait()
end

function Game3.isMailItem(id)
  id = tonumber(id) or 0
  return id >= Game3.ITEM_ORANGE_MAIL and id <= Game3.ITEM_RETRO_MAIL
end

function Game3:wateringBerryTreeAnim()
  self.wateringLeft = Game3.WATERING_FRAMES
  self:beginScriptWait()
end

function Game3:spawnCameraDummy()
  self:removeCameraDummy()
  local x = self.playerX or 0
  local y = self.playerY or 0
  local dummy = {
    x = x, y = y,
    fromX = x, fromY = y,
    homeX = x, homeY = y,
    facing = "south",
    graphicsId = 7,
    movementType = 8,
    localId = Game3.LOCALID_CAMERA,
    cooldown = 0,
    wait = 0,
    placeT = 0,
    invisible = true,
  }
  self.cameraDummy = dummy
  local map = self.map
  if not map then return end
  if not self.npcByMap then self.npcByMap = {} end
  local list = self:npcsFor(map)
  if not list then
    local key = map.id or map
    self.npcByMap[key] = {}
    list = self.npcByMap[key]
  end
  list[#list + 1] = dummy
end

function Game3:removeCameraDummy()
  local dummy = self.cameraDummy
  self.cameraDummy = nil
  if not dummy then return end
  local list = self:npcsFor(self.map)
  if not list then return end
  local i = #list
  while i >= 1 do
    if list[i] == dummy or (list[i] and list[i].localId == Game3.LOCALID_CAMERA) then
      table.remove(list, i)
    end
    i = i - 1
  end
end

function Game3:doSealedChamberShakingEffect1()
  self:startCameraShake(0, Game3.SEALED_SHAKE1_PAN,
    Game3.SEALED_SHAKE_PERIOD, Game3.SEALED_SHAKE1_HITS)
end

function Game3:doSealedChamberShakingEffect2()
  self:startCameraShake(0, Game3.SEALED_SHAKE2_PAN,
    Game3.SEALED_SHAKE_PERIOD, Game3.SEALED_SHAKE2_HITS)
end

function Game3:sub807E25C()
  self.route128Fade = { t = 0, left = Game3.ROUTE128_FADE_FRAMES }
  self:beginScriptWait()
end

function Game3:route128FadeAlpha()
  local f = self.route128Fade
  if not f then return 0 end
  local t = f.t or 0
  local rise = Game3.ROUTE128_FADE_RISE
  if t < rise then
    return math.min(1, (t * 3) / 16)
  end
  t = t - rise
  if t < Game3.ROUTE128_FADE_FALL then
    local y = 16 - math.floor(t / 10)
    if y < 0 then y = 0 end
    return y / 16
  end
  return 0
end

function Game3:snapshotHallOfFame()
  local out = {}
  local teams = self.hallOfFameTeams or {}
  for i = 1, #teams do
    local team = teams[i] or {}
    local row = {}
    for j = 1, #team do
      local mon = team[j]
      if mon then
        row[#row + 1] = {
          species = tonumber(mon.species) or 0,
          level = tonumber(mon.level) or 1,
          nick = mon.nick or "",
          tid = tonumber(mon.tid) or 0,
          pid = tonumber(mon.pid) or 0,
        }
      end
    end
    out[i] = row
  end
  return out
end

function Game3:loadHallOfFame(data)
  self.hallOfFameTeams = {}
  if type(data) ~= "table" then return end
  for i = 1, Game3.HALL_OF_FAME_MAX_TEAMS do
    local team = data[i]
    if type(team) ~= "table" then break end
    local row = {}
    for j = 1, 6 do
      local mon = team[j]
      if type(mon) == "table" and (tonumber(mon.species) or 0) ~= 0 then
        row[#row + 1] = {
          species = tonumber(mon.species) or 0,
          level = tonumber(mon.level) or 1,
          nick = mon.nick or "",
          tid = tonumber(mon.tid) or 0,
          pid = tonumber(mon.pid) or 0,
        }
      end
    end
    self.hallOfFameTeams[#self.hallOfFameTeams + 1] = row
  end
end

-- hall_of_fame.c Task_Hof_InitTeamSaveData. SPECIES2 so eggs are
-- SPECIES_EGG. SAVE_HALL_OF_FAME increments GAME_STAT_ENTERED_HOF
-- (cap 999). 50 teams; a full list drops the oldest.
function Game3:recordHallOfFameTeam()
  local team = {}
  local party = self.party or {}
  for i = 1, 6 do
    local mon = party[i]
    if mon and (tonumber(mon.species) or 0) ~= 0 then
      team[#team + 1] = {
        species = self:partyMonSpecies2(mon),
        level = mon.level or 1,
        nick = mon.name or "",
        tid = mon.otId or 0,
        pid = mon.pid or 0,
      }
    end
  end
  self.hallOfFameTeams = self.hallOfFameTeams or {}
  if #self.hallOfFameTeams >= Game3.HALL_OF_FAME_MAX_TEAMS then
    table.remove(self.hallOfFameTeams, 1)
  end
  self.hallOfFameTeams[#self.hallOfFameTeams + 1] = team
  local n = self:getGameStat(Game3.GAME_STAT_ENTERED_HOF)
  if n < Game3.HALL_OF_FAME_STAT_CAP then
    self.gameStats = self.gameStats or {}
    self.gameStats[Game3.GAME_STAT_ENTERED_HOF] = n + 1
  end
end

function Game3:accessHallOfFamePC()
  self:beginScriptWait()
  local teams = self.hallOfFameTeams or {}
  local n = #teams
  local page = self:getGameStat(Game3.GAME_STAT_ENTERED_HOF)
  if page < 1 then page = n end
  self.field = {
    kind = "hof_pc",
    scripted = true,
    teamIndex = n,
    pageNo = page,
    pokeIndex = 1,
  }
end

function Game3:closeHofPc()
  self.field = nil
  self:endScriptWait()
end

-- hall_of_fame.c sub_8142B04 / HallOfFame_LoadPokemonPic: full-team sprites at
-- dest positions with GetMonSpritePalFromOtIdPersonality (tid + pid). Selected
-- mon info at the bottom (HallOfFame_PrintMonInfo). D-pad changes selection.
function Game3:drawHofPc(f)
  local G = love.graphics
  G.setColor(0.06, 0.05, 0.12, 1)
  G.rectangle("fill", 0, 0, Game3.SCREEN_W, Game3.SCREEN_H)
  local teams = self.hallOfFameTeams or {}
  local idx = tonumber(f and f.teamIndex) or 0
  local page = tonumber(f and f.pageNo) or idx
  local team = teams[idx] or {}
  G.setColor(0.98, 0.98, 0.94, 1)
  self:drawText(("HALL OF FAME No. %d"):format(page), 8, 4)
  if #team < 1 then
    self:drawText("No records.", 10, 72)
  else
    local sel = tonumber(f and f.pokeIndex) or 1
    if sel < 1 then sel = 1 end
    if sel > #team then sel = #team end
    f.pokeIndex = sel
    local count = #team
    for i = 1, count do
      local mon = team[i]
      local pos = Game3.hofSlotPos(i, count)
      local x, y = pos[3], pos[4]
      -- HallOfFame_LoadPokemonPic(species, tid, personality) shiny-aware.
      local shiny = self:isShinyMon(mon)
      local img = self:battlePic(mon and mon.species, "front", shiny)
      if img then
        local s = Game3.HOF_PIC
        local dim = (i == sel) and 1 or 0.55
        G.setColor(dim, dim, dim, 1)
        G.draw(img, x - s / 2, y - s / 2, 0, s / img:getWidth(), s / img:getHeight())
      end
    end
    local mon = team[sel]
    if mon then
      G.setColor(0.98, 0.98, 0.94, 1)
      local no = self:hoennDexOf(mon.species)
      self:drawText(no and ("No. %03d"):format(no) or "", 12, 126)
      self:drawText(("%s / %s"):format(mon.nick or "",
        self:speciesName(mon.species) or ""), 60, 126)
      self:drawText(("Lv%d"):format(mon.level or 1), 12, 140)
    end
  end
  G.setColor(0.85, 0.85, 0.80, 1)
  self:drawText("UP/DOWN mon  A next  B close", 8, 152)
  G.setColor(1, 1, 1, 1)
end

function Game3:hofPcAdvance()
  local f = self.field
  if not f then return self:closeHofPc() end
  local idx = tonumber(f.teamIndex) or 0
  if idx > 1 then
    f.teamIndex = idx - 1
    local page = tonumber(f.pageNo) or 1
    if page > 1 then f.pageNo = page - 1 end
    f.pokeIndex = 1
    return
  end
  self:closeHofPc()
end

function Game3:setPacifidlogTMReceivedDay()
  local n = (self:localTime() or {}).days or 0
  self:setScriptVar(Game3.VAR_PACIFIDLOG_TM_RECEIVED_DAY, n)
  return n
end

function Game3:getDaysUntilPacifidlogTMAvailable()
  local t = self:localTime() or {}
  local days = t.days or 0
  local received = self:varGet(Game3.VAR_PACIFIDLOG_TM_RECEIVED_DAY)
  if days < 0 then return 8 end
  if days - received >= 7 then return 0 end
  return 7 - (days - received)
end

function Game3:monSizeHash(mon)
  if not mon then return 0 end
  local pid = math.floor(tonumber(mon.pid) or 0) % 65536
  local ivs = mon.ivs or Game3.zeroIvs()
  local hp = math.floor(tonumber(ivs.hp) or 0) % 16
  local atk = math.floor(tonumber(ivs.atk) or 0) % 16
  local def = math.floor(tonumber(ivs.def) or 0) % 16
  local spe = math.floor(tonumber(ivs.spe) or 0) % 16
  local spa = math.floor(tonumber(ivs.spa) or 0) % 16
  local spd = math.floor(tonumber(ivs.spd) or 0) % 16
  local hibyte = Game3.xorInt(Game3.xorInt(atk, def) * hp, pid % 256)
  local lobyte = Game3.xorInt(Game3.xorInt(spa, spd) * spe, math.floor(pid / 256))
  return hibyte * 256 + lobyte
end

function Game3.translateBigMonSizeIndex(hash)
  hash = tonumber(hash) or 0
  local t = Game3.BIG_MON_SIZE_TABLE
  for i = 2, 15 do
    if hash < t[i][3] then return i - 1 end
  end
  return 16
end

function Game3.getMonSize(species, hash)
  local height = Game3.DEX_HEIGHT[tonumber(species) or 0] or 0
  local i = Game3.translateBigMonSizeIndex(hash)
  local row = Game3.BIG_MON_SIZE_TABLE[i]
  if not row then row = Game3.BIG_MON_SIZE_TABLE[#Game3.BIG_MON_SIZE_TABLE] end
  local unk0 = row[1] + math.floor(((tonumber(hash) or 0) - row[3]) / row[2])
  return math.floor(height * unk0 / 10)
end

function Game3.formatMonSizeRecord(size)
  size = math.floor((tonumber(size) or 0) * 10 / 25.4)
  return ("%d.%d"):format(math.floor(size / 10), size % 10)
end

function Game3:getMonSizeRecordInfo(species, varId)
  local rec = self:varGet(varId)
  local size = Game3.formatMonSizeRecord(Game3.getMonSize(species, rec))
  self:setStringVar(3, size)
  self:setStringVar(1, self:speciesName(species))
  if rec == Game3.SIZE_RECORD_DEFAULT then
    self:setStringVar(2, Game3.TEXT_MARCO)
  else
    self:setStringVar(2, self:playerName())
  end
end

function Game3:compareMonSize(species, varId)
  local slot = self:varGet(Gen3Script.VAR_RESULT)
  if slot == 0xFF then return 0 end
  local mon = self.party and self.party[slot + 1]
  if not mon or mon.isEgg or (tonumber(mon.species) or 0) ~= species then
    return 1
  end
  local rec = self:varGet(varId)
  local hash = self:monSizeHash(mon)
  local newSize = Game3.getMonSize(species, hash)
  local oldSize = Game3.getMonSize(species, rec)
  self:setStringVar(2, Game3.formatMonSizeRecord(newSize))
  if newSize <= oldSize then return 2 end
  self:setScriptVar(varId, hash % 65536)
  return 3
end

function Game3:doTimeBasedEvents()
  -- clock.c DoTimeBasedEvents: only after FLAG_SYS_CLOCK_SET.
  if not (self.flags and self.flags[Game3.FLAG_SYS_CLOCK_SET]) then return end
  local t = self:localTime() or {}
  self:updatePerDay(t)
  self:updatePerMinute(t)
end

function Game3.u32(n)
  n = tonumber(n) or 0
  n = n % Game3.U32
  if n < 0 then n = n + Game3.U32 end
  return math.floor(n)
end

-- 16-bit split: Lua doubles lose low bits of u32 * 1103515245.
function Game3.mulu32(a, b)
  a, b = Game3.u32(a), Game3.u32(b)
  local a1, a2 = a % 65536, math.floor(a / 65536)
  local b1, b2 = b % 65536, math.floor(b / 65536)
  return Game3.u32(a1 * b1 + (a1 * b2 + a2 * b1) * 65536)
end

function Game3.lcg32(n)
  return Game3.u32(Game3.mulu32(n, Game3.LCG32_MUL) + Game3.LCG32_ADD)
end

-- event_data.c ClearDailyFlags: 64 flags from DAILY_FLAGS_START.
function Game3:clearDailyFlags()
  self.flags = self.flags or {}
  local start = Game3.DAILY_FLAGS_START
  for i = 0, Game3.DAILY_FLAGS_COUNT - 1 do
    self.flags[start + i] = nil
  end
end

-- dewford_trend.c UpdateDewfordTrendPerDay. 5 pairs; falling then
-- rising against maxPop; then sort by pop / maxPop.
function Game3:updateDewfordTrendPerDay(days)
  days = tonumber(days) or 0
  if days == 0 then return end
  local pairs = self:ensureDewfordTrend()
  local step = days * 5
  for i = 1, 5 do
    local p = pairs[i]
    if type(p) == "table" then
      local pop = tonumber(p.pop) or 0
      local maxp = tonumber(p.maxPop) or 0
      local add = step
      if not p.rising then
        if pop >= add then
          pop = pop - add
          if pop == 0 then p.rising = true end
          add = 0
        else
          add = add - pop
          pop = 0
          p.rising = true
        end
      end
      if add ~= 0 then
        local total = pop + add
        if maxp > 0 and total > maxp then
          local rem = total % maxp
          local q = math.floor(total / maxp)
          p.rising = (q % 2) == 0
          if p.rising then
            pop = rem
          else
            pop = maxp - rem
            p.rising = nil
          end
        else
          pop = total
          if pop == maxp then p.rising = nil end
        end
      end
      p.pop = pop
    end
  end
  table.sort(pairs, function(a, b)
    a, b = a or {}, b or {}
    if (a.pop or 0) ~= (b.pop or 0) then
      return (a.pop or 0) > (b.pop or 0)
    end
    return (a.maxPop or 0) > (b.maxPop or 0)
  end)
end

function Game3:updateWeatherPerDay(days)
  days = tonumber(days) or 0
  self.weatherCycleStage = ((self.weatherCycleStage or 0) + days) % 4
end

function Game3:updateMirageRnd(days)
  days = tonumber(days) or 0
  local rnd = Game3.u32(self:varGet(Game3.VAR_MIRAGE_RND_H) * 65536
    + self:varGet(Game3.VAR_MIRAGE_RND_L))
  for _ = 1, days do
    rnd = Game3.lcg32(rnd)
  end
  self:setScriptVar(Game3.VAR_MIRAGE_RND_L, rnd % 65536)
  self:setScriptVar(Game3.VAR_MIRAGE_RND_H, math.floor(rnd / 65536) % 65536)
end

function Game3:updateBirchState(days)
  days = tonumber(days) or 0
  local n = (self:varGet(Game3.VAR_BIRCH_STATE) + days) % 7
  self:setScriptVar(Game3.VAR_BIRCH_STATE, n)
  return n
end

function Game3:initBirchState()
  self:setScriptVar(Game3.VAR_BIRCH_STATE, 0)
  return 0
end

-- field_specials.c SetShoalItemFlag ignores days and FlagSets 0x85F.
function Game3:setShoalItemFlag()
  self.flags = self.flags or {}
  self.flags[Game3.FLAG_SYS_SHOAL_ITEM] = true
end

-- lottery_corner.c SetRandomLotteryNumber: Random then `days` LCG steps
-- (`while (--i != 0xFFFF)` on a u16).
function Game3:setRandomLotteryNumber(days)
  days = math.floor(tonumber(days) or 0)
  local var = self:gbaRandom()
  local i = days % 65536
  while true do
    i = i - 1
    if i < 0 then i = i + 65536 end
    if i == 0xFFFF then break end
    var = Game3.lcg32(var)
  end
  self:setLotteryNumber(var)
end

-- clock.c UpdatePerDay. Pokerus already ran here; daily berry flags,
-- Dewford trends, Route 119/123 weather cycle, mirage, Birch, shoal
-- item, and lottery all tick on the same day change.
function Game3:updatePerDay(t)
  t = t or self:localTime() or {}
  local days = t.days or 0
  local stored = self:varGet(Game3.VAR_DAYS)
  if stored == days or stored > days then return end
  local daysSince = days - stored
  self:clearDailyFlags()
  self:updateDewfordTrendPerDay(daysSince)
  self:updateTVShowsPerDay(daysSince)
  self:updateWeatherPerDay(daysSince)
  self:updatePartyPokerusTime(daysSince)
  self:updateMirageRnd(daysSince)
  self:updateBirchState(daysSince)
  self:setShoalItemFlag()
  self:setRandomLotteryNumber(daysSince)
  self:setScriptVar(Game3.VAR_DAYS, days)
end

-- tv.c UpdateTVShowsPerDay — Game3Tv.attach overwrites this.
function Game3:updateTVShowsPerDay(days)
end

-- clock.c UpdatePerMinute: berries already tick from tickBerryTrees.
function Game3:updatePerMinute(t)
end

function Game3:pokerusDays(byte)
  return math.floor(tonumber(byte) or 0) % 16
end

function Game3:updatePartyPokerusTime(days)
  days = tonumber(days) or 0
  local party = self.party or {}
  for i = 1, #party do
    local mon = party[i]
    if mon and (tonumber(mon.species) or 0) ~= 0 then
      local pk = math.floor(tonumber(mon.pokerus) or 0) % 256
      local left = pk % 16
      if left ~= 0 then
        if left < days or days > 4 then
          pk = pk - left
        else
          pk = pk - days
        end
        mon.pokerus = pk
      end
    end
  end
end

function Game3:randomlyGivePartyPokerus()
  local rnd = self:gbaRandom()
  if rnd ~= 0x4000 and rnd ~= 0x8000 and rnd ~= 0xC000 then return false end
  local party = self.party or {}
  local slot
  for _ = 1, 64 do
    slot = (self:gbaRandom() % 6) + 1
    local mon = party[slot]
    if mon and (tonumber(mon.species) or 0) ~= 0 and not mon.isEgg then
      break
    end
    slot = nil
  end
  local mon = slot and party[slot]
  if not mon then return false end
  if (tonumber(mon.pokerus) or 0) ~= 0 then return false end
  local rnd2 = 0
  for _ = 1, 64 do
    rnd2 = self:gbaRandom() % 256
    if rnd2 ~= 0 then break end
  end
  if math.floor(rnd2 / 16) % 16 ~= 0 then rnd2 = rnd2 % 8 end
  rnd2 = rnd2 + rnd2 * 16
  rnd2 = rnd2 % 256
  if math.floor(rnd2 / 4) % 2 == 1 then rnd2 = rnd2 - 4 end
  if math.floor(rnd2 / 8) % 2 == 1 then rnd2 = rnd2 - 8 end
  rnd2 = (rnd2 + 1) % 256
  mon.pokerus = rnd2
  return true
end

function Game3:partySpreadPokerus()
  if (self:gbaRandom() % 3) ~= 0 then return end
  local party = self.party or {}
  local i = 1
  while i <= 6 do
    local mon = party[i]
    if mon and (tonumber(mon.species) or 0) ~= 0 then
      local pk = math.floor(tonumber(mon.pokerus) or 0) % 256
      if pk ~= 0 and (pk % 16) ~= 0 then
        if i > 1 then
          local left = party[i - 1]
          if left and (math.floor(tonumber(left.pokerus) or 0) % 256) < 16 then
            left.pokerus = pk
          end
        end
        if i < 6 then
          local right = party[i + 1]
          if right and (math.floor(tonumber(right.pokerus) or 0) % 256) < 16 then
            right.pokerus = pk
            i = i + 1
          end
        end
      end
    end
    i = i + 1
  end
end

-- safari_zone.c EnterSafariMode / ExitSafariMode. Do not beginScriptWait;
-- the entrance script warps after the special. Balls are gNumSafariBalls,
-- not the bag. Step 0 is valid remaining (Lua 0 is truthy).
function Game3:inSafariMode()
  return self.flags and self.flags[Game3.FLAG_SYS_SAFARI_MODE] == true
end

function Game3:enterSafariMode()
  self:incrementGameStat(Game3.GAME_STAT_ENTERED_SAFARI_ZONE)
  self.flags = self.flags or {}
  self.flags[Game3.FLAG_SYS_SAFARI_MODE] = true
  self.safariBalls = Game3.SAFARI_BALLS
  self.safariSteps = Game3.SAFARI_STEPS
end

function Game3:exitSafariMode()
  if self.flags then self.flags[Game3.FLAG_SYS_SAFARI_MODE] = nil end
  self.safariBalls = 0
  self.safariSteps = 0
end

-- EventScript_1C341B: VAR_SAFARI_ZONE_STATE=1, ExitSafariMode, warp
-- MAP_ROUTE121_SAFARI_ZONE_ENTRANCE (255, 2, 5).
function Game3:leaveSafari()
  self:setScriptVar(Game3.VAR_SAFARI_ZONE_STATE, 1)
  self:exitSafariMode()
  self.field = nil
  return self:scriptWarp(
    Game3.MAP_SAFARI_ENTRANCE_GROUP,
    Game3.MAP_SAFARI_ENTRANCE_NUM,
    Game3.WARP_ID_NONE,
    Game3.SAFARI_EXIT_X,
    Game3.SAFARI_EXIT_Y)
end

-- SafariZoneTakeStep: decrement, at 0 run gUnknown_081C3448.
function Game3:safariZoneTakeStep()
  if not self:inSafariMode() then return false end
  local n = self.safariSteps or 0
  n = n - 1
  if n < 0 then n = 0 end
  self.safariSteps = n
  if n ~= 0 then return false end
  if not self.field then
    self.field = {
      kind = "talk",
      text = Game3.TEXT_SAFARI_TIME_UP,
      thenSafariExit = true,
    }
  end
  return true
end

function Game3:openSafariRetirePrompt()
  self.field = {
    kind = "safari_retire",
    text = Game3.TEXT_SAFARI_RETIRE,
    cursor = 0,
  }
  return true
end

function Game3:answerSafariRetire(yes)
  if yes then return self:leaveSafari() end
  self:closeField()
  return false
end

-- field_specials.c CheckFreePokemonStorageSpace: any empty PC slot.
-- Party full is a separate getpartysize check at the entrance.
function Game3:checkFreePokemonStorageSpace()
  return (self:pcFree() > 0) and 1 or 0
end

-- field_specials.c SetSSTidalFlag / ResetSSTidalFlag / CountSSTidalStep.
-- Corridor ON_FRAME (state 1) starts the cruise; 0xCD steps run
-- gUnknown_0815FD0D (state 2 → 3 Lilycove ding, state 7 → 8 Slateport).
-- Porthole Task_HandlePorthole counts the same way but sets 9/10.
-- Do not beginScriptWait. Lua 0 is a valid remaining count.
function Game3:inCruiseMode()
  return self.flags and self.flags[Game3.FLAG_SYS_CRUISE_MODE] == true
end

function Game3:setSSTidalFlag()
  self.flags = self.flags or {}
  self.flags[Game3.FLAG_SYS_CRUISE_MODE] = true
  self:setScriptVar(Game3.VAR_CRUISE_STEP_COUNT, 0)
end

function Game3:resetSSTidalFlag()
  if self.flags then self.flags[Game3.FLAG_SYS_CRUISE_MODE] = nil end
end

function Game3:countSSTidalStep(delta)
  if not self:inCruiseMode() then return false end
  delta = tonumber(delta) or 1
  local n = (self:varGet(Game3.VAR_CRUISE_STEP_COUNT) or 0) + delta
  if n > 65535 then n = n % 65536 end
  self:setScriptVar(Game3.VAR_CRUISE_STEP_COUNT, n)
  return n > Game3.CRUISE_STEP_ARRIVE
end

-- field_specials.c GetSSTidalLocation. Non-sailing states return nil
-- (C returns 1-4). Group is always TownsAndRoutes; y is 20.
function Game3:getSSTidalLocation()
  local state = self:varGet(Game3.VAR_PORTHOLE_STATE)
  local steps = self:varGet(Game3.VAR_CRUISE_STEP_COUNT) or 0
  local num, x
  if state == Game3.PORTHOLE_SAILING_TO_LILYCOVE then
    if steps < 60 then
      num, x = Game3.MAP_ROUTE134_NUM, steps + 19
    elseif steps < 140 then
      num, x = Game3.MAP_ROUTE133_NUM, steps - 60
    else
      num, x = Game3.MAP_ROUTE132_NUM, steps - 140
    end
  elseif state == Game3.PORTHOLE_SAILING_TO_SLATEPORT then
    if steps < 66 then
      num, x = Game3.MAP_ROUTE132_NUM, 65 - steps
    elseif steps < 146 then
      num, x = Game3.MAP_ROUTE133_NUM, 145 - steps
    else
      num, x = Game3.MAP_ROUTE134_NUM, 224 - steps
    end
  else
    return nil
  end
  return 0, num, x, Game3.PORTHOLE_OCEAN_Y
end

-- sub_80C7958: FlagSet cruise (does not zero steps), saved_warp2, fade
-- to GetSSTidalLocation. Task_HandlePorthole then waitstate. Ship OBJ
-- tiles are unextracted; the player is hidden.
function Game3:ssTidalPorthole()
  self.flags = self.flags or {}
  self.flags[Game3.FLAG_SYS_CRUISE_MODE] = true
  self.flags[Game3.FLAG_DONT_TRANSITION_MUSIC] = true
  self.flags[Game3.FLAG_HIDE_MAP_NAME_POPUP] = true
  local group, num = self:currentMapGroupNum()
  self.portholeReturn = {
    mapGroup = group,
    mapNum = num,
    x = self.playerX or 0,
    y = self.playerY or 0,
  }
  self.field = { kind = "porthole", acc = 0 }
  self:beginScriptWait()
  local og, on, x, y = self:getSSTidalLocation()
  if og ~= nil then
    self:scriptWarp(og, on, Game3.WARP_ID_NONE, x, y)
  end
  self.invisible = true
end

function Game3:stepPorthole(dt)
  local f = self.field
  if not (f and f.kind == "porthole") then return end
  f.acc = (f.acc or 0) + (dt or 0)
  local period = Game3.WALK_PERIOD
  while f.acc >= period do
    f.acc = f.acc - period
    if self:countSSTidalStep(1) then
      local state = self:varGet(Game3.VAR_PORTHOLE_STATE)
      if state == Game3.PORTHOLE_SAILING_TO_LILYCOVE then
        self:setScriptVar(Game3.VAR_PORTHOLE_STATE,
          Game3.PORTHOLE_ARRIVED_VIA_VIEW_LILYCOVE)
      else
        self:setScriptVar(Game3.VAR_PORTHOLE_STATE,
          Game3.PORTHOLE_ARRIVED_VIA_VIEW_SLATEPORT)
      end
      self:exitPorthole()
      return
    end
  end
  if Input.pressed and Input:wasPressed("a") then
    self:exitPorthole()
  end
end

function Game3:exitPorthole()
  self.field = nil
  self.invisible = nil
  if self.flags then
    self.flags[Game3.FLAG_DONT_TRANSITION_MUSIC] = nil
    self.flags[Game3.FLAG_HIDE_MAP_NAME_POPUP] = nil
  end
  local d = self.portholeReturn
  self.portholeReturn = nil
  if d then
    self:scriptWarp(d.mapGroup, d.mapNum, Game3.WARP_ID_NONE, d.x, d.y)
  end
  self:endCinemaWait()
end

function Game3:ssTidalTakeStep()
  if not self:countSSTidalStep(1) then return false end
  local state = self:varGet(Game3.VAR_PORTHOLE_STATE)
  if state == Game3.PORTHOLE_SAILING_TO_LILYCOVE then
    self:resetSSTidalFlag()
    self:setScriptVar(Game3.VAR_PORTHOLE_STATE, Game3.PORTHOLE_ARRIVED_LILYCOVE)
    if not self.field then
      self.field = { kind = "talk", text = Game3.TEXT_SS_TIDAL_VOYAGE }
    end
  elseif state == Game3.PORTHOLE_SAILING_TO_SLATEPORT then
    self:resetSSTidalFlag()
    self:setScriptVar(Game3.VAR_PORTHOLE_STATE, Game3.PORTHOLE_ARRIVED_SLATEPORT)
    if not self.field then
      self.field = { kind = "talk", text = Game3.TEXT_SS_TIDAL_LAND_SLATEPORT }
    end
  end
  return true
end

-- sub_80C824C after a safari battle. Balls already decremented.
function Game3:afterSafariBattle(outcome)
  local n = self.safariBalls or 0
  if n ~= 0 then return end
  if outcome == Game3.B_OUTCOME_NO_SAFARI_BALLS then
    self:leaveSafari()
  elseif outcome == Game3.B_OUTCOME_CAUGHT then
    self.field = {
      kind = "talk",
      text = Game3.TEXT_SAFARI_OUT_OF_BALLS,
      thenSafariExit = true,
    }
  end
end

function Game3:setHoleWarp(group, num, warpId, x, y)
  self.holeWarp = {
    mapGroup = tonumber(group) or 0,
    mapNum = tonumber(num) or 0,
    warpId = tonumber(warpId) or Game3.WARP_ID_NONE,
    x = tonumber(x) or 0,
    y = tonumber(y) or 0,
  }
  return true
end

-- scrcmd SetFixedDiveWarp / gFixedDiveWarp. Sootopolis ON_RESUME
-- (and underwater emerge) store dest here; there is no dive connection.
function Game3:setDiveWarp(group, num, warpId, x, y)
  self.diveWarp = {
    mapGroup = tonumber(group) or 0,
    mapNum = tonumber(num) or 0,
    warpId = tonumber(warpId) or Game3.WARP_ID_NONE,
    x = tonumber(x) or 0,
    y = tonumber(y) or 0,
  }
  return true
end

-- pokeruby gSaveBlock1.warp4. Outdoor (town/city/route/ocean/underwater)
-- into indoor/underground/secret base records the current map at xy.
function Game3.isOutdoorMapType(t)
  t = t or 0
  return t == Game3.MAP_TYPE_TOWN
    or t == Game3.MAP_TYPE_CITY
    or t == Game3.MAP_TYPE_ROUTE
    or t == Game3.MAP_TYPE_UNDERWATER
    or t == Game3.MAP_TYPE_OCEAN_ROUTE
end

function Game3:setEscapeWarp(group, num, warpId, x, y)
  group = tonumber(group) or 0
  num = tonumber(num) or 0
  local dest = self:lookupMap(group, num)
  self.escapeWarp = {
    mapId = dest and dest.id,
    mapGroup = group,
    mapNum = num,
    warpId = tonumber(warpId) or Game3.WARP_ID_NONE,
    x = tonumber(x) or 0,
    y = tonumber(y) or 0,
  }
  return true
end

function Game3:maybeSetEscapeWarp(dest, x, y)
  local from = self.map
  if not from or not dest then return end
  if not Game3.isOutdoorMapType(from.mapType) then return end
  if Game3.isOutdoorMapType(dest.mapType) then return end
  self.escapeWarp = {
    mapId = from.id,
    mapGroup = from.group,
    mapNum = from.index,
    x = tonumber(x) or self.playerX or 0,
    y = tonumber(y) or self.playerY or 0,
  }
end

function Game3:warpHole(group, num)
  group = tonumber(group) or 0
  num = tonumber(num) or 0
  local x, y = self.playerX or 0, self.playerY or 0
  if group == Game3.MAP_UNDEFINED_GROUP and num == Game3.MAP_UNDEFINED_NUM then
    local h = self.holeWarp
    if h then
      group, num = h.mapGroup, h.mapNum
    else
      return self:fallDownHole()
    end
  end
  self.walkCooldown = 0
  self.moveJobs = {}
  if self:scriptWarp(group, num, Game3.WARP_ID_NONE, x, y) then
    self.field = { kind = "talk", text = Game3.TEXT_FELL_THROUGH }
    return true
  end
  return self:fallDownHole()
end

function Game3:followDynamicWarp()
  local d = self.dynamicWarp
  if not d then return false end
  return self:scriptWarp(d.mapGroup, d.mapNum, d.warpId, d.x, d.y)
end

function Game3:truckTownXY()
  if self:isFemale() then
    return Game3.TRUCK_TOWN_FEMALE_X, Game3.TRUCK_TOWN_FEMALE_Y
  end
  return Game3.TRUCK_TOWN_MALE_X, Game3.TRUCK_TOWN_MALE_Y
end

function Game3:setTruckIntroFlags()
  self.flags = self.flags or {}
  self.scriptVars = self.scriptVars or {}
  if self:isFemale() then
    self.scriptVars[Game3.VAR_LITTLEROOT_INTRO_STATE] = 2
    self.scriptVars[Game3.VAR_LITTLEROOT_HOUSES_STATE] = 1
  else
    self.scriptVars[Game3.VAR_LITTLEROOT_INTRO_STATE] = 1
    self.scriptVars[Game3.VAR_LITTLEROOT_HOUSES_STATE_2] = 1
  end
  self:setBedroomHeal()
end

function Game3:littlerootTownMap()
  -- Prefer the ROM map id. pack.start is often the truck after WarpToTruck
  -- / extractor quirks, so startMap() alone cannot name the town.
  local town = self:lookupMap(Game3.MAP_GROUP_TOWNS_AND_ROUTES,
    Game3.MAP_LITTLEROOT_TOWN_NUM)
  if town then return town end
  town = self:lookupMapById("g0_9")
  if town then return town end
  local start = self:startMap()
  if start and not Game3.isTruckMap(start) then return start end
end

function Game3:scriptWarp(group, num, warpId, x, y)
  group, num = tonumber(group) or 0, tonumber(num) or 0
  warpId = tonumber(warpId) or Game3.WARP_ID_NONE
  x, y = tonumber(x) or 0, tonumber(y) or 0
  local dest = self:lookupMap(group, num)
  if not dest then return false end
  if warpId ~= Game3.WARP_ID_NONE then
    local dw = dest.warps and dest.warps[warpId + 1]
    if dw then
      x, y = dw.x or x, dw.y or y
    end
  end
  self:rememberLastWarp()
  -- A script warp lands through the same machinery as a walked one, so
  -- sub_8080AE4 still picks an arrival task from the destination tile and
  -- the two door kinds still walk the player off it before the map's
  -- ON_FRAME table is consulted.
  --
  -- PetalburgCity_Gym leaves with `warp MAP_PETALBURG_CITY, 255, 15, 8`,
  -- and (15,8) is the gym's own animated door. The cart steps the player
  -- south to (15,9) first, so PetalburgCity_OnFrame's Wally tutorial walks
  -- its 8-down / 20-right path along y=17, below the POKeMON CENTER at
  -- (20,16). Starting from the doorway instead ran it along y=16 -- one
  -- tile north, straight across the CENTER.
  local db = self:behaviorAt(dest, x, y)
  self._doorArrivalPending = (db == Game3.MB_NON_ANIMATED_DOOR
    or db == Game3.MB_ANIMATED_DOOR) or nil
  self:enterMap(dest, x, y, true)
  self:startDoorArrival()
  self._doorArrivalPending = nil
  return true
end

function Game3:exitTruck()
  -- Fallback when MAP_DYNAMIC has no setdynamicwarp (tests / skipped coord).
  -- Live ROM path: coord at x=3 arms dynamic warp, then followWarp uses it.
  self:setTruckIntroFlags()
  local town = self:littlerootTownMap()
  if town then
    local x, y = self:truckTownXY()
    local w, h = town.width or 0, town.height or 0
    if x >= 0 and y >= 0 and x < w and y < h then
      self:enterMap(town, x, y, true)
      self.facing = "south"
      return true
    end
  end
  local room = self:playerBedroomMap()
  if room then
    local spawn = room.spawn or {}
    local x, y = spawn.x or 4, spawn.y or 4
    if not Game3.walkable(room, x, y) then
      x, y = spawn.x or 0, spawn.y or 0
    end
    self:enterMap(room, x, y, true)
    self.facing = "south"
    return true
  end
  if not town then return false end
  local spawn = town.spawn or {}
  self:enterMap(town, spawn.x or 0, spawn.y or 0, false)
  self.facing = "south"
  return true
end

-- field_special_scene.c GetTruckCameraBobbingY / GetTruckBoxMovement.
function Game3.getTruckCameraBobbingY(t)
  t = math.floor(tonumber(t) or 0)
  if (t % 120) == 0 then return -1 end
  if (t % 10) <= 4 then return 1 end
  return 0
end

function Game3.getTruckBoxMovement(t)
  t = math.floor(tonumber(t) or 0)
  if ((t + 120) % 180) == 0 then return -1 end
  return 0
end

-- event_object_movement.c sub_805BD90: sprite->x2 / y2 in pixels.
function Game3:setTruckBoxSpritePos(localId, x2, y2)
  local npc = self:npcByLocalId(localId)
  if not npc then return false end
  npc.spriteX2 = tonumber(x2) or 0
  npc.spriteY2 = tonumber(y2) or 0
  return true
end

function Game3:truckBoxesBob(cameraXpan, t, settled)
  cameraXpan = tonumber(cameraXpan) or 0
  t = math.floor(tonumber(t) or 0)
  if settled then
    self:setTruckBoxSpritePos(Game3.LOCALID_TRUCK_BOX_TOP,
      3 - cameraXpan, 3)
    self:setTruckBoxSpritePos(Game3.LOCALID_TRUCK_BOX_BOTTOM_L,
      -cameraXpan, -3)
    self:setTruckBoxSpritePos(Game3.LOCALID_TRUCK_BOX_BOTTOM_R,
      -3 - cameraXpan, 0)
    return
  end
  local box1 = Game3.getTruckBoxMovement(t + 30) * 4
  local box2 = Game3.getTruckBoxMovement(t) * 2
  local box3 = Game3.getTruckBoxMovement(t) * 4
  self:setTruckBoxSpritePos(Game3.LOCALID_TRUCK_BOX_TOP,
    3 - cameraXpan, box1 + 3)
  self:setTruckBoxSpritePos(Game3.LOCALID_TRUCK_BOX_BOTTOM_L,
    -cameraXpan, box2 - 3)
  self:setTruckBoxSpritePos(Game3.LOCALID_TRUCK_BOX_BOTTOM_R,
    -3 - cameraXpan, box3)
end

function Game3:setTruckDoorMetatiles(open)
  -- Map-local (4,1)/(4,2)/(4,3); ROM MapGrid uses +MAP_OFFSET.
  if open then
    self:setMetatile(4, 1, Game3.MT_TRUCK_EXIT_LIGHT_TOP, 0)
    self:setMetatile(4, 2, Game3.MT_TRUCK_EXIT_LIGHT_MID, 0)
    self:setMetatile(4, 3, Game3.MT_TRUCK_EXIT_LIGHT_BOTTOM, 0)
  else
    self:setMetatile(4, 1, Game3.MT_TRUCK_DOOR_CLOSED_TOP, 0)
    self:setMetatile(4, 2, Game3.MT_TRUCK_DOOR_CLOSED_MID, 0)
    self:setMetatile(4, 3, Game3.MT_TRUCK_DOOR_CLOSED_BOTTOM, 0)
  end
end

-- overworld.c CB2_NewGame: gFieldCallback = ExecuteTruckSequence.
function Game3:executeTruckSequence()
  if not Game3.isTruckMap(self.map) then return false end
  self:setTruckDoorMetatiles(false)
  self.fieldControlsLocked = true
  -- CpuFastFill black into gPlttBufferFaded: instant black veil.
  self.screenFade = {
    mode = Game3.FADE_TO_BLACK,
    t = 1,
    dur = 0.001,
    hold = true,
  }
  self.cameraPanX, self.cameraPanY = 0, 0
  self.field = {
    kind = "truck_seq",
    state = 0,
    t = 0,
    bobT = 0,
    panIdx = 0,
    panSub = 0,
    panMode = 0, -- 0=idle, 1=Truck1 bob, 2=Truck2, 3=Truck3
  }
  return true
end

function Game3:truckSeqActive()
  local f = self.field
  return f and f.kind == "truck_seq"
end

-- field_tasks.c EndTruckSequence (STEP_CB_TRUCK): resting box offsets
-- once Task_HandleTruckSequence is gone.
function Game3:endTruckSequence()
  if self:truckSeqActive() then return false end
  self:setTruckBoxSpritePos(Game3.LOCALID_TRUCK_BOX_TOP, 3, 3)
  self:setTruckBoxSpritePos(Game3.LOCALID_TRUCK_BOX_BOTTOM_L, 0, -3)
  self:setTruckBoxSpritePos(Game3.LOCALID_TRUCK_BOX_BOTTOM_R, -3, 0)
  return true
end

function Game3:finishTruckSequence()
  self:setTruckDoorMetatiles(true)
  self:playSe(Game3.SE_TRUCK_DOOR)
  self.cameraPanX, self.cameraPanY = 0, 0
  self.fieldControlsLocked = nil
  self.field = nil
  self:endTruckSequence()
  -- Reveal after the door opens if a held black veil remained.
  if self.screenFade and self.screenFade.mode == Game3.FADE_TO_BLACK then
    self:beginScreenFade(Game3.FADE_FROM_BLACK)
  end
end

-- Task_HandleTruckSequence + Task_Truck1/2/3, advanced in frames.
function Game3:stepTruckSequence(dt)
  local f = self.field
  if not (f and f.kind == "truck_seq") then return end
  local frames = math.floor((dt or 0) * 60 + 0.0001)
  if frames < 1 then frames = 0 end
  local i = 0
  while i < frames do
    i = i + 1
    f.t = (f.t or 0) + 1
    local state = f.state or 0

    if f.panMode == 1 then
      -- Task_Truck1: continuous bob while case 0/1/2 wait.
      f.bobT = (f.bobT or 0) + 1
      if f.bobT >= 500 * 60 then f.bobT = 0 end
      local ypan = Game3.getTruckCameraBobbingY(f.bobT)
      self.cameraPanX, self.cameraPanY = 0, ypan
      self:truckBoxesBob(0, f.bobT, false)
    elseif f.panMode == 2 or f.panMode == 3 then
      -- Task_Truck2 / Task_Truck3: table advances every 6 frames.
      f.panSub = (f.panSub or 0) + 1
      if f.panSub > 5 then
        f.panSub = 0
        f.panIdx = (f.panIdx or 0) + 1
      end
      local idx = f.panIdx or 0
      local table_ = Game3.TRUCK_CAMERA_HORIZONTAL
      if idx >= #table_ then
        f.panMode = 0
        self.cameraPanX, self.cameraPanY = 0, 0
        self:endTruckSequence()
      else
        local xpan = table_[idx + 1] or 0
        if f.panMode == 2 and xpan == 2 then
          f.panMode = 3
        end
        local ypan = 0
        if f.panMode == 2 then
          f.bobT = (f.bobT or 0) + 1
          ypan = Game3.getTruckCameraBobbingY(f.bobT)
          self:truckBoxesBob(xpan, f.bobT, false)
        else
          self:truckBoxesBob(xpan, 0, true)
        end
        self.cameraPanX, self.cameraPanY = xpan, ypan
      end
    end

    if state == 0 then
      -- SECONDS(1.5) = 90
      if f.t >= 90 then
        f.t = 0
        f.bobT = 0
        f.panMode = 1
        f.state = 1
        self:playSe(Game3.SE_TRUCK_MOVE)
      end
    elseif state == 1 then
      -- SECONDS(2.5) = 150; then pal_fill_black = FADE_FROM_BLACK.
      if f.t >= 150 then
        f.t = 0
        f.state = 2
        self:beginScreenFade(Game3.FADE_FROM_BLACK)
      end
    elseif state == 2 then
      -- Wait !gPaletteFade.active && t > SECONDS(5).
      local fading = self.screenFade ~= nil
        and self.screenFade.mode == Game3.FADE_FROM_BLACK
        and (self.screenFade.t or 0) < (self.screenFade.dur or 0)
      if (not fading) and f.t > 300 then
        f.t = 0
        f.panMode = 2
        f.panIdx = 0
        f.panSub = 0
        f.state = 3
        self:playSe(Game3.SE_TRUCK_STOP)
      end
    elseif state == 3 then
      if f.panMode == 0 then
        f.t = 0
        f.state = 4
        self.cameraPanX, self.cameraPanY = 0, 0
      end
    elseif state == 4 then
      if f.t >= 90 then
        f.t = 0
        f.state = 5
        self:playSe(Game3.SE_TRUCK_UNLOAD)
      end
    elseif state == 5 then
      if f.t >= 120 then
        self:finishTruckSequence()
        return
      end
    end
  end
  self:clampCamera()
end


function Game3:revealBirchLab()
  self.flags = self.flags or {}
  self.flags[Game3.FLAG_HIDE_BIRCH_IN_LAB] = nil
  self.flags[Game3.FLAG_HIDE_BIRCH_ROUTE101] = true
  self.flags[Game3.FLAG_HIDE_BIRCH_BATTLE_POOCHYENA] = true
  self.flags[Game3.FLAG_HIDE_POOCHYENA_ROUTE101] = true
end

function Game3:warpToBirchLab()
  local lab = self:birchLabMap()
  if not lab then return false end
  local x, y = Game3.LAB_X, Game3.LAB_Y
  if not Game3.walkable(lab, x, y) then
    local spawn = lab.spawn or {}
    x, y = spawn.x or 0, spawn.y or 0
  end
  self:enterMap(lab, x, y, true)
  self.facing = "north"
  return true
end

function Game3:startBirchChase()
  if not self:startWildBattle(Game3.SPECIES_POOCHYENA, Game3.CHASE_LEVEL) then
    return false
  end
  self.battle.chase = true
  return true
end

function Game3:finishBirchChase()
  self:revealBirchLab()
  self:warpToBirchLab()
  self.field = {
    kind = "talk",
    text = "PROF. BIRCH: Thanks! Let's talk in my lab.",
  }
end

function Game3:savePlayerParty()
  local src = self.party or {}
  local copy = {}
  for i = 1, #src do
    copy[i] = self:cloneMon(src[i])
  end
  self.savedParty = copy
  return true
end

function Game3:loadPlayerParty()
  local saved = self.savedParty
  if type(saved) ~= "table" then return false end
  local copy = {}
  for i = 1, #saved do
    copy[i] = self:cloneMon(saved[i])
  end
  self.party = copy
  self.savedParty = nil
  return true
end

-- load_save.c LoadPlayerBag: snapshots the live bag into scratch storage,
-- same shape as savePlayerParty/loadPlayerParty above. This engine keeps
-- one flat self.bag list rather than the ROM's five separate pocket
-- arrays (items/keyItems/pokeBalls/TMsHMs/berries), so one copy covers it.
function Game3:loadPlayerBag()
  local src = self.bag or {}
  local copy = {}
  for i = 1, #src do
    copy[i] = { id = src[i].id, count = src[i].count }
  end
  self.loadedBag = copy
  return true
end

function Game3:putZigzagoonInPlayerParty()
  local mon = self:makeMon(
    Game3.SPECIES_ZIGZAGOON, Game3.WALLY_TUTORIAL_ZIGZAGOON_LEVEL)
  mon.ivs = {
    hp = 32, atk = 32, def = 32, spa = 32, spd = 32, spe = 32,
  }
  self:recalcStats(mon)
  mon.hp = mon.maxHp
  mon.moves = { self:copyMove(Game3.MOVE_TACKLE) }
  -- pokeruby SetMonData MON_DATA_ALT_ABILITY TRUE: Zigzagoon's second
  -- slot is none, so Pickup does not fire on the loaner.
  mon.ability = 0
  self.party = self.party or {}
  self.party[1] = mon
  return true
end

function Game3:startWallyTutorialBattle()
  self:beginScriptWait()
  if not self:startWildBattle(
      Game3.SPECIES_RALTS, Game3.WALLY_TUTORIAL_RALTS_LEVEL) then
    self:endScriptWait()
    return false
  end
  self.battle.wallyTutorial = true
  return true
end

function Game3:tryWallyTutorialAction()
  local b = self.battle
  if not (b and b.wallyTutorial and b.kind == "menu") then return false end
  if not b.wallyTackled then
    b.wallyTackled = true
    local move = b.player and b.player.moves and b.player.moves[1]
    self:beginTurn(move)
    return true
  end
  if not b.wallyThrew then
    b.wallyThrew = true
    self:throwBall(Game3.ITEM_POKE_BALL)
    return true
  end
  return false
end

function Game3:saveFs()
  if self._saveFs then return self._saveFs end
  if SaveData.persistenceFs then return SaveData.persistenceFs() end
  return love and love.filesystem
end

function Game3:ensureSaveSlot()
  if SaveData.activeSlot("ruby") then return true end
  local id = SaveData.createSlot("ruby")
  if id then SaveData.setActiveSlot("ruby", id) end
  return SaveData.activeSlot("ruby") ~= nil
end

function Game3:snapshotMon(mon)
  if type(mon) ~= "table" then return nil end
  local moves = {}
  for i = 1, #(mon.moves or {}) do
    local m = mon.moves[i]
    if m then moves[#moves + 1] = { id = m.id, pp = m.pp } end
  end
  return {
    species = mon.species,
    level = mon.level,
    hp = mon.hp,
    exp = mon.exp,
    pid = mon.pid,
    ivs = Game3.copyIvs(mon.ivs),
    status = mon.status,
    sleepTurns = mon.sleepTurns,
    moves = moves,
    otId = mon.otId,
    otName = mon.otName,
    name = mon.name,
    isEgg = mon.isEgg and true or nil,
    hatchLeft = mon.hatchLeft,
    metLocation = mon.metLocation,
    metLevel = mon.metLevel,
    cool = mon.cool,
    beauty = mon.beauty,
    cute = mon.cute,
    smart = mon.smart,
    tough = mon.tough,
    sheen = mon.sheen,
    item = mon.item,
    effortRibbon = mon.effortRibbon and true or nil,
    championRibbon = mon.championRibbon and true or nil,
    winningRibbon = mon.winningRibbon and true or nil,
    victoryRibbon = mon.victoryRibbon and true or nil,
    hpEv = mon.hpEv,
    atkEv = mon.atkEv,
    defEv = mon.defEv,
    speEv = mon.speEv,
    spaEv = mon.spaEv,
    spdEv = mon.spdEv,
    friendship = mon.friendship,
    pokerus = mon.pokerus,
    markings = tonumber(mon.markings) or nil,
    ribbons = type(mon.ribbons) == "table" and {
      cool = mon.ribbons.cool,
      beauty = mon.ribbons.beauty,
      cute = mon.ribbons.cute,
      smart = mon.ribbons.smart,
      tough = mon.ribbons.tough,
    } or nil,
  }
end

function Game3:restoreMon(row)
  if type(row) ~= "table" or not row.species then return nil end
  local moveIds = {}
  for i = 1, #(row.moves or {}) do
    local m = row.moves[i]
    if m and m.id then moveIds[#moveIds + 1] = m.id end
  end
  local mon = self:makeMon(row.species, row.level, #moveIds > 0 and moveIds or nil)
  if type(row.pid) == "number" then mon.pid = row.pid end
  if type(row.ivs) == "table" then
    mon.ivs = Game3.copyIvs(row.ivs)
  else
    mon.ivs = Game3.zeroIvs()
  end
  self:setAbility(mon)
  if type(row.exp) == "number" then mon.exp = row.exp end
  if row.status then
    mon.status = row.status
    mon.sleepTurns = row.sleepTurns
  end
  for i = 1, #(mon.moves or {}) do
    local src = row.moves and row.moves[i]
    if src and type(src.pp) == "number" then
      mon.moves[i].pp = math.max(0, math.min(mon.moves[i].maxPp or src.pp, src.pp))
    end
  end
  if type(row.otId) == "number" then mon.otId = row.otId end
  if type(row.otName) == "string" and row.otName ~= "" then
    mon.otName = row.otName
  end
  if row.isEgg then
    mon.isEgg = true
    mon.name = "EGG"
    mon.hatchLeft = tonumber(row.hatchLeft) or self:eggCyclesFor(mon.species)
  elseif type(row.name) == "string" and row.name ~= "" then
    mon.name = row.name
  end
  if type(row.metLocation) == "number" then mon.metLocation = row.metLocation end
  if type(row.metLevel) == "number" then mon.metLevel = row.metLevel end
  for _, key in ipairs(Game3.CONTEST_KEYS) do
    if type(row[key]) == "number" then mon[key] = row[key] end
  end
  if type(row.sheen) == "number" then mon.sheen = row.sheen end
  if type(row.friendship) == "number" then mon.friendship = row.friendship end
  if type(row.pokerus) == "number" then mon.pokerus = row.pokerus end
  if type(row.markings) == "number" then mon.markings = row.markings end
  if row.effortRibbon then mon.effortRibbon = true end
  if row.championRibbon then mon.championRibbon = true end
  if row.winningRibbon then mon.winningRibbon = true end
  if row.victoryRibbon then mon.victoryRibbon = true end
  for _, key in ipairs(Game3.EV_KEYS) do
    if type(row[key]) == "number" then mon[key] = row[key] end
  end
  self:recalcStats(mon)
  if type(row.hp) == "number" then
    mon.hp = math.max(0, math.min(mon.maxHp, row.hp))
  end
  local held = tonumber(row.item)
  if held and held > 0 then mon.item = held end
  if type(row.ribbons) == "table" then
    mon.ribbons = {}
    for _, key in ipairs(Game3.CONTEST_KEYS) do
      mon.ribbons[key] = tonumber(row.ribbons[key]) or nil
    end
  end
  return mon
end

function Game3:snapshotScriptVars()
  local out = {}
  for k, v in pairs(self.scriptVars or {}) do
    local id = tonumber(k)
    local n = tonumber(v)
    if id and n and n ~= 0
        and id >= Game3.VARS_START and id < Game3.SPECIAL_VARS_START then
      out[id] = n
    end
  end
  return out
end

function Game3:loadScriptVars(vars)
  self.scriptVars = {}
  if type(vars) ~= "table" then return end
  for k, v in pairs(vars) do
    local id = tonumber(k)
    local n = tonumber(v)
    if id and n and id >= Game3.VARS_START and id < Game3.SPECIAL_VARS_START then
      self.scriptVars[id] = n
    end
  end
end

function Game3:snapshotSave()
  local party = {}
  for i = 1, #(self.party or {}) do
    party[i] = self:snapshotMon(self.party[i])
  end
  local bag = {}
  for i = 1, #(self.bag or {}) do
    local slot = self.bag[i]
    if slot then bag[#bag + 1] = { id = slot.id, count = slot.count } end
  end
  local flags = {}
  for k, v in pairs(self.flags or {}) do
    if v then flags[k] = true end
  end
  local pc = {}
  self:ensurePc()
  for b = 1, Game3.BOX_COUNT do
    local box = {}
    local src = self.pc[b] or {}
    for i = 1, Game3.BOX_SIZE do
      if src[i] then box[i] = self:snapshotMon(src[i]) end
    end
    pc[b] = box
  end
  self:harvestCaught()
  return {
    format = Game3.SAVE_FORMAT,
    engine = "gen3",
    version = "ruby",
    mapId = self.map and self.map.id,
    x = self.playerX or 0,
    y = self.playerY or 0,
    facing = self.facing or "south",
    surfing = self.surfing and true or nil,
    climbing = self.climbing and true or nil,
    diving = self.diving and true or nil,
    bike = self.bike,
    money = self.money or 0,
    balls = self.balls or 0,
    bag = bag,
    pcItems = self:compactPcItems(),
    pcMail = self:compactPcMail(),
    party = party,
    pc = pc,
    pcCurrentBox = self.pcCurrentBox or 1,
    boxNames = self.boxNames,
    boxWallpapers = self.boxWallpapers,
    caught = self:snapshotCaught(),
    seen = self:snapshotSeen(),
    gender = self.gender or Game3.GENDER_MALE,
    rivalSpecies = self.rivalSpecies,
    rivalTookStarter = self.rivalTookStarter and true or nil,
    flags = flags,
    vars = self:snapshotScriptVars(),
    healMapId = self.lastHeal and self.lastHeal.mapId,
    healX = self.lastHeal and self.lastHeal.x,
    healY = self.lastHeal and self.lastHeal.y,
    -- SaveBlock2.specialSaveWarp (SetSecretBase2Field_9): Continue warps via warp1/heal.
    specialSaveWarp = self.specialSaveWarp and true or nil,
    escapeMapId = self.escapeWarp and self.escapeWarp.mapId,
    escapeMapGroup = self.escapeWarp and self.escapeWarp.mapGroup,
    escapeMapNum = self.escapeWarp and self.escapeWarp.mapNum,
    escapeX = self.escapeWarp and self.escapeWarp.x,
    escapeY = self.escapeWarp and self.escapeWarp.y,
    repelSteps = self.repelSteps or 0,
    daycare = self:snapshotDaycare(),
    daycarePending = self.daycarePending,
    eggCycleSteps = self.eggCycleSteps or 0,
    secretBase = self:snapshotSecretBase(),
    berryTrees = self:snapshotBerryTrees(),
    berryMinuteAcc = self.berryMinuteAcc or 0,
    pokeblocks = self.pokeblocks,
    berryBlenderRecords = self.berryBlenderRecords,
    museumPortraits = self.museumPortraits,
    easyChatPairs = self:snapshotEasyChatPairs(),
    playerName = self:playerName(),
    playSeconds = math.floor(self.playSeconds or 0),
    dexCount = self:dexCount(),
    badgeCount = self:badgeCount(),
    options = self.options,
    trainerId = self:ensureTrainerId(),
    registeredItem = self.registeredItem or 0,
    coins = self:getCoins(),
    clockHour = self.clockHour,
    clockMinute = self.clockMinute,
    clockAnchor = self.clockAnchor,
    mauvilleMan = self.mauvilleMan,
    trendyUnlocked = self.trendyUnlocked,
    decorInv = self.decorInv,
    -- SaveBlock1.playerRoomDecor/Pos: the bedroom's own 12 placement slots,
    -- separate from the owned inventory above. sub_80BBDD0 reads these
    -- whenever the current map is not a secret base.
    playerRoomDecor = self.playerRoomDecor,
    playerRoomDecorPos = self.playerRoomDecorPos,
    gameStats = self.gameStats,
    gabbyAndTy = self:snapshotGabbyAndTy(),
    trainerRematches = self:snapshotTrainerRematches(),
    trainerRematchStepCounter = tonumber(self.trainerRematchStepCounter) or 0,
    hallOfFameTeams = self:snapshotHallOfFame(),
    roamer = self:snapshotRoamer(),
    sav1Weather = self.sav1Weather or 0,
    currWeather = self.currWeather or 0,
    weatherCycleStage = self.weatherCycleStage or 0,
    mapLayoutId = self.mapLayoutId or (self.map and self.map.layoutId) or 0,
    tvShows = self:snapshotTvShows(),
    battleTower = self.battleTower,
    linkBattleRecords = self.linkBattleRecords,
  }
end

function Game3:hasSave()
  local data = self:readSave()
  return data ~= nil
end

function Game3:readSave()
  local fs = self:saveFs()
  if not (fs and fs.read) then return nil, "no filesystem" end
  local main = SaveData.saveFilename("ruby")
  local names = { main, main .. ".tmp", main .. ".bak" }
  if main ~= Game3.SAVE_FILE then
    names[#names + 1] = Game3.SAVE_FILE
  end
  local data, err
  local i = 1
  while i <= #names do
    local path = names[i]
    local raw
    if fs.getInfo then
      if fs.getInfo(path) then raw = fs.read(path) end
    else
      raw = fs.read(path)
    end
    if type(raw) == "string" and raw ~= "" then
      data, err = SaveSerializer.decode(raw)
      if data then break end
    end
    i = i + 1
  end
  if not data then return nil, err or "missing" end
  if data.format ~= Game3.SAVE_FORMAT or data.engine ~= "gen3" then
    return nil, "wrong format"
  end
  if type(data.party) ~= "table" then
    return nil, "unreadable"
  end
  return data
end

function Game3:writeSave()
  if self.phase == "battle" or self.phase == "battle_transition" then return false, "Can't save now." end
  if self:inSafariMode() then return false, "Can't save now." end
  local fs = self:saveFs()
  if not (fs and fs.write) then return false, "Save failed." end
  self:ensureSaveSlot()
  self:incrementGameStat(Game3.GAME_STAT_SAVED_GAME)
  local encoded = SaveSerializer.encode(self:snapshotSave())
  local main = SaveData.saveFilename("ruby")
  local bak, tmp = main .. ".bak", main .. ".tmp"
  local dir = main:match("^(.*)/[^/]+$")
  if dir and fs.createDirectory then fs.createDirectory(dir) end
  if fs.getInfo and fs.getInfo(main) and fs.read then
    local prev = fs.read(main)
    if prev then fs.write(bak, prev) end
  end
  fs.write(tmp, encoded)
  if fs.remove then fs.remove(main) end
  local ok = fs.write(main, encoded)
  if not ok then return false, "Save failed." end
  if fs.remove then fs.remove(tmp) end
  self.saveExists = true
  return true
end

-- start_menu.c SaveGame: waitstate dialog; RESULT SAVE_SUCCESS (1) or 0.
-- Cinema skip: write immediately, do not beginScriptWait.
function Game3:saveGameSpecial()
  local ok = self:writeSave()
  local n = ok and Game3.SAVE_SUCCESS or 0
  self:setScriptVar(Gen3Script.VAR_RESULT, n)
  return n
end

function Game3:applySave(data)
  if type(data) ~= "table" then return false, "unreadable" end
  local rows = data.party
  if type(rows) ~= "table" then rows = {} end
  local party = {}
  for i = 1, #rows do
    local mon = self:restoreMon(rows[i])
    if mon then party[#party + 1] = mon end
  end
  self.party = party
  self.bag = {}
  self.balls = 0
  for i = 1, #(data.bag or {}) do
    local slot = data.bag[i]
    if slot then self:addItem(slot.id, slot.count or 1) end
  end
  self.pcItems = {}
  if type(data.pcItems) == "table" then
    for i = 1, #data.pcItems do
      local slot = data.pcItems[i]
      if slot and (tonumber(slot.id) or 0) > 0 then
        self:addPcItem(slot.id, slot.count or 1)
      end
    end
  end
  self.pcMail = {}
  if type(data.pcMail) == "table" then
    for i = 1, #data.pcMail do
      local mail = data.pcMail[i]
      if mail then self:addPcMail(mail) end
    end
  end
  if self:itemCount(Game3.ITEM_POKE_BALL) < 1 then
    self.balls = data.balls or 0
  end
  self.money = data.money or 0
  self.flags = {}
  for k, v in pairs(data.flags or {}) do
    if v then self.flags[k] = true end
  end
  self:loadScriptVars(data.vars)
  self.pc = {}
  self:ensurePc()
  if type(data.pc) == "table" then
    for b = 1, Game3.BOX_COUNT do
      local src = data.pc[b]
      if type(src) == "table" then
        for i = 1, Game3.BOX_SIZE do
          local mon = self:restoreMon(src[i])
          if mon then self.pc[b][i] = mon end
        end
      end
    end
  end
  self.pcCurrentBox = tonumber(data.pcCurrentBox) or 1
  if self.pcCurrentBox < 1 then self.pcCurrentBox = 1 end
  if self.pcCurrentBox > Game3.BOX_COUNT then self.pcCurrentBox = Game3.BOX_COUNT end
  if type(data.boxNames) == "table" then
    self.boxNames = {}
    for b = 1, Game3.BOX_COUNT do
      local name = data.boxNames[b]
      if type(name) == "string" and name ~= "" then
        self.boxNames[b] = name:sub(1, Game3.BOX_NAME_LEN)
      end
    end
  end
  if type(data.boxWallpapers) == "table" then
    self.boxWallpapers = {}
    for b = 1, Game3.BOX_COUNT do
      local paper = tonumber(data.boxWallpapers[b])
      if paper then self.boxWallpapers[b] = paper % #Game3.PC_WALLPAPERS end
    end
  end
  self:ensurePc()
  self.caught = {}
  self.seen = {}
  if type(data.caught) == "table" then
    for i = 1, #data.caught do
      self:markCaught(data.caught[i])
    end
    for k, v in pairs(data.caught) do
      if v == true then self:markCaught(k) end
    end
  end
  if type(data.seen) == "table" then
    for i = 1, #data.seen do
      self:markSeen(data.seen[i])
    end
    for k, v in pairs(data.seen) do
      if v == true then self:markSeen(k) end
    end
  end
  self:harvestCaught()
  if self.flags and self.flags[Game3.FLAG_SYS_NATIONAL_DEX] then
    self.scriptVars = self.scriptVars or {}
    self.scriptVars[Game3.VAR_NATIONAL_DEX] = Game3.NATIONAL_DEX_ENABLED
  end
  self.gender = data.gender == Game3.GENDER_FEMALE
    and Game3.GENDER_FEMALE or Game3.GENDER_MALE
  if type(data.playerName) == "string" and data.playerName ~= "" then
    self.customName = data.playerName
  end
  self.playSeconds = tonumber(data.playSeconds) or 0
  if type(data.options) == "table" then self.options = data.options end
  self:applyDisplayOptions(self.options)
  if tonumber(data.trainerId) then
    self.trainerId = math.floor(tonumber(data.trainerId))
  else
    self:ensureTrainerId()
  end
  self.registeredItem = tonumber(data.registeredItem) or 0
  self.coins = tonumber(data.coins) or 0
  self.clockHour = tonumber(data.clockHour)
  self.clockMinute = tonumber(data.clockMinute)
  self.clockAnchor = tonumber(data.clockAnchor)
  self.mauvilleMan = data.mauvilleMan
  self.trendyUnlocked = data.trendyUnlocked
  self:loadDecorationInventories(data)
  self.playerRoomDecor =
    Game3.decorSlots(Game3.DECOR_MAX_PLAYERS_HOUSE, data.playerRoomDecor)
  self.playerRoomDecorPos =
    Game3.decorSlots(Game3.DECOR_MAX_PLAYERS_HOUSE, data.playerRoomDecorPos)
  self.pokeblocks = data.pokeblocks
  self.berryBlenderRecords = data.berryBlenderRecords
  self.museumPortraits = data.museumPortraits
  self:applyTvShows(data.tvShows)
  if type(data.gameStats) == "table" then
    self.gameStats = data.gameStats
  else
    self.gameStats = nil
  end
  if type(data.battleTower) == "table" then
    self.battleTower = data.battleTower
  end
  if type(data.linkBattleRecords) == "table" then
    self.linkBattleRecords = data.linkBattleRecords
  end
  if type(self.mauvilleMan) ~= "table" then self:setupMauvilleOldMan(true) end
  self:applyGabbyAndTySave(data.gabbyAndTy)
  self:applyTrainerRematchSave(data)
  self:loadHallOfFame(data.hallOfFameTeams)
  self:applyRoamerSave(data.roamer)
  self.rivalSpecies = tonumber(data.rivalSpecies)
  self.rivalTookStarter = data.rivalTookStarter and true or nil
  if data.healMapId then
    self.lastHeal = {
      mapId = data.healMapId,
      x = data.healX or 0,
      y = data.healY or 0,
    }
  else
    self.lastHeal = nil
  end
  -- GetSecretBase2Field_9 / specialSaveWarp from GameClear.
  self.specialSaveWarp = data.specialSaveWarp and true or nil
  self._recoveredStaleHeal = self:repairStaleBedroomHeal()
  if data.escapeMapId or data.escapeMapGroup then
    self.escapeWarp = {
      mapId = data.escapeMapId,
      mapGroup = data.escapeMapGroup,
      mapNum = data.escapeMapNum,
      x = data.escapeX or 0,
      y = data.escapeY or 0,
    }
  else
    self.escapeWarp = nil
  end
  local steps = tonumber(data.repelSteps) or 0
  self.repelSteps = steps > 0 and steps or nil
  self:loadDaycare(data.daycare)
  local pending = tonumber(data.daycarePending) or 0
  self.daycarePending = pending > 0 and pending or nil
  self.eggCycleSteps = tonumber(data.eggCycleSteps) or 0
  self:loadSecretBase(data.secretBase)
  self:loadBerryTrees(data.berryTrees)
  self.berryMinuteAcc = tonumber(data.berryMinuteAcc) or 0
  self:loadEasyChatPairs(data.easyChatPairs)
  self.facing = data.facing or "south"
  -- wWalkBikeSurfState: restore before enterMap so tile validation keeps
  -- valid surf/bike/climb/dive modes.
  self.surfing = data.surfing and true or nil
  self.climbing = data.climbing and true or nil
  self.diving = data.diving and true or nil
  if data.bike == "mach" or data.bike == "acro" then
    self.bike = data.bike
  else
    -- Avatar flags are EWRAM; older saves omit bike. FLAG_SYS_CYCLING_ROAD
    -- is in SaveBlock2, so CONTINUE can remount from the bag.
    self.bike = self:bikeKindFromCyclingFlag()
  end
  local map = self:lookupMapById(data.mapId)
  if not map and data.mapId == Game3.SECRET_BASE_MAP_ID then
    map = self:secretBaseMap()
  end
  if not map and self.map and self.map.id == data.mapId then
    map = self.map
  end
  if map then
    -- sRoamerLocation is EWRAM on hardware; CONTINUE would snap to
    -- Petalburg. Keep the saved map and skip RoamerMove on this load.
    self._skipRoamerMove = true
    -- CB2_ContinueSavedGame: if specialSaveWarp, sub_8053778 -> warp1 (bedroom).
    -- Also recover older post-GameClear saves that lack specialSaveWarp but
    -- still serialize the Champions Room / Hall of Fame map as location.
    -- CB2_ContinueSavedGame: specialSaveWarp -> warp1 bedroom (sub_8053778).
    -- Also recover post-GameClear saves still parked on any IndoorEverGrande
    -- map (Corridor4 g16_8 is common) even if specialSaveWarp was lost.
    local forceHome = self.specialSaveWarp
      or (self.flags and self.flags[Game3.FLAG_SYS_GAME_CLEAR]
          and self:isChampionEndgameMap(map))
    local redirectedHome = false
    if forceHome then
      self.specialSaveWarp = nil
      local heal = self.lastHeal
      local dest, hx, hy
      if heal and heal.mapId then
        dest = self:lookupMapById(heal.mapId)
        hx, hy = heal.x or 0, heal.y or 0
      end
      if not dest or not self:lastHealIsBedroom() then
        -- Hard guarantee: cleared game must not Continue into the league.
        dest = self:playerBedroomMap()
        hx, hy = Game3.HEAL_BEDROOM_X, Game3.HEAL_BEDROOM_Y
      end
      if dest then
        self:enterMap(dest, hx or 0, hy or 0, true)
        redirectedHome = true
      else
        self:enterMap(map, data.x or 0, data.y or 0, true)
      end
    else
      self:enterMap(map, data.x or 0, data.y or 0, true)
    end
    self._skipRoamerMove = nil
    -- Use the map we actually entered (bedroom after forceHome), not the
    -- serialized league map stuck in the local `map` binding.
    local live = self.map or map
    local b = self:behaviorAt(live, self.playerX, self.playerY)
    if Game3.isSurfable(b) and not self.surfing then
      self.surfing = true
    end
    if self:isUnderwater(live) and not self.diving then
      self.diving = true
      self.surfing = true
    end
    self:repairContinueBike()
    if self._recoveredStaleHeal and self:isLittlerootCatchment(live) then
      self:warpToHeal()
    end
    -- LoadSaveblockMapHeader uses the saved mapLayoutId only when Continue
    -- stays on that map. After specialSaveWarp / endgame redirect, WarpIntoMap
    -- loads the bedroom header+layout; re-applying the league layoutId here
    -- was painting Corridor4/Champions tiles onto Littleroot (the remaining
    -- "Continue still in champion room" bug).
    if not redirectedHome then
      local savedLayout = tonumber(data.mapLayoutId)
      if savedLayout and savedLayout ~= 0 then
        self:setMapLayoutIndex(savedLayout)
        -- overworld.c InitMapFromSavedGame runs InitMapLayoutData and only
        -- THEN RunOnLoadMapScript, so everything ON_LOAD writes sits on top
        -- of the layout. Here the layout lands second and blanks the grid,
        -- taking every setmetatile the map's own ON_LOAD just made with it:
        -- Lilycove's Wailmer came back as open water you could surf right
        -- through. Re-run ON_LOAD so it ends up on top, as it does on
        -- hardware. These scripts are setmetatile writes and are safe to
        -- repeat.
        self:runMapScript("onLoad")
      end
    end
  else
    self.playerX = data.x or 0
    self.playerY = data.y or 0
  end
  self._recoveredStaleHeal = nil
  -- CONTINUE keeps SaveBlock1.weather; LoadMap would overwrite from the
  -- header (Route 111 is SUNNY) and drop a desert save.
  local savW = tonumber(data.sav1Weather)
  local curW = tonumber(data.currWeather)
  local cycle = tonumber(data.weatherCycleStage)
  if savW ~= nil then self.sav1Weather = savW end
  if curW ~= nil then
    self.currWeather = curW
  elseif savW ~= nil then
    self.currWeather = savW
  end
  if cycle ~= nil then self.weatherCycleStage = cycle end
  self.battle = nil
  self:clearTransientOverlay()
  return true
end

function Game3:continueSave()
  local data, err = self:readSave()
  if not data then return false, err or "No save file." end
  local ok, why = self:applySave(data)
  if not ok then return false, why end
  if not self.map then self:spawnAtNewGame() end
  self.phase = "play"
  self.boot = nil
  return true
end

function Game3.facingFromDelta(dx, dy)
  if dy and dy < 0 then return "north" end
  if dy and dy > 0 then return "south" end
  if dx and dx < 0 then return "west" end
  if dx and dx > 0 then return "east" end
  return "south"
end

function Game3.deltaFromFacing(facing)
  if facing == "north" then return 0, -1 end
  if facing == "south" then return 0, 1 end
  if facing == "west" then return -1, 0 end
  if facing == "east" then return 1, 0 end
  return 0, 1
end

function Game3.oppositeFacing(facing)
  if facing == "north" then return "south" end
  if facing == "south" then return "north" end
  if facing == "west" then return "east" end
  if facing == "east" then return "west" end
  return "south"
end

-- pokeruby MOVEMENT_TYPE_WALK_SEQUENCE_* (0x1D–0x34). Briney 0x32 /
-- Peeko 0x33 after VAR_BRINEY_HOUSE_STATE is the cottage chase.
Game3.WALK_SEQUENCES = {
  [0x1D] = { "north", "east", "west", "south" },
  [0x1E] = { "east", "west", "south", "north" },
  [0x1F] = { "south", "north", "east", "west" },
  [0x20] = { "west", "south", "north", "east" },
  [0x21] = { "north", "west", "east", "south" },
  [0x22] = { "west", "east", "south", "north" },
  [0x23] = { "south", "north", "west", "east" },
  [0x24] = { "east", "south", "north", "west" },
  [0x25] = { "west", "north", "south", "east" },
  [0x26] = { "north", "south", "east", "west" },
  [0x27] = { "east", "west", "north", "south" },
  [0x28] = { "south", "east", "west", "north" },
  [0x29] = { "east", "north", "south", "west" },
  [0x2A] = { "north", "south", "west", "east" },
  [0x2B] = { "west", "east", "north", "south" },
  [0x2C] = { "south", "west", "east", "north" },
  [0x2D] = { "north", "west", "south", "east" },
  [0x2E] = { "south", "east", "north", "west" },
  [0x2F] = { "west", "south", "east", "north" },
  [0x30] = { "east", "north", "west", "south" },
  [0x31] = { "north", "east", "south", "west" },
  [0x32] = { "south", "west", "north", "east" },
  [0x33] = { "west", "north", "east", "south" },
  [0x34] = { "east", "south", "west", "north" },
}

-- pokeruby g*Directions + gGetVectorDirectionFuncs index. 4-entry tables
-- weight a dir twice (Random() & 3). Stay put; only facing changes.
Game3.FACE_LOOK = {
  [0x0D] = { dirs = { "south", "north" }, vec = 1 },
  [0x0E] = { dirs = { "west", "east" }, vec = 2 },
  [0x0F] = { dirs = { "north", "west" }, vec = 3 },
  [0x10] = { dirs = { "north", "east" }, vec = 4 },
  [0x11] = { dirs = { "south", "west" }, vec = 5 },
  [0x12] = { dirs = { "south", "east" }, vec = 6 },
  [0x13] = { dirs = { "north", "south", "west", "south" }, vec = 7 },
  [0x14] = { dirs = { "south", "north", "east", "south" }, vec = 8 },
  [0x15] = { dirs = { "north", "west", "east", "north" }, vec = 9 },
  [0x16] = { dirs = { "west", "east", "south", "south" }, vec = 10 },
}

function Game3.wanderDirs(movementType)
  local mt = movementType or 0
  if mt == 1 then return "look" end
  if mt == 2 then return { "north", "south", "west", "east" } end
  if mt == 3 or mt == 4 or mt == 25 or mt == 26 then
    return { "north", "south" }
  end
  if mt == 5 or mt == 6 or mt == 27 or mt == 28 then
    return { "west", "east" }
  end
  if Game3.FACE_LOOK[mt] then return "face_look" end
  if mt == Game3.MOVEMENT_TYPE_ROTATE_COUNTERCLOCKWISE then
    return "rotate_ccw"
  end
  if mt == Game3.MOVEMENT_TYPE_ROTATE_CLOCKWISE then
    return "rotate_cw"
  end
  if Game3.WALK_SEQUENCES[mt] then return "seq" end
  if mt >= 64 and mt <= 75 then return "place" end
  if mt >= 84 and mt <= 87 then return "place" end
  return nil
end

-- GetVectorDirection / GetLimitedVectorDirection_* (event_object_movement.c).
-- dx/dy are player minus NPC. Tie on |dx|==|dy| prefers south/north.
function Game3.vectorDirection(dx, dy)
  dx, dy = dx or 0, dy or 0
  local ax, ay = dx, dy
  if ax < 0 then ax = -ax end
  if ay < 0 then ay = -ay end
  if ax > ay then
    if dx < 0 then return "west" end
    return "east"
  end
  if dy < 0 then return "north" end
  return "south"
end

function Game3.limitedSouthNorth(dx, dy)
  if (dy or 0) < 0 then return "north" end
  return "south"
end

function Game3.limitedWestEast(dx, dy)
  if (dx or 0) < 0 then return "west" end
  return "east"
end

function Game3.limitedVectorDir(vec, dx, dy)
  dx, dy = dx or 0, dy or 0
  vec = vec or 0
  if vec == 1 then return Game3.limitedSouthNorth(dx, dy) end
  if vec == 2 then return Game3.limitedWestEast(dx, dy) end
  local dir = Game3.vectorDirection(dx, dy)
  if vec == 0 then return dir end
  if vec == 3 then
    if dir == "south" then
      dir = Game3.limitedWestEast(dx, dy)
      if dir == "east" then dir = "north" end
    elseif dir == "east" then
      dir = Game3.limitedSouthNorth(dx, dy)
      if dir == "south" then dir = "north" end
    end
    return dir
  end
  if vec == 4 then
    if dir == "south" then
      dir = Game3.limitedWestEast(dx, dy)
      if dir == "west" then dir = "north" end
    elseif dir == "west" then
      dir = Game3.limitedSouthNorth(dx, dy)
      if dir == "south" then dir = "north" end
    end
    return dir
  end
  if vec == 5 then
    if dir == "north" then
      dir = Game3.limitedWestEast(dx, dy)
      if dir == "east" then dir = "south" end
    elseif dir == "east" then
      dir = Game3.limitedSouthNorth(dx, dy)
      if dir == "north" then dir = "south" end
    end
    return dir
  end
  if vec == 6 then
    if dir == "north" then
      dir = Game3.limitedWestEast(dx, dy)
      if dir == "west" then dir = "south" end
    elseif dir == "west" then
      dir = Game3.limitedSouthNorth(dx, dy)
      if dir == "north" then dir = "south" end
    end
    return dir
  end
  if vec == 7 then
    if dir == "east" then dir = Game3.limitedSouthNorth(dx, dy) end
    return dir
  end
  if vec == 8 then
    if dir == "west" then dir = Game3.limitedSouthNorth(dx, dy) end
    return dir
  end
  if vec == 9 then
    if dir == "south" then dir = Game3.limitedWestEast(dx, dy) end
    return dir
  end
  if vec == 10 then
    if dir == "north" then dir = Game3.limitedWestEast(dx, dy) end
    return dir
  end
  return dir
end

-- gClockwiseDirections: S→W→N→E. gCounterclockwiseDirections: S→E→N→W.
function Game3.nextRotateFacing(facing, clockwise)
  if clockwise then
    if facing == "south" then return "west" end
    if facing == "west" then return "north" end
    if facing == "north" then return "east" end
    return "south"
  end
  if facing == "south" then return "east" end
  if facing == "east" then return "north" end
  if facing == "north" then return "west" end
  return "south"
end

-- field_control_avatar.c IsArrowWarpMetatileBehavior. East 0x62 is
-- unused-named; north also stairs-outside-ship, south also water-arrow
-- and Shoal Cave entrance.
function Game3.isArrowWarp(behavior)
  local b = behavior or 0
  return b == Game3.MB_EAST_ARROW_WARP
      or b == Game3.MB_WEST_ARROW_WARP
      or b == Game3.MB_NORTH_ARROW_WARP
      or b == Game3.MB_SOUTH_ARROW_WARP
      or b == Game3.MB_WATER_SOUTH_ARROW_WARP
      or b == Game3.MB_STAIRS_OUTSIDE_ABANDONED_SHIP
      or b == Game3.MB_SHOAL_CAVE_ENTRANCE
end

function Game3.arrowWarpMatches(behavior, dx, dy)
  local b = behavior or 0
  if b == Game3.MB_EAST_ARROW_WARP then return dx == 1 and dy == 0 end
  if b == Game3.MB_WEST_ARROW_WARP then return dx == -1 and dy == 0 end
  if b == Game3.MB_NORTH_ARROW_WARP
      or b == Game3.MB_STAIRS_OUTSIDE_ABANDONED_SHIP then
    return dx == 0 and dy == -1
  end
  if b == Game3.MB_SOUTH_ARROW_WARP
      or b == Game3.MB_WATER_SOUTH_ARROW_WARP
      or b == Game3.MB_SHOAL_CAVE_ENTRANCE then
    return dx == 0 and dy == 1
  end
  return false
end

function Game3:eachNeighbor(map, fn)
  self:eachConnectedMap(map, fn, 1)
end

-- Keep maps that were already on screen when you cross a connection.
--
-- connectedLayout only gathers CONNECTION_DRAW_HOPS from the CURRENT map, so
-- stepping from one route to the next threw away everything that was only
-- reachable through the map you just left: at survey zoom a screen full of
-- towns and routes collapsed to flat water the moment you walked east.
-- Raising the hop count is the obvious fix and is what ran the phone out of
-- memory before -- it loads a tileset per map whether or not it is on screen.
--
-- Instead, remember what was drawn and carry it forward. Both layouts are
-- normalised so the current map sits at (0,0), so a map that was at (mx,my)
-- relative to the map we just left is at (mx+ax, my+ay) now, where (ax,ay) is
-- where that map landed in this frame. Nothing is re-walked and no extra
-- tilesets are pulled in beyond the ones already on screen.
--
-- Bounded two ways: an entry is only kept while it still touches the view
-- (that is the whole point -- "still visible"), and never more than
-- STICKY_LAYOUT_MAX of them, nearest first.
Game3.STICKY_LAYOUT_MAX = 8
Game3.STICKY_LAYOUT_MARGIN = 2

function Game3:stickyLayoutEnabled()
  if self.noStickyLayout then return false end
  return true
end

-- The view rect in current-map tile space, with a margin so a map does not
-- pop out the instant its last column leaves the screen.
function Game3:stickyViewRect()
  local vw, vh = self:viewSize()
  local t = Game3.TILE
  local mx = vw * Game3.STICKY_LAYOUT_MARGIN
  local my = vh * Game3.STICKY_LAYOUT_MARGIN
  local x0 = ((self.camX or 0) - mx) / t
  local y0 = ((self.camY or 0) - my) / t
  local x1 = ((self.camX or 0) + vw + mx) / t
  local y1 = ((self.camY or 0) + vh + my) / t
  return x0, y0, x1, y1
end

function Game3:mergeStickyLayout(list, here)
  if not self:stickyLayoutEnabled() then return list end
  local sticky = self.stickyLayout
  local have = {}
  for i = 1, #list do
    have[list[i].map.id or list[i].map] = true
  end
  if type(sticky) == "table" and sticky.anchor and type(sticky.list) == "table" then
    -- Where the map the sticky set was anchored to sits in THIS frame. When
    -- it is the current map that is (0,0) and the merge is a no-op
    -- translation -- which matters, because connectedLayout recomputes
    -- several times per map change (enterMap drops the cache) and treating
    -- anchor == here as "nothing to do" threw the carried maps away again on
    -- the second call.
    local ax, ay
    if sticky.anchor == here then
      ax, ay = 0, 0
    else
      for i = 1, #list do
        if (list[i].map.id or list[i].map) == sticky.anchor then
          ax, ay = list[i].ox, list[i].oy
          break
        end
      end
    end
    if ax then
      local vx0, vy0, vx1, vy1 = self:stickyViewRect()
      local keep = {}
      for i = 1, #sticky.list do
        local p = sticky.list[i]
        local k = p.map.id or p.map
        if not have[k] then
          local ox, oy = p.ox + ax, p.oy + ay
          local w = p.map.width or 0
          local h = p.map.height or 0
          if ox < vx1 and ox + w > vx0 and oy < vy1 and oy + h > vy0 then
            local cx = ox + w / 2
            local cy = oy + h / 2
            keep[#keep + 1] = { map = p.map, ox = ox, oy = oy,
              d = cx * cx + cy * cy }
          end
        end
      end
      table.sort(keep, function(a, b)
        if a.d ~= b.d then return a.d < b.d end
        return tostring(a.map.id or a.map) < tostring(b.map.id or b.map)
      end)
      for i = 1, math.min(#keep, Game3.STICKY_LAYOUT_MAX) do
        local p = keep[i]
        list[#list + 1] = { map = p.map, ox = p.ox, oy = p.oy }
        have[p.map.id or p.map] = true
      end
    end
  end
  self.stickyLayout = { anchor = here, list = list }
  return list
end

-- Place every map in the hop cluster from a stable root (lowest id) so
-- walking Oldale → Route 102 does not restitch the holes. Current map
-- is translated to (0, 0).
function Game3:layoutViewTiles()
  local t = Game3.TILE
  local vw, vh = self:viewSize()
  local margin = 2
  local x0 = ((self.camX or 0) / t) - margin
  local y0 = ((self.camY or 0) / t) - margin
  local x1 = ((self.camX or 0) + vw) / t + margin
  local y1 = ((self.camY or 0) + vh) / t + margin
  return x0, y0, x1, y1
end

function Game3.layoutRectHits(ox, oy, dest, vx0, vy0, vx1, vy1)
  local w = dest and dest.width or 0
  local h = dest and dest.height or 0
  return ox < vx1 and ox + w > vx0 and oy < vy1 and oy + h > vy0
end

function Game3:connectedLayout(map, hops)
  map = map or self.map
  hops = math.floor(tonumber(hops) or Game3.CONNECTION_VIEW_HOPS or 4)
  if hops < 1 then hops = 1 end
  if hops > 6 then hops = 6 end
  if not map then return {} end
  local function keyOf(m)
    return m.id or m
  end
  local here = keyOf(map)
  local vx0, vy0, vx1, vy1 = self:layoutViewTiles()
  local cacheKey = tostring(here) .. "|" .. hops .. "|"
    .. math.floor(vx0) .. "," .. math.floor(vy0) .. ","
    .. math.floor(vx1) .. "," .. math.floor(vy1)
  local cache = self.connectedLayoutCache
  if cache and cache.key == cacheKey then return cache.list end
  local byKey = { [here] = map }
  local dist = { [here] = 0 }
  local gather = { map }
  local gi = 1
  while gi <= #gather do
    local m = gather[gi]
    gi = gi + 1
    local d = dist[keyOf(m)] or 0
    if d < hops then
      local conns = m.connections
      for c = 1, #(conns or {}) do
        local conn = conns[c]
        if Game3.spatialConnection(conn) then
          local dest = conn and self:lookupMap(conn.mapGroup, conn.mapNum)
          local k = dest and keyOf(dest)
          if dest and k and not byKey[k] then
            byKey[k] = dest
            dist[k] = d + 1
            gather[#gather + 1] = dest
          end
        end
      end
    end
  end
  local rootKey, root
  for k, m in pairs(byKey) do
    if not rootKey or tostring(k) < tostring(rootKey) then
      rootKey, root = k, m
    end
  end
  local origin = {}
  local function layoutFrom(start)
    local sk = keyOf(start)
    if not origin[sk] then origin[sk] = { 0, 0 } end
    local queue = { start }
    local qi = 1
    while qi <= #queue do
      local node = queue[qi]
      qi = qi + 1
      local o = origin[keyOf(node)]
      if o then
        local conns = node.connections
        for c = 1, #(conns or {}) do
          local conn = conns[c]
          local dest = conn and self:lookupMap(conn.mapGroup, conn.mapNum)
          local k = dest and keyOf(dest)
          if dest and k and byKey[k] and not origin[k] then
            local dx, dy = Game3.neighborOrigin(conn, node, dest)
            if dx then
              origin[k] = { o[1] + dx, o[2] + dy }
              queue[#queue + 1] = dest
            end
          end
        end
      end
    end
  end
  if root then layoutFrom(root) end
  if not origin[here] then origin[here] = { 0, 0 } end
  layoutFrom(map)
  local hx, hy = 0, 0
  if origin[here] then
    hx, hy = origin[here][1], origin[here][2]
  end
  local list = {}
  local maxMaps = Game3.CONNECTION_LAYOUT_MAX or 16
  for k, m in pairs(byKey) do
    local o = origin[k]
    if o then
      local ox, oy = o[1] - hx, o[2] - hy
      local hop = dist[k] or 99
      if hop <= (Game3.CONNECTION_DRAW_HOPS or 1)
          or Game3.layoutRectHits(ox, oy, m, vx0, vy0, vx1, vy1) then
        list[#list + 1] = { map = m, ox = ox, oy = oy, hop = hop }
      end
    end
  end
  if #list > maxMaps then
    table.sort(list, function(a, b)
      return (a.hop or 0) < (b.hop or 0)
    end)
    while #list > maxMaps do list[#list] = nil end
  end
  table.sort(list, function(a, b)
    local ka = tostring(a.map.id or a.map)
    local kb = tostring(b.map.id or b.map)
    return ka < kb
  end)
  list = self:mergeStickyLayout(list, here)
  self.connectedLayoutCache = { key = cacheKey, list = list }
  return list
end

-- Direct neighbor maps (CONNECTION_DRAW_HOPS). Origins are in the current
-- map's tile space. The current map is skipped.
function Game3:eachConnectedMap(map, fn, hops)
  map = map or self.map
  if type(fn) ~= "function" or not map then return end
  local here = map.id or map
  local list = self:connectedLayout(map, hops)
  for i = 1, #list do
    local p = list[i]
    if (p.map.id or p.map) ~= here then
      fn(p.map, p.ox, p.oy)
    end
  end
end

-- CONNECTION_DIVE / CONNECTION_EMERGE pair maps for the Dive HM warp;
-- they are not overworld neighbors and must not paint into survey zoom.
function Game3.spatialConnection(conn)
  if type(conn) ~= "table" then return false end
  local d = conn.dir
  return d == "south" or d == "north" or d == "west" or d == "east"
end

function Game3.neighborOrigin(conn, src, dest)
  if type(conn) ~= "table" or type(src) ~= "table" or type(dest) ~= "table" then
    return nil
  end
  if not Game3.spatialConnection(conn) then return nil end
  local off = conn.offset or 0
  if conn.dir == "north" then return off, -(dest.height or 0) end
  if conn.dir == "south" then return off, src.height or 0 end
  if conn.dir == "west" then return -(dest.width or 0), off end
  if conn.dir == "east" then return src.width or 0, off end
  return nil
end

function Game3.facingFromMovementType(movementType)
  return MT_FACING[(movementType or 0) + 1] or "south"
end

function Game3.poseFor(spec, facing, moving, t)
  facing = facing or "south"
  local pose
  if moving and spec and spec.walk and spec.walk[facing] and #spec.walk[facing] > 0 then
    local poses = spec.walk[facing]
    local i = math.floor((t or 0) * #poses) + 1
    if i < 1 then i = 1 elseif i > #poses then i = #poses end
    pose = poses[i]
  else
    pose = spec and spec.face and spec.face[facing]
  end
  if not pose then return { frame = 0, flip = false } end
  -- Inanimate sheets (bag, truck) are one frame. LOOK_AROUND still
  -- changes facing, and a borrowed walk script can index past the PNG.
  local n = spec and spec.frameCount
  local frame = pose.frame or 0
  if n and frame >= n then
    return { frame = 0, flip = pose.flip and true or false }
  end
  return pose
end

function Game3.spriteSpec(sprites, graphicsId)
  local byId = sprites and sprites.byId
  if type(byId) ~= "table" then return nil end
  return byId[graphicsId]
end

function Game3.spriteDrawPos(tileX, tileY, width, height, lift)
  width = width or Game3.TILE
  height = height or Game3.TILE
  local px = Game3.snapPixel(tileX * Game3.TILE + math.floor((Game3.TILE - width) / 2))
  local py = Game3.snapPixel(tileY * Game3.TILE + Game3.TILE - height - (lift or 0))
  return px, py
end

-- 16x16 trainer-see icon. GBA objc_exclamation_mark_probably places it
-- at object.y - 16, i.e. flush above a 32px OW sprite's head.
function Game3.emoteDrawPos(tileX, tileY, lift)
  return Game3.spriteDrawPos(
    tileX, tileY, Game3.EMOTE_SIZE, Game3.EMOTE_SIZE,
    (lift or 0) + Game3.TILE * 2)
end

function Game3.emoteSpec(sprites, emote)
  if not emote then return nil end
  local row = sprites and sprites.emotes and sprites.emotes[emote]
  if type(row) == "table" and row.path then return row end
  if not Game3.EMOTE_GLYPH[emote] then return nil end
  return {
    path = ("assets/generated/emotes/%s.png"):format(emote),
    width = Game3.EMOTE_SIZE,
    height = Game3.EMOTE_SIZE,
  }
end

-- field_effect_helpers.c GetReflectionVerticalOffset: graphics height - 2.
-- LÖVE sy=-1 pins local y=0 at the origin and grows upward, so the origin
-- is the flipped sprite's head (the lowest pixel, in the water).
function Game3.reflectionDrawY(py, height)
  height = height or Game3.TILE
  return (py or 0) + 2 * height - 2
end

function Game3:grabImage(path)
  if type(path) ~= "string" then return nil end
  local Assets = require("src.render.Assets")
  local ok, img = pcall(Assets.image, path)
  if not ok or not img then
    ok, img = pcall(love.graphics.newImage, path)
  end
  if ok and img then
    if img.setFilter then img:setFilter("nearest", "nearest") end
    return img
  end
  return nil
end

-- tileset_anim.c: sub_8072EDC ticks once per field frame and the wrapper gates
-- the DMA with `if (a1 % period == 0)`, so a tileset advances one animation
-- frame every `period` frames. The extractor bakes each frame as its own
-- atlas, so playing the animation is picking which atlas to sample.
function Game3:tilesetAnimSpec(tilesetId)
  local spec = self.data.tilesets and self.data.tilesets.byId
    and self.data.tilesets.byId[tilesetId]
  local anim = spec and spec.anim
  if type(anim) ~= "table" then return nil end
  local frames = tonumber(anim.frames) or 0
  if frames < 2 then return nil end
  return anim, frames, math.max(1, tonumber(anim.period) or 16)
end

function Game3:tilesetAnimFrame(tilesetId)
  local anim, frames, period = self:tilesetAnimSpec(tilesetId)
  if not anim then return 0 end
  local ticks = math.floor((self.playSeconds or 0) * 60)
  return math.floor(ticks / period) % frames
end

-- One animation frame's atlases, or nil when that frame has none of its own.
-- Kept separate from layersFor so the caller can tell "this frame is missing"
-- apart from "here is the resting atlas" -- stepTilesetAnim has to hold the
-- last good frame rather than drop to frame 0 on every cycle.
function Game3:animLayers(tilesetId, frame)
  if not tilesetId or not frame or frame < 1 then return nil, nil end
  local anim = self:tilesetAnimSpec(tilesetId)
  local paths = anim and anim.layers and anim.layers[frame]
  if not paths then return nil, nil end
  local key = tilesetId .. "#" .. frame
  local hit = self.atlasCache[key]
  if hit and hit.bottom and hit.top then return hit.bottom, hit.top end
  local b = self:grabImage(paths.bottom)
  local t = self:grabImage(paths.top)
  if not (b and t) then return nil, nil end
  self.atlasCache[key] = { bottom = b, top = t }
  return b, t
end

function Game3:layersFor(tilesetId, frame)
  if not tilesetId then return nil, nil end
  frame = frame or self:tilesetAnimFrame(tilesetId)
  local ab, at = self:animLayers(tilesetId, frame)
  if ab then return ab, at end
  local cached = self.atlasCache[tilesetId]
  -- A nil top is not a successful load. COVERED fence/house tops live
  -- only on that atlas; caching the miss left Route 111's picket fence
  -- as dirt with collision (the "invisible wall" south of Winstrate).
  if cached and cached.bottom and cached.top then
    return cached.bottom, cached.top
  end
  local spec = self.data.tilesets and self.data.tilesets.byId
    and self.data.tilesets.byId[tilesetId]
  if not spec then return nil, nil end
  local bottom = self:grabImage(spec.bottom) or (cached and cached.bottom)
  local top = self:grabImage(spec.top) or (cached and cached.top)
  self.atlasCache[tilesetId] = { bottom = bottom, top = top }
  return bottom, top
end

function Game3:loadTileset()
  self.layerBottom, self.layerTop = nil, nil
  local map = self.map
  if not map then return end
  self._tilesetFrame = self:tilesetAnimFrame(map.tileset)
  self.layerBottom, self.layerTop = self:layersFor(map.tileset, self._tilesetFrame)
end

-- Swap in the next frame's atlases when the tick rolls over. tileWindow keys
-- its sprite batch on the frame, so the ground rebuilds itself from there.
function Game3:stepTilesetAnim()
  local map = self.map
  if not map or not map.tileset then return end
  if not self:tilesetAnimSpec(map.tileset) then return end
  local frame = self:tilesetAnimFrame(map.tileset)
  if frame == self._tilesetFrame then return end
  local bottom, top
  if frame == 0 then
    bottom, top = self:layersFor(map.tileset, 0)
  else
    bottom, top = self:animLayers(map.tileset, frame)
  end
  if not bottom then return end
  self._tilesetFrame = frame
  self.layerBottom, self.layerTop = bottom, top
end

function Game3:quadFor(mid, image)
  local cols = (self.data.tilesets and self.data.tilesets.atlasCols) or Game3.ATLAS_COLS
  local sw, sh = 512, 512
  if image and image.getDimensions then
    sw, sh = image:getDimensions()
  end
  local key = mid .. ":" .. sw .. "x" .. sh
  local q = self.quads[key]
  if not q then
    local col = mid % cols
    local row = math.floor(mid / cols)
    q = love.graphics.newQuad(
      col * Game3.TILE, row * Game3.TILE,
      Game3.TILE, Game3.TILE, sw, sh)
    self.quads[key] = q
  end
  return q
end

function Game3:quadFor8(mid, corner, image)
  local cols = (self.data.tilesets and self.data.tilesets.atlasCols) or Game3.ATLAS_COLS
  local sw, sh = 512, 512
  if image and image.getDimensions then
    sw, sh = image:getDimensions()
  end
  local key = "8:" .. mid .. ":" .. corner .. ":" .. sw
  local q = self.quads[key]
  if not q then
    local col = mid % cols
    local row = math.floor(mid / cols)
    q = love.graphics.newQuad(
      col * Game3.TILE + (corner % 2) * 8,
      row * Game3.TILE + math.floor(corner / 2) * 8,
      8, 8, sw, sh)
    self.quads[key] = q
  end
  return q
end

function Game3:drawAnimCorners(image, map, mid, px, py, topPass, batch, behavior, mode, collision)
  if Game3.ledgeDelta(behavior) then return end
  local spec = self.data.tilesets and self.data.tilesets.byId
    and map and self.data.tilesets.byId[map.tileset]
  local tiles = spec and spec.overworldAnim and spec.tiles and spec.tiles[mid]
  if not tiles then return end
  if not self:tileAnimFlip() then return end
  local start = topPass and 5 or 1
  local i0, i1 = 0, 3
  if mode == "top8" then i1 = 1 elseif mode == "bottom8" then i0 = 2 end
  local G = love.graphics
  for i = i0, i1 do
    if Game3.shouldAnimCorner(tiles[start + i], behavior, tiles, start, collision) then
      local q = self:quadFor8(mid, i, image)
      local ox = (i % 2) * 8
      local oy = math.floor(i / 2) * 8
      if batch then
        batch:add(q, px + ox + 8, py + oy, 0, -1, 1)
      else
        G.draw(image, q, px + ox + 8, py + oy, 0, -1, 1)
      end
    end
  end
end

function Game3:beginScriptRun()
  self._scriptDepth = (self._scriptDepth or 0) + 1
end

function Game3:endScriptRun()
  local d = self._scriptDepth
  if not d then return end
  d = d - 1
  if d < 1 then
    self._scriptDepth = nil
    -- Script context finished without an explicit releaseall (broken /
    -- truncated scripts). Match cart teardown so the player is not stuck
    -- frozen after a failed trainerbattle mid-Champions Room.
    if not self._scriptPause then
      self.fieldControlsLocked = nil
    end
    self:flushPendingMapScripts()
  else
    self._scriptDepth = d
  end
end

function Game3:flushPendingMapScripts()
  if not self._pendingMapFrame then return false end
  if self.field then return false end
  if (self._scriptDepth or 0) > 0 then return false end
  self._pendingMapFrame = nil
  if self:tryMapFrameScript() then return true end
  return self:tryCoordEvent(self.playerX, self.playerY)
end

-- Fades, script waits, and 240×160 field UIs live in EWRAM. Escape to the
-- title and CONTINUE must drop them or a held TO_BLACK / HUD canvas plate
-- sits over the zoomed map after load (berry plant bag, yes/no, talk).
function Game3:clearTransientOverlay()
  self.field = nil
  self.battleEntrance = nil
  self.screenFade = nil
  self.scriptWait = nil
  self._scriptPause = nil
  self._scriptLoaded = nil
  self._scriptSays = nil
  self._scriptReturn = nil
  self._scriptCmp = 0
  self.delayLeft = nil
  self.fieldControlsLocked = nil
  self.moneyBox = nil
  self.coinsBox = nil
  self.orb = nil
  self.route128Fade = nil
  self.fieldEffects = nil
  self._waitFieldEffect = nil
end

function Game3:wipeNewGameState()
  self.party = {}
  self.pc = {}
  self.pcCurrentBox = 1
  self.boxNames = nil
  self.boxWallpapers = nil
  self.caught = {}
  self.seen = {}
  self.bag = {}
  self.money = Game3.START_MONEY
  self.coins = 0
  self.clockHour = nil
  self.clockMinute = nil
  self.clockAnchor = nil
  self.coinsBox = nil
  self.balls = 0
  self.pcItems = nil
