function Game3:spawnAtNewGame()
  local truck = self:findTruckMap()
  if truck then
    -- WarpToTruck writes dummy xy (-1,-1). SetPlayerCoordsFromWarp then
    -- uses layout width/2, height/2, not the first walkable cell.
    local w, h = truck.width or 5, truck.height or 5
    self:enterMap(truck, math.floor(w / 2), math.floor(h / 2), false)
    self:setBedroomHeal()
    return true
  end
  local pack = self.data and self.data.maps
  local start = pack and pack.maps and pack.maps[pack.start]
  if start then
    local spawn = start.spawn or {}
    self:enterMap(start, spawn.x or 0, spawn.y or 0, false)
    self:setBedroomHeal()
    return true
  end
  return self.map ~= nil
end

function Game3:resetWorldForNewGame()
  self:wipeNewGameState()
  self:spawnAtNewGame()
end

-- sub_8053D14 / LoadCurrentMapData. Freeze a copy of the header grid.
-- Do not replace map.grid on a normal enter: gym tests hold that table.
function Game3.copyGrid(src)
  if type(src) ~= "table" then return {} end
  local out = {}
  for i = 1, #src do out[i] = src[i] end
  return out
end

function Game3:ensureMapBase(map)
  if not map or map.baseGrid then return end
  map.baseGrid = Game3.copyGrid(map.grid)
  map.baseWidth = map.width
  map.baseHeight = map.height
  map.baseTileset = map.tileset
  map.baseBorder = map.border
end

function Game3.writeGrid(dst, src)
  if type(src) ~= "table" then return dst end
  if type(dst) ~= "table" then return Game3.copyGrid(src) end
  local n = #src
  if #dst > n then n = #dst end
  for i = 1, n do dst[i] = src[i] end
  return dst
end

function Game3:restoreMapLayout(map)
  if not map or not map.baseGrid then return end
  map.width = map.baseWidth
  map.height = map.baseHeight
  map.tileset = map.baseTileset
  map.grid = Game3.writeGrid(map.grid, map.baseGrid)
  map.border = map.baseBorder
  map.layoutSwapped = nil
  self:markTilesDirty()
end

function Game3:lookupLayout(id)
  id = tonumber(id) or 0
  if id == 0 then return nil end
  local pack = self.data and self.data.maps or {}
  local extra = pack.layouts
  local row = extra and (extra[id] or extra[tostring(id)])
  if type(row) == "table" then return row end
  local maps = pack.maps
  if type(maps) ~= "table" then return nil end
  for _, m in pairs(maps) do
    if m and tonumber(m.layoutId) == id then
      return {
        width = m.baseWidth or m.width,
        height = m.baseHeight or m.height,
        grid = m.baseGrid or m.grid,
        tileset = m.baseTileset or m.tileset,
        border = m.baseBorder or m.border,
      }
    end
  end
end

-- ScrCmd_setmaplayoutindex → sub_8053D14. Same events; collision /
-- tiles come from gMapLayouts[id - 1].
function Game3:setMapLayoutIndex(id)
  id = tonumber(id) or 0
  if id == 0 then return end
  self.mapLayoutId = id
  local layout = self:lookupLayout(id)
  local map = self.map
  if not layout or not map then return end
  self:ensureMapBase(map)
  map.width = layout.width or map.width
  map.height = layout.height or map.height
  if layout.tileset then map.tileset = layout.tileset end
  if type(layout.grid) == "table" then
    map.grid = Game3.writeGrid(map.grid, layout.grid)
  end
  if layout.border then map.border = layout.border end
  map.layoutSwapped = true
  -- Writing the layout wipes anything baked into the grid. The ROM applies
  -- the layout in InitMapLayoutData and only then runs
  -- InitSecretBaseAppearance, so the decorations go back on top; on the
  -- CONTINUE path this engine gets here AFTER enterMap already stamped
  -- them, which is what made a reload lose every placed decoration while
  -- the record still listed them as in use.
  map._pristineGrid = nil
  self:initSecretBaseAppearance(map)
  self:markTilesDirty()
  if self.map == map then self:loadTileset() end
end

-- time_events.c IsMirageIslandPresent: high 16 of the 32-bit rnd
-- (VAR_MIRAGE_RND_H) vs personality & 0xFFFF of a non-empty party slot.
function Game3:isMirageIslandPresent()
  local rnd = (tonumber(self:varGet(Game3.VAR_MIRAGE_RND_H)) or 0) % 65536
  local party = self.party or {}
  for i = 1, #party do
    local mon = party[i]
    if mon and (tonumber(mon.species) or 0) ~= 0 then
      local pid = tonumber(mon.pid) or 0
      if (pid % 65536) == rnd then return 1 end
    end
  end
  return 0
end

-- time_events.c UpdateShoalTideFlag. Only when lastUsedWarp is outdoor
-- (is_map_type_1_2_3_5_or_6). hours 0-23 from RtcCalcLocalTime.
function Game3:updateShoalTideFlag()
  if not Game3.isOutdoorMapType(self:lastUsedWarpMapType()) then return end
  local hour = (self:localTime().hours or 0) % 24
  local high = Game3.SHOAL_TIDE_BY_HOUR[hour + 1]
  self.flags = self.flags or {}
  if high ~= 0 then
    self.flags[Game3.FLAG_SYS_SHOAL_TIDE] = true
  else
    self.flags[Game3.FLAG_SYS_SHOAL_TIDE] = nil
  end
end

function Game3:setupEvilTeamGfxIds()
  -- Common_EventScript_SetupEvilTeamGfxIds (Ruby): Magma on VAR_1/2, Aqua
  -- on VAR_4/5, Maxie on VAR_6, Archie on VAR_7. Magma Hideout maps omit
  -- the ON_TRANSITION call Aqua Hideout has, so warping in with unset
  -- vars left GFX_VAR_* as brown squares.
  self:setScriptVar(Game3.VAR_OBJ_GFX_ID_0 + 1, Game3.GFX_MAGMA_MEMBER_M)
  self:setScriptVar(Game3.VAR_OBJ_GFX_ID_0 + 2, Game3.GFX_MAGMA_MEMBER_F)
  self:setScriptVar(Game3.VAR_OBJ_GFX_ID_0 + 4, Game3.GFX_AQUA_MEMBER_M)
  self:setScriptVar(Game3.VAR_OBJ_GFX_ID_0 + 5, Game3.GFX_AQUA_MEMBER_F)
  self:setScriptVar(Game3.VAR_OBJ_GFX_ID_0 + 6, Game3.GFX_MAXIE)
  self:setScriptVar(Game3.VAR_OBJ_GFX_ID_0 + 7, Game3.GFX_ARCHIE)
end

function Game3:mapNeedsEvilTeamGfx(map)
  map = map or self.map
  if not map then return false end
  local g = tonumber(map.group)
  local n = tonumber(map.index)
  if not g or not n then
    local gs, ns = tostring(map.id or ""):match("^g(%d+)_(%d+)$")
    g, n = tonumber(gs), tonumber(ns)
  end
  if g ~= Game3.MAP_MAGMA_HIDEOUT_1F_GROUP then return false end
  return n == Game3.MAP_MAGMA_HIDEOUT_1F_NUM
    or n == Game3.MAP_MAGMA_HIDEOUT_B1F_NUM
    or n == Game3.MAP_MAGMA_HIDEOUT_B2F_NUM
end

function Game3:enterMap(map, x, y, ignoreWarp, connected)
  self:ensureMapBase(map)
  if map and map.layoutSwapped then
    self:restoreMapLayout(map)
  end
  self.mapLayoutId = tonumber(map and map.layoutId) or 0
  self.map = map
  self.connectedLayoutCache = nil
  self.playerX = x
  self.playerY = y
  self.walkFromX = x
  self.walkFromY = y
  self.walkCooldown = 0
  self.moveJobs = {}
  self.invisible = nil
  self.cameraDummy = nil
  self.fixedPriority = nil
  self.objSubpriority = nil
  self.rotatingGates = nil
  self.rotatingGateOrients = nil
  self.ignoreWarp = ignoreWarp and true or false
  self.grassRustle = nil
  self.fieldEffects = nil
  self._waitFieldEffect = nil
  self.doorAnim = nil
  self.pendingDoorWarp = nil
  -- Both of these make walkHeld return before it reads the keypad -- the
  -- preventStep equivalents for the placing-decoration avatar mode and the
  -- jump/spin mat tasks. Neither can survive a map change: the ROM's tasks
  -- are destroyed with the field, and a leftover one here freezes the
  -- player on every map afterwards with no way to clear it. The forced
  -- movement latch is per-tile state and goes with them.
  self._decorPlacing = nil
  self.matEffect = nil
  self.forcedMoveLatch = nil
  -- ROM templates keep their extracted xy. ON_TRANSITION may park a
  -- blocker for this visit only; leftover perm from the last visit would
  -- leave the Littleroot twin / Oldale footprints man on the map edge.
  -- A connection keeps the neighbor we were already drawing, including
  -- those perms, so the seam does not respawn the map.
  if not connected then
    self:clearObjectPerms(map)
    -- field_player_avatar.c InitPlayerAvatar: playerObjEventTemplate.elevation
    -- = 0, and InitObjectEventStateFromTemplate resets both current and
    -- previous (draw) elevation from it on every warp. Without this, a
    -- stale previousElevation from the map we just left keeps classifying
    -- the player's draw pass (under/over the BG1 overlay) after warping
    -- into e.g. a cave whose entrance tile is elevation 0.
    self.currentElevation = 0
    self.previousElevation = 0
    -- fieldmap.c InitMap -> InitMapLayoutData: every warp-driven map load
    -- rebuilds the tile grid fresh from the ROM's map data, so a
    -- step-triggered writeMetatile edit (Fallarbor/Lavaridge ash cleared
    -- to grass, Cut grass, a cracked floor hole, the Fortree bridge dip,
    -- a Pacifidlog log) does not outlive the visit that made it. Without
    -- this, ash grass never regrows and the Soot Sack can only ever be
    -- filled once. map.dirtyTiles (populated by writeMetatile) tracks
    -- only cells actually touched that way, so it leaves alone anything
    -- a test or tool pokes into map.grid directly. Sootopolis Gym's
    -- cracked ice is the one tracked exception: it survives via
    -- SPECIAL_SET_SOOTOPOLIS_GYM_CRACKED_ICE re-applying saved bit flags
    -- from this map's onLoad/onResume script, which runs after this
    -- reset.
    if map and map.dirtyTiles then
      for i, orig in pairs(map.dirtyTiles) do
        map.grid[i] = orig
      end
      map.dirtyTiles = nil
    end
  end
  self:clearTempFlags()
  self:setDefaultFlashLevel(map)
  -- overworld.c LoadMap: TryUpdateRandomTrainerRematches before
  -- SetSav1WeatherFromCurrMapHeader. CONTINUE skips like RoamerMove.
  if not self._skipRoamerMove then
    self:tryUpdateRandomTrainerRematches()
  end
  self:doTimeBasedEvents()
  -- overworld.c LoadMap: SetSav1WeatherFromCurrMapHeader, ON_TRANSITION,
  -- then DoCurrentWeather. ON_TRANSITION may setweather (Route 111 sand).
  self:setSav1WeatherFromCurrMapHeader()
  if self:mapNeedsEvilTeamGfx(map) then
    self:setupEvilTeamGfxIds()
  end
  -- secret_base.inc gUnknown_081A2E14 runs on every way into a base and
  -- branches on sub_80BC114 ("is this somebody else's?"): its own-base arm,
  -- EventScript_1A2E38, sets FLAG_DECORATION_1 to hide the owner object.
  -- Without record mixing that arm is the only reachable one, so any entry
  -- into a base interior hides it -- including a save loaded while already
  -- standing inside, which never passes through enterSecretBase. Set before
  -- the map scripts and resetNpcs below, which is what reads the flag.
  if Game3.isSecretBaseMap(map) then
    self.flags = self.flags or {}
    self.flags[Game3.FLAG_DECORATION_1] = true
    -- fieldmap.c InitMapFromSavedGame / overworld.c: the placed
    -- decorations are baked into the freshly loaded grid before any script
    -- runs, so the room already looks right on arrival.
    self:initSecretBaseAppearance(map)
    -- SecretBase_OnWarp is map_script_2 VAR_SECRET_BASE_INITIALIZED, 0 ->
    -- InitDecorations, which is what runs sub_80BBDD0 to un-hide the
    -- DECORPERM_SOLID_MAT object events (the dolls and cushions);
    -- InitDecorations sets the var back to 1 itself. gUnknown_081A2E14
    -- arms it by zeroing the var on the way in, so do the same for every
    -- entry -- otherwise a save loaded while already inside never opens
    -- that gate and the room comes back with its dolls still hidden.
    self:setScriptVar(Game3.VAR_SECRET_BASE_INITIALIZED, 0)
    -- SecretBase_OnResume: setstepcallback 6, which is sub_80BCF1C -- the
    -- glitter / balloon / breakable door / music note mat reactions.
    self.stepCallback = Game3.STEP_CB_SECRET_BASE
  else
    -- fieldmap.c InitMapFromSavedGame also runs
    -- SetOccupiedSecretBaseEntranceMetatiles, so the route you dug on shows
    -- its entrance open when you come back.
    self:setOccupiedSecretBaseEntranceMetatiles(map)
  end
  self:runMapScript("onTransition")
  self:runMapScript("onLoad")
  -- overworld.c LoadMapFromLastWarp: after InitMap, before weather.
  if not self._skipRoamerMove then
    self:updateLocationHistoryForRoamer()
    self:roamerMove()
  end
  self:doCurrentWeather()
  self:runMapScript("onResume")
  self:resetNpcs(map)
  self:updatePlayerZCoord()
  -- tv.c UpdateTVScreensOnMap: default TVs off, then on if a show airs.
  self:updateTVScreensOnMap()
  self:lightExitDoors()
  self:clampCamera()
  -- Connection walks already drew this map as a neighbor. Tile batches
  -- are map-local, so keep them; wiping here is the seam hitch.
  if not connected then
    self:markTilesDirty()
  end
  self:loadTileset()
  self:warmConnectedMaps(map)
  if self.surfing and not self:isUnderwater(map)
      and not Game3.isSurfable(self:behaviorAt(map, x, y)) then
    self.surfing = nil
    self.climbing = nil
    self.diving = nil
  end
  if self.bike and not Game3.canBikeOn(map) then
    self.bike = nil
  end
  self:markFlyVisited(map)
  self:playMapMusic(map)
  self:runMapScriptTable("onWarp", false)
  -- pokeruby runs the dest ON_FRAME after the warp script finishes, not
  -- nested inside warpsilent. Boot cinema also must not run field scripts
  -- or NEW GAME can leave the map mid-scene and fall through to the roster.
  if (self._scriptDepth or 0) > 0 or self.phase == "boot"
      or self._doorArrivalPending then
    self._pendingMapFrame = true
  else
    self:tryMapFrameScript()
    self:tryCoordEvent(x, y)
  end
  -- overworld.c LoadMap (warp + connection): ShowMapNamePopup when
  -- gMapHeader.flags == 1, unless FLAG_HIDE_MAP_NAME_POPUP. Indoor
  -- maps skip ShowMapNamePopup; drop any leftover so a house warp does
  -- not keep the previous route label on screen.
  if not self:showMapNamePopup() and not self:mapWantsNamePopup(map) then
    self:hideMapNamePopup()
  end
end

-- pokeruby map_name_popup.c ShowMapNamePopup / Task_MapNamePopup.
-- MapHeader.flags (show_map_name) is 1 for routes/towns/caves; indoor 0.
function Game3:mapWantsNamePopup(map)
  map = map or self.map
  if not map then return false end
  if Game3.isTruckMap(map) or Game3.isSecretBaseMap(map) then
    return false
  end
  local flags = tonumber(map.flags)
  if flags ~= nil then return flags == 1 end
  -- Caches built before flags was extracted: approximate show_map_name.
  return not Game3.isIndoorFillMap(map)
end

function Game3:mapPopupName()
  local map = self.map
  if not map then return nil end
  if not self:mapWantsNamePopup(map) then return nil end
  local sec = tonumber(map.regionMapSectionId)
  if sec ~= nil then
    local n = Game3RegionMap.name(sec)
    if n and n ~= "" and n ~= "???" then return n end
  end
  local name = map.name or map.id
  if type(name) == "string" and name ~= "" then return name end
  return nil
end

function Game3:showMapNamePopup()
  if self.flags and self.flags[Game3.FLAG_HIDE_MAP_NAME_POPUP] then
    return false
  end
  local name = self:mapPopupName()
  if not name then return false end
  local p = self.mapNamePopup
  if p and p.name ~= name then
    p.phase = 2
    p.pendingName = name
    return true
  end
  self.mapNamePopup = {
    name = name,
    phase = 0,
    offset = 32,
    hold = 0,
  }
  return true
end

function Game3:hideMapNamePopup()
  self.mapNamePopup = nil
end

function Game3:stepMapNamePopup(dt)
  local p = self.mapNamePopup
  if not p then return end
  dt = dt or 0
  local frames = (dt > 0) and (dt * 60) or 1
  if p.phase == 0 then
    p.offset = (p.offset or 32) - 2 * frames
    if p.offset <= 0 then
      p.offset = 0
      p.phase = 1
      p.hold = 0
    end
  elseif p.phase == 1 then
    p.hold = (p.hold or 0) + frames
    if p.hold > 120 then
      p.phase = 2
    end
  elseif p.phase == 2 then
    p.offset = (p.offset or 0) + 2 * frames
    if p.offset > 31 then
      if p.pendingName then
        p.name = p.pendingName
        p.pendingName = nil
        p.phase = 0
        p.offset = 32
        p.hold = 0
      else
        self.mapNamePopup = nil
      end
    end
  end
end

function Game3:drawMapNamePopup()
  local p = self.mapNamePopup
  if not p or not p.name then return end
  local tile = Game3.MENU_TILE
  local x0, y0 = 0, -(p.offset or 0)
  local w, h = 14 * tile, 4 * tile
  self:drawWindow(x0, y0, w, h)
  self:setTextInk(Game3.TEXT_INK)
  local label = tostring(p.name)
  local tw = Game3.textWidth(label, self:font3WidthTable())
  local tx = x0 + math.floor((w - tw) / 2)
  local ty = y0 + 1 * tile + 2
  self:drawText(label, tx, ty)
end

function Game3:load()
  Input:init()
  -- Before applyDisplayOptions, which is what pushes options.touchControls
  -- into the overlay: init() decides whether the platform wants it at all and
  -- loads the art, applyTouchOptions then lays it out (src/core/Game.lua and
  -- Game2.lua do the same pair).
  TouchControls:init()
  self.touchControls = TouchControls
  self.data.header = loadGenerated("data/generated/header.lua") or {}
  self.data.constants = loadGenerated("data/generated/constants.lua") or {}
  self.data.pokemon = loadGenerated("data/generated/pokemon.lua") or {}
  self.data.maps = require("src.import.Gen3MapPack").load() or {}
  local layouts = loadGenerated("data/generated/layouts.lua")
  if type(layouts) == "table" then
    self.data.maps.layouts = layouts.byId or layouts
  end
  self.data.tilesets = loadGenerated("data/generated/tilesets.lua") or {}
  self.data.sprites = loadGenerated("data/generated/sprites.lua") or {}
  self.data.encounters = loadGenerated("data/generated/encounters.lua") or {}
  self.data.moves = loadGenerated("data/generated/moves.lua") or {}
  self.data.trainers = loadGenerated("data/generated/trainers.lua") or {}
  self.data.items = loadGenerated("data/generated/items.lua") or {}
  self.data.font = loadGenerated("data/generated/font.lua") or {}
  self.data.title = loadGenerated("data/generated/title.lua") or {}
  self.data.ui = loadGenerated("data/generated/ui.lua") or {}
  self.data.audio = loadGenerated("data/generated/audio.lua") or {}
  self.data.menus = loadGenerated("data/generated/menus.lua") or {}
  self.data.decorations = loadGenerated("data/generated/decorations.lua") or {}
  self:applyAudioOptions()
  self.named = namedList(self.data.pokemon)
  self.atlasCache = {}
  self.spriteCache = {}
  self.battlePicCache = {}
  self.npcByMap = {}
  self.tileBatches = {}
  self.tileWindows = {}
  self.borderFillCache = nil
  self.quads = {}
  self:resetWorldForNewGame()
  self.gender = nil
  self.phase = "boot"
  self.scroll = 1
  self.walkCooldown = 0
  self.facing = "south"
  self.saveExists = self:hasSave()
  self.playSeconds = 0
  self.customName = nil
  self.options = {
    textSpeed = 2, battleScene = true, battleStyle = "shift", stereo = false,
    windowFrame = 0, zoom = 0, tilt = 0,
    speedOverworld = 1, speedBattle = 1, speedMenu = 1,
  }
  self.viewW, self.viewH = Game3.SCREEN_W, Game3.SCREEN_H
  self:applyDisplayOptions()
  self.trainerId = nil
  self:ensureTrainerId()
  self:resetBoot()
end

function Game3:visualTile()
  local follow = self.cameraDummy
  if follow then
    local x, y = follow.x, follow.y
    if (follow.cooldown or 0) > 0 then
      local dur = follow.walkDuration or Game3.WALK_PERIOD
      local t = 1
      if dur > 0 then t = 1 - follow.cooldown / dur end
      if t < 0 then t = 0 elseif t > 1 then t = 1 end
      x = (follow.fromX or x) + (follow.x - (follow.fromX or x)) * t
      y = (follow.fromY or y) + (follow.y - (follow.fromY or y)) * t
    end
    return x, y
  end
  local x, y = self.playerX, self.playerY
  if (self.walkCooldown or 0) > 0 then
    local t = self:walkProgress()
    x = (self.walkFromX or x) + (self.playerX - (self.walkFromX or x)) * t
    y = (self.walkFromY or y) + (self.playerY - (self.walkFromY or y)) * t
  end
  return x, y
end

function Game3:walkProgress()
  if (self.walkCooldown or 0) <= 0 then return 1 end
  local dur = self.walkDuration or Game3.WALK_PERIOD
  if dur <= 0 then return 1 end
  local t = 1 - self.walkCooldown / dur
  if t < 0 then return 0 end
  if t > 1 then return 1 end
  return t
end

function Game3:worldBounds()
  local map = self.map
  if not map then return 0, 0, 0, 0 end
  local x0, y0 = 0, 0
  local x1 = (map.width or 0) * Game3.TILE
  local y1 = (map.height or 0) * Game3.TILE
  self:eachConnectedMap(map, function(dest, ox, oy)
    local dx0, dy0 = ox * Game3.TILE, oy * Game3.TILE
    local dx1 = dx0 + (dest.width or 0) * Game3.TILE
    local dy1 = dy0 + (dest.height or 0) * Game3.TILE
    if dx0 < x0 then x0 = dx0 end
    if dy0 < y0 then y0 = dy0 end
    if dx1 > x1 then x1 = dx1 end
    if dy1 > y1 then y1 = dy1 end
  end)
  return x0, y0, x1, y1
end

function Game3:windowSize()
  local ok, w, h = pcall(function()
    return GameViewport.dimensions()
  end)
  if not ok then return Game3.SCREEN_W, Game3.SCREEN_H end
  w, h = tonumber(w) or 0, tonumber(h) or 0
  if w < 1 or h < 1 then return Game3.SCREEN_W, Game3.SCREEN_H end
  return w, h
end

function Game3:fitScale()
  local w, h = self:windowSize()
  return math.max(1, math.floor(math.min(w / Game3.SCREEN_W, h / Game3.SCREEN_H)))
end

-- Android / iOS: battles and 240×160 screens use fractional fill scale
-- (Gen 1/2 battleFit "fill") instead of a tiny integer letterbox.
function Game3.isMobile()
  if Game3._forceMobile ~= nil then return Game3._forceMobile end
  local ok, Orientation = pcall(require, "src.core.Orientation")
  if not ok or type(Orientation) ~= "table" then return false end
  return Orientation.isAndroid() or Orientation.isIOS()
end

function Game3:wantsFillScale()
  if Game3.isMobile() then return true end
  local opts = self.options
  if type(opts) ~= "table" then
    local ok, SaveData = pcall(require, "src.core.SaveData")
    if ok and SaveData.loadOptions then
      local got = SaveData.loadOptions()
      if type(got) == "table" then opts = got end
    end
  end
  return type(opts) == "table" and opts.battleFit == "fill"
end

-- Scale a 240×160 surface into a w×h target.  Fixed keeps whole GB pixels;
-- fill uses the Renderer battle "fill" rule (aspect kept, fills vertically).
function Game3:frameScale(w, h)
  w, h = tonumber(w) or Game3.SCREEN_W, tonumber(h) or Game3.SCREEN_H
  if self:wantsFillScale() then
    local scale = math.min(w / Game3.SCREEN_W, h / Game3.SCREEN_H)
    if scale < 1 then scale = 1 end
    local ox = math.floor((w - Game3.SCREEN_W * scale) / 2)
    local oy = math.floor((h - Game3.SCREEN_H * scale) / 2)
    return scale, ox, oy
  end
  local scale = math.max(1, math.floor(math.min(
    w / Game3.SCREEN_W, h / Game3.SCREEN_H)))
  local ox = math.floor((w - Game3.SCREEN_W * scale) / 2)
  local oy = math.floor((h - Game3.SCREEN_H * scale) / 2)
  return scale, ox, oy
end

function Game3:zoomScale()
  return require("src.render.Zoom").scale(self:fitScale())
end

-- Houses / secret bases get the indoor fill zoom. Towns, routes, and
-- caves keep survey zoom so walking a connection does not pop the scale.
-- InsideOfTruck is MAP_TYPE_INDOOR but must stay on survey FIT: room-fit
-- on the 5x5 layout doubles the scale vs Littleroot, so stepping off
-- looked like Brendan shrinking (Sprint C / bugs.txt).
function Game3.isIndoorFillMap(map)
  if Game3.isTruckMap(map) then return false end
  local t = tonumber(map and map.mapType) or 0
  return t == Game3.MAP_TYPE_INDOOR or t == Game3.MAP_TYPE_SECRET_BASE
end

-- On phones, a small indoor map uses room-fit as the FIT baseline so the
-- house is readable. OPTIONS OUT/IN still step from that baseline.
-- Covering the tall axis (math.max) zoomed past the room and ate OUT.
function Game3:overworldZoomScale()
  local w, h = self:windowSize()
  local Zoom = require("src.render.Zoom")
  local S = self:fitScale()
  if Game3.isMobile() and self.phase == "play" and Game3.isIndoorFillMap(self.map) then
    local map = self.map
    local mw = (map.width or 0) * Game3.TILE
    local mh = (map.height or 0) * Game3.TILE
    if mw >= 1 and mh >= 1 then
      local pad = Game3.TILE * 3
      local fitS = math.min(w / (mw + pad), h / (mh + pad))
      if fitS > S then S = fitS end
    end
  end
  return Zoom.scale(S)
end

function Game3:viewSize()
  local vw = tonumber(self.viewW) or Game3.SCREEN_W
  local vh = tonumber(self.viewH) or Game3.SCREEN_H
  if vw < 1 then vw = Game3.SCREEN_W end
  if vh < 1 then vh = Game3.SCREEN_H end
  return vw, vh
end

-- World pixels covered by the window at the current zoom, grown when tilt
-- is on so the perspective capture still fills the screen (World:draw).
function Game3:syncWorldView()
  local Tilt = require("src.render.Tilt")
  local w, h = self:windowSize()
  local s = self:overworldZoomScale()
  local gw, gh = w, h
  if Tilt.active() then
    local g = Tilt.viewGrowth()
    gw, gh = math.ceil(w * g), math.ceil(h * g)
  end
  local vw = math.ceil(gw / s)
  local vh = math.ceil(gh / s)
  if vw % 2 ~= 0 then vw = vw + 1 end
  if vh % 2 ~= 0 then vh = vh + 1 end
  if vw < 2 then vw = 2 end
  if vh < 2 then vh = 2 end
  self.viewW, self.viewH = vw, vh
  self._zoomS = s
  self._tiltGw, self._tiltGh = gw, gh
  return vw, vh, s, gw, gh
end

-- Dialogue / START stay over the map. Full-screen UIs (party, bag, card,
-- minigames) keep the 240×160 letterbox. yesnobox is script_yesno (Std
-- MsgboxYesNo); a bare "yesno" kind is never opened.
Game3.WORLD_FIELD = {
  talk = true,
  menu = true,
  yesno = true,
  script_yesno = true,
  script_choice = true,
  safari_retire = true,
  wait = true,
  move = true,
  delay = true,
  fishing = true,
  trainer_approach = true,
  -- DoDoorWarp / arrival close must stay on the zoomed overworld path.
  -- Dropping to the 240×160 canvas hid the door atlas under a blank
  -- dialogue frame (drawFieldOverlay's default), so open/close never
  -- showed in-game even though doorAnim was advancing.
  door_enter = true,
  door_arrival = true,
  -- ExecuteTruckSequence is a field callback on the same OW view as the
  -- cart (no CB2). Leaving truck_seq off WORLD_FIELD forced the 240×160
  -- letterbox during New Game, then popped to survey zoom when the
  -- cinema ended — Brendan appeared to shrink/grow. Also fell through
  -- drawFieldOverlay to an empty dialogue frame (bugs.txt).
  truck_seq = true,
  link_records = true,
  tower_records = true,
  tower_party = true,
  tm_yesno = true,
  learn_yesno = true,
  learn_stop = true,
  tutor_confirm = true,
  tutor_giveup = true,
  surf_yesno = true,
  -- Wall clock is a CB2 in the ROM. Here it is a HUD over the bedroom so
  -- a held FADE_TO_BLACK cannot bury it on the 240×160 canvas path (that
  -- path blit as an opaque black plate on some GLES / GL drivers).
  clock_set = true,
  clock_yesno = true,
  clock_view = true,
  player_pc = true,
  item_storage = true,
  pc_item_list = true,
  pc_deposit_list = true,
  pc_qty = true,
  pc_mailbox = true,
  pc_mail_actions = true,
  pc_mail_give = true,
}

function Game3:fieldShowsWorld()
  local f = self.field
  if not f then return true end
  -- StorageSystemCreatePrimaryMenu sits on the field; the box screen is
  -- a full 240×160 letterbox like the party/bag.
  if f.kind == "pc" then return (f.mode or "root") == "root" end
  return Game3.WORLD_FIELD[f.kind] == true
end

-- The HUD letterbox is a 240×160 overlay on the zoomed world. Blitting it
-- when nothing is in it left a solid black rectangle in the window centre.
function Game3:playHudActive()
  local f = self.field
  if f then
    local k = f.kind
    if k ~= "move" and k ~= "delay" and k ~= "wait"
        and k ~= "door_enter" and k ~= "door_arrival"
        and k ~= "truck_seq" then
      return true
    end
  end
  if self.orb then return true end
  if self.route128Fade then return true end
  if self.moneyBox or self.coinsBox then return true end
  -- map_name_popup.c Task_MapNamePopup paints on BG0 during free roam.
  -- drawHudLetterbox gates on this; without it the slide-in window is
  -- armed/stepped but never drawn after a connection or warp.
  if self.mapNamePopup then return true end
  return false
end

function Game3:displayGateOK()
  if self.phase ~= "play" or not self.map then return false end
  if self.field then return false end
  if self:scriptDelaying() or self:scriptWaiting() then return false end
  return true
end

-- The GBA keeps the player dead centre and fills everything off the map with
-- the layout's 2x2 border block (fieldmap.c GetBorderBlockAt, which answers
-- for any out-of-bounds coordinate). That is safe on hardware because the
-- screen is 240x160 and MAP_OFFSET -- 7 tiles -- of padding always covers it.
-- This engine draws a wider view, so at a map edge the camera runs past the
-- padded border and into the void fill. The cart never had to make this
-- choice, so there is nothing to copy: stop the camera at the edge of what is
-- actually drawn instead. That is the map plus its connections plus each
-- one's own border pad -- not the map grid, or connected neighbours would be
-- clipped away and the camera would jump at every connection.
function Game3:drawnExtent(map)
  map = map or self.map
  if not map then return nil end
  local placements = self:mapPlacements(map)
  if type(placements) ~= "table" or #placements == 0 then return nil end
  local t = Game3.TILE
  local x0, y0, x1, y1
  for i = 1, #placements do
    local p = placements[i]
    local dest = p and p.map
    if dest then
      local pad = self:borderPad(dest)
      local ax = (p.ox or 0) * t - pad
      local ay = (p.oy or 0) * t - pad
      local bx = ((p.ox or 0) + (dest.width or 0)) * t + pad
      local by = ((p.oy or 0) + (dest.height or 0)) * t + pad
      if not x0 or ax < x0 then x0 = ax end
      if not y0 or ay < y0 then y0 = ay end
      if not x1 or bx > x1 then x1 = bx end
      if not y1 or by > y1 then y1 = by end
    end
  end
  if not x0 then return nil end
  return x0, y0, x1, y1
end

-- One axis of that clamp. When the drawn area is narrower than the view there
-- is nothing to pan to, so centre it and let the player move inside it.
function Game3.clampAxis(cam, lo, hi, span)
  if (hi - lo) <= span then return (lo + hi - span) / 2 end
  if cam < lo then return lo end
  if cam > hi - span then return hi - span end
  return cam
end

-- The follow camera can stop at the edge of what is drawn instead of always
-- centring the player. That is a DELIBERATE DEVIATION -- the cart never
-- clamps; fieldmap.c centres the player and lets GetBorderBlockAt tile the
-- 2x2 border block over anything off-map -- and it is OFF by default at the
-- player's request.
--
-- It was turned off because it kept breaking things that reasonably assume
-- the player is at the screen centre, which is true on hardware and was true
-- here until the clamp landed. The flash hole was one: it was pinned at
-- 120,80 straight out of WriteFlashScanlineEffectBuffer, so in a small cave
-- under a tall drawable the player walked up to 56px away from their own
-- light. Anything else that hardcodes a screen centre has the same hazard.
--
-- The code stays and clampAxis is still tested, so setting cameraClamp on a
-- Game3 turns it back on.
Game3.CAMERA_CLAMP_DEFAULT = false

function Game3:cameraClampEnabled()
  if self.noCameraClamp then return false end
  local v = self.cameraClamp
  if v == nil then return Game3.CAMERA_CLAMP_DEFAULT and true or false end
  return v and true or false
end

function Game3:clampCamera()
  local map = self.map
  if not map then
    self.camX, self.camY = 0, 0
    return
  end
  local vx, vy = self:visualTile()
  local spec = Game3.spriteSpec(self.data and self.data.sprites, self:playerGraphicsId())
  local sw = spec and spec.width or Game3.TILE
  local sh = spec and spec.height or Game3.TILE
  local px, py = Game3.spriteDrawPos(vx, vy, sw, sh, self.levitate or 0)
  local focusX = px + sw / 2
  local focusY = py + sh / 2
  local vw, vh = self:viewSize()
  local camX = focusX - vw / 2
  local camY = focusY - vh / 2
  -- fieldmap.h MAP_OFFSET 7: the GBA camera looks into the border, so the
  -- player stays at screen centre. We draw connected maps and the 2x2
  -- border fill in that extra space, so clamping to this map's grid would
  -- hide them and jump the camera at every connection. Flash and scripted
  -- walks already kept the sprite centred; free roam does too.
  -- Integer SCX/SCY.  Fractional cameras put nearest-neighbour tiles on
  -- half-pixels and the seams flash while walking. Draw uses scale(s) onto
  -- the window, so follow the drawable (gw x gh) not the even-padded view
  -- or zoom leaves the sprite a few pixels off window centre.
  local s = tonumber(self._zoomS)
  local gw, gh = tonumber(self._tiltGw), tonumber(self._tiltGh)
  local spanX, spanY = vw, vh
  if s and s > 0 and gw and gh and gw > 0 and gh > 0 then
    camX = focusX - gw / (2 * s)
    camY = focusY - gh / (2 * s)
    spanX, spanY = gw / s, gh / s
  end
  -- Clamp the follow camera to the drawn area, but add cameraPan afterwards:
  -- a scripted pan is meant to leave the player, and the cart lets it.
  local x0, y0, x1, y1 = self:drawnExtent(map)
  if x0 and self:cameraClampEnabled() then
    camX = Game3.clampAxis(camX, x0, x1, spanX)
    camY = Game3.clampAxis(camY, y0, y1, spanY)
  end
  self.camX, self.camY = Game3.snapPixel(camX + (self.cameraPanX or 0)),
    Game3.snapPixel(camY + (self.cameraPanY or 0))
end

-- FldEff_PokecenterHeal / HallOfFameRecord OBJs are authored in 240×160
-- screen space. Zoomed overworld uses a larger view, so HUD letterbox
-- coords land in the void; map these through the GBA camera instead.
function Game3:gbaCamOrigin()
  local vx, vy = self:visualTile()
  local spec = Game3.spriteSpec(self.data and self.data.sprites, self:playerGraphicsId())
  local sw = spec and spec.width or Game3.TILE
  local sh = spec and spec.height or Game3.TILE
  local px, py = Game3.spriteDrawPos(vx, vy, sw, sh, self.levitate or 0)
  local focusX = px + sw / 2 + (self.cameraPanX or 0)
  local focusY = py + sh / 2 + (self.cameraPanY or 0)
  return focusX - Game3.SCREEN_W / 2, focusY - Game3.SCREEN_H / 2
end

function Game3:gbaScreenToWorld(sx, sy)
  local ox, oy = self:gbaCamOrigin()
  return ox + (tonumber(sx) or 0), oy + (tonumber(sy) or 0)
end

-- fieldmap.c IsCoordInIncomingConnectingMap: dest size + offset is the
-- span on this map. Route 111 lists 113 (offset 0, 20 tall) then 112
-- (offset 20, 60 tall). First-match-by-dir sent every west step to 113.
function Game3.connectionCoordInRange(conn, src, dest, dir, x, y)
  if type(conn) ~= "table" or type(src) ~= "table" or type(dest) ~= "table" then
    return false
  end
  local off = tonumber(conn.offset) or 0
  local coord, srcMax, destMax
  if dir == "north" or dir == "south" then
    coord = tonumber(x) or 0
    srcMax = src.width or 0
    destMax = dest.width or 0
  else
    coord = tonumber(y) or 0
    srcMax = src.height or 0
    destMax = dest.height or 0
  end
  local lo = off
  if lo < 0 then lo = 0 end
  if destMax + off < srcMax then
    srcMax = destMax + off
  end
  return lo <= coord and coord <= srcMax
end

function Game3:connectionDest(map, x, y, dx, dy)
  local dir
  if dy < 0 then dir = "north"
  elseif dy > 0 then dir = "south"
  elseif dx < 0 then dir = "west"
  else dir = "east"
  end
  for i = 1, #(map.connections or {}) do
    local c = map.connections[i]
    if c and c.dir == dir then
      local dest = self:lookupMap(c.mapGroup, c.mapNum)
      if dest and Game3.connectionCoordInRange(c, map, dest, dir, x, y) then
        local ox = c.offset or 0
        if dir == "north" then return dest, x - ox, dest.height - 1 end
        if dir == "south" then return dest, x - ox, 0 end
        if dir == "west" then return dest, dest.width - 1, y - ox end
        return dest, 0, y - ox
      end
    end
  end
  return nil
end

-- pokeruby ApplyCurrentWarp: gLastUsedWarp = gSaveBlock1.location
-- before writing gWarpDestination. Connections do not update it.
function Game3:rememberLastWarp()
  local m = self.map
  if type(m) ~= "table" then
    self.lastUsedWarp = nil
    return
  end
  self.lastUsedWarp = {
    mapGroup = tonumber(m.group) or 0,
    mapNum = tonumber(m.index) or 0,
    mapType = tonumber(m.mapType) or 0,
    x = self.playerX or 0,
    y = self.playerY or 0,
  }
end

function Game3:lastUsedWarpMapType()
  local last = self.lastUsedWarp
  if not last then return 0 end
  if last.mapType ~= nil then return tonumber(last.mapType) or 0 end
  local m = self:lookupMap(last.mapGroup, last.mapNum)
  return (m and tonumber(m.mapType)) or 0
end

function Game3:followWarp(w)
  if not w then return false end
  if Game3.isSecretBaseMap(self.map) then
    return self:exitSecretBase()
  end
  if w.warpId == Game3.WARP_ID_NONE or w.warpId == Game3.WARP_ID_DYNAMIC then
    -- InsideOfTruck: coord script setdynamicwarp, then MAP_DYNAMIC.
    if self:followDynamicWarp() then return true end
    if Game3.isTruckMap(self.map) then
      return self:exitTruck()
    end
    return true
  end
  local dest = self:lookupMap(w.mapGroup, w.mapNum)
  if not dest then return true end
  self:maybeSetDynamicWarpFromDest(dest, w.warpId, w)
  self:maybeSetEscapeWarp(dest, w.x or self.playerX, w.y or self.playerY)
  local dw = dest.warps and dest.warps[w.warpId + 1]
  local x = dw and dw.x or (dest.spawn and dest.spawn.x) or 0
  local y = dw and dw.y or (dest.spawn and dest.spawn.y) or 0
  -- House doors are solid.  RSE walks you one step out (usually south)
  -- after the warp so you are not stuck in the wall.
  local ignore = true
  if not Game3.walkable(dest, x, y) then
    local dirs = { { 0, 1, "south" }, { 0, -1, "north" }, { -1, 0, "west" }, { 1, 0, "east" } }
    for i = 1, #dirs do
      local sx, sy = x + dirs[i][1], y + dirs[i][2]
      if Game3.walkable(dest, sx, sy) then
        x, y, ignore = sx, sy, false
        self.facing = dirs[i][3]
        break
      end
    end
  end
  self:rememberLastWarp()
  -- sub_8080AE4 picks the arrival task from the tile's behaviour, and the
  -- two door tasks walk the player off it with controls LOCKED -- the map's
  -- ON_FRAME table is not consulted until that finishes. Flag it before
  -- enterMap so the frame script waits for the step instead of firing from
  -- the doorway and running the whole scene one tile out of place.
  local db = self:behaviorAt(dest, x, y)
  self._doorArrivalPending = (db == Game3.MB_NON_ANIMATED_DOOR
    or db == Game3.MB_ANIMATED_DOOR) or nil
  self:enterMap(dest, x, y, ignore)
  self:settleAfterWarp()
  self:startDoorArrival()
  self._doorArrivalPending = nil
  return true
end

-- field_fadetransition.c sub_8080F68: SE_WARP_IN then WarpIntoMap.
function Game3:followHideoutWarp(w)
  self:playSe(Game3.SE_WARP_IN)
  return self:followWarp(w)
end

-- Indoor stairs land you on a walkable warp facing the wall you walked
-- into. Hold-through would bump that wall forever. Face a free tile and
-- ignore the d-pad until it is released.
function Game3:settleAfterWarp()
  self.warpSettle = true
  local map = self.map
  if not map then return end
  local x, y = self.playerX, self.playerY
  if not Game3.warpAt(map, x, y) then return end
  local function free(dx, dy)
    local nx, ny = x + dx, y + dy
    return Game3.walkable(map, nx, ny)
      and not Game3.warpAt(map, nx, ny)
      and not self:npcAt(map, nx, ny)
  end
  local fdx, fdy = Game3.deltaFromFacing(self.facing)
  if free(fdx, fdy) then return end
  local dirs = {
    { 0, 1, "south" }, { 1, 0, "east" }, { -1, 0, "west" }, { 0, -1, "north" },
  }
  for i = 1, #dirs do
    if free(dirs[i][1], dirs[i][2]) then
      self.facing = dirs[i][3]
      return
    end
  end
end

-- field_control_avatar.c mapheader_run_first_tag2: standing on an
-- arrow warp and holding the matching dir leaves. Indoor door mats
-- are often two tiles; the dest is a wall / OOB, so this must not
-- wait for a successful step.
-- field_control_avatar.c IsWarpMetatileBehavior. Stepping onto a warp event
-- does not warp you unless the tile itself is a warp tile: a door, a ladder,
-- an escalator, one of the two Lavaridge gym holes, the Aqua hideout warp or
-- the Mt. Pyre hole. Arrow warps have their own direction rule alongside this.
--
-- field_control_avatar.c IsWarpMetatileBehavior. A warp event alone does not
-- warp you: the tile has to be a warp tile too. The engine used to bump-warp on
-- anything outside a short deny-list, which is why the Trick House always gave
-- Puzzle 1 -- its entrance warp sits on plain floor (MB_NORMAL) and is meant to
-- be reached only by the scroll script's own warp, after the switch on
-- VAR_TRICK_HOUSE_ROOMS_COMPLETED picks a room. Walking over the tile skipped
-- the script and took the raw warp every time.
--
-- 125 warp events stop bump-warping under this rule and every one is meant to:
-- they are arrival tiles, script-driven warps, or doors that are still shut.
-- Petalburg Gym looks alarming (36) but its OnLoad setmetatiles each cleared
-- room's doorway to METATILE_PetalburgGym_RoomEntrance, whose behaviour is
-- MB_SOUTH_ARROW_WARP -- so an opened room warps down the arrow path instead.
-- behaviorAt reads the live grid, so that swap is visible here.
function Game3.isWarpBehavior(b)
  b = b or 0
  return b == Game3.MB_ANIMATED_DOOR
      or b == Game3.MB_LADDER
      or b == Game3.MB_UP_ESCALATOR
      or b == Game3.MB_DOWN_ESCALATOR
      or b == Game3.MB_NON_ANIMATED_DOOR
      or b == Game3.MB_WATER_DOOR
      or b == Game3.MB_UNUSED_DEEP_SOUTH_WARP
      or b == Game3.MB_LAVARIDGE_GYM_B1F_WARP
      or b == Game3.MB_LAVARIDGE_GYM_1F_WARP
      or b == Game3.MB_AQUA_HIDEOUT_WARP
      or b == Game3.MB_MT_PYRE_HOLE
end

function Game3:tryArrowWarpOnTile(dx, dy)
  if self.ignoreWarp then return false end
  local map = self.map
  if not map then return false end
  local here = Game3.warpAt(map, self.playerX, self.playerY)
  if not here then return false end
  local b = self:behaviorAt(map, self.playerX, self.playerY)
  if Game3.isArrowWarp(b) and Game3.arrowWarpMatches(b, dx, dy) then
    return self:followWarp(here)
  end
  return false
end

function Game3:tryWalk(dx, dy)
  local map = self.map
  if not map then return false end
  if not self.slopeFaceLock then
    self.facing = Game3.facingFromDelta(dx, dy)
  end
  if self:tryArrowWarpOnTile(dx, dy) then return true end
  local nx = self.playerX + dx
  local ny = self.playerY + dy
  -- Truck door column: prefer coord (setdynamicwarp) then MAP_DYNAMIC.
  -- exitTruck only if this stub map has neither (unit tests).
  if Game3.isTruckMap(map) and nx >= 3 then
    local warp = Game3.warpAt(map, nx, ny)
    if warp and not self.ignoreWarp then
      return self:followWarp(warp)
    end
    if not Game3.coordAt(map, nx, ny) then
      return self:exitTruck()
    end
  end
  if nx < 0 or ny < 0 or nx >= (map.width or 0) or ny >= (map.height or 0) then
    local dest, dx_, dy_ = self:connectionDest(map, self.playerX, self.playerY, dx, dy)
    if dest and self:canStep(dest, dx_, dy_) and not self:npcAt(dest, dx_, dy_) then
      self:maybeSetEscapeWarp(dest, self.playerX, self.playerY)
      self:enterMap(dest, dx_, dy_, false, true)
      -- World:tryConnection: land on the dest tile but lerp from one step
      -- behind so the camera and sprite keep moving. walkFrom can sit
      -- outside this map; the map we left is already drawn as a neighbor.
      self.walkFromX = dx_ - dx
      self.walkFromY = dy_ - dy
      self.playerX, self.playerY = dx_, dy_
      self:updatePlayerZCoord()
      self.walkDuration = self:walkPeriod()
      self.walkCooldown = self.walkDuration
      self:clampCamera()
      self:tickWalkCounters()
      self:beginGrassRustle(dx_, dy_)
      return true
    end
    self:tryAdvanceCyclingRoadCollisions()
    return false
  end
  -- Gen 3 doors sit on collision.  Walking into that tile is the warp.
  -- pokeruby TryStartStepBasedScript runs coord events first, so the
  -- house doormat's GoSeeRoom (intro 4) beats the door warp to town.
  -- Object-event collision also beats bump warps: Mom parks on the east
  -- door tile (9,8) during Littleroot intro (MoveMomToDoor), and warping
  -- before npcAt let the player clip through her into town.
  -- Arrow warps only fire from the matching walk direction. Mt. Pyre
  -- holes (0x0F) land first, then DoFallWarp — not a door-style bump.
  -- Norman gym sliding doors (MB_PETALBURG_GYM_DOOR / sign bg) are
  -- A-press only. Bump-warping them skips "appears locked" and can
  -- land on the paired warp inside a wall.
  local warp = Game3.warpAt(map, nx, ny)
  if warp and not self.ignoreWarp and not self:coordEventWouldRun(nx, ny) then
    local warpNpc = self:npcAt(map, nx, ny)
    if warpNpc and self:actorBlocksAt(warpNpc, self.currentElevation) then
      -- Strength boulders on a warp tile still need the push path below.
      if warpNpc.graphicsId ~= Game3.GFX_PUSHABLE_BOULDER then
        self:tryAdvanceCyclingRoadCollisions()
        return false
      end
    end
    local b = self:behaviorAt(map, nx, ny)
    if Game3.isArrowWarp(b) then
      if Game3.arrowWarpMatches(b, dx, dy) then
        return self:followWarp(warp)
      end
    elseif b == Game3.MB_AQUA_HIDEOUT_WARP then
      return self:followHideoutWarp(warp)
    elseif b == Game3.MB_ANIMATED_DOOR then
      -- field_control_avatar.c TryDoorWarp: only north into a warp door
      -- runs DoDoorWarp (open → walk in → close → fade). Other dirs bump.
      if dy == -1 then
        return self:beginDoorWarp(warp, nx, ny)
      end
      self:tryAdvanceCyclingRoadCollisions()
      return false
    elseif b ~= Game3.MB_MT_PYRE_HOLE
        and b ~= Game3.MB_PETALBURG_GYM_DOOR
        and Game3.isWarpBehavior(b) then
      -- No sign check: TryStartWarpEventScript is only
      -- `warpEventId != -1 && IsWarpMetatileBehavior(behaviour)`. Excluding
      -- any tile carrying a bg sign sealed all four braille chambers shut,
      -- because the braille panel shares its tile with the doorway warp --
      -- open the wall and you still could not walk through it. The locked
      -- doors that guard was written for gate themselves anyway: Petalburg
      -- by its own behaviour above, and the Mossdeep one because its script
      -- swaps in a metatile whose behaviour is not a warp at all.
      return self:followWarp(warp)
    end
  end
  if self:isOwnedSecretBaseTile(map, nx, ny) then
    return self:enterSecretBase()
  end
  local blocker = self:npcAt(map, nx, ny)
  if blocker and not self:actorBlocksAt(blocker, self.currentElevation) then
    blocker = nil
  end
  if blocker then
    if blocker.graphicsId == Game3.GFX_PUSHABLE_BOULDER then
      if not self:strengthOn() or not self:pushBoulder(blocker, dx, dy) then
        self:tryAdvanceCyclingRoadCollisions()
        return false
      end
    else
      self:tryAdvanceCyclingRoadCollisions()
      return false
    end
  end
  -- field_player_avatar.c CheckForObjectEventCollision: ShouldJumpLedge
  -- runs even when GetCollisionAtCoords on the adjacent tile is 0, so
  -- walkable jump lips (e.g. Lilycove beach) hop instead of stepping
  -- onto the lip tile.
  if self:tryLedgeHop(map, dx, dy) then return true end
  if not self:canStep(map, nx, ny) then
    self:tryAdvanceCyclingRoadCollisions()
    return false
  end
  if self:checkRotatingGateCollision(nx, ny, Game3.dirId(self.facing)) then
    self:tryAdvanceCyclingRoadCollisions()
    return false
  end
  -- field_player_avatar.c sub_8058EF0/sub_805A20C: vanilla only ever ends
  -- Surf on a step that lands at elevation 3 (the beach-dismount tile);
  -- Z_OAM_PRIORITY[4] above is "cycling road" -- a bridge deck is a plain
  -- walkable, non-surfable tile at elevation 4, and surfing across/under
  -- one must NOT auto-dismount or every bridge stops the player and forces
  -- a re-surf to continue.
  -- ...and never underwater. PlayerAvatarTransition_Underwater sets
  -- PLAYER_AVATAR_FLAG_UNDERWATER, which REPLACES the surfing flag, so
  -- there is no Surf to dismount from down there. 2799 walkable tiles on
  -- the underwater maps are plain MB_NORMAL, and stepping on one used to
  -- clear the dive state -- after which seaweed became impassable and the
  -- game offered SURF instead.
  if self.surfing and not self:isUnderwater(map)
      and Game3.walkable(map, nx, ny)
      and not Game3.isSurfable(self:behaviorAt(map, nx, ny)) then
    local ni = self:gridIndex(map, nx, ny)
    if ni and Game3.elevationOf(map.grid[ni]) == 3 then
      self.surfing = nil
      self.climbing = nil
      self.diving = nil
    end
  end
  local ox, oy = self.playerX, self.playerY
  self.walkFromX, self.walkFromY = ox, oy
  self.playerX, self.playerY = nx, ny
  self:updatePlayerZCoord()
  self.walkDuration = self:walkPeriod()
  self.walkCooldown = self.walkDuration
  self:clampCamera()
  -- A completed step is no longer the landing tile. House doorways are
  -- two adjacent arrow mats; shuffling onto the other used to keep
  -- ignoreWarp and block the south exit.
  self.ignoreWarp = false
  -- TryStartWarpEventScript: standing on MB_MT_PYRE_HOLE with a warp
  -- event runs EventScript_FallDownHoleMtPyre → special DoFallWarp.
  if not self.ignoreWarp
      and self:behaviorAt(map, nx, ny) == Game3.MB_MT_PYRE_HOLE
      and Game3.warpAt(map, nx, ny) then
    return self:doFallWarp()
  end
  -- TryStartWarpEventScript: MB_AQUA_HIDEOUT_WARP after occupying the pad.
  if not self.ignoreWarp
      and self:behaviorAt(map, nx, ny) == Game3.MB_AQUA_HIDEOUT_WARP
      and Game3.warpAt(map, nx, ny) then
    return self:followHideoutWarp(Game3.warpAt(map, nx, ny))
  end
  self:runStepCallback(ox, oy)
  self:tickWalkCounters()
  self:tryCoordEvent(nx, ny)
  self:beginGrassRustle(nx, ny)
  return true
end

function Game3:gridIndex(map, x, y)
  x = math.floor(tonumber(x) or 0)
  y = math.floor(tonumber(y) or 0)
  local w, h = map and map.width or 0, map and map.height or 0
  if not map or x < 0 or y < 0 or x >= w or y >= h then return nil end
  return y * w + x + 1
end

-- ScrCmd_setmetatile. Recorded in map.dirtyTiles like writeMetatile, so
-- the warp-driven reset in enterMap puts the cell back before ON_LOAD
-- runs again -- which is what InitMapLayoutData gives the ROM for free.
-- Without it an ON_LOAD write outlived the condition that made it: once
-- FLAG_EVIL_TEAM_ESCAPED_IN_SUBMARINE was set, LilycoveCity_OnLoad stopped
-- stamping the Wailmer, but the ones already baked into the shared cached
-- grid stayed there and kept the cove blocked forever.
function Game3:setMetatile(x, y, tile, collision)
  local map = self.map
  local i = self:gridIndex(map, x, y)
  if not i or type(map.grid) ~= "table" then return false end
  local cell = map.grid[i] or 0
  map.dirtyTiles = map.dirtyTiles or {}
  if map.dirtyTiles[i] == nil then map.dirtyTiles[i] = cell end
  local col = (collision and collision ~= 0) and 1024 or 0
  local elev = Game3.elevationBits(cell)
  map.grid[i] = elev + (tonumber(tile) or 0) % 1024 + col
  self:markTilesDirty()
  return true
end

-- fieldmap.c MapGrid*At: x/y include MAP_OFFSET 7. Collision lives in
-- bits 10-11; elevation (12-15) is preserved on write.
function Game3:mapGridGetMetatileId(gx, gy)
  local x = (tonumber(gx) or 0) - Game3.MAP_OFFSET
  local y = (tonumber(gy) or 0) - Game3.MAP_OFFSET
  local i = self:gridIndex(self.map, x, y)
  if not i then return 0 end
  return Game3.metatileOf(self.map.grid[i])
end

function Game3:mapGridGetCollision(gx, gy)
  local x = (tonumber(gx) or 0) - Game3.MAP_OFFSET
  local y = (tonumber(gy) or 0) - Game3.MAP_OFFSET
  local i = self:gridIndex(self.map, x, y)
  if not i then return 1 end
  return Game3.collisionOf(self.map.grid[i])
end

function Game3:mapGridSetMetatileId(gx, gy, metatile)
  local x = (tonumber(gx) or 0) - Game3.MAP_OFFSET
  local y = (tonumber(gy) or 0) - Game3.MAP_OFFSET
  local map = self.map
  local i = self:gridIndex(map, x, y)
  if not i or type(map.grid) ~= "table" then return false end
  local elev = math.floor((map.grid[i] or 0) / 4096) * 4096
  map.grid[i] = elev + ((tonumber(metatile) or 0) % 4096)
  self:markTilesDirty()
  return true
end

function Game3:mauvilleGymSpecial1()
  local which = tonumber(self:varGet(0x8004)) or 0
  local switches = Game3.MAUVILLE_GYM_SWITCHES
  for i = 1, #switches do
    local tile = Game3.MT_MAUVILLE_RAISED
    if i - 1 == which then tile = Game3.MT_MAUVILLE_PRESSED end
    self:mapGridSetMetatileId(switches[i][1], switches[i][2], tile)
  end
end

function Game3:mauvilleGymSpecial2()
  local toggle = Game3.MAUVILLE_GYM_TOGGLE
  local floor = Game3.MT_MAUVILLE_FLOOR
  local greenV1 = Game3.MT_MAUVILLE_GREEN_V1
  local coll = Game3.MAPGRID_COLLISION_MASK
  for y = 12, 23 do
    for x = 7, 15 do
      local id = self:mapGridGetMetatileId(x, y)
      if id == floor then
        if self:mapGridGetMetatileId(x, y - 1) == greenV1 then
          self:mapGridSetMetatileId(x, y, Game3.MT_MAUVILLE_GREEN_V2 + coll)
        else
          self:mapGridSetMetatileId(x, y, Game3.MT_MAUVILLE_RED_V2 + coll)
        end
      else
        local to = toggle[id]
        if to then self:mapGridSetMetatileId(x, y, to) end
      end
    end
  end
end

function Game3:mauvilleGymSpecial3()
  local switches = Game3.MAUVILLE_GYM_SWITCHES
  for i = 1, #switches do
    self:mapGridSetMetatileId(switches[i][1], switches[i][2],
      Game3.MT_MAUVILLE_PRESSED)
  end
  local off = Game3.MAUVILLE_GYM_OFF
  for y = 12, 23 do
    for x = 7, 15 do
      local to = off[self:mapGridGetMetatileId(x, y)]
      if to then self:mapGridSetMetatileId(x, y, to) end
    end
  end
end

function Game3:drawWholeMapView()
  -- field_camera.c copies the grid into BG VRAM. We already draw from
  -- map.grid every frame.
end

function Game3:storePlayerCoordsInVars()
  self:setScriptVar(0x8004, self.playerX or 0)
  self:setScriptVar(0x8005, self.playerY or 0)
end

function Game3:setPetalburgGymDoorTiles(room, metatile)
  room = tonumber(room) or 0
  metatile = tonumber(metatile) or Game3.MT_PETALBURG_DOOR_OPEN
  local doors = Game3.PETALBURG_GYM_DOORS[room]
  if not doors then return end
  local coll = Game3.MAPGRID_COLLISION_MASK
  for i = 1, #doors do
    local x, y = doors[i][1], doors[i][2]
    self:mapGridSetMetatileId(x + Game3.MAP_OFFSET, y + Game3.MAP_OFFSET,
      metatile + coll)
    self:mapGridSetMetatileId(x + Game3.MAP_OFFSET, y + Game3.MAP_OFFSET + 1,
      metatile + 8 + coll)
  end
end

function Game3:petalburgGymOpenDoors()
  self:setPetalburgGymDoorTiles(self:varGet(0x8004), Game3.MT_PETALBURG_DOOR_OPEN)
end

function Game3:setTrickHouseEndRoomFlag(on)
  self:setScriptVar(0x8004, Game3.FLAG_TRICK_HOUSE_END_ROOM)
  self.flags = self.flags or {}
  if on then
    self.flags[Game3.FLAG_TRICK_HOUSE_END_ROOM] = true
  else
    self.flags[Game3.FLAG_TRICK_HOUSE_END_ROOM] = nil
  end
end

function Game3:setHiddenItemFlag()
  local flag = tonumber(self:varGet(0x8004)) or 0
  self.flags = self.flags or {}
  if flag ~= 0 then self.flags[flag] = true end
end

function Game3:playerTrainerIdOnesDigit()
  return (self:ensureTrainerId() % 65536) % 10
end

function Game3:showFieldMessageStringVar4()
  local text = (self.stringVars and self.stringVars[4]) or ""
  if self._scriptSays then
    self:sayScript(text)
  elseif text ~= "" then
    self.field = { kind = "talk", text = text }
  end
end

function Game3:cableCarWarp()
  local down = (tonumber(self:varGet(0x8004)) or 0) ~= 0
  if down then
    self.cableCarDest = {
      group = Game3.MAP_INDOOR_ROUTE112_GROUP,
      num = Game3.MAP_ROUTE112_CABLE_CAR_NUM,
      x = 6, y = 4,
    }
  else
    self.cableCarDest = {
      group = Game3.MAP_INDOOR_ROUTE112_GROUP,
      num = Game3.MAP_MT_CHIMNEY_CABLE_CAR_NUM,
      x = 6, y = 4,
    }
  end
end

function Game3:cableCar()
  -- CableCar: LockPlayerFieldControls, fade, then the ride callback.
  -- unk_0004 is 0x15e going up (0x8004 == 0) and 0x109 going down.
  local d = self.cableCarDest
  if not d then return end
  local down = (tonumber(self:varGet(0x8004)) or 0) ~= 0
  self.field = {
    kind = "cable_car",
    dest = d,
    down = down,
    left = down and Game3.CABLE_CAR_FRAMES_DOWN or Game3.CABLE_CAR_FRAMES_UP,
    t = 0,
  }
  self:beginScriptWait()
  self:playSong(Game3.MUS_CABLE_CAR, true)
end

function Game3:stepCableCar(dt)
  local f = self.field
  if not (f and f.kind == "cable_car") then return end
  local frames = math.floor((dt or 0) * 60 + 0.0001)
  if frames < 1 then frames = 0 end
  f.t = (f.t or 0) + frames
  f.left = (f.left or 0) - frames
  if f.left <= 0 then
    self:finishCableCar()
  end
end

function Game3:finishCableCar()
  local f = self.field
  local d = f and f.dest
  self.field = nil
  self.cableCarDest = nil
  if d then
    self:scriptWarp(d.group, d.num, Game3.WARP_ID_NONE, d.x, d.y)
  end
  self:playMapMusic()
  self:endScriptWait()
end

-- sub_81239E4 / sub_8123AF8 + sub_8123CB8.
function Game3.cableCarScroll(t, down)
  t = math.floor(t or 0)
  if t < 0 then t = 0 end
  local dx = math.floor(Game3.CABLE_CAR_DX * t)
  local dy = math.floor(Game3.CABLE_CAR_DY * t)
  if down then
    return {
      bg3h = Game3.CABLE_CAR_DOWN_BG3_X + t,
      bg3v = Game3.CABLE_CAR_DOWN_BG3_Y + math.floor(t / 2),
      bg1h = math.floor(t / 8),
      bg1v = Game3.CABLE_CAR_DOWN_BG1_Y + math.floor(t / 8),
      carX = Game3.CABLE_CAR_DOWN_CAR_X + dx,
      carY = Game3.CABLE_CAR_DOWN_CAR_Y + dy,
      doorX = Game3.CABLE_CAR_DOWN_DOOR_X + dx,
      doorY = Game3.CABLE_CAR_DOWN_DOOR_Y + dy,
    }
  end
  return {
    bg3h = Game3.CABLE_CAR_UP_BG3_X - t,
    bg3v = Game3.CABLE_CAR_UP_BG3_Y - math.floor(t / 2),
    bg1h = -math.floor(t / 8),
    bg1v = Game3.CABLE_CAR_UP_BG1_Y - math.floor(t / 8),
    carX = Game3.CABLE_CAR_UP_CAR_X - dx,
    carY = Game3.CABLE_CAR_UP_CAR_Y - dy,
    doorX = Game3.CABLE_CAR_UP_DOOR_X - dx,
    doorY = Game3.CABLE_CAR_UP_DOOR_Y - dy,
  }
end

function Game3:drawWrap256(img, hofs, vofs)
  if not img then return end
  local G = love.graphics
  local ox = math.floor(hofs or 0) % 256
  local oy = math.floor(vofs or 0) % 256
  if ox < 0 then ox = ox + 256 end
  if oy < 0 then oy = oy + 256 end
  G.setColor(1, 1, 1, 1)
  for dx = 0, 1 do
    for dy = 0, 1 do
      G.draw(img, dx * 256 - ox, dy * 256 - oy)
    end
  end
end

function Game3:drawCableCar(f)
  local G = love.graphics
  local down = f and f.down
  local mountain = self:cinemaPic("cableCarMountain")
  if not mountain then
    if down then
      G.setColor(0.42, 0.40, 0.38, 1)
    else
      G.setColor(0.45, 0.62, 0.88, 1)
    end
    G.rectangle("fill", 0, 0, Game3.SCREEN_W, Game3.SCREEN_H)
    local t = f and f.t or 0
    local dir = down and 1 or -1
    G.setColor(0.28, 0.38, 0.22, 1)
    for i = 0, 8 do
      local y = ((i * 28 + t * dir) % 224) - 32
      G.rectangle("fill", 0, y, Game3.SCREEN_W, 18)
    end
    G.setColor(0.55, 0.22, 0.18, 1)
    local cx, cy = down and 128 or 176, down and 39 or 73
    G.rectangle("fill", cx - 24, cy - 16, 56, 40)
    G.setColor(0.85, 0.78, 0.55, 1)
    G.rectangle("fill", cx - 14, cy - 8, 20, 14)
    return
  end
  -- BG2 pri 3, BG1 pri 2, OBJ pri 2, BG0 pri 1, BG3 pri 0.
  local s = Game3.cableCarScroll(f and f.t, down)
  G.setColor(1, 1, 1, 1)
  G.draw(mountain, 0, 0)
  self:drawWrap256(self:cinemaPic("cableCarTrees"), s.bg1h, s.bg1v)
  local cord = self:cinemaPic("cableCarCord")
  if cord then
    for i = 0, 8 do
      G.draw(cord, 16 * i + 0x60, 8 * i - 8)
    end
  end
  local car = self:cinemaPic("cableCarCar")
  if car then
    -- affine-double identity: the 64x64 sheet sits at sprite x/y.
    G.draw(car, s.carX, s.carY)
  end
  local door = self:cinemaPic("cableCarDoor")
  if door then
    G.draw(door, s.doorX, s.doorY)
  end
  self:drawWrap256(self:cinemaPic("cableCarChimney"), 0, 0)
  self:drawWrap256(self:cinemaPic("cableCarPylon"), s.bg3h, s.bg3v)
  if down then
    G.setColor(0.45, 0.42, 0.40, 0.22)
    G.rectangle("fill", 0, 0, Game3.SCREEN_W, Game3.SCREEN_H)
  end
end

-- egg_hatch.c sprite at (0x78, 0x4B). Four 32x32 crack frames.
function Game3.gbaSin(index, amp)
  index = math.floor(index or 0) % 256
  if index < 0 then index = index + 256 end
  local v = math.sin(index * math.pi / 128) * 256
  if v >= 0 then v = math.floor(v + 0.5) else v = math.ceil(v - 0.5) end
  if amp == nil then return v end
  local p = v * amp
  if p >= 0 then return math.floor(p / 256) else return math.ceil(p / 256) end
end

-- CB2 pal wait 31, Egg_0 20, Egg_1 freeze 30 + 20, Egg_2 freeze 30 + 38,
-- Egg_3 51, Egg_4 white fade, Egg_5 reveal.
function Game3.eggHatchPose(t)
  t = math.floor(t or 0)
  if t < Game3.EGG_HATCH_WAIT then
    return { frame = 0, x2 = 0, egg = true, mon = false, flash = 0, scale = 1 }
  end
  local s = t - Game3.EGG_HATCH_WAIT
  local data1, frame = 0, 0
  if s < 20 then
    local d0 = s + 1
    data1 = (20 * d0) % 256
    if d0 >= 15 then frame = 1 end
    return { frame = frame, x2 = Game3.gbaSin(data1, 1), egg = true, mon = false,
      flash = 0, scale = 1 }
  end
  s = s - 20
  if s < 30 then
    return { frame = 1, x2 = 0, egg = true, mon = false, flash = 0, scale = 1 }
  end
  s = s - 30
  if s < 20 then
    local d0 = s + 1
    data1 = (20 * d0) % 256
    if d0 >= 15 then frame = 2 else frame = 1 end
    return { frame = frame, x2 = Game3.gbaSin(data1, 2), egg = true, mon = false,
      flash = 0, scale = 1 }
  end
  s = s - 20
  if s < 30 then
    return { frame = 2, x2 = 0, egg = true, mon = false, flash = 0, scale = 1 }
  end
  s = s - 30
  if s < 38 then
    local d0 = s + 1
    data1 = (20 * d0) % 256
    return { frame = 2, x2 = Game3.gbaSin(data1, 2), egg = true, mon = false,
      flash = 0, scale = 1 }
  end
  s = s - 38
  if s < 51 then
    return { frame = 2, x2 = 0, egg = true, mon = false, flash = 0, scale = 1 }
  end
  s = s - 51
  local fade = Game3.EGG_HATCH_FADE
  if s < fade then
    return { frame = 2, x2 = 0, egg = true, mon = false,
      flash = (s + 1) / fade, scale = 1 }
  end
  s = s - fade
  -- SpriteCB_Egg_5: y -= 1 while data[0] <= 9 (10 px). Affine anim 1
  -- is gSpriteAffineAnim_81E7AC0: set 0x28, then +0x12 for 12 frames.
  local lift = s + 1
  if lift > 10 then lift = 10 end
  local scale = (0x28 + s * 0x12) / 0x100
  if scale > 1 then scale = 1 end
  local flash = 1
  if s >= 8 then
    flash = 1 - (s - 8) / fade
    if flash < 0 then flash = 0 end
  end
  return {
    frame = 2, x2 = 0, egg = false, mon = true, flash = flash,
    scale = scale, monY = Game3.EGG_HATCH_MON_Y - lift,
  }
end

-- SpriteCB_EggShard. Spawns at Egg_0/2 cracks and the first 4 Egg_4 frames.
function Game3.eggHatchShards(t)
  t = math.floor(t or 0)
  local wait = Game3.EGG_HATCH_WAIT
  local t1 = wait + 14
  local t2 = wait + 20 + 30 + 20 + 30 + 14
  local t4 = wait + 20 + 30 + 20 + 30 + 38 + 51
  local vel = Game3.EGG_SHARD_VEL
  local out, vid = {}, 0
  local function spawn(at, n)
    if t < at then return end
    for _ = 1, n do
      vid = vid + 1
      local v = vel[vid]
      if v then
        local age = t - at
        local accx, accy, vy = 0, 0, v[2]
        local dead = false
        for _ = 1, age do
          accx = accx + v[1]
          accy = accy + vy
          vy = vy + Game3.EGG_SHARD_GRAVITY
          local y2
          if accy >= 0 then
            y2 = math.floor(accy / 256)
          else
            y2 = math.ceil(accy / 256)
          end
          if y2 > Game3.EGG_SHARD_DIE and vy > 0 then
            dead = true
            break
          end
        end
        if not dead then
          local x2, y2
          if accx >= 0 then
            x2 = math.floor(accx / 256)
          else
            x2 = math.ceil(accx / 256)
          end
          if accy >= 0 then
            y2 = math.floor(accy / 256)
          else
            y2 = math.ceil(accy / 256)
          end
          out[#out + 1] = {
            x = Game3.EGG_SHARD_X + x2,
            y = Game3.EGG_SHARD_Y + y2,
            frame = (vid - 1) % 4,
          }
        end
      end
    end
  end
  spawn(t1, 1)
  spawn(t2, 2)
  spawn(t4, 4)
  spawn(t4 + 1, 4)
  spawn(t4 + 2, 4)
  spawn(t4 + 3, 4)
  return out
end

function Game3:drawEggHatch(f)
  local G = love.graphics
  local egg = self:cinemaPic("eggHatch")
  if not egg then
    G.setColor(0.08, 0.08, 0.10, 1)
    G.rectangle("fill", 0, 0, Game3.SCREEN_W, Game3.SCREEN_H)
    local t = f and f.t or 0
    local wobble = math.sin(t * 0.35) * 6
    local cx, cy = Game3.EGG_HATCH_X, Game3.EGG_HATCH_Y
    G.setColor(0.92, 0.88, 0.78, 1)
    G.rectangle("fill", cx - 12 + wobble, cy - 16, 24, 32)
    G.setColor(0.55, 0.48, 0.38, 1)
    G.rectangle("line", cx - 12 + wobble, cy - 16, 24, 32)
    return
  end
  local bg = self:cinemaPic("hatchBg")
  if bg then
    G.setColor(1, 1, 1, 1)
    G.draw(bg, 0, 0)
  else
    G.setColor(0.08, 0.08, 0.10, 1)
    G.rectangle("fill", 0, 0, Game3.SCREEN_W, Game3.SCREEN_H)
  end
  local pose = Game3.eggHatchPose(f and f.t)
  if pose.egg then
    self:drawSpriteCenter(egg, Game3.EGG_HATCH_X + pose.x2, Game3.EGG_HATCH_Y,
      pose.frame * Game3.EGG_HATCH_SIZE, 0,
      Game3.EGG_HATCH_SIZE, Game3.EGG_HATCH_SIZE)
  end
  if pose.mon then
    local slot = f and f.slot
    local mon = slot and self.party and self.party[slot]
    -- egg_hatch.c GetMonSpritePalStruct(mon)
    local pic = mon and self:battlePic(mon.species, "front", self:isShinyMon(mon))
    if pic then
      self:drawSpriteCenter(pic, Game3.EGG_HATCH_MON_X,
        pose.monY or Game3.EGG_HATCH_MON_Y,
        0, 0, nil, nil, pose.scale or 1)
    end
  end
  local shard = self:cinemaPic("eggShard")
  if shard then
    local bits = Game3.eggHatchShards(f and f.t)
    for i = 1, #bits do
      local b = bits[i]
      self:drawSpriteCenter(shard, b.x, b.y,
        b.frame * Game3.EGG_SHARD_SIZE, 0,
        Game3.EGG_SHARD_SIZE, Game3.EGG_SHARD_SIZE)
    end
  end
  local flash = pose.flash or 0
  if flash > 0 then
    G.setColor(1, 1, 1, flash)
    G.rectangle("fill", 0, 0, Game3.SCREEN_W, Game3.SCREEN_H)
  end
end

-- DoTradeAnim_Cable states. t is vblanks from SetMainCallback2(sub_804BBCC).
function Game3.tradeScenePose(t)
  t = math.floor(t or 0)
  local hofs = Game3.TRADE_BG2HOFS
  if t < Game3.TRADE_SLIDE then
    local left = hofs - t * 3
    if left < 0 then left = 0 end
    return {
      bg = "platform", bg2hofs = left, sent = true, got = false,
      sentX = Game3.TRADE_MON_X - left, sentY = Game3.TRADE_MON_Y,
      line = 1, text = false, waitA = false,
    }
  end
  t = t - Game3.TRADE_SLIDE
  if t < Game3.TRADE_SEND_MSG then
    return {
      bg = "platform", bg2hofs = 0, sent = true, got = false,
      sentX = Game3.TRADE_MON_X, sentY = Game3.TRADE_MON_Y,
      line = 1, text = true, waitA = false,
    }
  end
  t = t - Game3.TRADE_SEND_MSG
  if t < Game3.TRADE_BYE then
    return {
      bg = "platform", bg2hofs = 0, sent = t < 20, got = false,
      sentX = Game3.TRADE_MON_X, sentY = Game3.TRADE_MON_Y,
      ball = true, ballFrame = math.floor(t / 3) % 12,
      ballX = Game3.TRADE_MON_X, ballY = Game3.TRADE_BALL_Y,
      line = 2, text = true, waitA = false,
    }
  end
  t = t - Game3.TRADE_BYE
  if t < Game3.TRADE_GBA_SEND then
    local sxy = 32 + math.floor(t * (128 - 32) / Game3.TRADE_GBA_SEND)
    return {
      bg = "affine", affineScale = sxy / 256, sent = false, got = false,
      line = 2, text = false, waitA = false,
    }
  end
  t = t - Game3.TRADE_GBA_SEND
  if t < Game3.TRADE_CABLE_OUT then
    local vofs = 0x15C - t * 2
    local glowY = 0x50 - t * 2
    return {
      bg = "gba", bg1vofs = vofs, sent = false, got = false,
      glow = true, glowY = glowY, cableEnd = t > 8,
      gbaScreen = t < 16, screenFrame = math.floor(t / 2) % 4,
      line = 2, text = false, waitA = false,
    }
  end
  t = t - Game3.TRADE_CABLE_OUT
  if t < Game3.TRADE_CROSS then
    return {
      bg = "cable", sent = true, got = true,
      sentX = Game3.TRADE_CROSS_SENT_X, sentY = 0xC0 - t * 3,
      gotX = Game3.TRADE_CROSS_GOT_X, gotY = -0x20 + t * 3,
      line = 2, text = false, waitA = false, flash = (t % 12) < 3,
    }
  end
  t = t - Game3.TRADE_CROSS
  if t < Game3.TRADE_CABLE_IN then
    local glowY = -0x14 + t * 3
    return {
      bg = "gba", bg1vofs = 0xA6 + t * 2, sent = false, got = false,
      glow = true, glowY = glowY, cableEnd = true,
      line = 2, text = false, waitA = false,
    }
  end
  t = t - Game3.TRADE_CABLE_IN
  if t < Game3.TRADE_GBA_RECV then
    local sxy = 128 - math.floor(t * (128 - 32) / Game3.TRADE_GBA_RECV)
    return {
      bg = "affine", affineScale = sxy / 256, sent = false, got = false,
      line = 2, text = false, waitA = false,
    }
  end
  t = t - Game3.TRADE_GBA_RECV
  if t < Game3.TRADE_NEW_MON then
    return {
      bg = "platform", bg2hofs = 0, sent = false, got = t > 8,
      gotX = Game3.TRADE_MON_X, gotY = Game3.TRADE_MON_Y,
      ball = t <= 24, ballFrame = math.floor(t / 3) % 12,
      ballX = Game3.TRADE_MON_X, ballY = 0x54,
      line = 2, text = false, waitA = false,
    }
  end
  t = t - Game3.TRADE_NEW_MON
  if t < Game3.TRADE_SENT_MSG then
    return {
      bg = "platform", bg2hofs = 0, sent = false, got = true,
      gotX = Game3.TRADE_MON_X, gotY = Game3.TRADE_MON_Y,
      line = 3, text = true, waitA = false,
    }
  end
  t = t - Game3.TRADE_SENT_MSG
  return {
    bg = "platform", bg2hofs = 0, sent = false, got = true,
    gotX = Game3.TRADE_MON_X, gotY = Game3.TRADE_MON_Y,
    line = 4, text = true, waitA = t >= Game3.TRADE_CARE_WAIT,
  }
end

function Game3:drawTradeScene(f)
  local G = love.graphics
  local pose = Game3.tradeScenePose(f and f.t)
  local bg
  if pose.bg == "cable" then
    bg = self:cinemaPic("tradeCable")
  elseif pose.bg == "affine" then
    bg = self:cinemaPic("tradeAffine") or self:cinemaPic("tradeGba")
  elseif pose.bg == "gba" then
    bg = self:cinemaPic("tradeGba")
  else
    bg = self:cinemaPic("hatchBg") or self:cinemaPic("tradeGba")
  end
  G.setColor(0.08, 0.08, 0.10, 1)
  G.rectangle("fill", 0, 0, Game3.SCREEN_W, Game3.SCREEN_H)
  if bg then
    G.setColor(1, 1, 1, 1)
    if pose.bg == "affine" then
      local scale = pose.affineScale or 0.5
      local iw, ih = bg:getDimensions()
      G.draw(bg, 120, 80, 0, scale, scale, iw / 2, ih / 2)
    elseif pose.bg == "gba" then
      self:drawWrap256(bg, 0, pose.bg1vofs or 0)
    else
      self:drawWrap256(bg, pose.bg2hofs or 0, 0)
    end
  end
  local function drawMon(species, x, y, shiny)
    if not species or not x then return end
    -- trade.c GetMonSpritePalStruct(pokemon)
    local pic = self:battlePic(species, "front", shiny and true or false)
    if pic then
      self:drawSpriteCenter(pic, x, y)
    end
  end
  if pose.sent then
    drawMon(f and f.sentSpecies, pose.sentX, pose.sentY, f and f.sentShiny)
  end
  if pose.got then
    drawMon(f and f.gotSpecies, pose.gotX, pose.gotY, f and f.gotShiny)
  end
  if pose.ball then
    local ball = self:cinemaPic("tradeBall")
    if ball then
      self:drawSpriteCenter(ball, pose.ballX, pose.ballY,
        (pose.ballFrame or 0) * Game3.TRADE_BALL_SIZE, 0,
        Game3.TRADE_BALL_SIZE, Game3.TRADE_BALL_SIZE)
    end
  end
  if pose.gbaScreen then
    local scr = self:cinemaPic("tradeGbaScreen")
    if scr then
      self:drawSpriteCenter(scr, Game3.TRADE_GLOW_X, 0x50,
        (pose.screenFrame or 0) * Game3.TRADE_GBA_SCREEN_W, 0,
        Game3.TRADE_GBA_SCREEN_W, Game3.TRADE_GBA_SCREEN_H)
    end
  end
  if pose.glow then
    local g1 = self:cinemaPic("tradeGlow1")
    local g2 = self:cinemaPic("tradeGlow2")
    local gy = pose.glowY or 0x50
    if g1 then
      self:drawSpriteCenter(g1, Game3.TRADE_GLOW_X, gy)
    end
    if g2 then
      self:drawSpriteCenter(g2, Game3.TRADE_GLOW_X, gy, 0, 0,
        Game3.TRADE_GLOW2_W, Game3.TRADE_GLOW2_H)
    end
  end
  if pose.cableEnd then
    local cord = self:cinemaPic("tradeCableEnd")
    if cord then
      self:drawSpriteCenter(cord, Game3.TRADE_GLOW_X, 0x41)
    end
  end
  if (pose.flash or 0) > 0 then
    G.setColor(1, 1, 1, 0.55)
    G.rectangle("fill", 0, 0, Game3.SCREEN_W, Game3.SCREEN_H)
  end
end

-- TradeEvolutionScene: platform + front pic at (120, 64). Sparkle
-- tasks stay colored rects (no Nintendo gfx in git).
function Game3:drawTradeEvolution(f)
  local G = love.graphics
  local bg = self:cinemaPic("hatchBg") or self:cinemaPic("tradeGba")
  G.setColor(0.08, 0.08, 0.10, 1)
  G.rectangle("fill", 0, 0, Game3.SCREEN_W, Game3.SCREEN_H)
  if bg then
    G.setColor(1, 1, 1, 1)
    self:drawWrap256(bg, 0, 0)
  end
  local evo = self.evolve
  local scale, flash, species = self:evolveDraw()
  if not species then
    species = evo and evo.mon and evo.mon.species
  end
  -- evolution_scene.c GetMonSpritePalStructFromOtIdPersonality (same OT/PID)
  local shiny = evo and evo.mon and self:isShinyMon(evo.mon)
  local pic = species and self:battlePic(species, "front", shiny)
  local cx, cy = Game3.TRADE_EVO_X, Game3.TRADE_EVO_Y
  if pic then
    self:drawSpriteCenter(pic, cx, cy, nil, nil, nil, nil, scale)
    if flash then
      G.setColor(1, 1, 1, 0.45)
      G.rectangle("fill", cx - 32, cy - 32, 64, 64)
    end
  else
    local w = math.floor(48 * (scale or 1))
    G.setColor(0.25, 0.18, 0.22, flash and 0.45 or 1)
    G.rectangle("fill", cx - w / 2, cy - w / 2, w, w)
  end
  if evo and evo.stage == "anim" then
    local t = evo.t or 0
    for i = 0, 5 do
      local a = t * 6 + i * (math.pi / 3)
      local r = 18 + 10 * math.sin(t * 10 + i)
      local sx = cx + math.cos(a) * r
      local sy = cy + math.sin(a) * r
      local pulse = 0.4 + 0.6 * (0.5 + 0.5 * math.sin(t * 14 + i))
      G.setColor(1, 1, 0.7, pulse)
      G.rectangle("fill", sx - 1, sy - 1, 3, 3)
    end
  end
  self:drawDialogueFrame()
  self:drawDialogue(f)
end

-- field_control_avatar.c SetCableClubWarp: dest is the warp under
-- the player's feet (after the receptionist walks them through the
-- door). C returns 0. Do not beginScriptWait.
function Game3:setCableClubWarp()
  local w = Game3.warpAt(self.map, self.playerX, self.playerY)
  if w then
    self.warpDestination = {
      mapGroup = w.mapGroup or 0,
      mapNum = w.mapNum or 0,
      warpId = w.warpId or Game3.WARP_ID_NONE,
      x = w.x or 0,
      y = w.y or 0,
    }
  end
  return 0
end

-- DoCableClubWarp / sub_80810DC: SE_EXIT, fade, then WarpIntoMap.
-- WaitCableClubWarp waits !PaletteFadeActive. Scripts follow with waitstate.
function Game3:doCableClubWarp()
  self:playSe(Game3.SE_EXIT)
  self.cableClubWarpLeft = Game3.FADE_FRAMES
  self:beginScriptWait()
end

-- cable_club.c sub_80839A4: LoadPlayerParty / copy saved warp. No wait.
function Game3:sub80839A4()
end

-- sub_80833EC: no GBA partner. RESULT 0 falls into the Colosseum
-- warp (1A4166). 5 is the receptionist goodbye. Do not beginScriptWait.
function Game3:cableClubNoLink()
  -- sub_80833EC / friends: no GBA SIO partner. RESULT 5 takes the
  -- receptionist goodbye branch (Colosseum / Trade Center / Record Mix).
  -- Full GBA multiplayer is out of scope; never beginScriptWait here.
  self.isLinkContest = false
  self:setScriptVar(Gen3Script.VAR_RESULT, Game3.CABLE_CLUB_NO_LINK)
  return Game3.CABLE_CLUB_NO_LINK
end

-- Optional explanatory banner when a PC-side link menu is opened without
-- a partner. Scripts that already print goodbye text do not call this.
function Game3:cableClubNoLinkExplain()
  self:cableClubNoLink()
  if self.sayScript then
    self:sayScript(Game3.CABLE_CLUB_NO_LINK_MSG)
  end
  return Game3.CABLE_CLUB_NO_LINK
end

function Game3:ensureLinkBattleRecords()
  local rows = self.linkBattleRecords
  if type(rows) == "table" then return rows end
  rows = {}
  local i = 1
  while i <= Game3.LINK_BATTLE_RECORD_SLOTS do
    rows[i] = { name = "", wins = 0, losses = 0, draws = 0 }
    i = i + 1
  end
  self.linkBattleRecords = rows
  return rows
end

-- battle_records.c ShowLinkBattleRecords. Script is special +
-- waitbuttonpress (still a decoder nop). Do not beginScriptWait.
function Game3:showLinkBattleRecords()
  self:ensureLinkBattleRecords()
  self.field = { kind = "link_records" }
end

function Game3:towerStreakLabel(level)
  local t = self:ensureBattleTower()
  local state = (t.var4AE and t.var4AE[level]) or 0
  if state == 2 or state == 3 or state == 6 then return "Current" end
  return "Prev"
end

-- battle_records.c ShowBattleTowerRecords. Same waitbuttonpress script.
function Game3:showBattleTowerRecords()
  self:ensureBattleTower()
  self.field = { kind = "tower_records" }
end

function Game3:drawLinkBattleRecords()
  local G = love.graphics
  G.setColor(0.10, 0.10, 0.12, 1)
  self:drawText("BATTLE RESULTS", 10, 8)
  self:drawText(("TOTAL  %dW  %dL  %dD"):format(
    self:getGameStat(Game3.GAME_STAT_LINK_BATTLE_WINS),
    self:getGameStat(Game3.GAME_STAT_LINK_BATTLE_LOSSES),
    self:getGameStat(Game3.GAME_STAT_LINK_BATTLE_DRAWS)), 10, 22)
  self:drawText("W/L/D", 80, 36)
  local rows = self:ensureLinkBattleRecords()
  local i = 1
  while i <= Game3.LINK_BATTLE_RECORD_SLOTS do
    local rec = rows[i] or {}
    local y = 46 + (i - 1) * 12
    local wins = tonumber(rec.wins) or 0
    local losses = tonumber(rec.losses) or 0
    local draws = tonumber(rec.draws) or 0
    if wins == 0 and losses == 0 and draws == 0 then
      self:drawText("-------   ----  ----  ----", 10, y)
    else
      self:drawText(("%s  %d  %d  %d"):format(
        rec.name or "", wins, losses, draws), 10, y)
    end
    i = i + 1
  end
  self:drawText("A/B close", 8, 148)
end

function Game3:drawBattleTowerRecords()
  local G = love.graphics
  local t = self:ensureBattleTower()
  local function streak(n)
    n = tonumber(n) or 0
    if n > 9999 then n = 9999 end
    return n
  end
  G.setColor(0.10, 0.10, 0.12, 1)
  self:drawText("BATTLE TOWER RESULTS", 10, 8)
  self:drawText("Lv. 50", 10, 28)
  self:drawText(("%s  %d Win Streak"):format(
    self:towerStreakLabel(0), streak(t.currentWinStreaks[0])), 18, 40)
  self:drawText(("Record  %d Win Streak"):format(
    streak(t.recordWinStreaks[0])), 18, 52)
  self:drawText("Lv. 100", 10, 76)
  self:drawText(("%s  %d Win Streak"):format(
    self:towerStreakLabel(1), streak(t.currentWinStreaks[1])), 18, 88)
  self:drawText(("Record  %d Win Streak"):format(
    streak(t.recordWinStreaks[1])), 18, 100)
  self:drawText("A/B close", 8, 148)
end

-- battle_tower.c sub_8134548. ON_FRAME VAR_TEMP_0==0 walks var_4AE for
-- both level modes and sets VAR_TEMP_0 so lobby scripts resume the right
-- branch (award / continue / lose / idle). Do not beginScriptWait.
function Game3:initBattleTowerOnFrame()
  local t = self:ensureBattleTower()
  local var1 = 0
  for levelType = 0, 1 do
    local state = (t.var4AE and t.var4AE[levelType]) or 0
    if state == 0 then
      self:resetBattleTowerStreak(levelType)
      if var1 == 0 then
        self:setScriptVar(Game3.VAR_TEMP_0, Game3.BATTLE_TOWER_IDLE)
      end
    elseif state == 1 then
      self:resetBattleTowerStreak(levelType)
      self:setScriptVar(Game3.VAR_TEMP_0, 1)
      var1 = var1 + 1
    elseif state == 4 then
      self:setScriptVar(Game3.VAR_TEMP_0, 2)
      var1 = var1 + 1
    elseif state == 5 then
      self:setScriptVar(Game3.VAR_TEMP_0, 3)
      var1 = var1 + 1
    elseif state == 2 then
      self:setScriptVar(Game3.VAR_TEMP_0, 4)
      var1 = var1 + 1
    elseif state == 3 or state == 6 then
      -- keep prior VAR_TEMP_0
    else
      self:resetBattleTowerStreak(levelType)
      if var1 == 0 then
        self:setScriptVar(Game3.VAR_TEMP_0, Game3.BATTLE_TOWER_IDLE)
      end
    end
  end
  local a = (t.var4AE and t.var4AE[0]) or 0
  local b = (t.var4AE and t.var4AE[1]) or 0
  if (a == 3 or a == 6) and (b == 3 or b == 6) then
    self:setScriptVar(Game3.VAR_TEMP_0, Game3.BATTLE_TOWER_IDLE)
  end
  return 0
end

function Game3:battleTowerData()
  if not Game3._battleTowerData then
    Game3._battleTowerData = require("src.data.battle_tower")
  end
  return Game3._battleTowerData
end

function Game3:ensureBattleTower()
  local t = self.battleTower
  if type(t) ~= "table" then
    t = {
      levelType = 0,
      var4AE = { [0] = 0, [1] = 0 },
      curChallengeBattleNum = { [0] = 1, [1] = 1 },
      curStreakChallengesNum = { [0] = 1, [1] = 1 },
      trainerId = 0,
      unk554 = 0,
      selectedPartyMons = { 0, 0, 0 },
      currentWinStreaks = { [0] = 0, [1] = 0 },
      recordWinStreaks = { [0] = 0, [1] = 0 },
      battledTrainerIds = { 0, 0, 0, 0, 0, 0, 0 },
      bestStreak = 0,
      prizeItem = 0,
      battleOutcome = 0,
      totalWins = 0,
      lastStreakLevelType = 0,
      records = {},
      playerRecord = nil,
    }
    self.battleTower = t
  end
  t.var4AE = t.var4AE or { [0] = 0, [1] = 0 }
  t.curChallengeBattleNum = t.curChallengeBattleNum or { [0] = 1, [1] = 1 }
  t.curStreakChallengesNum = t.curStreakChallengesNum or { [0] = 1, [1] = 1 }
  t.currentWinStreaks = t.currentWinStreaks or { [0] = 0, [1] = 0 }
  t.recordWinStreaks = t.recordWinStreaks or { [0] = 0, [1] = 0 }
  t.battledTrainerIds = t.battledTrainerIds or { 0, 0, 0, 0, 0, 0, 0 }
  t.selectedPartyMons = t.selectedPartyMons or { 0, 0, 0 }
  t.records = t.records or {}
  return t
end

-- battle_tower.c ResetBattleTowerStreak.
function Game3:resetBattleTowerStreak(levelType)
  local t = self:ensureBattleTower()
  levelType = tonumber(levelType)
  if levelType == nil then levelType = t.levelType or 0 end
  t.var4AE = t.var4AE or {}
  t.curChallengeBattleNum = t.curChallengeBattleNum or {}
  t.curStreakChallengesNum = t.curStreakChallengesNum or {}
  t.var4AE[levelType] = 0
  t.curChallengeBattleNum[levelType] = 1
  t.curStreakChallengesNum[levelType] = 1
end

-- 0x8004 selects the field. Case 0 is var_4AE[levelType]; 0 is a
-- valid idle streak. Must return. Do not beginScriptWait.
function Game3:battleTowerUtil()
  local t = self:ensureBattleTower()
  local which = self:varGet(0x8004)
  local level = t.levelType or 0
  local n = 0
  if which == 0 then
    n = (t.var4AE and t.var4AE[level]) or 0
  elseif which == 1 then
    n = level
  elseif which == 2 then
    n = (t.curChallengeBattleNum and t.curChallengeBattleNum[level]) or 0
  elseif which == 3 then
    n = (t.curStreakChallengesNum and t.curStreakChallengesNum[level]) or 0
  elseif which == 4 then
    n = t.trainerId or 0
  elseif which == 8 then
    n = t.unk554 or 0
  elseif which == 9 then
    n = self:getCurrentBattleTowerWinStreak(level)
  elseif which == 10 then
    self.gameStats = self.gameStats or {}
    self.gameStats[Game3.GAME_STAT_BATTLE_TOWER_BEST_STREAK] = t.bestStreak or 0
  elseif which == 11 then
    self:resetBattleTowerStreak(level)
  elseif which == 12 then
    if t.savedVar4AE ~= nil then
      t.var4AE = t.var4AE or {}
      t.var4AE[level] = t.savedVar4AE
    end
  elseif which == 13 then
    t.currentWinStreaks = t.currentWinStreaks or {}
    t.currentWinStreaks[level] = self:getCurrentBattleTowerWinStreak(level)
  elseif which == 14 then
    t.lastStreakLevelType = level
  end
  self:setScriptVar(Gen3Script.VAR_RESULT, n)
  return n
end

function Game3:saveCurrentBattleTowerWinStreak()
  local t = self:ensureBattleTower()
  local level = t.levelType or 0
  local streak = self:getCurrentBattleTowerWinStreak(level)
  t.recordWinStreaks = t.recordWinStreaks or { [0] = 0, [1] = 0 }
  if (t.recordWinStreaks[level] or 0) < streak then
    t.recordWinStreaks[level] = streak
  end
  local best = t.recordWinStreaks[0] or 0
  if (t.recordWinStreaks[1] or 0) > best then best = t.recordWinStreaks[1] end
  if best > 9999 then best = 9999 end
  t.bestStreak = best
  self.gameStats = self.gameStats or {}
  self.gameStats[Game3.GAME_STAT_BATTLE_TOWER_BEST_STREAK] = best
end

function Game3:setBattleTowerProperty()
  local t = self:ensureBattleTower()
  local which = self:varGet(0x8004)
  local val = self:varGet(0x8005)
  local level = t.levelType or 0
  if which == 0 then
    -- ROM also snapshots prior state into gBattleStruct->unk160FB.
    t.savedVar4AE = (t.var4AE and t.var4AE[level]) or 0
    t.var4AE = t.var4AE or {}
    t.var4AE[level] = val
  elseif which == 1 then
    t.levelType = val
  elseif which == 2 then
    t.curChallengeBattleNum = t.curChallengeBattleNum or {}
    t.curChallengeBattleNum[level] = val
  elseif which == 3 then
    t.curStreakChallengesNum = t.curStreakChallengesNum or {}
    t.curStreakChallengesNum[level] = val
  elseif which == 4 then
    t.trainerId = val
  elseif which == 5 then
    local order = self.selectedOrderFromParty or t.selectedPartyMons or { 0, 0, 0 }
    t.selectedPartyMons = {
      tonumber(order[1]) or 0,
      tonumber(order[2]) or 0,
      tonumber(order[3]) or 0,
    }
  elseif which == 6 then
    -- Win one battle in the current 7-set: bump battle num + streak.
    if (t.trainerId or 0) == Game3.BATTLE_TOWER_EREADER_TRAINER_ID then
      -- ClearEReaderTrainer: leave empty ereader slot.
      t.ereaderTrainer = nil
    end
    t.totalWins = (t.totalWins or 0) + 1
    if t.totalWins > 9999 then t.totalWins = 9999 end
    t.curChallengeBattleNum = t.curChallengeBattleNum or {}
    local nextBattle = ((t.curChallengeBattleNum[level] or 1) + 1)
    t.curChallengeBattleNum[level] = nextBattle
    self:saveCurrentBattleTowerWinStreak()
    self:setScriptVar(Gen3Script.VAR_RESULT, nextBattle)
    self:setStringVar(1, tostring(nextBattle))
  elseif which == 7 then
    t.curStreakChallengesNum = t.curStreakChallengesNum or {}
    local sets = t.curStreakChallengesNum[level] or 1
    if sets < 1430 then sets = sets + 1 end
    t.curStreakChallengesNum[level] = sets
    self:saveCurrentBattleTowerWinStreak()
    self:setScriptVar(Gen3Script.VAR_RESULT, sets)
  elseif which == 8 then
    t.unk554 = val
  elseif which == 10 then
    self.gameStats = self.gameStats or {}
    self.gameStats[Game3.GAME_STAT_BATTLE_TOWER_BEST_STREAK] = t.bestStreak or 0
  elseif which == 11 then
    if (t.var4AE and t.var4AE[level]) ~= 3 then
      self:resetBattleTowerStreak(level)
    end
  elseif which == 12 then
    if t.savedVar4AE ~= nil then
      t.var4AE = t.var4AE or {}
      t.var4AE[level] = t.savedVar4AE
    end
  elseif which == 13 then
    t.currentWinStreaks = t.currentWinStreaks or {}
    t.currentWinStreaks[level] = self:getCurrentBattleTowerWinStreak(level)
  elseif which == 14 then
    t.lastStreakLevelType = level
  end
end

-- CheckMonBattleTowerBanlist / CheckPartyBattleTowerBanlist.
-- 0x8004 = 1 means too few valid mons; 0 allows. VAR_RESULT is the
-- level mode (0 Lv50 / 1 Lv100) from the lobby multichoice.
function Game3:monBattleTowerEligible(mon, levelType, seenSpecies, seenItems)
  if not mon then return false end
  local species = self:partyMonSpecies2(mon)
  if species == 0 or species == Game3.SPECIES_EGG then return false end
  if Game3.BATTLE_TOWER_BANNED[species] then return false end
  levelType = tonumber(levelType) or 0
  if levelType == 0 and (tonumber(mon.level) or 1) > 50 then return false end
  seenSpecies = seenSpecies or {}
  seenItems = seenItems or {}
  for i = 1, #seenSpecies do
    if seenSpecies[i] == species then return false end
  end
  local held = tonumber(mon.item) or 0
  if held ~= 0 then
    for i = 1, #seenItems do
      if seenItems[i] == held then return false end
    end
  end
  return true
end

function Game3:checkPartyBattleTowerBanlist()
  local levelType = self:varGet(Gen3Script.VAR_RESULT) or 0
  local party = self.party or {}
  local validSpecies, validItems = {}, {}
  local counter = 0
  for i = 1, #party do
    local mon = party[i]
    if self:monBattleTowerEligible(mon, levelType, validSpecies, validItems) then
      counter = counter + 1
      validSpecies[counter] = self:partyMonSpecies2(mon)
      validItems[counter] = tonumber(mon.item) or 0
    end
  end
  if counter < 3 then
    self:setScriptVar(0x8004, 1)
    return 1
  end
  self:setScriptVar(0x8004, 0)
  local t = self:ensureBattleTower()
  t.levelType = levelType
  return 0
end

-- ChooseBattleTowerPlayerParty waitstate (contest_util.c).
-- RESULT 0 cancel / 1 confirm after three 1-based party slots.
function Game3:chooseBattleTowerPlayerParty()
  self.selectedOrderFromParty = { 0, 0, 0 }
  self:beginScriptWait()
  self.field = {
    kind = "tower_party",
    cursor = 0,
    order = { 0, 0, 0 },
    scripted = true,
  }
  return nil
end

function Game3:towerPartySelectedCount(order)
  order = order or {}
  local n = 0
  for i = 1, 3 do
    if (order[i] or 0) ~= 0 then n = n + 1 end
  end
  return n
end

function Game3:towerPartySlotIndex(order, partyIndex)
  order = order or {}
  partyIndex = tonumber(partyIndex) or 0
  for i = 1, 3 do
    if (order[i] or 0) == partyIndex then return i end
  end
  return 0
end

function Game3:toggleTowerPartySlot(partyIndex)
  local f = self.field
  if not f or f.kind ~= "tower_party" then return end
  partyIndex = tonumber(partyIndex) or 0
  if partyIndex < 1 then return end
  local order = f.order or { 0, 0, 0 }
  f.order = order
  local mon = self.party and self.party[partyIndex]
  local slot = self:towerPartySlotIndex(order, partyIndex)
  if slot > 0 then
    for i = slot, 2 do
      order[i] = order[i + 1] or 0
    end
    order[3] = 0
    return
  end
  if self:towerPartySelectedCount(order) >= 3 then return end
  local t = self:ensureBattleTower()
  local levelType = t.levelType or 0
  local seenSpecies, seenItems = {}, {}
  for i = 1, 3 do
    local idx = order[i] or 0
    if idx > 0 and self.party and self.party[idx] then
      local m = self.party[idx]
      seenSpecies[#seenSpecies + 1] = self:partyMonSpecies2(m)
      seenItems[#seenItems + 1] = tonumber(m.item) or 0
    end
  end
  if not self:monBattleTowerEligible(mon, levelType, seenSpecies, seenItems) then
    return
  end
  for i = 1, 3 do
    if (order[i] or 0) == 0 then
      order[i] = partyIndex
      return
    end
  end
end

function Game3:confirmTowerParty()
  local f = self.field
  if not f or f.kind ~= "tower_party" then return false end
  local order = f.order or { 0, 0, 0 }
  if self:towerPartySelectedCount(order) < 3 then return false end
  self.selectedOrderFromParty = { order[1], order[2], order[3] }
  local t = self:ensureBattleTower()
  t.selectedPartyMons = { order[1], order[2], order[3] }
  self:reducePlayerPartyToThree(order)
  -- After reduction the tower team occupies slots 1..3; keep indices
  -- aligned so AwardBattleTowerRibbons / records hit those mons.
  t.selectedPartyMons = { 1, 2, 3 }
  self.selectedOrderFromParty = { 1, 2, 3 }
  self.field = nil
  self:setScriptVar(Gen3Script.VAR_RESULT, 1)
  self:endScriptWait()
  return true
end

function Game3:cancelTowerParty()
  local f = self.field
  if not f or f.kind ~= "tower_party" then return end
  self.selectedOrderFromParty = { 0, 0, 0 }
  self.field = nil
  self:setScriptVar(Gen3Script.VAR_RESULT, 0)
  self:endScriptWait()
end

function Game3:reducePlayerPartyToThree(order)
  order = order or self.selectedOrderFromParty
      or (self.battleTower and self.battleTower.selectedPartyMons)
  if type(order) ~= "table" then return false end
  local party = self.party or {}
  local nextParty = {}
  for i = 1, 3 do
    local idx = tonumber(order[i]) or 0
    if idx > 0 and party[idx] then
      nextParty[#nextParty + 1] = self:cloneMon(party[idx])
    end
  end
  self.party = nextParty
  return #nextParty > 0
end

function Game3:setBattleTowerParty()
  local t = self:ensureBattleTower()
  local order = t.selectedPartyMons or { 0, 0, 0 }
  self.selectedOrderFromParty = { order[1] or 0, order[2] or 0, order[3] or 0 }
  local ok = self:reducePlayerPartyToThree(self.selectedOrderFromParty)
  if ok then
    t.selectedPartyMons = { 1, 2, 3 }
    self.selectedOrderFromParty = { 1, 2, 3 }
  end
  return ok
end

-- Empty e-reader checksum is 0 → RESULT 1 (door stays closed).
function Game3:validateEReaderTrainer()
  self:setScriptVar(Gen3Script.VAR_RESULT, Game3.E_READER_TRAINER_INVALID)
  return Game3.E_READER_TRAINER_INVALID
end

function Game3:getBestBattleTowerStreak()
  return self:getGameStat(Game3.GAME_STAT_BATTLE_TOWER_BEST_STREAK)
end

-- battle_tower.c sShortStreakPrizes / sLongStreakPrizes.
-- Short: streak challenges <= 6 (curStreakChallengesNum - 1 <= 5).
-- Long:  streak challenges > 6.
Game3.BATTLE_TOWER_SHORT_PRIZES = {
  Game3.ITEM_HP_UP,
  Game3.ITEM_PROTEIN,
  Game3.ITEM_IRON,
  Game3.ITEM_CALCIUM,
  Game3.ITEM_CARBOS,
  Game3.ITEM_ZINC,
}

Game3.BATTLE_TOWER_LONG_PRIZES = {
  Game3.ITEM_BRIGHT_POWDER,
  Game3.ITEM_WHITE_HERB,
  Game3.ITEM_QUICK_CLAW,
  Game3.ITEM_LEFTOVERS,
  Game3.ITEM_MENTAL_HERB,
  Game3.ITEM_KINGS_ROCK,
  Game3.ITEM_FOCUS_BAND,
  Game3.ITEM_SCOPE_LENS,
  Game3.ITEM_CHOICE_BAND,
}

-- GetCurrentBattleTowerWinStreak (battle_tower.c).
function Game3:getCurrentBattleTowerWinStreak(levelType)
  local t = self:ensureBattleTower()
  levelType = tonumber(levelType)
  if levelType == nil then levelType = t.levelType or 0 end
  local sets = (t.curStreakChallengesNum and t.curStreakChallengesNum[levelType]) or 0
  local battle = (t.curChallengeBattleNum and t.curChallengeBattleNum[levelType]) or 0
  -- u8 underflow in C when sets == 0: (0-1)*7-1 + battle. Mirror with
  -- unsigned 8-bit wrap so early streaks stay accurate.
  local setsM1 = (sets - 1) % 256
  local streak = setsM1 * 7 - 1 + battle
  if streak < 0 then streak = streak + 256 * 7 end
  if streak > 9999 then streak = 9999 end
  return streak
end

-- DetermineBattleTowerPrize. Picks prizeItem into battleTower state.
function Game3:determineBattleTowerPrize()
  local t = self:ensureBattleTower()
  local level = t.levelType or 0
  local sets = (t.curStreakChallengesNum and t.curStreakChallengesNum[level]) or 0
  local pool
  if (sets - 1) > 5 then
    pool = Game3.BATTLE_TOWER_LONG_PRIZES
  else
    pool = Game3.BATTLE_TOWER_SHORT_PRIZES
  end
  local idx = (self:gbaRandom() % #pool) + 1
  t.prizeItem = pool[idx] or 0
  return t.prizeItem
end

-- GiveBattleTowerPrize. Adds prizeItem; VAR_RESULT 1 on success, else 0
-- and var4AE[level]=6 so the clerk can retry later.
function Game3:giveBattleTowerPrize()
  local t = self:ensureBattleTower()
  local level = t.levelType or 0
  local item = tonumber(t.prizeItem) or 0
  if item > 0 and self:addItem(item, 1) then
    self:setStringVar(1, self:itemName(item) or "?")
    self:setScriptVar(Gen3Script.VAR_RESULT, 1)
    return 1
  end
  t.var4AE = t.var4AE or {}
  t.var4AE[level] = 6
  self:setScriptVar(Gen3Script.VAR_RESULT, 0)
  return 0
end

-- AwardBattleTowerRibbons. Lv50 → WINNING_RIBBON, Lv100 → VICTORY_RIBBON.
-- Only when current win streak > 55; stamps the three selected party mons.
function Game3:awardBattleTowerRibbons()
  local t = self:ensureBattleTower()
  local level = t.levelType or 0
  local ribbonField = (level ~= 0) and "victoryRibbon" or "winningRibbon"
  self:setScriptVar(Gen3Script.VAR_RESULT, 0)
  local awarded = 0
  if self:getCurrentBattleTowerWinStreak(level) > 55 then
    local party = self.party or {}
    local order = t.selectedPartyMons or { 0, 0, 0 }
    for i = 1, 3 do
      local idx = tonumber(order[i]) or 0
      local mon = (idx > 0) and party[idx] or nil
      if mon and not mon[ribbonField] then
        mon[ribbonField] = true
        awarded = 1
      end
    end
  end
  if awarded ~= 0 then
    self:setScriptVar(Gen3Script.VAR_RESULT, 1)
    self:incrementGameStat(Game3.GAME_STAT_RECEIVED_RIBBONS)
  end
  return awarded
end


function Game3:chooseNextBattleTowerTrainer()
  local t = self:ensureBattleTower()
  local level = t.levelType or 0
  local data = self:battleTowerData()
  if self:chooseSpecialBattleTowerTrainer() then
    self:setBattleTowerTrainerGfxId(t.trainerId or 0)
    local battleNum = (t.curChallengeBattleNum and t.curChallengeBattleNum[level]) or 1
    if battleNum >= 1 and battleNum <= 7 then
      t.battledTrainerIds = t.battledTrainerIds or {}
      t.battledTrainerIds[battleNum] = t.trainerId or 0
    end
    return t.trainerId
  end

  local sets = (t.curStreakChallengesNum and t.curStreakChallengesNum[level]) or 1
  local battleNum = (t.curChallengeBattleNum and t.curChallengeBattleNum[level]) or 1
  local trainerId = 0
  local function alreadyBattled(id)
    local n = battleNum - 1
    for i = 1, n do
      if (t.battledTrainerIds and t.battledTrainerIds[i]) == id then return true end
    end
    return false
  end

  if sets <= 7 then
    if battleNum == 7 then
      while true do
        trainerId = math.floor(((self:gbaRandom() % 256) * 5) / 128)
        trainerId = trainerId + (sets - 1) * 10 + 20
        if not alreadyBattled(trainerId) then break end
      end
    else
      while true do
        trainerId = math.floor(((self:gbaRandom() % 256) * 5) / 64)
        trainerId = trainerId + (sets - 1) * 10
        if not alreadyBattled(trainerId) then break end
      end
    end
  else
    while true do
      trainerId = math.floor(((self:gbaRandom() % 256) * 30) / 256) + 70
      if not alreadyBattled(trainerId) then break end
    end
  end

  t.trainerId = trainerId
  self:setBattleTowerTrainerGfxId(trainerId)
  if battleNum < 7 then
    t.battledTrainerIds = t.battledTrainerIds or {}
    t.battledTrainerIds[battleNum] = trainerId
  end
  return trainerId
end

-- Record-mix / e-reader opponents. Without mixed records or an e-reader
-- card this always returns false and the roster path above runs.
function Game3:chooseSpecialBattleTowerTrainer()
  local t = self:ensureBattleTower()
  local level = t.levelType or 0
  local streak = self:getCurrentBattleTowerWinStreak(level)
  -- E-reader: only when a valid card matching streak/level is present.
  if t.ereaderTrainer and type(t.ereaderTrainer) == "table" then
    -- validateEReaderTrainer already returns invalid by default.
  end
  local candidates = {}
  local records = t.records or {}
  for i = 1, 5 do
    local rec = records[i]
    if type(rec) == "table"
        and (tonumber(rec.winStreak) or 0) == streak
        and (tonumber(rec.battleTowerLevelType) or 0) == level
        and rec.hasData then
      candidates[#candidates + 1] = (i - 1) + Game3.BATTLE_TOWER_RECORD_MIXING_BASE_ID
    end
  end
  if #candidates == 0 then return false end
  local pick = candidates[(self:gbaRandom() % #candidates) + 1]
  t.trainerId = pick
  return true
end

function Game3:setBattleTowerTrainerGfxId(trainerIndex)
  trainerIndex = tonumber(trainerIndex) or 0
  local data = self:battleTowerData()
  local trainerClass = nil
  if trainerIndex < Game3.BATTLE_TOWER_RECORD_MIXING_BASE_ID then
    local row = data.trainers and data.trainers[trainerIndex]
    trainerClass = row and row.trainerClass
  elseif trainerIndex < Game3.BATTLE_TOWER_EREADER_TRAINER_ID then
    local rec = self:ensureBattleTower().records
      and self:ensureBattleTower().records[
        trainerIndex - Game3.BATTLE_TOWER_RECORD_MIXING_BASE_ID + 1]
    trainerClass = rec and rec.trainerClass
  else
    local er = self:ensureBattleTower().ereaderTrainer
    trainerClass = er and er.trainerClass
  end
  local gfx = Game3.BATTLE_TOWER_OBJ_GFX_BOY_1
  if trainerClass ~= nil then
    local males = data.maleClasses or {}
    local maleGfx = data.maleGfx or {}
    for i = 1, #males do
      if males[i] == trainerClass then
        gfx = maleGfx[i] or gfx
        self:setScriptVar(Game3.VAR_OBJ_GFX_ID_0, gfx)
        return gfx
      end
    end
    local females = data.femaleClasses or {}
    local femaleGfx = data.femaleGfx or {}
    for i = 1, #females do
      if females[i] == trainerClass then
        gfx = femaleGfx[i] or gfx
        self:setScriptVar(Game3.VAR_OBJ_GFX_ID_0, gfx)
        return gfx
      end
    end
  end
  self:setScriptVar(Game3.VAR_OBJ_GFX_ID_0, gfx)
  return gfx
end

function Game3:setEReaderTrainerGfxId()
  return self:setBattleTowerTrainerGfxId(Game3.BATTLE_TOWER_EREADER_TRAINER_ID)
end

function Game3:battleTowerTrainerRow(trainerId)
  trainerId = tonumber(trainerId)
  if trainerId == nil then
    trainerId = self:ensureBattleTower().trainerId or 0
  end
  local data = self:battleTowerData()
  if trainerId < Game3.BATTLE_TOWER_RECORD_MIXING_BASE_ID then
    return data.trainers and data.trainers[trainerId]
  end
  return nil
end

function Game3:battleTowerTrainerName(trainerId)
  local t = self:ensureBattleTower()
  trainerId = tonumber(trainerId) or (t.trainerId or 0)
  if trainerId == Game3.BATTLE_TOWER_EREADER_TRAINER_ID then
    local er = t.ereaderTrainer
    return (er and er.name) or "E-READER"
  end
  if trainerId >= Game3.BATTLE_TOWER_RECORD_MIXING_BASE_ID then
    local rec = t.records
      and t.records[trainerId - Game3.BATTLE_TOWER_RECORD_MIXING_BASE_ID + 1]
    return (rec and rec.name) or "TRAINER"
  end
  local row = self:battleTowerTrainerRow(trainerId)
  return (row and row.name) or "TRAINER"
end

function Game3:battleTowerTrainerClassName(trainerId)
  local row = self:battleTowerTrainerRow(trainerId)
  if row and row.className then return row.className end
  return "TRAINER"
end

-- Easy-Chat greetings are not decoded here; scripts still msgbox
-- string var 4 via ShowFieldMessageStringVar4.
function Game3:printBattleTowerTrainerGreeting()
  local name = self:battleTowerTrainerName()
  local className = self:battleTowerTrainerClassName()
  local text = ("%s %s wants to battle!"):format(className, name)
  self:setStringVar(4, text)
  return text
end

function Game3:printEReaderTrainerGreeting()
  self:setStringVar(4, "The E-READER TRAINER wants to battle!")
end

function Game3:bufferEReaderTrainerName()
  local er = self:ensureBattleTower().ereaderTrainer
  self:setStringVar(1, (er and er.name) or "E-READER")
end

-- CreateMonWithEVSpread: fixed IV on every stat, 510 EVs split across
-- the set bits of evSpread.
function Game3:makeBattleTowerMon(entry, level, fixedIV)
  if type(entry) ~= "table" then return nil end
  local moves = entry.moves or {}
  local mon = self:makeMon(entry.species, level, moves, { trainer = true })
  if not mon then return nil end
  fixedIV = tonumber(fixedIV) or 0
  if fixedIV < 0 then fixedIV = 0 end
  if fixedIV > 31 then fixedIV = 31 end
  mon.ivs = {
    hp = fixedIV, atk = fixedIV, def = fixedIV,
    spe = fixedIV, spa = fixedIV, spd = fixedIV,
  }
  local spread = tonumber(entry.evSpread) or 0
  local bits = {}
  for i = 0, 5 do
    if (spread % 2) == 1 then bits[#bits + 1] = i end
    spread = math.floor(spread / 2)
  end
  local evs = { hp = 0, atk = 0, def = 0, spe = 0, spa = 0, spd = 0 }
  local keys = { "hp", "atk", "def", "spe", "spa", "spd" }
  if #bits > 0 then
    local amount = math.floor(510 / #bits)
    for i = 1, #bits do
      evs[keys[bits[i] + 1]] = amount
    end
  end
  mon.evs = evs
  local data = self:battleTowerData()
  local heldIdx = tonumber(entry.heldItem) or 0
  mon.item = (data.heldItems and data.heldItems[heldIdx + 1]) or 0
  -- Frustration cares about low friendship.
  local friendship = 255
  for i = 1, 4 do
    if (moves[i] or 0) == 218 then friendship = 0 end -- MOVE_FRUSTRATION
  end
  mon.friendship = friendship
  self:recalcStats(mon)
  mon.hp = mon.maxHp
  -- Anti-shiny OT like makeTrainerMon.
  local pid = mon.pid or 0
  local ot
  for _ = 1, 64 do
    local lo = self:rand(65536) - 1
    local hi = self:rand(65536) - 1
    if lo < 0 then lo = 0 end
    if hi < 0 then hi = 0 end
    ot = hi * 65536 + lo
    if not Game3.isShinyOtIdPersonality(ot, pid) then break end
  end
  mon.otId = ot
  mon.otName = "TRAINER"
  return mon
end

function Game3:fillBattleTowerTrainerParty()
  local t = self:ensureBattleTower()
  local trainerId = t.trainerId or 0
  local data = self:battleTowerData()
  local party = {}

  local function band(a, b)
    local res, bitval = 0, 1
    a = math.floor(tonumber(a) or 0)
    b = math.floor(tonumber(b) or 0)
    while a > 0 and b > 0 do
      if (a % 2 == 1) and (b % 2 == 1) then res = res + bitval end
      a = math.floor(a / 2)
      b = math.floor(b / 2)
      bitval = bitval * 2
    end
    return res
  end

  if trainerId == Game3.BATTLE_TOWER_EREADER_TRAINER_ID then
    return party
  end
  if trainerId >= Game3.BATTLE_TOWER_RECORD_MIXING_BASE_ID then
    local rec = t.records
      and t.records[trainerId - Game3.BATTLE_TOWER_RECORD_MIXING_BASE_ID + 1]
    if rec and type(rec.party) == "table" then
      for i = 1, 3 do
        if rec.party[i] then party[#party + 1] = rec.party[i] end
      end
    end
    return party
  end

  local fixedIV, offset, poolSize = 6, 0, 60
  if trainerId >= 80 then
    fixedIV, offset, poolSize = 31, 200, 100
  elseif trainerId >= 70 then
    fixedIV, offset, poolSize = 31, 180, 60
  elseif trainerId >= 60 then
    fixedIV, offset, poolSize = 21, 150, 60
  elseif trainerId >= 50 then
    fixedIV, offset, poolSize = 18, 120, 60
  elseif trainerId >= 40 then
    fixedIV, offset, poolSize = 15, 90, 60
  elseif trainerId >= 30 then
    fixedIV, offset, poolSize = 12, 60, 60
  elseif trainerId >= 20 then
    fixedIV, offset, poolSize = 9, 30, 60
  end

  local level = ((t.levelType or 0) ~= 0) and 100 or 50
  local pool = ((t.levelType or 0) ~= 0) and data.level100Mons or data.level50Mons
  local row = data.trainers and data.trainers[trainerId]
  local teamFlags = (row and row.teamFlags) or 0
  local slots = {}
  local guard = 0
  while #slots < 3 and guard < 10000 do
    guard = guard + 1
    local idx = math.floor(((self:gbaRandom() % 256) * poolSize) / 256) + offset
    local entry = pool and pool[idx]
    if entry then
      local ok = true
      if teamFlags ~= 0 and band(entry.teamFlags or 0, teamFlags) ~= teamFlags then
        ok = false
      end
      if ok then
        for i = 1, #slots do
          local prev = pool[slots[i]]
          if prev and prev.species == entry.species then ok = false end
          if ok then
            local held = (data.heldItems and data.heldItems[(entry.heldItem or 0) + 1]) or 0
            local prevHeld = (data.heldItems and data.heldItems[(prev.heldItem or 0) + 1]) or 0
            if held ~= 0 and held == prevHeld then ok = false end
          end
          if ok and slots[i] == idx then ok = false end
          if not ok then break end
        end
      end
      if ok then slots[#slots + 1] = idx end
    end
  end

  for i = 1, #slots do
    local mon = self:makeBattleTowerMon(pool[slots[i]], level, fixedIV)
    if mon then
      party[#party + 1] = {
        species = mon.species,
        level = mon.level,
        moves = {},
        iv = math.floor((fixedIV * 255) / 31),
        _towerMon = mon,
      }
      -- Prefer raw mon objects for startTrainerBattle via makeTrainerMon bypass.
    end
  end
  -- Prefer returning prep-ready mons directly for startTrainerBattle.
  local live = {}
  for i = 1, #slots do
    local mon = self:makeBattleTowerMon(pool[slots[i]], level, fixedIV)
    if mon then live[#live + 1] = mon end
  end
  return live
end

function Game3:startSpecialBattle()
  local mode = self:varGet(0x8004)
  if mode == 0 then
    local built = self:fillBattleTowerTrainerParty()
    if #built < 1 then
      self:setScriptVar(Gen3Script.VAR_RESULT, 0)
      return false
    end
    local npc = {
      trainerId = 0,
      trainerName = self:battleTowerTrainerName(),
      trainerClass = self:battleTowerTrainerClassName(),
      party = built,
      battleTower = true,
      doubleBattle = false,
    }
    self:beginScriptWait()
    self.battleOutcome = 0
    local player = self:firstHealthy()
    if not player then
      self:endScriptWait()
      return false
    end
    local enemy = self:prepBattler(built[1])
    if not enemy then
      self:endScriptWait()
      return false
    end
    self:prepBattler(player)
    self:markSeen(enemy.species)
    self:clearPoisonStepCounter()
    self.walkCountdown = 0
    self.field = nil
    self.battle = {
      kind = "intro",
      cursor = 0,
      fightCursor = 0,
      partyCursor = 0,
      isTrainer = true,
      battleTower = true,
      doubles = nil,
      chooser = "player",
      npc = npc,
      trainerParty = built,
      trainerIndex = 1,
      player = player,
      enemy = enemy,
      text = ("%s would like to battle!"):format(self:trainerLabel(npc)),
      enterBoth = true,
      switchInDone = false,
      turns = 0,
      introT = 0,
      animT = 0,
      trainerItems = { 0, 0, 0, 0 },
      numItems = 0,
    }
    self:playBattleMusic("trainer")
    self:resetBattleResults()
    self:applyOverworldBattleWeather()
    self:markSentIn(player)
    self:launchBattleWithEntrance({ mode = "trainer", npc = npc })
    return true
  elseif mode == 2 then
    -- E-reader trainer battle: no card in this port.
    self:setScriptVar(Gen3Script.VAR_RESULT, 0)
    return false
  end
  return false
end

function Game3:saveBattleTowerProgress()
  local t = self:ensureBattleTower()
  local level = t.levelType or 0
  local mode = self:varGet(0x8004)
  if mode == 3 or mode == 0 then
    local sets = (t.curStreakChallengesNum and t.curStreakChallengesNum[level]) or 1
    local battle = (t.curChallengeBattleNum and t.curChallengeBattleNum[level]) or 1
    if sets > 1 or battle > 1 then
      self:snapshotBattleTowerPlayerRecord()
    end
  end
  self:recordBattleTowerDefeatMeta()
  t.battleOutcome = tonumber(self.battleOutcome) or 0
  if mode ~= 3 then
    t.var4AE = t.var4AE or {}
    t.var4AE[level] = mode
  end
  self:setScriptVar(Game3.VAR_TEMP_0, 0)
  t.unk554 = 1
  self:writeSave()
  return true
end

function Game3:snapshotBattleTowerPlayerRecord()
  local t = self:ensureBattleTower()
  local level = t.levelType or 0
  local record = {
    battleTowerLevelType = level,
    trainerClass = 0,
    name = self:playerName(),
    winStreak = self:getCurrentBattleTowerWinStreak(level),
    hasData = true,
    greeting = {},
    party = {},
  }
  t.playerRecord = record
  self:saveCurrentBattleTowerWinStreak()
end

function Game3:recordBattleTowerDefeatMeta()
  local t = self:ensureBattleTower()
  t.defeatedByTrainerName = self:battleTowerTrainerName()
  local b = self.battle
  if b and b.enemy then
    t.defeatedBySpecies = b.enemy.species or 0
    t.firstMonSpecies = (b.player and b.player.species) or 0
    t.firstMonNickname = (b.player and (b.player.name or b.player.nickname)) or ""
  end
end

-- field_specials.c TryInitBattleTowerAwardManObjectEvent ->
-- TryInitLocalObjectEvent(6). Without local-object templates this is a
-- no-op so lobby scripts never hang.
function Game3:tryInitBattleTowerAwardManObjectEvent()
  return 0
end

-- Enables Bravo Trainer Battle Tower TV show when a streak is mid-run.
-- TV pipeline is best-effort; never wait.
function Game3:tryEnableBravoTrainerBattleTower()
  local t = self:ensureBattleTower()
  for level = 0, 1 do
    if ((t.var4AE and t.var4AE[level]) or 0) == 1 then
      -- sub_80BFD20: mark a pending Bravo Trainer episode if TV helpers exist.
      if self.queueBravoTrainerBattleTowerShow then
        self:queueBravoTrainerBattleTowerShow()
      end
    end
  end
  return 0
end

function Game3:getSecretBaseNearbyMapName()
  local sec = tonumber(self:varGet(Game3.VAR_SECRET_BASE_MAP)) or 0
  -- Bases dug before createSecretBase stamped the var have 0 here, which
  -- names Littleroot. Read the section off the record's own map instead.
  if sec == 0 and self.secretBase then
    local pack = self.data.maps and self.data.maps.maps
    local host = type(pack) == "table" and pack[self.secretBase.mapId]
    sec = (host and tonumber(host.regionMapSectionId)) or sec
  end
  self:setStringVar(1, self:mapSectionName(sec))
end

function Game3:bufferSecretBaseOwnerName()
  self:setStringVar(1, self:playerName())
end

function Game3:getCurSecretBaseRegistrationValidity()
  self:setScriptVar(Gen3Script.VAR_RESULT, 0)
  return 0
end

-- Own base is slot 0. RESULT 0 is "this is yours".
function Game3:isNotPlayersSecretBase()
  local n = 0
  self:setScriptVar(Gen3Script.VAR_RESULT, n)
  return n
end

function Game3:recordPlayerSecretBase()
  self:setScriptVar(Game3.VAR_CURRENT_SECRET_BASE, 0)
  local m = self.map
  self:setScriptVar(Game3.VAR_SECRET_BASE_MAP,
    (m and m.regionMapSectionId) or 0)
  return 0
end

function Game3:warpIntoSecretBaseFromSpecial()
  if self:hasSecretBase() then self:enterSecretBase() end
end

-- secret_base.c sub_80BBBEC, the tail of special 24: once the fade has
-- finished it calls Overworld_SetWarpDestination(current map, warpId -1,
-- table[idx+2], table[idx+3]) + WarpIntoMap(), i.e. a reposition inside the
-- interior you are already standing in, to the entry table's raw coords.
-- Done here as a teleport rather than a re-entry: the ROM's WarpIntoMap +
-- CB2_LoadMap reload only re-runs this map's onTransition (its onWarp and
-- onFrame are both already var-gated shut by this point), so the observable
-- result is the same, and enterMap mid-script would clear moveJobs out from
-- under the waitstate the script is parked on.
function Game3:secretBaseEntryReposition()
  local map = self.map
  if not Game3.isSecretBaseMap(map) then return false end
  local entry = Game3.secretBaseEntry(self.secretBase and self.secretBase.id)
  if not entry then return false end
  self.playerX, self.playerY = entry.x, entry.y
  self.walkFromX, self.walkFromY = entry.x, entry.y
  self.walkCooldown = 0
  self.ignoreWarp = Game3.warpAt(map, entry.x, entry.y) ~= nil
  self:updatePlayerZCoord()
  self:clampCamera()
  return true
end

-- secret_base.c sub_80BBC78: FadeScreen(1, 0) then the task above. The
-- creation script follows it with waitstate, so this holds the script.
function Game3:secretBaseCreationWarp()
  -- SecretBase_EventScript_FirstEntrance's yes branch. With a move pending
  -- this is the first moment the player has actually seen the new base, so
  -- AskToMoveSecretBase's two questions run here rather than outside.
  if self._secretBaseMoveFrom then
    return self:askMoveSecretBaseInside()
  end
  self:beginScreenFade(Game3.FADE_TO_BLACK)
  self.secretBaseWarpLeft = Game3.FADE_FRAMES
  self:beginScriptWait()
end

-- UnknownString_81A3C71 then SecretBase_Text_AllDecorationsWillBeReturned,
-- the same pair AskToMoveSecretBase asks, just moved to inside the new base.
function Game3:askMoveSecretBaseInside()
  -- The line names where the base you are LEAVING is. By now slot 0 already
  -- holds the new dig (EventScript_1A2DB8 ran), and VAR_SECRET_BASE_MAP with
  -- it, so read the section off the record held aside for the move.
  local from = self._secretBaseMoveFrom
  local pack = self.data.maps and self.data.maps.maps
  local host = from and type(pack) == "table" and pack[from.mapId]
  local sec = host and tonumber(host.regionMapSectionId)
  if sec then
    self:setStringVar(1, self:mapSectionName(sec))
  else
    self:getSecretBaseNearbyMapName()
  end
  local near = (self.stringVars and self.stringVars[1]) or "this area"
  self:openSecretBaseYesNo(
    "You may only make one SECRET BASE.\r\nWould you like to move from the "
      .. "SECRET BASE near " .. near .. "?",
    "askMoveSecretBaseInsideDecorations", {})
  self:beginScriptWait()
end

function Game3:askMoveSecretBaseInsideDecorations()
  self:openSecretBaseYesNo(
    "All decorations and furniture in your\r\nSECRET BASE will be returned "
      .. "to your PC.\r\nIs that okay?",
    "commitSecretBaseMove", {})
end

-- Both yeses: MoveSecretBase proper -- sub_80BC474 seals the old entrance,
-- GAME_STAT_MOVED_SECRET_BASE, ResetSecretBase(0) on the old slot. The new
-- record is already in slot 0 from EventScript_1A2DB8, so only the old one
-- has to be torn down.
function Game3:commitSecretBaseMove()
  local from = self._secretBaseMoveFrom
  self._secretBaseMoveFrom = nil
  if from then
    local kept = self.secretBase
    self.secretBase = from
    self:closeSecretBaseEntrance()
    self:incrementGameStat(Game3.GAME_STAT_MOVED_SECRET_BASE)
    self.secretBase = kept
    if kept then
      kept.numSecretBasesReceived = from.numSecretBasesReceived
        or kept.numSecretBasesReceived
    end
  end
  self:setCurrentSecretBaseVar()
  self:beginScreenFade(Game3.FADE_TO_BLACK)
  self.secretBaseWarpLeft = Game3.FADE_FRAMES
  self:beginScriptWait()
end

-- decoration.h DECORPERM_*, and the two mat behaviours sub_80BBDD0 will
-- place a doll on (metatile_behaviors.h).
Game3.DECORPERM_SOLID_FLOOR = 0
Game3.DECORPERM_PASS_FLOOR = 1
Game3.DECORPERM_BEHIND_FLOOR = 2
Game3.DECORPERM_NA_WALL = 3
Game3.DECORPERM_SOLID_MAT = 4
Game3.DECOR_SOLID_BOARD = 33
Game3.DECORSHAPE_1x2 = 5
Game3.MB_NORMAL = 0x00
Game3.MB_BLOCK_DECORATION = 0xB3
Game3.MB_SECRET_BASE_NORTH_WALL = 0xB7
Game3.MB_SECRET_BASE_IMPASSABLE = 0xB9
Game3.MB_SECRET_BASE_HOLE = 0xC2
-- decoration.c sub_80FF1EC reads the decoration's own metatiles out of the
-- SECONDARY tileset, i.e. attributes for metatile 0x200 + tiles[n].
Game3.DECOR_TILE_BASE = 0x200
Game3.MB_SECRET_BASE_LARGE_MAT_EDGE = 0xB5
Game3.MB_LARGE_MAT_CENTER = 0xC3
-- The decoration sprite slots are object events with graphicsId GFX_VAR_0..E
-- hidden behind flags 0xAE + n, which the interior's onTransition sets.
Game3.SECRET_BASE_DECOR_FLAG_BASE = 0xAE
-- flags.h FLAG_DECORATION_1. It is objects[1]'s flagId in every interior --
-- the base OWNER, graphicsId GFX_VAR_F -- and setting it is how the ROM
-- hides that trainer when the base is your own. secret_base.inc sets it in
-- EventScript_1A2DB8 (every Secret Power use) and again in
-- EventScript_1A2E38 (walking into a base sub_80BC114 says is yours), and
-- only clears it for someone else's base, which record mixing can never
-- deliver here.
Game3.FLAG_DECORATION_1 = 0xAD

function Game3.decorationInfo(data, id)
  local pack = data and data.decorations
  local byId = pack and pack.byId
  return byId and byId[tonumber(id) or -1] or nil
end

-- The layer type of one of a decoration's own metatiles, which lives in the
-- secondary tileset. decoration.c reads GetMetatileAttributesById(0x200 +
-- tile) & 0xF000; loadBehaviors already split that nibble out per metatile,
-- so this is the same value the ROM compares against zero.
function Game3:decorTileLayerType(map, tile)
  local spec = self.data.tilesets and self.data.tilesets.byId
    and self.data.tilesets.byId[map and map.tileset]
  local layer = spec and spec.layerType
  return (layer and layer[Game3.DECOR_TILE_BASE + (tonumber(tile) or 0)]) or 0
end

-- decoration.c sub_80FFBDC: the floor permissions want a plain tile, with
-- SOLID BOARD additionally allowed over a secret base hole (that is what it
-- is for -- bridging one).
function Game3:decorFloorTileOk(behavior, id)
  if behavior == Game3.MB_BLOCK_DECORATION then return false end
  if id == Game3.DECOR_SOLID_BOARD and behavior == Game3.MB_SECRET_BASE_HOLE then
    return true
  end
  return behavior == Game3.MB_NORMAL
end

-- decoration.c sub_80FFC24: can this decoration stand with its BOTTOM-LEFT
-- cell at (x, y)? The ROM anchors on the bottom row and walks upward
-- (curY = data[1] - i), so row i counts up from the bottom. Coordinates here
-- are map-local; the ROM's +7 is only its MapGrid offset.
--
-- Each permission class has its own rule:
--   SOLID_FLOOR / PASS_FLOOR  every cell plain (or a hole under SOLID BOARD),
--                             nothing standing on it, and never the tile the
--                             player is on when that cell has a layer type.
--   BEHIND_FLOOR              upper rows may also sit on a block-decoration
--                             cell whose layer type is 0; the bottom row may
--                             sit against the north wall.
--   NA_WALL                   every cell must be north wall, and the tile
--                             below must not be metatile 0x28C.
--   SOLID_MAT                 a single row on mat tiles; 1x2 mats demand the
--                             centre, others take centre or edge.
function Game3:canPlaceDecoration(id, x, y, map)
  map = map or self.map
  local info = Game3.decorationInfo(self.data, id)
  if not (map and info) then return false end
  local w, h = info.width or 1, info.height or 1
  local perm = info.permission
  local tiles = info.tiles or {}
  local px, py = self.playerX, self.playerY

  local function occupied(cx, cy)
    return self:npcAt(map, cx, cy) ~= nil
  end
  -- sub_80FFB94: a cell that carries a layer type may not land on the player.
  local function playerBlocks(cx, cy, layerType)
    return layerType ~= 0 and cx == px and cy == py
  end

  if perm == Game3.DECORPERM_SOLID_FLOOR or perm == Game3.DECORPERM_PASS_FLOOR then
    for i = 0, h - 1 do
      local cy = y - i
      for j = 0, w - 1 do
        local cx = x + j
        local b = self:behaviorAt(map, cx, cy)
        local layer = self:decorTileLayerType(map, tiles[(h - 1 - i) * w + j + 1])
        if not self:decorFloorTileOk(b, id) then return false end
        if playerBlocks(cx, cy, layer) then return false end
        if occupied(cx, cy) then return false end
      end
    end
    return true
  end

  if perm == Game3.DECORPERM_BEHIND_FLOOR then
    for i = 0, h - 2 do
      local cy = y - i
      for j = 0, w - 1 do
        local cx = x + j
        local b = self:behaviorAt(map, cx, cy)
        local layer = self:decorTileLayerType(map, tiles[(h - 1 - i) * w + j + 1])
        local blockOk = b == Game3.MB_BLOCK_DECORATION and layer == 0
        if b ~= Game3.MB_NORMAL and not blockOk then return false end
        if playerBlocks(cx, cy, layer) then return false end
        if occupied(cx, cy) then return false end
      end
    end
    local cy = y - h + 1
    for j = 0, w - 1 do
      local cx = x + j
      local b = self:behaviorAt(map, cx, cy)
      local layer = self:decorTileLayerType(map, tiles[j + 1])
      if b ~= Game3.MB_NORMAL and b ~= Game3.MB_SECRET_BASE_NORTH_WALL then
        return false
      end
      if playerBlocks(cx, cy, layer) then return false end
      if occupied(cx, cy) then return false end
    end
    return true
  end

  if perm == Game3.DECORPERM_NA_WALL then
    for i = 0, h - 1 do
      local cy = y - i
      for j = 0, w - 1 do
        local cx = x + j
        if self:behaviorAt(map, cx, cy) ~= Game3.MB_SECRET_BASE_NORTH_WALL then
          return false
        end
        local below = self:gridIndex(map, cx, cy + 1)
        if below and Game3.metatileOf(map.grid[below]) == 0x28C then return false end
      end
    end
    return true
  end

  if perm == Game3.DECORPERM_SOLID_MAT then
    for j = 0, w - 1 do
      local cx = x + j
      local b = self:behaviorAt(map, cx, y)
      if info.shape == Game3.DECORSHAPE_1x2 then
        if b ~= Game3.MB_LARGE_MAT_CENTER then return false end
      elseif b ~= Game3.MB_SECRET_BASE_LARGE_MAT_EDGE
          and b ~= Game3.MB_LARGE_MAT_CENTER then
        return false
      end
      if occupied(cx, y) then return false end
    end
    return true
  end

  return false
end

-- decoration.c sub_80FF1B0 with gUnknown_083EC97C / gUnknown_083EC984
-- (ROM 0x083EC97C and 0x083EC984, eight bytes each, read off the cart and
-- matched byte-for-byte against the decomp). Every decoration but STAND
-- and SLIDE returns 0xFFFF, meaning "leave the cell's elevation alone";
-- those two carry a per-cell elevation nibble instead, which is what lets
-- you climb one and stand on top.
Game3.DECOR_SLIDE = 34
Game3.DECOR_STAND = 38
Game3.DECOR_CELL_ELEVATION = {
  [38] = { 4, 4, 4, 4, 0, 3, 3, 0 },
  [34] = { 4, 4, 4, 4, 0, 4, 3, 0 },
}

function Game3.decorCellElevation(id, cell)
  local row = Game3.DECOR_CELL_ELEVATION[tonumber(id) or 0]
  if not row then return nil end
  return row[(tonumber(cell) or 0) + 1]
end

-- decoration.c sub_80FF1EC: bake one decoration into the map grid. The
-- anchor is the BOTTOM-left cell, so row i writes at y - height + 1 + i.
-- Per cell:
--   collision 0xC00 when the decoration's own metatile is secret-base
--     impassable, or its layer type is non-zero and the permission is not
--     PASS_FLOOR; otherwise 0
--   +1 on the tile when the permission is not NA_WALL and the target cell
--     is a secret base north wall, which shifts to the wall variant
--   an elevation override for STAND and SLIDE only
function Game3:stampDecorationCells(x, y, w, h, id, map)
  map = map or self.map
  local info = Game3.decorationInfo(self.data, id)
  if not (map and info) then return false end
  local tiles = info.tiles or {}
  -- Snapshot before the first write, so what gets restored later is the
  -- layout as loaded and not a grid that already has this stamp in it.
  self:snapshotPristineGrid(map)
  for i = 0, h - 1 do
    local cy = y - h + 1 + i
    for j = 0, w - 1 do
      local cx = x + j
      local cell = i * w + j
      local tile = tonumber(tiles[cell + 1]) or 0
      local layer = self:decorTileLayerType(map, tile)
      local behavior = self:behaviorAt(map, cx, cy)
      local ownBehavior = self:decorTileBehavior(map, tile)
      local collision = 0
      if ownBehavior == Game3.MB_SECRET_BASE_IMPASSABLE
          or (info.permission ~= Game3.DECORPERM_PASS_FLOOR and layer ~= 0) then
        collision = Game3.MAPGRID_COLLISION_MASK
      end
      local wall = 0
      if info.permission ~= Game3.DECORPERM_NA_WALL
          and behavior == Game3.MB_SECRET_BASE_NORTH_WALL then
        wall = 1
      end
      local metatile = tile + Game3.DECOR_TILE_BASE + wall + collision
      local elev = Game3.decorCellElevation(id, cell)
      local gi = self:gridIndex(map, cx, cy)
      if gi and type(map.grid) == "table" then
        if elev then
          map.grid[gi] = metatile + elev * 4096
        else
          local keep = math.floor((map.grid[gi] or 0) / 4096) * 4096
          map.grid[gi] = keep + metatile
        end
      end
    end
  end
  self:markTilesDirty()
  return true
end

-- The behaviour of one of the decoration's OWN metatiles, which live in
-- the secondary tileset -- GetMetatileAttributesById(0x200 + tile).
function Game3:decorTileBehavior(map, tile)
  local spec = self.data.tilesets and self.data.tilesets.byId
    and self.data.tilesets.byId[map and map.tileset]
  local b = spec and spec.behavior
  return (b and b[Game3.DECOR_TILE_BASE + (tonumber(tile) or 0)]) or 0
end

-- Snapshot a map's grid the first time anything bakes into it, then hand
-- that copy back on demand. Stands in for the ROM's InitMapLayoutData.
function Game3:snapshotPristineGrid(map)
  if type(map) ~= "table" or type(map.grid) ~= "table" then return end
  if type(map._pristineGrid) == "table" then return end
  local copy = {}
  for i = 1, #map.grid do copy[i] = map.grid[i] end
  map._pristineGrid = copy
end

function Game3:restorePristineGrid(map)
  if type(map) ~= "table" or type(map.grid) ~= "table" then return end
  if type(map._pristineGrid) ~= "table" then
    return self:snapshotPristineGrid(map)
  end
  for i = 1, #map._pristineGrid do map.grid[i] = map._pristineGrid[i] end
  self:markTilesDirty()
end

-- decoration.c sub_80FF394: the same stamp, sized by the shape.
function Game3:stampDecoration(x, y, id, map)
  local info = Game3.decorationInfo(self.data, id)
  if not info then return false end
  return self:stampDecorationCells(x, y, info.width or 1, info.height or 1,
    id, map)
end

-- secret_base.c InitSecretBaseAppearance: on every load of a secret base
-- interior, bake in each of the 16 slots. DECORPERM_SOLID_MAT entries are
-- skipped here -- those are object events, and sub_80BBDD0 spawns them.
function Game3:initSecretBaseAppearance(map)
  map = map or self.map
  if not (map and Game3.isSecretBaseMap(map)) then return end
  -- The ROM re-reads the layout out of the cart on every map load, so the
  -- stamps below always land on a clean grid. This engine hands out one
  -- shared cached table per map, so keep a pristine copy and restore it
  -- first -- otherwise a decoration would double-stamp on re-entry and
  -- survive being put away.
  self:restorePristineGrid(map)
  local sb = self.secretBase
  local decor = sb and sb.decorations
  local pos = sb and sb.decorationPos
  if not (decor and pos) then return end
  for i = 1, Game3.DECOR_MAX_SECRET_BASE do
    local id = tonumber(decor[i]) or 0
    local info = id > 0 and id <= 0x78 and Game3.decorationInfo(self.data, id)
    if info and info.permission ~= Game3.DECORPERM_SOLID_MAT then
      local x, y = Game3.decorPosXY(pos[i])
      self:stampDecoration(x, y, id, map)
    end
  end
end

-- ===================================================================
-- Decorations that DO something when you walk on them. secret_base.c
-- sub_80BCF1C is the base's per-step callback (setstepcallback 6, from
-- SecretBase_OnResume) and fires only on the frame the player's tile
-- changes; the jump and spin mats are forced movement instead, out of
-- field_player_avatar.c's sForcedMovementTestFuncs.
-- ===================================================================
Game3.MB_SECRET_BASE_BALLOON = 0xB8
Game3.MB_SECRET_BASE_GLITTER_MAT = 0xBA
Game3.MB_SECRET_BASE_JUMP_MAT = 0xBB
Game3.MB_SECRET_BASE_SPIN_MAT = 0xBC
Game3.MB_SECRET_BASE_MUSIC_NOTE_MAT = 0xBD
Game3.MB_SECRET_BASE_BREAKABLE_DOOR = 0xBE

-- fldeff_decoration.c Task_SecretBaseMusicNoteMatSound, by metatile id.
Game3.MUSIC_NOTE_MAT_SE = {
  [632] = 62, [633] = 63, [634] = 64, [635] = 65,
  [636] = 66, [637] = 67, [638] = 68, [691] = 69,
}
-- fldeff_decoration.c DoBalloonSoundEffect.
Game3.BALLOON_SE = { [824] = 74, [828] = 75, [832] = 76, [552] = 20 }
-- The balloon, the breakable door and the music note mats are pure
-- timers -- the ROM runs them as tasks with no sprite of their own, the
-- visible part being the metatile they swap or the sound they play. They
-- ride the field-effect list only to get ticked, so they need an id that
-- draws nothing rather than FLDEFF_SPARKLE, which would put a stray
-- sparkle on every note you step on.
Game3.FLDEFF_SECRET_BASE_TIMER = -1
Game3.SE_BREAKABLE_DOOR = 77
Game3.SE_M_HEAL_BELL = 195
Game3.SE_LEDGE = 10
Game3.SE_WARP_IN = 45
-- The two halves a shattered breakable door leaves behind.
Game3.MT_BROKEN_DOOR_BOTTOM = 630
Game3.MT_BROKEN_DOOR_TOP = 622

function Game3:secretBaseStepEffect(x, y, behavior)
  if behavior == Game3.MB_SECRET_BASE_GLITTER_MAT then
    return self:doGlitterMatSparkle(x, y)
  end
  if behavior == Game3.MB_SECRET_BASE_BALLOON then
    return self:popSecretBaseBalloon(x, y)
  end
  if behavior == Game3.MB_SECRET_BASE_BREAKABLE_DOOR then
    return self:shatterBreakableDoor(x, y)
  end
  if behavior == Game3.MB_SECRET_BASE_MUSIC_NOTE_MAT then
    return self:playMusicNoteMat(x, y)
  end
  return false
end

-- DoSecretBaseGlitterMatSparkle + SpriteCB_GlitterMatSparkle: a 32-frame
-- sparkle on the player's own tile, with SE_M_HEAL_BELL at frame 8. The
-- sparkle renderer reads fx.x / fx.y (the field effect arguments), so
-- those are what have to carry the tile -- setting only gx/gy left it
-- drawing wherever the last effect's arguments happened to point.
function Game3:doGlitterMatSparkle(x, y)
  self.fieldEffects = self.fieldEffects or {}
  self.fieldEffects[#self.fieldEffects + 1] = {
    id = Game3.FLDEFF_SPARKLE,
    left = 32, dur = 32,
    x = x, y = y, gx = x, gy = y,
    glitter = true, t = 0,
  }
  return true
end

-- PopSecretBaseBalloon / sub_80C68EC: the balloon's metatile advances by
-- one every 7 frames through +1, +2, +3, with the pop SE on the +2 step.
function Game3:popSecretBaseBalloon(x, y)
  local i = self:gridIndex(self.map, x, y)
  if not i then return false end
  local base = Game3.metatileOf(self.map.grid[i])
  self.fieldEffects = self.fieldEffects or {}
  self.fieldEffects[#self.fieldEffects + 1] = {
    id = Game3.FLDEFF_SECRET_BASE_TIMER,
    left = 22, dur = 22, gx = x, gy = y,
    balloon = base, t = 0, phase = 1,
  }
  return true
end

-- ShatterSecretBaseBreakableDoor / sub_80C69C4: facing south it shatters
-- at once; walking north into it takes 7 frames first. Both leave the same
-- two broken halves.
function Game3:shatterBreakableDoor(x, y)
  if self.facing == "north" then
    self.fieldEffects = self.fieldEffects or {}
    self.fieldEffects[#self.fieldEffects + 1] = {
      id = Game3.FLDEFF_SECRET_BASE_TIMER,
      left = 8, dur = 8, gx = x, gy = y,
      door = true, t = 0,
    }
    return true
  end
  return self:breakDoorNow(x, y)
end

function Game3:breakDoorNow(x, y)
  self:playSe(Game3.SE_BREAKABLE_DOOR)
  self:writeMetatile(x, y, Game3.MT_BROKEN_DOOR_BOTTOM)
  self:writeMetatile(x, y - 1, Game3.MT_BROKEN_DOOR_TOP)
  return true
end

-- PlaySecretBaseMusicNoteMatSound: the note is picked by metatile id, and
-- plays 7 frames after the step.
function Game3:playMusicNoteMat(x, y)
  local i = self:gridIndex(self.map, x, y)
  if not i then return false end
  local se = Game3.MUSIC_NOTE_MAT_SE[Game3.metatileOf(self.map.grid[i])]
  if not se then return false end
  self.fieldEffects = self.fieldEffects or {}
  self.fieldEffects[#self.fieldEffects + 1] = {
    id = Game3.FLDEFF_SECRET_BASE_TIMER,
    left = 8, dur = 8, gx = x, gy = y,
    note = se, t = 0,
  }
  return true
end

-- The delayed halves of the four effects above, ticked from
-- stepFieldEffects the way the ROM's tasks tick off the frame counter.
function Game3:tickSecretBaseDecorEffect(fx, frames)
  if not fx then return end
  local t = (fx.t or 0) + (frames or 1)
  fx.t = t
  if fx.note and not fx.fired and t >= 7 then
    fx.fired = true
    self:playSe(fx.note)
  elseif fx.door and not fx.fired and t >= 7 then
    fx.fired = true
    self:breakDoorNow(fx.gx, fx.gy)
  elseif fx.balloon then
    local phase = fx.phase or 1
    if phase <= 3 and t >= phase * 7 then
      if phase == 2 then
        local se = Game3.BALLOON_SE[fx.balloon]
        if se then self:playSe(se) end
      end
      self:writeMetatile(fx.gx, fx.gy, fx.balloon + phase)
      fx.phase = phase + 1
    end
  elseif fx.glitter and not fx.fired and t >= 8 then
    fx.fired = true
    self:playSe(Game3.SE_M_HEAL_BELL)
  end
end

-- PlayerAvatar_SecretBaseMatSpinStep1's direction table, indexed by the
-- current movementDirection: SOUTH->WEST, NORTH->EAST, WEST->NORTH,
-- EAST->SOUTH, i.e. the facing turns counter-clockwise.
Game3.SPIN_MAT_NEXT = {
  south = "west", west = "north", north = "east", east = "south",
}
Game3.OPPOSITE_DIR = {
  south = "north", north = "south", west = "east", east = "west",
}
-- Frames per beat of either mat, matching the held-movement actions the
-- ROM queues (a jump in place, a face-direction turn, a slow walk).
Game3.MAT_JUMP_FRAMES = 16
Game3.MAT_SPIN_FRAMES = 8

-- field_player_avatar.c ForcedMovement_SecretBaseJumpMat /
-- _SecretBaseSpinMat. Both are entries in sForcedMovementTestFuncs, but
-- GetForcedMovementByMetatileBehavior refuses to look at ALL of them while
-- PLAYER_AVATAR_FLAG_5 is set -- and the jump mat sets that flag when it
-- finishes. PlayerAllowForcedMovementIfMovingSameDirection clears it again
-- once the player is actually moving. Without that latch the mat re-fires
-- every frame you stand on it, which is an inescapable loop.
function Game3:trySecretBaseMat(behavior)
  if self.matEffect then return true end
  if self.forcedMoveLatch then return false end
  if behavior == Game3.MB_SECRET_BASE_JUMP_MAT then
    -- PlayerAvatar_DoSecretBaseMatJump: two jump-in-place actions, then
    -- preventStep goes back off and the latch goes on.
    self.matEffect = { kind = "jump", left = Game3.MAT_JUMP_FRAMES, jumps = 0 }
    self:beginMatJump()
    return true
  end
  if behavior == Game3.MB_SECRET_BASE_SPIN_MAT then
    -- PlayerAvatar_SecretBaseMatSpinStep0: SE_WARP_IN and the controls
    -- lock. data[1] remembers the direction you arrived facing; the spin
    -- ends by walking you one tile the opposite way, so you leave the mat.
    self:playSe(Game3.SE_WARP_IN)
    self.matEffect = {
      kind = "spin",
      left = Game3.MAT_SPIN_FRAMES,
      entry = self.facing or "south",
      turns = 0,
    }
    return true
  end
  return false
end

-- One GetJumpInPlaceMovementAction. drawPlayer arcs the sprite by
-- 8 * sin(walkProgress * pi), and walkProgress is driven off walkCooldown
-- against walkDuration -- so the jump has to run that clock itself. The
-- mat's own early return in walkHeld skips the block that would otherwise
-- tick it, which is why setting only `hopping` produced no visible jump
-- at all.
function Game3:beginMatJump()
  self:playSe(Game3.SE_LEDGE)
  self.hopping = true
  self.walkFromX, self.walkFromY = self.playerX, self.playerY
  self.walkDuration = Game3.MAT_JUMP_FRAMES / 60
  self.walkCooldown = self.walkDuration
end

-- The held-movement queue the two tasks drive, one beat at a time. Called
-- from walkHeld before anything reads the keypad, so the player cannot
-- steer or step out mid-effect -- that is gPlayerAvatar.preventStep.
function Game3:stepSecretBaseMat(dt)
  local m = self.matEffect
  if not m then return false end
  if m.kind == "jump" and (self.walkCooldown or 0) > 0 then
    self.walkCooldown = self.walkCooldown - (dt or 0)
    if self.walkCooldown < 0 then self.walkCooldown = 0 end
  end
  m.left = (m.left or 0) - math.floor((dt or 0) * 60 + 0.0001)
  if m.left > 0 then return true end
  if m.kind == "jump" then
    m.jumps = (m.jumps or 0) + 1
    if m.jumps > 1 then
      -- gPlayerAvatar.unk1 |= 0x20: done, and do not re-trigger until the
      -- player has actually moved off.
      self.hopping = nil
      self.walkCooldown = 0
      self.matEffect = nil
      self.forcedMoveLatch = true
      return false
    end
    m.left = Game3.MAT_JUMP_FRAMES
    self:beginMatJump()
    return true
  end
  -- Spin: turn one step, and stop once it has come all the way round to
  -- the opposite of the entry facing.
  local opposite = Game3.OPPOSITE_DIR[m.entry] or "north"
  m.turns = (m.turns or 0) + 1
  self.facing = Game3.SPIN_MAT_NEXT[self.facing or "south"] or "west"
  if m.turns > 3 and self.facing == opposite then
    -- Step3: GetWalkSlowMovementAction(GetOppositeDirection(entry)) walks
    -- the player off the mat the way they came in.
    self.matEffect = nil
    local dx, dy = Game3.deltaFromFacing(opposite)
    self.facing = opposite
    if not self:tryWalk(dx, dy) then
      -- Nowhere to go: latch instead of spinning forever.
      self.forcedMoveLatch = true
    end
    return false
  end
  m.left = Game3.MAT_SPIN_FRAMES
  return true
end

-- ===================================================================
-- decoration.c: the decoration PC. Task_SecretBasePC_Decoration (special
-- 14) inside a base, DoPlayerPCDecoration from the bedroom PC. Both share
-- sDecorationContext -- which room's slots to work on, and whether it is
-- the player's own room (which only takes DOLLs and CUSHIONs).
-- ===================================================================

-- gUnknown_083EC604 / gUnknown_083EC624: the four options and the line
-- shown under each.
Game3.DECOR_PC_ACTIONS = { "DECORATE", "PUT AWAY", "TOSS", "EXIT" }
Game3.DECOR_PC_NOTES = {
  "Put out the selected decoration item.",
  "Store the chosen decoration in the PC.",
  "Throw away unwanted decorations.",
  "Go back to the\r\nprevious menu.",
}

function Game3:decorContext()
  if self._decorPlayerRoom then
    return self.playerRoomDecor, self.playerRoomDecorPos,
      Game3.DECOR_MAX_PLAYERS_HOUSE, true
  end
  local sb = self.secretBase
  return sb and sb.decorations, sb and sb.decorationPos,
    Game3.DECOR_MAX_SECRET_BASE, false
end

function Game3:secretBasePCDecoration()
  self._decorPlayerRoom = false
  self:openDecorMenu(Game3.DECOR_PC_ACTIONS, "pickDecorPCAction",
    Game3.DECOR_PC_NOTES)
end

-- decoration.c DoPlayerPCDecoration: the same menu on the bedroom PC.
function Game3:playerRoomPCDecoration()
  self._decorPlayerRoom = true
  self:openDecorMenu(Game3.DECOR_PC_ACTIONS, "pickDecorPCAction",
    Game3.DECOR_PC_NOTES)
end

function Game3:openDecorMenu(labels, onPick, notes)
  self:beginScriptWait()
  self.field = {
    kind = "decor_menu",
    labels = labels,
    notes = notes,
    cursor = 0,
    onPick = onPick,
  }
end

-- A message that returns to the PC menu when dismissed, the way every
-- DisplayItemMessageOnField(..., sub_80FE428, 0) in decoration.c does.
function Game3:decorSay(text, back)
  self.field = { kind = "talk", text = text, afterDecor = back ~= false }
end

function Game3:pickDecorPCAction(index)
  if index == 0 then return self:decorateStart() end
  if index == 1 then return self:decorPutAwayStart() end
  if index == 2 then return self:decorTossStart() end
  -- gpu_pal_decompress_alloc_tag_and_upload: EXIT goes back to the PC it
  -- was opened from -- SecretBase_EventScript_PCCancel in a base, and
  -- ReshowPlayerPC in the bedroom.
  if self._decorPlayerRoom then
    self:closeField()
    return
  end
  self:openSecretBasePCMenu()
end

-- sub_80FF160 (DECORATE) and sub_8101700 (TOSS) both refuse up front when
-- you own nothing at all.
function Game3:decorateStart()
  if self:numDecorationsInInventory() == 0 then
    return self:decorSay("There are no decorations.")
  end
  self._decorMode = "decorate"
  self:openDecorCategoryMenu()
end

function Game3:decorTossStart()
  if self:numDecorationsInInventory() == 0 then
    return self:decorSay("There are no decorations.")
  end
  self._decorMode = "toss"
  self:openDecorCategoryMenu()
end

function Game3:openDecorCategoryMenu()
  local labels = {}
  for cat = 0, Game3.DECOR_CATEGORY_COUNT - 1 do
    labels[#labels + 1] = Game3.DECOR_CATEGORY_NAMES[cat]
  end
  labels[#labels + 1] = "CANCEL"
  self:openDecorMenu(labels, "pickDecorCategory")
end

function Game3:pickDecorCategory(index)
  if index >= Game3.DECOR_CATEGORY_COUNT then
    return self:secretBasePCDecorationReopen()
  end
  self._decorCategory = index
  local ids = self:decorationInventoryIds(index)
  if #ids == 0 then
    return self:decorSay("There are no decorations.")
  end
  -- sub_80FE7A8 prints the highlighted decoration's description under the
  -- list, the same way the main menu explains its four options.
  local labels, notes = {}, {}
  for _, id in ipairs(ids) do
    labels[#labels + 1] = self:decorationName(id)
    notes[#notes + 1] = self:decorationDescription(id)
  end
  labels[#labels + 1] = "CANCEL"
  notes[#notes + 1] = "Go back to the\r\nprevious menu."
  self._decorIds = ids
  self:openDecorMenu(labels, "pickDecorItem", notes)
end

function Game3:secretBasePCDecorationReopen()
  if self._decorPlayerRoom then return self:playerRoomPCDecoration() end
  return self:secretBasePCDecoration()
end

-- Which inventory slots of this category are already standing in the room.
-- decoration.c derives gUnknown_020388D6 the same way each time the menu
-- opens: for every placed id, claim the first matching inventory slot that
-- has not been claimed yet.
function Game3:placedDecorInventorySlots(cat)
  local used = {}
  local items = select(1, self:decorContext())
  local list = self:decorationInventory(cat)
  if type(items) ~= "table" then return used end
  for i = 1, #items do
    local id = tonumber(items[i]) or 0
    if id ~= 0 then
      for j = 1, #list do
        if list[j] == id and not used[j] then used[j] = true break end
      end
    end
  end
  return used
end

-- The inventory slot behind entry `index` of decorationInventoryIds(cat) --
-- the two run in the same order, skipping empties.
function Game3.decorSlotForIndex(list, index)
  local n = 0
  for j = 1, #list do
    if list[j] ~= Game3.DECOR_NONE then
      n = n + 1
      if n == index + 1 then return j end
    end
  end
end

function Game3:pickDecorItem(index)
  local ids = self._decorIds or {}
  if index >= #ids then return self:openDecorCategoryMenu() end
  local id = ids[index + 1]
  local cat = self._decorCategory or 0
  local slot = Game3.decorSlotForIndex(self:decorationInventory(cat), index)
  local inUse = self:placedDecorInventorySlots(cat)[slot] and true or false
  if self._decorMode == "toss" then
    if inUse then
      return self:decorSay("This decoration is in use.\r\nIt can't be thrown away.")
    end
    self._decorPending = { id = id, cat = cat, slot = slot }
    self:setStringVar(1, self:decorationName(id))
    return self:openDecorYesNo(
      ("This %s will be discarded.\r\nIs that okay?"):format(self:decorationName(id)),
      "confirmDecorToss")
  end
  return self:beginPlacingDecoration(id, cat, slot, inUse)
end

-- sub_8101848: TOSS clears the inventory slot outright and re-sorts, then
-- says so. It is not RemoveDecorationFromInventory -- the slot is already
-- known, so the id search is skipped.
function Game3:confirmDecorToss()
  local p = self._decorPending
  self._decorPending = nil
  if not p then return end
  self:decorationInventory(p.cat)[p.slot] = Game3.DECOR_NONE
  self:sortDecorationInventory(p.cat)
  self:decorSay("The decoration item was thrown away.")
end

-- sub_80FF5BC, the three gates before the placing avatar mode opens.
function Game3:beginPlacingDecoration(id, cat, slot, inUse)
  local items, _, size, isPlayerRoom = self:decorContext()
  if isPlayerRoom and cat ~= 6 and cat ~= 7 then
    return self:decorSay("This decoration can't be placed in\r\nyour own room.")
  end
  if inUse then
    return self:decorSay("This is in use already.")
  end
  if not Game3.firstFreeDecorSlot(items) then
    self:setStringVar(1, tostring(size))
    return self:decorSay(("No more decorations can be placed.\r\n" ..
      "The most that can be placed is %d."):format(size))
  end
  local x, y = self.playerX or 0, self.playerY or 0
  self.field = nil
  self:endScriptWait()
  self._decorPlacing = {
    id = id, cat = cat, slot = slot,
    x = x, y = y,
  }
end

function Game3.firstFreeDecorSlot(items)
  if type(items) ~= "table" then return nil end
  for i = 1, #items do
    if (tonumber(items[i]) or 0) == Game3.DECOR_NONE then return i end
  end
  return nil
end

-- sub_8100174: claim the first free room slot, storing the decoration id
-- and the packed x/y. Then bake it in, or hand a SOLID_MAT one to
-- sub_80BBDD0's object-event path.
function Game3:commitDecorationPlacement()
  local p = self._decorPlacing
  if not p then return false end
  local items, pos = self:decorContext()
  local i = Game3.firstFreeDecorSlot(items)
  if not i then return false end
  items[i] = p.id
  pos[i] = Game3.decorPosPack(p.x, p.y)
  local info = Game3.decorationInfo(self.data, p.id)
  if info and info.permission == Game3.DECORPERM_SOLID_MAT then
    self:setScriptVar(0x8004, 0)
    self:setScriptVar(0x8005, 0)
    self:spawnMatDecorations()
  else
    self:stampDecoration(p.x, p.y, p.id)
  end
  self._decorPlacing = nil
  return true
end

-- sub_8100A0C (PUT AWAY): pick one of the room's occupied slots, confirm,
-- then clear it. The ROM reloads the map afterwards, which un-bakes the
-- decoration; here initSecretBaseAppearance re-runs off the pristine grid.
function Game3:decorPutAwayStart()
  local items = select(1, self:decorContext())
  local ids, slots = {}, {}
  for i = 1, #(items or {}) do
    local id = tonumber(items[i]) or 0
    if id ~= 0 then
      ids[#ids + 1] = self:decorationName(id)
      slots[#slots + 1] = i
    end
  end
  if #slots == 0 then
    return self:decorSay("There are no decorations in use.")
  end
  ids[#ids + 1] = "CANCEL"
  self._decorPutAwaySlots = slots
  self:openDecorMenu(ids, "pickDecorPutAway")
end

function Game3:pickDecorPutAway(index)
  local slots = self._decorPutAwaySlots or {}
  if index >= #slots then return self:secretBasePCDecorationReopen() end
  self._decorPending = { roomSlot = slots[index + 1] }
  self:openDecorYesNo("Return this decoration to the PC?", "confirmDecorPutAway")
end

function Game3:confirmDecorPutAway()
  local p = self._decorPending
  self._decorPending = nil
  if not p then return end
  local items, pos = self:decorContext()
  items[p.roomSlot] = Game3.DECOR_NONE
  pos[p.roomSlot] = 0
  self:refreshRoomDecorations()
  self:decorSay("The decoration was returned to the PC.")
end

-- What the ROM gets for free by reloading the map: the grid back to its
-- pristine state with only the decorations that are still placed baked in,
-- and the mat object events respawned.
function Game3:refreshRoomDecorations()
  local map = self.map
  if not map then return end
  if Game3.isSecretBaseMap(map) then
    self:initSecretBaseAppearance(map)
  else
    self:restorePristineGrid(map)
    local items, pos = self:decorContext()
    for i = 1, #(items or {}) do
      local id = tonumber(items[i]) or 0
      local info = id > 0 and Game3.decorationInfo(self.data, id)
      if info and info.permission ~= Game3.DECORPERM_SOLID_MAT then
        local x, y = Game3.decorPosXY(pos[i])
        self:stampDecoration(x, y, id, map)
      end
    end
  end
  self:resetNpcs()
  self:setScriptVar(0x8004, 0)
  self:setScriptVar(0x8005, 0)
  self:spawnMatDecorations()
end

-- SetUpPlacingDecorationPlayerAvatar / sub_810065C: the map stays live
-- with a cursor you steer. A offers "Place it here?" when sub_80FFC24
-- allows it, B offers "Cancel decorating?".
function Game3:decorPlacingActive()
  return self._decorPlacing ~= nil and self.field == nil
end

function Game3:stepDecorPlacing()
  local p = self._decorPlacing
  if not p then return end
  local map = self.map
  local dx, dy = 0, 0
  if Input:wasPressed("left") then dx = -1
  elseif Input:wasPressed("right") then dx = 1
  elseif Input:wasPressed("up") then dy = -1
  elseif Input:wasPressed("down") then dy = 1 end
  if dx ~= 0 or dy ~= 0 then
    local nx, ny = p.x + dx, p.y + dy
    if map and nx >= 0 and ny >= 0
        and nx < (map.width or 0) and ny < (map.height or 0) then
      p.x, p.y = nx, ny
    end
    return
  end
  if Input:wasPressed("a") then
    if self:canPlaceDecoration(p.id, p.x, p.y, map) then
      self:openDecorYesNo("Place it here?", "confirmDecorPlacement")
    else
      self:playSe(Game3.SE_FAILURE)
      self:decorSay("It can't be placed here.", false)
    end
  elseif Input:wasPressed("b") then
    self:openDecorYesNo("Cancel decorating?", "cancelDecorPlacement")
  end
end

-- The placing cursor. AddDecorationIconObjectFromObjectEvent shows the
-- decoration itself following the cursor, so this draws its real
-- metatiles -- 0x200 + tiles[i * w + j], out of the map's own atlas, laid
-- out from the BOTTOM-left cell the way sub_80FFC24 measures it -- with a
-- frame tinted by whether that placement would be accepted.
function Game3:drawDecorPlacingCursor(overOverlay)
  if overOverlay then return end
  local p = self._decorPlacing
  if not p then return end
  local info = Game3.decorationInfo(self.data, p.id)
  if not info then return end
  local map = self.map
  local w, h = info.width or 1, info.height or 1
  local ok = self:canPlaceDecoration(p.id, p.x, p.y, map)
  local px = Game3.snapPixel((p.x) * Game3.TILE)
  local py = Game3.snapPixel((p.y - h + 1) * Game3.TILE)
  local sw, sh = w * Game3.TILE, h * Game3.TILE
  -- A DECORPERM_SOLID_MAT decoration is an object event, not grid tiles:
  -- its single "tile" is an OBJ_EVENT_GFX id, so only the frame is drawn.
  local grid = info.permission ~= Game3.DECORPERM_SOLID_MAT
  local image = self.layerBottom
  if grid and map and map.tileset
      and map.tileset ~= (self.map and self.map.tileset) then
    image = self:layersFor(map.tileset)
  end
  self:drawStandingAt(px, py, sw, sh, function()
    local G = love.graphics
    if grid and image then
      G.setColor(1, 1, 1, 1)
      for i = 0, h - 1 do
        for j = 0, w - 1 do
          local tile = tonumber((info.tiles or {})[i * w + j + 1]) or 0
          local mid = Game3.DECOR_TILE_BASE + tile
          G.draw(image, self:quadFor(mid, image),
            px + j * Game3.TILE, py + i * Game3.TILE)
        end
      end
      if self.layerTop then
        for i = 0, h - 1 do
          for j = 0, w - 1 do
            local tile = tonumber((info.tiles or {})[i * w + j + 1]) or 0
            local mid = Game3.DECOR_TILE_BASE + tile
            G.draw(self.layerTop, self:quadFor(mid, self.layerTop),
              px + j * Game3.TILE, py + i * Game3.TILE)
          end
        end
      end
    end
    if ok then G.setColor(0.35, 0.95, 0.45, 0.75)
    else G.setColor(0.95, 0.30, 0.24, 0.75) end
    G.rectangle("line", px + 0.5, py + 0.5, sw - 1, sh - 1)
    G.rectangle("line", px + 1.5, py + 1.5, sw - 3, sh - 3)
    G.setColor(1, 1, 1, 1)
  end)
end

function Game3:confirmDecorPlacement()
  self:commitDecorationPlacement()
  self:secretBasePCDecorationReopen()
end

function Game3:cancelDecorPlacement()
  self._decorPlacing = nil
  self:secretBasePCDecorationReopen()
end

-- `plain` marks a prompt that is not part of the decoration PC at all. The NO
-- branch below drops back into the DECORATE menu, which is right for the PC's
-- own refusals but not for the two callers that merely borrowed this yes/no
-- box: saying no to "Would you like to use DIVE?" or to the POKeBLOCK FEEDER
-- opened the secret base decoration menu on top of the map.
function Game3:openDecorYesNo(text, onYes, plain)
  self.field = {
    kind = "decor_yesno",
    text = text,
    cursor = 0,
    boxX = Game3.YESNO_LEFT,
    boxY = Game3.YESNO_TOP,
    onYes = onYes,
    plain = plain or nil,
  }
end

function Game3:answerDecorYesNo(yes)
  local f = self.field
  self.field = nil
  if yes and f and f.onYes and self[f.onYes] then
    self[f.onYes](self, f)
  elseif f and f.plain then
    -- Not a decoration prompt: NO just closes, the way the cart's
    -- UseDiveScript and the POKeBLOCK FEEDER both end on their no branch.
    self.field = nil
  elseif self._decorPlacing then
    -- gSecretBaseText_CancelDecorating's NO just returns to the cursor.
    self.field = nil
  else
    self:secretBasePCDecorationReopen()
  end
end

-- secret_base.c sub_80BBDD0. Walks the room's decoration slots -- the
-- base's 16 when standing in one, the bedroom's 12 otherwise -- and for
-- every DECORPERM_SOLID_MAT entry claims the next decoration object slot
-- (the one whose flagId is 0xAE + VAR_0x8004), points its GFX_VAR_n at the
-- decoration's OW graphics id, clears the hide flag and moves it onto the
-- stored tile. Slots whose tile is not a large-mat edge/centre are skipped
-- without consuming a sprite, exactly as the ROM does.
--
-- The ROM reads the behaviour at (x + 7, y + 7) because its lookup is in
-- MapGrid space; decorationPos and this engine's grid are both map-local,
-- so no MAP_OFFSET is added back here.
function Game3:spawnMatDecorations()
  local map = self.map
  if not map then return end
  local inBase = Game3.isSecretBaseMap(map)
  local decor, pos, ndecor
  if inBase then
    local sb = self.secretBase
    if type(sb) ~= "table" then return end
    decor, pos = sb.decorations, sb.decorationPos
    ndecor = Game3.DECOR_MAX_SECRET_BASE
  else
    decor, pos = self.playerRoomDecor, self.playerRoomDecorPos
    ndecor = Game3.DECOR_MAX_PLAYERS_HOUSE
  end
  if type(decor) ~= "table" then return end
  local objects = map.objects or {}
  local slot = self:varGet(Gen3Script.VAR_0x8004) or 0
  for i = 1, ndecor do
    local id = tonumber(decor[i]) or Game3.DECOR_NONE
    if id ~= Game3.DECOR_NONE then
      local info = Game3.decorationInfo(self.data, id)
      if info and info.permission == Game3.DECORPERM_SOLID_MAT then
        local want = Game3.SECRET_BASE_DECOR_FLAG_BASE + slot
        local obj
        for j = 1, #objects do
          if objects[j] and objects[j].flagId == want then obj = objects[j] break end
        end
        if obj then
          local x, y = Game3.decorPosXY(pos and pos[i])
          local b = self:behaviorAt(map, x, y)
          if b == Game3.MB_SECRET_BASE_LARGE_MAT_EDGE
              or b == Game3.MB_LARGE_MAT_CENTER then
            local gid = tonumber(obj.graphicsId) or 0
            if gid >= Game3.GFX_VAR_0 and gid <= Game3.GFX_VAR_F then
              self:setScriptVar(Game3.VAR_OBJ_GFX_ID_0 + (gid - Game3.GFX_VAR_0),
                info.gfx or 0)
            end
            self:addObject(obj.localId)
            self:setObjectXYPerm(obj.localId, x, y)
            slot = slot + 1
            self:setScriptVar(Gen3Script.VAR_0x8004, slot)
          end
        end
      end
    end
  end
end

-- secret_base.c MoveOutOfSecretBase: IncrementGameStat then sub_80BC440.
-- shared_secret_base.inc SecretBase_EventScript_PCPackUp -- the base PC's
-- PACK UP option, after "All decorations will be returned" -- so this wipes
-- the record and puts you back outside rather than just walking you out.
-- ClearSecretBase only zeroes the slots; nothing is credited back to the
-- owned-decoration counts, which is a placement-time question anyway since
-- nothing can be placed yet. Script is `special / releaseall / end`, no
-- waitstate, so like the decline branch this holds nothing.
function Game3:moveOutOfSecretBase()
  self:incrementGameStat(Game3.GAME_STAT_MOVED_SECRET_BASE)
  self:resetSecretBaseSpecial()
end

-- secret_base.c sub_80BC440: ResetSecretBase(0) (ClearSecretBase wipes the
-- record) then sub_80BC0F8 -- FadeScreen(1, 0) plus sub_80BC074, which on
-- the far side of the fade restores the saved outdoor warp and reloads it.
-- This is the FirstEntrance decline branch: the base you are standing in is
-- un-made and you are put back where you used Secret Power. The script ends
-- right after the special with no waitstate, so nothing is held here.
function Game3:resetSecretBaseSpecial()
  local sb = self.secretBase
  -- The ROM keeps the way out in saved warp2 (special 8 set it before
  -- warping in); here it rides on the record, so take it before clearing.
  if sb then
    self.secretBaseExit = {
      mapId = sb.mapId,
      x = sb.outX or sb.x or 0,
      y = sb.outY or sb.y or 0,
    }
  end
  self.secretBase = nil
  self:setCurrentSecretBaseVar()
  self:beginScreenFade(Game3.FADE_TO_BLACK)
  self.secretBaseResetLeft = Game3.FADE_FRAMES
end

-- secret_base.c sub_80BC474: seal the entrance of the base you are leaving.
-- Finds this map's BG_EVENT_SECRET_BASE whose id matches your record and
-- swaps its tile from the open half of its gUnknown_083D1358 pair back to
-- the closed one. Only the open->closed direction, unlike
-- SetOpenedSecretBaseMetatile's two passes.
function Game3:closeSecretBaseEntrance(map)
  map = map or self.map
  local sb = self.secretBase
  if not (map and sb) then return false end
  for _, ev in ipairs(map.bgEvents or {}) do
    if ev.kind == Game3.BG_SECRET_BASE
        and (tonumber(ev.secretBaseId) or -1) == (tonumber(sb.id) or -2) then
      local gx = ev.x + Game3.MAP_OFFSET
      local gy = ev.y + Game3.MAP_OFFSET
      local tile = self:mapGridGetMetatileId(gx, gy)
      for _, pair in ipairs(Game3.SECRET_BASE_ENTRANCE_TILES) do
        if pair[2] == tile then
          self:mapGridSetMetatileId(gx, gy,
            pair[1] + Game3.MAPGRID_COLLISION_MASK)
          return true
        end
      end
      return false
    end
  end
  return false
end

-- secret_base.c SetOccupiedSecretBaseEntranceMetatiles, run on every map
-- load: any BG_EVENT_SECRET_BASE that matches a record you hold is drawn
-- with its entrance already open, so your own base stays dug when you come
-- back to the route.
-- The ROM only has to open the owned one, because the rest come back
-- closed with the freshly loaded layout. Here the grid is a shared cached
-- table that keeps whatever was last written to it, so every entrance on
-- the map is set explicitly: open if it is yours, closed otherwise.
function Game3:setOccupiedSecretBaseEntranceMetatiles(map)
  map = map or self.map
  if type(map) ~= "table" then return end
  local ownId = self.secretBase and tonumber(self.secretBase.id)
  for _, ev in ipairs(map.bgEvents or {}) do
    if ev.kind == Game3.BG_SECRET_BASE then
      local gx = ev.x + Game3.MAP_OFFSET
      local gy = ev.y + Game3.MAP_OFFSET
      local tile = self:mapGridGetMetatileId(gx, gy)
      local want = ((tonumber(ev.secretBaseId) or -1) == (ownId or -2)) and 2 or 1
      for _, pair in ipairs(Game3.SECRET_BASE_ENTRANCE_TILES) do
        if pair[1] == tile or pair[2] == tile then
          if pair[want] ~= tile then
            self:mapGridSetMetatileId(gx, gy,
              pair[want] + Game3.MAPGRID_COLLISION_MASK)
          end
          break
        end
      end
    end
  end
end

-- special 330 MoveSecretBase: close the old entrance, count the move, then
-- ResetSecretBase(0) -- keeping only numSecretBasesReceived. The record is
-- WIPED here; the new one is written afterwards by EventScript_1A2DB8's
-- sub_80BB8CC, once you actually use SECRET POWER on the new spot.
function Game3:moveSecretBaseSpecial()
  self:closeSecretBaseEntrance()
  self:incrementGameStat(Game3.GAME_STAT_MOVED_SECRET_BASE)
  local received = (self.secretBase and self.secretBase.numSecretBasesReceived) or 0
  self.secretBase = nil
  self._secretBasesReceived = received
  self:setCurrentSecretBaseVar()
end

function Game3:canRegisterItem(id)
  return self:itemPocket(id) == Game3.POCKET_KEY
end

function Game3:toggleRegisteredItem(id)
  id = tonumber(id) or 0
  if not self:canRegisterItem(id) then
    return false, "It can't be registered."
  end
  if (self.registeredItem or 0) == id then
    self.registeredItem = 0
    return true, "SELECT icon was removed."
  end
  self.registeredItem = id
  return true, "Registered to SELECT."
end

function Game3:useRegisteredItem()
  local id = tonumber(self.registeredItem) or 0
  if id < 1 or self:itemCount(id) < 1 then
    self.registeredItem = 0
    self.field = { kind = "talk", text = Game3.TEXT_NO_REGISTERED_ITEM }
    return true
  end
  local _, msg = self:useFieldItem(id)
  if type(msg) == "string" and msg ~= "" then
    self.field = { kind = "talk", text = msg }
  end
  return true
end

function Game3:rotatingGatePuzzleType()
  local map = self.map
  if not map then return 0 end
  local id = map.id
  if id == Game3.mapId(Game3.MAP_FORTREE_GYM_GROUP, Game3.MAP_FORTREE_GYM_NUM)
      or (map.group == Game3.MAP_FORTREE_GYM_GROUP
        and map.index == Game3.MAP_FORTREE_GYM_NUM) then
    return Game3.PUZZLE_FORTREE
  end
  if id == Game3.mapId(Game3.MAP_TRICK_HOUSE_PUZZLE6_GROUP,
        Game3.MAP_TRICK_HOUSE_PUZZLE6_NUM)
      or (map.group == Game3.MAP_TRICK_HOUSE_PUZZLE6_GROUP
        and map.index == Game3.MAP_TRICK_HOUSE_PUZZLE6_NUM) then
    return Game3.PUZZLE_TRICK_HOUSE_6
  end
  return 0
end

function Game3:rotatingGateConfig()
  local kind = self:rotatingGatePuzzleType()
  if kind == Game3.PUZZLE_FORTREE then return Game3.ROTATING_GATE_FORTREE end
  if kind == Game3.PUZZLE_TRICK_HOUSE_6 then
    return Game3.ROTATING_GATE_TRICK_HOUSE
  end
end

function Game3:rotatingGateLoadConfig()
  local cfg = self:rotatingGateConfig()
  self.rotatingGates = cfg
  if not cfg then
    self.rotatingGateOrients = nil
    return
  end
  if not self.rotatingGateOrients then self.rotatingGateOrients = {} end
end

function Game3:rotatingGateResetOrients()
  local cfg = self.rotatingGates
  if not cfg then return end
  local orients = {}
  for i = 1, #cfg do
    orients[i] = cfg[i][4] or 0
  end
  self.rotatingGateOrients = orients
end

function Game3:rotatingGateInitPuzzle()
  self:rotatingGateLoadConfig()
  self:rotatingGateResetOrients()
end

function Game3:rotatingGateInitGfx()
  self:rotatingGateLoadConfig()
  if self.rotatingGates and not self.rotatingGateOrients then
    self:rotatingGateResetOrients()
  end
end

function Game3:rotatingGateOrient(gateId)
  local orients = self.rotatingGateOrients
  if not orients then return 0 end
  return orients[gateId] or 0
end

function Game3:rotatingGateSetOrient(gateId, ori)
  self.rotatingGateOrients = self.rotatingGateOrients or {}
  self.rotatingGateOrients[gateId] = (tonumber(ori) or 0) % 4
end

function Game3:rotatingGateHasArm(gateId, arm, isLong)
  local cfg = self.rotatingGates
  local gate = cfg and cfg[gateId]
  if not gate then return false end
  local layout = Game3.ROTATING_GATE_ARMS[(gate[3] or 0) + 1]
  if not layout then return false end
  local face = ((tonumber(arm) or 0) - self:rotatingGateOrient(gateId) + 4) % 4
  local longBit = 0
  if isLong == true or isLong == 1 then longBit = 1 end
  local idx = face * 2 + longBit + 1
  return layout[idx] == 1
end

function Game3:rotatingGateCanRotate(gateId, dir)
  local cfg = self.rotatingGates
  local gate = cfg and cfg[gateId]
  if not gate then return false end
  local armPos
  if dir == Game3.ROTATE_ACW then
    armPos = Game3.ROTATING_GATE_ACW_POS
  elseif dir == Game3.ROTATE_CW then
    armPos = Game3.ROTATING_GATE_CW_POS
  else
    return false
  end
  local layout = Game3.ROTATING_GATE_ARMS[(gate[3] or 0) + 1]
  if not layout then return false end
  local gx = gate[1] + Game3.MAP_OFFSET
  local gy = gate[2] + Game3.MAP_OFFSET
  local orientation = self:rotatingGateOrient(gateId)
  for i = 0, 3 do
    for j = 0, 1 do
      if layout[i * 2 + j + 1] == 1 then
        local armIndex = 2 * ((orientation + i) % 4) + j
        local pos = armPos[armIndex + 1]
        if self:mapGridGetCollision(gx + pos[1], gy + pos[2]) == 1 then
          return false
        end
      end
    end
  end
  return true
end

function Game3:rotatingGateRotate(gateId, dir)
  local ori = self:rotatingGateOrient(gateId)
  if dir == Game3.ROTATE_ACW then
    if ori ~= 0 then
      ori = ori - 1
    else
      ori = Game3.GATE_ORIENTATION_270
    end
  else
    ori = (ori + 1) % 4
  end
  self:rotatingGateSetOrient(gateId, ori)
end

function Game3:rotatingGateRotationInfo(direction, cx, cy)
  if cx < 0 or cx > 3 or cy < 0 or cy > 3 then
    return Game3.GATE_ROT_NONE
  end
  local ptr
  if direction == Game3.DIR_NORTH then
    ptr = Game3.ROTATING_GATE_INFO_NORTH
  elseif direction == Game3.DIR_SOUTH then
    ptr = Game3.ROTATING_GATE_INFO_SOUTH
  elseif direction == Game3.DIR_WEST then
    ptr = Game3.ROTATING_GATE_INFO_WEST
  elseif direction == Game3.DIR_EAST then
    ptr = Game3.ROTATING_GATE_INFO_EAST
  else
    return Game3.GATE_ROT_NONE
  end
  return ptr[cy * 4 + cx + 1] or Game3.GATE_ROT_NONE
end

-- field_player_avatar.c: dest is MapGrid. Returns true when the step is
-- blocked (collision 8). A successful spin still lets the player through.
function Game3:checkRotatingGateCollision(x, y, direction)
  if self:rotatingGatePuzzleType() == 0 then return false end
  local cfg = self.rotatingGates or self:rotatingGateConfig()
  if not cfg then return false end
  if not self.rotatingGates then self.rotatingGates = cfg end
  local gx = (tonumber(x) or 0) + Game3.MAP_OFFSET
  local gy = (tonumber(y) or 0) + Game3.MAP_OFFSET
  for i = 1, #cfg do
    local gateX = cfg[i][1] + Game3.MAP_OFFSET
    local gateY = cfg[i][2] + Game3.MAP_OFFSET
    if gateX - 2 <= gx and gx <= gateX + 1
        and gateY - 2 <= gy and gy <= gateY + 1 then
      local info = self:rotatingGateRotationInfo(
        direction, gx - gateX + 2, gy - gateY + 2)
      if info ~= Game3.GATE_ROT_NONE then
        local spin = math.floor(info / 16) % 16
        local armInfo = info % 16
        local arm = math.floor(armInfo / 2)
        local long = (armInfo % 2) == 1
        if self:rotatingGateHasArm(i, arm, long) then
          if self:rotatingGateCanRotate(i, spin) then
            self:rotatingGateRotate(i, spin)
            return false
          end
          return true
        end
      end
    end
  end
  return false
end

Game3.GATE_SHAPE_L1 = 0
Game3.GATE_SHAPE_T1 = 4
-- StartSpriteAffineAnim: 0 / -64 / -128 / +64. 256 units = 360°.
Game3.ROTATING_GATE_AFFINE = { [0] = 0, [1] = -64, [2] = -128, [3] = 64 }
function Game3.rotatingGateSize(shape)
  shape = tonumber(shape) or 0
  if shape == Game3.GATE_SHAPE_L1 or shape == Game3.GATE_SHAPE_T1 then
    return 32
  end
  return 64
end
function Game3.rotatingGateAngle(ori)
  local a = Game3.ROTATING_GATE_AFFINE[(tonumber(ori) or 0) % 4]
  -- ROTATING_GATE_AFFINE is the raw GBA StartSpriteAffineAnim argument,
  -- where -64 is a clockwise quarter turn. love.graphics.draw's rotation
  -- is signed the other way (positive = clockwise on screen), and
  -- rotatingGateRotate's orientation already increases clockwise per the
  -- arm-layout math (face = (arm - orientation) % 4 walks N,E,S,W as
  -- orientation counts up) -- so the GBA sign has to be flipped here or
  -- the sprite spins opposite the collision state ("switches facing the
  -- wrong way").
  return -a * math.pi / 128
end

-- GBA affine OBJ: sub_8060388 sets sprite->x/y on the config map tile, then
-- OAM draws at sprite->x + centerToCornerVec (negative half the sprite size).
-- The rotation pivot sits on that tile corner, not on the graphic's top-left.
function Game3.rotatingGateDrawArgs(gx, gy, iw, ih, ori, tile)
  tile = tile or Game3.TILE
  local ox, oy = (iw or 0) / 2, (ih or 0) / 2
  return gx * tile, gy * tile, Game3.rotatingGateAngle(ori), ox, oy
end

function Game3:drawRotatingGates()
  if self:rotatingGatePuzzleType() ~= 0 and not self.rotatingGates then
    self:rotatingGateInitGfx()
  end
  local cfg = self.rotatingGates
  if not cfg or not love or not love.graphics then return end
  local G = love.graphics
  local t = Game3.TILE
  G.setColor(1, 1, 1, 1)
  for i = 1, #cfg do
    local gx, gy, shape = cfg[i][1], cfg[i][2], cfg[i][3] or 0
    local img = self:cinemaPic("rotatingGate" .. shape)
    if img then
      local iw, ih = img:getDimensions()
      local x, y, angle, ox, oy = Game3.rotatingGateDrawArgs(
        gx, gy, iw, ih, self:rotatingGateOrient(i), t)
      G.draw(img, x, y, angle, 1, 1, ox, oy)
    end
  end
end

function Game3:hasEnoughMoneyFor()
  local need = tonumber(self:varGet(0x8005)) or 0
  if (self.money or 0) >= need then return 1 end
  return 0
end

function Game3:payMoneyFor()
  local need = tonumber(self:varGet(0x8005)) or 0
  local n = (self.money or 0) - need
  if n < 0 then n = 0 end
  self.money = n
end

function Game3:getPriceReduction(kind)
  kind = tonumber(kind) or 0
  if kind == 0 then return false end
  return false
end

function Game3:getSlotMachineId()
  local slot = tonumber(self:varGet(0x8004)) or 0
  local salt = Game3.SLOT_MACHINE_SALT[(slot % 12) + 1] or 0
  local pair = self.easyChatPairs and self.easyChatPairs[1]
  local extra = 0
  if type(pair) == "table" then
    extra = (tonumber(pair[1]) or 0) + (tonumber(pair[2]) or 0)
  end
  local v0 = extra + salt
  local table_ = Game3.SLOT_MACHINE_NORMAL
  if self:getPriceReduction(2) then
    table_ = Game3.SLOT_MACHINE_DISCOUNT
  end
  return table_[(v0 % 12) + 1] or 0
end

function Game3:getCoins()
  local n = tonumber(self.coins) or 0
  if n < 0 then n = 0 end
  if n > Game3.MAX_COINS then n = Game3.MAX_COINS end
  return n
end

function Game3:addCoins(n)
  n = tonumber(n) or 0
  if n < 0 then n = 0 end
  if self:getCoins() >= Game3.MAX_COINS then return false end
  local sum = self:getCoins() + n
  if sum > Game3.MAX_COINS then sum = Game3.MAX_COINS end
  self.coins = sum
  return true
end

function Game3:removeCoins(n)
  n = tonumber(n) or 0
  if n < 0 then n = 0 end
  if self:getCoins() < n then return false end
  self.coins = self:getCoins() - n
  return true
end

function Game3:showCoinsBox(x, y)
  self.coinsBox = { x = tonumber(x) or 0, y = tonumber(y) or 0 }
end

function Game3:hideCoinsBox()
  self.coinsBox = nil
end

function Game3:updateCoinsBox()
  if self.coinsBox then return true end
end

function Game3:checkCoinsVar(varId)
  self:setScriptVar(varId, self:getCoins())
  return self:getCoins()
end

function Game3:addCoinsScript(n)
  if self:addCoins(n) then return 0 end
  return 1
end

function Game3:removeCoinsScript(n)
  if self:removeCoins(n) then return 0 end
  return 1
end

function Game3:initTimeBasedEvents()
  self.flags = self.flags or {}
  self.flags[Game3.FLAG_SYS_CLOCK_SET] = true
  local t = self:localTime()
  self:setScriptVar(Game3.VAR_DAYS, t.days)
  self.lastBerryTreeUpdate = {
    days = t.days, hours = t.hours, minutes = t.minutes,
  }
end

function Game3:rtcInitLocalTimeOffset(hours, minutes)
  hours = tonumber(hours) or 0
  minutes = tonumber(minutes) or 0
  if hours < 0 then hours = 0 elseif hours > 23 then hours = 23 end
  if minutes < 0 then minutes = 0 elseif minutes > 59 then minutes = 59 end
  self.clockHour = hours
  self.clockMinute = minutes
  self.clockAnchor = os.time()
end

function Game3:localTime()
  local hours = tonumber(self.clockHour) or 0
  local minutes = tonumber(self.clockMinute) or 0
  local anchor = tonumber(self.clockAnchor)
  local elapsed = 0
  if anchor then
    elapsed = os.time() - anchor
    if elapsed < 0 then elapsed = 0 end
  end
  local total = hours * 60 + minutes + math.floor(elapsed / 60)
  local days = math.floor(total / (24 * 60))
  total = total % (24 * 60)
  return {
    days = days,
    hours = math.floor(total / 60),
    minutes = total % 60,
  }
end

function Game3:clockString(t)
  t = t or self:localTime()
  local h = t.hours or 0
  local period = "AM"
  if h >= 12 then period = "PM" end
  local h12 = h % 12
  if h12 == 0 then h12 = 12 end
  return ("%d:%02d %s"):format(h12, t.minutes or 0, period)
end

function Game3:startWallClock()
  -- Rival bedroom must not run the setter during intro. If a script still
  -- reaches here, abort it so post-waitstate flag writes cannot steal Mom /
  -- movers / VAR_LITTLEROOT_INTRO_STATE.
  if not self:isPlayerBedroomMap(self.map)
      and not (self.flags and self.flags[Game3.FLAG_SET_WALL_CLOCK]) then
    self._wallClockStubIntro = nil
    self._scriptPause = nil
    self:endScriptRun()
    self.field = { kind = "talk", text = "It's a wall clock." }
    return
  end
  self:beginScriptWait()
  -- WallClockInit: BeginNormalPaletteFade(..., 16, 0, RGB_BLACK).
  self:fadeInFromBlack()
  self.field = {
    kind = "clock_set",
    hours = 10,
    minutes = 0,
  }
end

function Game3:viewWallClock()
  self:beginScriptWait()
  self:fadeInFromBlack()
  self.field = { kind = "clock_view" }
end

function Game3:confirmWallClock()
  local f = self.field
  local hours = (f and f.hours) or 10
  local minutes = (f and f.minutes) or 0
  self:rtcInitLocalTimeOffset(hours, minutes)
  self:initTimeBasedEvents()
  -- No-script stub path: scripts normally set these after StartWallClock
  -- waitstate. Only the player bedroom stub may own intro / movers.
  if self._wallClockStubIntro then
    self._wallClockStubIntro = nil
    if self:isPlayerBedroomMap(self.map) then
      self:applyWallClockIntroFlags()
    end
  end
  -- The setter froze the leftover step into the clock; that lerp is not
  -- script movement. Drop it so waitstate can resume.
  self.walkCooldown = 0
  self.field = nil
  -- CB2_ReturnToFieldContinueScriptPlayMapMusic fades the bedroom back in.
  -- Without this the script's FADE_TO_BLACK holds forever.
  self:fadeInFromBlack()
  self:endScriptWait()
end

function Game3:closeWallClock()
  self.field = nil
  self:fadeInFromBlack()
  self:endScriptWait()
end

function Game3:advanceClock(dir)
  local f = self.field
  if not f then return end
  local h = f.hours or 0
  local m = f.minutes or 0
  if dir < 0 then
    if m > 0 then
      m = m - 1
    else
      m = 59
      if h > 0 then h = h - 1 else h = 23 end
    end
  else
    if m < 59 then
      m = m + 1
    else
      m = 0
      if h < 23 then h = h + 1 else h = 0 end
    end
  end
  f.hours, f.minutes = h, m
end

function Game3.slotMatch(c1, c2, c3)
  c1, c2, c3 = tonumber(c1) or 0, tonumber(c2) or 0, tonumber(c3) or 0
  if c1 == c2 and c1 == c3 then
    return Game3.SLOT_SYM_TO_MATCH[c1 + 1] or Game3.SLOT_MATCH_NONE
  end
  if c1 == Game3.SLOT_TAG_7_RED and c2 == Game3.SLOT_TAG_7_RED
      and c3 == Game3.SLOT_TAG_7_BLUE then
    return Game3.SLOT_MATCH_777_MIXED
  end
  if c1 == Game3.SLOT_TAG_7_BLUE and c2 == Game3.SLOT_TAG_7_BLUE
      and c3 == Game3.SLOT_TAG_7_RED then
    return Game3.SLOT_MATCH_777_MIXED
  end
  if c1 == Game3.SLOT_TAG_CHERRY then return Game3.SLOT_MATCH_1CHERRY end
  return Game3.SLOT_MATCH_NONE
end

function Game3.slotPayout(match)
  match = tonumber(match)
  if not match or match == Game3.SLOT_MATCH_NONE then return 0 end
  return Game3.SLOT_PAYOUTS[match + 1] or 0
end

function Game3:slotReelWindow(reel, start)
  local strip = Game3.SLOT_REELS[reel]
  start = (tonumber(start) or 0) % 21
  local top = strip[start + 1]
  local mid = strip[(start + 1) % 21 + 1]
  local bot = strip[(start + 2) % 21 + 1]
  return { top, mid, bot }
end

function Game3:slotScore(windows, bet)
  bet = tonumber(bet) or 1
  local pay = 0
  local replay = false
  local function take(match, mode)
    if match == Game3.SLOT_MATCH_NONE then return end
    if mode == "tb" and match == Game3.SLOT_MATCH_1CHERRY then
      match = Game3.SLOT_MATCH_2CHERRY
    end
    if mode == "diag" and match == Game3.SLOT_MATCH_1CHERRY then return end
    pay = pay + Game3.slotPayout(match)
    if match == Game3.SLOT_MATCH_REPLAY then replay = true end
  end
  local w1, w2, w3 = windows[1], windows[2], windows[3]
  take(Game3.slotMatch(w1[2], w2[2], w3[2]), "center")
  if bet > 1 then
    take(Game3.slotMatch(w1[1], w2[1], w3[1]), "tb")
    take(Game3.slotMatch(w1[3], w2[3], w3[3]), "tb")
  end
  if bet > 2 then
    take(Game3.slotMatch(w1[1], w2[2], w3[3]), "diag")
    take(Game3.slotMatch(w1[3], w2[2], w3[1]), "diag")
  end
  return pay, replay
end

function Game3.slotBitAnd(a, b)
  local r, p = 0, 1
  a, b = math.floor(tonumber(a) or 0), math.floor(tonumber(b) or 0)
  while a > 0 and b > 0 do
    if a % 2 == 1 and b % 2 == 1 then r = r + p end
    a, b, p = math.floor(a / 2), math.floor(b / 2), p * 2
  end
  return r
end

function Game3.slotBitOr(a, b)
  local r, p = 0, 1
  a, b = math.floor(tonumber(a) or 0), math.floor(tonumber(b) or 0)
  while a > 0 or b > 0 do
    if a % 2 == 1 or b % 2 == 1 then r = r + p end
    a, b, p = math.floor(a / 2), math.floor(b / 2), p * 2
  end
  return r
end

function Game3.slotBitClear(a, mask)
  return Game3.slotBitAnd(a, 255 - Game3.slotBitAnd(mask, 255))
end

function Game3:playSlotMachine(id)
  id = tonumber(id) or 0
  if id < 0 then id = 0 elseif id > 5 then id = id % 6 end
  self:beginScriptWait()
  self.field = {
    kind = "slots",
    machine = id,
    bet = 1,
    replay = false,
    pikaPower = 0,
    luckyGame = (self:gbaRandom() % 2) == 1,
    bias = 0,
    reelTimeLeft = 0,
  }
end

function Game3:closeSlots()
  self.field = nil
  self:endScriptWait()
end

function Game3.slotBiasSymbol(bias)
  bias = tonumber(bias) or 0
  for i = 1, 8 do
    if bias % 2 == 1 then
      return Game3.SLOT_BIAS_SYMBOLS[i] or 0
    end
    bias = math.floor(bias / 2)
  end
  return 0
end

function Game3:slotRollByte()
  return self:gbaRandom() % 256
end

function Game3:slotDrawMachineBias(f)
  f = f or self.field
  if not f then return 0 end
  -- Sticky straight/mixed 7 survive between spins; everything else clears.
  local bias = Game3.slotBitAnd(f.bias or 0, Game3.SLOT_BIAS_7)
  if (f.reelTimeLeft or 0) > 0 then
    f.bias = bias
    return bias
  end
  local machine = (f.machine or 0) % 6
  local bet = f.bet or 1
  if bet < 1 then bet = 1 elseif bet > 3 then bet = 3 end
  if Game3.slotBitAnd(bias, Game3.SLOT_BIAS_7) == 0 then
    local oddsRow = Game3.SLOT_SPECIAL_DRAW_ODDS[machine + 1] or { 1, 1, 12 }
    if (oddsRow[bet] or 0) > self:slotRollByte() then
      local which = 3
      for i = 1, 3 do
        local row = Game3.SLOT_BIAS_SPECIAL_PROBS[i]
        local value = (row and row[machine + 1]) or 0
        if value > self:slotRollByte() then
          which = i - 1
          break
        end
      end
      if which < 3 then
        bias = Game3.slotBitOr(bias, Game3.SLOT_BIAS_SPECIAL_FLAGS[which + 1] or 0)
        if which ~= 1 then
          f.bias = bias
          return bias
        end
      end
    end
    local which = 5
    for i = 1, 5 do
      local row = Game3.SLOT_BIAS_REGULAR_PROBS[i]
      local value = (row and row[machine + 1]) or 0
      if i == 1 and f.luckyGame then
        value = value + 10
        if value > 256 then value = 256 end
      elseif i == 5 and f.luckyGame then
        value = value - 10
        if value < 0 then value = 0 end
      end
      if value > self:slotRollByte() then
        which = i - 1
        break
      end
    end
    if which < 5 then
      bias = Game3.slotBitOr(bias, Game3.SLOT_BIAS_REGULAR_FLAGS[which + 1] or 0)
    end
  end
  f.bias = bias
  return bias
end

function Game3:slotReelTimeProb(spins, f)
  f = f or self.field
  local pp = f and f.pikaPower or 0
  if pp < 0 then pp = 0 elseif pp > 16 then pp = 16 end
  local table_ = (f and f.luckyGame) and Game3.SLOT_REELTIME_LUCKY
      or Game3.SLOT_REELTIME_NORMAL
  local row = table_[spins + 1]
  return (row and row[pp + 1]) or 0
end

function Game3:slotDrawReelTime(f)
  f = f or self.field
  if not f then return 0 end
  if self:slotRollByte() < self:slotReelTimeProb(0, f) then
    return 0
  end
  for spins = 5, 1, -1 do
    if self:slotRollByte() < self:slotReelTimeProb(spins, f) then
      return spins
    end
  end
  return 0
end

function Game3:slotWindowsMatchBias(wins, bias, bet)
  if not wins or (bias or 0) == 0 then return false end
  local pay, replay = self:slotScore(wins, bet)
  if Game3.slotBitAnd(bias, Game3.SLOT_BIAS_STRAIGHT_7) ~= 0 then
    local m = Game3.slotMatch(wins[1][2], wins[2][2], wins[3][2])
    return m == Game3.SLOT_MATCH_777_RED or m == Game3.SLOT_MATCH_777_BLUE
  end
  if Game3.slotBitAnd(bias, Game3.SLOT_BIAS_MIXED_7) ~= 0 then
    return Game3.slotMatch(wins[1][2], wins[2][2], wins[3][2])
        == Game3.SLOT_MATCH_777_MIXED
  end
  if Game3.slotBitAnd(bias, Game3.SLOT_BIAS_REPLAY) ~= 0 then
    return replay
  end
  if Game3.slotBitAnd(bias, Game3.SLOT_BIAS_CHERRY) ~= 0 then
    return pay >= 2
  end
  local sym = Game3.slotBiasSymbol(bias)
  local m = Game3.slotMatch(wins[1][2], wins[2][2], wins[3][2])
  if sym == Game3.SLOT_TAG_POWER then
    return m == Game3.SLOT_MATCH_POWER
  end
  if sym == Game3.SLOT_TAG_AZURILL then
    return m == Game3.SLOT_MATCH_AZURILL
  end
  if sym == Game3.SLOT_TAG_LOTAD then
    return m == Game3.SLOT_MATCH_LOTAD
  end
  return false
end

function Game3:slotFindTripleWindows(a, b, c)
  local starts = { {}, {}, {} }
  for reel = 1, 3 do
    local want = ({ a, b, c })[reel]
    for s = 0, 20 do
      local w = self:slotReelWindow(reel, s)
      if w[2] == want then
        starts[reel][#starts[reel] + 1] = s
      end
    end
    if #starts[reel] < 1 then return nil end
  end
  return {
    self:slotReelWindow(1, starts[1][1]),
    self:slotReelWindow(2, starts[2][1]),
    self:slotReelWindow(3, starts[3][1]),
  }
end

function Game3:slotFindBiasedWindows(bias, bet)
  bias = tonumber(bias) or 0
  bet = tonumber(bet) or 1
  if bias == 0 or Game3.slotBitAnd(bias, Game3.SLOT_BIAS_REELTIME) ~= 0 then
    return nil
  end
  for _ = 1, 400 do
    local wins = {}
    for r = 1, 3 do
      wins[r] = self:slotReelWindow(r, self:gbaRandom() % 21)
    end
    if self:slotWindowsMatchBias(wins, bias, bet) then
      return wins
    end
  end
  local sym = Game3.slotBiasSymbol(bias)
  if Game3.slotBitAnd(bias, Game3.SLOT_BIAS_STRAIGHT_7) ~= 0 then
    for color = 0, 1 do
      local found = self:slotFindTripleWindows(color, color, color)
      if found then return found end
    end
  elseif Game3.slotBitAnd(bias, Game3.SLOT_BIAS_MIXED_7) ~= 0 then
    return self:slotFindTripleWindows(0, 0, 1)
        or self:slotFindTripleWindows(1, 1, 0)
  elseif Game3.slotBitAnd(bias, Game3.SLOT_BIAS_CHERRY) ~= 0 then
    for s0 = 0, 20 do
      local w1 = self:slotReelWindow(1, s0)
      if w1[2] == Game3.SLOT_TAG_CHERRY or w1[1] == Game3.SLOT_TAG_CHERRY
          or w1[3] == Game3.SLOT_TAG_CHERRY then
        return {
          w1,
          self:slotReelWindow(2, self:gbaRandom() % 21),
          self:slotReelWindow(3, self:gbaRandom() % 21),
        }
      end
    end
  else
    return self:slotFindTripleWindows(sym, sym, sym)
  end
  return nil
end

function Game3:spinSlots()
  local f = self.field
  if not f or f.kind ~= "slots" then return end
  local bet = f.bet or 1
  if not f.replay then
    if not self:removeCoins(bet) then return false end
  end
  f.replay = false
  f.reelTimeNote = nil
  local bias = self:slotDrawMachineBias(f)
  if Game3.slotBitAnd(bias, Game3.SLOT_BIAS_REELTIME) ~= 0
      and (f.reelTimeLeft or 0) < 1 then
    local spins = self:slotDrawReelTime(f)
    bias = Game3.slotBitClear(bias, Game3.SLOT_BIAS_REELTIME)
    if spins > 0 then
      f.reelTimeLeft = spins
      f.pikaPower = 0
      f.reelTimeNote = spins
      bias = Game3.slotBitOr(bias, Game3.SLOT_BIAS_POWER)
    end
    f.bias = bias
  end
  if (f.reelTimeLeft or 0) > 0 then
    bias = Game3.slotBitOr(bias, Game3.SLOT_BIAS_POWER)
    f.bias = bias
  end
  local wins
  if bias ~= 0 and Game3.slotBitAnd(bias, Game3.SLOT_BIAS_REELTIME) == 0 then
    wins = self:slotFindBiasedWindows(bias, bet)
  end
  if not wins then
    wins = {}
    for r = 1, 3 do
      wins[r] = self:slotReelWindow(r, self:gbaRandom() % 21)
    end
  end
  f.windows = wins
  local pay, replay = self:slotScore(wins, bet)
  f.payout = pay
  f.replay = replay and true or false
  local center = Game3.slotMatch(wins[1][2], wins[2][2], wins[3][2])
  if center == Game3.SLOT_MATCH_POWER and (f.pikaPower or 0) < 16 then
    f.pikaPower = (f.pikaPower or 0) + 1
  end
  if center == Game3.SLOT_MATCH_777_RED or center == Game3.SLOT_MATCH_777_BLUE
      or center == Game3.SLOT_MATCH_777_MIXED then
    f.bias = Game3.slotBitClear(f.bias or 0, Game3.SLOT_BIAS_7)
    if center == Game3.SLOT_MATCH_777_RED or center == Game3.SLOT_MATCH_777_BLUE then
      f.reelTimeLeft = 0
      f.luckyGame = center == Game3.SLOT_MATCH_777_BLUE
    end
  end
  if (f.reelTimeLeft or 0) > 0 then
    f.reelTimeLeft = f.reelTimeLeft - 1
  end
  if pay > 0 then self:addCoins(pay) end
  return true
end

function Game3.rouletteFlag(id)
  id = tonumber(id) or 0
  if id < 1 then return 0 end
  return 2 ^ id
end

function Game3.rouletteMinBet(var)
  var = tonumber(var) or 0
  local idx = (var % 2) + math.floor(var / 128) * 2
  return Game3.ROULETTE_MIN_BETS[idx + 1] or 1
end

function Game3:resetRouletteHits(f)
  f = f or (self.field)
  if not f then return end
  f.hitFlags = 0
  f.pokeHits = { 0, 0, 0, 0 }
  f.colorHits = { 0, 0, 0 }
  f.balls = 0
  f.landed = nil
  f.won = nil
  f.payout = nil
end

function Game3:rouletteMultiplier(sel, f)
  sel = tonumber(sel) or 0
  f = f or self.field
  if sel < 1 or sel > 19 then return 0 end
  local hits = f and f.colorHits or { 0, 0, 0 }
  local pokes = f and f.pokeHits or { 0, 0, 0, 0 }
  local flags = (f and f.hitFlags) or 0
  local m = Game3.ROULETTE_MULTS
  if sel == 5 or sel == 10 or sel == 15 then
    local row = math.floor(sel / 5) - 1
    if (hits[row + 1] or 0) >= 4 then return 0 end
    return m[(hits[row + 1] or 0) + 2] or 0
  end
  if sel >= 1 and sel <= 4 then
    if (pokes[sel] or 0) >= 3 then return 0 end
    return m[(pokes[sel] or 0) + 3] or 0
  end
  if math.floor(flags / Game3.rouletteFlag(sel)) % 2 == 1 then return 0 end
  return Game3.ROULETTE_MAX_MULT
end

function Game3.rouletteHitInBet(square, bet)
  square, bet = tonumber(square) or 0, tonumber(bet) or 0
  if bet >= 1 and bet <= 4 then
    return square == bet + 5 or square == bet + 10 or square == bet + 15
  end
  if bet == 5 or bet == 10 or bet == 15 then
    return square >= bet + 1 and square <= bet + 4
  end
  return square == bet
end

function Game3:playRoulette()
  local var = self:varGet(0x8004) or 0
  self:beginScriptWait()
  local f = {
    kind = "roulette",
    minBet = Game3.rouletteMinBet(var),
    cursor = 6,
    streak = 0,
    partySpeciesFlags = self:roulettePartySpeciesFlags(),
  }
  self.field = f
  self:resetRouletteHits(f)
end

function Game3:closeRoulette()
  local f = self.field
  local minBet = (f and f.minBet) or 1
  self.field = nil
  self:setScriptVar(0x8004, (self:getCoins() < minBet) and 1 or 0)
  self:endScriptWait()
end

function Game3:moveRouletteCursor(dir)
  local f = self.field
  if not f or f.kind ~= "roulette" then return end
  local sel = f.cursor or 6
  local col = sel % 5
  local row = math.floor(sel / 5)
  if dir == 0 then
    row = row - 1
  elseif dir == 1 then
    row = row + 1
  elseif dir == 2 then
    col = col - 1
  else
    col = col + 1
  end
  if row < 0 then row = 3 elseif row > 3 then row = 0 end
  if col < 0 then col = 4 elseif col > 4 then col = 0 end
  local nxt = row * 5 + col
  if nxt == 0 then
    if dir == 2 then nxt = 4 else nxt = 1 end
  end
  f.cursor = nxt
end

function Game3:recordRouletteHit(slot)
  local f = self.field
  if not f then return 0 end
  slot = tonumber(slot) or 0
  local square = Game3.ROULETTE_SLOTS[slot + 1]
  if not square then return 0 end
  local sqFlag = Game3.rouletteFlag(square)
  if math.floor((f.hitFlags or 0) / sqFlag) % 2 ~= 1 then
    f.hitFlags = (f.hitFlags or 0) + sqFlag
  end
  local col = square % 5
  local row = math.floor(square / 5)
  if col >= 1 and col <= 4 then
    f.pokeHits = f.pokeHits or { 0, 0, 0, 0 }
    f.pokeHits[col] = (f.pokeHits[col] or 0) + 1
    if f.pokeHits[col] >= 3 then
      local fl = Game3.rouletteFlag(col)
      if math.floor(f.hitFlags / fl) % 2 ~= 1 then
        f.hitFlags = f.hitFlags + fl
      end
    end
  end
  if row >= 1 and row <= 3 then
    f.colorHits = f.colorHits or { 0, 0, 0 }
    f.colorHits[row] = (f.colorHits[row] or 0) + 1
    if f.colorHits[row] >= 4 then
      local fl = Game3.rouletteFlag(row * 5)
      if math.floor(f.hitFlags / fl) % 2 ~= 1 then
        f.hitFlags = f.hitFlags + fl
      end
    end
  end
  return square
end

function Game3:roulettePartySpeciesFlags()
  local flags = 0
  local party = self.party or {}
  for i = 1, #party do
    local sp = party[i] and party[i].species or 0
    if sp == Game3.SPECIES_SHROOMISH and flags % 2 == 0 then
      flags = flags + Game3.ROULETTE_HAS_SHROOMISH
    end
    if sp == Game3.SPECIES_TAILLOW
        and math.floor(flags / Game3.ROULETTE_HAS_TAILLOW) % 2 == 0 then
      flags = flags + Game3.ROULETTE_HAS_TAILLOW
    end
  end
  return flags
end

function Game3:rouletteTravelBias(ballNum, rand)
  -- Half of GetRandomForBallTravelDistance: lower = more consistent.
  -- Returns 1 (tight) / 2 (medium) / 4 (wide) for slot-weighting.
  local flags = (self.field and self.field.partySpeciesFlags)
    or self:roulettePartySpeciesFlags()
  local hour = tonumber(self.clockHour) or 12
  ballNum = tonumber(ballNum) or 0
  rand = tonumber(rand) or self:gbaRandom()
  local morning = hour > 3 and hour < 10
  if flags == Game3.ROULETTE_HAS_SHROOMISH
      or flags == Game3.ROULETTE_HAS_TAILLOW then
    if hour > 3 and hour < 10 then
      if ballNum < Game3.ROULETTE_BALLS * 2 or (rand % 2) == 1 then
        return 2
      end
      return 1
    end
    if (rand % 4) ~= 0 then return 2 end
    return 4
  end
  if flags == (Game3.ROULETTE_HAS_SHROOMISH + Game3.ROULETTE_HAS_TAILLOW) then
    if hour > 3 and hour < 11 then
      if ballNum < Game3.ROULETTE_BALLS or (rand % 2) == 1 then
        return 2
      end
      return 1
    end
    if (rand % 2) == 1 and ballNum > Game3.ROULETTE_BALLS then
      return 1
    end
    return 2
  end
  if morning then
    if (rand % 4) == 0 then return 1 end
    return 2
  end
  if (rand % 4) == 0 then
    if ballNum > Game3.ROULETTE_BALLS * 2 then return 2 end
    return 4
  end
  if (rand % 65536) >= 32768 then
    if ballNum > Game3.ROULETTE_BALLS * 2 then return 4 end
    return 8
  end
  return 8
end

function Game3:pickRouletteSlot()
  local f = self.field
  local flags = (f and f.hitFlags) or 0
  local open = {}
  for i = 0, 11 do
    local sq = Game3.ROULETTE_SLOTS[i + 1]
    if math.floor(flags / Game3.rouletteFlag(sq)) % 2 ~= 1 then
      open[#open + 1] = i
    end
  end
  if #open < 1 then return 0 end
  if #open == 1 then return open[1] end
  local last = f and f.lastSlot
  local bias = self:rouletteTravelBias(f and f.balls or 0, self:gbaRandom())
  if last == nil or bias >= 8 then
    return open[self:rand(#open) or 1]
  end
  -- Weight open wheel indices toward lastSlot when travel is consistent.
  local weights = {}
  local total = 0
  for i = 1, #open do
    local idx = open[i]
    local dist = math.abs(idx - last)
    if dist > 6 then dist = 12 - dist end
    local w = math.max(1, 7 - dist * math.max(1, math.floor(bias / 2)))
    weights[i] = w
    total = total + w
  end
  local roll = (self:gbaRandom() % total) + 1
  local acc = 0
  for i = 1, #open do
    acc = acc + weights[i]
    if roll <= acc then return open[i] end
  end
  return open[#open]
end

function Game3:spinRoulette()
  local f = self.field
  if not f or f.kind ~= "roulette" then return false end
  if f.spinning then return false end
  local bet = f.cursor or 6
  local mult = self:rouletteMultiplier(bet, f)
  if mult < 1 then return false end
  local cost = f.minBet or 1
  if not self:removeCoins(cost) then return false end
  local slot = self:pickRouletteSlot()
  f.spinning = true
  f.spinT = 0
  f.spinSlot = slot
  f.spinBet = bet
  f.spinMult = mult
  f.spinCost = cost
  f.landed = nil
  f.won = nil
  f.payout = nil
  return true
end

function Game3:resolveRoulette()
  local f = self.field
  if not f or not f.spinning then return end
  local slot = f.spinSlot or 0
  local bet = f.spinBet or f.cursor or 6
  local mult = f.spinMult or 1
  local cost = f.spinCost or 1
  f.lastSlot = slot
  local square = self:recordRouletteHit(slot)
  local won = Game3.rouletteHitInBet(square, bet)
  f.landed = square
  f.won = won and true or false
  f.mult = mult
  f.balls = (f.balls or 0) + 1
  local pay = 0
  if won then
    pay = cost * mult
    self:addCoins(pay)
    f.streak = (f.streak or 0) + 1
    if f.streak > self:getGameStat(Game3.GAME_STAT_CONSECUTIVE_ROULETTE_WINS) then
      self.gameStats = self.gameStats or {}
      self.gameStats[Game3.GAME_STAT_CONSECUTIVE_ROULETTE_WINS] = f.streak
    end
  else
    f.streak = 0
  end
  f.payout = pay
  f.spinning = nil
  if (f.balls or 0) >= Game3.ROULETTE_BALLS then
    f.hitFlags = 0
    f.pokeHits = { 0, 0, 0, 0 }
    f.colorHits = { 0, 0, 0 }
    f.balls = 0
    f.lastSlot = nil
    f.cleared = true
  else
    f.cleared = nil
  end
end

function Game3:stepRoulette()
  local f = self.field
  if not f or f.kind ~= "roulette" or not f.spinning then return end
  f.spinT = (f.spinT or 0) + 1 / 60
  if f.spinT >= 1.2 then
    self:resolveRoulette()
  end
end

-- field_door.c gDoorOpenAnimFrames/gDoorCloseAnimFrames: 4 phases of 4
-- vblanks each (16 GBA frames total either direction). Phase 0 is the
-- plain closed art (no overlay -- the normal tileset tile already shows
-- it); phases 1-3 are the baked frames in data/generated/tilesets.lua's
-- doorByMetatile atlas, column 0/1/2, in opening order (closing plays the
-- same three columns back to front, then rests on the plain closed art).
local DOOR_OPEN_SEQ = { nil, 0, 1, 2 }
local DOOR_CLOSE_SEQ = { 2, 1, 0, nil }

function Game3:doorEntryFor(map, x, y)
  local tilesets = self.data and self.data.tilesets
  local byMetatile = tilesets and tilesets.doorByMetatile
  if not byMetatile then return nil end
  local i = self:gridIndex(map, x, y)
  local cell = i and map.grid[i]
  if not cell then return nil end
  return byMetatile[Game3.metatileOf(cell)]
end

function Game3:openDoor(x, y, animate)
  local map = self.map
  local i = self:gridIndex(map, x, y)
  if not i or type(map.grid) ~= "table" then return false end
  local cell = map.grid[i] or 0
  map.grid[i] = Game3.elevationBits(cell) + Game3.metatileOf(cell)
  self:markTilesDirty()
  -- lightExitDoors opens the mat you landed on with animate=false: no
  -- transient task, but the door must still render open (real hardware
  -- leaves the VRAM override from the entry side in place).
  map.openDoors = map.openDoors or {}
  map.openDoors[i] = true
  if animate ~= false then
    -- scrcmd.c ScrCmd_opendoor / field_fadetransition.c: PlaySE only pairs
    -- with FieldAnimateDoorOpen, never Close, and never the instant
    -- FieldSetDoorOpened that lightExitDoors uses (animate=false).
    local entry = self:doorEntryFor(map, x, y)
    self:playSe(entry and entry.sound == 1
      and Game3.SE_SLIDING_DOOR or Game3.SE_DOOR)
    self.doorAnim = {
      map = map, i = i, x = x, y = y, t = 0,
      dur = Game3.DOOR_ANIM_FRAMES / 60,
      opening = true,
    }
  end
  return true
end

function Game3:closeDoor(x, y, animate)
  local map = self.map
  local i = self:gridIndex(map, x, y)
  if not i or type(map.grid) ~= "table" then return false end
  local cell = map.grid[i] or 0
  map.grid[i] = Game3.elevationBits(cell) + Game3.metatileOf(cell) + 1024
  self:markTilesDirty()
  if map.openDoors then map.openDoors[i] = nil end
  if animate ~= false then
    self.doorAnim = {
      map = map, i = i, x = x, y = y, t = 0,
      dur = Game3.DOOR_ANIM_FRAMES / 60,
      opening = false,
    }
  else
    self.doorAnim = nil
  end
  return true
end

function Game3:doorAnimating()
  local d = self.doorAnim
  return d ~= nil and (d.t or 0) < (d.dur or 0)
end

function Game3:stepDoorAnim(dt)
  local d = self.doorAnim
  if not d then return end
  d.t = (d.t or 0) + (dt or 0)
  if d.t >= (d.dur or 0) then
    self.doorAnim = nil
  end
end

function Game3:doorAtlasFor(tilesetId)
  if not tilesetId then return nil end
  self.doorAtlasCache = self.doorAtlasCache or {}
  local cached = self.doorAtlasCache[tilesetId]
  if cached ~= nil then return cached or nil end
  local spec = self.data.tilesets and self.data.tilesets.byId
    and self.data.tilesets.byId[tilesetId]
  local image = spec and spec.doorAtlas and self:grabImage(spec.doorAtlas)
  self.doorAtlasCache[tilesetId] = image or false
  return image
end

function Game3:doorQuad(row, frame, image)
  local tilesets = self.data.tilesets
  local cw = (tilesets and tilesets.doorCellW) or Game3.TILE
  local ch = (tilesets and tilesets.doorCellH) or (Game3.TILE * 2)
  local sw, sh = cw * (tilesets and tilesets.doorFrames or 3), ch
  if image and image.getDimensions then sw, sh = image:getDimensions() end
  local key = row .. ":" .. frame .. ":" .. sw .. "x" .. sh
  local q = self.quads[key]
  if not q then
    q = love.graphics.newQuad(frame * cw, row * ch, cw, ch, sw, sh)
    self.quads[key] = q
  end
  return q
end

-- Draws one door tile's current baked frame (opening/closing transient,
-- or the resting fully-open frame) anchored at its (x, y-1) arch tile --
-- the atlas cell already covers both the arch and the opening (see
-- RomExtractorGen3.renderDoorAtlas). Routed through drawStandingAt like any
-- other ground-level sprite: with a tilt billboard active, a raw
-- love.graphics.draw at world coordinates ignores the camera/zoom/tilt
-- projection entirely and stays glued to a fixed window position instead
-- of tracking the map -- exactly the "artifact follows the player" bug.
function Game3:drawDoorFrame(map, x, y, frame)
  if not frame then return end
  local entry = self:doorEntryFor(map, x, y)
  if not entry then return end
  local image = self:doorAtlasFor(map.tileset)
  if not image then return end
  local quad = self:doorQuad(entry.row, frame, image)
  local px, py = Game3.spriteDrawPos(x or 0, y or 0, Game3.TILE, Game3.TILE * 2, 0)
  self:drawStandingAt(px, py, Game3.TILE, Game3.TILE * 2, function()
    love.graphics.setColor(1, 1, 1, 1)
    love.graphics.draw(image, quad, px, py)
  end)
end

-- Doors sit on the ground layer, under BG1 roofs AND under sprites --
-- door_build_blockdef leaves a door metatile's top four tile entries
-- blank, so nothing of a door is ever drawn above the player. Only on the
-- pre-overlay pass, matching drawWorldStanding's two calls (false/true)
-- around drawMapOverlay so this doesn't double-draw every frame, and
-- before drawActors so the player is in front.
function Game3:drawDoorAnim(overOverlay)
  if overOverlay then return end
  local map = self.map
  if not map then return end
  local d = self.doorAnim
  local activeI = d and d.map == map and d.i
  if d and d.map == map then
    local dur = d.dur or (Game3.DOOR_ANIM_FRAMES / 60)
    local u = dur > 0 and ((d.t or 0) / dur) or 1
    if u < 0 then u = 0 elseif u > 1 then u = 1 end
    local phase = math.min(3, math.floor(u * 4))
    local seq = d.opening and DOOR_OPEN_SEQ or DOOR_CLOSE_SEQ
    self:drawDoorFrame(map, d.x, d.y, seq[phase + 1])
  end
  if map.openDoors then
    local w = map.width or 0
    for i, open in pairs(map.openDoors) do
      if open and i ~= activeI and w > 0 then
        local x, y = (i - 1) % w, math.floor((i - 1) / w)
        self:drawDoorFrame(map, x, y, 2)
      end
    end
  end
end

function Game3:lightExitDoors()
  local map = self.map
  if not map or Game3.isTruckMap(map) then return end
  if map.connections and #map.connections > 0 then return end
  local px, py = self.playerX or 0, self.playerY or 0
  local spots = {
    { px, py }, { px, py - 1 }, { px, py + 1 }, { px - 1, py }, { px + 1, py },
  }
  for i = 1, #spots do
    local w = Game3.warpAt(map, spots[i][1], spots[i][2])
    if w then
      local bx, by = w.x, w.y
      -- Only animated warp doors get the open VRAM override. Opening every
      -- nearby warp (stairs, holes) left phantom open-door overlays.
      if self:behaviorAt(map, bx, by) == Game3.MB_ANIMATED_DOOR then
        self:openDoor(bx, by, false)
      end
    end
  end
end

-- The mat-search lightExitDoors uses, isolated so followWarp can find the
-- same door without re-opening it (already done above): spawn tiles land
-- adjacent to the door rather than under it (followWarp's own not-walkable
-- shift, or just normal indoor layout), so this checks the four neighbors
-- too, not only the exact landing tile.
function Game3:findEntryDoor()
  local map = self.map
  if not map or Game3.isTruckMap(map) then return nil end
  if map.connections and #map.connections > 0 then return nil end
  local px, py = self.playerX or 0, self.playerY or 0
  local spots = {
    { px, py }, { px, py - 1 }, { px, py + 1 }, { px - 1, py }, { px + 1, py },
  }
  for i = 1, #spots do
    local w = Game3.warpAt(map, spots[i][1], spots[i][2])
    if w then
      local bx, by = w.x, w.y
      if self:behaviorAt(map, bx, by) == Game3.MB_ANIMATED_DOOR then
        return bx, by
      end
    end
  end
  return nil
end

-- field_fadetransition.c Task_DoDoorWarp / sub_808115C: exterior enter.
-- Player stands south of the door (currentCoords); ROM uses y-1 for the
-- door tile. Open → walk north through → close (player hidden) → warp.
function Game3:beginDoorWarp(warp, x, y)
  if not warp or self.field then return false end
  self.pendingDoorWarp = warp
  self.facing = "north"
  self:openDoor(x, y, true)
  self.field = { kind = "door_enter", phase = "open", x = x, y = y }
  return true
end

-- field_fadetransition.c sub_8080B9C, called only from followWarp (a real
-- interactive bump warp -- never a save load or scripted map jump, which
-- go through enterMap directly and must not replay this): the door you
-- just walked through is already open (lightExitDoors, no animation) with
-- its SE, then the player is auto-walked one further step into the room,
-- and only then does FieldAnimateDoorClose play -- the single visible door
-- animation on the arrival side.
-- field_fadetransition.c sub_8080AE4 picks the arrival task by the
-- behaviour of the tile you land on: an animated door gets sub_8080B9C
-- (open, walk out, close), a NON-animated door gets
-- task_map_chg_seq_0807E20C, and anything else gets
-- task_map_chg_seq_0807E2CC. The first two both walk the player one normal
-- step in their facing direction before returning control; only the third
-- leaves them standing on the tile.
--
-- Indoor stairs are MB_NON_ANIMATED_DOOR, and we were treating them as the
-- third case, so the player stayed on the stair tile -- one tile north of
-- where the cart puts them for the rest of the scene. The Petalburg Gym
-- report then walked them onto the TV instead of stopping south of it.
function Game3:startDoorArrival()
  if self.field then return end
  local bx, by = self:findEntryDoor()
  if bx then
    local entry = self:doorEntryFor(self.map, bx, by)
    self:playSe(entry and entry.sound == 1
      and Game3.SE_SLIDING_DOOR or Game3.SE_DOOR)
    self.facing = "south"
    self:applyMovement(Game3.LOCALID_PLAYER, { { kind = "walk", dir = "south" } })
    self.field = { kind = "door_arrival", x = bx, y = by }
    return
  end
  if not self.map then return end
  -- Both door kinds walk the player off the tile; the animated one only
  -- adds the open/close graphic and its sound. findEntryDoor above handles
  -- the ones we have a door graphic for -- when it finds none (the gym
  -- doors among them) the step still has to happen, or the map's ON_FRAME
  -- script runs a tile north of where the cart puts the player.
  local b = self:behaviorAt(self.map, self.playerX, self.playerY)
  if b ~= Game3.MB_NON_ANIMATED_DOOR and b ~= Game3.MB_ANIMATED_DOOR then
    return
  end
  -- No door graphic and no sound for this one, just the step.
  self:applyMovement(Game3.LOCALID_PLAYER,
    { { kind = "walk", dir = self.facing or "south" } })
  -- The step takes the player off the warp tile, so release the latch that
  -- stops a fresh arrival from immediately warping back. Without this the
  -- tile stays inert and stepping onto it again does nothing -- you get
  -- stuck inside a lift.
  self.ignoreWarp = false
  self.field = { kind = "door_arrival" }
end

function Game3:setStepCallback(id)
  id = tonumber(id) or 0
  if id == 0 then
    self.stepCallback = nil
  else
    self.stepCallback = id
    if id == Game3.STEP_CB_PACIFIDLOG then
      self:setPacifidlogPair(self.playerX, self.playerY, 2)
    end
  end
end

function Game3:npcByLocalId(localId)
  localId = tonumber(localId)
  local npcs = self:npcsFor(self.map)
  if not localId or not npcs then return nil end
  for i = 1, #npcs do
    if npcs[i] and npcs[i].localId == localId then return npcs[i] end
  end
end

function Game3:objectTemplate(localId)
  localId = tonumber(localId)
  local objects = self.map and self.map.objects
  if not localId or type(objects) ~= "table" then return nil end
  for i = 1, #objects do
    if objects[i] and objects[i].localId == localId then return objects[i] end
  end
end

function Game3:npcFromTemplate(o, i)
  i = i or 1
  local x = o.permX
  if x == nil then x = o.x end
  local y = o.permY
  if y == nil then y = o.y end
  local movementType = o.permMovementType or o.movementType or 0
  local npc = {
    templateIndex = i,
    x = x, y = y,
    fromX = x, fromY = y,
    homeX = x, homeY = y,
    elevation = o.elevation or 0,
    currentElevation = o.elevation or 0,
    previousElevation = o.elevation or 0,
    facing = Game3.facingFromMovementType(movementType),
    graphicsId = self:resolveGraphicsId(o.graphicsId or 0),
    movementType = movementType,
    rangeX = o.rangeX or 0,
    rangeY = o.rangeY or 0,
    trainerType = o.trainerType or 0,
    trainerRange = o.trainerRange or 0,
    trainerId = o.trainerId,
    trainerName = o.trainerName,
    trainerClass = o.trainerClass,
    doubleBattle = o.doubleBattle,
    party = o.party,
    items = o.items,
    itemId = o.itemId,
    itemCount = o.itemCount,
    mart = o.mart,
    script = o.script,
    flagId = o.flagId,
    localId = o.localId,
    defeated = self:isNpcDefeated(o),
    cooldown = 0,
    wait = ((i * 37) % 90) / 60,
    placeT = 0,
    invisible = Game3.movementTypeHidesSprite(movementType) or nil,
  }
  self:applyBerryTreeSprite(npc)
  return npc
end

function Game3:hideObject(localId)
  self:setActorInvisible(self:scriptActor(localId), true)
  return true
end

function Game3:showObject(localId, mapGroup, mapNum)
  localId = tonumber(localId) or 0
  if localId == Game3.LOCALID_PLAYER
      and mapGroup ~= nil and mapNum ~= nil then
    local dest = self:lookupMap(mapGroup, mapNum)
    if dest and dest ~= self.map then
      local x, y = self:objectGfxXY(dest, Game3.GFX_BRINEY_BOAT)
      if not x then
        local spawn = dest.spawn or {}
        x, y = spawn.x or 0, spawn.y or 0
      end
      self:scriptWarp(mapGroup, mapNum, Game3.WARP_ID_NONE, x, y)
    end
  end
  self:setActorInvisible(self:scriptActor(localId), false)
  return true
end

function Game3:removeObject(localId)
  localId = tonumber(localId) or 0
  if localId == Game3.LOCALID_PLAYER then
    self.invisible = true
    return true
  end
  local o = self:objectTemplate(localId)
  if o and o.flagId and o.flagId ~= 0 then
    self.flags = self.flags or {}
    self.flags[o.flagId] = true
  end
  local npc = self:npcByLocalId(localId)
  if npc then npc.hidden = true end
  return npc ~= nil or o ~= nil
end

function Game3:addObject(localId)
  localId = tonumber(localId) or 0
  if localId == Game3.LOCALID_PLAYER then
    self.invisible = nil
    return true
  end
  local o = self:objectTemplate(localId)
  if o and o.flagId and o.flagId ~= 0 then
    self.flags = self.flags or {}
    self.flags[o.flagId] = nil
  end
  local npc = self:npcByLocalId(localId)
  if npc then
    npc.hidden = nil
    self:applyBerryTreeSprite(npc)
    return true
  end
  if not o then return false end
  local map = self.map
  if not map then return false end
  if not self.npcByMap then self.npcByMap = {} end
  local list = self:npcsFor(map)
  if not list then
    list = {}
    self.npcByMap[map.id or map] = list
  end
  local npc = self:npcFromTemplate(o, #list + 1)
  self:updateNpcZCoord(npc, map)
  list[#list + 1] = npc
  return true
end

-- pokeruby TrySpawnObjectEvent: a clear FLAG_HIDE_* brings the template
-- back at xyperm. removeobject only hides the sprite; StolenGoods then
-- clearflag FLAG_HIDE_DEVON_RUSTBORO without addobject, so the employee
-- at Devon Corp stayed invisible.
function Game3:trySpawnObject(localId)
  localId = tonumber(localId) or 0
  if localId < 1 then return false end
  local o = self:objectTemplate(localId)
  if not o then return false end
  local fid = o.flagId or 0
  if fid ~= 0 and self.flags and self.flags[fid] then return false end
  local npc = self:npcByLocalId(localId)
  if npc then
    if npc.hidden then
      npc.hidden = nil
      local x = o.permX
      if x == nil then x = npc.homeX or o.x end
      local y = o.permY
      if y == nil then y = npc.homeY or o.y end
      npc.x, npc.y = x, y
      npc.fromX, npc.fromY = x, y
      npc.homeX, npc.homeY = x, y
      npc.graphicsId = self:resolveGraphicsId(o.graphicsId or npc.graphicsId or 0)
      self:applyBerryTreeSprite(npc)
    end
    return true
  end
  return self:addObject(localId)
end

function Game3:trySpawnByFlag(flag)
  flag = tonumber(flag)
  if not flag or flag == 0 then return false end
  local objects = self.map and self.map.objects
  if type(objects) ~= "table" then return false end
  local spawned = false
  for i = 1, #objects do
    local o = objects[i]
    if o and o.flagId == flag and o.localId then
      if self:trySpawnObject(o.localId) then spawned = true end
    end
  end
  return spawned
end

function Game3:setObjectXY(localId, x, y)
  local actor = self:scriptActor(localId)
  if actor == "player" then
    self.playerX, self.playerY = x, y
    self.walkFromX, self.walkFromY = x, y
    self.walkCooldown = 0
    self:clampCamera()
    return true
  elseif actor then
    actor.x, actor.y = x, y
    actor.fromX, actor.fromY = x, y
    actor.cooldown = 0
    return true
  end
  return false
end

function Game3:clearObjectPerms(map)
  local objects = map and map.objects
  if type(objects) ~= "table" then return end
  for i = 1, #objects do
    local o = objects[i]
    if o then
      o.permX, o.permY = nil, nil
      o.permMovementType = nil
    end
  end
end

function Game3:setObjectXYPerm(localId, x, y)
  x, y = tonumber(x) or 0, tonumber(y) or 0
  local o = self:objectTemplate(localId)
  if o then
    o.permX, o.permY = x, y
  end
  local npc = self:npcByLocalId(localId)
  if npc then
    npc.homeX, npc.homeY = x, y
  end
  return self:setObjectXY(localId, x, y) or o ~= nil
end

function Game3.movementTypeHidesSprite(movementType)
  return movementType == Game3.MOVEMENT_TYPE_HIDDEN
      or movementType == Game3.MOVEMENT_TYPE_INVISIBLE
      or movementType == Game3.MOVEMENT_TYPE_TREE_DISGUISE
      or movementType == Game3.MOVEMENT_TYPE_MOUNTAIN_DISGUISE
end

function Game3.faceMovementType(facing)
  if facing == "north" then return Game3.MOVEMENT_TYPE_FACE_UP end
  if facing == "west" then return Game3.MOVEMENT_TYPE_FACE_LEFT end
  if facing == "east" then return Game3.MOVEMENT_TYPE_FACE_RIGHT end
  return Game3.MOVEMENT_TYPE_FACE_DOWN
end

-- trainer_see.c SetTrainerMovementType + OverrideMovementTypeForObjectEvent
-- after the ash pop / tree-rock pop. Skip FLDEFF_POP_OUT_OF_ASH and
-- FLDEFF_TREE/MOUNTAIN_DISGUISE cinema; persist FACE_* so a later
-- ON_TRANSITION that skips bury (already defeated) does not respawn HIDDEN
-- from leftover permMovementType 63 on the Lua map object.
function Game3:revealHiddenTrainer(npc)
  if not npc then return false end
  local mt = npc.movementType or 0
  if mt ~= Game3.MOVEMENT_TYPE_HIDDEN
      and mt ~= Game3.MOVEMENT_TYPE_TREE_DISGUISE
      and mt ~= Game3.MOVEMENT_TYPE_MOUNTAIN_DISGUISE then
    return false
  end
  npc.invisible = nil
  local face = Game3.faceMovementType(npc.facing)
  npc.movementType = face
  local o = npc.localId and self:objectTemplate(npc.localId)
  if o then o.permMovementType = face end
  return true
end

function Game3:setObjectMovementType(localId, movementType)
  movementType = tonumber(movementType) or 0
  local o = self:objectTemplate(localId)
  if o then o.permMovementType = movementType end
  local npc = self:npcByLocalId(localId)
  if npc then
    npc.movementType = movementType
    npc.facing = Game3.facingFromMovementType(movementType)
    if Game3.movementTypeHidesSprite(movementType) then
      npc.invisible = true
    else
      npc.invisible = nil
    end
  end
  return o ~= nil or npc ~= nil
end

function Game3:currentMapGroupNum()
  local map = self.map
  if not map then return 0, 0 end
  local g, n = tonumber(map.group), tonumber(map.index)
  if g ~= nil and n ~= nil then return g, n end
  local gs, ns = tostring(map.id or ""):match("^g(%d+)_(%d+)$")
  return tonumber(gs) or 0, tonumber(ns) or 0
end

function Game3:mapMatches(mapGroup, mapNum)
  local map = self.map
  if not map then return false end
  local id = map.id
  if type(id) ~= "string" then return true end
  local g, n = id:match("^g(%d+)_(%d+)$")
  if not g then return true end
  return tonumber(g) == (tonumber(mapGroup) or 0)
      and tonumber(n) == (tonumber(mapNum) or 0)
end

function Game3:setObjectPriority(localId, priority, mapGroup, mapNum)
  localId = tonumber(localId) or 0
  local sub = (tonumber(priority) or 0) + Game3.OBJECT_SUBPRIORITY_ADD
  if localId == Game3.LOCALID_PLAYER then
    self.fixedPriority = true
    self.objSubpriority = sub
    return true
  end
  if not self:mapMatches(mapGroup, mapNum) then return false end
  local actor = self:npcByLocalId(localId)
  if not actor then return false end
  actor.fixedPriority = true
  actor.objSubpriority = sub
  return true
end

function Game3:resetObjectPriority(localId, mapGroup, mapNum)
  localId = tonumber(localId) or 0
  if localId == Game3.LOCALID_PLAYER then
    self.fixedPriority = nil
    self.objSubpriority = nil
    return true
  end
  if not self:mapMatches(mapGroup, mapNum) then return false end
  local actor = self:npcByLocalId(localId)
  if not actor then return false end
  actor.fixedPriority = nil
  actor.objSubpriority = nil
  return true
end

function Game3:moveObjectOffscreen(localId)
  local npc = self:npcByLocalId(localId)
  if not npc then return false end
  local x, y = npc.x, npc.y
  npc.homeX, npc.homeY = x, y
  local o = self:objectTemplate(localId)
  if o then
    o.permX, o.permY = x, y
  end
  return true
end

function Game3:turnObject(localId, dir)
  local facing = Game3.DIR_FACING[tonumber(dir) or 0] or "south"
  local actor = self:scriptActor(localId)
  if actor == "player" then
    self.facing = facing
    return true
  elseif actor then
    actor.facing = facing
    return true
  end
  return false
end

function Game3:faceScriptNpc()
  local npc = self._scriptNpc
  if npc then self:faceActorAt(npc, self.playerX, self.playerY) end
  return true
end

function Game3:lockScriptNpcs(all)
  -- pokeruby ScriptContext2_Enable + FreezeObjectEvents (lock / lockall).
  -- Field controls stay locked until release/releaseall even between
  -- msgbox / waitmovement pauses -- otherwise the Champions Room walk-up
  -- can drop self.field for a frame and let the player walk off Steven,
  -- abort the ON_FRAME script after VAR_TEMP_1 is set, and soft-lock
  -- (Steven has no talk script; north door still closed).
  self.fieldControlsLocked = true
  -- ROM lock / lockall freeze wandering, not facing. lockfacing is a
  -- movement action. Pinning facing here made Wally moonwalk.
  local function lockOne(npc)
    if npc and npc ~= "player" then
      npc.talkLock = true
    end
  end
  if all then
    local npcs = self:npcsFor(self.map)
    if npcs then
      for i = 1, #npcs do lockOne(npcs[i]) end
    end
  else
    lockOne(self._scriptNpc)
  end
  return true
end

function Game3:unlockScriptNpcs()
  -- ScriptContext2_Disable. Only release/releaseall (and cleanup paths
  -- that call this) should clear the player freeze.
  self.fieldControlsLocked = nil
  local npcs = self:npcsFor(self.map)
  if not npcs then return true end
  for i = 1, #npcs do
    local n = npcs[i]
    if n and n.talkLock then
      n.talkLock = nil
      n.facingLocked = nil
    end
  end
  return true
end

function Game3:scriptActor(localId)
  localId = tonumber(localId) or 0
  if localId == Game3.LOCALID_PLAYER then return "player" end
  return self:npcByLocalId(localId)
end

function Game3:actorBusy(actor)
  if actor == "player" then return (self.walkCooldown or 0) > 0 end
  return actor and (actor.cooldown or 0) > 0
end

function Game3:tickActorCooldown(actor, dt)
  if actor == "player" then
    if (self.walkCooldown or 0) > 0 then
      self.walkCooldown = self.walkCooldown - dt
      if self.walkCooldown <= 0 then
        self.walkCooldown = 0
        self.hopping = nil
        self.emote = nil
      end
    end
  elseif actor and (actor.cooldown or 0) > 0 then
    actor.cooldown = actor.cooldown - dt
    if actor.cooldown <= 0 then
      actor.cooldown = 0
      actor.emote = nil
    end
  end
end

function Game3:holdActor(actor, seconds)
  seconds = seconds or 0
  if seconds < 0 then seconds = 0 end
  if actor == "player" then
    self.walkFromX, self.walkFromY = self.playerX, self.playerY
    self.walkDuration = seconds
    self.walkCooldown = seconds
  elseif actor then
    actor.fromX, actor.fromY = actor.x, actor.y
    actor.walkDuration = seconds
    actor.cooldown = seconds
  end
end

function Game3:setActorInvisible(actor, hidden)
  if actor == "player" then
    self.invisible = hidden and true or nil
  elseif actor then
    actor.invisible = hidden and true or nil
  end
end

function Game3:actorFacingLocked(actor)
  if actor == "player" then return self.facingLocked end
  return actor and actor.facingLocked
end

function Game3:setActorFacing(actor, dir)
  if not dir then return end
  if self:actorFacingLocked(actor) then return end
  if actor == "player" then
    self.facing = dir
  elseif actor then
    actor.facing = dir
  end
end

function Game3:setActorFacingLocked(actor, locked)
  if actor == "player" then
    self.facingLocked = locked and true or nil
  elseif actor then
    actor.facingLocked = locked and true or nil
  end
end

function Game3:setActorLockAnim(actor, locked)
  if actor == "player" then
    self.lockAnim = locked and true or nil
  elseif actor then
    actor.lockAnim = locked and true or nil
  end
  self:setActorFacingLocked(actor, locked)
end

function Game3:setActorFlag(actor, key, on)
  if type(key) ~= "string" or key == "" then return end
  local val = on and true or nil
  if actor == "player" then
    self[key] = val
  elseif actor then
    actor[key] = val
  end
end

function Game3:scriptEmote(actor, emote)
  if actor == "player" then
    self.emote = emote
  elseif actor then
    actor.emote = emote
  end
  self:holdActor(actor, Game3.EMOTE_PERIOD)
end

function Game3:faceActorAt(actor, tx, ty)
  local x, y
  if actor == "player" then
    x, y = self.playerX, self.playerY
  elseif actor then
    x, y = actor.x, actor.y
  else
    return
  end
  local dx, dy = (tx or 0) - (x or 0), (ty or 0) - (y or 0)
  if dx == 0 and dy == 0 then return end
  local dir
  if math.abs(dx) > math.abs(dy) then
    dir = dx > 0 and "east" or "west"
  else
    dir = dy > 0 and "south" or "north"
  end
  if actor == "player" then
    self.facing = dir
  else
    actor.facing = dir
  end
end

function Game3:faceActorAwayFrom(actor, tx, ty)
  self:faceActorAt(actor, tx, ty)
  if actor == "player" then
    self.facing = Game3.oppositeFacing(self.facing)
  elseif actor then
    actor.facing = Game3.oppositeFacing(actor.facing)
  end
end

function Game3:faceActorOriginal(actor)
  local mt = 0
  if actor and actor ~= "player" then mt = actor.movementType or 0 end
  self:setActorFacing(actor, Game3.facingFromMovementType(mt))
end

function Game3:scriptMoveDelta(actor, dx, dy, tiles, animated, period)
  tiles = tiles or 1
  dx, dy = dx or 0, dy or 0
  period = period or Game3.WALK_PERIOD
  local fromX, fromY
  if actor == "player" then
    fromX, fromY = self.playerX, self.playerY
  elseif actor then
    fromX, fromY = actor.x, actor.y
  else
    return
  end
  local x, y = fromX, fromY
  for _ = 1, tiles do
    x, y = x + dx, y + dy
  end
  if actor == "player" then
    if animated then
      self.walkFromX, self.walkFromY = fromX, fromY
      self.walkDuration = period
      self.walkCooldown = period
    else
      self.walkFromX, self.walkFromY = x, y
      self.walkCooldown = 0
    end
    self.playerX, self.playerY = x, y
    self:updatePlayerZCoord()
  else
    if animated then
      actor.fromX, actor.fromY = fromX, fromY
      actor.walkDuration = period
      actor.cooldown = period
    else
      actor.fromX, actor.fromY = x, y
      actor.cooldown = 0
    end
    actor.x, actor.y = x, y
    self:updateNpcZCoord(actor)
  end
end

function Game3:scriptMoveActor(actor, dir, tiles, animated, period)
  local dx, dy = Game3.deltaFromFacing(dir)
  self:scriptMoveDelta(actor, dx, dy, tiles, animated, period)
end

function Game3:setActorLevitate(actor, px)
  if actor == "player" then
    self.levitate = px
  elseif actor then
    actor.levitate = px
  end
  self:holdActor(actor, Game3.WALK_PERIOD)
end

function Game3:playScriptStep(actor, step)
  if not (actor and step) then return end
  local kind = step.kind
  if kind == "delay" then
    -- ROM delay_8/16 always occupies the object. Skipping when the
    -- player sprite is hidden made every NPC delay instant in the
    -- contest hall (ON_WARP hideobjectat LOCALID_PLAYER).
    self:holdActor(actor, (step.frames or 1) / 60)
    return
  end
  if kind == "emote" then
    self:scriptEmote(actor, step.emote)
    return
  end
  if kind == "walkplace" then
    self:setActorFacing(actor, step.dir)
    self:holdActor(actor, Game3.scriptStepPeriod(step))
    return
  end
  if kind == "invisible" then
    self:setActorInvisible(actor, true)
    return
  end
  if kind == "visible" then
    self:setActorInvisible(actor, false)
    return
  end
  if kind == "faceplayer" then
    self:faceActorAt(actor, self.playerX, self.playerY)
    return
  end
  if kind == "faceaway" then
    self:faceActorAwayFrom(actor, self.playerX, self.playerY)
    return
  end
  if kind == "faceoriginal" then
    self:faceActorOriginal(actor)
    return
  end
  if kind == "lockface" then
    self:setActorFacingLocked(actor, true)
    return
  end
  if kind == "unlockface" then
    self:setActorFacingLocked(actor, false)
    return
  end
  if kind == "bow" then
    if actor == "player" then
      self.facing = "south"
    elseif actor then
      actor.facing = "south"
    end
    self:holdActor(actor, Game3.EMOTE_PERIOD)
    return
  end
  if kind == "reveal" then
    if actor ~= "player" and self:revealHiddenTrainer(actor) then
      actor.revealed = true
    else
      self:setActorInvisible(actor, false)
      if actor ~= "player" then actor.revealed = true end
    end
    self:holdActor(actor, Game3.WALK_PERIOD)
    return
  end
  if kind == "smash" or kind == "cut" then
    self:setActorInvisible(actor, true)
    self:holdActor(actor, Game3.SMASH_PERIOD)
    return
  end
  if kind == "lockanim" then
    self:setActorLockAnim(actor, true)
    return
  end
  if kind == "unlockanim" then
    self:setActorLockAnim(actor, false)
    return
  end
  if kind == "place" then
    self:holdActor(actor, Game3.WALK_PERIOD)
    return
  end
  if kind == "flag" then
    self:setActorFlag(actor, step.key, step.on)
    return
  end
  if kind == "levitate" then
    self:setActorLevitate(actor, Game3.LEVITATE_PX)
    return
  end
  if kind == "land" or kind == "flydown" then
    self:setActorLevitate(actor, 0)
    return
  end
  if kind == "flyup" then
    self:setActorLevitate(actor, Game3.FLY_PX)
    return
  end
  if not step.dir and not step.dx then return end
  local prevX, prevY
  if actor == "player" then
    self:setActorFacing(actor, step.dir)
    prevX, prevY = self.playerX, self.playerY
  else
    self:setActorFacing(actor, step.dir)
  end
  if kind == "walk" or kind == "jump" then
    local period = Game3.scriptStepPeriod(step)
    if step.dx then
      self:scriptMoveDelta(actor, step.dx, step.dy, 1, true, period)
    else
      self:scriptMoveActor(actor, step.dir, 1, true, period)
    end
    if actor == "player" then self:runStepCallback(prevX, prevY) end
  elseif kind == "jump2" then
    self:scriptMoveActor(actor, step.dir, 2, true, Game3.scriptStepPeriod(step))
    if actor == "player" then self:runStepCallback(prevX, prevY) end
  end
end

function Game3:expandMoveSteps(steps)
  local out = {}
  for i = 1, #(steps or {}) do
    local step = steps[i]
    if step and step.kind == "jump2" then
      out[#out + 1] = { kind = "walk", dir = step.dir }
      out[#out + 1] = { kind = "walk", dir = step.dir }
    elseif step then
      out[#out + 1] = step
    end
  end
  return out
end

function Game3:scriptMoving()
  local jobs = self.moveJobs
  if type(jobs) == "table" and #jobs > 0 then return true end
  -- Leftover D-pad / warp lerp is not waitmovement. LinkContestRoom1
  -- ON_WARP hideobjectat LOCALID_PLAYER then waitmovement 0 used to
  -- freeze the hall on that cooldown with an empty job list.
  if (self.walkCooldown or 0) > 0 and not self.invisible then return true end
  return false
end

function Game3:startScriptDelay(frames)
  self.delayLeft = (tonumber(frames) or 0) / 60
end

function Game3:scriptDelaying()
  return (self.delayLeft or 0) > 0
end

function Game3:beginScriptWait()
  self.scriptWait = true
end

function Game3:scriptWaiting()
  return self.scriptWait and true or false
end

function Game3:endScriptWait()
  self.scriptWait = nil
  if self._scriptPause then
    return self:resumeMoveScript()
  end
  return false
end

function Game3:pumpScriptMove()
  local jobs = self.moveJobs
  if type(jobs) ~= "table" then return end
  local i = 1
  while i <= #jobs do
    local job = jobs[i]
    local actor = self:scriptActor(job.localId)
    if not actor then
      table.remove(jobs, i)
    elseif self:actorBusy(actor) then
      i = i + 1
    else
      local step = job.steps[job.i]
      if not step then
        table.remove(jobs, i)
      else
        job.i = job.i + 1
        self:playScriptStep(actor, step)
        if self:actorBusy(actor) then
          i = i + 1
        end
      end
    end
  end
  if self:scriptActor(Game3.LOCALID_PLAYER) then self:clampCamera() end
end

function Game3:stepScriptMove(dt)
  dt = dt or 0
  self:tickActorCooldown("player", dt)
  local jobs = self.moveJobs or {}
  for i = 1, #jobs do
    local actor = self:scriptActor(jobs[i].localId)
    if actor and actor ~= "player" then self:tickActorCooldown(actor, dt) end
  end
  self:pumpScriptMove()
end

function Game3:finishScriptMoves()
  local n = 0
  while self:scriptMoving() and n < 1024 do
    self:stepScriptMove(Game3.WALK_PERIOD)
    n = n + 1
  end
end

function Game3:applyMovement(localId, steps)
  localId = tonumber(localId) or 0
  local actor = self:scriptActor(localId)
  if not actor then return false end
  local expanded = self:expandMoveSteps(steps)
  self.moveJobs = self.moveJobs or {}
  local jobs = self.moveJobs
  for i = #jobs, 1, -1 do
    if jobs[i].localId == localId then table.remove(jobs, i) end
  end
  jobs[#jobs + 1] = { localId = localId, steps = expanded, i = 1 }
  self:pumpScriptMove()
  return true
end

function Game3:resumeMoveScript()
  local pause = self._scriptPause
  if type(pause) ~= "table" or type(pause.ops) ~= "table" then
    self.field = nil
    self:endScriptRun()
    return false
  end
  local fromMsg = self.field and self.field.thenContinue
  local jobs = self.moveJobs
  local hasJobs = type(jobs) == "table" and #jobs > 0
  -- StartWallClock nils field then resumes. A leftover D-pad lerp is
  -- scriptMoving() but not an applymovement job; wait only on jobs or
  -- the field stays nil and FLAG_SET_WALL_CLOCK never sets.
  local function hold(kind)
    local f = self.field
    if f and f.kind == kind then return true end
    if f and f.kind ~= "talk" and f.kind ~= "wait"
        and f.kind ~= "move" and f.kind ~= "delay" then
      return true
    end
    self.field = { kind = kind }
    return true
  end
  -- scriptMoving() is also true for a leftover D-pad lerp. Wait only on
  -- applymovement jobs; that lerp is not waitmovement. fromMsg keeps the
  -- talk line up (Route 101 shove).
  if fromMsg then
    if hasJobs or self:scriptDelaying() then
      return true
    end
    if self:scriptWaiting() then
      -- Keep the line up only while a live cinema/effect owns the wait.
      -- A leftover scriptWait (heal, unused waitstate) used to pin
      -- "ZIGZAGOON used ROCK SMASH." forever.
      if self:cinemaHolding() then return true end
      self.scriptWait = nil
    end
  else
    if hasJobs then return hold("move") end
    if self:scriptDelaying() then return hold("delay") end
    if self:scriptWaiting() then return hold("wait") end
  end
  self._scriptPause = nil
  self._scriptSays = {}
  local _, again = self:continueScript(pause.ops, pause.at)
  return self:presentScript(again)
end

function Game3:fallDownHole()
  local x, y = self.playerX or 0, self.playerY or 0
  local h = self.holeWarp
  if h and self:lookupMap(h.mapGroup, h.mapNum) then
    self.walkCooldown = 0
    self.moveJobs = {}
    self:scriptWarp(h.mapGroup, h.mapNum, Game3.WARP_ID_NONE, x, y)
    self.field = { kind = "talk", text = Game3.TEXT_FELL_THROUGH }
    return true
  end
  local map = self.map
  if map and map.group == Game3.GRANITE_CAVE_GROUP
      and map.index == Game3.GRANITE_CAVE_B1F_NUM
      and self:lookupMap(Game3.GRANITE_CAVE_GROUP, Game3.GRANITE_CAVE_B2F_NUM) then
    self.walkCooldown = 0
    self.moveJobs = {}
    self:scriptWarp(Game3.GRANITE_CAVE_GROUP, Game3.GRANITE_CAVE_B2F_NUM,
      Game3.WARP_ID_NONE, x, y)
    self.field = { kind = "talk", text = Game3.TEXT_FELL_THROUGH }
    return true
  end
  local spawn = map and map.spawn or {}
  self.playerX = spawn.x or 0
  self.playerY = spawn.y or 0
  self.walkFromX, self.walkFromY = self.playerX, self.playerY
  self:updatePlayerZCoord()
  self.walkCooldown = 0
  self.moveJobs = {}
  self.field = { kind = "talk", text = Game3.TEXT_FELL_THROUGH }
  return true
end

-- field_fadetransition.c sp13E_warp_to_last_warp. The name is a
-- misnomer: dest is gWarpDestination (already set by sub_8068C30 or
-- warpsilent), not gLastUsedWarp. Do not beginScriptWait.
function Game3:warpToWarpDestination()
  local d = self.warpDestination
  if d then
    self.walkCooldown = 0
    self.moveJobs = {}
    return self:scriptWarp(d.mapGroup, d.mapNum,
      d.warpId or Game3.WARP_ID_NONE, d.x, d.y)
  end
  local w = Game3.warpAt(self.map, self.playerX, self.playerY)
  if w then
    self.walkCooldown = 0
    self.moveJobs = {}
    return self:followWarp(w)
  end
  return false
end

-- EventScript_FallDownHoleMtPyre → special DoFallWarp. Dest is the
-- hole's warp event (sub_8068C30), then the fall field callback.
function Game3:doFallWarp()
  if self:warpToWarpDestination() then
    self.field = { kind = "talk", text = Game3.TEXT_FELL_THROUGH }
    return true
  end
  return self:fallDownHole()
end

function Game3:writeMetatile(x, y, mid)
  local map = self.map
  local i = self:gridIndex(map, x, y)
  if not i or type(map.grid) ~= "table" then return false end
  local cell = map.grid[i] or 0
  -- Track the pre-edit cell so a later warp-driven enterMap can put it
  -- back (fieldmap.c InitMap rebuilds the whole grid from ROM on every
  -- warp; this is the same effect scoped to just the cells a step
  -- callback actually touched).
  map.dirtyTiles = map.dirtyTiles or {}
  if map.dirtyTiles[i] == nil then map.dirtyTiles[i] = cell end
  map.grid[i] = Game3.elevationBits(cell)
    + (tonumber(mid) or 0) % 1024
    + Game3.collisionOf(cell) * 1024
  self:markTilesDirty()
  return true
end

-- field_tasks.c PerStepCallback_806A07C. A cracked floor does not drop you the
-- moment you tread on it: stepping on a fresh one arms a three-step countdown
-- for that tile, and when the count runs out sub_806A040 swaps the metatile so
-- the crack becomes a hole. Only two can be counting down at once. You fall
-- later, by walking onto a tile that has already collapsed.
Game3.CRACKED_FLOOR_STEPS = 3
Game3.CRACKED_FLOOR_SLOTS = 2
-- sub_806A040: 0x22F becomes 0x206, anything else becomes 0x237.
Game3.MT_CRACKED_FLOOR_ALT = 0x22F
Game3.MT_CRACKED_FLOOR_HOLE_ALT = 0x206
Game3.MT_CRACKED_FLOOR_HOLE = 0x237

function Game3:collapseCrackedFloor(x, y)
  local map = self.map
  local i = self:gridIndex(map, x, y)
  if not i or type(map.grid) ~= "table" then return false end
  local mid = Game3.metatileOf(map.grid[i])
  local become = (mid == Game3.MT_CRACKED_FLOOR_ALT)
    and Game3.MT_CRACKED_FLOOR_HOLE_ALT or Game3.MT_CRACKED_FLOOR_HOLE
  return self:writeMetatile(x, y, become)
end

function Game3:crackedFloorSlots()
  self.crackedFloorPending = self.crackedFloorPending or {}
  return self.crackedFloorPending
end

-- Armed when the player steps onto a cracked tile that is not already counting.
function Game3:armCrackedFloor(x, y)
  local slots = self:crackedFloorSlots()
  for i = 1, #slots do
    local slot = slots[i]
    if slot and slot.x == x and slot.y == y then return false end
  end
  if #slots >= Game3.CRACKED_FLOOR_SLOTS then return false end
  slots[#slots + 1] = { x = x, y = y, left = Game3.CRACKED_FLOOR_STEPS }
  return true
end

-- One tick per FRAME, matching PerStepCallback_806A07C running off an
-- ordinary task. `frames` is how many elapsed since the last call.
function Game3:tickCrackedFloors(frames)
  if self.stepCallback ~= Game3.STEP_CB_CRACKED_FLOOR then return end
  local slots = self.crackedFloorPending
  if type(slots) ~= "table" or #slots < 1 then return end
  frames = math.floor(tonumber(frames) or 1)
  if frames < 1 then frames = 1 end
  local keep = {}
  for i = 1, #slots do
    local slot = slots[i]
    slot.left = (slot.left or 1) - frames
    if slot.left <= 0 then
      self:collapseCrackedFloor(slot.x, slot.y)
    else
      keep[#keep + 1] = slot
    end
  end
  self.crackedFloorPending = keep
end

function Game3:crackTileAt(x, y)
  local map = self.map
  local i = self:gridIndex(map, x, y)
  if not i or type(map.grid) ~= "table" then return false end
  return self:writeMetatile(x, y, Game3.metatileOf(map.grid[i]) + 1)
end

-- field_tasks.c sub_8069CB8: map-local x in 3..13, y in 6..19, and
-- gUnknown_083763E4[y] nonzero. C casts (x-3) to u16.
function Game3.sootopolisIceBit(x, y)
  x, y = x or 0, y or 0
  if x < 3 or x > 13 then return nil end
  if y < 6 or y > 19 then return nil end
  local id = Game3.SOOTOPOLIS_ICE_ROW_VAR[y]
  if not id or id == 0 then return nil end
  return id, x - 3
end

function Game3:markSootopolisIceCracked(x, y)
  local id, bit = Game3.sootopolisIceBit(x, y)
  if not id then return false end
  local n = self:varGet(id)
  local mask = 2 ^ bit
  if math.floor(n / mask) % 2 == 0 then
    n = n + mask
    if n > 65535 then n = n - 65536 end
    self:setScriptVar(id, n)
  end
  return true
end

function Game3:sootopolisIceWasCracked(x, y)
  local id, bit = Game3.sootopolisIceBit(x, y)
  if not id then return false end
  local mask = 2 ^ bit
  return math.floor(self:varGet(id) / mask) % 2 == 1
end

-- special 309. MapGridSetMetatileIdAt(x+7, y+7, Ice_Cracked).
function Game3:setSootopolisGymCrackedIceMetatiles()
  local map = self.map
  if not (map and map.grid) then return false end
  local w, h = map.width or 0, map.height or 0
  local any = false
  for y = 0, h - 1 do
    for x = 0, w - 1 do
      if self:sootopolisIceWasCracked(x, y) then
        self:writeMetatile(x, y, Game3.MT_SOOTOPOLIS_ICE_CRACKED)
        any = true
      end
    end
  end
  return any
end

function Game3:iceFrameFallsToHole()
  local rows = self.map and self.map.mapScripts and self.map.mapScripts.onFrame
  if type(rows) ~= "table" then return false end
  for i = 1, #rows do
    local row = rows[i]
    if row and (row.var or 0) == Game3.VAR_ICE_STEP_COUNT
        and (row.value or 0) == 0 then
      return true
    end
  end
  return false
end

function Game3:behaviorOf(mid)
  local map = self.map
  local spec = map and self.data.tilesets and self.data.tilesets.byId
    and self.data.tilesets.byId[map.tileset]
  local behavior = spec and spec.behavior
  if type(behavior) ~= "table" then return 0 end
  return behavior[mid] or 0
end

function Game3:clearAshAt(x, y)
  local map = self.map
  local i = self:gridIndex(map, x, y)
  if not i then return false end
  local mid = Game3.metatileOf(map.grid[i])
  local dest = Game3.ASH_CLEAR[mid] or (mid + 1)
  self:writeMetatile(x, y, dest)
  if self:itemCount(Game3.ITEM_SOOT_SACK) > 0 then
    self.scriptVars = self.scriptVars or {}
    local n = (self.scriptVars[Game3.VAR_ASH_GATHER_COUNT] or 0) + 1
    if n > 9999 then n = 9999 end
    self.scriptVars[Game3.VAR_ASH_GATHER_COUNT] = n
  end
  return true
end

function Game3:shiftFortreeAt(x, y, delta)
  if self:behaviorAt(self.map, x, y) ~= Game3.MB_FORTREE_BRIDGE then return false end
  local map = self.map
  local i = self:gridIndex(map, x, y)
  if not i then return false end
  local mid = Game3.metatileOf(map.grid[i])
  local dest = mid + delta
  if self:behaviorOf(dest) ~= Game3.MB_FORTREE_BRIDGE then return false end
  return self:writeMetatile(x, y, dest)
end

function Game3.pacifidlogPartner(behavior)
  if behavior == Game3.MB_PACIFIDLOG_VERTICAL_LOG_1 then return 0, 1 end
  if behavior == Game3.MB_PACIFIDLOG_VERTICAL_LOG_2 then return 0, -1 end
  if behavior == Game3.MB_PACIFIDLOG_HORIZONTAL_LOG_1 then return 1, 0 end
  if behavior == Game3.MB_PACIFIDLOG_HORIZONTAL_LOG_2 then return -1, 0 end
end

function Game3.isPacifidlogLog(behavior)
  return Game3.pacifidlogPartner(behavior) ~= nil
end

function Game3:setPacifidlogTile(x, y, state)
  local map = self.map
  local i = self:gridIndex(map, x, y)
  if not i then return false end
  local mid = Game3.metatileOf(map.grid[i])
  local row = Game3.PACIFIDLOG_STAGE[mid]
  if row then
    return self:writeMetatile(x, y, row[state + 1] or row[1])
  end
  return self:writeMetatile(x, y, mid - (mid % 3) + state)
end

function Game3:setPacifidlogPair(x, y, state)
  local b = self:behaviorAt(self.map, x, y)
  local dx, dy = Game3.pacifidlogPartner(b)
  if dx == nil then return false end
  self:setPacifidlogTile(x, y, state)
  self:setPacifidlogTile(x + dx, y + dy, state)
  return true
end

function Game3:runStepCallback(prevX, prevY)
  local id = self.stepCallback
  if not id then return false end
  local x, y = self.playerX, self.playerY
  local b = self:behaviorAt(self.map, x, y)
  local moved = prevX ~= nil and (prevX ~= x or prevY ~= y)
  if id == Game3.STEP_CB_ASH then
    if b == Game3.MB_ASHGRASS then return self:clearAshAt(x, y) end
  elseif id == Game3.STEP_CB_FORTREE then
    if moved then self:shiftFortreeAt(prevX, prevY, -1) end
    return self:shiftFortreeAt(x, y, 1)
  elseif id == Game3.STEP_CB_PACIFIDLOG then
    if moved and Game3.isPacifidlogLog(self:behaviorAt(self.map, prevX, prevY)) then
      self:setPacifidlogPair(prevX, prevY, 0)
    end
    if Game3.isPacifidlogLog(b) then return self:setPacifidlogPair(x, y, 2) end
  elseif id == Game3.STEP_CB_SECRET_BASE then
    -- secret_base.c sub_80BCF1C: only on the frame the player's tile
    -- actually changes, and only one of the four can fire.
    if moved then return self:secretBaseStepEffect(x, y, b) end
  elseif id == Game3.STEP_CB_CRACKED_FLOOR then
    -- The countdown itself is ticked per frame in walkHeld, the way the
    -- cart's task does; this branch only arms and handles the hole.
    if b == Game3.MB_CRACKED_FLOOR_HOLE then
      self:setScriptVar(Game3.VAR_ICE_STEP_COUNT, 0)
      return self:fallDownHole()
    end
    if b == Game3.MB_CRACKED_FLOOR then
      if moved then
        -- GetPlayerSpeed() != 4: the Mach Bike is the one speed that does
        -- not reset the counter this var does double duty for.
        if self.bike ~= "mach" then
          self:setScriptVar(Game3.VAR_ICE_STEP_COUNT, 0)
        end
        self:armCrackedFloor(x, y)
      end
      return false
    end
  elseif id == Game3.STEP_CB_TRUCK then
    return self:endTruckSequence()
  elseif id == Game3.STEP_CB_ICE then
    if b == Game3.MB_CRACKED_ICE then
      self:setScriptVar(Game3.VAR_ICE_STEP_COUNT, 0)
      local i = self:gridIndex(self.map, x, y)
      if i and self.map and self.map.grid then
        local mid = Game3.metatileOf(self.map.grid[i])
        if mid == Game3.MT_SOOTOPOLIS_ICE_CRACKED then
          self:writeMetatile(x, y, Game3.MT_SOOTOPOLIS_ICE_BROKEN)
        end
      end
      -- Sootopolis ON_FRAME warphole MAP_SOOTOPOLIS_CITY_GYM_B1F.
      -- Do not snap to spawn first; dest xy is the hole the player is on.
      if self:iceFrameFallsToHole() then return true end
      return self:fallDownHole()
    end
    if b == Game3.MB_THIN_ICE then
      local n = self:varGet(Game3.VAR_ICE_STEP_COUNT) + 1
      if n > 65535 then n = n - 65536 end
      self:setScriptVar(Game3.VAR_ICE_STEP_COUNT, n)
      self:markSootopolisIceCracked(x, y)
      return self:crackTileAt(x, y)
    end
  end
  return false
end

function Game3:advance()
  if self.phase == "boot" then
    return self:beginNewGame()
  end
end

function Game3:moveScroll(delta)
  if self.phase ~= "roster" then return end
  local max = math.max(1, #self.named)
  self.scroll = ((self.scroll - 1 + delta) % max) + 1
end

local LAND_GRASS = {
  [0x02] = true, -- MB_TALL_GRASS
  [0x03] = true, -- MB_LONG_GRASS
  [0x07] = true, -- MB_SHORT_GRASS
  [0x24] = true, -- MB_ASHGRASS
}

-- pokeruby sTileBitAttributes: wildEncounter and not surfable.
-- MB_SHORT_GRASS 0x07 has no encounter bit; cave floors are 0x0B.
local LAND_WILD = {
  [0x02] = true, -- MB_TALL_GRASS
  [0x03] = true, -- MB_LONG_GRASS
  [0x05] = true, -- MB_UNUSED_05
  [0x06] = true, -- MB_UNUSED_DEEP_SAND
  [0x08] = true, -- MB_UNUSED_CAVE
  [0x0B] = true, -- MB_INDOOR_ENCOUNTER
  [0x24] = true, -- MB_ASHGRASS
  [0x25] = true, -- MB_FOOTPRINTS
}

local SURFABLE = {
  [0x10] = true, -- MB_POND_WATER
  [0x11] = true, -- MB_INTERIOR_DEEP_WATER
  [0x12] = true, -- MB_DEEP_WATER
  [0x13] = true, -- MB_WATERFALL
  [0x14] = true, -- MB_SOOTOPOLIS_DEEP_WATER
  [0x15] = true, -- MB_OCEAN_WATER
  [0x19] = true, -- MB_NO_SURFACING
  [0x22] = true, -- MB_SEAWEED
  [0x2A] = true, -- MB_SEAWEED_NO_SURFACING
  [0x50] = true, -- MB_EASTWARD_CURRENT
  [0x51] = true, -- MB_WESTWARD_CURRENT
  [0x52] = true, -- MB_NORTHWARD_CURRENT
  [0x53] = true, -- MB_SOUTHWARD_CURRENT
  [0x6C] = true, -- MB_WATER_DOOR
  [0x6D] = true, -- MB_WATER_SOUTH_ARROW_WARP
  [0x6F] = true, -- MB_UNUSED_6F
}

function Game3.isLandGrass(behavior)
  return LAND_GRASS[behavior or 0] == true
end

function Game3.isLandWildEncounter(behavior)
  return LAND_WILD[behavior or 0] == true
end

-- pokeruby BattleSetup_GetEnvironmentId.
function Game3:battleEnvironment()
  local b = 0
  local map = self.map
  if map then
    b = self:behaviorAt(map, self.playerX or 0, self.playerY or 0) or 0
  end
  if b == Game3.MB_TALL_GRASS then return Game3.BATTLE_ENV_GRASS end
  if b == Game3.MB_LONG_GRASS then return Game3.BATTLE_ENV_LONG_GRASS end
  if b == Game3.MB_SAND or b == Game3.MB_UNUSED_DEEP_SAND then
    return Game3.BATTLE_ENV_SAND
  end
  local t = map and (map.mapType or 0) or 0
  if t == Game3.MAP_TYPE_UNDERGROUND then
    if b == Game3.MB_INDOOR_ENCOUNTER then return Game3.BATTLE_ENV_BUILDING end
    if Game3.isSurfable(b) then return Game3.BATTLE_ENV_POND end
    return Game3.BATTLE_ENV_CAVE
  end
  if t == Game3.MAP_TYPE_INDOOR or t == Game3.MAP_TYPE_SECRET_BASE then
    return Game3.BATTLE_ENV_BUILDING
  end
  if t == Game3.MAP_TYPE_UNDERWATER then return Game3.BATTLE_ENV_UNDERWATER end
  if t == Game3.MAP_TYPE_OCEAN_ROUTE then
    if Game3.isSurfable(b) then return Game3.BATTLE_ENV_WATER end
    return Game3.BATTLE_ENV_PLAIN
  end
  if b == Game3.MB_OCEAN_WATER or b == Game3.MB_SEMI_DEEP_WATER
      or b == Game3.MB_UNUSED_DEEP_WATER then
    return Game3.BATTLE_ENV_WATER
  end
  if Game3.isSurfable(b) then return Game3.BATTLE_ENV_POND end
  if b == Game3.MB_MOUNTAIN_TOP then return Game3.BATTLE_ENV_MOUNTAIN end
  if self.surfing then return Game3.BATTLE_ENV_WATER end
  return Game3.BATTLE_ENV_PLAIN
end

function Game3.isWaterfall(behavior)
  return (behavior or 0) == Game3.MB_WATERFALL
end

function Game3.isSurfable(behavior)
  return SURFABLE[behavior or 0] == true
end

-- metatile_behavior.c IsReflective. Ocean is surfable but does not
-- spawn a character reflection; pond / ice / under-bridge do.
local REFLECTIVE = {
  [0x10] = true, -- MB_POND_WATER
  [0x14] = true, -- MB_SOOTOPOLIS_DEEP_WATER
  [0x16] = true, -- MB_PUDDLE
  [0x1A] = true, -- MB_UNUSED_SOOTOPOLIS_DEEP_WATER_2
  [0x20] = true, -- MB_ICE
  [0x2B] = true, -- MB_REFLECTION_UNDER_BRIDGE
}

function Game3.isReflective(behavior)
  return REFLECTIVE[behavior or 0] == true
end

-- metatile_behavior.c MetatileBehavior_IsSurfableFishableWater -- the
-- predicate IsPlayerFacingSurfableFishableWater uses to offer SURF. It is
-- a much shorter list than "surfable": no seaweed, no MB_NO_SURFACING, no
-- waterfall, no water doors. Deriving it from isSurfable meant the game
-- offered to SURF on underwater seaweed.
local SURF_START = {
  [0x10] = true, -- MB_POND_WATER
  [0x11] = true, -- MB_SEMI_DEEP_WATER
  [0x12] = true, -- MB_UNUSED_DEEP_WATER
  [0x14] = true, -- MB_SOOTOPOLIS_DEEP_WATER
  [0x15] = true, -- MB_OCEAN_WATER
  [0x50] = true, -- MB_UNUSED_EASTWARD_CURRENT
  [0x51] = true, -- MB_WESTWARD_CURRENT
  [0x52] = true, -- MB_NORTHWARD_CURRENT
  [0x53] = true, -- MB_SOUTHWARD_CURRENT
}

function Game3.isSurfStart(behavior)
  return SURF_START[behavior or 0] == true
end

-- metatile_behavior.c MetatileBehavior_IsDiveable takes three behaviours:
-- MB_SEMI_DEEP_WATER (0x11), MB_UNUSED_DEEP_WATER (0x12) and
-- MB_SOOTOPOLIS_DEEP_WATER (0x14). 0x11 was missing, and it is the one every
-- ocean dive spot actually uses -- ROUTE 134's patch around (60,31) is 0x11 --
-- so DIVE simply said "You can't use that here!" on every real dive tile.
-- The engine's own name for 0x11, MB_INTERIOR_DEEP_WATER, is what hid it.
function Game3.isDiveable(behavior)
  local b = behavior or 0
  return b == Game3.MB_INTERIOR_DEEP_WATER
      or b == Game3.MB_DEEP_WATER
      or b == Game3.MB_SOOTOPOLIS_DEEP_WATER
end

function Game3.isUnableToEmerge(behavior)
  local b = behavior or 0
  return b == Game3.MB_NO_SURFACING or b == Game3.MB_SEAWEED_NO_SURFACING
end

function Game3.isCounter(behavior)
  return (behavior or 0) == Game3.MB_COUNTER
end

-- metatile_behavior.c MetatileBehavior_IsPC is MB_PC and nothing else.
-- MB_SECRET_BASE_PC gets SecretBase_EventScript_PC instead, further down
-- GetInteractedMetatileScript -- treating it as storage is what made the
-- base's PC open the box system rather than DECORATION / PACK UP.
-- MB_PLAYER_ROOM_PC_ON is the bedroom PC, which this engine still routes
-- to storage.
function Game3.isPc(behavior)
  local b = behavior or 0
  return b == Game3.MB_PC or b == Game3.MB_PLAYER_ROOM_PC
end

Game3.MB_RECORD_MIXING_SECRET_BASE_PC = 0xB1
Game3.MB_SECRET_BASE_SAND_ORNAMENT = 0xBF
Game3.MB_SECRET_BASE_SHIELD_OR_TOY_TV = 0xC4

function Game3.isSecretBasePc(behavior)
  return (behavior or 0) == Game3.MB_SECRET_BASE_PC
end

function Game3.topIsOverlay(layerType)
  return (layerType or 0) ~= Game3.LAYER_COVERED
end

-- GBA tile 0 on BG1 is blank. Our top atlas still has a quad there, so a
-- LAYER_NORMAL metatile whose top four tiles are 0 must not ride overlay.
function Game3:metatileTopEmpty(map, mid)
  local byId = self.data.tilesets and self.data.tilesets.byId
  local spec = byId and map and byId[map.tileset]
  local row = spec and spec.tiles and spec.tiles[mid]
  if type(row) ~= "table" then return false end
  return (row[5] or 0) == 0 and (row[6] or 0) == 0
    and (row[7] or 0) == 0 and (row[8] or 0) == 0
end

function Game3:topIsOverlayAt(map, x, y)
  local behavior = self:behaviorAt(map, x, y)
  if Game3.isLandGrass(behavior) then return false end
  if behavior == Game3.MB_BERRY_TREE_SOIL then return false end
  -- Route 110's seaside cycling road sits next to LAYER_NORMAL ocean
  -- (mid 786). BG1 overlay would paint that water over the 32px bike
  -- sprites that hang 8px off the 2-tile road.
  if Game3.isSurfable(behavior) then return false end
  if not Game3.topIsOverlay(self:layerTypeAt(map, x, y)) then return false end
  if not (map and map.grid) then return true end
  local mid = Game3.metatileOf(map.grid[(y or 0) * (map.width or 0) + (x or 0) + 1])
  if self:metatileTopEmpty(map, mid) then return false end
  return true
end

-- pokeruby METATILE_LAYER_TYPE_SPLIT: BG1's top 8px overlay sprites, the
-- bottom 8px sit on BG2 with the ground. Blitting the whole 16x16 overlay
-- buries a 16x32 OW sprite's head (tree trunks, Devon Corp door/sign).
function Game3.metatileTopPassMode(layerType, topPass, overlay)
  if not topPass then return "full" end
  local lt = layerType or 0
  -- LAYER_COVERED is BG3 (bottom) + BG2 (middle), never BG1. Do not
  -- consult `overlay`: if layerTypeAt is right and topIsOverlayAt is
  -- wrong, the picket fence still has to land under sprites.
  if lt == Game3.LAYER_COVERED then
    if topPass == "overlay" then return "skip" end
    return "full"
  end
  if overlay and lt == Game3.LAYER_SPLIT then
    if topPass == "overlay" then return "top8" end
    return "bottom8"
  end
  if topPass == "overlay" then
    return overlay and "full" or "skip"
  end
  return overlay and "skip" or "full"
end

-- General-tileset VRAM slots that TilesetCB_General DMAs (water / flowers).
function Game3.isGeneralAnimTile(tid)
  tid = (tid or 0) % 1024
  return tid >= 108 and tid <= 137
end

-- Flowers are tiles 127-130 (0x80 bytes at BG_TILE_ADDR(127)). Water is
-- 108-137, but ledges and treetops reuse those numbers in other
-- tilesets — only flip water on surfable metatiles, flowers otherwise.
function Game3.isFlowerAnimTile(tid)
  tid = (tid or 0) % 1024
  return tid >= 127 and tid <= 130
end

-- Core water DMA is VRAM 108-126. 127-130 are flowers; 131-137 share the
-- water DMA range with rock. A horizontal flip is only a stand-in for
-- open water, not pond banks or cliff lips.
function Game3.isWaterAnimTile(tid)
  tid = (tid or 0) % 1024
  return tid >= 108 and tid <= 126
end

-- Flower DMA is VRAM 127-130. Water-edge / cliff metatiles mix those
-- slots with water (108-126) or rock (131+); flipping them makes the
-- white harbor cap blink instead of the water swaying.
function Game3.blocksFlowerAnim(tid)
  tid = (tid or 0) % 1024
  if tid >= 108 and tid <= 126 then return true end
  return tid > 130 and tid < 512
end

function Game3.shouldAnimCorner(tid, behavior, tiles, start, collision)
  if not Game3.isGeneralAnimTile(tid) then return false end
  if Game3.ledgeDelta(behavior) then return false end
  if Game3.isSurfable(behavior) then
    -- Route 104's pond banks (mid 176/177/184) mix water 108-124 with
    -- transparent 0 and foam. Mirroring those 8x8s makes the brown
    -- cliff-shore jump; the ROM DMA keeps the bank shape.
    if not Game3.isWaterAnimTile(tid) then return false end
    if type(tiles) == "table" then
      start = start or 1
      for i = 0, 3 do
        if not Game3.isWaterAnimTile(tiles[start + i]) then return false end
      end
    end
    return true
  end
  if not Game3.isFlowerAnimTile(tid) then return false end
  -- Solid (collision ~= 0) harbor walls share flower VRAM. Lua 0 is
  -- walkable and must still flip.
  if collision ~= nil and collision ~= 0 then return false end
  if type(tiles) == "table" then
    start = start or 1
    for i = 0, 3 do
      if Game3.blocksFlowerAnim(tiles[start + i]) then return false end
    end
  end
  return true
end

function Game3:tileAnimFlip()
  return math.floor((self.playSeconds or 0) * 4) % 2 == 1
end

function Game3.chooseLandSlot(roll100)
  local r = roll100 or 0
  if r < 20 then return 0 end
  if r < 40 then return 1 end
  if r < 50 then return 2 end
  if r < 60 then return 3 end
  if r < 70 then return 4 end
  if r < 80 then return 5 end
  if r < 85 then return 6 end
  if r < 90 then return 7 end
  if r < 94 then return 8 end
  if r < 98 then return 9 end
  if r < 99 then return 10 end
  return 11
end

function Game3.chooseWaterRockSlot(roll100)
  local r = roll100 or 0
  if r < 60 then return 0 end
  if r < 90 then return 1 end
  if r < 95 then return 2 end
  if r < 99 then return 3 end
  return 4
end

function Game3.chooseFishSlot(rod, roll100)
  local r = roll100 or 0
  rod = rod or 0
  if rod == Game3.GOOD_ROD then
    if r < 60 then return 2 end
    if r < 80 then return 3 end
    return 4
  end
  if rod == Game3.SUPER_ROD then
    if r < 40 then return 5 end
    if r < 80 then return 6 end
    if r < 95 then return 7 end
    if r < 99 then return 8 end
    return 9
  end
  if r < 70 then return 0 end
  return 1
end

function Game3.statHP(base, level, iv, ev)
  base = base or 1
  level = level or 1
  iv = iv or 0
  ev = math.floor((tonumber(ev) or 0) / 4)
  return math.floor(((2 * base + iv + ev) * level) / 100) + level + 10
end

function Game3.statOther(base, level, iv, natureTenths, ev)
  base = base or 1
  level = level or 1
  iv = iv or 0
  natureTenths = natureTenths or 10
  ev = math.floor((tonumber(ev) or 0) / 4)
  local n = math.floor(((2 * base + iv + ev) * level) / 100) + 5
  if natureTenths ~= 10 then
    n = math.floor(n * natureTenths / 10)
  end
  if n < 1 then n = 1 end
  return n
end

function Game3.natureIndex(pid)
  return (pid or 0) % 25
end

function Game3.natureName(pid)
  return Game3.NATURE_NAMES[Game3.natureIndex(pid)] or "HARDY"
end

-- stat is 0=Atk, 1=Def, 2=Spe, 3=SpA, 4=SpD.  Returns tenths (9/10/11).
function Game3.natureMul(pid, stat)
  local n = Game3.natureIndex(pid)
  local boost, drop = math.floor(n / 5), n % 5
  if boost == drop then return 10 end
  if stat == boost then return 11 end
  if stat == drop then return 9 end
  return 10
end

-- Gen 3 shiny (pokeruby IsShinyOtIdPersonality / GetShinyValue):
--   shinyValue = HIHALF(otId) XOR LOHALF(otId) XOR HIHALF(pid) XOR LOHALF(pid)
--   shiny iff shinyValue < 8  (odds 1/8192). Gen2 DV shiny is untouched.
-- Self-check vectors: Game3.INGAME_TRADES[*] are non-shiny; otId=0 pid=0 is
-- shiny (value 0); otId=0x12345678 pid=0x444C is shiny (value 0).
function Game3.hiHalf(n)
  return math.floor((tonumber(n) or 0) / 65536) % 65536
end

function Game3.loHalf(n)
  return (tonumber(n) or 0) % 65536
end

function Game3.u16Xor(a, b)
  -- Pure 16-bit XOR (no bit lib) so Game3 stays free of an extra require.
  a = (tonumber(a) or 0) % 65536
  b = (tonumber(b) or 0) % 65536
  local r, bit = 0, 1
  for _ = 1, 16 do
    local abit, bbit = a % 2, b % 2
    if abit ~= bbit then r = r + bit end
    a = math.floor(a / 2)
    b = math.floor(b / 2)
    bit = bit * 2
  end
  return r
end

function Game3.shinyValue(otId, pid)
  local a = Game3.u16Xor(Game3.hiHalf(otId), Game3.loHalf(otId))
  local b = Game3.u16Xor(Game3.hiHalf(pid), Game3.loHalf(pid))
  return Game3.u16Xor(a, b)
end

function Game3.isShinyOtIdPersonality(otId, pid)
  return Game3.shinyValue(otId, pid) < 8
end

function Game3:isShinyMon(mon)
  if type(mon) ~= "table" then return false end
  local pid = mon.pid or mon.personality or 0
  -- HoF snapshots store OT as tid; contest subjects may pass otId.
  local ot = mon.otId
  if ot == nil then ot = mon.tid end
  if ot == nil then ot = self:ensureTrainerId() end
  return Game3.isShinyOtIdPersonality(ot, pid)
end

-- Debug: when true, makeMon forces a shiny PID vs stamped OT (wild/gifts).
-- makeTrainerMon passes opts.trainer so foes stay anti-shiny.
-- Defaults ON under --developer / POKEPORT_DEV=1 (Play-Developer.bat); backtick
-- toggles at runtime (Gen3 has no Lua REPL console).
Game3.forceShiny = (os.getenv("POKEPORT_DEV") == "1" or _G.POKEPORT_DEV_MODE == true)

-- Rewrites pid so isShinyOtIdPersonality(otId, pid), keeping nature (pid%25).
function Game3.personalityForcedShiny(otId, pid)
  pid = tonumber(pid) or 0
  otId = tonumber(otId) or 0
  if Game3.isShinyOtIdPersonality(otId, pid) then return pid end
  local nature = pid % 25
  local otXor = Game3.u16Xor(Game3.hiHalf(otId), Game3.loHalf(otId))
  for shinyBits = 0, 7 do
    local want = Game3.u16Xor(otXor, shinyBits)
    for hi = 0, 65535 do
      local lo = Game3.u16Xor(hi, want)
      local cand = hi * 65536 + lo
      if cand % 25 == nature then
        return cand
      end
    end
  end
  return pid
end

function Game3.zeroIvs()
  return { hp = 0, atk = 0, def = 0, spe = 0, spa = 0, spd = 0 }
end

function Game3.copyIvs(ivs)
  ivs = ivs or {}
  return {
    hp = ivs.hp or 0,
    atk = ivs.atk or 0,
    def = ivs.def or 0,
    spe = ivs.spe or 0,
    spa = ivs.spa or 0,
    spd = ivs.spd or 0,
  }
end

-- pokeruby atkC1_hiddenpowercalc: bit 0 of each IV packed hp..spd.
function Game3.hiddenPowerTypeBits(ivs)
  ivs = ivs or {}
  local function b0(n) return (tonumber(n) or 0) % 2 end
  return b0(ivs.hp) + b0(ivs.atk) * 2 + b0(ivs.def) * 4
    + b0(ivs.spe) * 8 + b0(ivs.spa) * 16 + b0(ivs.spd) * 32
end

function Game3.hiddenPowerPowerBits(ivs)
  ivs = ivs or {}
  local function b1(n) return math.floor((tonumber(n) or 0) / 2) % 2 end
  return b1(ivs.hp) + b1(ivs.atk) * 2 + b1(ivs.def) * 4
    + b1(ivs.spe) * 8 + b1(ivs.spa) * 16 + b1(ivs.spd) * 32
end

function Game3.hiddenPowerType(ivs)
  local t = math.floor(Game3.hiddenPowerTypeBits(ivs) * 15 / 63) + 1
  if t >= Game3.TYPE_MYSTERY then t = t + 1 end
  return t
end

function Game3.hiddenPowerPower(ivs)
  return 30 + math.floor(Game3.hiddenPowerPowerBits(ivs) * 40 / 63)
end

function Game3:attackType(attacker, move)
  if (move and move.effect or 0) == Game3.EFFECT_HIDDEN_POWER then
    return Game3.hiddenPowerType(attacker and attacker.ivs)
  end
  if (move and move.effect or 0) == Game3.EFFECT_WEATHER_BALL then
    return self:weatherBallType()
  end
  return (move and move.type) or 0
end

-- pokeemerald gExperienceTables.  Level 1 is 0; Medium Slow is negative
-- below that so it is clamped.
function Game3.expAtLevel(growth, level)
  level = math.floor(level or 1)
  if level <= 1 then return 0 end
  if level > 100 then level = 100 end
  growth = growth or Game3.GROWTH_MEDIUM_SLOW
  local n, n2, n3 = level, level * level, level * level * level
  if growth == Game3.GROWTH_MEDIUM_FAST then return n3 end
  if growth == Game3.GROWTH_FAST then return math.floor(4 * n3 / 5) end
  if growth == Game3.GROWTH_SLOW then return math.floor(5 * n3 / 4) end
  if growth == Game3.GROWTH_MEDIUM_SLOW then
    return math.floor(6 * n3 / 5) - 15 * n2 + 100 * n - 140
  end
  if growth == Game3.GROWTH_ERRATIC then
    if n < 50 then return math.floor(n3 * (100 - n) / 50) end
    if n < 68 then return math.floor(n3 * (150 - n) / 100) end
    if n < 98 then
      return math.floor(n3 * math.floor((1911 - 10 * n) / 3) / 500)
    end
    return math.floor(n3 * (160 - n) / 100)
  end
  if growth == Game3.GROWTH_FLUCTUATING then
    local k
    if n < 15 then k = math.floor((n + 1) / 3) + 24
    elseif n < 36 then k = n + 14
    else k = math.floor(n / 2) + 32 end
    return math.floor(n3 * k / 50)
  end
  return n3
end

function Game3.expBarFill(mon)
  if not mon then return 0 end
  local growth = mon.growth or Game3.GROWTH_MEDIUM_SLOW
  local lv = mon.level or 1
  if lv >= 100 then return 1 end
  local at = Game3.expAtLevel(growth, lv)
  local nxt = Game3.expAtLevel(growth, lv + 1)
  local exp = mon.exp or at
  if nxt <= at then return 1 end
  local t = (exp - at) / (nxt - at)
  if t < 0 then return 0 end
  if t > 1 then return 1 end
  return t
end

function Game3.wildExp(yield, level, trainer)
  local a = math.max(1, math.floor((yield or 0) * (level or 1) / 7))
  if trainer then a = math.floor(a * 3 / 2) end
  return a
end

function Game3.damage(level, power, attack, defense, stab, typeMul)
  attack = math.max(1, attack or 1)
  defense = math.max(1, defense or 1)
  typeMul = typeMul or 10
  if typeMul <= 0 then return 0 end
  local base = math.floor(math.floor((2 * (level or 1) / 5 + 2)
    * (power or 1) * attack / defense) / 50) + 2
  if stab then base = math.floor(base * 3 / 2) end
  if typeMul ~= 10 then base = math.floor(base * typeMul / 10) end
  return math.max(1, base)
end

function Game3.stageMul(stage)
  stage = stage or 0
  if stage >= 0 then return (2 + stage) / 2 end
  return 2 / (2 - stage)
end

-- pokeruby gAccuracyStageRatios: indexes 0-12 are stages -6..+6.
Game3.ACC_STAGE_RATIOS = {
  { 33, 100 }, { 36, 100 }, { 43, 100 }, { 50, 100 }, { 60, 100 }, { 75, 100 },
  { 1, 1 },
  { 133, 100 }, { 166, 100 }, { 2, 1 }, { 233, 100 }, { 133, 50 }, { 3, 1 },
}

function Game3.accuracyFromStages(moveAcc, atkAcc, defEva)
  local buff = (tonumber(atkAcc) or 0) - (tonumber(defEva) or 0) + 6
  if buff < 0 then buff = 0 elseif buff > 12 then buff = 12 end
  local r = Game3.ACC_STAGE_RATIOS[buff + 1]
  return math.floor((tonumber(moveAcc) or 0) * r[1] / r[2])
end

function Game3.isPhysical(moveType)
  return (moveType or 0) < 9
end

function Game3.typeRgb(moveType)
  local c = Game3.TYPE_RGB[tonumber(moveType) or 0]
  if c then return c[1], c[2], c[3] end
  return 1, 1, 0.55
end

function Game3.catchAnimDuration(catch)
  if not catch then return 0 end
  return (catch.throw or Game3.CATCH_THROW)
    + (catch.open or 0) + (catch.bounce or 0)
    + (catch.shakes or 0) * (catch.perShake or Game3.CATCH_SHAKE)
    + (catch.stars or 0) + (catch.breakout or 0)
end

-- Ball shell colors by item (procedural fallback when tradeBall is missing).
function Game3.catchBallColors(itemId)
  itemId = tonumber(itemId) or Game3.ITEM_POKE_BALL
  local colors = {
    [Game3.ITEM_MASTER_BALL] = { 0.55, 0.18, 0.72 },
    [Game3.ITEM_ULTRA_BALL] = { 0.95, 0.78, 0.12 },
    [Game3.ITEM_GREAT_BALL] = { 0.22, 0.42, 0.88 },
    [Game3.ITEM_SAFARI_BALL] = { 0.55, 0.78, 0.28 },
    [Game3.ITEM_NET_BALL] = { 0.18, 0.62, 0.72 },
    [Game3.ITEM_DIVE_BALL] = { 0.18, 0.48, 0.82 },
    [Game3.ITEM_NEST_BALL] = { 0.42, 0.78, 0.28 },
    [Game3.ITEM_REPEAT_BALL] = { 0.82, 0.48, 0.12 },
    [Game3.ITEM_TIMER_BALL] = { 0.82, 0.42, 0.18 },
    [Game3.ITEM_LUXURY_BALL] = { 0.72, 0.28, 0.42 },
    [Game3.ITEM_PREMIER_BALL] = { 0.92, 0.92, 0.95 },
  }
  return colors[itemId] or { 0.93, 0.18, 0.18 }
end

-- Enemy visibility/scale during catch cinema (pokeruby shrink-into-ball).
-- Returns hide, scale, yOff, alpha for the foe sprite.
function Game3.catchEnemyVisual(catch, catchT)
  if not catch then return false, 1, 0, 1 end
  catchT = catchT or 0
  local throw = catch.throw or Game3.CATCH_THROW
  local open = catch.open or 0
  local bounce = catch.bounce or 0
  local per = catch.perShake or Game3.CATCH_SHAKE
  local shakes = catch.shakes or 0
  local afterShakes = throw + open + bounce + shakes * per
  local dur = Game3.catchAnimDuration(catch)
  -- Breakout: mon pops back out of the ball.
  if (not catch.ok) and (catch.breakout or 0) > 0 and catchT >= afterShakes then
    local u = (catchT - afterShakes) / math.max(catch.breakout, 0.01)
    if u > 1 then u = 1 end
    local sc = 0.15 + 0.85 * u
    return false, sc, (1 - u) * 10, math.min(1, 0.35 + u)
  end
  if catchT < throw * 0.92 then
    return false, 1, 0, 1
  end
  if catchT < throw + open then
    local u = (catchT - throw) / math.max(open, 0.01)
    if u < 0 then u = 0 elseif u > 1 then u = 1 end
    -- Brief contact, then shrink toward the ball (sub_813FEC8 case 1).
    if u < 0.18 then
      return false, 1, 0, 1
    end
    local s = (u - 0.18) / 0.82
    local sc = 1 - 0.88 * s
    if sc < 0.12 then sc = 0.12 end
    return false, sc, -s * 14, 1 - s * 0.55
  end
  -- Inside the ball until stars/breakout.
  if catchT < dur then
    return true, 0.12, 0, 0
  end
  -- Success linger / past stars: mon stays sealed (pokeruby shows only the ball).
  if catch.ok then
    return true, 0.12, 0, 0
  end
  return false, 1, 0, 1
end


-- Normalize trainer class for TRAINER_CLASS_PIC lookup.
function Game3.normalizeTrainerClass(className)
  local s = tostring(className or ""):upper()
  s = s:gsub("%s+", ""):gsub("[^A-Z0-9]", "")
  return s
end

function Game3:battleSceneOn()
  local opt = self.options
  return not (opt and opt.battleScene == false)
end

-- Arm entrance / send-out cinema. mode: trainer | wild | foe_switch | player_switch
function Game3:armIntroCinema(mode, opts)
  local b = self.battle
  if not b then return end
  mode = mode or (b.isTrainer and "trainer" or "wild")
  opts = opts or {}
  if not self:battleSceneOn() then
    b.introCinema = {
      mode = mode, phase = "done", t = 0,
      enemyReleased = true, enemy2Released = true,
      playerReleased = true, player2Released = true, trainerGone = true,
    }
    b.introT = 1
    return
  end
  local wildish = (mode == "wild")
  local foeSwitch = (mode == "foe_switch")
  local playerSwitch = (mode == "player_switch")

  -- Mid-battle switch: which slot(s) get ball cinema (doubles-aware).
  local switchSlots = opts.slots
  if type(switchSlots) ~= "table" or #switchSlots < 1 then
    if opts.slot then
      switchSlots = { opts.slot }
    elseif foeSwitch then
      switchSlots = { "enemy" }
    elseif playerSwitch then
      switchSlots = { "player" }
    else
      switchSlots = {}
    end
  end
  local switchSet = {}
  local ordered = {}
  for _, s in ipairs(switchSlots) do
    if (s == "enemy" or s == "enemy2" or s == "player" or s == "player2")
        and not switchSet[s] then
      switchSet[s] = true
      ordered[#ordered + 1] = s
    end
  end
  -- Stable order: foe1, foe2, player1, player2.
  if #ordered > 1 then
    local rank = { enemy = 1, enemy2 = 2, player = 3, player2 = 4 }
    table.sort(ordered, function(a, bb)
      return (rank[a] or 9) < (rank[bb] or 9)
    end)
  end

  local phase
  if mode == "trainer" then
    phase = "trainer_slide"
  elseif mode == "wild" then
    phase = "wild_slide"
  elseif foeSwitch or playerSwitch then
    local first = ordered[1] or (foeSwitch and "enemy" or "player")
    if opts.recall then
      phase = first .. "_recall"
    else
      phase = first .. "_throw"
    end
  else
    phase = "wild_slide"
  end

  local enemyReleased, enemy2Released, playerReleased, player2Released
  if foeSwitch or playerSwitch then
    enemyReleased = not switchSet.enemy
    enemy2Released = not switchSet.enemy2
    playerReleased = not switchSet.player
    player2Released = not switchSet.player2
    if not (b.doubles and b.enemy2) then enemy2Released = true end
    if not (b.doubles and b.player2) then player2Released = true end
  else
    -- Wild mons are already on-field.
    enemyReleased = wildish and true or false
    enemy2Released = wildish and true or false
    playerReleased = false
    player2Released = false
  end

  b.introCinema = {
    mode = mode,
    phase = phase,
    t = 0,
    enemyReleased = enemyReleased,
    enemy2Released = enemy2Released,
    playerReleased = playerReleased,
    player2Released = player2Released,
    trainerGone = mode ~= "trainer",
    switchSlots = ordered,
    switchIdx = 1,
    recall = opts.recall and true or false,
    recallSpecies = opts.recallSpecies,
    recallShiny = opts.recallShiny and true or false,
  }
  b.introT = 0
  self:playIntroPhaseSe(phase)
end


-- Doubles intro: need a separate ball/release for the partner slot.
function Game3:introHasEnemy2()
  local b = self.battle
  return b and b.doubles and b.enemy2 and true or false
end

function Game3:introHasPlayer2()
  local b = self.battle
  return b and b.doubles and b.player2 and true or false
end

function Game3:introGoText()
  local b = self.battle
  local pname = (b and b.player and b.player.name) or "POKeMON"
  if b and b.doubles and b.player2 and b.player2.name then
    return ("Go! %s and %s!"):format(pname, b.player2.name)
  end
  return ("Go! %s!"):format(pname)
end

function Game3:introFoeSentText()
  local b = self.battle
  local label = self:trainerLabel(b and b.npc)
  local ename = (b and b.enemy and b.enemy.name) or "POKeMON"
  if b and b.enemy2 and b.enemy2.name then
    return ("%s sent out %s and %s!"):format(label, ename, b.enemy2.name)
  end
  return ("%s sent out %s!"):format(label, ename)
end

function Game3:introMarkAllReleased(c)
  if not c then return end
  c.enemyReleased = true
  c.enemy2Released = true
  c.playerReleased = true
  c.player2Released = true
  c.trainerGone = true
end

function Game3:introPhaseDuration(phase)
  if phase == "trainer_slide" or phase == "wild_slide" then
    return Game3.SEND_SLIDE
  end
  if phase == "enemy_throw" or phase == "player_throw"
      or phase == "enemy2_throw" or phase == "player2_throw" then
    return Game3.SEND_THROW
  end
  if phase == "enemy_open" or phase == "player_open"
      or phase == "enemy2_open" or phase == "player2_open" then
    return Game3.SEND_OPEN
  end
  if phase == "enemy_recall" or phase == "player_recall"
      or phase == "enemy2_recall" or phase == "player2_recall" then
    return Game3.SEND_RECALL
  end
  return 0
end

function Game3:advanceIntroCinemaPhase()
  local b = self.battle
  local c = b and b.introCinema
  if not c then return end
  local phase = c.phase
  local mode = c.mode

  local function finishSwitchCinema()
    c.phase = "done"
    c.t = 0
    b.introT = 1
    if b.kind == "intro" and mode ~= "foe_switch" and mode ~= "player_switch" then
      self:dismissIntro()
    end
  end

  -- After a switch slot opens (or if no more slots), finish or continue.
  local function afterSwitchSlotOpen(side)
    if side == "enemy" then
      c.enemyReleased = true
      self:armShinySparkle("enemy", b.enemy)
    elseif side == "enemy2" then
      c.enemy2Released = true
      self:armShinySparkle("enemy2", b.enemy2)
    elseif side == "player" then
      c.playerReleased = true
      self:armShinySparkle("player", b.player)
    elseif side == "player2" then
      c.player2Released = true
      self:armShinySparkle("player2", b.player2)
    end
    local slots = c.switchSlots
    local idx = (c.switchIdx or 1) + 1
    c.switchIdx = idx
    if type(slots) == "table" and idx <= #slots then
      local nextSide = slots[idx]
      c.phase = nextSide .. "_throw"
      c.t = 0
      return
    end
    finishSwitchCinema()
  end

  if phase == "trainer_slide" then
    c.phase = "hold"
    c.t = 0
  elseif phase == "wild_slide" then
    c.enemyReleased = true
    c.enemy2Released = true
    self:armShinySparkle("enemy", b.enemy)
    if b.enemy2 then self:armShinySparkle("enemy2", b.enemy2) end
    c.phase = "hold"
    c.t = 0
    b.introT = 1
  elseif phase == "enemy_recall" then
    c.phase = "enemy_throw"
    c.t = 0
  elseif phase == "enemy2_recall" then
    c.phase = "enemy2_throw"
    c.t = 0
  elseif phase == "player_recall" then
    c.phase = "player_throw"
    c.t = 0
  elseif phase == "player2_recall" then
    c.phase = "player2_throw"
    c.t = 0
  elseif phase == "enemy_throw" then
    c.trainerGone = true
    c.phase = "enemy_open"
    c.t = 0
  elseif phase == "enemy_open" then
    if mode == "foe_switch" or mode == "player_switch" then
      afterSwitchSlotOpen("enemy")
    else
      c.enemyReleased = true
      self:armShinySparkle("enemy", b.enemy)
      -- Doubles trainer intro: stagger foe2 after foe1 (Ruby partner delay).
      if mode == "trainer" and self:introHasEnemy2() and not c.enemy2Released then
        c.phase = "enemy2_throw"
        c.t = 0
      elseif mode == "trainer" then
        if not c.skipPlayer then
          b.text = self:introGoText()
          b.printSrc = nil
          b.textPage = 0
          b.printN = 0
          c.phase = "player_throw"
          c.t = 0
        else
          c.phase = "done"
          c.t = 0
          b.introT = 1
          self:dismissIntro()
        end
      else
        c.phase = "done"
        c.t = 0
        b.introT = 1
      end
    end
  elseif phase == "enemy2_throw" then
    c.phase = "enemy2_open"
    c.t = 0
  elseif phase == "enemy2_open" then
    if mode == "foe_switch" or mode == "player_switch" then
      afterSwitchSlotOpen("enemy2")
    else
      c.enemy2Released = true
      self:armShinySparkle("enemy2", b.enemy2)
      if mode == "trainer" then
        if not c.skipPlayer then
          b.text = self:introGoText()
          b.printSrc = nil
          b.textPage = 0
          b.printN = 0
          c.phase = "player_throw"
          c.t = 0
        else
          c.phase = "done"
          c.t = 0
          b.introT = 1
          self:dismissIntro()
        end
      else
        c.phase = "done"
        c.t = 0
        b.introT = 1
      end
    end
  elseif phase == "player_throw" then
    c.phase = "player_open"
    c.t = 0
  elseif phase == "player_open" then
    if mode == "foe_switch" or mode == "player_switch" then
      afterSwitchSlotOpen("player")
    elseif (mode == "trainer" or mode == "wild")
        and self:introHasPlayer2() and not c.player2Released then
      c.playerReleased = true
      self:armShinySparkle("player", b.player)
      c.phase = "player2_throw"
      c.t = 0
    else
      c.playerReleased = true
      self:armShinySparkle("player", b.player)
      c.phase = "done"
      c.t = 0
      b.introT = 1
      if b.kind == "intro" then
        self:dismissIntro()
      end
    end
  elseif phase == "player2_throw" then
    c.phase = "player2_open"
    c.t = 0
  elseif phase == "player2_open" then
    if mode == "foe_switch" or mode == "player_switch" then
      afterSwitchSlotOpen("player2")
    else
      c.player2Released = true
      self:armShinySparkle("player2", b.player2)
      c.phase = "done"
      c.t = 0
      b.introT = 1
      if b.kind == "intro" then
        self:dismissIntro()
      end
    end
  end
  -- SE_BALL_THROW / SE_BALL_OPEN when landing on a throw/open phase.
  self:playIntroPhaseSe(c.phase)
end

function Game3:stepIntroCinema(dt)
  local b = self.battle
  local c = b and b.introCinema
  if not c then
    if b and b.kind == "intro" then
      b.introT = math.min(1, (b.introT or 0) + dt / 0.45)
    end
    return
  end
  if c.phase == "hold" or c.phase == "done" then
    if c.phase == "done" then b.introT = 1 end
    -- Auto-start foe send-out after a short hold so enemy_throw always plays
    -- even if A-confirm is missed; timer lock still prevents mash-skip mid-throw.
    if c.phase == "hold" and c.mode == "trainer" and not c.enemyReleased then
      c.holdT = (c.holdT or 0) + (dt or 0)
      local printing = b.printSrc and b.printN and (#tostring(b.printSrc) > 0)
        and (b.printN < #tostring(b.printSrc))
      if c.holdT >= 0.55 and not printing then
        b.text = self:introFoeSentText()
        b.printSrc = nil
        b.textPage = 0
        b.printN = 0
        c.phase = "enemy_throw"
        c.t = 0
        c.holdT = 0
        self:playIntroPhaseSe(c.phase)
      end
    end
    return
  end
  c.t = (c.t or 0) + (dt or 0)
  local dur = self:introPhaseDuration(c.phase)
  if dur <= 0 then
    self:advanceIntroCinemaPhase()
    return
  end
  local u = c.t / dur
  if u > 1 then u = 1 end
  -- Keep legacy introT roughly in sync for any leftover slide math.
  if c.phase == "trainer_slide" or c.phase == "wild_slide" then
    b.introT = u
  elseif c.enemyReleased and c.playerReleased
      and (not self:introHasEnemy2() or c.enemy2Released)
      and (not self:introHasPlayer2() or c.player2Released) then
    b.introT = 1
  elseif c.enemyReleased then
    b.introT = 0.55 + 0.45 * u
  else
    b.introT = u * 0.35
  end
  if c.t >= dur then
    c.t = 0
    self:advanceIntroCinemaPhase()
  end
end

function Game3:onIntroConfirm()
  local b = self.battle
  if not b then return end
  local c = b.introCinema
  if not c or c.phase == "done" then
    self:dismissIntro()
    return
  end
  local phase = c.phase
  -- Ball throw/open must play via stepIntroCinema. A only finishes the
  -- dialogue printer (caller); acknowledging "sent out" / "Go!" must NOT
  -- skip the foe/player Poké Ball (prior mash path jumped enemy_throw ->
  -- enemy_open in one press, so the arc never painted).
  if phase == "enemy_throw" or phase == "enemy_open"
      or phase == "enemy2_throw" or phase == "enemy2_open"
      or phase == "player_throw" or phase == "player_open"
      or phase == "player2_throw" or phase == "player2_open"
      or phase == "enemy_recall" or phase == "enemy2_recall"
      or phase == "player_recall" or phase == "player2_recall" then
    return
  end
  if phase == "trainer_slide" or phase == "wild_slide" then
    -- Snap slide to hold only; do not chain into enemy_throw same press.
    self:advanceIntroCinemaPhase()
    return
  end
  if c.phase ~= "hold" then
    self:advanceIntroCinemaPhase()
    if c.phase == "done" then return end
    if c.phase ~= "hold" then return end
  end
  -- hold: start remaining send-outs
  local function resetPrinter()
    b.printSrc = nil
    b.textPage = 0
    b.printN = 0
  end
  if c.mode == "trainer" and not c.enemyReleased then
    b.text = self:introFoeSentText()
    resetPrinter()
    c.phase = "enemy_throw"
    c.t = 0
    self:playIntroPhaseSe(c.phase)
    return
  end
  if (c.mode == "wild" or c.mode == "trainer") and not c.playerReleased then
    b.text = self:introGoText()
    resetPrinter()
    c.phase = "player_throw"
    c.t = 0
    self:playIntroPhaseSe(c.phase)
    return
  end
  self:dismissIntro()
end

function Game3:trainerRubyPicPath(pic)
  pic = tonumber(pic)
  if pic == nil or pic < 0 then return nil end
  return ("assets/generated/battle/trainers/ruby_%02d.png"):format(pic)
end

function Game3:trainerClassPicPath(className)
  local key = Game3.normalizeTrainerClass(className)
  local ruby = Game3.TRAINER_CLASS_RUBY_PIC and Game3.TRAINER_CLASS_RUBY_PIC[key]
  if ruby ~= nil then
    local path = self:trainerRubyPicPath(ruby)
    if path then return path end
  end
  local file = Game3.TRAINER_CLASS_PIC and Game3.TRAINER_CLASS_PIC[key]
  if not file and key:find("RIVAL", 1, true) then file = "rival1" end
  if not file then return nil end
  return ("assets/generated/battle/trainers/%s.png"):format(file)
end

function Game3:opponentTrainerImage(npc)
  self._trainerPicCache = self._trainerPicCache or {}
  local function cached(path)
    if not path then return nil end
    if self._trainerPicCache[path] ~= nil then
      local img = self._trainerPicCache[path]
      return img or nil
    end
    local img = self:grabImage(path)
    self._trainerPicCache[path] = img or false
    return img
  end
  local gid = npc and (npc.graphicsId or 0) or 0
  if npc and self.resolveGraphicsId then
    gid = self:resolveGraphicsId(gid) or gid
  end
  if npc and Game3.isRivalGfx and Game3.isRivalGfx(gid) then
    local name = self:isFemale() and "trainerFrontBrendan" or "trainerFrontMay"
    local img = self.cinemaPic and self:cinemaPic(name)
    if img then return img, 64, 64 end
  end
  -- Prefer per-trainer Ruby front pic index (colored 64x64).
  local row = npc and self:trainerRow(npc.trainerId) or nil
  local pic = (npc and (npc.trainerPic or npc.pic)) or (row and row.pic)
  if pic ~= nil then
    local img = cached(self:trainerRubyPicPath(pic))
    if img then return img, 64, 64 end
  end
  local className = npc and (npc.trainerClass or npc.className)
  if (not className or className == "") and row then
    className = row.className
  end
  local path = self:trainerClassPicPath(className)
  local img = cached(path)
  if img then return img, 64, 64 end
  return nil, 64, 64
end

function Game3:playerTrainerBattleImage()
  local female = self.isFemale and self:isFemale()
  local sheet = female and self:cinemaPic("intro3may") or self:cinemaPic("intro3brendan")
  if not sheet then
    sheet = self:cinemaPic("trainerFrontMay") or self:cinemaPic("trainerFrontBrendan")
  end
  return sheet
end

function Game3:drawTrainerSilhouette(cx, cy, facing, alpha, tint)
  local G = love.graphics
  alpha = alpha or 1
  tint = tint or { 0.18, 0.16, 0.22 }
  G.setColor(tint[1], tint[2], tint[3], alpha)
  local dir = (facing == "left") and -1 or 1
  -- Simple 64x64-ish trainer blob: head + torso + legs.
  if G.circle then
    G.circle("fill", cx, cy - 18, 8)
  end
  G.rectangle("fill", cx - 10, cy - 10, 20, 22)
  G.rectangle("fill", cx - 8, cy + 12, 7, 14)
  G.rectangle("fill", cx + 1, cy + 12, 7, 14)
  G.setColor(tint[1] * 1.3, tint[2] * 1.2, tint[3] * 1.1, alpha)
  G.rectangle("fill", cx + dir * 6 - 3, cy - 4, 10, 6)
end

function Game3:drawBattleTrainerPic(img, x, y, scale, alpha, flip)
  local G = love.graphics
  scale = scale or 1
  alpha = alpha or 1
  if img and img.getDimensions then
    local iw, ih = img:getDimensions()
    local fw, fh = iw, ih
    -- intro3 sheets are 4x 64x64 frames; use frame 0 (idle / throw-ready).
    if iw >= 256 and ih >= 64 then
      fw, fh = 64, 64
    elseif iw >= 64 and ih >= 64 and iw ~= ih then
      fw, fh = 64, 64
    end
    local key = ("btpic:%s:%d:%d"):format(tostring(img), fw, fh)
    self.quads = self.quads or {}
    local q = self.quads[key]
    if not q then
      q = love.graphics.newQuad(0, 0, fw, fh, iw, ih)
      self.quads[key] = q
    end
    G.setColor(1, 1, 1, alpha)
    local sx = flip and -scale or scale
    G.draw(img, q, x + fw * scale / 2, y + fh * scale / 2, 0, sx, scale, fw / 2, fh / 2)
    G.setColor(1, 1, 1, 1)
    return
  end
  self:drawTrainerSilhouette(x + 32 * scale, y + 32 * scale,
    flip and "left" or "right", alpha)
  G.setColor(1, 1, 1, 1)
end

-- Visual state for drawBattle during intro / send-out cinema.
-- Returns table: enemy/player hide,scale,slide,alpha; trainers; ball; boxes.
function Game3:introCinemaVisuals()
  local b = self.battle
  local c = b and b.introCinema
  local vis = {
    enemyHide = false, enemyScale = 1, enemySlide = 0, enemyAlpha = 1,
    enemy2Hide = false, enemy2Scale = 1, enemy2Alpha = 1,
    playerHide = false, playerScale = 1, playerSlide = 0, playerAlpha = 1,
    player2Hide = false, player2Scale = 1, player2Alpha = 1,
    showEnemyTrainer = false, enemyTrainerX = 0, enemyTrainerA = 1,
    showPlayerTrainer = false, playerTrainerX = 0, playerTrainerA = 1,
    ball = nil, balls = nil, hideBoxes = false, hidePlayerBox = false,
    recallSide = nil, recallSpecies = nil, recallShiny = false,
  }
  if not c then
    -- Legacy slide-only intro.
    if b and b.kind == "intro" then
      local slide = b.introT or 0
      if slide < 0 then slide = 0 elseif slide > 1 then slide = 1 end
      vis.enemySlide = (1 - slide) * 90
      vis.playerSlide = (1 - slide) * 90
    end
    return vis
  end
  local phase = c.phase
  local t = c.t or 0
  local mode = c.mode
  local switchMode = (mode == "foe_switch" or mode == "player_switch")
  local function uOf(dur)
    local u = t / math.max(dur, 0.01)
    if u < 0 then u = 0 elseif u > 1 then u = 1 end
    return u
  end
  local doubles = b.doubles and true or false
  local epx = Game3.BATTLER_CX.enemy or 176
  local epy = Game3.BATTLER_CY.enemy or 40
  local ppx = Game3.BATTLER_CX.player or 72
  local ppy = Game3.BATTLER_CY.player or 80

  local function foeBall(side, u, openPhase)
    local ecx, ecy = Game3.battlerCenter(side, doubles)
    if openPhase then
      return {
        x = ecx, y = ecy + 8,
        scale = 1.25 + 0.3 * math.sin(u * math.pi),
        open = u < 0.9, angle = 0, frame = (u < 0.9) and 1 or 2,
        burst = u < 0.85 and u / 0.85 or nil,
        sendOut = true,
      }
    end
    -- Arc from trainer hand (slot center +32) to battler center.
    local handX, handY = ecx + 32, ecy + 4
    local destX, destY = ecx, ecy + 8
    local bx = handX + (destX - handX) * u
    local by = handY + (destY - handY) * u - math.sin(u * math.pi) * 40
    return {
      x = bx, y = by, scale = 1.15 + 0.4 * u, open = false,
      angle = u * math.pi * 2.4, frame = math.floor(u * 8) % 2,
      sendOut = true,
    }
  end

  local function playerBall(side, u, openPhase)
    local pcx, pcy = Game3.battlerCenter(side, doubles)
    if openPhase then
      return {
        x = pcx, y = pcy + 4,
        scale = 1.2 + 0.3 * math.sin(u * math.pi),
        open = u < 0.85, angle = 0, frame = (u < 0.85) and 1 or 2,
        burst = u < 0.7 and u / 0.7 or nil,
        sendOut = true,
      }
    end
    -- Arc from player hand toward this mon's slot (singles keeps old path).
    if not doubles or side == "player" then
      local bx = (ppx - 28) + u * 28
      local by = ppy - 8 - math.sin(u * math.pi) * 28
      return {
        x = bx, y = by, scale = 1.1 + 0.4 * u, open = false,
        angle = u * math.pi * 2.2, frame = math.floor(u * 6) % 2,
        sendOut = true,
      }
    end
    local handX, handY = (Game3.BATTLER_CX.player or 72) - 28, ppy - 8
    local bx = handX + (pcx - handX) * u
    local by = handY + (pcy - handY) * u - math.sin(u * math.pi) * 28
    return {
      x = bx, y = by, scale = 1.1 + 0.4 * u, open = false,
      angle = u * math.pi * 2.2, frame = math.floor(u * 6) % 2,
      sendOut = true,
    }
  end

  -- Return-ball: open at feet, suck mon in, close (CreatePokeballSprite spirit).
  local function recallBall(side, u)
    local cx, cy
    if side == "enemy" or side == "enemy2" then
      cx, cy = Game3.battlerCenter(side, doubles)
      cy = cy + 8
    else
      cx, cy = Game3.battlerCenter(side, doubles)
      cy = cy + 4
    end
    local open = u < 0.55
    return {
      x = cx, y = cy,
      scale = 1.15 + 0.2 * math.sin(math.min(1, u * 1.4) * math.pi),
      open = open, angle = 0,
      frame = open and 1 or 0,
      burst = (u < 0.45) and (u / 0.45) or nil,
      sendOut = true,
    }
  end

  local function setBall(ball)
    vis.ball = ball
    vis.balls = ball and { ball } or nil
  end

  -- Baseline released visibility for switch cinema partners.
  local function applyReleasedBaseline()
    vis.enemyHide = not c.enemyReleased
    vis.enemy2Hide = not c.enemy2Released
    vis.playerHide = not c.playerReleased
    vis.player2Hide = not c.player2Released
  end

  if phase == "trainer_slide" then
    local u = uOf(Game3.SEND_SLIDE)
    vis.showEnemyTrainer = true
    vis.enemyTrainerX = (1 - u) * 100
    vis.enemyTrainerA = 1
    vis.showPlayerTrainer = true
    vis.playerTrainerX = (1 - u) * 80
    vis.playerTrainerA = 1
    vis.enemyHide = true
    vis.enemy2Hide = true
    vis.playerHide = true
    vis.player2Hide = true
    vis.hideBoxes = true
  elseif phase == "wild_slide" then
    local u = uOf(Game3.SEND_SLIDE)
    vis.enemyHide = false
    vis.enemy2Hide = false
    vis.enemySlide = (1 - u) * 90
    vis.playerHide = true
    vis.player2Hide = true
    vis.showPlayerTrainer = true
    vis.playerTrainerX = (1 - u) * 80
    vis.playerTrainerA = 1
    vis.hideBoxes = true
  elseif phase == "hold" then
    if c.mode == "trainer" and not c.enemyReleased then
      vis.showEnemyTrainer = not c.trainerGone
      vis.showPlayerTrainer = not c.playerReleased
      vis.enemyHide = true
      vis.enemy2Hide = true
      vis.playerHide = true
      vis.player2Hide = true
      vis.hideBoxes = true
    elseif c.mode == "wild" and not c.playerReleased then
      vis.enemyHide = false
      vis.enemy2Hide = false
      vis.playerHide = true
      vis.player2Hide = true
      vis.showPlayerTrainer = true
      vis.hideBoxes = false
      vis.hidePlayerBox = true
    elseif c.mode == "foe_switch" then
      applyReleasedBaseline()
      vis.hideBoxes = not c.enemyReleased
    else
      applyReleasedBaseline()
      vis.hideBoxes = not (c.enemyReleased and c.playerReleased)
    end
  elseif phase == "enemy_recall" or phase == "enemy2_recall"
      or phase == "player_recall" or phase == "player2_recall" then
    local side = phase:gsub("_recall", "")
    local u = uOf(Game3.SEND_RECALL)
    applyReleasedBaseline()
    -- Show outgoing (stashed) sprite shrinking; hide incoming until throw/open.
    vis.recallSide = side
    vis.recallSpecies = c.recallSpecies
    vis.recallShiny = c.recallShiny and true or false
    local sc = math.max(0.08, 1 - 0.92 * u)
    local al = math.max(0.05, 1 - 0.85 * u)
    if side == "enemy" then
      vis.enemyHide = false
      vis.enemyScale = sc
      vis.enemyAlpha = al
    elseif side == "enemy2" then
      vis.enemy2Hide = false
      vis.enemy2Scale = sc
      vis.enemy2Alpha = al
    elseif side == "player" then
      vis.playerHide = false
      vis.playerScale = sc
      vis.playerAlpha = al
    else
      vis.player2Hide = false
      vis.player2Scale = sc
      vis.player2Alpha = al
    end
    vis.hideBoxes = true
    setBall(recallBall(side, u))
  elseif phase == "enemy_throw" then
    local u = uOf(Game3.SEND_THROW)
    vis.showEnemyTrainer = not c.trainerGone
    if vis.showEnemyTrainer then
      -- Slide trainer off sooner so the ball is not lost on their sprite.
      vis.enemyTrainerX = u * 140
      vis.enemyTrainerA = math.max(0, 1 - u * 1.25)
    end
    if c.mode == "trainer" then
      vis.showPlayerTrainer = true
    end
    if switchMode then
      applyReleasedBaseline()
      vis.enemyHide = true
    else
      vis.enemyHide = true
      vis.enemy2Hide = true
      vis.playerHide = not c.playerReleased
      vis.player2Hide = not c.player2Released
    end
    vis.hideBoxes = true
    setBall(foeBall("enemy", u, false))
  elseif phase == "enemy_open" then
    local u = uOf(Game3.SEND_OPEN)
    if switchMode then
      applyReleasedBaseline()
    end
    vis.enemyHide = false
    vis.enemyScale = 0.12 + 0.88 * u
    vis.enemyAlpha = math.min(1, 0.35 + u)
    -- Partner still hidden until its own throw/open.
    if not switchMode then
      vis.enemy2Hide = self:introHasEnemy2() and not c.enemy2Released
      vis.playerHide = not c.playerReleased
      vis.player2Hide = not c.player2Released
    end
    if c.mode == "trainer" and not c.playerReleased then
      vis.showPlayerTrainer = true
    end
    vis.hideBoxes = u < 0.85
    setBall(foeBall("enemy", u, true))
  elseif phase == "enemy2_throw" then
    local u = uOf(Game3.SEND_THROW)
    if switchMode then
      applyReleasedBaseline()
      vis.enemy2Hide = true
    else
      vis.enemyHide = not c.enemyReleased
      vis.enemy2Hide = true
      vis.playerHide = not c.playerReleased
      vis.player2Hide = not c.player2Released
    end
    if c.mode == "trainer" and not c.playerReleased then
      vis.showPlayerTrainer = true
    end
    vis.hideBoxes = not c.enemyReleased
    setBall(foeBall("enemy2", u, false))
  elseif phase == "enemy2_open" then
    local u = uOf(Game3.SEND_OPEN)
    if switchMode then
      applyReleasedBaseline()
    else
      vis.enemyHide = not c.enemyReleased
      vis.playerHide = not c.playerReleased
      vis.player2Hide = not c.player2Released
    end
    vis.enemy2Hide = false
    vis.enemy2Scale = 0.12 + 0.88 * u
    vis.enemy2Alpha = math.min(1, 0.35 + u)
    if c.mode == "trainer" and not c.playerReleased then
      vis.showPlayerTrainer = true
    end
    vis.hideBoxes = u < 0.85 and not c.enemyReleased
    if c.enemyReleased and u >= 0.5 then vis.hideBoxes = false end
    setBall(foeBall("enemy2", u, true))
  elseif phase == "player_throw" then
    local u = uOf(Game3.SEND_THROW)
    if switchMode then
      applyReleasedBaseline()
      vis.playerHide = true
      vis.showPlayerTrainer = false
    else
      vis.enemyHide = not c.enemyReleased
      vis.enemy2Hide = not c.enemy2Released
      vis.playerHide = true
      vis.player2Hide = true
      vis.showPlayerTrainer = true
      vis.playerTrainerX = u * 100
      vis.playerTrainerA = 1 - u * 0.9
    end
    vis.hideBoxes = not c.enemyReleased
    vis.hidePlayerBox = true
    setBall(playerBall("player", u, false))
  elseif phase == "player_open" then
    local u = uOf(Game3.SEND_OPEN)
    if switchMode then
      applyReleasedBaseline()
    else
      vis.enemyHide = not c.enemyReleased
      vis.enemy2Hide = not c.enemy2Released
      vis.player2Hide = self:introHasPlayer2() and not c.player2Released
    end
    vis.playerHide = false
    vis.playerScale = 0.12 + 0.88 * u
    vis.playerAlpha = math.min(1, 0.35 + u)
    vis.hideBoxes = u < 0.85 and not c.enemyReleased
    if c.enemyReleased and u >= 0.5 then vis.hideBoxes = false end
    if not c.enemyReleased then vis.hideBoxes = true end
    setBall(playerBall("player", u, true))
  elseif phase == "player2_throw" then
    local u = uOf(Game3.SEND_THROW)
    if switchMode then
      applyReleasedBaseline()
      vis.player2Hide = true
    else
      vis.enemyHide = not c.enemyReleased
      vis.enemy2Hide = not c.enemy2Released
      vis.playerHide = not c.playerReleased
      vis.player2Hide = true
    end
    vis.hideBoxes = not c.enemyReleased
    vis.hidePlayerBox = true
    setBall(playerBall("player2", u, false))
  elseif phase == "player2_open" then
    local u = uOf(Game3.SEND_OPEN)
    if switchMode then
      applyReleasedBaseline()
    else
      vis.enemyHide = not c.enemyReleased
      vis.enemy2Hide = not c.enemy2Released
      vis.playerHide = not c.playerReleased
    end
    vis.player2Hide = false
    vis.player2Scale = 0.12 + 0.88 * u
    vis.player2Alpha = math.min(1, 0.35 + u)
    vis.hideBoxes = false
    vis.hidePlayerBox = u < 0.5
    setBall(playerBall("player2", u, true))
  elseif phase == "done" then
    applyReleasedBaseline()
  end
  -- Mid-battle foe switch: keep player side visible / no trainers.
  if c.mode == "foe_switch" then
    if not (phase == "player_throw" or phase == "player_open"
        or phase == "player2_throw" or phase == "player2_open"
        or phase == "player_recall" or phase == "player2_recall") then
      vis.playerHide = false
      vis.player2Hide = not (b.doubles and b.player2) and true or false
      if b.doubles and b.player2 then vis.player2Hide = false end
      vis.playerScale = 1
      vis.player2Scale = 1
      vis.playerAlpha = 1
      vis.player2Alpha = 1
    end
    vis.showPlayerTrainer = false
    vis.showEnemyTrainer = false
  end
  if c.mode == "player_switch" then
    -- Foes stay on-field; no trainers during mid-battle player switch.
    vis.enemyHide = false
    vis.enemy2Hide = not (b.doubles and b.enemy2)
    vis.showEnemyTrainer = false
    vis.showPlayerTrainer = false
    -- Keep the non-switching partner visible at full size.
    if phase == "player_throw" or phase == "player_open" or phase == "player_recall" then
      if b.doubles and b.player2 and c.player2Released then
        vis.player2Hide = false
        vis.player2Scale = 1
        vis.player2Alpha = 1
      end
    elseif phase == "player2_throw" or phase == "player2_open" or phase == "player2_recall" then
      if c.playerReleased then
        vis.playerHide = false
        vis.playerScale = 1
        vis.playerAlpha = 1
      end
    end
  end
  return vis
end


-- Arm typed battle FX for the next drawBattle pass. battleScene OFF skips.

function Game3:armMoveAnim(attacker, defender, move, kind)
  local b = self.battle
  if not b then return end
  local opt = self.options
  if opt and opt.battleScene == false then return end
  local moveType = self:attackType(attacker, move)
  local physical = Game3.isPhysical(moveType)
  local onEnemy = self:isPlayerBattler(attacker)
  local dur = (kind == "status") and Game3.MOVE_ANIM_STATUS or Game3.MOVE_ANIM_DAMAGE
  if kind ~= "status" then
    kind = physical and "physical" or "special"
  end
  b.moveAnim = {
    t = 0,
    dur = dur,
    type = moveType,
    kind = kind,
    onEnemy = onEnemy and true or false,
    physical = physical and true or false,
  }
  b.animT = dur
end

function Game3:beginSurfMountCinema()
  self.owCinema = {
    kind = "surf_mount",
    t = 0,
    dur = Game3.SURF_MOUNT_DUR,
  }
end

function Game3:beginFlyInCinema()
  self.owCinema = {
    kind = "fly_in",
    t = 0,
    dur = Game3.FLY_IN_DUR,
  }
  self:playSe(Game3.SE_M_FLY)
end

function Game3:beginFlyOutCinema()
  self.owCinema = {
    kind = "fly_out",
    t = 0,
    dur = Game3.FLY_IN_DUR * 0.55,
  }
  self:playSe(Game3.SE_M_FLY)
end

function Game3:stepOwCinema(dt)
  local c = self.owCinema
  if not c then return end
  c.t = (c.t or 0) + (dt or 0)
  if (c.t or 0) >= (c.dur or 0) then
    self.owCinema = nil
  end
end

function Game3:drawOwCinema()
  local c = self.owCinema
  if not c then return end
  local G = love.graphics
  local t = Game3.TILE
  local vx, vy = self:visualTile()
  local cx = vx * t + t / 2
  local cy = vy * t + t / 2
  local u = (c.t or 0) / math.max(c.dur or 1, 0.01)
  if u < 0 then u = 0 elseif u > 1 then u = 1 end
  if c.kind == "surf_mount" then
    local a = math.min(1, u * 3) * (1 - math.max(0, u - 0.55) * 2.2)
    local r = 4 + 10 * math.min(1, u * 1.4)
    self:drawStandingAt(cx - r - 4, cy - 2, r * 2 + 8, r + 10, function()
      G.setColor(0.35, 0.65, 0.95, a * 0.85)
      if G.circle then
        G.circle("line", cx, cy + 6, r)
        G.circle("line", cx, cy + 8, r * 0.65)
      end
      G.setColor(0.85, 0.95, 1, a)
      G.rectangle("fill", cx - 2, cy + 2, 4, 3)
    end)
  elseif c.kind == "fly_in" or c.kind == "fly_out" then
    -- Bird silhouette arcs in (or out) — rectangles if polygon is absent.
    local rise = (1 - u) * (1 - u)
    if c.kind == "fly_out" then rise = u * u end
    local bx = cx - 40 + 40 * u
    if c.kind == "fly_out" then bx = cx + 40 * u end
    local by = cy - 50 * rise - 8
    local a = math.min(1, u * 4) * (u < 0.85 and 1 or (1 - u) / 0.15)
    if c.kind == "fly_out" then
      a = math.min(1, (1 - u) * 4) * (u > 0.15 and 1 or u / 0.15)
    end
    local scale = 0.7 + 0.5 * (1 - rise)
    self:drawStandingAt(bx - 12, by - 8, 28, 20, function()
      G.setColor(0.15, 0.15, 0.18, a)
      if G.polygon then
        G.polygon("fill",
          bx - 10 * scale, by,
          bx + 12 * scale, by - 2 * scale,
          bx - 2 * scale, by + 6 * scale)
        G.setColor(0.85, 0.85, 0.9, a * 0.9)
        G.polygon("fill",
          bx - 2 * scale, by - 4 * scale,
          bx + 10 * scale, by - 8 * scale,
          bx + 4 * scale, by)
      else
        G.rectangle("fill", bx - 8 * scale, by - 2 * scale, 16 * scale, 6 * scale)
        G.setColor(0.85, 0.85, 0.9, a * 0.9)
        G.rectangle("fill", bx, by - 6 * scale, 10 * scale, 4 * scale)
      end
    end)
  end
end

function Game3:drawSurfBlob()
  if not self.surfing then return end
  local G = love.graphics
  local t = Game3.TILE
  local vx, vy = self:visualTile()
  local cx = vx * t + t / 2
  local cy = vy * t + t - 2
  local bob = math.sin((love.timer and love.timer.getTime() or 0) * 6) * 1.5
  self:drawStandingAt(cx - 10, cy - 4 + bob, 20, 10, function()
    G.setColor(0.25, 0.55, 0.85, 0.9)
    if G.ellipse then
      G.ellipse("fill", cx, cy + bob, 10, 4)
    else
      G.rectangle("fill", cx - 10, cy - 2 + bob, 20, 5)
    end
    G.setColor(0.55, 0.8, 1, 0.55)
    G.rectangle("fill", cx - 6, cy - 3 + bob, 12, 2)
  end)
end

function Game3.chartMul(chart, atkType, defType, identified)
  if type(chart) ~= "table" then return 10 end
  for i = 1, #chart do
    local row = chart[i]
    if row and row[1] == atkType and row[2] == defType then
      -- Rows after TYPE_FORESIGHT (0xFE): Normal/Fighting vs Ghost.
      if identified and defType == Game3.TYPE_GHOST
          and (atkType == 0 or atkType == Game3.TYPE_FIGHTING)
          and (row[3] or 0) == 0 then
        return 10
      end
      return row[3]
    end
  end
  return 10
end

function Game3.typeMul(chart, atkType, type1, type2, identified)
  local m = Game3.chartMul(chart, atkType, type1 or 0, identified)
  if type2 and type2 ~= type1 then
    m = math.floor(m * Game3.chartMul(chart, atkType, type2, identified) / 10)
  end
  return m
end

function Game3:speciesRow(id)
  local byIndex = self.data.pokemon and self.data.pokemon.byIndex
  if type(byIndex) ~= "table" then return nil end
  return byIndex[id]
end

function Game3:speciesName(id)
  local row = self:speciesRow(id)
  local name = row and row.name or ""
  if name == "" or name:match("^[?%-]+$") then
    return Game3.STARTER_NAMES[id] or ("POKeMON %d"):format(id or 0)
  end
  return name
end

function Game3.abilityFor(row, pid)
  local a1 = (row and row.ability1) or 0
  local a2 = (row and row.ability2) or 0
  if a2 ~= 0 and ((pid or 0) % 2 == 1) then return a2 end
  return a1
end

function Game3:setAbility(mon)
  if not mon then return end
  mon.ability = Game3.abilityFor(self:speciesRow(mon.species), mon.pid)
end

function Game3:hasAbility(mon, id)
  return mon and (mon.ability or 0) == id
end

function Game3.isContact(move)
  return ((move and move.flags) or 0) % 2 == Game3.FLAG_CONTACT
end

-- F_AFFECTED_BY_MAGIC_COAT and F_AFFECTED_BY_SNATCH, bits 2 and 3 of the
-- move table's flags byte. They are what decides whether a move can be
-- bounced or stolen -- not its effect id.
function Game3.moveFlag(move, bit)
  local flags = (move and move.flags) or 0
  return math.floor(flags / bit) % 2 == 1
end

function Game3.magicCoatable(move)
  return Game3.moveFlag(move, Game3.FLAG_MAGIC_COAT)
end

function Game3.snatchable(move)
  return Game3.moveFlag(move, Game3.FLAG_SNATCH)
end

