function Game3:rollIvs()
  return {
    hp = self:rand(32) - 1,
    atk = self:rand(32) - 1,
    def = self:rand(32) - 1,
    spe = self:rand(32) - 1,
    spa = self:rand(32) - 1,
    spd = self:rand(32) - 1,
  }
end

function Game3:makeMon(species, level, moveIds, opts)
  level = level or 5
  opts = type(opts) == "table" and opts or nil
  local row = self:speciesRow(species) or {}
  local mon = {
    species = species or Game3.STARTER_SPECIES,
    name = self:speciesName(species),
    level = level,
    type1 = row.type1 or 0,
    type2 = row.type2 or row.type1 or 0,
    catchRate = row.catchRate or 45,
    expYield = row.expYield or 0,
    growth = row.growthRate or Game3.GROWTH_MEDIUM_SLOW,
    exp = Game3.expAtLevel(row.growthRate or Game3.GROWTH_MEDIUM_SLOW, level),
    pid = (self:rand(65536) - 1) + (self:rand(65536) - 1) * 65536,
    ivs = self:rollIvs(),
    stages = { atk = 0, def = 0, spa = 0, spd = 0, spe = 0 },
    moves = self:movesFor(species, level),
    friendship = tonumber(row.friendship) or Game3.BASE_FRIENDSHIP,
  }
  self:setAbility(mon)
  self:recalcStats(mon)
  mon.hp = mon.maxHp
  if type(moveIds) == "table" and #moveIds > 0 then
    mon.moves = {}
    for i = 1, math.min(4, #moveIds) do
      mon.moves[#mon.moves + 1] = self:copyMove(moveIds[i])
    end
  end
  -- Wild / gift: stamp player OT at create (GiveMonToPlayer / CreateMon).
  self:stampPlayerOt(mon)
  -- Debug force-shiny: rewrite pid vs stamped OT (nature preserved).
  -- Trainers pass opts.trainer; makeTrainerMon anti-shiny OT still applies.
  if self.forceShiny and not (opts and opts.trainer) then
    mon.pid = Game3.personalityForcedShiny(mon.otId, mon.pid)
    self:setAbility(mon)
    self:recalcStats(mon)
    mon.hp = mon.maxHp
  end
  return mon
end

function Game3:copyMove(id)
  local spec = self.data.moves and self.data.moves.byId and self.data.moves.byId[id]
  if spec then
    local acc = spec.accuracy
    if acc == nil then acc = 100 end
    return {
      id = spec.id or id,
      name = spec.name or ("MOVE %d"):format(id),
      effect = spec.effect or 0,
      power = spec.power or 0,
      type = spec.type or 0,
      accuracy = acc,
      pp = spec.pp or 20,
      maxPp = spec.pp or 20,
      priority = spec.priority or 0,
      secondary = spec.secondary or 0,
      flags = spec.flags or 0,
      target = spec.target or 0,
      contestCategory = spec.contestCategory,
      contestAppeal = spec.contestAppeal,
    }
  end
  return {
    id = id or 33, name = "TACKLE", effect = 0, power = 35, type = 0,
    accuracy = 95, pp = 35, maxPp = 35, priority = 0, secondary = 0, flags = 0,
    target = 0,
  }
end

function Game3:moveEffect(move)
  if type(move) ~= "table" then return 0 end
  local spec = self.data and self.data.moves and self.data.moves.byId
    and self.data.moves.byId[move.id]
  if spec and spec.effect ~= nil then return spec.effect end
  return tonumber(move.effect) or 0
end

function Game3:movesFor(species, level)
  level = level or 1
  local row = self:speciesRow(species)
  local learn = row and row.learnset or {}
  local ids = {}
  for i = 1, #learn do
    local e = learn[i]
    if e and (e.level or 1) <= level then
      if #ids >= 4 then table.remove(ids, 1) end
      ids[#ids + 1] = e.move
    end
  end
  local moves = {}
  for i = 1, #ids do
    moves[i] = self:copyMove(ids[i])
  end
  if #moves == 0 then moves[1] = self:copyMove(33) end
  return moves
end

function Game3:behaviorAt(map, x, y)
  map = map or self.map
  if not (map and map.grid) then return 0 end
  x = math.floor(tonumber(x) or 0)
  y = math.floor(tonumber(y) or 0)
  local w, h = map.width or 0, map.height or 0
  if x < 0 or y < 0 or x >= w or y >= h then return 0 end
  local i = y * w + x + 1
  if type(map.behavior) == "table" and map.behavior[i] ~= nil then
    return map.behavior[i]
  end
  local mid = Game3.metatileOf(map.grid[i])
  local spec = self.data.tilesets and self.data.tilesets.byId
    and self.data.tilesets.byId[map.tileset]
  local behavior = spec and spec.behavior
  if type(behavior) ~= "table" then return 0 end
  return behavior[mid] or 0
end

-- Metatile behaviors (walk pads, ice, currents) only apply when the actor
-- is on that cell's elevation layer. Mossdeep Gym walkways (elevation 3/4)
-- sit beside floor belts (elevation 0); forced movement must not bleed
-- across layers.
function Game3.isForcedMovementBehavior(behavior)
  local b = tonumber(behavior) or 0
  if b >= Game3.MB_WALK_EAST and b <= Game3.MB_TRICK_HOUSE_PUZZLE_8_FLOOR then
    return true
  end
  if b >= Game3.MB_EASTWARD_CURRENT and b <= Game3.MB_SOUTHWARD_CURRENT then
    return true
  end
  return b == Game3.MB_MUDDY_SLOPE
      or b == Game3.MB_CRACKED_FLOOR
      or b == Game3.MB_WATERFALL
      or b == Game3.MB_ICE
end

function Game3:behaviorAtElevation(map, x, y, elevation)
  map = map or self.map
  local b = self:behaviorAt(map, x, y)
  if not Game3.isForcedMovementBehavior(b) then return b end
  local i = self:gridIndex(map, x, y)
  if not i then return b end
  local tileZ = Game3.elevationOf(map.grid[i])
  elevation = elevation or 0
  if tileZ ~= 0 and tileZ ~= 15 then
    if elevation == 0 or Game3.zMismatch(elevation, tileZ) then
      return 0
    end
  elseif elevation >= 2 then
  -- Raised walkways (2+) must not inherit floor-level belts/currents.
    return 0
  end
  return b
end

function Game3:actorBlocksAt(actor, elevation)
  if not actor then return false end
  local z = actor.currentElevation
  if z == nil then z = actor.elevation end
  if z == nil then z = 0 end
  return not Game3.zMismatch(elevation or 0, z)
end

function Game3:layerTypeAt(map, x, y)
  map = map or self.map
  if not (map and map.grid) then return Game3.LAYER_NORMAL end
  local w, h = map.width or 0, map.height or 0
  if x < 0 or y < 0 or x >= w or y >= h then return Game3.LAYER_NORMAL end
  local mid = Game3.metatileOf(map.grid[y * w + x + 1])
  local spec = self.data.tilesets and self.data.tilesets.byId
    and self.data.tilesets.byId[map.tileset]
  local layerType = spec and spec.layerType
  if type(layerType) ~= "table" then return Game3.LAYER_NORMAL end
  return layerType[mid] or Game3.LAYER_NORMAL
end

function Game3:encountersFor(map)
  map = map or self.map
  local pack = self.data.encounters
  if not (map and pack and pack.byMap) then return nil end
  return pack.byMap[map.id]
end

function Game3:rand(n)
  n = n or 1
  if self.rng then return self.rng(n) end
  if love and love.math and love.math.random then
    return love.math.random(n)
  end
  return math.random(n)
end

-- pokeruby Random(): 16-bit 0..65535.
function Game3:gbaRandom()
  local v = (tonumber(self:rand(65536)) or 1) - 1
  if v < 0 then v = 0 end
  return math.floor(v) % 65536
end

function Game3:hasFishingMons(map)
  local enc = self:encountersFor(map)
  local fish = enc and enc.fish
  return fish ~= nil and type(fish.slots) == "table" and #fish.slots > 0
end

-- arr1[rod] + Random() % arr2[rod]
function Game3.fishMinRounds(rod, randomValue)
  rod = rod or 0
  local span = Game3.FISH_MIN_SPAN[rod] or 1
  return (Game3.FISH_MIN_BASE[rod] or 1) + ((randomValue or 0) % span)
end

-- wild_encounter.c DoWildEncounterTest. Rate is the header encounterRate
-- before *16. Bike, flutes, Cleanse Tag, then lead ability unless
-- ignoreAbility (Rock Smash). Cap MAX_ENCOUNTER_RATE 2880.
function Game3:wildEncounterRate(baseRate, ignoreAbility)
  local rate = (tonumber(baseRate) or 0) * 16
  if self.bike then
    rate = math.floor(rate * 80 / 100)
  end
  local flags = self.flags
  if flags and flags[Game3.FLAG_SYS_ENC_UP_ITEM] == true then
    rate = rate + math.floor(rate / 2)
  elseif flags and flags[Game3.FLAG_SYS_ENC_DOWN_ITEM] == true then
    rate = math.floor(rate / 2)
  end
  local lead = self.party and self.party[1]
  -- HOLD_EFFECT_REPEL. Also matched by id, so this still works before the
  -- item table is loaded (and in fixtures that have none).
  if lead and (self:holdEffectOf(lead) == Game3.HOLD_EFFECT_REPEL
      or (tonumber(lead.item) or 0) == Game3.ITEM_CLEANSE_TAG) then
    rate = math.floor(rate * 2 / 3)
  end
  if not ignoreAbility and lead and not lead.isEgg then
    if self:hasAbility(lead, Game3.ABILITY_STENCH) then
      rate = math.floor(rate / 2)
    end
    if self:hasAbility(lead, Game3.ABILITY_ILLUMINATE) then
      rate = rate * 2
    end
  end
  if rate > Game3.MAX_ENCOUNTER_RATE then
    rate = Game3.MAX_ENCOUNTER_RATE
  end
  return rate
end

function Game3:tryWildEncounter()
  local map = self.map
  if not map then return false end
  local enc = self:encountersFor(map)
  local info, picker
  local b = self:behaviorAt(map, self.playerX, self.playerY)
  if self.surfing and Game3.isSurfable(b) then
    info, picker = enc and enc.water, Game3.chooseWaterRockSlot
  elseif Game3.isLandWildEncounter(b) then
    info, picker = enc and enc.land, Game3.chooseLandSlot
  else
    return false
  end
  if not (info and info.slots and #info.slots > 0) then return false end
  local rate = self:wildEncounterRate(info.rate or 0, false)
  if (self:rand(Game3.MAX_ENCOUNTER_RATE) - 1) >= rate then return false end
  if not self:firstHealthy() then return false end
  -- wild_encounter.c: TryStartRoamerEncounter after the rate roll. A
  -- TRUE that Repel then blocks does not fall through to the slot table.
  if self:tryStartRoamerEncounter() then
    local roamer = self.roamer
    if roamer and not self:repelBlocks(roamer.level) then
      return self:startRoamerBattle()
    end
    return false
  end
  return self:startWildFrom(info, picker(self:rand(100) - 1))
end

function Game3:startWildFrom(info, slotIndex, skipRepel)
  if not (info and info.slots) then return false end
  local slot = info.slots[(slotIndex or 0) + 1] or info.slots[1]
  if not slot or not slot.species then return false end
  local minL, maxL = slot.minLevel or 2, slot.maxLevel or slot.minLevel or 2
  if maxL < minL then maxL = minL end
  local level = minL
  if maxL > minL then level = minL + self:rand(maxL - minL + 1) - 1 end
  if not skipRepel and self:repelBlocks(level) then return false end
  return self:startWildBattle(slot.species, level)
end

function Game3:tryRockSmashEncounter()
  local enc = self:encountersFor(self.map)
  local rock = enc and enc.rock
  if not (rock and rock.slots and #rock.slots > 0) then return false end
  local rate = self:wildEncounterRate(rock.rate or 0, true)
  if (self:rand(Game3.MAX_ENCOUNTER_RATE) - 1) >= rate then return false end
  if not self:firstHealthy() then return false end
  return self:startWildFrom(rock, Game3.chooseWaterRockSlot(self:rand(100) - 1))
end

-- ScrSpecial_RockSmashWildEncounter: area 2, Repel on, ignoreAbility.
-- BattleSetup_StartWildBattle increments stats 7/8 and ScriptContext_Stop.
function Game3:rockSmashWildEncounter()
  if self:tryRockSmashEncounter() then
    self:incrementGameStat(Game3.GAME_STAT_TOTAL_BATTLES)
    self:incrementGameStat(Game3.GAME_STAT_WILD_BATTLES)
    self:beginScriptWait()
    self:setScriptVar(Gen3Script.VAR_RESULT, 1)
    return 1
  end
  self:setScriptVar(Gen3Script.VAR_RESULT, 0)
  return 0
end

-- TryUpdateRusturfTunnelState. Exact g24_4 (mapMatches is permissive on
-- stub ids that are not gN_M). FLAG_HIDE_ROCK_1 wins if both are set.
function Game3:tryUpdateRusturfTunnelState()
  if self.flags and self.flags[Game3.FLAG_RUSTURF_TUNNEL_OPENED] then
    return 0
  end
  local id = self.map and self.map.id
  if id ~= Game3.mapId(Game3.MAP_RUSTURF_TUNNEL_GROUP,
      Game3.MAP_RUSTURF_TUNNEL_NUM) then
    return 0
  end
  if self.flags and self.flags[Game3.FLAG_HIDE_RUSTURF_TUNNEL_ROCK_1] then
    self:setScriptVar(Game3.VAR_RUSTURF_TUNNEL_STATE, 4)
    return 1
  end
  if self.flags and self.flags[Game3.FLAG_HIDE_RUSTURF_TUNNEL_ROCK_2] then
    self:setScriptVar(Game3.VAR_RUSTURF_TUNNEL_STATE, 5)
    return 1
  end
  return 0
end

function Game3:trySweetScentEncounter()
  local map = self.map
  if not map then return false end
  local enc = self:encountersFor(map)
  local b = self:behaviorAt(map, self.playerX, self.playerY)
  local info, picker
  if Game3.isLandWildEncounter(b) then
    info, picker = enc and enc.land, Game3.chooseLandSlot
  elseif Game3.isSurfable(b) and not Game3.isWaterfall(b) then
    info, picker = enc and enc.water, Game3.chooseWaterRockSlot
  else
    return false
  end
  if not (info and info.slots and #info.slots > 0) then return false end
  if not self:firstHealthy() then return false end
  -- SweetScentWildEncounter: TryStartRoamerEncounter with no Repel check.
  if self:tryStartRoamerEncounter() then
    return self:startRoamerBattle()
  end
  return self:startWildFrom(info, picker(self:rand(100) - 1), true)
end

-- roamer.c. Location RAM is EWRAM on hardware; CONTINUE keeps mapNum so
-- Latios does not snap to Petalburg (group 0, num 0).
function Game3:clearRoamerData()
  self.roamer = {
    species = 0,
    level = 0,
    active = false,
    ivs = Game3.zeroIvs(),
    personality = 0,
    hp = 0,
    cool = 0,
    beauty = 0,
    cute = 0,
    smart = 0,
    tough = 0,
  }
end

function Game3:clearRoamerLocationData()
  self.roamerLocationHistory = { { 0, 0 }, { 0, 0 }, { 0, 0 } }
  self.roamerLocation = { 0, 0 }
end

function Game3:createInitialRoamerMon()
  local mon = self:makeMon(Game3.ROAMER_SPECIES, Game3.ROAMER_LEVEL)
  self.roamer = {
    species = Game3.ROAMER_SPECIES,
    level = Game3.ROAMER_LEVEL,
    active = true,
    ivs = Game3.copyIvs(mon.ivs),
    personality = mon.pid or 0,
    hp = mon.maxHp or 0,
    cool = mon.cool or 0,
    beauty = mon.beauty or 0,
    cute = mon.cute or 0,
    smart = mon.smart or 0,
    tough = mon.tough or 0,
  }
  local sets = Game3.ROAMER_LOCATIONS
  local loc = self.roamerLocation
  if type(loc) ~= "table" then
    self:clearRoamerLocationData()
    loc = self.roamerLocation
  end
  loc[1] = 0
  loc[2] = sets[(self:gbaRandom() % 20) + 1][1]
end

function Game3:initRoamer()
  self:clearRoamerData()
  self:clearRoamerLocationData()
  self:createInitialRoamerMon()
end

function Game3:updateLocationHistoryForRoamer()
  local hist = self.roamerLocationHistory
  if type(hist) ~= "table" then
    self:clearRoamerLocationData()
    hist = self.roamerLocationHistory
  end
  local h2, h1 = hist[2], hist[1]
  hist[3] = { h2[1] or 0, h2[2] or 0 }
  hist[2] = { h1[1] or 0, h1[2] or 0 }
  local g, n = self:currentMapGroupNum()
  hist[1] = { g, n }
end

function Game3:roamerMoveToOtherLocationSet()
  local r = self.roamer
  if not (r and r.active) then return end
  local loc = self.roamerLocation
  if type(loc) ~= "table" then
    self:clearRoamerLocationData()
    loc = self.roamerLocation
  end
  loc[1] = 0
  local sets = Game3.ROAMER_LOCATIONS
  while true do
    local val = sets[(self:gbaRandom() % 20) + 1][1]
    if loc[2] ~= val then
      loc[2] = val
      return
    end
  end
end

function Game3:roamerMove()
  if (self:gbaRandom() % 16) == 0 then
    self:roamerMoveToOtherLocationSet()
    return
  end
  local r = self.roamer
  if not (r and r.active) then return end
  local loc = self.roamerLocation
  local hist = self.roamerLocationHistory
  if type(loc) ~= "table" or type(hist) ~= "table" then return end
  local current = loc[2]
  local sets = Game3.ROAMER_LOCATIONS
  for locSet = 1, 20 do
    local row = sets[locSet]
    if row[1] == current then
      local old = hist[3]
      while true do
        local mapNum = row[(self:gbaRandom() % 5) + 2]
        local skip = (old[1] or 0) == 0 and (old[2] or 0) == mapNum
        if not skip and mapNum ~= Game3.ROAMER_MAP_NONE then
          loc[2] = mapNum
          return
        end
      end
    end
  end
end

function Game3:isRoamerAt(mapGroup, mapNum)
  local r = self.roamer
  local loc = self.roamerLocation
  if not (r and r.active and type(loc) == "table") then return false end
  return loc[1] == (tonumber(mapGroup) or 0)
      and loc[2] == (tonumber(mapNum) or 0)
end

function Game3:tryStartRoamerEncounter()
  local g, n = self:currentMapGroupNum()
  if self:isRoamerAt(g, n) and (self:gbaRandom() % 4) == 0 then
    return true
  end
  return false
end

function Game3:startRoamerBattle()
  local r = self.roamer
  if not (r and r.active) then return false end
  if not self:startWildBattle(r.species, r.level) then return false end
  local enemy = self.battle.enemy
  if r.personality then enemy.pid = r.personality end
  if type(r.ivs) == "table" then
    enemy.ivs = Game3.copyIvs(r.ivs)
    self:recalcStats(enemy)
  end
  local hp = tonumber(r.hp)
  if hp ~= nil then
    enemy.hp = math.max(0, math.min(enemy.maxHp or hp, hp))
  end
  enemy.status = r.status
  enemy.sleepTurns = r.sleepTurns
  enemy.cool = r.cool or 0
  enemy.beauty = r.beauty or 0
  enemy.cute = r.cute or 0
  enemy.smart = r.smart or 0
  enemy.tough = r.tough or 0
  self.battle.roamer = true
  self:incrementGameStat(Game3.GAME_STAT_TOTAL_BATTLES)
  self:incrementGameStat(Game3.GAME_STAT_WILD_BATTLES)
  return true
end

function Game3:updateRoamerHPStatus(mon)
  local r = self.roamer
  if not r then return end
  r.hp = (mon and mon.hp) or 0
  r.status = mon and mon.status
  r.sleepTurns = mon and mon.sleepTurns
  self:roamerMoveToOtherLocationSet()
end

function Game3:setRoamerInactive()
  local r = self.roamer
  if r then r.active = false end
end

function Game3:finishRoamerBattle(outcome)
  if not (self.battle and self.battle.roamer) then return end
  self:updateRoamerHPStatus(self.battle.enemy)
  local o = tonumber(outcome) or 0
  if o == Game3.B_OUTCOME_WON or o == Game3.B_OUTCOME_CAUGHT then
    self:setRoamerInactive()
  end
end

function Game3:snapshotRoamer()
  local r = self.roamer
  if type(r) ~= "table" then return nil end
  local loc = self.roamerLocation or { 0, 0 }
  return {
    species = r.species or 0,
    level = r.level or 0,
    status = r.status,
    sleepTurns = r.sleepTurns,
    active = r.active and true or false,
    ivs = Game3.copyIvs(r.ivs),
    personality = r.personality or 0,
    hp = r.hp or 0,
    cool = r.cool or 0,
    beauty = r.beauty or 0,
    cute = r.cute or 0,
    smart = r.smart or 0,
    tough = r.tough or 0,
    mapGroup = loc[1] or 0,
    mapNum = loc[2] or 0,
  }
end

function Game3:applyRoamerSave(data)
  self:clearRoamerData()
  self:clearRoamerLocationData()
  if type(data) ~= "table" then return end
  local r = self.roamer
  r.species = tonumber(data.species) or 0
  r.level = tonumber(data.level) or 0
  r.status = data.status
  r.sleepTurns = data.sleepTurns
  r.active = data.active and true or false
  if type(data.ivs) == "table" then r.ivs = Game3.copyIvs(data.ivs) end
  r.personality = tonumber(data.personality) or 0
  r.hp = tonumber(data.hp) or 0
  r.cool = tonumber(data.cool) or 0
  r.beauty = tonumber(data.beauty) or 0
  r.cute = tonumber(data.cute) or 0
  r.smart = tonumber(data.smart) or 0
  r.tough = tonumber(data.tough) or 0
  self.roamerLocation[1] = tonumber(data.mapGroup) or 0
  self.roamerLocation[2] = tonumber(data.mapNum) or 0
end

-- tv.c CheckForBigMovieOrEmergencyNewsOnTV. Must be the matching
-- gender's Littleroot 1F. FLAG_SYS_TV_LATI → 1; FLAG_SYS_TV_HOME → 2;
-- else 1. 0 if the map is not that house.
function Game3:checkForBigMovieOrEmergencyNewsOnTV()
  local group, num = self:currentMapGroupNum()
  if group ~= Game3.MAP_LITTLEROOT_INDOOR_GROUP then return 0 end
  if self:isFemale() then
    if num ~= Game3.MAP_MAYS_HOUSE_1F_NUM then return 0 end
  else
    if num ~= Game3.MAP_BRENDANS_HOUSE_1F_NUM then return 0 end
  end
  if self.flags and self.flags[Game3.FLAG_SYS_TV_LATI] then return 1 end
  if self.flags and self.flags[Game3.FLAG_SYS_TV_HOME] then return 2 end
  return 1
end

function Game3:trainerLabel(npc)
  local class = (npc and npc.trainerClass) or "TRAINER"
  local name = (npc and npc.trainerName) or "TRAINER"
  if class == "" then class = "TRAINER" end
  if name == "" then name = "TRAINER" end
  return class .. " " .. name
end

function Game3:makeTrainerMon(slot)
  if type(slot) ~= "table" then return nil end
  -- opts.trainer skips forceShiny; anti-shiny OT re-roll below still runs.
  local mon = self:makeMon(slot.species, slot.level, slot.moves, { trainer = true })
  if not mon then return nil end
  local iv = tonumber(slot.iv)
  if iv ~= nil then
    local v = math.floor(iv * 31 / 255)
    mon.ivs = { hp = v, atk = v, def = v, spe = v, spa = v, spd = v }
    self:recalcStats(mon)
    mon.hp = mon.maxHp
  end
  -- pokeruby CreateMonWithOT / otIdType=2: random OT, re-roll while shiny
  -- vs that OT. Trainer foes never keep the player's OT from makeMon.
  local pid = mon.pid or 0
  local ot
  for _ = 1, 64 do
    local lo = self:rand(65536) - 1
    local hi = self:rand(65536) - 1
    if lo < 0 then lo = 0 end
    if hi < 0 then hi = 0 end
    ot = hi * 65536 + lo
    if not Game3.isShinyOtIdPersonality(ot, pid) then break end
  end
  mon.otId = ot
  mon.otName = mon.otName or "TRAINER"
  return mon
end

function Game3.aliveMon(mon)
  return mon ~= nil and (mon.hp or 0) > 0
end

-- Living foes still to beat: the active battler(s), roared-out bench,
-- plus unsent party.
function Game3:trainerMonsLeft()
  local b = self.battle
  if not b then return 0 end
  local n = 0
  if Game3.aliveMon(b.enemy) then n = n + 1 end
  if Game3.aliveMon(b.enemy2) then n = n + 1 end
  local bench = b.phazed or {}
  for i = 1, #bench do
    if Game3.aliveMon(bench[i]) then n = n + 1 end
  end
  local party = b.trainerParty or {}
  for i = (b.trainerIndex or 1) + 1, #party do n = n + 1 end
  return n
end

-- ShouldUseItem AI_ITEM_HEAL_HP / FULL_RESTORE.
function Game3:shouldUseHealItem(mon, itemId)
  local amount = self:healAmount(itemId)
  if not amount or not mon then return false end
  local hp, maxHp = mon.hp or 0, mon.maxHp or 1
  if hp == 0 then return false end
  if itemId == Game3.ITEM_FULL_RESTORE then
    return hp < math.floor(maxHp / 4)
  end
  return hp < math.floor(maxHp / 4) or (maxHp - hp) > amount
end

function Game3:takeTrainerHealItem(mon)
  local b = self.battle
  if not (b and b.isTrainer and mon) then return nil end
  local items = b.trainerItems
  if type(items) ~= "table" then return nil end
  local valid = self:trainerMonsLeft()
  local num = b.numItems or 0
  for i = 1, 4 do
    local item = items[i] or 0
    if item ~= 0 then
      local hold = i > 1 and valid > (num - (i - 1)) + 1
      if not hold and self:shouldUseHealItem(mon, item) then
        items[i] = 0
        return item
      end
    end
  end
end

function Game3:applyTrainerItem(mon, itemId)
  local amount = self:healAmount(itemId) or 0
  local heal = amount >= 999 and (mon.maxHp or amount) or amount
  mon.hp = math.min(mon.maxHp or heal, (mon.hp or 0) + heal)
  local label = self:trainerLabel(self.battle and self.battle.npc)
  local itemName = self:itemName(itemId)
  return {
    ("%s used %s!"):format(label, itemName),
    ("%s's %s restored health!"):format(mon.name, itemName),
  }
end


-- ---------------------------------------------------------------------------
-- Trainer mid-battle switching (pokeruby battle_ai_switch_items.c):
-- ShouldSwitch / GetMostSuitableMonToSwitchInto / AI_TrySwitchOrUseItem.
-- Heal items stay in takeTrainerHealItem; switching runs first.
-- ---------------------------------------------------------------------------

Game3.AI_MOVE_RESULT_SUPER_EFFECTIVE = 8
Game3.AI_MOVE_RESULT_NOT_VERY_EFFECTIVE = 4
Game3.AI_MOVE_RESULT_DOESNT_AFFECT = 1

function Game3:aiSwitchEscapeBlocked(mon)
  if not mon then return true end
  if self:isTrapped(mon) then return true end
  if mon.cannotEscape or mon.rooted then return true end
  local code = self:canRunFromBattle(mon)
  return code ~= 0
end

-- Living bench: roared-out phazed mons plus unsent trainerParty slots.
-- Each entry is { source="phazed"|"party", index=n, mon?=battler }.
function Game3:aiSwitchCandidates(active)
  local b = self.battle
  if not (b and b.isTrainer and active) then return {} end
  local reserved = b.aiSwitchReserved or {}
  local out = {}
  local partner = self:allyOf(active)
  local bench = b.phazed or {}
  for i = 1, #bench do
    local mon = bench[i]
    local key = "phazed:" .. tostring(i)
    if Game3.aliveMon(mon) and mon ~= active and mon ~= partner and not mon.isEgg
        and not reserved[key] then
      out[#out + 1] = { source = "phazed", index = i, mon = mon }
    end
  end
  local party = b.trainerParty or {}
  for i = (b.trainerIndex or 1) + 1, #party do
    local slot = party[i]
    local key = "party:" .. tostring(i)
    if type(slot) == "table" and slot.species and not reserved[key] then
      out[#out + 1] = { source = "party", index = i, slot = slot }
    end
  end
  return out
end

function Game3:aiCandidateSpeciesAbility(cand)
  if cand.mon then
    return cand.mon.species, cand.mon.ability or 0, cand.mon
  end
  local slot = cand.slot or {}
  local species = tonumber(slot.species) or slot.species
  if type(species) == "string" then
    -- Trainer party slots normally carry numeric species ids.
    species = tonumber(species) or 0
  end
  local row = self:speciesRow(species)
  local ability = Game3.abilityFor(row, 0)
  local level = tonumber(slot.level) or 1
  -- Rough stats so aiDamageOf's damage fallback can compare candidates
  -- without instantiating a full trainer mon (and burning OT RNG).
  local atk = math.max(1, math.floor((((row and row.atk) or 50) * 2 * level) / 100) + 5)
  local defense = math.max(1, math.floor((((row and row.def) or 50) * 2 * level) / 100) + 5)
  local spa = math.max(1, math.floor((((row and row.spa) or 50) * 2 * level) / 100) + 5)
  local spd = math.max(1, math.floor((((row and row.spd) or 50) * 2 * level) / 100) + 5)
  local spe = math.max(1, math.floor((((row and row.spe) or 50) * 2 * level) / 100) + 5)
  local maxHp = math.max(1, math.floor((((row and row.hp) or 50) * 2 * level) / 100) + level + 10)
  local temp = {
    species = species,
    ability = ability,
    type1 = row and row.type1,
    type2 = row and (row.type2 or row.type1),
    moves = {},
    name = (row and row.name) or "POKeMON",
    level = level,
    maxHp = maxHp,
    hp = maxHp,
    atk = atk, def = defense, spa = spa, spd = spd, spe = spe,
    stages = { atk = 0, def = 0, spa = 0, spd = 0, spe = 0 },
  }
  local moves = slot.moves
  if type(moves) == "table" and #moves > 0 then
    for i = 1, math.min(4, #moves) do
      local id = moves[i]
      if type(id) == "table" then id = id.id or id.move end
      local mv = self:copyMove(id)
      if mv then temp.moves[#temp.moves + 1] = mv end
    end
  else
    -- Same default as makeMon: level-up moves for the slot's level.
    temp.moves = self:movesFor(species, level)
  end
  return species, ability, temp
end

function Game3:aiTypeResultFlags(move, defender)
  if not move or not defender then return 0 end
  -- Fake attacker: attackType only needs the move (and maybe ability).
  local dummy = { ability = 0 }
  local bonus = self:aiDamageBonus(dummy, defender, move)
  local flags = 0
  if bonus == 0 then
    flags = flags + Game3.AI_MOVE_RESULT_DOESNT_AFFECT
  elseif bonus == 10 or bonus == 20 then
    flags = flags + Game3.AI_MOVE_RESULT_NOT_VERY_EFFECTIVE
  elseif bonus >= 80 then
    flags = flags + Game3.AI_MOVE_RESULT_SUPER_EFFECTIVE
  end
  return flags
end

function Game3:aiHasSEMoveAgainst(attacker, defender, noRng)
  if not (attacker and defender) then return false end
  for i = 1, #(attacker.moves or {}) do
    local move = attacker.moves[i]
    if move and (move.id or 0) ~= 0 then
      local flags = self:aiTypeResultFlags(move, defender)
      if flags % (Game3.AI_MOVE_RESULT_SUPER_EFFECTIVE * 2)
          >= Game3.AI_MOVE_RESULT_SUPER_EFFECTIVE then
        if noRng then return true end
        if (self:gbaRandom() % 10) ~= 0 then return true end
      end
    end
  end
  return false
end

function Game3:aiHasSEMoveAgainstOpponents(attacker, noRng)
  local foes = self:livingOf(self:foesOf(attacker))
  for i = 1, #foes do
    if self:aiHasSEMoveAgainst(attacker, foes[i], noRng) then return true end
  end
  return false
end

function Game3:aiAreStatsRaised(mon)
  local st = (mon and mon.stages) or {}
  local buff = 0
  for _, key in ipairs({ "atk", "def", "spa", "spd", "spe", "acc", "eva" }) do
    local v = st[key] or 0
    if v > 0 then buff = buff + v end
  end
  return buff > 3
end

function Game3:aiSetSwitchChoice(active, cand)
  local b = self.battle
  if not b then return end
  b.aiSwitchChoice = b.aiSwitchChoice or {}
  local key = (active == b.enemy2) and "enemy2" or "enemy"
  b.aiSwitchChoice[key] = cand
end

function Game3:aiGetSwitchChoice(active)
  local b = self.battle
  if not b or not b.aiSwitchChoice then return nil end
  local key = (active == b.enemy2) and "enemy2" or "enemy"
  return b.aiSwitchChoice[key]
end

function Game3:aiShouldSwitchIfPerishSong(active)
  -- perishSongTimer == 0: next residual faints the mon.
  if active and active.perishSong == 0 then
    self:aiSetSwitchChoice(active, nil) -- pick later via GetMostSuitable
    return true
  end
  return false
end

function Game3:aiShouldSwitchIfWonderGuard(active)
  local b = self.battle
  if not b or b.doubles then return false end
  local foe = b.player
  if not (Game3.aliveMon(foe) and self:hasAbility(foe, Game3.ABILITY_WONDER_GUARD)) then
    return false
  end
  if self:aiHasSEMoveAgainst(active, foe, true) then return false end
  local cands = self:aiSwitchCandidates(active)
  for i = 1, #cands do
    local _, _, mon = self:aiCandidateSpeciesAbility(cands[i])
    for j = 1, #(mon.moves or {}) do
      local move = mon.moves[j]
      if move and self:aiTypeResultFlags(move, foe)
          % (Game3.AI_MOVE_RESULT_SUPER_EFFECTIVE * 2)
          >= Game3.AI_MOVE_RESULT_SUPER_EFFECTIVE
          and (self:gbaRandom() % 3) < 2 then
        self:aiSetSwitchChoice(active, cands[i])
        return true
      end
    end
  end
  return false
end

function Game3:aiFindMonThatAbsorbs(active)
  if self:aiHasSEMoveAgainstOpponents(active, true)
      and (self:gbaRandom() % 3) ~= 0 then
    return false
  end
  local landed = active and active.lastLandedMove
  if not landed or (landed.power or 0) == 0 then return false end
  local moveType = self:attackType({ ability = 0 }, landed)
  local absorb
  if moveType == Game3.TYPE_FIRE then
    absorb = Game3.ABILITY_FLASH_FIRE
  elseif moveType == Game3.TYPE_WATER then
    absorb = Game3.ABILITY_WATER_ABSORB
  elseif moveType == Game3.TYPE_ELECTRIC then
    absorb = Game3.ABILITY_VOLT_ABSORB
  else
    return false
  end
  if self:hasAbility(active, absorb) then return false end
  local cands = self:aiSwitchCandidates(active)
  for i = 1, #cands do
    local _, ability = self:aiCandidateSpeciesAbility(cands[i])
    if ability == absorb and (self:gbaRandom() % 2) == 1 then
      self:aiSetSwitchChoice(active, cands[i])
      return true
    end
  end
  return false
end

function Game3:aiShouldSwitchIfNaturalCure(active)
  if not active or active.status ~= Game3.STATUS_SLP then return false end
  if not self:hasAbility(active, Game3.ABILITY_NATURAL_CURE) then return false end
  if (active.hp or 0) < math.floor((active.maxHp or 1) / 2) then return false end
  local landed = active.lastLandedMove
  if (not landed or (landed.power or 0) == 0) and (self:gbaRandom() % 2) == 1 then
    self:aiSetSwitchChoice(active, nil)
    return true
  end
  if self:aiFindMonWithFlagsAndSE(active, Game3.AI_MOVE_RESULT_DOESNT_AFFECT, 1) then
    return true
  end
  if self:aiFindMonWithFlagsAndSE(active, Game3.AI_MOVE_RESULT_NOT_VERY_EFFECTIVE, 1) then
    return true
  end
  if (self:gbaRandom() % 2) == 1 then
    self:aiSetSwitchChoice(active, nil)
    return true
  end
  return false
end

function Game3:aiFindMonWithFlagsAndSE(active, wantFlags, moduloPercent)
  local landed = active and active.lastLandedMove
  local hitter = active and active.lastHitBy
  if not landed or (landed.power or 0) == 0 or not Game3.aliveMon(hitter) then
    return false
  end
  local cands = self:aiSwitchCandidates(active)
  for i = 1, #cands do
    local _, _, mon = self:aiCandidateSpeciesAbility(cands[i])
    local flags = self:aiTypeResultFlags(landed, mon)
    if flags % (wantFlags * 2) >= wantFlags then
      for j = 1, #(mon.moves or {}) do
        local move = mon.moves[j]
        if move and self:aiTypeResultFlags(move, hitter)
            % (Game3.AI_MOVE_RESULT_SUPER_EFFECTIVE * 2)
            >= Game3.AI_MOVE_RESULT_SUPER_EFFECTIVE
            and (self:gbaRandom() % moduloPercent) == 0 then
          self:aiSetSwitchChoice(active, cands[i])
          return true
        end
      end
    end
  end
  return false
end

-- ShouldSwitch (battle_ai_switch_items.c).
function Game3:aiShouldSwitch(active)
  local b = self.battle
  if not (b and b.isTrainer and Game3.aliveMon(active)) then return false end
  if self:aiSwitchEscapeBlocked(active) then return false end
  local cands = self:aiSwitchCandidates(active)
  if #cands < 1 then return false end
  if self:aiShouldSwitchIfPerishSong(active) then return true end
  if self:aiShouldSwitchIfWonderGuard(active) then return true end
  if self:aiFindMonThatAbsorbs(active) then return true end
  if self:aiShouldSwitchIfNaturalCure(active) then return true end
  if self:aiHasSEMoveAgainstOpponents(active, false) then return false end
  if self:aiAreStatsRaised(active) then return false end
  if self:aiFindMonWithFlagsAndSE(active, Game3.AI_MOVE_RESULT_DOESNT_AFFECT, 2) then
    return true
  end
  if self:aiFindMonWithFlagsAndSE(active, Game3.AI_MOVE_RESULT_NOT_VERY_EFFECTIVE, 3) then
    return true
  end
  return false
end

-- GetMostSuitableMonToSwitchInto: best typing vs a random opposing side mon,
-- preferring a SE move; else highest projected damage.
function Game3:aiMostSuitableMon(active)
  local b = self.battle
  local cands = self:aiSwitchCandidates(active)
  if #cands < 1 then return nil end
  local foes = self:livingOf(self:foesOf(active))
  if #foes < 1 then return cands[1] end
  local opposing = foes[1]
  if b and b.doubles and #foes > 1 then
    opposing = foes[(self:gbaRandom() % #foes) + 1]
  end

  local invalid = {}
  while true do
    local bestDmg, best = 0, nil
    local anyValid = false
    for i = 1, #cands do
      if not invalid[i] then
        anyValid = true
        local species, _, mon = self:aiCandidateSpeciesAbility(cands[i])
        if species and species ~= 0 then
          local typeDmg = 10
          local chart = self.data and self.data.moves and self.data.moves.typeChart
          local function modulate(atkType)
            if not atkType then return end
            local t1 = mon.type1 or 0
            typeDmg = math.floor(typeDmg * Game3.chartMul(chart, atkType, t1, false) / 10)
            local t2 = mon.type2
            if t2 and t2 ~= t1 then
              typeDmg = math.floor(typeDmg * Game3.chartMul(chart, atkType, t2, false) / 10)
            end
          end
          -- Offensive typing: opposing mon's types attacking our candidate's types
          -- is inverted in the ROM: it modulates opposing type1/2 as ATACK types
          -- against the candidate's defense types -- i.e. how hard the foe's
          -- STAB hits us. Match that (battle_ai_switch_items.c:583-584).
          modulate(opposing.type1)
          if opposing.type2 and opposing.type2 ~= opposing.type1 then
            modulate(opposing.type2)
          end
          -- Actually wait: ModulateByTypeEffectiveness(opposing.type1, type1, type2)
          -- uses opposing type as attack and candidate types as defense -- so
          -- higher typeDmg means the FOE hits us harder. The ROM picks the max,
          -- which is a known quirk (prefers mons the foe is strong against).
          -- Keep ROM behaviour.
          if bestDmg < typeDmg then
            bestDmg = typeDmg
            best = i
          end
        else
          invalid[i] = true
        end
      end
    end
    if not anyValid or not best then break end
    local _, _, mon = self:aiCandidateSpeciesAbility(cands[best])
    local hasSE = false
    for j = 1, #(mon.moves or {}) do
      local move = mon.moves[j]
      if move and self:aiTypeResultFlags(move, opposing)
          % (Game3.AI_MOVE_RESULT_SUPER_EFFECTIVE * 2)
          >= Game3.AI_MOVE_RESULT_SUPER_EFFECTIVE then
        hasSE = true
        break
      end
    end
    if hasSE then return cands[best] end
    invalid[best] = true
  end

  -- Damage fallback.
  local bestDmg, bestCand = 0, nil
  for i = 1, #cands do
    local _, _, mon = self:aiCandidateSpeciesAbility(cands[i])
    for j = 1, #(mon.moves or {}) do
      local move = mon.moves[j]
      if move and (move.power or 0) > 1 then
        local dmg = self:aiDamageOf(mon, opposing, move)
        if bestDmg < dmg then
          bestDmg = dmg
          bestCand = cands[i]
        end
      end
    end
  end
  return bestCand or cands[1]
end

