-- Perform a voluntary AI switch. Returns message lines.
function Game3:aiPerformSwitch(active, cand)
  local b = self.battle
  local texts = {}
  if not (b and active and cand) then return texts end
  if not Game3.aliveMon(active) then return texts end
  if self:slotOfBattler(active) == nil then return texts end
  local slot = self:slotOfBattler(active) or "enemy"
  local label = self:trainerLabel(b.npc)
  local outgoing = active
  local incoming
  if cand.source == "phazed" then
    local bench = b.phazed or {}
    local idx = cand.index
    if cand.mon then
      idx = nil
      for i = 1, #bench do
        if bench[i] == cand.mon then idx = i break end
      end
    end
    if not idx then return texts end
    incoming = table.remove(bench, idx)
    b.phazed = bench
    incoming = self:prepBattler(incoming)
  elseif cand.source == "party" then
    -- Skip party slots already sent past trainerIndex unless this exact index
    -- is still the next unsent one or still beyond current index.
    local party = b.trainerParty or {}
    local idx = cand.index
    if idx <= (b.trainerIndex or 1) then return texts end
    incoming = self:prepBattler(self:makeTrainerMon(cand.slot or party[idx]))
    -- Advance trainerIndex past this slot; leave gaps for later sequential fills.
    if idx == (b.trainerIndex or 1) + 1 then
      b.trainerIndex = idx
    else
      -- Mark by bumping to at least idx so fillTrainerSlots won't remake it;
      -- unsent holes between are skipped by walking trainerIndex only forward
      -- in fillTrainerSlots, so stash the mon onto phazed? Simpler: set index.
      b.trainerIndex = math.max(b.trainerIndex or 1, idx)
    end
  end
  if not incoming then return texts end
  self:aiClearOutgoingBattler(outgoing)
  local bench = b.phazed or {}
  bench[#bench + 1] = outgoing
  b.phazed = bench
  self:aiResetIncomingBattler(incoming)
  b[slot] = incoming
  self:markSeen(incoming.species)
  self:markSentIn(incoming)
  texts[#texts + 1] = ("%s withdrew %s!"):format(label, outgoing.name or "POKeMON")
  texts[#texts + 1] = ("%s sent out %s!"):format(label, incoming.name or "POKeMON")
  local foe = Game3.aliveMon(b.player) and b.player
    or (Game3.aliveMon(b.player2) and b.player2)
  if foe then
    local extra = self:activateEnter(incoming, foe)
    for i = 1, #(extra or {}) do texts[#texts + 1] = extra[i] end
  end
  if self:battleSceneOn() then
    self:armIntroCinema("foe_switch", {
      slot = slot,
      recall = true,
      recallSpecies = outgoing.species,
      recallShiny = self:isShinyMon(outgoing),
    })
  end
  if b.aiSwitchChoice then
    local key = (slot == "enemy2") and "enemy2" or "enemy"
    b.aiSwitchChoice[key] = nil
  end
  if b.aiSwitchReserved and cand then
    b.aiSwitchReserved[cand.source .. ":" .. tostring(cand.index)] = nil
  end
  return texts
end

-- AI_TrySwitchOrUseItem decision only (no side effects yet except claiming
-- a heal item slot). Returns kind ("switch"|"item"|nil), payload (cand or itemId).
function Game3:aiDecideSwitchOrItem(mon)
  local b = self.battle
  if not (b and b.isTrainer and Game3.aliveMon(mon)) then return nil end
  if self:aiShouldSwitch(mon) then
    local cand = self:aiGetSwitchChoice(mon) or self:aiMostSuitableMon(mon)
    if not cand then
      local cands = self:aiSwitchCandidates(mon)
      cand = cands[1]
    end
    if cand then
      -- Reserve so the doubles partner cannot claim the same bench / party slot
      -- (monToSwitchIntoId in battle_ai_switch_items.c).
      b.aiSwitchReserved = b.aiSwitchReserved or {}
      local key = cand.source .. ":" .. tostring(cand.index)
      b.aiSwitchReserved[key] = true
      return "switch", cand
    end
  end
  local item = self:takeTrainerHealItem(mon)
  if item then return "item", item end
  return nil
end


function Game3:queueEnemyAction(queue)
  local b = self.battle
  if not b or not Game3.aliveMon(b.enemy) then return end
  b.aiSwitchReserved = nil
  if b.safari then
    self:queueSafariEnemy(queue)
    return
  end
  if b.player and (b.player.hp or 0) <= 0 then return end
  -- AI_TrySwitchOrUseItem: switch first, else heal item, else move.
  local kind, payload = self:aiDecideSwitchOrItem(b.enemy)
  if kind == "switch" then
    local texts = self:aiPerformSwitch(b.enemy, payload)
    for i = 1, #(texts or {}) do queue[#queue + 1] = texts[i] end
    return
  end
  if kind == "item" then
    local texts = self:applyTrainerItem(b.enemy, payload)
    for i = 1, #texts do queue[#queue + 1] = texts[i] end
    return
  end
  -- The PURSUIT check on a switch already drew this turn's move; rolling
  -- again here would both burn an extra Random() and pick a different one.
  local move = (b.enemyPickMon == b.enemy and b.enemyPick)
    or self:pickEnemyMove(b.enemy)
  b.enemyPick, b.enemyPickMon = nil, nil
  local texts = self:useMove(b.enemy, b.player, move)
  for i = 1, #texts do queue[#queue + 1] = texts[i] end
end

-- battle_ai BattleAICmd_if_random_100: Random()%100 < safariFleeRate*5.
function Game3:queueSafariEnemy(queue)
  local b = self.battle
  if not b or not Game3.aliveMon(b.enemy) then return end
  local rate = (b.safariFleeRate or 3) * 5
  local name = (b.enemy and b.enemy.name) or "POKeMON"
  if (self:gbaRandom() % 100) < rate then
    queue[#queue + 1] = ("Wild %s fled!"):format(name)
    b.fled = true
    return
  end
  queue[#queue + 1] = ("%s is watching\r\ncarefully!"):format(name)
end

function Game3:safariGoNear()
  local b = self.battle
  if not b or not b.safari then return end
  local n = b.safariGoNearCounter or 0
  local addCatch = Game3.SAFARI_GO_NEAR_CATCH[n + 1] or 1
  local addFlee = Game3.SAFARI_GO_NEAR_FLEE[n + 1] or 4
  b.safariCatchFactor = (b.safariCatchFactor or 0) + addCatch
  if b.safariCatchFactor > Game3.SAFARI_CATCH_FACTOR_MAX then
    b.safariCatchFactor = Game3.SAFARI_CATCH_FACTOR_MAX
  end
  b.safariFleeRate = (b.safariFleeRate or 3) + addFlee
  if b.safariFleeRate > Game3.SAFARI_FLEE_RATE_MAX then
    b.safariFleeRate = Game3.SAFARI_FLEE_RATE_MAX
  end
  local closer = n < 3
  if closer then b.safariGoNearCounter = n + 1 end
  local player = (b.player and b.player.name) or self:playerName()
  local foe = (b.enemy and b.enemy.name) or "POKeMON"
  local line
  if closer then
    line = ("%s crept closer to\r\n%s!"):format(player, foe)
  else
    line = ("%s can't get any closer!"):format(player)
  end
  local queue = { line }
  self:queueEnemyAction(queue)
  b.queue = queue
  b.qi = 1
  b.kind = "text"
  b.text = queue[1]
  b.turns = (b.turns or 0) + 1
end

function Game3:safariThrowPokeblock(flavor)
  local b = self.battle
  if not b or not b.safari then return end
  flavor = math.floor(tonumber(flavor) or 0)
  if flavor < 0 then flavor = 0 elseif flavor > 2 then flavor = 2 end
  if (b.safariPkblThrowCounter or 0) < 3 then
    b.safariPkblThrowCounter = (b.safariPkblThrowCounter or 0) + 1
  end
  local row = Game3.SAFARI_POKEBLOCK_FLEE[(b.safariPkblThrowCounter or 0) + 1]
  local cut = row and row[flavor + 1] or 0
  local flee = b.safariFleeRate or 3
  if flee > 1 then
    if flee < cut then
      b.safariFleeRate = 1
    else
      b.safariFleeRate = flee - cut
    end
  end
  local foe = (b.enemy and b.enemy.name) or "POKeMON"
  local lines = {
    [0] = ("%s is curious about\r\nthe POKeBLOCK!"):format(foe),
    ("%s is enthralled by\r\nthe POKeBLOCK!"):format(foe),
    ("%s completely ignored\r\nthe POKeBLOCK!"):format(foe),
  }
  local queue = { lines[flavor] or lines[0] }
  self:queueEnemyAction(queue)
  b.queue = queue
  b.qi = 1
  b.kind = "text"
  b.text = queue[1]
  b.turns = (b.turns or 0) + 1
end

-- SafariHandleOpenBag → sub_810BADC (case mode 2). Cancel / empty returns
-- to the safari menu; USE runs PokeblockGetGain then HandleAction_ThrowPokeblock.
function Game3:openSafariPokeblockCase()
  local b = self.battle
  if not b or not b.safari then return false end
  local blocks = self:ensurePokeblocks()
  local labels, ids = {}, {}
  for i = 1, Game3.POKEBLOCK_MAX do
    local block = blocks[i]
    if block and (block.color or 0) ~= 0 then
      labels[#labels + 1] = self:pokeblockName(block)
      ids[#ids + 1] = i
    end
  end
  labels[#labels + 1] = "CANCEL"
  b.kind = "pokeblock_case"
  b.pokeblockLabels = labels
  b.pokeblockIds = ids
  b.pokeblockCursor = 0
  return true
end

function Game3:pokeblockGetGain(nature, block)
  nature = math.floor(tonumber(nature) or 0)
  if nature < 0 then nature = 0 elseif nature > 24 then nature = 24 end
  if type(block) ~= "table" then return 0 end
  local flavors = {
    block.spicy or 0, block.dry or 0, block.sweet or 0,
    block.bitter or 0, block.sour or 0,
  }
  local total = 0
  local base = nature * 5
  for i = 1, 5 do
    local cur = flavors[i]
    if cur > 0 then
      total = total + cur * (Game3.POKEBLOCK_FLAVOR_COMPAT[base + i] or 0)
    end
  end
  return total
end

function Game3:clearPokeblock(slot)
  slot = math.floor(tonumber(slot) or 0)
  if slot < 1 or slot > Game3.POKEBLOCK_MAX then return false end
  local blocks = self:ensurePokeblocks()
  blocks[slot] = {
    color = 0, spicy = 0, dry = 0, sweet = 0, bitter = 0, sour = 0, feel = 0,
  }
  return true
end

function Game3:copyPokeblock(block)
  if type(block) ~= "table" then return nil end
  return {
    color = block.color or 0,
    spicy = block.spicy or 0,
    dry = block.dry or 0,
    sweet = block.sweet or 0,
    bitter = block.bitter or 0,
    sour = block.sour or 0,
    feel = block.feel or 0,
  }
end

-- sub_810C788: gain 0 / >0 / <0 → curious / enthralled / ignored, then clear.
function Game3:pickSafariPokeblock(index)
  local b = self.battle
  if not b or not b.safari then return end
  local ids = b.pokeblockIds or {}
  index = math.floor(tonumber(index) or 0)
  if index < 0 or index >= #ids then
    b.kind = "menu"
    return
  end
  local slot = ids[index + 1]
  local block = self.pokeblocks and self.pokeblocks[slot]
  if type(block) ~= "table" or (block.color or 0) == 0 then
    b.kind = "menu"
    return
  end
  local nature = Game3.natureIndex(b.enemy and b.enemy.personality)
  local gain = self:pokeblockGetGain(nature, block)
  self:clearPokeblock(slot)
  local flavor = 0
  if gain > 0 then
    flavor = 1
  elseif gain < 0 then
    flavor = 2
  end
  self:safariThrowPokeblock(flavor)
end

function Game3:prepBattler(mon)
  if not mon then return nil end
  self:recalcStats(mon)
  mon.hp = math.min(mon.hp or mon.maxHp or 0, mon.maxHp or mon.hp or 0)
  mon.stages = { atk = 0, def = 0, spa = 0, spd = 0, spe = 0 }
  mon.focusEnergy = nil
  mon.mudSport = nil
  mon.waterSport = nil
  mon.rage = nil
  mon.leechSeed = nil
  mon.leechSeedSlot = nil
  mon.leechSeedFrom = nil
  mon.foresight = nil
  mon.rooted = nil
  mon.perishSong = nil
  mon.uproarTurns = nil
  mon.uproarMove = nil
  -- status2 belongs to the mon on the field, so a battler that enters is never
  -- born wrapped, recharging, or locked into a rampage.
  mon.wrapped = nil
  mon.wrappedMoveName = nil
  mon.wrappedBy = nil
  mon.recharge = nil
  mon.rampage = nil
  mon.rampageMove = nil
  mon.rolloutTimer = nil
  mon.rolloutMove = nil
  mon.furyCutter = nil
  mon.stockpile = nil
  mon.chargeTurns = nil
  mon.imprisoning = nil
  mon.helpingHand = nil
  mon.magicCoat = nil
  mon.snatch = nil
  mon.tauntTurns = nil
  mon.tormented = nil
  mon.grudge = nil
  mon.cursed = nil
  mon.yawnTurns = nil
  mon.minimized = nil
  mon.substitute = nil
  mon.substituteHp = nil
  mon.disabledMove = nil
  mon.disableTurns = nil
  mon.encoreMove = nil
  mon.encoreSlot = nil
  mon.encoreTurns = nil
  mon.sureHitFrom = nil
  mon.sureHitTurns = nil
  mon.destinyBond = nil
  mon.lastMove = nil
  mon.lastHitByType = nil
  mon.lastLandedMove = nil
  mon.lastHitBy = nil
  mon.nightmare = nil
  mon.cannotEscape = nil
  self:undoTransform(mon)
  if type(mon.moves) ~= "table" or #mon.moves < 1 then
    mon.moves = self:movesFor(mon.species, mon.level)
  end
  return mon
end

function Game3:menuBattler()
  local b = self.battle
  if not b then return nil end
  if b.chooser == "player2" and Game3.aliveMon(b.player2) then
    return b.player2
  end
  if Game3.aliveMon(b.player) then return b.player end
  if Game3.aliveMon(b.player2) then return b.player2 end
  return b.player
end

function Game3:defaultTarget(attacker)
  local b = self.battle
  if not b or not attacker then return nil end
  local a1, a2, f1, f2 = b.player, b.player2, b.enemy, b.enemy2
  local primary, secondary
  if attacker == a1 or attacker == a2 then
    primary = attacker == a2 and f2 or f1
    secondary = attacker == a2 and f1 or f2
  else
    primary = attacker == f2 and a2 or a1
    secondary = attacker == f2 and a1 or a2
  end
  if Game3.aliveMon(primary) then return primary end
  if Game3.aliveMon(secondary) then return secondary end
end

function Game3.isSpreadTarget(target)
  target = target or 0
  return target == Game3.TARGET_BOTH or target == Game3.TARGET_FOES_AND_ALLY
end

function Game3:isPlayerSide(mon)
  local b = self.battle
  return b ~= nil and (mon == b.player or mon == b.player2)
end

function Game3:foesOf(mon)
  local b = self.battle
  if not b then return {} end
  if self:isPlayerSide(mon) then return { b.enemy, b.enemy2 } end
  return { b.player, b.player2 }
end

function Game3:allyOf(mon)
  local b = self.battle
  if not b then return nil end
  if mon == b.player then return b.player2 end
  if mon == b.player2 then return b.player end
  if mon == b.enemy then return b.enemy2 end
  if mon == b.enemy2 then return b.enemy end
end

function Game3:livingOf(list)
  local out = {}
  for i = 1, #(list or {}) do
    if Game3.aliveMon(list[i]) then out[#out + 1] = list[i] end
  end
  return out
end

function Game3:spreadTargets(attacker, move)
  local t = (move and move.target) or 0
  if t == Game3.TARGET_USER then return { attacker } end
  local foes = self:livingOf(self:foesOf(attacker))
  if t == Game3.TARGET_BOTH then return foes end
  if t == Game3.TARGET_FOES_AND_ALLY then
    local ally = self:allyOf(attacker)
    if Game3.aliveMon(ally) then foes[#foes + 1] = ally end
    return foes
  end
  return {}
end

function Game3:selectableTargets(attacker, move)
  local t = (move and move.target) or 0
  if t == Game3.TARGET_USER or Game3.isSpreadTarget(t) then return {} end
  return self:livingOf(self:foesOf(attacker))
end

function Game3:fillTrainerSlots()
  local b = self.battle
  if not b or not b.isTrainer then return {} end
  local party = b.trainerParty or {}
  local sent = {}
  local function takePhazed()
    local bench = b.phazed
    if type(bench) ~= "table" then return nil end
    for i = 1, #bench do
      local mon = bench[i]
      if Game3.aliveMon(mon) and mon ~= b.enemy and mon ~= b.enemy2 then
        table.remove(bench, i)
        return self:prepBattler(mon)
      end
    end
  end
  local function fill(slot)
    if Game3.aliveMon(b[slot]) then return end
    local mon = takePhazed()
    if not mon then
      local nextIdx = (b.trainerIndex or 1) + 1
      if nextIdx > #party then return end
      b.trainerIndex = nextIdx
      local slot = party[nextIdx]
      -- Battle Tower parties are pre-built mons (have maxHp); ordinary
      -- trainers store species/level/moves slots for makeTrainerMon.
      if type(slot) == "table" and slot.maxHp ~= nil then
        mon = self:prepBattler(slot)
      else
        mon = self:prepBattler(self:makeTrainerMon(slot))
      end
    end
    if mon then self:markSeen(mon.species) end
    b[slot] = mon
    sent[#sent + 1] = { mon = mon, slot = slot }
  end
  fill("enemy")
  if b.doubles then fill("enemy2") end
  return sent
end

function Game3:canOfferShift()
  local opt = self.options or {}
  if opt.battleStyle == "set" then return false end
  local b = self.battle
  if not (b and b.isTrainer) then return false end
  local party = b.trainerParty or {}
  local bench = b.phazed or {}
  local benched = false
  for i = 1, #bench do
    if Game3.aliveMon(bench[i]) then benched = true break end
  end
  if (b.trainerIndex or 1) >= #party and not benched then return false end
  return self:firstHealthy(b.player, b.player2) ~= nil
end

function Game3:sendTrainerReplacement()
  local b = self.battle
  local sent = self:fillTrainerSlots()
  if #sent < 1 then return false end
  b.kind = "intro"
  b.switchInDone = false
  b.enterBoth = false
  b.queue = nil
  local slots = {}
  for i = 1, #sent do slots[i] = sent[i].slot end
  if #sent == 1 then
    b.text = ("%s sent out %s!"):format(
      self:trainerLabel(b.npc), sent[1].mon.name)
  else
    b.text = ("%s sent out %s and %s!"):format(
      self:trainerLabel(b.npc), sent[1].mon.name, sent[2].mon.name)
  end
  self:armIntroCinema("foe_switch", { slots = slots, recall = false })
  return true
end

function Game3:emptyPlayerSlot()
  local b = self.battle
  if not b then return nil end
  if not Game3.aliveMon(b.player) then return "player" end
  if b.doubles and not Game3.aliveMon(b.player2) then return "player2" end
end

function Game3:afterFaintContinue()
  local b = self.battle
  local slot = self:emptyPlayerSlot()
  if slot then
    local mon, i = self:firstHealthy(b.player, b.player2)
    if mon then
      b.kind = "party"
      b.mustSwitch = true
      b.switchSlot = slot
      b.partyCursor = (i or 1) - 1
      b.text = nil
      return
    end
    if not Game3.aliveMon(b.player) and not Game3.aliveMon(b.player2) then
      b.kind = "blackout"
      b.text = "You scurried back to safety!"
      b.queue = nil
      return
    end
  end
  b.kind = "menu"
  b.text = nil
  self:tryWallyTutorialAction()
end

function Game3:trainerFlagId(id)
  id = tonumber(id) or 0
  if id < 1 then return nil end
  return Game3.TRAINER_FLAG_START + id
end

function Game3:trainerDefeated(id)
  local fid = self:trainerFlagId(id)
  return fid and self.flags and self.flags[fid] and true or false
end

function Game3:setTrainerDefeated(id)
  local fid = self:trainerFlagId(id)
  if not fid then return end
  self.flags = self.flags or {}
  self.flags[fid] = true
end

function Game3:isNpcDefeated(o)
  if not o then return false end
  if o.defeated then return true end
  -- Defeat is only the 0x500+trainerId bit. ObjectEventTemplate.flagId is a
  -- spawn/hide flag (often shared by every Magma grunt on a map). Treating
  -- it as "defeated" made removeobject / setflag on one grunt skip battles
  -- for all the others while they were still on screen.
  if self:trainerDefeated(o.trainerId) then return true end
  return false
end

function Game3:trainerRow(id)
  id = tonumber(id) or 0
  local pack = self.data and self.data.trainers
  return pack and pack.byId and pack.byId[id]
end

-- trainers_eye.c. Ruby's PokeNav feature is TRAINER'S EYE, not the Match Call
-- of later games: there is no registration step and no phone. The list is
-- derived every time it opens, from two tables and the trainer flags.
--
-- sGymLeaderTrainersEye. Unlike the 56 rematch rows these carry a fixed region
-- map section rather than a map to look one up from, and never a rematch
-- number -- a gym leader is listed once beaten and never asks for a return.
Game3.TRAINERS_EYE_GYM_LEADERS = {
  { 265, 10 },  -- ROXANNE, RUSTBORO CITY
  { 266, 2 },   -- BRAWLY, DEWFORD TOWN
  { 267, 9 },   -- WATTSON, MAUVILLE CITY
  { 268, 3 },   -- FLANNERY, LAVARIDGE TOWN
  { 269, 7 },   -- NORMAN, PETALBURG CITY
  { 270, 11 },  -- WINONA, FORTREE CITY
  { 271, 13 },  -- TATE AND LIZA, MOSSDEEP CITY
  { 272, 14 },  -- WALLACE, SOOTOPOLIS CITY
  { 261, 15 },  -- SIDNEY, EVER GRANDE CITY
  { 262, 15 },  -- PHOEBE
  { 263, 15 },  -- GLACIA
  { 264, 15 },  -- DRAKE
  { 335, 15 },  -- STEVEN
}

-- sub_80F6C20 numbers the gym leaders from 0x38, straight on from the 56
-- rematch rows, so one index covers both halves of the list.
Game3.TRAINERS_EYE_GYM_BASE = 56

-- The list the PokeNav shows: every rematch-table trainer already beaten, then
-- every gym leader and Elite Four member already beaten, in table order.
function Game3:trainersEyeList()
  local out = {}
  local flags = self:ensureTrainerRematches()
  local rows = Game3.TRAINER_EYE_TRAINERS
  for i = 1, #rows do
    local row = rows[i]
    local first = row[1][1]
    if self:trainerDefeated(first) then
      local map = self:lookupMap(row[2], row[3])
      out[#out + 1] = {
        opponentId = first,
        rematchTableIdx = i - 1,
        rematchNo = tonumber(flags[i]) or 0,
        regionMapSectionId = (map and map.regionMapSectionId) or 0,
      }
    end
  end
  for i = 1, #Game3.TRAINERS_EYE_GYM_LEADERS do
    local row = Game3.TRAINERS_EYE_GYM_LEADERS[i]
    if self:trainerDefeated(row[1]) then
      out[#out + 1] = {
        opponentId = row[1],
        rematchTableIdx = Game3.TRAINERS_EYE_GYM_BASE + i - 1,
        rematchNo = 0,
        regionMapSectionId = row[2],
        gymLeader = true,
      }
    end
  end
  return out
end

-- A non-zero rematch number is what puts the marker beside a name.
function Game3.trainersEyeWantsRematch(entry)
  return entry ~= nil and (entry.rematchNo or 0) ~= 0
end

-- LoadTrainerEyesDescriptionLines indexes gTrainerEyeDescriptions by the
-- rematch table index, which is why the gym leaders were numbered on from 56
-- rather than restarting: one table covers both halves of the list.
function Game3:trainersEyeDescription(entry)
  local pack = self.data and self.data.trainers
  local all = pack and pack.eyeDescriptions
  local lines = all and entry and all[entry.rematchTableIdx]
  if type(lines) ~= "table" then return nil end
  return lines
end

-- What each row shows: the trainer's class and name, and where they were.
function Game3:trainersEyeRowText(entry)
  if not entry then return "" end
  local row = self:trainerRow(entry.opponentId)
  local name = (row and row.name) or ("TRAINER %d"):format(entry.opponentId or 0)
  local place = Game3RegionMap.name(entry.regionMapSectionId) or ""
  if place == "" then return name end
  return ("%s  %s"):format(name, place)
end

function Game3:resetTrainerRematches()
  self.trainerRematches = {}
  self.trainerRematchStepCounter = 0
end

function Game3:ensureTrainerRematches()
  if type(self.trainerRematches) ~= "table" then
    self.trainerRematches = {}
  end
  return self.trainerRematches
end

function Game3:snapshotTrainerRematches()
  local src = self:ensureTrainerRematches()
  local out = {}
  for k, v in pairs(src) do
    local n = tonumber(v) or 0
    if n ~= 0 then out[tonumber(k) or k] = n end
  end
  return out
end

function Game3:applyTrainerRematchSave(data)
  self:resetTrainerRematches()
  if type(data) ~= "table" then return end
  self.trainerRematchStepCounter = tonumber(data.trainerRematchStepCounter) or 0
  local src = data.trainerRematches
  if type(src) ~= "table" then return end
  local dst = self:ensureTrainerRematches()
  for k, v in pairs(src) do
    local n = tonumber(v) or 0
    if n ~= 0 then dst[tonumber(k) or k] = n end
  end
end

function Game3:hasAtLeastFiveBadges()
  local n = 0
  for i = 1, 8 do
    if self:hasBadge(i) then
      n = n + 1
      if n >= 5 then return true end
    end
  end
  return false
end

function Game3:trainerEyeIndexByFirst(opponentId)
  opponentId = tonumber(opponentId) or 0
  if opponentId < 1 then return nil end
  local rows = Game3.TRAINER_EYE_TRAINERS
  for i = 1, #rows do
    local ids = rows[i][1]
    if ids and ids[1] == opponentId then return i end
  end
end

function Game3:trainerEyeIndex(opponentId)
  opponentId = tonumber(opponentId) or 0
  if opponentId < 1 then return nil end
  local rows = Game3.TRAINER_EYE_TRAINERS
  for i = 1, #rows do
    local ids = rows[i][1]
    if ids then
      for j = 1, 5 do
        local id = ids[j] or 0
        if id == 0 then break end
        if id == opponentId then return i end
      end
    end
  end
end

function Game3:trainerEyeRematchValue(index)
  if not index or index < 1 or index > Game3.MAX_REMATCH_ENTRIES then
    return 0
  end
  return tonumber(self:ensureTrainerRematches()[index]) or 0
end

function Game3:isFirstTrainerIdReadyForRematch(opponentId)
  return self:trainerEyeRematchValue(self:trainerEyeIndexByFirst(opponentId)) ~= 0
end

function Game3:getTrainerEyeRematchFlag(opponentId)
  return self:trainerEyeRematchValue(self:trainerEyeIndex(opponentId)) ~= 0
end

function Game3:wasSecondRematchWon(opponentId)
  local i = self:trainerEyeIndexByFirst(opponentId)
  if not i then return false end
  local second = Game3.TRAINER_EYE_TRAINERS[i][1][2] or 0
  if second == 0 then return false end
  return self:trainerDefeated(second)
end

function Game3:shouldTryRematchBattle()
  local id = tonumber(self.trainerBattleOpponent) or 0
  if self:isFirstTrainerIdReadyForRematch(id) or self:wasSecondRematchWon(id) then
    return 1
  end
  return 0
end

function Game3:isTrainerReadyForRematch()
  local id = tonumber(self.trainerBattleOpponent) or 0
  if self:getTrainerEyeRematchFlag(id) then return 1 end
  return 0
end

function Game3:getRematchTrainerId(opponentId)
  opponentId = tonumber(opponentId) or tonumber(self.trainerBattleOpponent) or 0
  local i = self:trainerEyeIndexByFirst(opponentId)
  if not i then return 0 end
  local ids = Game3.TRAINER_EYE_TRAINERS[i][1]
  for k = 2, 5 do
    local id = ids[k] or 0
    if id == 0 then return ids[k - 1] or 0 end
    if not self:trainerDefeated(id) then return id end
  end
  return ids[5] or 0
end

function Game3:clearTrainerEyeRematchFlag(opponentId)
  local i = self:trainerEyeIndex(opponentId)
  if i then self:ensureTrainerRematches()[i] = 0 end
end

function Game3:incrementRematchStepCounter()
  if not self:hasAtLeastFiveBadges() then return end
  local n = tonumber(self.trainerRematchStepCounter) or 0
  if n >= Game3.TRAINER_REMATCH_STEPS then
    self.trainerRematchStepCounter = Game3.TRAINER_REMATCH_STEPS
  else
    self.trainerRematchStepCounter = n + 1
  end
end

function Game3:isRematchStepCounterMaxed()
  if not self:hasAtLeastFiveBadges() then return false end
  return (tonumber(self.trainerRematchStepCounter) or 0)
    >= Game3.TRAINER_REMATCH_STEPS
end

function Game3:updateRandomTrainerEyeRematches(mapGroup, mapNum)
  mapGroup = tonumber(mapGroup) or 0
  mapNum = tonumber(mapNum) or 0
  local flags = self:ensureTrainerRematches()
  local rows = Game3.TRAINER_EYE_TRAINERS
  local ret = false
  for i = 1, #rows do
    local row = rows[i]
    if row[2] == mapGroup and row[3] == mapNum then
      if (tonumber(flags[i]) or 0) ~= 0 then
        ret = true
      else
        local ids = row[1]
        if self:trainerDefeated(ids[1])
            and (self:gbaRandom() % 100) <= 30 then
          local rematches = 1
          while rematches < 5 do
            local nxt = ids[rematches + 1] or 0
            if nxt == 0 or not self:trainerDefeated(nxt) then break end
            rematches = rematches + 1
          end
          flags[i] = rematches
          ret = true
        end
      end
    end
  end
  return ret
end

function Game3:tryUpdateRandomTrainerRematches(mapGroup, mapNum)
  if mapGroup == nil then
    mapGroup, mapNum = self:currentMapGroupNum()
  end
  if not self:isRematchStepCounterMaxed() then return false end
  if self:updateRandomTrainerEyeRematches(mapGroup, mapNum) then
    self.trainerRematchStepCounter = 0
    return true
  end
  return false
end

function Game3:startRematchBattleSpecial()
  if self.phase == "battle" then return 0 end
  local kind = tonumber(self.trainerBattleMode)
  if kind ~= Game3.TRAINER_BATTLE_REMATCH_DOUBLE then
    kind = Game3.TRAINER_BATTLE_REMATCH
  end
  if not self:scriptTrainerBattle({
    kind = kind,
    trainerId = self.trainerBattleOpponent,
    intro = self.trainerIntroSpeech,
  }) then
    return 0
  end
  self:beginScriptWait()
  return 1
end

-- battle_setup.c only sets the trainer's own flag (TRAINER_FLAG_START +
-- trainerId). ObjectEventTemplate.flagId is a SPAWN/hide flag and is often
-- SHARED -- every grunt across all four hideout maps carries
-- FLAG_HIDE_GRUNTS_HIDEOUTS -- so setting it here made beating one grunt
-- hide all the others, including the one whose post-battle script is the
-- submarine scene. That left FLAG_EVIL_TEAM_ESCAPED_IN_SUBMARINE unset
-- forever, so Lilycove's Wailmer never cleared and the story could not be
-- finished. Defeated trainers stay on the map in the ROM; a script that
-- wants one gone says removeobject.
function Game3:markTrainerDefeated(npc)
  if not npc then return end
  npc.defeated = true
  if npc.trainerId then self:setTrainerDefeated(npc.trainerId) end
end

-- Same trainerId on two map objects = double-battle pair (Amy & Liv, etc.).
function Game3:isDoubleBattlePartner(a, b)
  if not (a and b) or a == b then return false end
  local id = tonumber(a.trainerId) or 0
  if id < 1 then return false end
  return (tonumber(b.trainerId) or 0) == id
end

function Game3:trainerSeeInfo(npc, map)
  map = map or self.map
  if not (npc and map) then return end
  if npc.defeated or self:isNpcDefeated(npc) then return end
  if (npc.trainerType or 0) < 1 then return end
  local party = npc.party
  if type(party) ~= "table" or #party < 1 then return end
  local range = npc.trainerRange or 0
  if range < 1 then return end
  local px, py = self.playerX, self.playerY
  local dirs
  if npc.trainerType == Game3.TRAINER_TYPE_NORMAL then
    dirs = { npc.facing or "south" }
  else
    -- TRAINER_TYPE_SEE_ALL and TRAINER_TYPE_BURIED (trainer_see.c else).
    dirs = { "north", "south", "west", "east" }
  end
  for i = 1, #dirs do
    local dir = dirs[i]
    local dx, dy = Game3.deltaFromFacing(dir)
    for dist = 1, range do
      local x, y = npc.x + dx * dist, npc.y + dy * dist
      if x == px and y == py then
        local clear = true
        for s = 1, dist - 1 do
          local sx, sy = npc.x + dx * s, npc.y + dy * s
          if not Game3.walkable(map, sx, sy) then
            clear = false
            break
          end
          local blocker = self:npcAt(map, sx, sy)
          -- Double-battle partners share a trainerId and stand adjacent;
          -- do not let the partner tile clip the other's sight cone.
          if blocker and not self:isDoubleBattlePartner(npc, blocker) then
            clear = false
            break
          end
        end
        if clear then return dx, dy, dist, dir end
        break
      end
      if not Game3.walkable(map, x, y) then break end
      local blocker = self:npcAt(map, x, y)
      if blocker and not self:isDoubleBattlePartner(npc, blocker) then break end
    end
  end
end

function Game3:seesPlayer(npc, map)
  return self:trainerSeeInfo(npc, map) ~= nil
end

function Game3:completeTrainerApproach(npc)
  npc = npc or (self.field and self.field.npc)
  self.moveJobs = {}
  self.field = nil
  if not npc then return false end
  if npc.script then
    self._scriptNpc = npc
    self:rememberTalk(npc)
    if self:runNpcScript(npc.script) then
      if self.phase == "battle" then return true end
    end
  end
  if npc.defeated or self:isNpcDefeated(npc) then return false end
  return self:startTrainerBattle(npc)
end

function Game3:stepTrainerApproach(dt)
  local f = self.field
  if not (f and f.kind == "trainer_approach") then return end
  local npc = f.npc
  dt = dt or 0
  if f.stage == "emote" then
    f.wait = (f.wait or 0) - dt
    if npc then self:tickActorCooldown(npc, dt) end
    if (f.wait or 0) > 0 then return end
    local dist = f.dist or 1
    local dir = f.dir or (npc and npc.facing) or "south"
    if npc then npc.facing = dir end
    if npc and npc.localId and dist > 1 then
      local steps = {}
      for _ = 1, dist - 1 do
        steps[#steps + 1] = { kind = "walk", dir = dir }
      end
      self:applyMovement(npc.localId, steps)
      f.stage = "walk"
    else
      f.stage = "trans"
      f.wait = 0.05
    end
  elseif f.stage == "walk" then
    self:stepScriptMove(dt)
    if not self:scriptMoving() then
      f.stage = "trans"
      f.wait = 0.05
    end
  elseif f.stage == "trans" then
    f.wait = (f.wait or 0) - dt
    if (f.wait or 0) <= 0 then
      self:completeTrainerApproach(npc)
    end
  end
end

function Game3:beginTrainerApproach(npc)
  local dx, dy, dist, dir = self:trainerSeeInfo(npc)
  if not dist then return false end
  if npc then npc.facing = dir end
  self:revealHiddenTrainer(npc)
  self.field = {
    kind = "trainer_approach",
    npc = npc,
    stage = "emote",
    wait = Game3.EMOTE_PERIOD,
    dx = dx, dy = dy, dist = dist, dir = dir,
  }
  if npc then self:scriptEmote(npc, "exclaim") end
  if not (npc and npc.localId) then
    return self:completeTrainerApproach(npc)
  end
  return true
end

function Game3:tryTrainerSpot()
  local map = self.map
  local npcs = self:npcsFor(map)
  if not npcs then return false end
  for i = 1, #npcs do
    local npc = npcs[i]
    if npc and self:seesPlayer(npc, map) then
      return self:beginTrainerApproach(npc)
    end
  end
  return false
end

function Game3:startTrainerBattle(npc)
  local party = npc and npc.party
  if type(party) ~= "table" or #party < 1 then return false end
  local player = self:firstHealthy()
  if not player then return false end
  local enemy = self:prepBattler(self:makeTrainerMon(party[1]))
  if not enemy then return false end
  local doubles = npc.doubleBattle and #party >= 2 and true or false
  local enemy2 = doubles and self:prepBattler(self:makeTrainerMon(party[2])) or nil
  if doubles and not enemy2 then doubles = false end
  local player2 = doubles and self:firstHealthy(player) or nil
  self:prepBattler(player)
  if player2 then self:prepBattler(player2) end
  self:markSeen(enemy.species)
  if enemy2 then self:markSeen(enemy2.species) end
  self:clearPoisonStepCounter()
  self.walkCooldown = 0
  self.field = nil
  local packed, nItems = {}, 0
  local src = npc.items
  if type(src) ~= "table" or #src < 1 then
    local tr = self:trainerRow(npc.trainerId)
    src = tr and tr.items
  end
  if type(src) == "table" then
    for i = 1, 4 do
      local id = tonumber(src[i]) or 0
      packed[i] = id
      if id > 0 then nItems = nItems + 1 end
    end
  end
  self.battle = {
    kind = "intro",
    cursor = 0,
    fightCursor = 0,
    partyCursor = 0,
    isTrainer = true,
    doubles = doubles or nil,
    chooser = "player",
    npc = npc,
    trainerParty = party,
    trainerIndex = (doubles and enemy2) and 2 or 1,
    player = player,
    player2 = player2,
    enemy = enemy,
    enemy2 = enemy2,
    text = ("%s would like to battle!"):format(self:trainerLabel(npc)),
    enterBoth = true,
    switchInDone = false,
    turns = 0,
    introT = 0,
    animT = 0,
    trainerItems = packed,
    numItems = nItems,
    eyeRematch = npc.eyeRematch and true or nil,
  }
  self:playBattleMusic("trainer")
  self:resetBattleResults()
  self:applyOverworldBattleWeather()
  self:markSentIn(player)
  self:markSentIn(player2)
  self:applyLeagueFriendship(npc)
  self:launchBattleWithEntrance({ mode = "trainer", npc = npc })
  return true
end

function Game3:isDoubleTrainerKind(kind)
  kind = kind or 0
  return kind == Game3.TRAINER_BATTLE_DOUBLE
    or kind == Game3.TRAINER_BATTLE_CONTINUE_DOUBLE
    or kind == Game3.TRAINER_BATTLE_REMATCH_DOUBLE
    or kind == Game3.TRAINER_BATTLE_CONTINUE_DOUBLE_NO_MUSIC
end

-- pokeruby GetMonsStateToDoubles: one party slot is PLAYER_HAS_ONE_MON,
-- otherwise count non-egg HP>0. Gina & Mia need two usable mons.
function Game3:monsStateToDoubles()
  local party = self.party or {}
  if #party == 1 then return Game3.PLAYER_HAS_ONE_MON end
  local alive = 0
  for i = 1, #party do
    if self:canBattle(party[i]) then alive = alive + 1 end
  end
  if alive > 1 then return Game3.PLAYER_HAS_TWO_USABLE_MONS end
  return Game3.PLAYER_HAS_ONE_USABLE_MON
end

function Game3:scriptTrainerBattle(op)
  op = op or {}
  local kind = tonumber(op.kind) or Game3.TRAINER_BATTLE_SINGLE
  self.trainerBattleMode = kind
  self.trainerIntroSpeech = op.intro
  self.trainerCannotSpeech = op.cannot
  local npc = self._scriptNpc
  local id = tonumber(op.trainerId) or (npc and tonumber(npc.trainerId)) or 0
  self.trainerBattleOpponent = id
  local rematch = kind == Game3.TRAINER_BATTLE_REMATCH
      or kind == Game3.TRAINER_BATTLE_REMATCH_DOUBLE
  -- BattleSetup_ConfigureTrainerBattle sends TRAINER_BATTLE_SINGLE_NO_INTRO_TEXT
  -- to EventScript_DoNoIntroTrainerBattle, which goes straight to
  -- trainerbattlebegin -- no GetTrainerFlag check, unlike the normal and
  -- double paths. The 44 scripts that use it (Elite Four, Steven, Norman,
  -- the rival, Wally, the Winstrates, the story grunts) each gate the
  -- fight on their own story flag instead. Reading the trainer flag here
  -- made a lost Elite Four run unwinnable: EventScript_WhiteOut clears
  -- FLAG_DEFEATED_ELITE_4_*, but nothing clears TRAINER_FLAG_START+SIDNEY,
  -- so talking to Sidney skipped the battle and fell into
  -- EventScript_Defeated -- re-setting the flag and opening the door.
  local noIntro = kind == Game3.TRAINER_BATTLE_NO_INTRO
  if rematch then
    -- EventScript_TryDoRematchBattle: not ready → gotopostbattlescript.
    -- First-fight id is already defeated; do not reuse npc.party.
    if self:isTrainerReadyForRematch() == 0 then return false end
    if self:trainerEyeIndexByFirst(id) then
      id = self:getRematchTrainerId(id)
      self.trainerBattleOpponent = id
    end
    if id < 1 then return false end
  elseif not noIntro and id > 0 and self:trainerDefeated(id) then
    return false
  end
  -- Object-event trainers: a second trainerbattle on that NPC is the
  -- already-defeated talk-again path.  Winstrate reuses Victor as
  -- _scriptNpc for Victoria / Vivi / Vicky; removeobject sets his hide
  -- flag, which must not skip those later trainerIds.
  local npcId = npc and tonumber(npc.trainerId) or 0
  local sameNpc = npc ~= nil and npcId ~= 0 and npcId == id
  if not rematch and not noIntro and sameNpc
      and (npc.defeated or self:isNpcDefeated(npc)) then
    return false
  end
  local battler = (not rematch) and sameNpc and npc or nil
  local party = battler and battler.party
  if rematch or type(party) ~= "table" or #party < 1 then
    local tr = self:trainerRow(id)
    if not (tr and type(tr.party) == "table" and #tr.party > 0) then
      return false
    end
    battler = {
      party = tr.party,
      trainerName = tr.name,
      trainerClass = tr.className,
      doubleBattle = tr.doubleBattle,
      trainerId = id,
      items = tr.items,
      eyeRematch = rematch and true or nil,
    }
    if not rematch and sameNpc then
      npc.party = npc.party or tr.party
      npc.trainerId = npc.trainerId or id
      npc.trainerName = npc.trainerName or tr.name
      npc.trainerClass = npc.trainerClass or tr.className
      npc.items = npc.items or tr.items
      battler = npc
    end
  else
    battler.trainerId = battler.trainerId or id
  end
  if self:isDoubleTrainerKind(op.kind) then
    battler.doubleBattle = true
    if self:monsStateToDoubles() ~= Game3.PLAYER_HAS_TWO_USABLE_MONS then
      return false, op.cannot or Game3.TEXT_NOT_ENOUGH_MONS
    end
  end
  if not self:startTrainerBattle(battler) then return false end
  if (op.kind or 0) == Game3.TRAINER_BATTLE_NO_INTRO then
    -- EventScript_DoNoIntroTrainerBattle: trainerbattlebegin, no intro
    -- speech and no "would like to battle" wait. Flag is honored when the
    -- entrance wipe finishes (or immediately if Battle Scene is OFF).
    self.battle.noIntroCinema = true
    self.battle.kind = "menu"
    self.battle.text = nil
    if self.phase == "battle" then
      self.battle.introT = 1
      if self.battle.introCinema then
        self.battle.introCinema.phase = "done"
        self:introMarkAllReleased(self.battle.introCinema)
      end
    end
  elseif op.intro then
    self.battle.text = self:expandScriptText(op.intro)
  end
  -- pokeruby GetTrainerLoseText / B_TXT_TRAINER1_LOSE_TEXT: the
  -- trainerbattle defeat pointer prints before "player defeated".
  self.battle.defeat = op.defeat and self:expandScriptText(op.defeat) or op.defeat
  return true
end

function Game3:getTrainerBattleMode()
  return tonumber(self.trainerBattleMode) or Game3.TRAINER_BATTLE_SINGLE
end

function Game3:sayTrainerSpeech(text)
  text = self:expandScriptText(text or "")
  if text == "" then return end
  if self._scriptSays then
    self:sayScript(text)
  elseif not self.field then
    self.field = { kind = "talk", text = text }
  end
end

function Game3:showTrainerIntroSpeech()
  self:sayTrainerSpeech(self.trainerIntroSpeech)
end

function Game3:showTrainerNonBattlingSpeech()
  self:sayTrainerSpeech(self.trainerCannotSpeech)
end

function Game3:getTrainerFlag()
  local id = tonumber(self.trainerBattleOpponent) or 0
  if id < 1 then
    local npc = self._scriptNpc
    id = npc and tonumber(npc.trainerId) or 0
  end
  if self:trainerDefeated(id) then return 1 end
  return 0
end

function Game3:hasEnoughMonsForDoubleBattle()
  local n = self:monsStateToDoubles()
  self:setScriptVar(Gen3Script.VAR_RESULT, n)
  return n
end

function Game3:countAlivePartyMonsExceptSelectedOne()
  local skip = self:varGet(0x8004)
  local n = 0
  local party = self.party or {}
  for i = 1, #party do
    if (i - 1) ~= skip and self:canBattle(party[i]) then
      n = n + 1
    end
  end
  return n
end

function Game3:leadMonNicknamed()
  local mon = self:leadMon()
  if not mon then return 0 end
  local nick = mon.name or ""
  local species = self:speciesName(mon.species)
  if nick ~= species then return 1 end
  return 0
end

function Game3:interviewBefore()
  self:setScriptVar(Gen3Script.VAR_RESULT, 0)
  if self:varGet(0x8005) == Game3.TVSHOW_FAN_CLUB_LETTER then
    local mon = self:leadMon()
    if mon then
      self:setStringVar(1, self:speciesName(mon.species))
    end
  end
  return 0
end

function Game3:setContestCategoryStringVarForInterview()
  local cat = 0
  local shows = self.tvShows
  local i = self:varGet(0x8004) + 1
  if type(shows) == "table" and shows[i] then
    cat = tonumber(shows[i].contestCategory) or 0
  end
  local names = Game3.CONTEST_CAT_NAMES
  self:setStringVar(2, names[cat + 1] or "COOL")
end

function Game3:tvIsScriptShowKindAlreadyInQueue()
  return 0
end

function Game3:scriptGetMultiplayerId()
  self:setScriptVar(Gen3Script.VAR_RESULT, 4)
  return 4
end

function Game3:scriptRandom()
  local limit = self:varGet(Gen3Script.VAR_RESULT)
  if limit == 0 then return 0 end
  local n = self:gbaRandom() % limit
  self:setScriptVar(Gen3Script.VAR_RESULT, n)
  return n
end

function Game3:trainerLoseText(npc)
  local b = self.battle
  local t = b and b.defeat
  if type(t) == "string" and t ~= "" then
    return self:expandScriptText(t)
  end
  npc = npc or (b and b.npc)
  local ops = npc and npc.script
  if type(ops) ~= "table" then return nil end
  for i = 1, #ops do
    local op = ops[i]
    if op and op.op == "trainerbattle" then
      t = op.defeat
      if type(t) == "string" and t ~= "" then
        return self:expandScriptText(t)
      end
    end
  end
end

function Game3:openTrainerVictory()
  local b = self.battle
  if not b then return end
  self:recordBattleEnd(Game3.B_OUTCOME_WON)
  b.kind = "won_trainer"
  local pay = Game3.trainerPay(b)
  -- HOLD_EFFECT_DOUBLE_PRIZE (Amulet Coin) doubles the payout when the mon
  -- that led the battle is holding it.
  local lead = (self.party or {})[1]
  if pay > 0 and lead
      and self:holdEffectOf(lead) == Game3.HOLD_EFFECT_DOUBLE_PRIZE then
    pay = pay * 2
  end
  if pay > 0 then
    self.money = (self.money or 0) + pay
  end
  local prize
  if pay > 0 then
    prize = ("You defeated %s! Got $%d!"):format(
      self:trainerLabel(b.npc), pay)
  else
    prize = ("You defeated %s!"):format(self:trainerLabel(b.npc))
  end
  local lose = self:trainerLoseText(b.npc)
  if lose then
    b.text = lose
    b.queue = { lose, prize }
    b.qi = 1
  else
    b.text = prize
    b.queue = nil
  end
end

function Game3:confirmTrainerWin()
  local b = self.battle
  if not b then return end
  local queue = b.queue
  local qi = b.qi or 1
  if type(queue) == "table" and qi < #queue then
    b.qi = qi + 1
    b.text = queue[b.qi]
    b.textPage = 0
    b.printSrc = nil
    return
  end
  self:markTrainerDefeated(b.npc)
  if b.eyeRematch then
    self:clearTrainerEyeRematchFlag(
      (b.npc and b.npc.trainerId) or self.trainerBattleOpponent)
  end
  if b.rivalRoute103 then self:finishRoute103Rival(b.npc) end
  self:finishBattle()
end

function Game3:canBattle(mon)
  return mon and not mon.isEgg and (mon.hp or 0) > 0
end

function Game3:firstHealthy(except, except2)
  local party = self.party or {}
  for i = 1, #party do
    local mon = party[i]
    if mon and mon ~= except and mon ~= except2 and self:canBattle(mon) then
      return mon, i
    end
  end
end

function Game3:healParty()
  local party = self.party or {}
  for i = 1, #party do
    local mon = party[i]
    if mon then
      mon.hp = mon.maxHp or mon.hp
      mon.status = nil
      mon.sleepTurns = nil
      mon.confuseTurns = nil
      mon.flinch = nil
      mon.flashFire = nil
      local moves = mon.moves or {}
      for m = 1, #moves do
        if moves[m] then moves[m].pp = moves[m].maxPp or moves[m].pp end
      end
    end
  end
end

function Game3:itemRow(id)
  local pack = self.data and self.data.items
  return pack and pack.byId and pack.byId[id]
end

function Game3.typeName(id)
  return Game3.TYPE_NAMES[id or 0] or "???"
end

function Game3:itemPocket(id)
  id = tonumber(id) or 0
  local row = self:itemRow(id)
  local pocket = row and tonumber(row.pocket)
  if pocket and pocket >= Game3.POCKET_ITEMS and pocket <= Game3.POCKET_KEY then
    return pocket
  end
  if Game3.isBall(id) then return Game3.POCKET_BALLS end
  if id >= Game3.ITEM_CHERI_BERRY and id <= Game3.ITEM_ENIGMA_BERRY then
    return Game3.POCKET_BERRIES
  end
  if id >= Game3.ITEM_TM01 and id <= Game3.ITEM_HM_DIVE then
    return Game3.POCKET_TMHM
  end
  if id == Game3.ITEM_MACH_BIKE or id == Game3.ITEM_ACRO_BIKE
      or id == Game3.ITEM_SOOT_SACK or id == Game3.ITEM_WAILMER_PAIL
      or id == Game3.ITEM_DEVON_GOODS or id == Game3.ITEM_LETTER
      or id == Game3.ITEM_ITEMFINDER or id == Game3.ITEM_COIN_CASE
      or id == Game3.ITEM_GO_GOGGLES or id == Game3.ITEM_DEVON_SCOPE
      or id == Game3.ITEM_POKEBLOCK_CASE
      or id == Game3.ITEM_RED_ORB
      or Game3.rodKind(id) ~= nil then
    return Game3.POCKET_KEY
  end
  return Game3.POCKET_ITEMS
end

function Game3:bagSlotsIn(pocket)
  pocket = tonumber(pocket) or Game3.POCKET_ITEMS
  local list = {}
  local bag = self.bag or {}
  for i = 1, #bag do
    local slot = bag[i]
    if slot and self:itemPocket(slot.id) == pocket then
      list[#list + 1] = slot
    end
  end
  -- Gen 1 leftover `balls` counter: show a POKe BALL in the BALLS pocket
  -- when the bag itself has none, so trainer-battle throws still work.
  if pocket == Game3.POCKET_BALLS
      and self:itemCount(Game3.ITEM_POKE_BALL) < 1
      and (self.balls or 0) > 0 then
    list[#list + 1] = { id = Game3.ITEM_POKE_BALL, count = self.balls }
  end
  return list
end

function Game3:pocketName(pocket)
  pocket = tonumber(pocket) or Game3.POCKET_ITEMS
  return Game3.POCKET_NAMES[pocket] or "ITEMS"
end

function Game3:firstFilledPocket()
  for p = 1, Game3.POCKET_COUNT do
    if #self:bagSlotsIn(p) > 0 then return p end
  end
  return Game3.POCKET_ITEMS
end

