  [56] = 10, -- OLD_COUPLE
  [57] = 3,  -- SIS_AND_BRO
}

function Game3.trainerClassBaseMoney(className, classId)
  classId = tonumber(classId)
  if classId ~= nil then
    local byId = Game3.TRAINER_MONEY_BY_ID[classId]
    if byId ~= nil then return byId end
  end
  local key = Game3.normalizeTrainerClass(className)
  if key ~= "" then
    local byName = Game3.TRAINER_MONEY[key]
    if byName ~= nil then return byName end
    key = key:gsub("^TRAINERCLASS", "")
    byName = Game3.TRAINER_MONEY[key]
    if byName ~= nil then return byName end
  end
  return Game3.TRAINER_MONEY_DEFAULT
end

-- pokeruby atk5D_getmoneyreward:
--   4 * lastMonLevel * moneyMultiplier * (double?2:1) * gTrainerMoney[class].baseMoney
-- moneyMultiplier (Amulet Coin) is applied by the caller so existing hooks stay.
function Game3.trainerPay(b)
  if not b then return 0 end
  local party = b.trainerParty or {}
  local n = #party
  local level
  if n >= 1 then
    local last = party[n]
    level = last and tonumber(last.level)
  end
  level = level or (b.enemy and tonumber(b.enemy.level)) or 5
  local npc = b.npc
  local className = npc and (npc.trainerClass or npc.className)
  local classId = npc and (npc.class or npc.trainerClassId)
  if classId == nil and type(npc and npc.trainerClass) == "number" then
    classId = npc.trainerClass
  end
  local base = Game3.trainerClassBaseMoney(className, classId)
  local doubles = b.doubles and 2 or 1
  return 4 * level * doubles * base
end

function Game3:markHealPoint()
  if not (self.map and self.map.id) then return false end
  self.lastHeal = {
    mapId = self.map.id,
    x = self.playerX or 0,
    y = self.playerY or 0,
  }
  return true
end

function Game3:startMap()
  local pack = (self.data or {}).maps or {}
  return pack.maps and pack.maps[pack.start]
end

function Game3:warpToHeal()
  self:repairStaleBedroomHeal()
  local dest, x, y
  local heal = self.lastHeal
  if heal and heal.mapId then
    dest = self:lookupMapById(heal.mapId)
    x, y = heal.x or 0, heal.y or 0
    -- Heal locations are towns / cities / the bedroom. special 0 on
    -- Route 101 used to stamp the starter bag tile as lastHeal.
    if dest and dest.mapType == Game3.MAP_TYPE_ROUTE then
      dest = nil
    end
  end
  -- Early-game blackout (no Center yet, or bedroom lookup failed at
  -- setrespawn) must land in the player's room, not the start map
  -- (truck / Route 101).
  if not dest then
    dest = self:playerBedroomMap()
    if dest then
      x, y = Game3.HEAL_BEDROOM_X, Game3.HEAL_BEDROOM_Y
      if not Game3.walkable(dest, x, y) then
        local spawn = dest.spawn or {}
        x, y = spawn.x or x, spawn.y or y
      end
    end
  end
  if not dest then
    dest = self:startMap()
    if dest and Game3.isTruckMap(dest) then
      dest = self:littlerootTownMap() or dest
    end
    local spawn = dest and dest.spawn or {}
    x, y = spawn.x or 0, spawn.y or 0
  end
  if not dest then return false end
  self.surfing = nil
  self.climbing = nil
  self.diving = nil
  self.bike = nil
  self:enterMap(dest, x or 0, y or 0, false)
  return true
end

-- post_battle_event_funcs.c GameClear then hall_of_fame.c / credits.c:
-- heal, FLAG_SYS_GAME_CLEAR, first HoF time, Champion ribbons, record
-- the party, bedroom heal, HoF cinema, credits, then SoftReset to title.
-- beginScriptWait parks the Hall of Fame map script across the cinema.
function Game3:hofPlayTimeStat()
  local sec = math.floor(tonumber(self.playSeconds) or 0)
  if sec < 0 then sec = 0 end
  local h = math.floor(sec / 3600)
  local m = math.floor((sec % 3600) / 60)
  local s = sec % 60
  return h * 65536 + m * 256 + s
end

function Game3:gameClear()
  self:healParty()
  self.flags = self.flags or {}
  if self.flags[Game3.FLAG_SYS_GAME_CLEAR] then
    self.hasHallOfFameRecords = true
  else
    self.hasHallOfFameRecords = false
    self.flags[Game3.FLAG_SYS_GAME_CLEAR] = true
  end
  if self:getGameStat(Game3.GAME_STAT_FIRST_HOF_PLAY_TIME) == 0 then
    self.gameStats = self.gameStats or {}
    self.gameStats[Game3.GAME_STAT_FIRST_HOF_PLAY_TIME] = self:hofPlayTimeStat()
  end
  -- SetSecretBase2Field_9 + sub_80537CC(bedroom): Continue uses warp1/heal, not HoF map.
  self.specialSaveWarp = true
  self:setBedroomHeal()
  local ribbonGet = false
  local party = self.party or {}
  for i = 1, #party do
    local mon = party[i]
    if mon and (mon.species or 0) ~= 0
        and not mon.isEgg and not mon.championRibbon then
      mon.championRibbon = true
      ribbonGet = true
    end
  end
  if ribbonGet then
    self:incrementGameStat(Game3.GAME_STAT_RECEIVED_RIBBONS)
    self.flags[Game3.FLAG_SYS_RIBBON_GET] = true
  end
  self:recordHallOfFameTeam()
  -- hall_of_fame.c Save_WriteData(SAVE_HALL_OF_FAME) also flushes SaveBlock1/2
  -- (specialSaveWarp + warp1 bedroom). Never skip that write because phase is
  -- still "battle" from the champion fight -- SoftReset would lose the home warp.
  do
    local prevPhase = self.phase
    if prevPhase == "battle" or prevPhase == "battle_transition" then
      self.phase = "play"
    end
    self:writeSave()
    if prevPhase == "battle" or prevPhase == "battle_transition" then
      self.phase = prevPhase
    end
  end
  -- GameClear's last line is SetMainCallback2(sub_8141F90): the Hall of Fame
  -- screen, not the overworld. warpToHeal is what happens after it, once the
  -- team has been presented.
  if self:startHallOfFame() then
    -- GameClear's last act is SetMainCallback2(sub_8141F90): it LEAVES the
    -- overworld, and the `waitstate` after `special GameClear` parks the
    -- script until that screen hands control back. Without arming that
    -- wait the script ran straight on through releaseall/end, which tore
    -- the cinema down and returned control inside the HALL OF FAME -- a
    -- room whose only way out is the rest of this script.
    self:beginScriptWait()
    return true
  end
  return self:warpToHeal()
end

-- hall_of_fame.c. GameClear ends with SetMainCallback2(sub_8141F90), which
-- leaves the overworld for the Hall of Fame screen: every party mon slides in
-- from off screen, cries, and is captioned with its dex number, nickname,
-- species and level, held 120 frames each; then the whole team and the
-- trainer together. Only after that does the cart walk you back to your
-- bedroom. gameClear here did all the bookkeeping and then warped straight
-- home, so beating the champion showed nothing whatsoever.
-- sHallOfFame_MonsFullTeamPositions / ...HalfTeamPositions, each row
-- { startX, startY, destX, destY } -- some start off screen and slide in.
Game3.HOF_FULL_TEAM_POS = {
  { 120, 210, 120, 40 }, { 326, 220, 56, 40 }, { -86, 220, 184, 40 },
  { 120, -62, 120, 88 }, { -25, -62, 200, 88 }, { 265, -62, 40, 88 },
}
Game3.HOF_HALF_TEAM_POS = {
  { 120, 214, 120, 64 }, { 281, 214, 56, 64 }, { -41, 214, 184, 64 },
}
Game3.HOF_MON_HOLD_FRAMES = 120
Game3.HOF_SLIDE_FRAMES = 20
Game3.HOF_END_HOLD_FRAMES = 200
Game3.MUS_HALL_OF_FAME = 436
Game3.HOF_PIC = 64

-- >3 mons uses the two-row layout, otherwise the single centred row.
function Game3.hofSlotPos(slot, count)
  local tbl = Game3.HOF_HALF_TEAM_POS
  if (tonumber(count) or 1) > 3 then tbl = Game3.HOF_FULL_TEAM_POS end
  return tbl[tonumber(slot) or 1] or tbl[1]
end

function Game3:startHallOfFame()
  local mons = {}
  local party = self.party or {}
  for i = 1, #party do
    local m = party[i]
    if m and (m.species or 0) ~= 0 and not m.isEgg then
      mons[#mons + 1] = m
    end
  end
  if #mons < 1 then return false end
  self.field = { kind = "hof", mons = mons, slot = 1, stage = "slide", t = 0 }
  self:playSong(Game3.MUS_HALL_OF_FAME, true)
  return true
end

-- Where slot `i` sits this frame: off-screen start, sliding, or parked.
function Game3:hofMonXY(f, i)
  local pos = Game3.hofSlotPos(i, #(f.mons or {}))
  local sx, sy, dx, dy = pos[1], pos[2], pos[3], pos[4]
  if i < (f.slot or 1) then return dx, dy end
  if i > (f.slot or 1) then return nil end
  if f.stage ~= "slide" then return dx, dy end
  local n = Game3.HOF_SLIDE_FRAMES
  local k = (f.t or 0) / n
  if k > 1 then k = 1 end
  return sx + (dx - sx) * k, sy + (dy - sy) * k
end

function Game3:stepHofCinema(frames)
  local f = self.field
  if not f or f.kind ~= "hof" then return end
  f.t = (f.t or 0) + (tonumber(frames) or 1)
  if f.stage == "slide" then
    if f.t >= Game3.HOF_SLIDE_FRAMES then
      f.stage = "hold"
      f.t = 0
      local mon = f.mons[f.slot]
      if mon then self:playMonCry(mon.species) end
    end
  elseif f.stage == "hold" then
    if f.t >= Game3.HOF_MON_HOLD_FRAMES then
      if f.slot < #f.mons then
        f.slot = f.slot + 1
        f.stage = "slide"
        f.t = 0
      else
        f.stage = "team"
        f.t = 0
      end
    end
  elseif f.stage == "team" then
    if f.t >= Game3.HOF_END_HOLD_FRAMES then f.stage = "done" end
  end
end

-- A or B only skips ahead once the whole team is up, the way the cart's
-- confirm does; mid-presentation presses are ignored so a stray tap cannot
-- eat somebody's Hall of Fame.
function Game3:hofCinemaPressed()
  local f = self.field
  if not f or f.kind ~= "hof" then return false end
  if f.stage ~= "team" and f.stage ~= "done" then return false end
  -- hall_of_fame.c: after the team board, SetMainCallback2(CB2_StartCreditsSequence).
  -- credits.c SoftReset at THE END -> boot/title. Re-flush save so bedroom heal +
  -- specialSaveWarp are on disk even if an earlier GameClear write was skipped.
  self:writeSave()
  self:startCreditsSequence()
  return true
end

