  elseif id == Game3.SPECIAL_GET_CUR_SECRET_BASE_REGISTRATION_VALIDITY then
    return self:getCurSecretBaseRegistrationValidity()
  elseif id == Game3.SPECIAL_TOGGLE_CUR_SECRET_BASE_REGISTRY then
    self:toggleCurSecretBaseRegistry()
  elseif id == Game3.SPECIAL_SECRET_BASE_PC_DECORATION then
    self:secretBasePCDecoration()
  elseif id == Game3.SPECIAL_SECRET_BASE_PC_REGISTRY then
    self:secretBasePCRegistry()
  elseif id == Game3.SPECIAL_SET_SECRET_BASE_OWNER_GFX_ID then
    self:setSecretBaseOwnerGfxId()
  elseif id == Game3.SPECIAL_SUB_80BB70C then
    self:setSecretBaseEntranceTypeVar()
  elseif id == Game3.SPECIAL_SUB_80BCE1C then
    self:createSecretBaseEnemyParty()
  elseif id == Game3.SPECIAL_SUB_80BCE90 then
    return self:secretBaseDailyBattleCheck()
  elseif id == Game3.SPECIAL_SUB_80BCE4C then
    self:setSecretBaseBattledOwnerToday()
  elseif id == Game3.SPECIAL_GET_SHIELD_TOY_TV_DECORATION_INFO then
    return self:getShieldToyTVDecorationInfo()
  elseif id == Game3.SPECIAL_DO_SECRET_BASE_PC_TURN_OFF_EFFECT then
