function Game3.statusFromEffect(effect)
  if effect == Game3.EFFECT_TOXIC or effect == Game3.EFFECT_POISON_FANG then
    return Game3.STATUS_TOXIC
  end
  if effect == Game3.EFFECT_POISON_HIT or effect == Game3.EFFECT_POISON then
    return Game3.STATUS_PSN
  end
  if effect == Game3.EFFECT_BURN_HIT or effect == Game3.EFFECT_WILL_O_WISP then
    return Game3.STATUS_BRN
  end
  if effect == Game3.EFFECT_FREEZE_HIT then return Game3.STATUS_FRZ end
  if effect == Game3.EFFECT_PARALYZE_HIT or effect == Game3.EFFECT_PARALYZE then
    return Game3.STATUS_PAR
  end
  if effect == Game3.EFFECT_SLEEP then return Game3.STATUS_SLP end
end

function Game3:statusBlocks(mon, move)
  local texts = {}
  -- atkCanceller runs recharge before any status roll, and clears the flag as
  -- it spends the turn -- so a mon that just fired Hyper Beam loses exactly one
  -- turn even if it is also asleep.
  if mon and mon.recharge then
    mon.recharge = nil
    mon.rampage = nil
    mon.rampageMove = nil
  mon.rolloutTimer = nil
  mon.rolloutMove = nil
  mon.furyCutter = nil
    texts[1] = ("%s must recharge!"):format(mon.name or "POKeMON")
    return true, texts
  end
  local status = mon and mon.status
  if status == Game3.STATUS_FRZ then
    local thaw = (self:attackType(mon, move) == Game3.TYPE_FIRE)
      or (self:rand(100) <= 20)
    if thaw then
      mon.status = nil
      texts[1] = ("%s thawed out!"):format(mon.name)
      return false, texts
    end
    texts[1] = ("%s is frozen solid!"):format(mon.name)
    return true, texts
  end
  if status == Game3.STATUS_SLP then
    local left = mon.sleepTurns or 0
    if left <= 0 then
      mon.status = nil
      mon.sleepTurns = nil
      texts[1] = ("%s woke up!"):format(mon.name)
      return false, texts
    end
    mon.sleepTurns = left - 1
    if self:hasAbility(mon, Game3.ABILITY_EARLY_BIRD) and mon.sleepTurns > 0 then
      mon.sleepTurns = mon.sleepTurns - 1
    end
    texts[1] = ("%s is fast asleep!"):format(mon.name)
    return true, texts
  end
  if status == Game3.STATUS_PAR and self:rand(100) <= 25 then
    texts[1] = ("%s is paralyzed! It can't move!"):format(mon.name)
    return true, texts
  end
  if self:hasAbility(mon, Game3.ABILITY_TRUANT) then
    if mon.truant then
      mon.truant = nil
      texts[#texts + 1] = ("%s is loafing around!"):format(mon.name)
      return true, texts
    end
    mon.truant = true
  end
  local crush = mon.infatuatedBy
  if crush and Game3.aliveMon(crush) then
    texts[#texts + 1] = ("%s is in love with %s!"):format(
      mon.name, crush.name or "POKeMON")
    if (self:gbaRandom() % 2) == 0 then
      texts[#texts + 1] = ("%s is immobilized by love!"):format(mon.name)
      return true, texts
    end
  end
  return false, texts
end

function Game3:applyConfuse(mon)
  if not mon or (mon.hp or 0) <= 0 then return nil end
  if self:hasAbility(mon, Game3.ABILITY_OWN_TEMPO) then return nil end
  if (mon.confuseTurns or 0) > 0 then return nil end
  mon.confuseTurns = (self:rand(4) - 1) + 2
  if self.pulseBattleStatusFx and self.battle then
    local b = self.battle
    for _, slot in ipairs({ "player", "enemy", "player2", "enemy2" }) do
      if b[slot] == mon then
        self:pulseBattleStatusFx(slot)
        break
      end
    end
  end
  return ("%s became confused!"):format(mon.name or "POKeMON")
end

function Game3:confusionDamage(mon)
  if not mon then return 0 end
  local attack = staged(mon, "atk")
  if mon.status == Game3.STATUS_BRN then
    attack = math.max(1, math.floor(attack / 2))
  end
  local defense = staged(mon, "def")
  local dmg = Game3.damage(
    mon.level, Game3.CONFUSION_POWER, attack, defense, false, 10)
  local roll = 85 + self:rand(16) - 1
  dmg = math.max(1, math.floor(dmg * roll / 100))
  if mon.endured and dmg >= (mon.hp or 0) then
    dmg = math.max(0, (mon.hp or 1) - 1)
  end
  mon.hp = math.max(0, (mon.hp or 0) - dmg)
  return dmg
end

function Game3:confuseBlocks(mon)
  local texts = {}
  local left = mon and mon.confuseTurns or 0
  if left < 1 then return false, texts end
  mon.confuseTurns = left - 1
  if mon.confuseTurns < 1 then
    texts[1] = ("%s snapped out of confusion!"):format(mon.name)
    return false, texts
  end
  texts[1] = ("%s is confused!"):format(mon.name)
  -- ROM plays ConfusionEffect on the confuse check; one pulse, not idle loop.
  do
    local b = self.battle
    local slot = "player"
    if b then
      if mon == b.enemy or mon == b.enemy2 then
        slot = (mon == b.enemy2) and "enemy2" or "enemy"
      elseif mon == b.player2 then
        slot = "player2"
      end
      if self.pulseStatusFx then self:pulseStatusFx(slot, "confuse") end
    end
  end
  if self:rand(100) <= 50 then
    self:confusionDamage(mon)
    texts[#texts + 1] = "It hurt itself in its confusion!"
    if (mon.hp or 0) <= 0 then
      texts[#texts + 1] = ("%s fainted!"):format(mon.name)
    end
    return true, texts
  end
  return false, texts
end

-- pokeemerald: Random() & 3; if > 1 then (Random() & 3) + 2 else + 2.
function Game3.multiHitCount(first, second)
  first = (first or 0) % 4
  if first > 1 then return ((second or 0) % 4) + 2 end
  return first + 2
end

function Game3:rollMultiHits()
  local first = self:rand(4) - 1
  if first > 1 then return Game3.multiHitCount(first, self:rand(4) - 1) end
  return Game3.multiHitCount(first, 0)
end

function Game3.isFlinchEffect(effect)
  return effect == Game3.EFFECT_FLINCH_HIT
    or effect == Game3.EFFECT_FLINCH_MINIMIZE_HIT
    or effect == Game3.EFFECT_SKY_ATTACK
end

-- CalcCritChanceBonus: SCOPE_LENS adds a stage, and LUCKY_PUNCH / STICK add
-- two for the species that own them.
function Game3:heldCritStages(mon)
  local hold = self:holdEffectOf(mon)
  if hold == Game3.HOLD_EFFECT_SCOPE_LENS then return 1 end
  if hold == Game3.HOLD_EFFECT_LUCKY_PUNCH
      and mon and mon.species == Game3.SPECIES_CHANSEY then
    return 2
  end
  if hold == Game3.HOLD_EFFECT_STICK
      and mon and mon.species == Game3.SPECIES_FARFETCHD then
    return 2
  end
  return 0
end

function Game3.critStage(effect, focused, held)
  local n = (focused and 2 or 0) + (held or 0)
  if effect == Game3.EFFECT_HIGH_CRITICAL
      or effect == Game3.EFFECT_RAZOR_WIND
      or effect == Game3.EFFECT_SKY_ATTACK
      or effect == Game3.EFFECT_BLAZE_KICK
      or effect == Game3.EFFECT_POISON_TAIL then
    n = n + 1
  end
  if n > 4 then n = 4 end
  return n
end

-- pokeruby sCriticalHitChance: 1/N at stages 0-4.
Game3.CRIT_CHANCES = { 16, 8, 4, 3, 2 }

function Game3.critDenom(effect, focused, held)
  return Game3.CRIT_CHANCES[Game3.critStage(effect, focused, held) + 1]
end

function Game3.recoilDenom(effect)
  if effect == Game3.EFFECT_RECOIL then return 4 end
  if effect == Game3.EFFECT_DOUBLE_EDGE then return 3 end
end

function Game3:hitCountFor(effect)
  if effect == Game3.EFFECT_MULTI_HIT then return self:rollMultiHits() end
  if effect == Game3.EFFECT_DOUBLE_HIT then return 2 end
  if effect == Game3.EFFECT_TWINEEDLE then return 2 end
  if effect == Game3.EFFECT_TRIPLE_KICK then return 3 end
  return 1
end

function Game3:useRestoreHp(attacker, texts, move)
  local hp, maxHp = attacker.hp or 0, attacker.maxHp or 0
  if maxHp < 1 or hp >= maxHp then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  local heal = math.max(1, math.floor(maxHp / 2))
  attacker.hp = math.min(maxHp, hp + heal)
  texts[#texts + 1] = ("%s regained health!"):format(attacker.name)
  self:armMoveAnim(attacker, attacker, move or { name = "RECOVER", id = 105 }, "status")
  return texts
end

function Game3:useRest(attacker, texts)
  if attacker.status == Game3.STATUS_SLP then
    texts[#texts + 1] = ("%s is already asleep!"):format(attacker.name)
    return texts
  end
  -- jumpifcantmakeasleep before trysetrest: uproar, then Insomnia/Vital Spirit.
  if self:fieldHasUproar()
      and not self:hasAbility(attacker, Game3.ABILITY_SOUNDPROOF) then
    texts[#texts + 1] = ("But %s can't sleep in an UPROAR!"):format(
      attacker.name)
    return texts
  end
  if self:hasAbility(attacker, Game3.ABILITY_INSOMNIA)
      or self:hasAbility(attacker, Game3.ABILITY_VITAL_SPIRIT) then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  local hp, maxHp = attacker.hp or 0, attacker.maxHp or 0
  if maxHp < 1 or hp >= maxHp then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  attacker.hp = maxHp
  attacker.status = Game3.STATUS_SLP
  attacker.sleepTurns = 2
  attacker.toxicCounter = nil
  texts[#texts + 1] = ("%s went to sleep and became healthy!"):format(
    attacker.name)
  return texts
end

-- atkAE_healpartystatus. Heal Bell skips Soundproof battlers (and matching
-- party slots); Aromatherapy heals everyone. status1 only.
function Game3:useHealBell(attacker, move, texts)
  texts = texts or {}
  local id = (move and move.id) or 0
  local name = (move and move.name or ""):upper()
  local aroma = id == Game3.MOVE_AROMATHERAPY or name == "AROMATHERAPY"
  local blocked = {}
  local function healMon(mon)
    if not mon or mon.isEgg then return end
    if not aroma and self:hasAbility(mon, Game3.ABILITY_SOUNDPROOF) then
      blocked[#blocked + 1] = mon
      return
    end
    mon.status = nil
    mon.sleepTurns = nil
    mon.toxicCounter = nil
  end
  if self:isPlayerSide(attacker) then
    local party = self.party
    if type(party) == "table" and #party > 0 then
      for i = 1, #party do healMon(party[i]) end
    else
      healMon(attacker)
      healMon(self:allyOf(attacker))
    end
  else
    healMon(attacker)
    healMon(self:allyOf(attacker))
  end
  if aroma then
    texts[#texts + 1] = "A soothing aroma wafted through the area!"
  else
    texts[#texts + 1] = "A bell chimed!"
    for i = 1, #blocked do
      texts[#texts + 1] = ("%s's %s blocks %s!"):format(
        blocked[i].name, Game3.abilityName(Game3.ABILITY_SOUNDPROOF),
        (move and move.name) or "HEAL BELL")
    end
  end
  return texts
end

-- atkB2_trysetperishsong. Skip Soundproof and already-perishing battlers.
function Game3:usePerishSong(attacker, move, texts)
  texts = texts or {}
  local mons = self:battlers()
  local hit = 0
  local blocked = {}
  for i = 1, #mons do
    local mon = mons[i]
    if mon then
      if self:hasAbility(mon, Game3.ABILITY_SOUNDPROOF) then
        blocked[#blocked + 1] = mon
      elseif not mon.perishSong then
        mon.perishSong = 3
        hit = hit + 1
      end
    end
  end
  if hit < 1 then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  texts[#texts + 1] = "All affected POKeMON will faint in 3 turns!"
  for i = 1, #blocked do
    texts[#texts + 1] = ("%s's %s blocks %s!"):format(
      blocked[i].name, Game3.abilityName(Game3.ABILITY_SOUNDPROOF),
      (move and move.name) or "PERISH SONG")
  end
  return texts
end

-- atkD5_trysetroots.
function Game3:useIngrain(attacker, texts)
  texts = texts or {}
  if attacker.rooted then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  attacker.rooted = true
  texts[#texts + 1] = ("%s planted its roots!"):format(attacker.name)
  return texts
end

-- ENDTURN_WRAP: decrement first, then damage if still held, else the free
-- message. maxHP/16, floored at 1.
function Game3:wrapResidual(mon)
  if not mon or (mon.hp or 0) <= 0 then return {} end
  local left = mon.wrapped or 0
  if left <= 0 then return {} end
  left = left - 1
  local name = mon.wrappedMoveName or "the attack"
  if left <= 0 then
    mon.wrapped = nil
    mon.wrappedMoveName = nil
    mon.wrappedBy = nil
    return { ("%s was freed from %s!"):format(mon.name or "POKeMON", name) }
  end
  mon.wrapped = left
  local dmg = math.max(1, math.floor((mon.maxHp or 1) / Game3.WRAP_DENOM))
  mon.hp = math.max(0, (mon.hp or 0) - dmg)
  local texts = { ("%s is hurt by %s!"):format(mon.name or "POKeMON", name) }
  if (mon.hp or 0) <= 0 then
    texts[#texts + 1] = ("%s fainted!"):format(mon.name or "POKeMON")
  end
  return texts
end

-- A wrapped mon cannot switch out or run (battle_main.c checks STATUS2_WRAPPED
-- alongside STATUS2_ESCAPE_PREVENTION).
function Game3:isTrapped(mon)
  return mon ~= nil and (mon.wrapped or 0) > 0
end

function Game3:statusResidual(mon)
  if not mon or (mon.hp or 0) <= 0 then return {} end
  if self:hasAbility(mon, Game3.ABILITY_SHED_SKIN) and mon.status
      and self:rand(100) <= 30 then
    mon.status = nil
    mon.sleepTurns = nil
    mon.toxicCounter = nil
    return { ("%s's %s cured its status!"):format(
      mon.name, Game3.abilityName(Game3.ABILITY_SHED_SKIN)) }
  end
  local status = mon.status
  if status ~= Game3.STATUS_BRN and not Game3.isPoisonStatus(status) then
    return {}
  end
  local dmg
  if status == Game3.STATUS_TOXIC then
    -- pokeruby ENDTURN_BAD_POISON: maxHP/16 * N, N increments (cap 15).
    dmg = math.max(1, math.floor((mon.maxHp or 1) / 16))
    local n = tonumber(mon.toxicCounter) or 0
    if n < 15 then n = n + 1 end
    mon.toxicCounter = n
    dmg = dmg * n
  else
    dmg = math.max(1, math.floor((mon.maxHp or 1) / 8))
  end
  mon.hp = math.max(0, (mon.hp or 0) - dmg)
  local texts = {}
  if status == Game3.STATUS_BRN then
    texts[1] = ("%s was hurt by its burn!"):format(mon.name)
  else
    texts[1] = ("%s was hurt by poison!"):format(mon.name)
  end
  if (mon.hp or 0) <= 0 then
    texts[#texts + 1] = ("%s fainted!"):format(mon.name)
  end
  return texts
end

function Game3:isPlayerBattler(mon)
  local b = self.battle
  if not (b and mon) then return false end
  return mon == b.player or mon == b.player2
end

function Game3:battlerSlot(mon)
  local b = self.battle
  if not (b and mon) then return nil end
  if mon == b.player then return "player" end
  if mon == b.player2 then return "player2" end
  if mon == b.enemy then return "enemy" end
  if mon == b.enemy2 then return "enemy2" end
end

function Game3:leechSeedSower(mon)
  if not mon then return nil end
  local slot = mon.leechSeedSlot
  if slot and self.battle then return self.battle[slot] end
  return mon.leechSeedFrom
end

-- pokeruby BattleScript_EffectLeechSeed / atk7F_setseeded.
function Game3:useLeechSeed(attacker, defender, texts)
  texts = texts or {}
  if not defender then return texts end
  if defender.leechSeed then
    texts[#texts + 1] = ("%s evaded the attack!"):format(defender.name)
    return texts
  end
  if Game3.hasType(defender, Game3.TYPE_GRASS) then
    texts[#texts + 1] = ("It doesn't affect %s..."):format(defender.name)
    return texts
  end
  defender.leechSeed = true
  defender.leechSeedFrom = attacker
  defender.leechSeedSlot = self:battlerSlot(attacker)
  texts[#texts + 1] = ("%s was seeded!"):format(defender.name)
  self:armMoveAnim(attacker, defender, { name = "LEECH SEED", type = Game3.TYPE_GRASS },
    "status")
  return texts
end

-- pokeruby BattleScript_EffectNaturePower / atkCC_callenvironmentattack.
function Game3:useNaturePower(attacker, defender, texts)
  texts = texts or {}
  local env = self:battleEnvironment()
  local id = Game3.NATURE_POWER_MOVES[env] or Game3.MOVE_SWIFT
  local called = self:copyMove(id)
  texts[#texts + 1] = ("NATURE POWER turned into %s!"):format(
    called.name or "MOVE")
  local more = self:useMove(attacker, defender, called, true)
  for i = 1, #more do
    texts[#texts + 1] = more[i]
  end
  return texts
end

-- pokeruby BattleScript_EffectForesight / atkB1_setforesight.
function Game3:useForesight(attacker, defender, texts)
  texts = texts or {}
  if not defender then return texts end
  defender.foresight = true
  texts[#texts + 1] = ("%s identified %s!"):format(
    attacker.name, defender.name)
  return texts
end

function Game3:useAttract(attacker, defender, texts)
  texts = texts or {}
  if not defender then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  if self:hasAbility(defender, Game3.ABILITY_OBLIVIOUS) then
    texts[#texts + 1] = ("%s's %s prevents attraction!"):format(
      defender.name, Game3.abilityName(Game3.ABILITY_OBLIVIOUS))
    return texts
  end
  if defender.invuln then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  if defender.infatuatedBy then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  local ag, dg = self:monGender(attacker), self:monGender(defender)
  if ag == dg or ag == Game3.MON_GENDERLESS or dg == Game3.MON_GENDERLESS then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  defender.infatuatedBy = attacker
  texts[#texts + 1] = ("%s fell in love!"):format(defender.name)
  return texts
end

-- ENDTURN_LEECH_SEED: maxHP/8, min 1. Liquid Ooze hurts the sower.
function Game3:leechSeedResidual(mon)
  if not mon or not mon.leechSeed or (mon.hp or 0) <= 0 then return {} end
  local sower = self:leechSeedSower(mon)
  if not Game3.aliveMon(sower) then return {} end
  local dmg = math.max(1, math.floor((mon.maxHp or 1) / 8))
  mon.hp = math.max(0, (mon.hp or 0) - dmg)
  local texts = {}
  if self:hasAbility(mon, Game3.ABILITY_LIQUID_OOZE) then
    sower.hp = math.max(0, (sower.hp or 0) - dmg)
    texts[1] = "It sucked up the LIQUID OOZE!"
  else
    local maxHp = sower.maxHp or (sower.hp or 0)
    sower.hp = math.min(maxHp, (sower.hp or 0) + dmg)
    texts[1] = ("%s's health is sapped by LEECH SEED!"):format(mon.name)
  end
  if (mon.hp or 0) <= 0 then
    texts[#texts + 1] = ("%s fainted!"):format(mon.name)
  end
  if (sower.hp or 0) <= 0 then
    texts[#texts + 1] = ("%s fainted!"):format(sower.name)
  end
  return texts
end

-- ENDTURN_INGRAIN: maxHP/16, min 1, before leech seed.
function Game3:ingrainResidual(mon)
  if not mon or not mon.rooted or (mon.hp or 0) <= 0 then return {} end
  local maxHp = mon.maxHp or 1
  if (mon.hp or 0) >= maxHp then return {} end
  local heal = math.max(1, math.floor(maxHp / 16))
  mon.hp = math.min(maxHp, (mon.hp or 0) + heal)
  return { ("%s absorbed nutrients with its roots!"):format(mon.name) }
end

-- ENDTURN_UPROAR: wake every non-Soundproof sleeper, then decrement.
function Game3:uproarResidual(mon)
  if not mon or (mon.uproarTurns or 0) < 1 then return {} end
  local texts = {}
  local mons = self:battlers()
  for i = 1, #mons do
    local other = mons[i]
    if other and (other.hp or 0) > 0 and other.status == Game3.STATUS_SLP
        and not self:hasAbility(other, Game3.ABILITY_SOUNDPROOF) then
      other.status = nil
      other.sleepTurns = nil
      texts[#texts + 1] = ("%s woke up in the UPROAR!"):format(other.name)
    end
  end
  mon.uproarTurns = mon.uproarTurns - 1
  if mon.uproarTurns > 0 then
    texts[#texts + 1] = ("%s is making an UPROAR!"):format(mon.name)
  else
    mon.uproarTurns = nil
    mon.uproarMove = nil
    texts[#texts + 1] = ("%s calmed down."):format(mon.name)
  end
  return texts
end

-- HandleWishPerishSongOnTurnEnd: print the current count, then decrement
-- (or faint when the count is already 0).
function Game3:perishSongResidual(mon)
  if not mon or not mon.perishSong or (mon.hp or 0) <= 0 then return {} end
  local n = mon.perishSong
  if n <= 0 then
    mon.hp = 0
    mon.perishSong = nil
    return {
      ("%s's PERISH count fell to 0!"):format(mon.name),
      ("%s fainted!"):format(mon.name),
    }
  end
  local texts = { ("%s's PERISH count fell to %d!"):format(mon.name, n) }
  mon.perishSong = n - 1
  return texts
end

function Game3:holdEffectOf(mon)
  local id = mon and tonumber(mon.item) or 0
  if id < 1 then return 0, 0 end
  local row = self:itemRow(id)
  local effect = row and tonumber(row.holdEffect)
  local param = row and tonumber(row.holdEffectParam)
  if not effect or effect == 0 then
    effect = Game3.TYPE_POWER_ITEM[id]
    if effect then param = 10 end
  end
  if (not effect or effect == 0) and id == Game3.ITEM_SOOTHE_BELL then
    effect = Game3.HOLD_EFFECT_HAPPINESS_UP
  end
  if (not effect or effect == 0) and id == Game3.ITEM_QUICK_CLAW then
    effect = Game3.HOLD_EFFECT_QUICK_CLAW
    param = Game3.QUICK_CLAW_PARAM
  end
  if (not effect or effect == 0) and id == Game3.ITEM_EXP_SHARE then
    effect = Game3.HOLD_EFFECT_EXP_SHARE
  end
  if (not effect or effect == 0) and id == Game3.ITEM_MACHO_BRACE then
    effect = Game3.HOLD_EFFECT_MACHO_BRACE
  end
  if (not effect or effect == 0) and id == Game3.ITEM_SMOKE_BALL then
    effect = Game3.HOLD_EFFECT_CAN_ALWAYS_RUN
  end
  if (not effect or effect == 0) and id == Game3.ITEM_EVERSTONE then
    effect = Game3.HOLD_EFFECT_PREVENT_EVOLVE
  end
  return effect or 0, param or 0
end

-- pokeruby CalculateBaseDamage: matching gHoldEffectToType boosts
-- attack or Sp. Atk by (param + 100) / 100.
function Game3:applyTypePower(mon, moveType, stat)
  local effect, param = self:holdEffectOf(mon)
  if Game3.HOLD_EFFECT_TYPE[effect] ~= moveType then return stat end
  return math.max(1, math.floor(stat * (100 + (param or 10)) / 100))
end

-- pokeruby BADGE_BOOST: 10% on the player's stat in trainer battles.
function Game3:applyBadgeBoost(mon, badge, stat)
  if not (self.battle and self.battle.isTrainer) then return stat end
  if not self:isPlayerBattler(mon) then return stat end
  if not self:hasBadge(badge) then return stat end
  return math.max(1, math.floor(stat * 110 / 100))
end

function Game3:dealDamage(attacker, defender, move, dryRun)
  local chart = self.data.moves and self.data.moves.typeChart
  local moveType = self:attackType(attacker, move)
  if self:hasAbility(defender, Game3.ABILITY_LEVITATE)
      and moveType == Game3.TYPE_GROUND then
    return { dmg = 0, mul = 0 }
  end
  -- battle_script_commands.c TypeCalc / AI_TypeCalc both open with
  -- `if (move == MOVE_STRUGGLE) return 0;`, so Struggle is typeless: no
  -- STAB, no effectiveness, and Wonder Guard does not stop it.
  local struggle = (move.id or 0) == Game3.MOVE_STRUGGLE
  local mul = struggle and 10
    or Game3.typeMul(chart, moveType, defender.type1, defender.type2,
      defender.foresight)
  if not struggle and self:hasAbility(defender, Game3.ABILITY_WONDER_GUARD)
      and mul > 0 and mul <= 10 then
    mul = 0
  end
  if mul <= 0 then return { dmg = 0, mul = 0 } end
  -- Seismic Toss / Night Shade: dmgtolevel, then clear SE/NVE for display.
  if (move.effect or 0) == Game3.EFFECT_LEVEL_DAMAGE then
    local dmg = math.max(1, attacker.level or 1)
    local endured = false
    if defender.endured and dmg >= (defender.hp or 0) then
      dmg = math.max(0, (defender.hp or 1) - 1)
      endured = true
    end
    defender.hp = math.max(0, (defender.hp or 0) - dmg)
    self:noteBideHit(defender, attacker, dmg)
    self:notePlayerDamaged(defender, dmg)
    self:maybeFaintFriendship(defender, attacker)
    return { dmg = dmg, mul = 10, crit = false, endured = endured }
  end
  -- atk94_damagetohalftargethp: half the target's CURRENT hp, floored at 1.
  if (move.effect or 0) == Game3.EFFECT_SUPER_FANG then
    return self:applySetDamage(attacker, defender,
      math.max(1, math.floor((defender.hp or 1) / 2)))
  end
  -- SONICBOOM is a flat 20 the same way DRAGON RAGE is a flat 40.
  if (move.effect or 0) == Game3.EFFECT_SONICBOOM then
    return self:applySetDamage(attacker, defender, Game3.SONICBOOM_DAMAGE)
  end
  -- FALSE SWIPE always leaves the target standing.
  if (move.effect or 0) == Game3.EFFECT_FALSE_SWIPE then
    local keep = math.max(0, (defender.hp or 0) - 1)
    -- fall through to the normal formula, capped below
    move._falseSwipeCap = keep
  end
  -- Beat Up runs its own formula per swing rather than the usual one.
  if (move.effect or 0) == Game3.EFFECT_BEAT_UP then
    return self:applySetDamage(attacker, defender,
      self:beatUpDamage(attacker, defender, move))
  end
  -- setword gBattleMoveDamage, 40 -- flat, whatever the levels are.
  if (move.effect or 0) == Game3.EFFECT_DRAGON_RAGE then
    return self:applySetDamage(attacker, defender, Game3.DRAGON_RAGE_DAMAGE)
  end
  -- atkA0_psywavedamageeffect: a 0-10 roll times ten, then
  -- level * (roll + 50) / 100 -- half to one and a half times the level.
  if (move.effect or 0) == Game3.EFFECT_PSYWAVE then
    local roll = self:gbaRandom() % 16
    while roll > 10 do roll = self:gbaRandom() % 16 end
    local dmg = math.floor((attacker.level or 1) * (roll * 10 + 50) / 100)
    return self:applySetDamage(attacker, defender, math.max(1, dmg))
  end
  -- atkA1/atkA2: twice the damage this mon took from the other side this turn,
  -- physical for COUNTER and special for MIRROR COAT. No source, no damage.
  if (move.effect or 0) == Game3.EFFECT_COUNTER
      or (move.effect or 0) == Game3.EFFECT_MIRROR_COAT then
    local slot = (move.effect == Game3.EFFECT_COUNTER)
      and "counterPhysical" or "counterSpecial"
    local taken = attacker[slot]
    local from = attacker[slot .. "From"]
    if not taken or taken < 1 or not Game3.aliveMon(from) then
      return { dmg = 0, mul = 0, failed = true }
    end
    return self:applySetDamage(attacker, defender, taken * 2)
  end
  -- pokeruby atkD8_setdamagetohealthdifference + atk69_adjustsetdamage.
  -- Damage is targetHP - userHP. No STAB, screens, crit, or roll.
  if (move.effect or 0) == Game3.EFFECT_ENDEAVOR then
    local dmg = (defender.hp or 0) - (attacker.hp or 0)
    if dmg < 1 then return { dmg = 0, mul = 0 } end
    local endured = false
    if defender.endured and dmg >= (defender.hp or 0) then
      dmg = math.max(0, (defender.hp or 1) - 1)
      endured = true
    end
    defender.hp = math.max(0, (defender.hp or 0) - dmg)
    self:noteBideHit(defender, attacker, dmg)
    self:notePlayerDamaged(defender, dmg)
    self:maybeFaintFriendship(defender, attacker)
    return { dmg = dmg, mul = 10, crit = false, endured = endured }
  end
  local physical = Game3.isPhysical(moveType)
  local attack = staged(attacker, physical and "atk" or "spa")
  if physical then
    if self:hasAbility(attacker, Game3.ABILITY_HUSTLE) then
      attack = math.max(1, math.floor(attack * 150 / 100))
    end
    if self:hasAbility(attacker, Game3.ABILITY_GUTS) and attacker.status then
      attack = math.max(1, math.floor(attack * 3 / 2))
    elseif attacker.status == Game3.STATUS_BRN then
      attack = math.max(1, math.floor(attack / 2))
    end
    if self:hasAbility(attacker, Game3.ABILITY_HUGE_POWER)
        or self:hasAbility(attacker, Game3.ABILITY_PURE_POWER) then
      attack = attack * 2
    end
  else
    if (self:hasAbility(attacker, Game3.ABILITY_PLUS)
          and self:fieldHasAbility(Game3.ABILITY_MINUS))
        or (self:hasAbility(attacker, Game3.ABILITY_MINUS)
          and self:fieldHasAbility(Game3.ABILITY_PLUS)) then
      attack = math.max(1, math.floor(attack * 150 / 100))
    end
  end
  -- calculate_base_damage.c's held-item block. CHOICE_BAND lifts the physical
  -- attack whatever the move; the rest are species-locked.
  local aHold, aParam = self:holdEffectOf(attacker)
  if physical and aHold == Game3.HOLD_EFFECT_CHOICE_BAND then
    attack = math.max(1, math.floor(attack * 150 / 100))
  end
  if physical and aHold == Game3.HOLD_EFFECT_THICK_CLUB
      and (attacker.species == Game3.SPECIES_CUBONE
        or attacker.species == Game3.SPECIES_MAROWAK) then
    attack = attack * 2
  end
  if not physical and aHold == Game3.HOLD_EFFECT_SOUL_DEW
      and (attacker.species == Game3.SPECIES_LATIAS
        or attacker.species == Game3.SPECIES_LATIOS) then
    attack = math.max(1, math.floor(attack * 150 / 100))
  end
  if not physical and aHold == Game3.HOLD_EFFECT_DEEP_SEA_TOOTH
      and attacker.species == Game3.SPECIES_CLAMPERL then
    attack = attack * 2
  end
  if not physical and aHold == Game3.HOLD_EFFECT_LIGHT_BALL
      and attacker.species == Game3.SPECIES_PIKACHU then
    attack = attack * 2
  end
  attack = self:applyTypePower(attacker, moveType, attack)
  attack = self:applyBadgeBoost(attacker, physical and 1 or 7, attack)
  local defense = staged(defender, physical and "def" or "spd")
  local dHold = self:holdEffectOf(defender)
  if physical and dHold == Game3.HOLD_EFFECT_METAL_POWDER
      and defender.species == Game3.SPECIES_DITTO then
    defense = defense * 2
  end
  if not physical and dHold == Game3.HOLD_EFFECT_SOUL_DEW
      and (defender.species == Game3.SPECIES_LATIAS
        or defender.species == Game3.SPECIES_LATIOS) then
    defense = math.max(1, math.floor(defense * 150 / 100))
  end
  if not physical and dHold == Game3.HOLD_EFFECT_DEEP_SEA_SCALE
      and defender.species == Game3.SPECIES_CLAMPERL then
    defense = defense * 2
  end
  if physical and self:hasAbility(defender, Game3.ABILITY_MARVEL_SCALE)
      and defender.status then
    defense = math.max(1, math.floor(defense * 3 / 2))
  end
  defense = self:applyBadgeBoost(defender, physical and 5 or 7, defense)
  if (move.effect or 0) == Game3.EFFECT_EXPLOSION then
    defense = math.max(1, math.floor(defense / 2))
  end
  local power = self:boostedPower(attacker, move, defender, dryRun)
  local dmg = Game3.damage(
    attacker.level, power, attack, defense,
    (not struggle) and hasStab(attacker, moveType) or false, mul)
  -- AI_CalcDmg takes the flat figure: the AI's spread comes from its own
  -- simulatedRNG afterwards, so rolling here as well would double it.
  local roll = dryRun == "ai" and 100 or (85 + self:rand(16) - 1)
  dmg = math.max(1, math.floor(dmg * roll / 100))
  local wmul = self:weatherPowerTenths(moveType)
  if wmul ~= 10 then
    dmg = math.max(1, math.floor(dmg * wmul / 10))
  end
  if defender.invuln == "dig"
      and (move.effect == Game3.EFFECT_EARTHQUAKE
        or move.effect == Game3.EFFECT_MAGNITUDE) then
    dmg = dmg * 2
  elseif defender.invuln == "fly"
      and (move.effect == Game3.EFFECT_GUST
        or move.effect == Game3.EFFECT_TWISTER) then
    dmg = dmg * 2
  end
  if self:hasAbility(defender, Game3.ABILITY_THICK_FAT)
      and (moveType == Game3.TYPE_FIRE or moveType == Game3.TYPE_ICE) then
    dmg = math.max(1, math.floor(dmg / 2))
  end
  local crit = false
  local b = self.battle
  if not (b and (b.wallyTutorial or b.chase))
      and not self:hasAbility(defender, Game3.ABILITY_BATTLE_ARMOR)
      and not self:hasAbility(defender, Game3.ABILITY_SHELL_ARMOR) then
    local denom = Game3.critDenom(move.effect, attacker.focusEnergy,
      self:heldCritStages(attacker))
    crit = self:rand(denom) == denom
  end
  if crit then dmg = dmg * 2 end
  if not crit then
    local cut = self:screenDamageMul(defender, physical)
    if cut ~= 10 then
      dmg = math.max(1, math.floor(dmg * cut / 10))
    end
  end
  if move.spreadHits then
    dmg = math.max(1, math.floor(dmg / 2))
  end
  -- BattleScript_SmellingsaltDoubleDmg sets sDMG_MULTIPLIER to 2 before
  -- the calc when the target is paralysed.
  if (move.effect or 0) == Game3.EFFECT_SMELLINGSALT then
    dmg = dmg * self:smellingSaltMultiplier(defender)
  end
  if (move.effect or 0) == Game3.EFFECT_REVENGE then
    dmg = dmg * self:revengeMultiplier(attacker, defender)
  end
  -- BattleScript_ActionSwitch is what sets sDMG_MULTIPLIER for PURSUIT:
  -- the doubling belongs to the switch, not to the move.
  if move._pursuitSwitch then dmg = dmg * 2 end
  -- STATUS3_CHARGED_UP doubles one ELECTRIC move, and HELPING HAND adds
  -- half again on top of the crit multiplier.
  dmg = dmg * self:chargeMultiplier(attacker, moveType)
  if attacker.helpingHand then
    dmg = math.floor(dmg * Game3.HELPING_HAND_NUM / Game3.HELPING_HAND_DEN)
  end
  -- SPIT UP multiplies the base damage by whatever is banked.
  if (move.effect or 0) == Game3.EFFECT_SPIT_UP then
    dmg = dmg * self:spitUpMultiplier(attacker)
  end
  -- FALSE SWIPE always leaves the target with at least one HP.
  if (move.effect or 0) == Game3.EFFECT_FALSE_SWIPE then
    dmg = math.min(dmg, math.max(0, (defender.hp or 1) - 1))
  end
  local endured = false
  if defender.endured and dmg >= (defender.hp or 0) then
    dmg = math.max(0, (defender.hp or 1) - 1)
    endured = true
  end
  -- Jump Kick's crash runs damagecalc/typecalc/adjustnormaldamage without
  -- ever landing the hit, so this stops short of touching the target.
  if dryRun then return { dmg = dmg, mul = mul, crit = crit } end
  -- The doll soaks the whole hit and the holder's own HP never moves; Focus
  -- Band and the counter record only matter for damage that actually lands.
  if defender.substitute then
    local faded = self:absorbIntoSubstitute(defender, dmg)
    return { dmg = dmg, mul = mul, crit = crit, substitute = true,
      substituteFaded = faded and #faded > 0 or false, texts = faded }
  end
  -- HOLD_EFFECT_FOCUS_BAND: a param% roll to hang on with 1 HP left.
  if dmg >= (defender.hp or 0) and (defender.hp or 0) > 0 then
    local hold, param = self:holdEffectOf(defender)
    if hold == Game3.HOLD_EFFECT_FOCUS_BAND
        and (self:gbaRandom() % 100) < (param or 0) then
      dmg = math.max(0, (defender.hp or 1) - 1)
      defender.heldOn = true
    end
  end
  defender.hp = math.max(0, (defender.hp or 0) - dmg)
  -- HOLD_EFFECT_SHELL_BELL drains an eighth of what it dealt, and
  -- HOLD_EFFECT_FLINCH (King's Rock) rolls to make the target flinch.
  if dmg > 0 then
    local hold, param = self:holdEffectOf(attacker)
    if hold == Game3.HOLD_EFFECT_SHELL_BELL
        and (attacker.hp or 0) > 0 and (attacker.hp or 0) < (attacker.maxHp or 0) then
      local heal = math.max(1, math.floor(dmg / Game3.SHELL_BELL_DENOM))
      attacker.hp = math.min(attacker.maxHp, (attacker.hp or 0) + heal)
      attacker.drainedByShellBell = heal
    end
    if hold == Game3.HOLD_EFFECT_FLINCH
        and (defender.hp or 0) > dmg
        and (self:gbaRandom() % 100) < (param or 0) then
      defender.flinch = true
    end
  end
  -- gProtectStructs physicalDmg / specialDmg, which COUNTER and MIRROR COAT
  -- read back later in the same turn. Set damage does not fill these -- only a
  -- real physical or special hit does.
  if dmg > 0 then
    defender.lastHitByType = moveType
    -- gLastLandedMoves / gLastHitBy: switch AI (FindMonThatAbsorbs /
    -- FindMonWithFlagsAndSuperEffective) reads the last damaging hit.
    defender.lastLandedMove = move
    defender.lastHitBy = attacker
    if physical then
      defender.counterPhysical = dmg
      defender.counterPhysicalFrom = attacker
    else
      defender.counterSpecial = dmg
      defender.counterSpecialFrom = attacker
    end
  end
  self:noteBideHit(defender, attacker, dmg)
  self:notePlayerDamaged(defender, dmg)
  self:maybeFaintFriendship(defender, attacker)
  return { dmg = dmg, mul = mul, crit = crit, endured = endured }
end

-- atkA5_painsplitdmgcalc: average the two current HPs and move both mons to
-- it. Either side can gain HP, and it does not go through damage at all -- no
-- type check, no crit, no Endure, and a substitute blocks it outright.
function Game3:usePainSplit(attacker, defender, texts)
  texts = texts or {}
  if not defender or (defender.hp or 0) <= 0 or defender.substitute then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  local avg = math.floor(((attacker.hp or 0) + (defender.hp or 0)) / 2)
  attacker.hp = math.min(attacker.maxHp or avg, avg)
  defender.hp = math.min(defender.maxHp or avg, avg)
  texts[#texts + 1] = "The battlers shared their pain!"
  return texts
end

-- normalisebuffs: every stage on the field goes back to zero, both sides.
-- atk9B_transformdataexecution: the user becomes a copy of the target -- its
-- species, types, ability, stats and stat stages -- keeping only its own HP
-- and level. Copied moves come with 5 PP, or the move's own if that is less.
function Game3:useTransform(attacker, defender, texts)
  texts = texts or {}
  if not defender or defender.transformed or defender.substitute then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  -- The copy is only for this battle, so keep everything it overwrites. Without
  -- this a Ditto that transformed would stay a Charizard in the party.
  attacker.transformOriginal = {
    species = attacker.species, type1 = attacker.type1, type2 = attacker.type2,
    ability = attacker.ability, atk = attacker.atk, def = attacker.def,
    spa = attacker.spa, spd = attacker.spd, spe = attacker.spe,
    moves = attacker.moves,
  }
  attacker.transformed = true
  attacker.species = defender.species
  attacker.type1, attacker.type2 = defender.type1, defender.type2
  attacker.ability = defender.ability
  for _, k in ipairs({ "atk", "def", "spa", "spd", "spe" }) do
    attacker[k] = defender[k]
  end
  local st = defender.stages or {}
  attacker.stages = {
    atk = st.atk or 0, def = st.def or 0, spa = st.spa or 0,
    spd = st.spd or 0, spe = st.spe or 0, acc = st.acc or 0, eva = st.eva or 0,
  }
  local copied = {}
  for i = 1, #(defender.moves or {}) do
    local mv = defender.moves[i]
    if mv then
      local base = self:movePp(mv.id) or Game3.COPIED_MOVE_PP
      local pp = math.min(base, Game3.COPIED_MOVE_PP)
      copied[i] = { id = mv.id, pp = pp, maxPp = pp }
    end
  end
  attacker.moves = copied
  -- transformdataexecution also clears any disable on the user.
  attacker.disabledMove = nil
  attacker.disableTurns = nil
  texts[#texts + 1] = ("%s transformed into %s!"):format(
    attacker.name or "POKeMON", defender.name or "POKeMON")
  return texts
end

-- Put back everything useTransform copied over. Safe to call on any mon.
function Game3:undoTransform(mon)
  local orig = mon and mon.transformOriginal
  if not orig then return false end
  for k, v in pairs(orig) do mon[k] = v end
  mon.transformOriginal = nil
  mon.transformed = nil
  return true
end

function Game3:movePp(id)
  local row = self.data and self.data.moves and self.data.moves.byId
    and self.data.moves.byId[tonumber(id) or -1]
  return row and tonumber(row.pp)
end

-- The slot the move being used occupies, which is what Mimic and Sketch
-- overwrite.
function Game3:moveSlotOf(mon, move)
  if not (mon and move) then return nil end
  for i = 1, #(mon.moves or {}) do
    local mv = mon.moves[i]
    if mv and mv.id == move.id then return i end
  end
  return nil
end

-- atk9D_mimicattackcopy: the target's last move replaces the Mimic slot with
-- five PP. Refused for a transformed user, an uncopyable move, or one the
-- user already knows.
function Game3:useMimic(attacker, defender, move, texts)
  texts = texts or {}
  local last = defender and defender.lastMove
  local slot = self:moveSlotOf(attacker, move)
  local known = false
  for i = 1, #(attacker.moves or {}) do
    local mv = attacker.moves[i]
    if mv and last and mv.id == last then known = true end
  end
  if not last or last == 0 or attacker.transformed
      or Game3.MIMIC_FORBIDDEN[last] or known or not slot then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  local base = self:movePp(last) or Game3.COPIED_MOVE_PP
  local pp = math.min(base, Game3.COPIED_MOVE_PP)
  attacker.moves[slot] = { id = last, pp = pp, maxPp = pp, mimicked = true }
  texts[#texts + 1] = ("%s learned %s!"):format(
    attacker.name or "POKeMON", self:moveName(last))
  return texts
end

-- Sketch is Mimic that sticks: the slot is replaced for good, and with the
-- copied move's own PP rather than five.
function Game3:useSketch(attacker, defender, move, texts)
  texts = texts or {}
  local last = defender and defender.lastMove
  local slot = self:moveSlotOf(attacker, move)
  local known = false
  for i = 1, #(attacker.moves or {}) do
    local mv = attacker.moves[i]
    if mv and last and mv.id == last then known = true end
  end
  if not last or last == 0 or Game3.COPY_FORBIDDEN[last] or known or not slot then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  local pp = self:movePp(last) or Game3.COPIED_MOVE_PP
  attacker.moves[slot] = { id = last, pp = pp, maxPp = pp }
  texts[#texts + 1] = ("%s sketched %s!"):format(
    attacker.name or "POKeMON", self:moveName(last))
  return texts
end

-- A move the copiers are allowed to pull. `full` uses the whole forbidden
-- list (Metronome, Sleep Talk, Mirror Move); Mimic uses the short one.
function Game3:copyableMove(id, full)
  id = tonumber(id) or 0
  if id == 0 then return false end
  if full then return not Game3.COPY_FORBIDDEN[id] end
  return not Game3.MIMIC_FORBIDDEN[id]
end

-- Conversion takes the type of one of the user's own moves.
function Game3:useConversion(attacker, texts)
  texts = texts or {}
  local byId = self.data and self.data.moves and self.data.moves.byId
  local options = {}
  for i = 1, #(attacker.moves or {}) do
    local mv = attacker.moves[i]
    local row = mv and byId and byId[mv.id]
    local t = row and row.type
    if t and not Game3.hasType(attacker, t) then options[#options + 1] = t end
  end
  if #options < 1 then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  local pick = options[(self:gbaRandom() % #options) + 1]
  attacker.type1, attacker.type2 = pick, pick
  texts[#texts + 1] = ("%s transformed into the %s type!"):format(
    attacker.name or "POKeMON", Game3.typeName(pick))
  return texts
end

-- Conversion 2 takes a type that resists whatever last hit the user, which is
-- why dealDamage records the incoming move's type.
function Game3:useConversion2(attacker, texts)
  texts = texts or {}
  local last = attacker.lastHitByType
  local chart = self.data and self.data.moves and self.data.moves.typeChart
  if not last or not chart then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  local options = {}
  for t = 0, Game3.TYPE_COUNT_LAST do
    if Game3.chartMul(chart, last, t, false) < 10 then
      options[#options + 1] = t
    end
  end
  if #options < 1 then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  local pick = options[(self:gbaRandom() % #options) + 1]
  attacker.type1, attacker.type2 = pick, pick
  texts[#texts + 1] = ("%s transformed into the %s type!"):format(
    attacker.name or "POKeMON", Game3.typeName(pick))
  return texts
end

-- Metronome, Sleep Talk and Mirror Move all resolve to another move and then
-- run it, so they hand back a move table for useMove to execute rather than
-- doing anything themselves.

-- atk9E_metronome: any move in the table except the forbidden list.
function Game3:rollMetronomeMove()
  local byId = self.data and self.data.moves and self.data.moves.byId
  if type(byId) ~= "table" then return nil end
  local pool = {}
  for id, row in pairs(byId) do
    if type(row) == "table" and self:copyableMove(id, true) then
      pool[#pool + 1] = id
    end
  end
  if #pool < 1 then return nil end
  table.sort(pool)
  local id = pool[(self:gbaRandom() % #pool) + 1]
  return { id = id, pp = 1, maxPp = 1, called = true }
end

-- atkA9_trychoosesleeptalkmove: only while asleep, and only from the user's
-- own moves, minus the forbidden list.
function Game3:rollSleepTalkMove(attacker)
  if not attacker or attacker.status ~= Game3.STATUS_SLP then return nil end
  local pool = {}
  for i = 1, #(attacker.moves or {}) do
    local mv = attacker.moves[i]
    if mv and self:copyableMove(mv.id, true) then pool[#pool + 1] = mv end
  end
  if #pool < 1 then return nil end
  local pick = pool[(self:gbaRandom() % #pool) + 1]
  return { id = pick.id, pp = 1, maxPp = 1, called = true }
end

-- Mirror Move replays the last move the target used.
function Game3:mirrorMoveOf(defender)
  local last = defender and defender.lastMove
  if not last or last == 0 or not self:copyableMove(last, true) then return nil end
  return { id = last, pp = 1, maxPp = 1, called = true }
end

-- atkB6_happinesstodamagecalculation: 10 * friendship / 25 for RETURN, and
-- the same off 255 for FRUSTRATION. Both cap at 102.
function Game3:friendshipPower(attacker, effect)
  local f = tonumber(attacker and attacker.friendship) or 0
  if effect == Game3.EFFECT_FRUSTRATION then f = 255 - f end
  return math.max(1, math.floor(10 * f / 25))
end

-- The weather healers: half in clear weather, two thirds in sun, a quarter in
-- anything else.
function Game3:weatherHealFraction()
  if self:weatherSuppressed() then return 2 end
  local w = self.battle and self.battle.weather
  if w == Game3.WEATHER_SUN then return nil end
  if w == nil or w == 0 then return 2 end
  return 4
end

function Game3:useWeatherHeal(attacker, texts)
  texts = texts or {}
  local maxHp = attacker.maxHp or 0
  if maxHp < 1 or (attacker.hp or 0) >= maxHp then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  local denom = self:weatherHealFraction()
  local heal
  if denom == nil then
    heal = math.max(1, math.floor(maxHp * 2 / 3))
  else
    heal = math.max(1, math.floor(maxHp / denom))
  end
  attacker.hp = math.min(maxHp, (attacker.hp or 0) + heal)
  texts[#texts + 1] = ("%s regained health!"):format(attacker.name or "POKeMON")
  return texts
end

-- BELLY DRUM: half the user's max HP for a maxed attack stage. Fails if that
-- would leave it with nothing.
function Game3:useBellyDrum(attacker, texts)
  texts = texts or {}
  local cost = math.max(1, math.floor((attacker.maxHp or 1) / 2))
  if (attacker.hp or 0) <= cost then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  attacker.hp = (attacker.hp or 0) - cost
  attacker.stages = attacker.stages or {}
  attacker.stages.atk = 6
  texts[#texts + 1] = ("%s cut its own HP and maximized its ATTACK!")
    :format(attacker.name or "POKeMON")
  return texts
end

-- MEAN LOOK sets STATUS2_ESCAPE_PREVENTION, which canRunFromBattle already
-- reads through mon.cannotEscape.
function Game3:useMeanLook(attacker, defender, texts)
  texts = texts or {}
  if not defender or defender.cannotEscape then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  defender.cannotEscape = true
  texts[#texts + 1] = ("%s can no longer escape!"):format(
    defender.name or "POKeMON")
  return texts
end

-- NIGHTMARE only takes on a sleeping target, and costs it a quarter a turn.
function Game3:useNightmare(attacker, defender, texts)
  texts = texts or {}
  if not defender or defender.status ~= Game3.STATUS_SLP or defender.nightmare then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  defender.nightmare = true
  texts[#texts + 1] = ("%s began having a NIGHTMARE!"):format(
    defender.name or "POKeMON")
  return texts
end

function Game3:nightmareResidual(mon)
  if not mon or (mon.hp or 0) <= 0 or not mon.nightmare then return {} end
  -- It lifts the moment the holder wakes.
  if mon.status ~= Game3.STATUS_SLP then
    mon.nightmare = nil
    return {}
  end
  local dmg = math.max(1, math.floor((mon.maxHp or 1) / 4))
  mon.hp = math.max(0, (mon.hp or 0) - dmg)
  local texts = { ("%s is locked in a NIGHTMARE!"):format(mon.name or "POKeMON") }
  if (mon.hp or 0) <= 0 then
    texts[#texts + 1] = ("%s fainted!"):format(mon.name or "POKeMON")
  end
  return texts
end

-- SAFEGUARD is a five turn side status that blocks new status conditions.
function Game3:useSafeguard(attacker, texts)
  texts = texts or {}
  local b = self.battle
  if not b then return texts end
  local key = self:isPlayerSide(attacker) and "safeguardTurns" or "safeguardTurnsFoe"
  if (b[key] or 0) > 0 then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  b[key] = Game3.SAFEGUARD_TURNS
  texts[#texts + 1] = ("%s's party is protected by SAFEGUARD!"):format(
    attacker.name or "POKeMON")
  return texts
end

function Game3:safeguardTurnsFor(mon)
  local b = self.battle
  if not b then return 0 end
  return (self:isPlayerSide(mon) and b.safeguardTurns or b.safeguardTurnsFoe) or 0
end

-- DREAM EATER only bites a sleeping target, and gives back half of what it
-- deals.
function Game3:dreamEaterDrain(attacker, defender, dmg, texts)
  if dmg <= 0 then return texts end
  local heal = math.max(1, math.floor(dmg / 2))
  attacker.hp = math.min(attacker.maxHp or heal, (attacker.hp or 0) + heal)
  texts = texts or {}
  texts[#texts + 1] = ("%s's dream was eaten!"):format(
    defender.name or "POKeMON")
  return texts
end

function Game3:useHaze(texts)
  texts = texts or {}
  local b = self.battle
  -- Not ipairs: in singles player2/enemy2 are nil, and ipairs would stop at
  -- the first hole and leave the far side's stages untouched.
  for _, mon in pairs({ b and b.player, b and b.player2,
      b and b.enemy, b and b.enemy2 }) do
    mon.stages = { atk = 0, def = 0, spa = 0, spd = 0, spe = 0, acc = 0, eva = 0 }
  end
  texts[#texts + 1] = "All stat changes were eliminated!"
  return texts
end

-- SIDE_STATUS_MIST for five turns. The engine already tracked the player's
-- side for GUARD SPEC, so the foe's side gets its own counter beside it.
function Game3:useMist(attacker, texts)
  texts = texts or {}
  local b = self.battle
  if not b then return texts end
  local key = self:isPlayerSide(attacker) and "mistTurns" or "mistTurnsFoe"
  if (b[key] or 0) > 0 then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  b[key] = Game3.MIST_TURNS
  texts[#texts + 1] = ("%s became shrouded in MIST!"):format(
    attacker.name or "POKeMON")
  return texts
end

function Game3:mistTurnsFor(mon)
  local b = self.battle
  if not b then return 0 end
  return (self:isPlayerSide(mon) and b.mistTurns or b.mistTurnsFoe) or 0
end

-- The slot holding the target's last used move, or nil. Both Disable and
-- Encore refuse when the move is not in the target's own four, or is spent.
-- atkAD_tryspiteppreduce: 2 to 5 PP off the target's last move, never more
-- than it has left.
function Game3:useSpite(attacker, defender, texts)
  texts = texts or {}
  local _, mv = self:lastMoveSlot(defender)
  if not mv or (mv.pp or 0) < 1 then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  local lost = math.min(mv.pp, 2 + (self:gbaRandom() % 4))
  mv.pp = mv.pp - lost
  texts[#texts + 1] = ("%s's %s was reduced by %d!"):format(
    defender.name or "POKeMON", self:moveName(mv.id), lost)
  return texts
end

-- TORMENT: never the same move twice running.
function Game3:useTorment(attacker, defender, texts)
  texts = texts or {}
  if not defender or defender.tormented then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  defender.tormented = true
  texts[#texts + 1] = ("%s was subjected to TORMENT!"):format(
    defender.name or "POKeMON")
  return texts
end

-- TAUNT: two turns of damaging moves only.
function Game3:useTaunt(attacker, defender, texts)
  texts = texts or {}
  if not defender or (defender.tauntTurns or 0) > 0 then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  defender.tauntTurns = Game3.TAUNT_TURNS
  texts[#texts + 1] = ("%s fell for the TAUNT!"):format(
    defender.name or "POKeMON")
  return texts
end

-- GRUDGE: whatever lands the killing blow loses all of that move's PP.
function Game3:useGrudge(attacker, texts)
  texts = texts or {}
  attacker.grudge = true
  texts[#texts + 1] = ("%s wants its target to bear a GRUDGE!"):format(
    attacker.name or "POKeMON")
  return texts
end

function Game3:tryGrudge(defender, attacker, move, texts)
  if not defender or (defender.hp or 0) > 0 or not defender.grudge then
    return texts
  end
  defender.grudge = nil
  if not (attacker and move) then return texts end
  local slot = self:moveSlotOf(attacker, move)
  local mv = slot and attacker.moves[slot]
  if not mv then return texts end
  mv.pp = 0
  texts = texts or {}
  texts[#texts + 1] = ("%s's %s lost all its PP!"):format(
    attacker.name or "POKeMON", self:moveName(mv.id))
  return texts
end

-- SPIKES stacks three deep. Entry damage is maxHP / ((5 - layers) * 2), so one
-- layer is an eighth, two a sixth and three a quarter.
function Game3:useSpikes(attacker, texts)
  texts = texts or {}
  local b = self.battle
  if not b then return texts end
  local key = self:isPlayerSide(attacker) and "spikesFoe" or "spikesPlayer"
  local n = b[key] or 0
  if n >= Game3.SPIKES_MAX then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  b[key] = n + 1
  texts[#texts + 1] = "Spikes were scattered all around the foe's side!"
  return texts
end

function Game3:spikeLayersFor(mon)
  local b = self.battle
  if not b then return 0 end
  return (self:isPlayerSide(mon) and b.spikesPlayer or b.spikesFoe) or 0
end

-- Flying types and Levitate walk over them.
function Game3:applySpikes(mon)
  if not mon or (mon.hp or 0) <= 0 then return {} end
  local layers = self:spikeLayersFor(mon)
  if layers < 1 then return {} end
  if Game3.hasType(mon, Game3.TYPE_FLYING) then return {} end
  if self:hasAbility(mon, Game3.ABILITY_LEVITATE) then return {} end
  local dmg = math.max(1, math.floor((mon.maxHp or 1) / ((5 - layers) * 2)))
  mon.hp = math.max(0, (mon.hp or 0) - dmg)
  local texts = { ("%s is hurt by SPIKES!"):format(mon.name or "POKeMON") }
  if (mon.hp or 0) <= 0 then
    texts[#texts + 1] = ("%s fainted!"):format(mon.name or "POKeMON")
  end
  return texts
end

-- rapidspinfree: wrap, Leech Seed and the user's own side's Spikes.
function Game3:rapidSpinFree(attacker, texts)
  texts = texts or {}
  if attacker.wrapped then
    attacker.wrapped = nil
    attacker.wrappedMoveName = nil
    attacker.wrappedBy = nil
    texts[#texts + 1] = ("%s got free!"):format(attacker.name or "POKeMON")
  end
  if attacker.leechSeed then
    attacker.leechSeed = nil
    attacker.leechSeedSlot = nil
    attacker.leechSeedFrom = nil
    texts[#texts + 1] = ("%s shed LEECH SEED!"):format(attacker.name or "POKeMON")
  end
  local b = self.battle
  local key = self:isPlayerSide(attacker) and "spikesPlayer" or "spikesFoe"
  if b and (b[key] or 0) > 0 then
    b[key] = nil
    texts[#texts + 1] = ("%s blew away SPIKES!"):format(attacker.name or "POKeMON")
  end
  return texts
end

-- MEMENTO: the user faints to drop the target two stages of each attack.
function Game3:useMemento(attacker, defender, texts)
  texts = texts or {}
  if not defender or defender.substitute then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  attacker.hp = 0
  texts[#texts + 1] = self:dropStat(defender, "atk", "ATTACK", 2)
  texts[#texts + 1] = self:dropStat(defender, "spa", "SP. ATK", 2)
  texts[#texts + 1] = ("%s fainted!"):format(attacker.name or "POKeMON")
  return texts
end

-- cureifburnedparalysedorpoisoned. Sleep and freeze are not on the list.
function Game3:useRefresh(attacker, texts)
  texts = texts or {}
  local st = attacker.status
  if st ~= Game3.STATUS_BRN and not Game3.isPoisonStatus(st)
      and st ~= Game3.STATUS_PAR then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  attacker.status = nil
  attacker.toxicCounter = nil
  texts[#texts + 1] = ("%s's status returned to normal!"):format(
    attacker.name or "POKeMON")
  return texts
end

-- removelightscreenreflect runs before the damage calc, so Brick Break takes
-- the screens down even when the hit itself is resisted.
function Game3:breakScreens(defender, texts)
  texts = texts or {}
  local b = self.battle
  local screens = b and b.screens
  local side = screens and screens[self:screenSide(defender)]
  if type(side) == "table" then
    local shattered = false
    if side.reflect then
      side.reflect = nil
      shattered = true
      texts[#texts + 1] = "REFLECT wore off!"
    end
    if side.lightScreen then
      side.lightScreen = nil
      shattered = true
      texts[#texts + 1] = "LIGHT SCREEN wore off!"
    end
    -- Wave-4: Brick Break screen-shatter path (Move_BRICK_BREAK choosetwoturnanim).
    if shattered and b then b.brickBreakShatter = true end
  end
  return texts
end

-- MOVE_EFFECT_STEAL_ITEM: only when the thief is empty-handed and the target
-- is holding something. Sticky Hold refuses.
function Game3:stealItem(attacker, defender, texts)
  texts = texts or {}
  local item = tonumber(defender and defender.item) or 0
  if item == 0 or (tonumber(attacker.item) or 0) ~= 0 then return texts end
  if self:hasAbility(defender, Game3.ABILITY_STICKY_HOLD) then
    texts[#texts + 1] = ("%s's %s made it ineffective!"):format(
      defender.name or "POKeMON", Game3.abilityName(Game3.ABILITY_STICKY_HOLD))
    return texts
  end
  defender.item = 0
  attacker.item = item
  texts[#texts + 1] = ("%s stole %s's %s!"):format(
    attacker.name or "POKeMON", defender.name or "POKeMON", self:itemName(item))
  return texts
end

-- settypetoenvironment. Every battle terrain outside the special fields maps
-- to NORMAL in sTerrainToType, which is what an ordinary battle uses.
function Game3:useCamouflage(attacker, texts)
  texts = texts or {}
  if attacker.type1 == Game3.TYPE_NORMAL and attacker.type2 == Game3.TYPE_NORMAL then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  attacker.type1, attacker.type2 = Game3.TYPE_NORMAL, Game3.TYPE_NORMAL
  texts[#texts + 1] = ("%s transformed into the %s type!"):format(
    attacker.name or "POKeMON", Game3.typeName(Game3.TYPE_NORMAL))
  return texts
end

-- SWAGGER raises the target's ATTACK two stages and then confuses it;
-- FLATTER does the same with one stage of SP. ATK. Both fail outright only
-- when the target is already confused and the stat is maxed.
function Game3:useSwaggerLike(attacker, defender, effect, texts)
  texts = texts or {}
  local stat, label, amount
  if effect == Game3.EFFECT_FLATTER then
    stat, label, amount = "spa", "SP. ATK", 1
  else
    stat, label, amount = "atk", "ATTACK", 2
  end
  local st = (defender and defender.stages) or {}
  if not defender or ((defender.confuseTurns or 0) > 0 and (st[stat] or 0) >= 6) then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  texts[#texts + 1] = self:raiseStat(defender, stat, amount, label)
  local line = self:applyConfuse(defender)
  if line then texts[#texts + 1] = line end
  return texts
end

-- TICKLE drops ATTACK and DEFENSE by one each, and fails only when neither
-- can fall any further.
function Game3:useTickle(attacker, defender, texts)
  texts = texts or {}
  local st = (defender and defender.stages) or {}
  if not defender or ((st.atk or 0) <= -6 and (st.def or 0) <= -6) then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  texts[#texts + 1] = self:dropStat(defender, "atk", "ATTACK", 1)
  texts[#texts + 1] = self:dropStat(defender, "def", "DEFENSE", 1)
  return texts
end

-- setminimize, then EVASION +1. The flag is what makes Stomp hit double.
function Game3:useMinimize(attacker, texts)
  texts = texts or {}
  attacker.minimized = true
  texts[#texts + 1] = self:raiseStat(attacker, "eva", 1, "EVASION")
  return texts
end

-- TEETER DANCE confuses everything on the field but the user.
function Game3:useTeeterDance(attacker, texts)
  texts = texts or {}
  local b = self.battle
  if not b then return texts end
  local any = false
  for _, mon in pairs({ b.player, b.player2, b.enemy, b.enemy2 }) do
    if mon ~= attacker and (mon.hp or 0) > 0 and not mon.substitute then
      local line = self:applyConfuse(mon)
      if line then
        texts[#texts + 1] = line
        any = true
      end
    end
  end
  if not any then texts[#texts + 1] = "But it failed!" end
  return texts
end

-- Smelling Salts doubles against a paralysed target, and then cures it.
function Game3:smellingSaltMultiplier(defender)
  if defender and defender.status == Game3.STATUS_PAR then return 2 end
  return 1
end

-- MOVE_EFFECT_PAYDAY banks level * 5 per hit, handed over when the battle is
-- won. gPaydayMoney saturates at 0xFFFF rather than wrapping.
function Game3:addPayday(attacker)
  local b = self.battle
  if not b then return end
  b.payday = math.min(0xFFFF,
    (b.payday or 0) + (tonumber(attacker.level) or 0) * 5)
end

function Game3:collectPayday()
  local b = self.battle
  local amount = (b and b.payday) or 0
  if amount < 1 then return nil end
  b.payday = nil
  self.money = (self.money or 0) + amount
  if Game3.MAX_MONEY then
    self.money = math.min(Game3.MAX_MONEY, self.money)
  end
  return ("You picked up $%d!"):format(amount)
end

-- Jump Kick's crash: half the damage it would have dealt, at least 1, and
-- never more than half the target's max HP.
function Game3:crashDamage(attacker, defender, move, texts)
  texts = texts or {}
  local result = self:dealDamage(attacker, defender, move, true) or {}
  if (result.mul or 0) <= 0 then return texts end
  local dmg = math.max(1, math.floor((result.dmg or 0) / 2))
  dmg = math.min(dmg, math.max(1, math.floor((defender.maxHp or 2) / 2)))
  attacker.hp = math.max(0, (attacker.hp or 0) - dmg)
  texts[#texts + 1] = ("%s kept going and crashed!"):format(
    attacker.name or "POKeMON")
  if (attacker.hp or 0) <= 0 then
    texts[#texts + 1] = ("%s fainted!"):format(attacker.name or "POKeMON")
  end
  return texts
end

-- atkB3_rolloutdamagecalculation. The timer counts 5 down to 0 and the power
-- doubles on the way, so a full run is 30 / 60 / 120 / 240 / 480. DEFENSE CURL
-- doubles it again.
function Game3:rolloutPower(attacker, move, peek)
  local base = move.power or 0
  local timer = attacker.rolloutTimer or 0
  if timer < 1 then timer = Game3.ROLLOUT_TURNS end
  timer = timer - 1
  local power = base
  for _ = 1, (Game3.ROLLOUT_TURNS - timer) - 1 do
    power = power * 2
  end
  if attacker.defenseCurl then power = power * 2 end
  if peek then return power end
  if (attacker.rolloutTimer or 0) < 1 then attacker.rolloutMove = move end
  attacker.rolloutTimer = timer
  if timer <= 0 then
    attacker.rolloutTimer = nil
    attacker.rolloutMove = nil
  end
  return power
end

-- atkB5_furycuttercalc: the counter climbs to 5 and the power doubles with it,
-- so 10 / 20 / 40 / 80 / 160. A miss puts it back to nothing.
function Game3:furyCutterPower(attacker, move, peek)
  local n = math.min(Game3.FURY_CUTTER_MAX, (attacker.furyCutter or 0) + 1)
  if not peek then attacker.furyCutter = n end
  local power = move.power or 0
  for _ = 2, n do power = power * 2 end
  return power
end

-- atkB7_presentdamagecalculation: a byte roll picks 40, 80 or 120 power, and
-- the top slice heals the target a quarter of its max HP instead.
function Game3:presentRoll()
  local r = self:gbaRandom() % 256
  if r < 102 then return 40 end
  if r < 178 then return 80 end
  if r < 204 then return 120 end
  return nil
end

function Game3:usePresentHeal(defender, texts)
  texts = texts or {}
  local maxHp = defender.maxHp or 0
  if maxHp < 1 or (defender.hp or 0) >= maxHp then
    texts[#texts + 1] = ("%s's HP is full!"):format(defender.name or "POKeMON")
    return texts
  end
  local heal = math.max(1, math.floor(maxHp / 4))
  defender.hp = math.min(maxHp, (defender.hp or 0) + heal)
  texts[#texts + 1] = ("%s regained health!"):format(defender.name or "POKeMON")
  return texts
end

-- atkD9_scaledamagebyhealthratio: Eruption and Water Spout fall off with the
-- user's own HP.
function Game3:eruptionPower(attacker, move)
  local maxHp = attacker.maxHp or 1
  return math.max(1,
    math.floor((attacker.hp or 0) * (move.power or 0) / maxHp))
end

-- Triple Kick adds ten power a hit, so 10 / 20 / 30 across its three.
function Game3:tripleKickPower(move)
  return Game3.TRIPLE_KICK_STEP * math.max(1, move._hit or 1)
end

-- atkC4_trydobeatup walks the user's own party and takes one swing per member
-- that is alive, awake and not an egg. The enemy side's roster is the trainer
-- party spec, which carries a species and a level but no live HP.
function Game3:beatUpMembers(attacker)
  local b = self.battle
  local party = self:isPlayerSide(attacker) and self.party
    or (b and b.trainerParty)
  local out = {}
  for i = 1, #(party or {}) do
    local p = party[i]
    local hp = p and p.hp
    if p and (p.species or 0) > 0 and not p.isEgg and not p.status
        and (hp == nil or hp > 0) then
      out[#out + 1] = p
    end
  end
  if #out < 1 then out[1] = attacker end
  return out
end

function Game3:beatUpCount(attacker)
  return #self:beatUpMembers(attacker)
end

-- Each swing uses that member's base ATTACK and level against the target's
-- base DEFENSE. No stages, no STAB, no roll.
function Game3:beatUpDamage(attacker, defender, move)
  local members = self:beatUpMembers(attacker)
  local mon = members[math.max(1, move._hit or 1)] or attacker
  local atkRow = self:speciesRow(mon.species)
  local defRow = self:speciesRow(defender.species)
  local baseAtk = (atkRow and atkRow.atk) or 1
  local baseDef = math.max(1, (defRow and defRow.def) or 1)
  local dmg = baseAtk * (move.power or 10)
  dmg = dmg * math.floor((mon.level or 1) * 2 / 5 + 2)
  dmg = math.floor(dmg / baseDef)
  return math.floor(dmg / 50) + 2
end

-- atkBD_copyfoestats: every stage, straight across.
function Game3:usePsychUp(attacker, defender, texts)
  texts = texts or {}
  local st = (defender and defender.stages) or {}
  attacker.stages = attacker.stages or {}
  for _, k in ipairs({ "atk", "def", "spa", "spd", "spe", "acc", "eva" }) do
    attacker.stages[k] = st[k] or 0
  end
  texts[#texts + 1] = ("%s copied %s's stat changes!"):format(
    attacker.name or "POKeMON", (defender and defender.name) or "POKeMON")
  return texts
end

-- atkDA_tryswapabilities. Two blanks fail, and WONDER GUARD is not for trading.
function Game3:useSkillSwap(attacker, defender, texts)
  texts = texts or {}
  local a, d = attacker.ability or 0, (defender and defender.ability) or 0
  if not defender or (a == 0 and d == 0)
      or a == Game3.ABILITY_WONDER_GUARD or d == Game3.ABILITY_WONDER_GUARD then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  attacker.ability, defender.ability = d, a
  texts[#texts + 1] = ("%s swapped abilities with its target!"):format(
    attacker.name or "POKeMON")
  return texts
end

-- atkD3_trycopyability: one way, and never WONDER GUARD.
function Game3:useRolePlay(attacker, defender, texts)
  texts = texts or {}
  local d = (defender and defender.ability) or 0
  if d == 0 or d == Game3.ABILITY_WONDER_GUARD then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  attacker.ability = d
  texts[#texts + 1] = ("%s copied %s's %s!"):format(
    attacker.name or "POKeMON", defender.name or "POKeMON",
    Game3.abilityName(d))
  return texts
end

-- atkD2_tryswapitems. Two empty hands fail, and STICKY HOLD will not let go.
function Game3:useTrick(attacker, defender, texts)
  texts = texts or {}
  local a = tonumber(attacker.item) or 0
  local d = tonumber(defender and defender.item) or 0
  if not defender or defender.substitute or (a == 0 and d == 0) then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  if self:hasAbility(defender, Game3.ABILITY_STICKY_HOLD) then
    texts[#texts + 1] = ("%s's %s made it ineffective!"):format(
      defender.name or "POKeMON", Game3.abilityName(Game3.ABILITY_STICKY_HOLD))
    return texts
  end
  attacker.item, defender.item = d, a
  texts[#texts + 1] = ("%s switched items with its target!"):format(
    attacker.name or "POKeMON")
  return texts
end

-- atkEA_tryrecycleitem: the item this mon used up earlier, and only if its
-- hands are empty now.
function Game3:useRecycle(attacker, texts)
  texts = texts or {}
  local used = tonumber(attacker.usedItem) or 0
  if used == 0 or (tonumber(attacker.item) or 0) ~= 0 then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  attacker.usedItem = nil
  attacker.item = used
  texts[#texts + 1] = ("%s found one %s!"):format(
    attacker.name or "POKeMON", self:itemName(used))
  return texts
end

-- atkD6_doubledamagedealtifdamaged: REVENGE hits twice as hard when this
-- target already got a hit in this turn.
function Game3:revengeMultiplier(attacker, defender)
  if not (attacker and defender) then return 1 end
  if attacker.counterPhysicalFrom == defender
      and (attacker.counterPhysical or 0) > 0 then
    return 2
  end
  if attacker.counterSpecialFrom == defender
      and (attacker.counterSpecial or 0) > 0 then
    return 2
  end
  return 1
end

-- atkD7_setyawn: two turns, then sleep. Refused against anything that already
-- has a status, and against the abilities that turn sleep away.
function Game3:useYawn(attacker, defender, texts)
  texts = texts or {}
  if not defender or defender.substitute or defender.status
      or (defender.yawnTurns or 0) > 0 then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  if self:hasAbility(defender, Game3.ABILITY_VITAL_SPIRIT)
      or self:hasAbility(defender, Game3.ABILITY_INSOMNIA) then
    texts[#texts + 1] = ("%s's %s made it ineffective!"):format(
      defender.name, Game3.abilityName(defender.ability))
    return texts
  end
  if self:safeguardTurnsFor(defender) > 0 then
    texts[#texts + 1] = ("%s is protected by SAFEGUARD!"):format(defender.name)
    return texts
  end
  defender.yawnTurns = Game3.YAWN_TURNS
  texts[#texts + 1] = ("%s made %s drowsy!"):format(
    attacker.name or "POKeMON", defender.name or "POKeMON")
  return texts
end

function Game3:tickYawn(mon)
  if not mon or (mon.yawnTurns or 0) < 1 then return {} end
  mon.yawnTurns = mon.yawnTurns - 1
  if mon.yawnTurns > 0 then return {} end
  mon.yawnTurns = nil
  local line = self:applyStatus(mon, Game3.STATUS_SLP)
  return line and { line } or {}
end

-- CURSE splits on the user's own type: a GHOST pays half its HP to lay one,
-- anything else trades SPEED for ATTACK and DEFENSE.
function Game3:useCurse(attacker, defender, texts)
  texts = texts or {}
  if Game3.hasType(attacker, Game3.TYPE_GHOST) then
    if not defender or defender.cursed then
      texts[#texts + 1] = "But it failed!"
      return texts
    end
    defender.cursed = true
    local cost = math.max(1, math.floor((attacker.maxHp or 2) / 2))
    attacker.hp = math.max(0, (attacker.hp or 0) - cost)
    texts[#texts + 1] = ("%s cut its own HP and laid a CURSE on %s!"):format(
      attacker.name or "POKeMON", defender.name or "POKeMON")
    if (attacker.hp or 0) <= 0 then
      texts[#texts + 1] = ("%s fainted!"):format(attacker.name or "POKeMON")
    end
    return texts
  end
  local st = attacker.stages or {}
  if (st.spe or 0) <= -6 and (st.atk or 0) >= 6 and (st.def or 0) >= 6 then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  texts[#texts + 1] = self:dropStat(attacker, "spe", "SPEED", 1, true)
  texts[#texts + 1] = self:raiseStat(attacker, "atk", 1, "ATTACK")
  texts[#texts + 1] = self:raiseStat(attacker, "def", 1, "DEFENSE")
  return texts
end

function Game3:curseResidual(mon)
  if not mon or (mon.hp or 0) <= 0 or not mon.cursed then return {} end
  local dmg = math.max(1, math.floor((mon.maxHp or 1) / 4))
  mon.hp = math.max(0, (mon.hp or 0) - dmg)
  local texts = { ("%s is afflicted by the CURSE!"):format(mon.name or "POKeMON") }
  if (mon.hp or 0) <= 0 then
    texts[#texts + 1] = ("%s fainted!"):format(mon.name or "POKeMON")
  end
  return texts
end

-- SUPERPOWER's rider is AFFECTS_USER | CERTAIN, so it lands whatever the roll.
function Game3:superpowerDrop(attacker, texts)
  texts = texts or {}
  texts[#texts + 1] = self:dropStat(attacker, "atk", "ATTACK", 1, true)
  texts[#texts + 1] = self:dropStat(attacker, "def", "DEFENSE", 1, true)
  return texts
end

-- MOVE_EFFECT_ALL_STATS_UP: one stage of each of the five.
function Game3:allStatsUp(attacker, texts)
  texts = texts or {}
  for _, spec in ipairs({ { "atk", "ATTACK" }, { "def", "DEFENSE" },
    { "spe", "SPEED" }, { "spa", "SP. ATK" }, { "spd", "SP. DEF" } }) do
    texts[#texts + 1] = self:raiseStat(attacker, spec[1], 1, spec[2])
  end
  return texts
end

-- atkE4_getsecretpowereffect maps gBattleEnvironment to a rider. Everything
-- outside the special fields -- which is what an ordinary battle is -- takes
-- the default, MOVE_EFFECT_PARALYSIS.
function Game3:secretPowerStatus()
  return Game3.STATUS_PAR
end

-- atk85_stockpile: three deep and no further.
function Game3:useStockpile(attacker, texts)
  texts = texts or {}
  local n = attacker.stockpile or 0
  if n >= Game3.STOCKPILE_MAX then
    texts[#texts + 1] = ("%s can't stockpile any more!"):format(
      attacker.name or "POKeMON")
    return texts
  end
  attacker.stockpile = n + 1
  texts[#texts + 1] = ("%s stockpiled %d!"):format(
    attacker.name or "POKeMON", attacker.stockpile)
  return texts
end

-- atk86_stockpiletobasedamage: the base damage times whatever was banked, and
-- the bank empties either way.
function Game3:spitUpMultiplier(attacker)
  return attacker.stockpile or 0
end

-- atk87_stockpiletohpheal: maxHP / (1 << (3 - counter)), so a quarter, a half
-- or the lot.
function Game3:useSwallow(attacker, texts)
  texts = texts or {}
  local n = attacker.stockpile or 0
  local maxHp = attacker.maxHp or 0
  if n < 1 then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  attacker.stockpile = nil
  if (attacker.hp or 0) >= maxHp then
    texts[#texts + 1] = ("%s's HP is full!"):format(attacker.name or "POKeMON")
    return texts
  end
  local heal = math.max(1, math.floor(maxHp / (2 ^ (Game3.STOCKPILE_MAX - n))))
  attacker.hp = math.min(maxHp, (attacker.hp or 0) + heal)
  texts[#texts + 1] = ("%s regained health!"):format(attacker.name or "POKeMON")
  return texts
end

-- atkC3_trysetfutureattack: the damage is worked out now and lands three
-- turns later, whoever is standing there by then.
function Game3:useFutureSight(attacker, defender, move, texts)
  texts = texts or {}
  if not defender or (defender.futureTurns or 0) > 0 then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  local result = self:dealDamage(attacker, defender, move, true) or {}
  defender.futureTurns = Game3.FUTURE_SIGHT_TURNS
  defender.futureDamage = math.max(1, result.dmg or 1)
  defender.futureName = move.name or "FUTURE SIGHT"
  texts[#texts + 1] = ("%s foresaw an attack!"):format(
    attacker.name or "POKeMON")
  return texts
end

function Game3:tickFutureSight(mon)
  if not mon or (mon.futureTurns or 0) < 1 then return {} end
  mon.futureTurns = mon.futureTurns - 1
  if mon.futureTurns > 0 then return {} end
  local dmg = mon.futureDamage or 1
  mon.futureTurns, mon.futureDamage = nil, nil
  local name = mon.futureName or "FUTURE SIGHT"
  mon.futureName = nil
  if (mon.hp or 0) <= 0 then return {} end
  mon.hp = math.max(0, (mon.hp or 0) - dmg)
  local texts = { ("%s took the %s attack!"):format(mon.name or "POKeMON", name) }
  if (mon.hp or 0) <= 0 then
    texts[#texts + 1] = ("%s fainted!"):format(mon.name or "POKeMON")
  end
  return texts
end

-- atkD4_trywish: two turns, then half the max HP of whoever holds the slot.
function Game3:useWish(attacker, texts)
  texts = texts or {}
  if (attacker.wishTurns or 0) > 0 then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  attacker.wishTurns = Game3.WISH_TURNS
  texts[#texts + 1] = ("%s made a wish!"):format(attacker.name or "POKeMON")
  return texts
end

function Game3:tickWish(mon)
  if not mon or (mon.wishTurns or 0) < 1 then return {} end
  mon.wishTurns = mon.wishTurns - 1
  if mon.wishTurns > 0 then return {} end
  mon.wishTurns = nil
  if (mon.hp or 0) <= 0 then return {} end
  local maxHp = mon.maxHp or 0
  if (mon.hp or 0) >= maxHp then
    return { ("%s's HP is full!"):format(mon.name or "POKeMON") }
  end
  local heal = math.max(1, math.floor(maxHp / 2))
  mon.hp = math.min(maxHp, (mon.hp or 0) + heal)
  return { ("%s's wish came true!"):format(mon.name or "POKeMON"),
    ("%s regained health!"):format(mon.name or "POKeMON") }
end

-- atkCB_setcharge: STATUS3_CHARGED_UP for two turns, doubling one ELECTRIC
-- move on the way past.
function Game3:useCharge(attacker, texts)
  texts = texts or {}
  attacker.chargeTurns = Game3.CHARGE_TURNS
  texts[#texts + 1] = ("%s began charging power!"):format(
    attacker.name or "POKeMON")
  return texts
end

function Game3:chargeMultiplier(attacker, moveType)
  if (attacker.chargeTurns or 0) > 0 and moveType == Game3.TYPE_ELECTRIC then
    return 2
  end
  return 1
end

-- atkD1_trysethelpinghand only takes in a double battle, and only when
-- neither partner has already offered.
function Game3:useHelpingHand(attacker, texts)
  texts = texts or {}
  local partner = self:partnerOf(attacker)
  local b = self.battle
  if not (b and b.doubles) or not Game3.aliveMon(partner)
      or attacker.helpingHand or partner.helpingHand then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  partner.helpingHand = true
  texts[#texts + 1] = ("%s is ready to help %s!"):format(
    attacker.name or "POKeMON", partner.name or "POKeMON")
  return texts
end

function Game3:partnerOf(mon)
  local b = self.battle
  if not b then return nil end
  if mon == b.player then return b.player2 end
  if mon == b.player2 then return b.player end
  if mon == b.enemy then return b.enemy2 end
  if mon == b.enemy2 then return b.enemy end
  return nil
end

-- atkCA_setforcedtarget. Only doubles has another target to pull off.
function Game3:useFollowMe(attacker, texts)
  texts = texts or {}
  local b = self.battle
  if not (b and b.doubles) then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  b.forcedTarget = attacker
  texts[#texts + 1] = ("%s became the center of attention!"):format(
    attacker.name or "POKeMON")
  return texts
end

-- atkDB_tryimprison: every move the user knows is off the table for the other
-- side, and it only takes if there is at least one in common.
function Game3:useImprison(attacker, texts)
  texts = texts or {}
  if attacker.imprisoning then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  local shared = false
  for _, foe in ipairs(self:foesOf(attacker)) do
    if foe then
      for i = 1, #(attacker.moves or {}) do
        local mine = attacker.moves[i]
        for j = 1, #(foe.moves or {}) do
          local theirs = foe.moves[j]
          if mine and theirs and (mine.id or 0) > 0 and mine.id == theirs.id then
            shared = true
          end
        end
      end
    end
  end
  if not shared then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  attacker.imprisoning = true
  texts[#texts + 1] = ("%s sealed the opponent's move(s)!"):format(
    attacker.name or "POKeMON")
  return texts
end

function Game3:imprisonedMove(mon, move)
  if not (mon and move and (move.id or 0) > 0) then return false end
  for _, foe in ipairs(self:foesOf(mon)) do
    if foe and foe.imprisoning and (foe.hp or 0) > 0 then
      for i = 1, #(foe.moves or {}) do
        local mv = foe.moves[i]
        if mv and mv.id == move.id then return true end
      end
    end
  end
  return false
end

-- atkDF_trysetmagiccoat / atkE0_trysetsnatch both fail when the user is last
-- to act, since there is nothing left to catch.
function Game3:useMagicCoat(attacker, texts)
  texts = texts or {}
  attacker.magicCoat = true
  texts[#texts + 1] = ("%s shrouded itself with MAGIC COAT!"):format(
    attacker.name or "POKeMON")
  return texts
end

-- Whoever on the other side is lying in wait for a snatchable move.
-- The ROM runs the bounced or stolen move properly, attackstring and all.
-- Its ppreduce already came off the original user, so the echo works on a
-- copy and spends nothing.
function Game3:echoMove(move)
  local copy = {}
  for k, v in pairs(move or {}) do copy[k] = v end
  copy.pp = math.max(1, copy.pp or 1)
  copy._pursuitSwitch = nil
  return copy
end

function Game3:snatcherOf(attacker, move)
  if not Game3.snatchable(move) then return nil end
  for _, foe in ipairs(self:foesOf(attacker)) do
    if foe and foe.snatch and (foe.hp or 0) > 0 then return foe end
  end
  return nil
end

function Game3:useSnatch(attacker, texts)
  texts = texts or {}
  attacker.snatch = true
  texts[#texts + 1] = ("%s waits for a target to make a move!"):format(
    attacker.name or "POKeMON")
  return texts
end

-- atkDE_assistattackselect draws from the rest of the party's movesets, minus
-- the moves the copiers are never allowed to pull.
function Game3:assistPool(attacker)
  local party = self:isPlayerSide(attacker) and self.party or nil
  local pool = {}
  for i = 1, #(party or {}) do
    local mon = party[i]
    if mon and mon ~= attacker and (mon.species or 0) > 0 and not mon.isEgg then
      for j = 1, #(mon.moves or {}) do
        local mv = mon.moves[j]
        if mv and (mv.id or 0) > 0 and self:copyableMove(mv.id, true) then
          pool[#pool + 1] = mv.id
        end
      end
    end
  end
  return pool
end

function Game3:rollAssistMove(attacker)
  local pool = self:assistPool(attacker)
  if #pool < 1 then return nil end
  return self:copyMove(pool[(self:gbaRandom() % #pool) + 1])
end

-- BATON PASS hands the whole of status2 and every stat stage to whoever comes
-- in, which is the one switch that does not wipe them.
function Game3:useBatonPass(attacker, texts)
  texts = texts or {}
  local b = self.battle
  if not b or not self:hasSwitchTarget() then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  b.batonPass = {
    stages = attacker.stages,
    confuseTurns = attacker.confuseTurns,
    leechSeed = attacker.leechSeed,
    leechSeedFrom = attacker.leechSeedFrom,
    substitute = attacker.substitute,
    substituteHp = attacker.substituteHp,
    focusEnergy = attacker.focusEnergy,
    perishSong = attacker.perishSong,
    cursed = attacker.cursed,
    rooted = attacker.rooted,
    cannotEscape = attacker.cannotEscape,
  }
  b.kind = "party"
  b.mustSwitch = true
  b.switchSlot = self:isPlayerSide(attacker) and "player" or nil
  texts[#texts + 1] = ("%s passed on its effects!"):format(
    attacker.name or "POKeMON")
  return texts
end

function Game3:hasSwitchTarget()
  local b = self.battle
  for i = 1, #(self.party or {}) do
    local mon = self.party[i]
    if mon and (mon.hp or 0) > 0 and not mon.isEgg
        and mon ~= (b and b.player) and mon ~= (b and b.player2) then
      return true
    end
  end
  return false
end

-- Whatever Baton Pass banked lands on the incoming mon, after switchTo has
-- cleared everything else.
function Game3:applyBatonPass(mon)
  local b = self.battle
  local pass = b and b.batonPass
  if not (mon and pass) then return end
  b.batonPass = nil
  mon.stages = pass.stages or mon.stages
  mon.confuseTurns = pass.confuseTurns
  mon.leechSeed = pass.leechSeed
  mon.leechSeedFrom = pass.leechSeedFrom
  mon.substitute = pass.substitute
  mon.substituteHp = pass.substituteHp
  mon.focusEnergy = pass.focusEnergy
  mon.perishSong = pass.perishSong
  mon.cursed = pass.cursed
  mon.rooted = pass.rooted
  mon.cannotEscape = pass.cannotEscape
end

-- BattleScript_ActionSwitch sets sDMG_MULTIPLIER to 2 and then runs the
-- pursuer's move before the swap, marking it as having acted this turn.
function Game3:pursuitOnSwitch(outgoing, queue)
  local b = self.battle
  if not (b and outgoing and Game3.aliveMon(b.enemy)) then return false end
  if (outgoing.hp or 0) <= 0 then return false end
  local move = self:pickEnemyMove(b.enemy)
  if not move or self:moveEffect(move) ~= Game3.EFFECT_PURSUIT then
    -- Not a pursuer: hold the pick so the turn uses this move, not a reroll.
    b.enemyPick, b.enemyPickMon = move, b.enemy
    return false
  end
  move._pursuitSwitch = true
  local texts = self:useMove(b.enemy, outgoing, move)
  for i = 1, #texts do queue[#queue + 1] = texts[i] end
  move._pursuitSwitch = nil
  return true
end

function Game3:lastMoveSlot(mon)
  local last = mon and mon.lastMove
  if not last or last == 0 then return nil end
  for i = 1, #(mon.moves or {}) do
    local mv = mon.moves[i]
    if mv and mv.id == last then
      if (mv.pp or 0) <= 0 then return nil end
      return i, mv
    end
  end
  return nil
end

function Game3:useDisable(attacker, defender, texts)
  texts = texts or {}
  local _, mv = self:lastMoveSlot(defender)
  if not mv or defender.disabledMove then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  defender.disabledMove = mv.id
  defender.disableTurns = Game3.DISABLE_MIN_TURNS + (self:gbaRandom() % 4)
  texts[#texts + 1] = ("%s's %s was disabled!"):format(
    defender.name or "POKeMON", self:moveName(mv.id))
  return texts
end

-- Struggle, Encore and Mirror Move cannot be encored.
Game3.ENCORE_BANNED = { [165] = true, [227] = true, [119] = true }

function Game3:useEncore(attacker, defender, texts)
  texts = texts or {}
  local slot, mv = self:lastMoveSlot(defender)
  if not mv or defender.encoreMove or Game3.ENCORE_BANNED[mv.id] then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  defender.encoreMove = mv
  defender.encoreSlot = slot
  defender.encoreTurns = Game3.ENCORE_MIN_TURNS + (self:gbaRandom() % 4)
  texts[#texts + 1] = ("%s got an ENCORE!"):format(defender.name or "POKeMON")
  return texts
end

-- STATUS3_ALWAYS_HITS_TURN(2) on the target, remembering who gets the sure
-- hit -- it is the attacker's moves that stop missing, not everyone's.
function Game3:useLockOn(attacker, defender, texts)
  texts = texts or {}
  defender.sureHitFrom = attacker
  defender.sureHitTurns = Game3.LOCK_ON_TURNS
  texts[#texts + 1] = ("%s took aim at %s!"):format(
    attacker.name or "POKeMON", defender.name or "POKeMON")
  return texts
end

function Game3:useDestinyBond(attacker, texts)
  texts = texts or {}
  attacker.destinyBond = true
  texts[#texts + 1] = ("%s is trying to take its foe with it!"):format(
    attacker.name or "POKeMON")
  return texts
end

function Game3:useSubstitute(attacker, texts)
  texts = texts or {}
  local cost = math.max(1, math.floor((attacker.maxHp or 1) / Game3.SUBSTITUTE_DENOM))
  if (attacker.hp or 0) <= cost then
    texts[#texts + 1] = ("But it failed!")
    return texts
  end
  if attacker.substitute then
    texts[#texts + 1] = ("%s already has a SUBSTITUTE!"):format(
      attacker.name or "POKeMON")
    return texts
  end
  attacker.hp = math.max(1, (attacker.hp or 0) - cost)
  attacker.substitute = true
  attacker.substituteHp = cost
  -- setsubstitute also drops STATUS2_WRAPPED off the user.
  attacker.wrapped = nil
  attacker.wrappedMoveName = nil
  attacker.wrappedBy = nil
  texts[#texts + 1] = ("%s put in a SUBSTITUTE!"):format(
    attacker.name or "POKeMON")
  return texts
end

-- The doll eats the hit instead of the holder. Returns the texts to print, or
-- nil when there is no substitute to absorb it.
function Game3:absorbIntoSubstitute(defender, dmg)
  if not defender or not defender.substitute then return nil end
  local left = defender.substituteHp or 0
  if left >= dmg then
    defender.substituteHp = left - dmg
  else
    defender.substituteHp = 0
  end
  if (defender.substituteHp or 0) <= 0 then
    defender.substitute = nil
    defender.substituteHp = nil
    return { ("%s's SUBSTITUTE faded!"):format(defender.name or "POKeMON") }
  end
  return {}
end

-- atk69_adjustsetdamage: a set amount still respects ENDURE and still feeds
-- Bide, friendship and the damage-taken record.
-- TrySetDestinyBondToHappen: a mon that faints while its bond is up drags the
-- battler that felled it down too.
function Game3:tryDestinyBond(defender, attacker, texts)
  if not defender or (defender.hp or 0) > 0 then return texts end
  if not defender.destinyBond then return texts end
  if not attacker or (attacker.hp or 0) <= 0 then return texts end
  defender.destinyBond = nil
  attacker.hp = 0
  texts = texts or {}
  texts[#texts + 1] = ("%s took %s down with it!"):format(
    defender.name or "POKeMON", attacker.name or "POKeMON")
  return texts
end

function Game3:applySetDamage(attacker, defender, dmg)
  dmg = math.max(0, math.floor(dmg or 0))
  if defender.substitute then
    local faded = self:absorbIntoSubstitute(defender, dmg)
    return { dmg = dmg, mul = 10, crit = false, substitute = true,
      substituteFaded = faded and #faded > 0 or false, texts = faded }
  end
  local endured = false
  if defender.endured and dmg >= (defender.hp or 0) then
    dmg = math.max(0, (defender.hp or 1) - 1)
    endured = true
  end
  defender.hp = math.max(0, (defender.hp or 0) - dmg)
  self:noteBideHit(defender, attacker, dmg)
  self:notePlayerDamaged(defender, dmg)
  self:maybeFaintFriendship(defender, attacker)
  return { dmg = dmg, mul = 10, crit = false, endured = endured }
end

function Game3:dealTackle(attacker, defender)
  return self:dealDamage(attacker, defender, {
    power = Game3.TACKLE_POWER, type = Game3.TACKLE_TYPE,
  }).dmg
end

function Game3:blocksStatDrop(mon, stat)
  if self:hasAbility(mon, Game3.ABILITY_CLEAR_BODY)
      or self:hasAbility(mon, Game3.ABILITY_WHITE_SMOKE) then
    return true
  end
  if stat == "atk" and self:hasAbility(mon, Game3.ABILITY_HYPER_CUTTER) then
    return true
  end
  if stat == "acc" and self:hasAbility(mon, Game3.ABILITY_KEEN_EYE) then
    return true
  end
  return false
end

function Game3:dropStat(mon, stat, label, amount, selfInflicted)
  amount = amount or 1
  local b = self.battle
  if not selfInflicted and b and self:mistTurnsFor(mon) > 0 then
    return ("%s is protected by MIST!"):format(mon.name)
  end
  local st = mon.stages
  if type(st) ~= "table" then
    st = { atk = 0, def = 0, spa = 0, spd = 0, spe = 0 }
    mon.stages = st
  end
  if not selfInflicted and self:blocksStatDrop(mon, stat) then
    return ("%s's %s cannot be lowered!"):format(
      mon.name, Game3.abilityName(mon.ability))
  end
  local cur = st[stat] or 0
  if cur <= -6 then
    return ("%s's %s won't go lower!"):format(mon.name, label)
  end
  st[stat] = math.max(-6, cur - amount)
  if amount >= 2 then
    return ("%s's %s harshly fell!"):format(mon.name, label)
  end
  return ("%s's %s fell!"):format(mon.name, label)
end

function Game3:raiseStat(mon, stat, amount, label)
  amount = amount or 1
  local st = mon.stages
  if type(st) ~= "table" then
    st = { atk = 0, def = 0, spa = 0, spd = 0, spe = 0 }
    mon.stages = st
  end
  local cur = st[stat] or 0
  if cur >= 6 then
    return ("%s's %s won't go any higher!"):format(mon.name, label)
  end
  st[stat] = math.min(6, cur + amount)
  if amount >= 2 then
    return ("%s's %s rose sharply!"):format(mon.name, label)
  end
  return ("%s's %s rose!"):format(mon.name, label)
end

function Game3.statUpSpec(effect)
  if effect == Game3.EFFECT_ATTACK_UP then return { { "atk", 1, "ATTACK" } } end
  if effect == Game3.EFFECT_DEFENSE_UP or effect == Game3.EFFECT_DEFENSE_CURL then
    return { { "def", 1, "DEFENSE" } }
  end
  if effect == Game3.EFFECT_SPEED_UP then return { { "spe", 1, "SPEED" } } end
  if effect == Game3.EFFECT_SPATK_UP then return { { "spa", 1, "SP. ATK" } } end
  if effect == Game3.EFFECT_SPDEF_UP then return { { "spd", 1, "SP. DEF" } } end
  if effect == Game3.EFFECT_EVASION_UP then return { { "eva", 1, "EVASION" } } end
  if effect == Game3.EFFECT_ATTACK_UP_2 then return { { "atk", 2, "ATTACK" } } end
  if effect == Game3.EFFECT_DEFENSE_UP_2 then return { { "def", 2, "DEFENSE" } } end
  if effect == Game3.EFFECT_SPEED_UP_2 then return { { "spe", 2, "SPEED" } } end
  if effect == Game3.EFFECT_SPATK_UP_2 then return { { "spa", 2, "SP. ATK" } } end
  if effect == Game3.EFFECT_SPDEF_UP_2 then return { { "spd", 2, "SP. DEF" } } end
  if effect == Game3.EFFECT_COSMIC_POWER then
    return { { "def", 1, "DEFENSE" }, { "spd", 1, "SP. DEF" } }
  end
  if effect == Game3.EFFECT_BULK_UP then
    return { { "atk", 1, "ATTACK" }, { "def", 1, "DEFENSE" } }
  end
  if effect == Game3.EFFECT_CALM_MIND then
    return { { "spa", 1, "SP. ATK" }, { "spd", 1, "SP. DEF" } }
  end
  if effect == Game3.EFFECT_DRAGON_DANCE then
    return { { "atk", 1, "ATTACK" }, { "spe", 1, "SPEED" } }
  end
end

-- Roxanne's Rock Tomb (70) and Crunch / Shadow Ball (72).
function Game3.statDownHitSpec(effect)
  if effect == Game3.EFFECT_ATTACK_DOWN_HIT then return "atk", "ATTACK" end
  if effect == Game3.EFFECT_DEFENSE_DOWN_HIT then return "def", "DEFENSE" end
  if effect == Game3.EFFECT_SPEED_DOWN_HIT then return "spe", "SPEED" end
  if effect == Game3.EFFECT_SPECIAL_ATTACK_DOWN_HIT then return "spa", "SP. ATK" end
  if effect == Game3.EFFECT_SPECIAL_DEFENSE_DOWN_HIT then return "spd", "SP. DEF" end
  if effect == Game3.EFFECT_ACCURACY_DOWN_HIT then return "acc", "ACCURACY" end
end

-- pokeruby BattleScript_EffectStatDown / setstatchanger. Fake Tears is
-- SPECIAL_DEFENSE_DOWN_2; Charm / Screech / Cotton Spore / Metal Sound
-- share the same script with a different stat.
function Game3.statDownSpec(effect)
  if effect == Game3.EFFECT_ATTACK_DOWN then return "atk", "ATTACK", 1 end
  if effect == Game3.EFFECT_DEFENSE_DOWN then return "def", "DEFENSE", 1 end
  if effect == Game3.EFFECT_SPEED_DOWN then return "spe", "SPEED", 1 end
  if effect == Game3.EFFECT_ACCURACY_DOWN then return "acc", "ACCURACY", 1 end
  if effect == Game3.EFFECT_EVASION_DOWN then return "eva", "EVASION", 1 end
  if effect == Game3.EFFECT_ATTACK_DOWN_2 then return "atk", "ATTACK", 2 end
  if effect == Game3.EFFECT_DEFENSE_DOWN_2 then return "def", "DEFENSE", 2 end
  if effect == Game3.EFFECT_SPEED_DOWN_2 then return "spe", "SPEED", 2 end
  if effect == Game3.EFFECT_SPECIAL_ATTACK_DOWN_2 then return "spa", "SP. ATK", 2 end
  if effect == Game3.EFFECT_SPECIAL_DEFENSE_DOWN_2 then return "spd", "SP. DEF", 2 end
  if effect == Game3.EFFECT_ACCURACY_DOWN_2 then return "acc", "ACCURACY", 2 end
  if effect == Game3.EFFECT_EVASION_DOWN_2 then return "eva", "EVASION", 2 end
end

function Game3:useStatDownMove(attacker, defender, move, effect, texts)
  texts = texts or {}
  local stat, label, amount = Game3.statDownSpec(effect)
  if not stat then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  local chart = self.data.moves and self.data.moves.typeChart
  local mul = Game3.typeMul(chart, move.type, defender.type1, defender.type2,
    defender.foresight)
  if self:hasAbility(defender, Game3.ABILITY_LEVITATE)
      and move.type == Game3.TYPE_GROUND then
    mul = 0
  end
  if mul <= 0 then
    texts[#texts + 1] = ("It doesn't affect %s..."):format(defender.name)
    return texts
  end
  texts[#texts + 1] = self:dropStat(defender, stat, label, amount)
  self:armMoveAnim(attacker, defender, move, "status")
  return texts
end

-- Steven's TM47 Steel Wing (138) and Metal Claw (139).
function Game3.statUpHitSpec(effect)
  if effect == Game3.EFFECT_ATTACK_UP_HIT then return "atk", "ATTACK" end
  if effect == Game3.EFFECT_DEFENSE_UP_HIT then return "def", "DEFENSE" end
end

-- nil means the move cannot miss (Swift, Thunder in rain).
function Game3:moveHitChance(attacker, defender, move, effect)
  effect = effect or (move and move.effect) or 0
  if effect == Game3.EFFECT_ALWAYS_HIT or effect == Game3.EFFECT_VITAL_THROW then
    return nil
  end
  -- STATUS3_ALWAYS_HITS, and only for the battler that took aim.
  if defender and (defender.sureHitTurns or 0) > 0
      and defender.sureHitFrom == attacker then
    return nil
  end
  local acc = tonumber(move and move.accuracy)
  if acc == nil then acc = 100 end
  if acc < 1 then return nil end
  if not self:weatherSuppressed() and self.battle then
    local w = self.battle.weather
    if w == Game3.WEATHER_RAIN
        and (effect == Game3.EFFECT_THUNDER
          or self:attackType(attacker, move) == Game3.TYPE_ELECTRIC) then
      return nil
    end
    if w == Game3.WEATHER_SUN and effect == Game3.EFFECT_THUNDER then
      acc = 50
    end
  end
  local atkAcc = attacker and attacker.stages and attacker.stages.acc or 0
  local defEva = defender and defender.stages and defender.stages.eva or 0
  if defender and defender.foresight then defEva = 0 end
  acc = Game3.accuracyFromStages(acc, atkAcc, defEva)
  if self:hasAbility(attacker, Game3.ABILITY_COMPOUND_EYES) then
    acc = math.floor(acc * 130 / 100)
  end
  if Game3.isPhysical(self:attackType(attacker, move))
      and self:hasAbility(attacker, Game3.ABILITY_HUSTLE) then
    acc = math.floor(acc * 80 / 100)
  end
  if effect ~= Game3.EFFECT_OHKO
      and not self:weatherSuppressed()
      and self.battle and self.battle.weather == Game3.WEATHER_SAND
      and self:hasAbility(defender, Game3.ABILITY_SAND_VEIL) then
    acc = math.max(1, math.floor(acc * 80 / 100))
  end
  return acc
end

function Game3.protectSucceeds(streak, roll)
  local rates = { 65535, 32767, 16383, 8191 }
  local i = (streak or 0) + 1
  if i > #rates then i = #rates end
  return (roll or 0) <= rates[i]
end

function Game3.ohkoChance(atkLevel, defLevel)
  atkLevel = atkLevel or 1
  defLevel = defLevel or 1
  if defLevel > atkLevel then return 0 end
  local n = atkLevel - defLevel + 30
  if n > 100 then n = 100 end
  return n
end

function Game3.chargeKind(move)
  local effect = move and move.effect or 0
  if effect == Game3.EFFECT_SOLARBEAM then return "solarbeam" end
  if effect == Game3.EFFECT_RAZOR_WIND then return "razorwind" end
  if effect == Game3.EFFECT_SKY_ATTACK then return "skyattack" end
  if effect == Game3.EFFECT_SKULL_BASH then return "skullbash" end
  if effect ~= Game3.EFFECT_FLY then return nil end
  local t = move.type or 0
  if t == Game3.TYPE_GROUND then return "dig" end
  if t == Game3.TYPE_WATER then return "dive" end
  return "fly"
end

function Game3.chargeText(mon, kind)
  local name = mon and mon.name or "POKeMON"
  if kind == "solarbeam" then return ("%s took in sunlight!"):format(name) end
  if kind == "fly" then return ("%s flew up high!"):format(name) end
  if kind == "dig" then return ("%s dug a hole!"):format(name) end
  if kind == "dive" then return ("%s hid underwater!"):format(name) end
  if kind == "razorwind" then return ("%s whipped up a whirlwind!"):format(name) end
  if kind == "skyattack" then return ("%s is glowing!"):format(name) end
  if kind == "skullbash" then return ("%s tucked in its head!"):format(name) end
  return ("%s is charging up!"):format(name)
end

function Game3:hitsInvuln(move, kind)
  if not kind then return true end
  local effect = move and move.effect or 0
  if kind == "fly" then
    return effect == Game3.EFFECT_THUNDER or effect == Game3.EFFECT_GUST
      or effect == Game3.EFFECT_TWISTER or effect == Game3.EFFECT_SKY_UPPERCUT
  end
  if kind == "dig" then
    return effect == Game3.EFFECT_EARTHQUAKE or effect == Game3.EFFECT_MAGNITUDE
      or effect == Game3.EFFECT_OHKO
  end
  if kind == "dive" then
    local name = move and move.name or ""
    return name:find("SURF", 1, true) ~= nil
      or name:find("WHIRLPOOL", 1, true) ~= nil
  end
  return false
end

function Game3:skipsCharge(move)
  if not move or move.effect ~= Game3.EFFECT_SOLARBEAM then return false end
  return not self:weatherSuppressed()
    and self.battle and self.battle.weather == Game3.WEATHER_SUN
end

function Game3:useFocusEnergy(mon, texts)
  texts = texts or {}
  if mon.focusEnergy then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  mon.focusEnergy = true
  texts[#texts + 1] = ("%s is getting pumped!"):format(mon.name)
  return texts
end

-- pokeruby BattleScript_EffectRage / MOVE_EFFECT_RAGE / atk49 ATK49_RAGE.
-- Accuracy check first: miss and Protect run clearstatusfromeffect USER.
-- A pass sets STATUS2_RAGE on the user even if type immunity zeroes damage.
function Game3:clearRageIfOtherMove(attacker, effect)
  if attacker and effect ~= Game3.EFFECT_RAGE then
    attacker.rage = nil
  end
end

function Game3:armRage(attacker, effect, hit)
  if not attacker or effect ~= Game3.EFFECT_RAGE then return end
  attacker.rage = hit and true or nil
end

function Game3:tickRage(defender, dmg, texts)
  if not defender or not defender.rage or not texts then return end
  if (dmg or 0) < 1 or (defender.hp or 0) < 1 then return end
  local st = defender.stages
  if type(st) ~= "table" then
    st = { atk = 0, def = 0, spa = 0, spd = 0, spe = 0 }
    defender.stages = st
  end
  if (st.atk or 0) >= 6 then return end
  st.atk = (st.atk or 0) + 1
  texts[#texts + 1] = ("%s's RAGE is building!"):format(defender.name)
end

-- pokeruby BattleScript_EffectMudSport / atkE8_settypebasedhalvers.
-- No accuracy check. Already-set on this battler is BattleScript_ButItFailed.
function Game3:useSport(attacker, effect, texts)
  texts = texts or {}
  local key, line
  if effect == Game3.EFFECT_MUD_SPORT then
    key, line = "mudSport", "Electricity's power was weakened!"
  else
    key, line = "waterSport", "Fire's power was weakened!"
  end
  if attacker[key] then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  attacker[key] = true
  texts[#texts + 1] = line
  return texts
end

function Game3:useProtect(attacker, texts, endure)
  texts = texts or {}
  local streak = attacker.protectStreak or 0
  local roll = self:rand(65536) - 1
  if not Game3.protectSucceeds(streak, roll) then
    attacker.protectStreak = 0
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  attacker.protectStreak = streak + 1
  if endure then
    attacker.endured = true
    texts[#texts + 1] = ("%s braced itself!"):format(attacker.name)
  else
    attacker.protected = true
    texts[#texts + 1] = ("%s protected itself!"):format(attacker.name)
  end
  return texts
end

-- pokeruby CanRunFromBattle. 0 = can run, 1 = fail, 2 = ability.
function Game3:canRunFromBattle(mon)
  if not mon then return 1 end
  local hold = self:holdEffectOf(mon)
  if hold == Game3.HOLD_EFFECT_CAN_ALWAYS_RUN then return 0 end
  if self:hasAbility(mon, Game3.ABILITY_RUN_AWAY) then return 0 end
  local foes = self:foesOf(mon)
  for i = 1, #foes do
    local foe = foes[i]
    if Game3.aliveMon(foe) then
      if self:hasAbility(foe, Game3.ABILITY_SHADOW_TAG) then
        return 2, foe, Game3.ABILITY_SHADOW_TAG
      end
      if self:hasAbility(foe, Game3.ABILITY_ARENA_TRAP)
          and not self:hasAbility(mon, Game3.ABILITY_LEVITATE)
          and not Game3.hasType(mon, Game3.TYPE_FLYING) then
        return 2, foe, Game3.ABILITY_ARENA_TRAP
      end
      if self:hasAbility(foe, Game3.ABILITY_MAGNET_PULL)
          and Game3.hasType(mon, Game3.TYPE_STEEL) then
        return 2, foe, Game3.ABILITY_MAGNET_PULL
      end
    end
  end
  if mon.cannotEscape or mon.wrapped or mon.rooted then return 1 end
  local b = self.battle
  if b and (b.chase or b.wallyTutorial) then return 1 end
  return 0
end

-- battle_main.c TryRunFromBattle -- the roll, as opposed to
-- canRunFromBattle above, which is the cart's separate CanRunFromBattle
-- trapping check. Escape is only ever uncertain when the player's mon is
-- SLOWER than the foe: at equal speed or faster it always gets away. Every
-- attempt, successful or not, bumps runTries, and each one adds 30 to the
-- numerator, so repeated tries converge on escaping. A Smoke Ball or the
-- RUN AWAY ability skips the roll outright.
--
-- Returns ok, holdEffect, ability -- the latter two so the caller can name
-- whichever one did it.
function Game3:tryRunFromBattle(mon)
  local b = self.battle
  if not (b and mon) then return false end
  if self:holdEffectOf(mon) == Game3.HOLD_EFFECT_CAN_ALWAYS_RUN then
    return true, Game3.HOLD_EFFECT_CAN_ALWAYS_RUN
  end
  if self:hasAbility(mon, Game3.ABILITY_RUN_AWAY) then
    return true, nil, Game3.ABILITY_RUN_AWAY
  end
  local ok = false
  -- The cart only rolls in a single battle; the double-battle branch
  -- falls through with effect unset, so a wild double can never be fled.
  if not b.doubles then
    local mine = self:speedOf(mon)
    local theirs = self:speedOf(b.enemy)
    if theirs > 0 and mine < theirs then
      -- integer divide, exactly as the C does
      local speedVar = math.floor(mine * 128 / theirs) + (b.runTries or 0) * 30
      if speedVar > (self:gbaRandom() % 256) then ok = true end
    else
      ok = true
    end
  end
  b.runTries = (b.runTries or 0) + 1
  return ok
end

-- Battle Teleport. Field HM-style TELEPORT is useTeleport.
function Game3:useBattleTeleport(attacker, texts)
  texts = texts or {}
  local b = self.battle
  if not b or b.isTrainer then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  local code, foe, ability = self:canRunFromBattle(attacker)
  if code == 2 then
    texts[#texts + 1] = ("%s's %s made it ineffective!"):format(
      foe.name, Game3.abilityName(ability))
    return texts
  end
  if code ~= 0 then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  texts[#texts + 1] = ("%s fled from battle!"):format(attacker.name)
  b.fled = true
  return texts
end

-- pokeruby AbilityBattleEffects ENDTURN Speed Boost. isFirstTurn == 2
-- is the switch-in turn; battle_main decrements it at the next turn start.
function Game3:speedBoostResidual(mon)
  if not mon or (mon.hp or 0) <= 0 then return {} end
  if not self:hasAbility(mon, Game3.ABILITY_SPEED_BOOST) then return {} end
  if (mon.isFirstTurn or 0) == 2 then return {} end
  local st = mon.stages
  if type(st) ~= "table" then
    st = { atk = 0, def = 0, spa = 0, spd = 0, spe = 0 }
    mon.stages = st
  end
  if (st.spe or 0) >= 6 then return {} end
  st.spe = (st.spe or 0) + 1
  return { ("%s's %s raised its SPEED!"):format(
    mon.name, Game3.abilityName(Game3.ABILITY_SPEED_BOOST)) }
end

function Game3:slotOfBattler(mon)
  local b = self.battle
  if not b or not mon then return nil end
  if mon == b.player then return "player" end
  if mon == b.player2 then return "player2" end
  if mon == b.enemy then return "enemy" end
  if mon == b.enemy2 then return "enemy2" end
end

-- pokeruby BattleScript_EffectRoar / atk8F_forcerandomswitch.
function Game3:useRoar(attacker, defender, texts)
  texts = texts or {}
  local b = self.battle
  if not b or not defender then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  if self:hasAbility(defender, Game3.ABILITY_SUCTION_CUPS) then
    texts[#texts + 1] = ("%s anchors itself with %s!"):format(
      defender.name, Game3.abilityName(Game3.ABILITY_SUCTION_CUPS))
    return texts
  end
  if defender.rooted then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  if not b.isTrainer then
    local atkLv, defLv = attacker.level or 1, defender.level or 1
    if atkLv < defLv then
      local random = self:gbaRandom() % 256
      local rolled = math.floor(random * (atkLv + defLv) / 256) + 1
      if rolled <= math.floor(defLv / 4) then
        texts[#texts + 1] = "But it failed!"
        return texts
      end
    end
    b.fled = true
    b.forcedOut = true
    return texts
  end
  local incoming
  if self:isPlayerBattler(defender) then
    local cands = {}
    local party = self.party or {}
    for i = 1, #party do
      local mon = party[i]
      if Game3.aliveMon(mon) and mon ~= b.player and mon ~= b.player2
          and not mon.isEgg then
        cands[#cands + 1] = i
      end
    end
    if #cands < 1 then
      texts[#texts + 1] = "But it failed!"
      return texts
    end
    local idx = cands[self:rand(#cands)]
    incoming = party[idx]
    b.switchSlot = defender == b.player2 and "player2" or "player"
    local ok, _, extra = self:switchTo(idx)
    if not ok then
      texts[#texts + 1] = "But it failed!"
      return texts
    end
    texts[#texts + 1] = ("%s was dragged out!"):format(incoming.name)
    for i = 1, #(extra or {}) do texts[#texts + 1] = extra[i] end
    return texts
  end
  local cands = {}
  local bench = b.phazed or {}
  for i = 1, #bench do
    if Game3.aliveMon(bench[i]) and bench[i] ~= defender then
      cands[#cands + 1] = { bench = i }
    end
  end
  local party = b.trainerParty or {}
  local nextIdx = (b.trainerIndex or 1) + 1
  if nextIdx <= #party then
    cands[#cands + 1] = { trainer = nextIdx }
  end
  if #cands < 1 then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  local pick = cands[self:rand(#cands)]
  if pick.trainer then
    incoming = self:prepBattler(self:makeTrainerMon(party[pick.trainer]))
    b.trainerIndex = pick.trainer
  else
    incoming = table.remove(bench, pick.bench)
    incoming = self:prepBattler(incoming)
  end
  if not incoming then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  b.phazed = bench
  bench[#bench + 1] = defender
  local slot = self:slotOfBattler(defender) or "enemy"
  b[slot] = incoming
  self:markSeen(incoming.species)
  self:markSentIn(incoming)
  texts[#texts + 1] = ("%s was dragged out!"):format(incoming.name)
  local foe = Game3.aliveMon(b.player) and b.player or b.player2
  if foe then
    local extra = self:activateEnter(incoming, foe)
    for i = 1, #extra do texts[#texts + 1] = extra[i] end
  end
  return texts
end

function Game3:noteBideHit(defender, attacker, dmg)
  if defender and defender.bideTurns and (dmg or 0) > 0 then
    defender.bideTaken = (defender.bideTaken or 0) + dmg
    defender.bideFrom = attacker
  end
end

function Game3:cancelMultiTurn(mon)
  if not mon then return end
  mon.charging = nil
  mon.invuln = nil
  mon.bideTurns = nil
  mon.bideTaken = nil
  mon.bideFrom = nil
  mon.uproarTurns = nil
  mon.uproarMove = nil
  -- CancelMultiTurnMoves clears the rampage lock too. No confusion: the cart
  -- only confuses when the counter runs down on its own.
  mon.rampage = nil
  mon.rampageMove = nil
  mon.rolloutTimer = nil
  mon.rolloutMove = nil
  mon.furyCutter = nil
end

-- pokeruby setbide / BattleScript_Bide*: two stored turns, then 2x HP.
function Game3:useBide(attacker, defender, move, texts)
  texts = texts or {}
  if not attacker.bideTurns then
    attacker.bideTurns = 2
    attacker.bideTaken = 0
    attacker.bideFrom = nil
    attacker.charging = { move = move, kind = "bide" }
    texts[#texts + 1] = ("%s is storing energy!"):format(attacker.name)
    return texts
  end
  attacker.bideTurns = attacker.bideTurns - 1
  if attacker.bideTurns > 0 then
    texts[#texts + 1] = ("%s is storing energy!"):format(attacker.name)
    return texts
  end
  attacker.charging = nil
  local stored = attacker.bideTaken or 0
  local from = attacker.bideFrom
  attacker.bideTurns = nil
  attacker.bideTaken = nil
  attacker.bideFrom = nil
  texts[#texts + 1] = ("%s unleashed energy!"):format(attacker.name)
  if stored <= 0 then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  local target = from
  if not Game3.aliveMon(target) or target == attacker then
    target = self:defaultTarget(attacker)
  end
  if not Game3.aliveMon(target) then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  if target.protected then
    texts[#texts + 1] = ("%s protected itself!"):format(target.name)
    return texts
  end
  if target.invuln and not self:hitsInvuln(move, target.invuln) then
    texts[#texts + 1] = "The attack missed!"
    return texts
  end
  local chance = self:moveHitChance(attacker, target, move, Game3.EFFECT_BIDE)
  if chance and chance < 100
      and (chance < 1 or self:rand(100) > chance) then
    texts[#texts + 1] = "The attack missed!"
    return texts
  end
  local chart = self.data.moves and self.data.moves.typeChart
  local mul = Game3.typeMul(chart, move.type or 0, target.type1, target.type2,
    target.foresight)
  if self:hasAbility(target, Game3.ABILITY_WONDER_GUARD)
      and mul > 0 and mul <= 10 then
    mul = 0
  end
  if mul <= 0 then
    texts[#texts + 1] = ("It doesn't affect %s..."):format(target.name)
    return texts
  end
  local dmg = stored * 2
  local endured = false
  if target.endured and dmg >= (target.hp or 0) then
    dmg = math.max(0, (target.hp or 1) - 1)
    endured = true
  end
  target.hp = math.max(0, (target.hp or 0) - dmg)
  if endured then
    texts[#texts + 1] = ("%s endured the hit!"):format(target.name)
  end
  if Game3.isContact(move) then
    self:onContact(attacker, target, texts)
  end
  if (target.hp or 0) <= 0 then
    texts[#texts + 1] = ("%s fainted!"):format(target.name)
  end
  if (attacker.hp or 0) <= 0 then
    texts[#texts + 1] = ("%s fainted!"):format(attacker.name)
  end
  return texts
end

function Game3:useOhko(attacker, defender, move, texts)
  local chart = self.data.moves and self.data.moves.typeChart
  local mul = Game3.typeMul(chart, move.type, defender.type1, defender.type2,
    defender.foresight)
  if self:hasAbility(defender, Game3.ABILITY_LEVITATE)
      and move.type == Game3.TYPE_GROUND then
    mul = 0
  end
  if self:hasAbility(defender, Game3.ABILITY_WONDER_GUARD)
      and mul > 0 and mul <= 10 then
    mul = 0
  end
  if mul <= 0 then
    texts[#texts + 1] = ("It doesn't affect %s..."):format(defender.name)
    return texts
  end
  if self:hasAbility(defender, Game3.ABILITY_STURDY) then
    texts[#texts + 1] = ("%s was protected by %s!"):format(
      defender.name, Game3.abilityName(Game3.ABILITY_STURDY))
    return texts
  end
  local chance = Game3.ohkoChance(attacker.level, defender.level)
  if chance < 1 then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  if self:rand(100) > chance then
    texts[#texts + 1] = "The attack missed!"
    return texts
  end
  defender.hp = 0
  self:notePlayerDamaged(defender, 1)
  self:maybeFaintFriendship(defender, attacker)
  texts[#texts + 1] = "It's a one-hit KO!"
  texts[#texts + 1] = ("%s fainted!"):format(defender.name)
  return texts
end

function Game3:weatherSuppressed()
  local b = self.battle
  if not b then return true end
  local mons = { b.player, b.player2, b.enemy, b.enemy2 }
  for i = 1, 4 do
    if self:hasAbility(mons[i], Game3.ABILITY_CLOUD_NINE)
        or self:hasAbility(mons[i], Game3.ABILITY_AIR_LOCK) then
      return true
    end
  end
  return false
end

-- pokeruby AbilityBattleEffects(ABILITYEFFECT_FIELD_SPORT): any battler
-- with STATUS3_MUDSPORT / WATERSPORT. SwitchInClearSetData zeroes them
-- unless Baton Pass kept the bits.
function Game3:fieldHasSport(key)
  local b = self.battle
  if not b or not key then return false end
  local mons = { b.player, b.player2, b.enemy, b.enemy2 }
  for i = 1, 4 do
    if mons[i] and mons[i][key] then return true end
  end
  return false
end

function Game3:battlers()
  local b = self.battle
  if not b then return {} end
  local out = {}
  if b.player then out[#out + 1] = b.player end
  if b.player2 then out[#out + 1] = b.player2 end
  if b.enemy then out[#out + 1] = b.enemy end
  if b.enemy2 then out[#out + 1] = b.enemy2 end
  return out
end

-- Plus / Minus: AbilityBattleEffects(ABILITYEFFECT_FIELD_SPORT).
-- Fainted battlers still count.
function Game3:fieldHasAbility(id)
  local mons = self:battlers()
  for i = 1, #mons do
    if self:hasAbility(mons[i], id) then return true end
  end
  return false
end

function Game3:fieldHasUproar()
  local mons = self:battlers()
  for i = 1, #mons do
    if mons[i] and (mons[i].uproarTurns or 0) > 0 then return true end
  end
  return false
end

function Game3:battlerWithAbility(id)
  local mons = self:battlers()
  for i = 1, #mons do
    if self:hasAbility(mons[i], id) then return mons[i] end
  end
end

function Game3:countAbilityExcept(except, id)
  local n = 0
  local mons = self:battlers()
  for i = 1, #mons do
    if mons[i] and mons[i] ~= except and self:hasAbility(mons[i], id) then
      n = n + 1
    end
  end
  return n
end

function Game3:countAbilityOpponents(attacker, id)
  local n = 0
  local foes = self:foesOf(attacker)
  for i = 1, #foes do
    if self:hasAbility(foes[i], id) then n = n + 1 end
  end
  return n
end

function Game3.isSoundMove(move)
  local id = type(move) == "table" and (move.id or 0) or (move or 0)
  return Game3.SOUND_MOVES[id] == true
end

-- pokeruby atk03_ppreduce + Pressure.
function Game3:pressurePpCost(attacker, defender, move)
  local n = 1
  local t = (move and move.target) or 0
  if t == Game3.TARGET_FOES_AND_ALLY then
    n = n + self:countAbilityExcept(attacker, Game3.ABILITY_PRESSURE)
  elseif t == Game3.TARGET_BOTH or t == Game3.TARGET_OPPONENTS_FIELD then
    n = n + self:countAbilityOpponents(attacker, Game3.ABILITY_PRESSURE)
  elseif attacker ~= defender
      and self:hasAbility(defender, Game3.ABILITY_PRESSURE) then
    n = n + 1
  end
  -- PressurePPLoseOnUsingPerishSong: +1 per other Pressure (TARGET_USER
  -- skips the defender branch above). Deducted even if the move fails.
  if self:moveEffect(move) == Game3.EFFECT_PERISH_SONG then
    n = n + self:countAbilityExcept(attacker, Game3.ABILITY_PRESSURE)
  end
  return n
end

function Game3.weatherStartText(kind)
  if kind == Game3.WEATHER_RAIN then return "It started to rain!" end
  if kind == Game3.WEATHER_SUN then return "The sunlight turned harsh!" end
  if kind == Game3.WEATHER_SAND then return "A sandstorm brewed!" end
  if kind == Game3.WEATHER_HAIL then return "It started to hail!" end
  return "The weather changed!"
end

function Game3.weatherEndText(kind)
  if kind == Game3.WEATHER_RAIN then return "The rain stopped." end
  if kind == Game3.WEATHER_SUN then return "The sunlight faded." end
  if kind == Game3.WEATHER_SAND then return "The sandstorm subsided." end
  if kind == Game3.WEATHER_HAIL then return "The hail stopped." end
  return "The weather cleared."
end

function Game3:restoreSpeciesTypes(mon)
  if not mon then return end
  local row = self:speciesRow(mon.species) or {}
  if row.type1 == nil then return end
  mon.type1 = row.type1
  mon.type2 = row.type2 or row.type1
end

function Game3:restorePartySpeciesTypes()
  local party = self.party
  if type(party) ~= "table" then return end
  for i = 1, #party do
    self:restoreSpeciesTypes(party[i])
  end
end

-- pokeruby CastformDataTypeChange. Form ids: 0 none, 1 Normal, 2 Fire,
-- 3 Water, 4 Ice. Cloud Nine / Air Lock revert a transformed Castform.
-- Sandstorm is not a Forecast weather, so it also reverts.
function Game3:castformDataTypeChange(mon)
  if not mon then return Game3.CASTFORM_NO_CHANGE end
  if mon.species ~= Game3.SPECIES_CASTFORM then return Game3.CASTFORM_NO_CHANGE end
  if not self:hasAbility(mon, Game3.ABILITY_FORECAST) then
    return Game3.CASTFORM_NO_CHANGE
  end
  if (mon.hp or 0) == 0 then return Game3.CASTFORM_NO_CHANGE end
  local t1, t2 = mon.type1, mon.type2
  if self:weatherSuppressed() then
    if t1 ~= Game3.TYPE_NORMAL and t2 ~= Game3.TYPE_NORMAL then
      mon.type1, mon.type2 = Game3.TYPE_NORMAL, Game3.TYPE_NORMAL
      return Game3.CASTFORM_TO_NORMAL
    end
    return Game3.CASTFORM_NO_CHANGE
  end
  local w = self.battle and self.battle.weather
  local formChange = Game3.CASTFORM_NO_CHANGE
  local weatherForm = w == Game3.WEATHER_RAIN
    or w == Game3.WEATHER_SUN
    or w == Game3.WEATHER_HAIL
  if not weatherForm and t1 ~= Game3.TYPE_NORMAL and t2 ~= Game3.TYPE_NORMAL then
    mon.type1, mon.type2 = Game3.TYPE_NORMAL, Game3.TYPE_NORMAL
    formChange = Game3.CASTFORM_TO_NORMAL
  end
  if w == Game3.WEATHER_SUN and t1 ~= Game3.TYPE_FIRE and t2 ~= Game3.TYPE_FIRE then
    mon.type1, mon.type2 = Game3.TYPE_FIRE, Game3.TYPE_FIRE
    formChange = Game3.CASTFORM_TO_FIRE
  end
  if w == Game3.WEATHER_RAIN and t1 ~= Game3.TYPE_WATER and t2 ~= Game3.TYPE_WATER then
    mon.type1, mon.type2 = Game3.TYPE_WATER, Game3.TYPE_WATER
    formChange = Game3.CASTFORM_TO_WATER
  end
  if w == Game3.WEATHER_HAIL and t1 ~= Game3.TYPE_ICE and t2 ~= Game3.TYPE_ICE then
    mon.type1, mon.type2 = Game3.TYPE_ICE, Game3.TYPE_ICE
    formChange = Game3.CASTFORM_TO_ICE
  end
  return formChange
end

function Game3:applyCastformChange(mon)
  local form = self:castformDataTypeChange(mon)
  if form == Game3.CASTFORM_NO_CHANGE then return nil end
  return ("%s transformed!"):format(mon.name)
end

function Game3:tryForecastForms()
  local texts = {}
  local b = self.battle
  if not b then return texts end
  local mons = { b.player, b.player2, b.enemy, b.enemy2 }
  for i = 1, 4 do
    local line = self:applyCastformChange(mons[i])
    if line then texts[#texts + 1] = line end
  end
  return texts
end

-- atkE9_setweatherballtype: type follows weather; any weather doubles.
function Game3:weatherBallType()
  if not self:weatherBallBoosts() then return Game3.TYPE_NORMAL end
  local w = self.battle and self.battle.weather
  if w == Game3.WEATHER_RAIN then return Game3.TYPE_WATER end
  if w == Game3.WEATHER_SAND then return Game3.TYPE_ROCK end
  if w == Game3.WEATHER_SUN then return Game3.TYPE_FIRE end
  if w == Game3.WEATHER_HAIL then return Game3.TYPE_ICE end
  return Game3.TYPE_NORMAL
end

function Game3:weatherBallBoosts()
  if self:weatherSuppressed() then return false end
  return (self.battle and self.battle.weather) ~= nil
end

function Game3:setWeather(kind, turns)
  local b = self.battle
  if not b or not kind then return false, "But it failed!" end
  if b.weather == kind then return false, "But it failed!" end
  b.weather = kind
  b.weatherTurns = turns
  return true, Game3.weatherStartText(kind)
end

function Game3:screenSide(mon)
  return self:isPlayerBattler(mon) and "player" or "enemy"
end

function Game3:sideAliveCount(mon)
  local b = self.battle
  if not b then return 1 end
  local a, c
  if self:isPlayerBattler(mon) then
    a, c = b.player, b.player2
  else
    a, c = b.enemy, b.enemy2
  end
  local n = 0
  if Game3.aliveMon(a) then n = n + 1 end
  if Game3.aliveMon(c) then n = n + 1 end
  return n
end

-- calculate_base_damage.c: screens halve (2/3 in doubles when both
-- defenders are up). Crits (gCritMultiplier == 2) skip them.
function Game3:screenDamageMul(defender, physical)
  local b = self.battle
  local row = b and b.screens and b.screens[self:screenSide(defender)]
  if type(row) ~= "table" then return 10 end
  local kind = physical and "reflect" or "lightScreen"
  if (row[kind] or 0) < 1 then return 10 end
  if b.doubles and self:sideAliveCount(defender) >= 2 then return 20 / 3 end
  return 5
end

function Game3:setSideScreen(mon, kind)
  local b = self.battle
  if not (b and mon and kind) then return "But it failed!" end
  b.screens = b.screens or {}
  local side = self:screenSide(mon)
  local row = b.screens[side] or {}
  b.screens[side] = row
  if (row[kind] or 0) > 0 then return "But it failed!" end
  row[kind] = Game3.SCREEN_TURNS
  if kind == "lightScreen" then return "LIGHT SCREEN raised SP. DEF!" end
  return "REFLECT raised DEFENSE!"
end

function Game3:tickScreens()
  local b = self.battle
  local texts = {}
  -- SAFEGUARD and MIST are side counters like the screens, so they run down
  -- on the same beat.
  for _, pair in ipairs({
      { "safeguardTurns", "SAFEGUARD" }, { "safeguardTurnsFoe", "SAFEGUARD" },
      { "mistTurns", "MIST" }, { "mistTurnsFoe", "MIST" } }) do
    local key = pair[1]
    if b and (b[key] or 0) > 0 then
      b[key] = b[key] - 1
      if b[key] <= 0 then
        b[key] = nil
        texts[#texts + 1] = ("%s wore off!"):format(pair[2])
      end
    end
  end
  local screens = b and b.screens
  if type(screens) ~= "table" then return texts end
  local sides = { "player", "enemy" }
  local kinds = { "reflect", "lightScreen" }
  for s = 1, #sides do
    local row = screens[sides[s]]
    if type(row) == "table" then
      for k = 1, #kinds do
        local kind = kinds[k]
        if (row[kind] or 0) > 0 then
          row[kind] = row[kind] - 1
          if row[kind] <= 0 then
            row[kind] = nil
            local name = kind == "reflect" and "REFLECT" or "LIGHT SCREEN"
            texts[#texts + 1] = ("%s wore off!"):format(name)
          end
        end
      end
    end
  end
  return texts
end

function Game3:weatherKindForEffect(effect)
  if effect == Game3.EFFECT_RAIN_DANCE then return Game3.WEATHER_RAIN end
  if effect == Game3.EFFECT_SUNNY_DAY then return Game3.WEATHER_SUN end
  if effect == Game3.EFFECT_SANDSTORM then return Game3.WEATHER_SAND end
  if effect == Game3.EFFECT_HAIL then return Game3.WEATHER_HAIL end
end

function Game3:weatherPowerTenths(moveType)
  if self:weatherSuppressed() then return 10 end
  local w = self.battle and self.battle.weather
  if w == Game3.WEATHER_SUN then
    if moveType == Game3.TYPE_FIRE then return 15 end
    if moveType == Game3.TYPE_WATER then return 5 end
  elseif w == Game3.WEATHER_RAIN then
    if moveType == Game3.TYPE_WATER then return 15 end
    if moveType == Game3.TYPE_FIRE then return 5 end
  end
  return 10
end

function Game3:sandImmune(mon)
  return Game3.hasType(mon, Game3.TYPE_ROCK)
    or Game3.hasType(mon, Game3.TYPE_STEEL)
    or Game3.hasType(mon, Game3.TYPE_GROUND)
    or self:hasAbility(mon, Game3.ABILITY_SAND_VEIL)
end

function Game3:weatherResidual(mon)
  if not mon or (mon.hp or 0) <= 0 then return {} end
  if self:weatherSuppressed() then return {} end
  local w = self.battle and self.battle.weather
  local texts = {}
  if w == Game3.WEATHER_RAIN and self:hasAbility(mon, Game3.ABILITY_RAIN_DISH) then
    local maxHp = mon.maxHp or 1
    if (mon.hp or 0) < maxHp then
      local heal = math.max(1, math.floor(maxHp / 16))
      mon.hp = math.min(maxHp, (mon.hp or 0) + heal)
      texts[#texts + 1] = ("%s restored HP using its %s!"):format(
        mon.name, Game3.abilityName(Game3.ABILITY_RAIN_DISH))
    end
    return texts
  end
  if w == Game3.WEATHER_SAND then
    if self:sandImmune(mon) then return {} end
    local dmg = math.max(1, math.floor((mon.maxHp or 1) / 16))
    mon.hp = math.max(0, (mon.hp or 0) - dmg)
    texts[1] = ("%s is buffeted by the sandstorm!"):format(mon.name)
  elseif w == Game3.WEATHER_HAIL then
    if Game3.hasType(mon, Game3.TYPE_ICE) then return {} end
    local dmg = math.max(1, math.floor((mon.maxHp or 1) / 16))
    mon.hp = math.max(0, (mon.hp or 0) - dmg)
    texts[1] = ("%s is pelted by the hail!"):format(mon.name)
  else
    return {}
  end
  if (mon.hp or 0) <= 0 then
    texts[#texts + 1] = ("%s fainted!"):format(mon.name)
  end
  return texts
end

function Game3:tickWeather()
  local b = self.battle
  if not b or not b.weather then return {} end
  local texts = {}
  local function add(mon)
    local lines = self:weatherResidual(mon)
    for i = 1, #lines do texts[#texts + 1] = lines[i] end
  end
  add(b.player)
  add(b.enemy)
  if type(b.weatherTurns) == "number" then
    b.weatherTurns = b.weatherTurns - 1
    if b.weatherTurns <= 0 then
      texts[#texts + 1] = Game3.weatherEndText(b.weather)
      b.weather = nil
      b.weatherTurns = nil
      local extra = self:tryForecastForms()
      for i = 1, #extra do texts[#texts + 1] = extra[i] end
    end
  end
  return texts
end

function Game3:tryWeatherAbility(mon)
  if not mon then return nil end
  local kind, name
  if self:hasAbility(mon, Game3.ABILITY_DRIZZLE) then
    kind, name = Game3.WEATHER_RAIN, Game3.ABILITY_DRIZZLE
  elseif self:hasAbility(mon, Game3.ABILITY_DROUGHT) then
    kind, name = Game3.WEATHER_SUN, Game3.ABILITY_DROUGHT
  elseif self:hasAbility(mon, Game3.ABILITY_SAND_STREAM) then
    kind, name = Game3.WEATHER_SAND, Game3.ABILITY_SAND_STREAM
  else
    return nil
  end
  local b = self.battle
  if not b then return nil end
  if b.weather == kind and not b.weatherTurns then return nil end
  b.weather = kind
  b.weatherTurns = nil
  if kind == Game3.WEATHER_RAIN then
    return ("%s's %s made it rain!"):format(mon.name, Game3.abilityName(name))
  end
  if kind == Game3.WEATHER_SUN then
    return ("%s's %s intensified the sun's rays!"):format(
      mon.name, Game3.abilityName(name))
  end
  return ("%s's %s whipped up a sandstorm!"):format(
    mon.name, Game3.abilityName(name))
end

function Game3:activateEnter(mon, foe)
  local texts = {}
  if not mon or not foe then return texts end
  mon.truant = nil
  mon.isFirstTurn = 2
  for _, line in ipairs(self:applySpikes(mon)) do texts[#texts + 1] = line end
  if self:hasAbility(mon, Game3.ABILITY_TRACE) and (foe.ability or 0) > 0
      and foe.ability ~= Game3.ABILITY_TRACE then
    mon.ability = foe.ability
    texts[#texts + 1] = ("%s's TRACE copied %s's %s!"):format(
      mon.name, foe.name, Game3.abilityName(mon.ability))
  end
  if self:hasAbility(mon, Game3.ABILITY_INTIMIDATE) then
    local before = foe.stages and foe.stages.atk or 0
    texts[#texts + 1] = self:dropStat(foe, "atk", "ATTACK")
    local after = foe.stages and foe.stages.atk or 0
    if after < before then
      texts[#texts] = ("%s's INTIMIDATE cuts %s's ATTACK!"):format(
        mon.name, foe.name)
    end
  end
  local weather = self:tryWeatherAbility(mon)
  if weather then texts[#texts + 1] = weather end
  local extra = self:tryForecastForms()
  for i = 1, #extra do texts[#texts + 1] = extra[i] end
  -- ABILITYEFFECT_IMMUNITY after Trace / switch-in abilities.
  local cured = self:abilityImmunityCure(mon)
  if cured then texts[#texts + 1] = cured end
  return texts
end

-- AbilityBattleEffects(ABILITYEFFECT_IMMUNITY). English BattleText_* names
-- (poison / sleep / paralysis / burn / ice / confusion / love).
function Game3:abilityImmunityCure(mon)
  if not mon then return nil end
  local problem
  if self:hasAbility(mon, Game3.ABILITY_IMMUNITY)
      and Game3.isPoisonStatus(mon.status) then
    problem = "poison"
    mon.status = nil
    mon.toxicCounter = nil
  elseif self:hasAbility(mon, Game3.ABILITY_OWN_TEMPO)
      and (mon.confuseTurns or 0) > 0 then
    problem = "confusion"
    mon.confuseTurns = nil
  elseif self:hasAbility(mon, Game3.ABILITY_LIMBER)
      and mon.status == Game3.STATUS_PAR then
    problem = "paralysis"
    mon.status = nil
  elseif (self:hasAbility(mon, Game3.ABILITY_INSOMNIA)
        or self:hasAbility(mon, Game3.ABILITY_VITAL_SPIRIT))
      and mon.status == Game3.STATUS_SLP then
    problem = "sleep"
    mon.status = nil
    mon.sleepTurns = nil
  elseif self:hasAbility(mon, Game3.ABILITY_WATER_VEIL)
      and mon.status == Game3.STATUS_BRN then
    problem = "burn"
    mon.status = nil
  elseif self:hasAbility(mon, Game3.ABILITY_MAGMA_ARMOR)
      and mon.status == Game3.STATUS_FRZ then
    problem = "ice"
    mon.status = nil
  elseif self:hasAbility(mon, Game3.ABILITY_OBLIVIOUS) and mon.infatuatedBy then
    problem = "love"
    mon.infatuatedBy = nil
  end
  if not problem then return nil end
  return ("%s's %s cured its %s problem!"):format(
    mon.name, Game3.abilityName(mon.ability), problem)
end

function Game3:trySynchronize(from, to, status)
  if not self:hasAbility(from, Game3.ABILITY_SYNCHRONIZE) then return nil end
  if not Game3.isPoisonStatus(status) and status ~= Game3.STATUS_BRN
      and status ~= Game3.STATUS_PAR then
    return nil
  end
  return self:applyStatus(to, status)
end

function Game3:typeAbsorb(defender, move, attacker)
  local t = self:attackType(attacker, move)
  if t == Game3.TYPE_ELECTRIC then
    if self:hasAbility(defender, Game3.ABILITY_VOLT_ABSORB) then
      local heal = math.max(1, math.floor((defender.maxHp or 1) / 4))
      defender.hp = math.min(defender.maxHp or heal, (defender.hp or 0) + heal)
      return ("%s restored HP using its %s!"):format(
        defender.name, Game3.abilityName(Game3.ABILITY_VOLT_ABSORB))
    end
    if self:hasAbility(defender, Game3.ABILITY_LIGHTNING_ROD) then
      local st = defender.stages
      if type(st) ~= "table" then
        st = { atk = 0, def = 0, spa = 0, spd = 0, spe = 0 }
        defender.stages = st
      end
      st.spa = math.min(6, (st.spa or 0) + 1)
      return ("%s's %s raised SP. ATK!"):format(
        defender.name, Game3.abilityName(Game3.ABILITY_LIGHTNING_ROD))
    end
  end
  if t == Game3.TYPE_WATER
      and self:hasAbility(defender, Game3.ABILITY_WATER_ABSORB) then
    local heal = math.max(1, math.floor((defender.maxHp or 1) / 4))
    defender.hp = math.min(defender.maxHp or heal, (defender.hp or 0) + heal)
    return ("%s restored HP using its %s!"):format(
      defender.name, Game3.abilityName(Game3.ABILITY_WATER_ABSORB))
  end
  if t == Game3.TYPE_FIRE
      and self:hasAbility(defender, Game3.ABILITY_FLASH_FIRE) then
    defender.flashFire = true
    return ("%s's %s raised the power of its FIRE moves!"):format(
      defender.name, Game3.abilityName(Game3.ABILITY_FLASH_FIRE))
  end
end

-- Knock Off (effect 188). Shield Dust does not block it: SetMoveEffect
-- only filters MOVE_EFFECT_BYTE <= 9, and KNOCK_OFF is 0x36.
function Game3:knockOffItem(attacker, defender, move)
  local item = defender.item or 0
  if item == 0 then return nil end
  if self:hasAbility(defender, Game3.ABILITY_STICKY_HOLD) then
    return ("%s's %s made %s ineffective!"):format(
      defender.name, Game3.abilityName(Game3.ABILITY_STICKY_HOLD),
      (move and move.name) or "KNOCK OFF")
  end
  defender.item = 0
  return ("%s knocked off %s's %s!"):format(
    attacker.name, defender.name, self:itemName(item))
end

function Game3:applyHitSecondaries(attacker, defender, move, effect, texts)
  local chance = move.secondary or 0
  if self:hasAbility(attacker, Game3.ABILITY_SERENE_GRACE) then
    chance = math.min(100, chance * 2)
  end
  -- setmoveeffect returns early when the target is behind a substitute and the
  -- effect is not aimed at the user, so no status, no flinch, no stat drop.
  if defender and defender.substitute then return end
  -- FAKE OUT flinches outright rather than on a roll: its script writes the
  -- flinch straight into cEFFECT_CHOOSER, so it does not go through
  -- gBattleMoves[].secondaryEffectChance and must not be gated on it.
  if effect == Game3.EFFECT_FAKE_OUT then
    if not self:hasAbility(defender, Game3.ABILITY_INNER_FOCUS)
        and not self:hasAbility(defender, Game3.ABILITY_SHIELD_DUST) then
      defender.flinch = true
    end
    return
  end
  if chance < 1 then return end
  local dust = self:hasAbility(defender, Game3.ABILITY_SHIELD_DUST)
  if not dust then
    local status = Game3.statusFromEffect(effect)
    -- TRI ATTACK rolls one of burn, freeze or paralysis; TWINEEDLE poisons.
    if effect == Game3.EFFECT_TRI_ATTACK then
      status = ({ Game3.STATUS_BRN, Game3.STATUS_FRZ,
        Game3.STATUS_PAR })[(self:gbaRandom() % 3) + 1]
    elseif effect == Game3.EFFECT_TWINEEDLE then
      status = Game3.STATUS_PSN
    elseif effect == Game3.EFFECT_POISON_FANG then
      -- setmoveeffect EFFECT_TOXIC -> STATUS1_TOXIC_POISON.
      status = Game3.STATUS_TOXIC
    elseif effect == Game3.EFFECT_THAW_HIT then
      status = Game3.STATUS_BRN
    elseif effect == Game3.EFFECT_SECRET_POWER then
      status = self:secretPowerStatus()
    end
    if status and self:rand(100) <= chance then
      local line = self:applyStatus(defender, status)
      if line then
        texts[#texts + 1] = line
        local sync = self:trySynchronize(defender, attacker, status)
        if sync then texts[#texts + 1] = sync end
      end
    end
    if Game3.isFlinchEffect(effect) and self:rand(100) <= chance
        and not self:hasAbility(defender, Game3.ABILITY_INNER_FOCUS) then
      defender.flinch = true
    end
    if effect == Game3.EFFECT_CONFUSE_HIT and self:rand(100) <= chance then
      local line = self:applyConfuse(defender)
      if line then texts[#texts + 1] = line end
    end
    local downStat, downLabel = Game3.statDownHitSpec(effect)
    if downStat and self:rand(100) <= chance then
      texts[#texts + 1] = self:dropStat(defender, downStat, downLabel)
    end
  end
  if effect == Game3.EFFECT_ALL_STATS_UP_HIT and self:rand(100) <= chance then
    self:allStatsUp(attacker, texts)
  end
  local upStat, upLabel = Game3.statUpHitSpec(effect)
  if upStat and self:rand(100) <= chance then
    texts[#texts + 1] = self:raiseStat(attacker, upStat, 1, upLabel)
  end
  if effect == Game3.EFFECT_KNOCK_OFF and self:rand(100) <= chance then
    local line = self:knockOffItem(attacker, defender, move)
    if line then texts[#texts + 1] = line end
  end
end

function Game3:onContact(attacker, defender, texts)
  if not attacker or not defender or (attacker.hp or 0) <= 0 then return end
  if self:hasAbility(defender, Game3.ABILITY_ROUGH_SKIN) then
    local dmg = math.max(1, math.floor((attacker.maxHp or 1) / 16))
    attacker.hp = math.max(0, (attacker.hp or 0) - dmg)
    texts[#texts + 1] = ("%s was hurt by %s's %s!"):format(
      attacker.name, defender.name, Game3.abilityName(Game3.ABILITY_ROUGH_SKIN))
  end
  if (attacker.hp or 0) <= 0 then return end
  if self:hasAbility(defender, Game3.ABILITY_EFFECT_SPORE)
      and (self:gbaRandom() % 10) == 0 then
    local pick = self:rand(3)
    local status = Game3.STATUS_PSN
    if pick == 2 then status = Game3.STATUS_PAR
    elseif pick == 3 then status = Game3.STATUS_SLP end
    local line = self:applyStatus(attacker, status)
    if line then texts[#texts + 1] = line end
  end
  local function proc(ability, status)
    if self:hasAbility(defender, ability) and self:rand(100) <= 30 then
      local line = self:applyStatus(attacker, status)
      if line then texts[#texts + 1] = line end
    end
  end
  proc(Game3.ABILITY_STATIC, Game3.STATUS_PAR)
  proc(Game3.ABILITY_FLAME_BODY, Game3.STATUS_BRN)
  proc(Game3.ABILITY_POISON_POINT, Game3.STATUS_PSN)
  if self:hasAbility(defender, Game3.ABILITY_CUTE_CHARM)
      and (defender.hp or 0) > 0
      and (self:gbaRandom() % 3) == 0
      and not self:hasAbility(attacker, Game3.ABILITY_OBLIVIOUS)
      and not attacker.infatuatedBy then
    local ag, dg = self:monGender(attacker), self:monGender(defender)
    if ag ~= dg and ag ~= Game3.MON_GENDERLESS
        and dg ~= Game3.MON_GENDERLESS then
      attacker.infatuatedBy = defender
      texts[#texts + 1] = ("%s's %s infatuated %s!"):format(
        defender.name, Game3.abilityName(Game3.ABILITY_CUTE_CHARM),
        attacker.name)
    end
  end
end

-- pokeruby AbilityBattleEffects(ABILITYEFFECT_CONTACT) Color Change.
-- Lives in the CONTACT case but does not check F_MAKES_CONTACT: any
-- damaging hit that is not Struggle, not no-effect, not already that
-- type, and leaves the defender standing.
function Game3:tryColorChange(attacker, defender, move, texts)
  if not defender or not move or type(texts) ~= "table" then return end
  if not self:hasAbility(defender, Game3.ABILITY_COLOR_CHANGE) then return end
  if (move.id or 0) == Game3.MOVE_STRUGGLE then return end
  if (move.power or 0) == 0 then return end
  if (defender.hp or 0) == 0 then return end
  local moveType = self:attackType(attacker, move)
  if (defender.type1 or 0) == moveType then return end
  if (defender.type2 or 0) == moveType then return end
  defender.type1 = moveType
  defender.type2 = moveType
  texts[#texts + 1] = ("%s's %s made it the %s type!"):format(
    defender.name,
    Game3.abilityName(Game3.ABILITY_COLOR_CHANGE),
    Game3.typeName(moveType))
end

function Game3:useMove(attacker, defender, move, extra)
  local texts = extra and {}
    or { ("%s used %s!"):format(attacker.name, move.name or "TACKLE") }
  if self:isPlayerBattler(attacker) then
    local r = self.battleResults
    if r then r.lastUsedMove = tonumber(move and move.id) or 0 end
  end
  -- gLastMoves, which is what Disable, Encore and Mirror Move look up.
  if not extra then attacker.lastMove = tonumber(move and move.id) or 0 end
  local effect = self:moveEffect(move)
  local power = move.power or 0
  local finishing = attacker.charging ~= nil
  if not extra then
    self:clearRageIfOtherMove(attacker, effect)
    if finishing then
      if not (attacker.charging and attacker.charging.kind == "bide") then
        attacker.charging = nil
        attacker.invuln = nil
      end
    elseif (attacker.uproarTurns or 0) < 1 and (attacker.rampage or 0) < 1 then
      move.pp = math.max(0, (move.pp or 1) - self:pressurePpCost(
        attacker, defender, move))
      if effect ~= Game3.EFFECT_PROTECT and effect ~= Game3.EFFECT_ENDURE then
        attacker.protectStreak = 0
      end
    end
    -- MAGIC COAT throws the move back at whoever aimed it, and SNATCH
    -- takes a self-aimed one for its own. Both are one-shot: the flag is
    -- spent whether or not anything else lands.
    if defender and defender.magicCoat and Game3.magicCoatable(move) then
      defender.magicCoat = nil
      texts[#texts + 1] = ("%s bounced the %s back!"):format(
        defender.name, move.name or "move")
      for _, line in ipairs(
          self:useMove(defender, attacker, self:echoMove(move))) do
        texts[#texts + 1] = line
      end
      return texts
    end
    local thief = self:snatcherOf(attacker, move)
    if thief then
      thief.snatch = nil
      texts[#texts + 1] = ("%s snatched %s's move!"):format(
        thief.name, attacker.name)
      for _, line in ipairs(
          self:useMove(thief, thief, self:echoMove(move))) do
        texts[#texts + 1] = line
      end
      return texts
    end
    if effect == Game3.EFFECT_SPLASH then
      texts[#texts + 1] = "But nothing happened!"
      self:armMoveAnim(attacker, defender, move, "status")
      return texts
    end
    if effect == Game3.EFFECT_RESTORE_HP then
      return self:useRestoreHp(attacker, texts, move)
    end
    if effect == Game3.EFFECT_PAIN_SPLIT then
      return self:usePainSplit(attacker, defender, texts)
    end
    if effect == Game3.EFFECT_SUBSTITUTE then
      return self:useSubstitute(attacker, texts)
    end
    if effect == Game3.EFFECT_HAZE then
      return self:useHaze(texts)
    end
    if effect == Game3.EFFECT_BELLY_DRUM then
      return self:useBellyDrum(attacker, texts)
    end
    if effect == Game3.EFFECT_MEAN_LOOK then
      return self:useMeanLook(attacker, defender, texts)
    end
    if effect == Game3.EFFECT_NIGHTMARE then
      return self:useNightmare(attacker, defender, texts)
    end
    if effect == Game3.EFFECT_SAFEGUARD then
      return self:useSafeguard(attacker, texts)
    end
    if effect == Game3.EFFECT_SPIKES then
      return self:useSpikes(attacker, texts)
    end
    if effect == Game3.EFFECT_GRUDGE then
      return self:useGrudge(attacker, texts)
    end
    if effect == Game3.EFFECT_REFRESH then
      return self:useRefresh(attacker, texts)
    end
    if effect == Game3.EFFECT_MINIMIZE then
      return self:useMinimize(attacker, texts)
    end
    if effect == Game3.EFFECT_CAMOUFLAGE then
      return self:useCamouflage(attacker, texts)
    end
    if effect == Game3.EFFECT_TEETER_DANCE then
      return self:useTeeterDance(attacker, texts)
    end
    if effect == Game3.EFFECT_RECYCLE then
      return self:useRecycle(attacker, texts)
    end
    if effect == Game3.EFFECT_CURSE then
      return self:useCurse(attacker, defender, texts)
    end
    if effect == Game3.EFFECT_STOCKPILE then
      return self:useStockpile(attacker, texts)
    end
    if effect == Game3.EFFECT_SWALLOW then
      return self:useSwallow(attacker, texts)
    end
    if effect == Game3.EFFECT_WISH then
      return self:useWish(attacker, texts)
    end
    if effect == Game3.EFFECT_CHARGE then
      return self:useCharge(attacker, texts)
    end
    if effect == Game3.EFFECT_HELPING_HAND then
      return self:useHelpingHand(attacker, texts)
    end
    if effect == Game3.EFFECT_FOLLOW_ME then
      return self:useFollowMe(attacker, texts)
    end
    if effect == Game3.EFFECT_IMPRISON then
      return self:useImprison(attacker, texts)
    end
    if effect == Game3.EFFECT_MAGIC_COAT then
      return self:useMagicCoat(attacker, texts)
    end
    if effect == Game3.EFFECT_SNATCH then
      return self:useSnatch(attacker, texts)
    end
    if effect == Game3.EFFECT_BATON_PASS then
      return self:useBatonPass(attacker, texts)
    end
    -- jumpifnodamage: FOCUS PUNCH is lost if anything got a hit in first.
    if effect == Game3.EFFECT_FOCUS_PUNCH
        and ((attacker.counterPhysical or 0) > 0
          or (attacker.counterSpecial or 0) > 0) then
      texts[#texts + 1] = ("%s lost its focus and couldn't move!")
        :format(attacker.name)
      return texts
    end
    -- ASSIST resolves to a move from the rest of the party and runs it.
    if effect == Game3.EFFECT_ASSIST then
      local called = self:rollAssistMove(attacker)
      if not called then
        texts[#texts + 1] = "But it failed!"
        return texts
      end
      for _, line in ipairs(self:useMove(attacker, defender, called, true)) do
        texts[#texts + 1] = line
      end
      return texts
    end
    if effect == Game3.EFFECT_SOFTBOILED then
      return self:useRestoreHp(attacker, texts, move)
    end
    if effect == Game3.EFFECT_MORNING_SUN or effect == Game3.EFFECT_SYNTHESIS
        or effect == Game3.EFFECT_MOONLIGHT then
      return self:useWeatherHeal(attacker, texts)
    end
    -- These three resolve to a different move and then run it, so the called
    -- move replaces the current one for the rest of this use.
    if effect == Game3.EFFECT_METRONOME or effect == Game3.EFFECT_SLEEP_TALK
        or effect == Game3.EFFECT_MIRROR_MOVE then
      local called
      if effect == Game3.EFFECT_METRONOME then
        called = self:rollMetronomeMove()
      elseif effect == Game3.EFFECT_SLEEP_TALK then
        called = self:rollSleepTalkMove(attacker)
      else
        called = self:mirrorMoveOf(defender)
      end
      if not called then
        texts[#texts + 1] = "But it failed!"
        return texts
      end
      if effect == Game3.EFFECT_METRONOME then
        self:armMoveAnim(attacker, defender, move, "status")
      end
      local row = self.data and self.data.moves and self.data.moves.byId
        and self.data.moves.byId[called.id]
      if row then
        called.power, called.type = row.power, row.type
        called.accuracy, called.effect = row.accuracy, row.effect
        called.secondary, called.name = row.secondary, row.name
      end
      texts[#texts + 1] = self:usedMoveText(0, self:moveName(called.id))
      return self:useMove(attacker, defender, called, true)
    end
    if effect == Game3.EFFECT_TRANSFORM then
      texts = self:useTransform(attacker, defender, texts)
      self:armMoveAnim(attacker, defender, move, "status")
      return texts
    end
    if effect == Game3.EFFECT_MIMIC then
      return self:useMimic(attacker, defender, move, texts)
    end
    if effect == Game3.EFFECT_SKETCH then
      return self:useSketch(attacker, defender, move, texts)
    end
    if effect == Game3.EFFECT_CONVERSION then
      return self:useConversion(attacker, texts)
    end
    if effect == Game3.EFFECT_CONVERSION_2 then
      return self:useConversion2(attacker, texts)
    end
    if effect == Game3.EFFECT_MIST then
      return self:useMist(attacker, texts)
    end
    if effect == Game3.EFFECT_DISABLE then
      return self:useDisable(attacker, defender, texts)
    end
    if effect == Game3.EFFECT_ENCORE then
      return self:useEncore(attacker, defender, texts)
    end
    if effect == Game3.EFFECT_LOCK_ON then
      return self:useLockOn(attacker, defender, texts)
    end
    if effect == Game3.EFFECT_DESTINY_BOND then
      texts = self:useDestinyBond(attacker, texts)
      self:armMoveAnim(attacker, defender, move, "status")
      return texts
    end
    if effect == Game3.EFFECT_REST then
      return self:useRest(attacker, texts)
    end
    if effect == Game3.EFFECT_HEAL_BELL then
      return self:useHealBell(attacker, move, texts)
    end
    if effect == Game3.EFFECT_PERISH_SONG then
      return self:usePerishSong(attacker, move, texts)
    end
    if effect == Game3.EFFECT_INGRAIN then
      return self:useIngrain(attacker, texts)
    end
    local kind = self:weatherKindForEffect(effect)
    if kind then
      local ok, msg = self:setWeather(kind, Game3.WEATHER_TURNS)
      texts[#texts + 1] = msg
      if ok then
        local extra = self:tryForecastForms()
        for i = 1, #extra do texts[#texts + 1] = extra[i] end
        self:armMoveAnim(attacker, defender, move, "status")
      end
      return texts
    end
    if effect == Game3.EFFECT_LIGHT_SCREEN then
      texts[#texts + 1] = self:setSideScreen(attacker, "lightScreen")
      self:armMoveAnim(attacker, defender, move, "status")
      return texts
    end
    if effect == Game3.EFFECT_REFLECT then
      texts[#texts + 1] = self:setSideScreen(attacker, "reflect")
      self:armMoveAnim(attacker, defender, move, "status")
      return texts
    end
    if effect == Game3.EFFECT_MUD_SPORT
        or effect == Game3.EFFECT_WATER_SPORT then
      return self:useSport(attacker, effect, texts)
    end
    if effect == Game3.EFFECT_BIDE then
      return self:useBide(attacker, defender, move, texts)
    end
    if not finishing then
      if effect == Game3.EFFECT_PROTECT then
        return self:useProtect(attacker, texts)
      end
      if effect == Game3.EFFECT_ENDURE then
        return self:useProtect(attacker, texts, true)
      end
      if effect == Game3.EFFECT_FOCUS_ENERGY then
        return self:useFocusEnergy(attacker, texts)
      end
      if effect == Game3.EFFECT_TELEPORT then
        return self:useBattleTeleport(attacker, texts)
      end
      -- atkBF_setdefensecurlbit: the flag Rollout doubles off.
      if effect == Game3.EFFECT_DEFENSE_CURL then
        attacker.defenseCurl = true
      end
      local ups = Game3.statUpSpec(effect)
      if ups then
        for i = 1, #ups do
          local spec = ups[i]
          texts[#texts + 1] = self:raiseStat(attacker, spec[1], spec[2], spec[3])
        end
        self:armMoveAnim(attacker, defender, move, "status")
        return texts
      end
      -- BattleScript for the Hyper Beam family ends in a MOVE_EFFECT that sets
      -- STATUS2_RECHARGE on the attacker, so the *next* turn is the one lost.
      if effect == Game3.EFFECT_RECHARGE then
        attacker.recharge = true
      end
      -- MOVE_EFFECT_WRAP is a no-op while the target is already wrapped.
      if effect == Game3.EFFECT_TRAP and defender
          and (defender.hp or 0) > 0 and (defender.wrapped or 0) < 1 then
        defender.wrapped = Game3.WRAP_MIN_TURNS + (self:gbaRandom() % 4)
        defender.wrappedMoveName = self:moveName(move.id) or "the attack"
        defender.wrappedBy = attacker
        texts[#texts + 1] = ("%s was trapped in the vortex!")
          :format(defender.name or "POKeMON")
      end
      if effect == Game3.EFFECT_RAMPAGE then
        if (attacker.rampage or 0) > 0 then
          attacker.rampage = attacker.rampage - 1
          if attacker.rampage <= 0 then
            -- atk8C_confuseifrepeatingattackends: the user confuses itself
            -- only when the lock expires, never when it is broken early.
            attacker.rampage = nil
            attacker.rampageMove = nil
            local line = self:applyConfuse(attacker)
            if line then
              texts[#texts + 1] = ("%s became confused due to fatigue!")
                :format(attacker.name or "POKeMON")
            end
          end
        else
          attacker.rampage = (Game3.RAMPAGE_MIN_TURNS - 1) + (self:gbaRandom() % 2)
          attacker.rampageMove = move
        end
      end
      local charge = Game3.chargeKind(move)
      if charge and not self:skipsCharge(move) then
        attacker.charging = { move = move, kind = charge }
        if charge == "fly" or charge == "dig" or charge == "dive" then
          attacker.invuln = charge
        end
        texts[#texts + 1] = Game3.chargeText(attacker, charge)
        if charge == "skullbash" then
          texts[#texts + 1] = self:raiseStat(attacker, "def", 1, "DEFENSE")
        end
        -- Wave-4: play charge-half move anim (Dig/Fly/Dive/Solar Beam/Skull Bash).
        self:armMoveAnim(attacker, defender, move, "charge")
        return texts
      end
    end
  end
  local function noteUserFaint()
    if (attacker.hp or 0) > 0 then return end
    local line = ("%s fainted!"):format(attacker.name)
    for i = 1, #texts do
      if texts[i] == line then return end
    end
    texts[#texts + 1] = line
  end
  if effect == Game3.EFFECT_EXPLOSION then
    local damp = self:battlerWithAbility(Game3.ABILITY_DAMP)
    if damp then
      if not extra then
        texts[#texts + 1] = ("%s's %s prevents %s from using %s!"):format(
          damp.name, Game3.abilityName(Game3.ABILITY_DAMP),
          attacker.name, move.name or "EXPLOSION")
      end
      return texts
    end
    if not extra then attacker.hp = 0 end
  end
  if not defender then
    noteUserFaint()
    return texts
  end
  if Game3.isSoundMove(move)
      and self:hasAbility(defender, Game3.ABILITY_SOUNDPROOF) then
    texts[#texts + 1] = ("%s's %s blocks %s!"):format(
      defender.name, Game3.abilityName(Game3.ABILITY_SOUNDPROOF),
      move.name or "the attack")
    noteUserFaint()
    return texts
  end
  if effect == Game3.EFFECT_NATURE_POWER then
    return self:useNaturePower(attacker, defender, texts)
  end
  if defender.protected then
    self:armRage(attacker, effect, false)
    texts[#texts + 1] = ("%s protected itself!"):format(defender.name)
    noteUserFaint()
    return texts
  end
  if effect == Game3.EFFECT_ROAR then
    if self:hasAbility(defender, Game3.ABILITY_SUCTION_CUPS) then
      texts[#texts + 1] = ("%s anchors itself with %s!"):format(
        defender.name, Game3.abilityName(Game3.ABILITY_SUCTION_CUPS))
      return texts
    end
    if defender.rooted then
      texts[#texts + 1] = "But it failed!"
      return texts
    end
  end
  -- BattleScript_EffectEndeavor: setdamagetohealthdifference before
  -- accuracycheck (so Fly / Dig is a miss only when the HP check passes).
  -- jumpifnotfirstturn: Fake Out fails outright after the turn the user
  -- switched in. Snore is the mirror of it -- only usable while asleep.
  if effect == Game3.EFFECT_FAKE_OUT and (attacker.isFirstTurn or 0) < 1 then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  if effect == Game3.EFFECT_SNORE and attacker.status ~= Game3.STATUS_SLP then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  if effect == Game3.EFFECT_DREAM_EATER and defender.status ~= Game3.STATUS_SLP then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  if effect == Game3.EFFECT_ENDEAVOR then
    if (defender.hp or 0) <= (attacker.hp or 0) then
      self:armRage(attacker, effect, false)
      texts[#texts + 1] = "But it failed!"
      return texts
    end
  end
  if defender.invuln and not self:hitsInvuln(move, defender.invuln) then
    self:armRage(attacker, effect, false)
    texts[#texts + 1] = "The attack missed!"
    noteUserFaint()
    return texts
  end
  if effect ~= Game3.EFFECT_OHKO then
    local chance = self:moveHitChance(attacker, defender, move, effect)
    if chance and chance < 100
        and (chance < 1 or self:rand(100) > chance) then
      self:armRage(attacker, effect, false)
      if effect == Game3.EFFECT_LEECH_SEED then
        texts[#texts + 1] = ("%s evaded the attack!"):format(defender.name)
      else
        texts[#texts + 1] = "The attack missed!"
      end
      -- furycuttercalc puts the counter back to nothing on a miss, and
      -- rolloutdamagecalculation cancels the lock outright.
      if effect == Game3.EFFECT_FURY_CUTTER then attacker.furyCutter = nil end
      if effect == Game3.EFFECT_ROLLOUT then
        attacker.rolloutTimer = nil
        attacker.rolloutMove = nil
      end
      -- BattleScript_MoveMissedDoDamage: Jump Kick and Hi Jump Kick keep
      -- going and crash for half of what they would have dealt.
      if effect == Game3.EFFECT_RECOIL_IF_MISS then
        self:crashDamage(attacker, defender, move, texts)
      end
      noteUserFaint()
      return texts
    end
  end
  self:armRage(attacker, effect, true)
  if effect == Game3.EFFECT_OHKO then
    return self:useOhko(attacker, defender, move, texts)
  end
  local absorbed = self:typeAbsorb(defender, move, attacker)
  if absorbed then
    texts[#texts + 1] = absorbed
    return texts
  end
  local hit = false
  if effect == Game3.EFFECT_CONFUSE then
    local line = self:applyConfuse(defender)
    if line then
      texts[#texts + 1] = line
      self:armMoveAnim(attacker, defender, move, "status")
    elseif (defender.confuseTurns or 0) > 0 then
      texts[#texts + 1] = ("%s is already confused!"):format(defender.name)
    elseif self:hasAbility(defender, Game3.ABILITY_OWN_TEMPO) then
      texts[#texts + 1] = ("It doesn't affect %s..."):format(defender.name)
    else
      texts[#texts + 1] = "But it failed!"
    end
    return texts
  end
  if effect == Game3.EFFECT_LEECH_SEED then
    return self:useLeechSeed(attacker, defender, texts)
  end
  if effect == Game3.EFFECT_SPITE then
    return self:useSpite(attacker, defender, texts)
  end
  if effect == Game3.EFFECT_TORMENT then
    return self:useTorment(attacker, defender, texts)
  end
  if effect == Game3.EFFECT_TAUNT then
    return self:useTaunt(attacker, defender, texts)
  end
  if effect == Game3.EFFECT_TICKLE then
    return self:useTickle(attacker, defender, texts)
  end
  if effect == Game3.EFFECT_MEMENTO then
    return self:useMemento(attacker, defender, texts)
  end
  if effect == Game3.EFFECT_SWAGGER or effect == Game3.EFFECT_FLATTER then
    return self:useSwaggerLike(attacker, defender, effect, texts)
  end
  if effect == Game3.EFFECT_PSYCH_UP then
    return self:usePsychUp(attacker, defender, texts)
  end
  if effect == Game3.EFFECT_SKILL_SWAP then
    return self:useSkillSwap(attacker, defender, texts)
  end
  if effect == Game3.EFFECT_ROLE_PLAY then
    return self:useRolePlay(attacker, defender, texts)
  end
  if effect == Game3.EFFECT_TRICK then
    return self:useTrick(attacker, defender, texts)
  end
  if effect == Game3.EFFECT_YAWN then
    return self:useYawn(attacker, defender, texts)
  end
  if effect == Game3.EFFECT_FUTURE_SIGHT then
    return self:useFutureSight(attacker, defender, move, texts)
  end
  -- stockpiletobasedamage jumps to the failure branch on an empty bank.
  if effect == Game3.EFFECT_SPIT_UP and (attacker.stockpile or 0) < 1 then
    texts[#texts + 1] = "But it failed!"
    return texts
  end
  if effect == Game3.EFFECT_FORESIGHT then
    return self:useForesight(attacker, defender, texts)
  end
  if effect == Game3.EFFECT_ATTRACT then
    return self:useAttract(attacker, defender, texts)
  end
  if effect == Game3.EFFECT_ROAR then
    return self:useRoar(attacker, defender, texts)
  end
  -- presentdamagecalculation rolls a byte: three power tiers, or the top
  -- slice which heals the target instead of hitting it.
  if effect == Game3.EFFECT_PRESENT then
    move._presentPower = self:presentRoll()
    if not move._presentPower then
      return self:usePresentHeal(defender, texts)
    end
  end
  -- removelightscreenreflect comes before critcalc in the Brick Break
  -- script, so the screens go whatever the hit ends up doing.
  if effect == Game3.EFFECT_BRICK_BREAK then
    self:breakScreens(defender, texts)
  end
  if power > 0 then
    local hits = self:hitCountFor(effect)
    local total, lastMul, landed = 0, 10, 0
    local critHit, enduredHit = false, false
    for hitIndex = 1, hits do
      if (defender.hp or 0) <= 0 then break end
      -- Triple Kick and Beat Up both need to know which swing this is.
      move._hit = hitIndex
      local result = self:dealDamage(attacker, defender, move)
      lastMul = result.mul
      if result.mul <= 0 then
        texts[#texts + 1] = ("It doesn't affect %s..."):format(defender.name)
        landed = 0
        break
      end
      landed = landed + 1
      total = total + result.dmg
      if result.crit then critHit = true end
      if result.endured then enduredHit = true end
    end
    if landed > 0 then
      hit = true
      self:armMoveAnim(attacker, defender, move, "damage")
      -- atk0E_effectivenesssound after the move anim (queued so SE_M_* plays first)
      self:queueEffectivenessSe(lastMul)
      if critHit then texts[#texts + 1] = "A critical hit!" end
      if lastMul > 10 then texts[#texts + 1] = "It's super effective!" end
      if lastMul < 10 and lastMul > 0 then
        texts[#texts + 1] = "It's not very effective..."
      end
      if enduredHit then
        texts[#texts + 1] = ("%s endured the hit!"):format(defender.name)
      end
      if hits > 1 then
        texts[#texts + 1] = ("Hit %d time%s!"):format(
          landed, landed == 1 and "" or "s")
      end
      if effect == Game3.EFFECT_ABSORB and total > 0 then
        local heal = math.max(1, math.floor(total / 2))
        if self:hasAbility(defender, Game3.ABILITY_LIQUID_OOZE) then
          attacker.hp = math.max(0, (attacker.hp or 0) - heal)
          texts[#texts + 1] = ("It was sucked into %s's %s!"):format(
            defender.name, Game3.abilityName(Game3.ABILITY_LIQUID_OOZE))
        else
          local maxHp = attacker.maxHp or (attacker.hp or 0)
          attacker.hp = math.min(maxHp, (attacker.hp or 0) + heal)
          texts[#texts + 1] = ("%s had its energy drained!"):format(defender.name)
        end
      end
      local denom = Game3.recoilDenom(effect)
      if denom and total > 0 and (attacker.hp or 0) > 0
          and not self:hasAbility(attacker, Game3.ABILITY_ROCK_HEAD) then
        local recoil = math.max(1, math.floor(total / denom))
        attacker.hp = math.max(0, (attacker.hp or 0) - recoil)
        texts[#texts + 1] = ("%s is hit with recoil!"):format(attacker.name)
      end
      if effect == Game3.EFFECT_OVERHEAT then
        texts[#texts + 1] = self:dropStat(attacker, "spa", "SP. ATK", 2, true)
      end
      if effect == Game3.EFFECT_DREAM_EATER and total > 0 then
        self:dreamEaterDrain(attacker, defender, total, texts)
      end
      if effect == Game3.EFFECT_PAY_DAY then
        self:addPayday(attacker)
        texts[#texts + 1] = "Coins scattered everywhere!"
      end
      if effect == Game3.EFFECT_THIEF then
        self:stealItem(attacker, defender, texts)
      end
      if effect == Game3.EFFECT_RAPID_SPIN then
        self:rapidSpinFree(attacker, texts)
      end
      -- MOVE_EFFECT_REMOVE_PARALYSIS is CERTAIN, so Smelling Salts always
      -- wakes the target it just hit twice as hard.
      if effect == Game3.EFFECT_SMELLINGSALT
          and defender.status == Game3.STATUS_PAR then
        defender.status = nil
        texts[#texts + 1] = ("%s was cured of paralysis!"):format(defender.name)
      end
      -- The bank empties on the way out, hit or miss.
      if effect == Game3.EFFECT_SPIT_UP then attacker.stockpile = nil end
      if effect == Game3.EFFECT_SUPERPOWER then
        self:superpowerDrop(attacker, texts)
      end
      if effect == Game3.EFFECT_THAW_HIT and defender.status == Game3.STATUS_FRZ then
        defender.status = nil
        texts[#texts + 1] = ("%s was defrosted!"):format(defender.name)
      end
      self:tickRage(defender, total, texts)
      if effect == Game3.EFFECT_UPROAR and not attacker.uproarTurns then
        attacker.uproarTurns = (self:gbaRandom() % 4) + 2
        attacker.uproarMove = move
        texts[#texts + 1] = ("%s caused an UPROAR!"):format(attacker.name)
      end
    end
  elseif Game3.statDownSpec(effect) then
    return self:useStatDownMove(attacker, defender, move, effect, texts)
  else
    local status = Game3.statusFromEffect(effect)
    if status then
      local line = self:applyStatus(defender, status)
      if line then
        texts[#texts + 1] = line
        self:armMoveAnim(attacker, defender, move, "status")
        local sync = self:trySynchronize(defender, attacker, status)
        if sync then texts[#texts + 1] = sync end
      elseif not self:canStatus(defender, status) and not defender.status then
        texts[#texts + 1] = ("It doesn't affect %s..."):format(defender.name)
      else
        texts[#texts + 1] = "But it failed!"
      end
    else
      texts[#texts + 1] = "But it failed!"
    end
  end
  if hit and (defender.hp or 0) > 0 then
    self:applyHitSecondaries(attacker, defender, move, effect, texts)
    self:tryColorChange(attacker, defender, move, texts)
  end
  if hit and Game3.isContact(move) then
    self:onContact(attacker, defender, texts)
  end
  if (defender.hp or 0) <= 0 then
    texts[#texts + 1] = ("%s fainted!"):format(defender.name)
    self:tryDestinyBond(defender, attacker, texts)
    self:tryGrudge(defender, attacker, move, texts)
    if (attacker.hp or 0) <= 0 then
      texts[#texts + 1] = ("%s fainted!"):format(attacker.name)
    end
  end
  if (attacker.hp or 0) <= 0 then
    texts[#texts + 1] = ("%s fainted!"):format(attacker.name)
  end
  return texts
end

-- battle_util.c AreAllMovesUnusable: when CheckMoveLimitations rules out
-- every slot the battler has no valid move, and battle_main.c then forces
-- gCurrentMove = MOVE_STRUGGLE with HITMARKER_NO_PPDEDUCT. Running out of
-- PP is the case that reaches this in a single battle; the other limiters
-- (Disable, Taunt, Torment, Imprison, Choice Band) narrow the same check.
-- A disabled move is off the table as surely as one with no PP, so it counts
-- toward the "nothing left but Struggle" test too.
function Game3:moveUsable(mon, move)
  if not move then return false end
  -- MOVE_NONE is an empty slot. A move table with no id at all is not one:
  -- that shape only turns up in fixtures, and rejecting it would push a mon
  -- with a full moveset into Struggle.
  if move.id ~= nil and move.id == 0 then return false end
  if (move.pp or 0) <= 0 then return false end
  if mon and mon.disabledMove and move.id and move.id == mon.disabledMove then
    return false
  end
  -- Taunt rules out anything with no power; Torment rules out whatever the
  -- mon used last.
  if mon and (mon.tauntTurns or 0) > 0 and (move.power or 0) < 1 then
    return false
  end
  if mon and mon.tormented and move.id and move.id == mon.lastMove then
    return false
  end
  if self:imprisonedMove(mon, move) then return false end
  return true
end

function Game3:allMovesUnusable(mon)
  local moves = mon and mon.moves
  if type(moves) ~= "table" or #moves < 1 then return false end
  for i = 1, #moves do
    if self:moveUsable(mon, moves[i]) then return false end
  end
  return true
end

-- A fresh Struggle to act with. It is deliberately NOT one of the mon's
-- move slots, which is what makes the ROM's no-PP-deduct behaviour fall
-- out naturally: nothing in the real moveset is touched.
function Game3:struggleMove()
  return self:copyMove(Game3.MOVE_STRUGGLE)
end

-- battle_ai_script_commands.c. Trainers carry a bitfield of AI scripts; each
-- one that is set runs over every move and nudges its score, and the highest
-- score wins with ties broken at random. sBattleAIScriptTable's order is what
-- fixes the bit values.
Game3.AI_CHECK_BAD_MOVE = 1
Game3.AI_CHECK_VIABILITY = 2
Game3.AI_TRY_TO_FAINT = 4
Game3.AI_SETUP_FIRST_TURN = 8
-- Remaining BattleAIs bits (pokeruby data/battle_ai_scripts.s BattleAIs::).
-- Emerald renames bit 5 PreferPowerExtremes and puts AI_DoubleBattle at bit 7
-- (Ruby has AI_Nothing there). We keep Ruby bit order and implement Emerald's
-- DOUBLE_BATTLE script at bit 7 so doubles scoring can opt in.
Game3.AI_RISKY = 16
Game3.AI_PREFER_STRONGEST = 32
Game3.AI_PREFER_BATON_PASS = 64
Game3.AI_DOUBLE_BATTLE = 128
Game3.AI_HP_AWARE = 256
Game3.AI_BASE_SCORE = 100
Game3.AI_SETUP_FIRST_TURN_ROLL = 80
-- AI_TryToFaint branches on this one, which is the only place in the engine
-- that needs Quick Attack by name -- what makes it early is its priority.
Game3.EFFECT_QUICK_ATTACK = 103

-- The moves is_most_powerful_move refuses to call the most powerful, so that a
-- self-destructing or two-turn move never counts as the AI's best option.
Game3.AI_DISCOURAGED_EFFECTS = {
  [Game3.EFFECT_EXPLOSION] = true,
