function Game3:aiTargetFor(mon)
  local b = self.battle
  if not b then return nil end
  if mon == b.enemy or mon == b.enemy2 then
    return Game3.aliveMon(b.player) and b.player or b.player2
  end
  return Game3.aliveMon(b.enemy) and b.enemy or b.enemy2
end

function Game3:aiFlagsFor(mon)
  local b = self.battle
  if not b or not b.isTrainer then return 0 end
  if mon ~= b.enemy and mon ~= b.enemy2 then return 0 end
  local id = b.npc and b.npc.trainerId
  local row = id and self:trainerRow(id)
  return tonumber(row and row.aiFlags) or 0
end

function Game3.aiHasFlag(flags, bit)
  return math.floor((tonumber(flags) or 0) / bit) % 2 == 1
end

-- if_damage_bonus: TypeCalc run against a base of 40, so 0 is an immunity, 10
-- a quarter, 20 a half, 40 neutral, 80 double and 160 quadruple.
function Game3:aiDamageBonus(attacker, defender, move)
  local chart = self.data and self.data.moves and self.data.moves.typeChart
  local moveType = self:attackType(attacker, move)
  local dmg = 40
  local t1 = defender.type1 or 0
  dmg = math.floor(dmg * Game3.chartMul(chart, moveType, t1, defender.foresight) / 10)
  local t2 = defender.type2
  if t2 and t2 ~= t1 then
    dmg = math.floor(dmg * Game3.chartMul(chart, moveType, t2, defender.foresight) / 10)
  end
  -- The ROM folds these back before comparing, so a script only ever sees
  -- one of 0, 10, 20, 40, 80, 160.
  if dmg == 120 then dmg = 80 end
  if dmg == 240 then dmg = 160 end
  if dmg == 30 then dmg = 20 end
  if dmg == 15 then dmg = 10 end
  return dmg
end

-- AI_CalcDmg does not roll: the spread comes from simulatedRNG instead.
function Game3:aiDamageOf(attacker, defender, move)
  if (move.power or 0) < 2 then return 0 end
  local result = self:dealDamage(attacker, defender, move, "ai")
  if (result.mul or 0) <= 0 then return 0 end
  return result.dmg or 0
end

-- is_most_powerful_move sets funcResult to one of three values, and the
-- scripts branch on all three:
--   0  never in the running on power -- a status move, or a discouraged one
--   1  something else in the moveset hits harder
--   2  this is the hardest hitter
-- AI_CheckBadMove skips its ability block only on 0, and AI_TryToFaint
-- docks a point only on 1, so a boolean cannot stand in for it.
function Game3:aiPowerRank(attacker, defender, move, rng, index)
  local effect = self:moveEffect(move)
  if (move.power or 0) <= 1 or Game3.AI_DISCOURAGED_EFFECTS[effect] then
    return 0
  end
  local mine = math.max(1, math.floor(
    self:aiDamageOf(attacker, defender, move) * (rng[index] or 100) / 100))
  for i = 1, #(attacker.moves or {}) do
    local other = attacker.moves[i]
    local oe = other and self:moveEffect(other)
    if other and i ~= index and (other.power or 0) > 1
        and not Game3.AI_DISCOURAGED_EFFECTS[oe] then
      local theirs = math.max(1, math.floor(
        self:aiDamageOf(attacker, defender, other) * (rng[i] or 100) / 100))
      if theirs > mine then return 1 end
    end
  end
  return 2
end

function Game3:aiCanFaint(attacker, defender, move, rng, index)
  if (move.power or 0) < 2 then return false end
  local dmg = math.max(1, math.floor(
    self:aiDamageOf(attacker, defender, move) * (rng[index] or 100) / 100))
  return (defender.hp or 0) <= dmg
end

-- AI_CheckBadMove. The type and ability checks at the top are skipped only for
-- moves that were never in the running on power; every damaging move goes
-- through them. The effect table below runs on everything.
function Game3:aiCheckBadMove(attacker, defender, move, score, rng, index)
  local effect = self:moveEffect(move)
  local bonus = self:aiDamageBonus(attacker, defender, move)

  if self:aiPowerRank(attacker, defender, move, rng, index) ~= 0 then
    if bonus == 0 then return score - 10 end
    local moveType = self:attackType(attacker, move)
    if self:hasAbility(defender, Game3.ABILITY_VOLT_ABSORB)
        and moveType == Game3.TYPE_ELECTRIC then
      return score - 12
    end
    if self:hasAbility(defender, Game3.ABILITY_WATER_ABSORB)
        and moveType == Game3.TYPE_WATER then
      return score - 12
    end
    if self:hasAbility(defender, Game3.ABILITY_FLASH_FIRE)
        and moveType == Game3.TYPE_FIRE then
      return score - 12
    end
    -- CheckIfWonderGuardCancelsMove tests for exactly 80, so a four-times
    -- effective move is discouraged too. That is the cart's behaviour.
    if self:hasAbility(defender, Game3.ABILITY_WONDER_GUARD) and bonus ~= 80 then
      return score - 10
    end
    if self:hasAbility(defender, Game3.ABILITY_LEVITATE)
        and moveType == Game3.TYPE_GROUND then
      return score - 10
    end
  end

  if self:hasAbility(defender, Game3.ABILITY_SOUNDPROOF)
      and Game3.AI_SOUND_MOVES[move.id or 0] then
    return score - 10
  end

  -- AI_CheckBadMove_CheckEffect. Everything here is a reason not to bother.
  local statused = defender.status ~= nil
  if effect == Game3.EFFECT_SLEEP then
    if self:hasAbility(defender, Game3.ABILITY_INSOMNIA)
        or self:hasAbility(defender, Game3.ABILITY_VITAL_SPIRIT)
        or statused then
      return score - 10
    end
  elseif effect == Game3.EFFECT_TOXIC or effect == Game3.EFFECT_POISON then
    if Game3.hasType(defender, Game3.TYPE_STEEL)
        or Game3.hasType(defender, Game3.TYPE_POISON)
        or self:hasAbility(defender, Game3.ABILITY_IMMUNITY) or statused then
      return score - 10
    end
  elseif effect == Game3.EFFECT_PARALYZE then
    if bonus == 0 or self:hasAbility(defender, Game3.ABILITY_LIMBER)
        or statused then
      return score - 10
    end
  elseif effect == Game3.EFFECT_WILL_O_WISP then
    if self:hasAbility(defender, Game3.ABILITY_WATER_VEIL) or statused
        or bonus == 0 or bonus == 20 or bonus == 10 then
      return score - 10
    end
  elseif effect == Game3.EFFECT_CONFUSE then
    if self:hasAbility(defender, Game3.ABILITY_OWN_TEMPO) then
      return score - 10
    end
    if (defender.confuseTurns or 0) > 0 then return score - 5 end
  elseif effect == Game3.EFFECT_EXPLOSION then
    if bonus == 0 or self:hasAbility(defender, Game3.ABILITY_DAMP) then
      return score - 10
    end
  elseif effect == Game3.EFFECT_DREAM_EATER then
    if defender.status ~= Game3.STATUS_SLP then return score - 8 end
    if bonus == 0 then return score - 10 end
  elseif effect == Game3.EFFECT_NIGHTMARE then
    if defender.nightmare then return score - 10 end
    if defender.status ~= Game3.STATUS_SLP then return score - 8 end
  elseif effect == Game3.EFFECT_BELLY_DRUM then
    if (attacker.hp or 0) * 100 < (attacker.maxHp or 1) * 51 then
      return score - 10
    end
  elseif effect == Game3.EFFECT_OHKO then
    if bonus == 0 or self:hasAbility(defender, Game3.ABILITY_STURDY)
        or (defender.level or 0) > (attacker.level or 0) then
      return score - 10
    end
  end

  -- A stat move that cannot move the stat any further is wasted.
  local ups = Game3.statUpSpec(effect)
  if ups then
    local maxed = true
    for i = 1, #ups do
      local spec = ups[i]
      if ((attacker.stages or {})[spec[1]] or 0) < 6 then maxed = false end
    end
    if maxed then return score - 10 end
  end
  local downStat = Game3.statDownSpec(effect)
  if downStat and ((defender.stages or {})[downStat] or 0) <= -6 then
    return score - 10
  end

  return score
end

-- AI_TryToFaint: reach for whatever finishes the job. The Quick Attack label
-- falls through into the +4 rather than jumping past it, so a Quick Attack
-- that can finish is worth +6 -- easy to read as +2 if you stop at the label.
-- The point docked at the end goes to a move something else outdamages.
function Game3:aiTryToFaint(attacker, defender, move, score, rng, index)
  local effect = self:moveEffect(move)
  if self:aiCanFaint(attacker, defender, move, rng, index) then
    if effect == Game3.EFFECT_EXPLOSION then return score end
    if effect == Game3.EFFECT_QUICK_ATTACK then return score + 6 end
    return score + 4
  end
  if self:aiPowerRank(attacker, defender, move, rng, index) == 1 then
    return score - 1
  end
  return score
end

-- AI_SetupFirstTurn: on the turn it comes out, a four-in-five chance of
-- favouring a setup move.
function Game3:aiSetupFirstTurn(attacker, move, score)
  local b = self.battle
  if (b and b.turns or 0) ~= 0 then return score end
  if not Game3.AI_SETUP_EFFECTS[self:moveEffect(move)] then return score end
  if self:rand(100) - 1 < Game3.AI_SETUP_FIRST_TURN_ROLL then return score end
  return score + 2
end


