Game3.AI_RISKY_EFFECTS = {
  [Game3.EFFECT_SLEEP] = true, [Game3.EFFECT_EXPLOSION] = true,
  [Game3.EFFECT_MIRROR_MOVE] = true, [Game3.EFFECT_OHKO] = true,
  [Game3.EFFECT_HIGH_CRITICAL] = true, [Game3.EFFECT_CONFUSE] = true,
  [Game3.EFFECT_METRONOME] = true, [Game3.EFFECT_PSYWAVE] = true,
  [Game3.EFFECT_COUNTER] = true, [Game3.EFFECT_DESTINY_BOND] = true,
  [Game3.EFFECT_SWAGGER] = true, [Game3.EFFECT_ATTRACT] = true,
  [Game3.EFFECT_PRESENT] = true, [Game3.EFFECT_ALL_STATS_UP_HIT] = true,
  [Game3.EFFECT_BELLY_DRUM] = true, [Game3.EFFECT_MIRROR_COAT] = true,
  [Game3.EFFECT_FOCUS_PUNCH] = true, [Game3.EFFECT_REVENGE] = true,
  [Game3.EFFECT_TEETER_DANCE] = true,
}

function Game3:aiRisky(attacker, defender, move, score)
  if defender and self:allyOf(attacker) == defender then
    return score
  end
  local effect = self:moveEffect(move)
  if not Game3.AI_RISKY_EFFECTS[effect] then return score end
  if (self:gbaRandom() % 256) < 128 then return score end
  return score + 2
end

-- Ruby PreferStrongestMove / Emerald PreferPowerExtremes: encourage moves
-- that is_most_powerful_move ranks as 0 (status / discouraged).
function Game3:aiPreferStrongest(attacker, defender, move, score, rng, index)
  if self:aiPowerRank(attacker, defender, move, rng, index) ~= 0 then
    return score
  end
  if (self:gbaRandom() % 256) < 100 then return score end
  return score + 2
end

function Game3:aiUserKnowsEffect(attacker, effectId)
  for i = 1, #(attacker.moves or {}) do
    local m = attacker.moves[i]
    if m and self:moveEffect(m) == effectId then return true end
  end
  return false
end

function Game3:aiCountUsableBench(attacker)
  return #self:aiSwitchCandidates(attacker)
end

-- Ruby AI_PreferBatonPass (simpler than Emerald's expanded version).
function Game3:aiPreferBatonPass(attacker, defender, move, score, rng, index)
  if self:aiCountUsableBench(attacker) < 1 then return score end
  if self:aiPowerRank(attacker, defender, move, rng, index) ~= 0 then
    return score
  end
  if not self:aiUserKnowsEffect(attacker, Game3.EFFECT_BATON_PASS) then
    if (self:gbaRandom() % 256) < 80 then return score end
  end
  if (self:gbaRandom() % 256) < 20 then return score end
  return score + 3
end

-- Emerald AI_DoubleBattle (vanilla pret), applied in doubles. Bit 7 is
-- AI_Nothing on Ruby; we still implement the script and auto-enable it in
-- doubles the way Emerald ORs AI_FLAG_DOUBLE_BATTLE.
function Game3:aiDoubleBattle(attacker, defender, move, score, rng, index)
  local b = self.battle
  if not (b and b.doubles) then return score end
  local partner = self:allyOf(attacker)
  local effect = self:moveEffect(move)
  local moveType = self:attackType(attacker, move)

  -- Targeting the ally.
  if defender and partner and defender == partner then
    local rank = self:aiPowerRank(attacker, defender, move, rng, index)
    if rank ~= 0 then
      -- Fire into Flash Fire partner.
      if moveType == Game3.TYPE_FIRE
          and self:hasAbility(partner, Game3.ABILITY_FLASH_FIRE)
          and not partner.flashFire then
        return score + 3
      end
      return score - 30
    end
    if effect == Game3.EFFECT_SKILL_SWAP then
      if self:hasAbility(defender, Game3.ABILITY_TRUANT) then return score + 10 end
      return score - 30
    end
    if effect == Game3.EFFECT_WILL_O_WISP or effect == Game3.EFFECT_TOXIC then
      if self:hasAbility(defender, Game3.ABILITY_GUTS) and not defender.status
          and (attacker.hp or 0) * 100 >= (attacker.maxHp or 1) * 91 then
        return score + 5
      end
      return score - 30
    end
    if effect == Game3.EFFECT_HELPING_HAND then
      if (self:gbaRandom() % 256) < 64 then return score - 1 end
      return score + 2
    end
    if effect == Game3.EFFECT_SWAGGER then
      return score - 30
    end
    return score - 30
  end

  if effect == Game3.EFFECT_SKILL_SWAP then
    if self:hasAbility(attacker, Game3.ABILITY_TRUANT) then return score + 5 end
    if self:hasAbility(defender, Game3.ABILITY_SHADOW_TAG)
        or self:hasAbility(defender, Game3.ABILITY_PURE_POWER)
        or self:hasAbility(defender, Game3.ABILITY_HUGE_POWER) then
      return score + 2
    end
  end

  if effect == Game3.EFFECT_EARTHQUAKE or effect == Game3.EFFECT_MAGNITUDE then
    if Game3.aliveMon(partner) then
      if self:hasAbility(partner, Game3.ABILITY_LEVITATE)
          or Game3.hasType(partner, Game3.TYPE_FLYING) then
        return score + 2
      end
      for _, t in ipairs({ Game3.TYPE_FIRE, Game3.TYPE_ELECTRIC, Game3.TYPE_POISON,
                           Game3.TYPE_ROCK }) do
        if Game3.hasType(partner, t) then return score - 10 end
      end
      return score - 3
    end
  end

  if moveType == Game3.TYPE_ELECTRIC and Game3.aliveMon(partner) then
    -- Lightning Rod on the opposing partner (target's ally).
    local foePartner = self:allyOf(defender)
    if Game3.aliveMon(foePartner)
        and self:hasAbility(foePartner, Game3.ABILITY_LIGHTNING_ROD) then
      score = score - 2
      if not Game3.hasType(foePartner, Game3.TYPE_GROUND) then
        score = score - 8
      end
    end
  end

  if moveType == Game3.TYPE_FIRE and attacker.flashFire then
    return score + 1
  end

  if self:hasAbility(attacker, Game3.ABILITY_GUTS)
      and Game3.aliveMon(partner)
      and self:aiUserKnowsEffect(partner, Game3.EFFECT_HELPING_HAND) then
    if self:aiPowerRank(attacker, defender, move, rng, index) ~= 0 then
      return score + 1
    end
  elseif attacker.status then
    local rank = self:aiPowerRank(attacker, defender, move, rng, index)
    if rank == 0 then return score - 5 end
    score = score + 1
    if rank == 2 then score = score + 2 end
  end

  return score
end

local function aiHpPct(mon)
  local maxHp = mon and mon.maxHp or 1
  if maxHp < 1 then maxHp = 1 end
  return math.floor(((mon and mon.hp) or 0) * 100 / maxHp)
end

