function Game3:aiHpAware(attacker, defender, move, score)
  local effect = self:moveEffect(move)
  local userHp = aiHpPct(attacker)
  local list
  if userHp > 70 then
    list = Game3.AI_HPA_HIGH
  elseif userHp > 30 then
    list = Game3.AI_HPA_MED
  else
    list = Game3.AI_HPA_LOW
  end
  if list[effect] and (self:gbaRandom() % 256) >= 50 then
    score = score - 2
  end
  local targetHp = aiHpPct(defender)
  local tlist
  if targetHp > 70 then
    tlist = nil -- empty list in the ROM
  elseif targetHp > 30 then
    tlist = Game3.AI_HPA_TARGET_MED
  else
    tlist = Game3.AI_HPA_TARGET_LOW
  end
  if tlist and tlist[effect] and (self:gbaRandom() % 256) >= 50 then
    score = score - 2
  end
  return score
end


-- BattleAI_SetupAIData plus BattleAI_ChooseMoveOrAction: every move opens at
-- 100, anything unselectable drops to 0, each enabled script adjusts the rest,
-- and the best score wins with ties broken at random.
function Game3:aiScoreMoves(mon, target)
  local flags = self:aiFlagsFor(mon)
  -- Emerald ORs AI_FLAG_DOUBLE_BATTLE in doubles; Ruby's bit 7 is AI_Nothing,
  -- so enabling the Emerald DoubleBattle script here only affects doubles.
  local b = self.battle
  if b and b.doubles then
    flags = flags + (Game3.aiHasFlag(flags, Game3.AI_DOUBLE_BATTLE)
      and 0 or Game3.AI_DOUBLE_BATTLE)
  end
  if flags == 0 or not target then return nil end
  local moves = mon.moves or {}
  local scores, rng = {}, {}
  for i = 1, #moves do
    rng[i] = 100 - (self:gbaRandom() % 16)
    scores[i] = self:moveUsable(mon, moves[i]) and Game3.AI_BASE_SCORE or 0
  end
  for i = 1, #moves do
    local move = moves[i]
    if move and scores[i] > 0 then
      if Game3.aiHasFlag(flags, Game3.AI_CHECK_BAD_MOVE) then
        scores[i] = self:aiCheckBadMove(mon, target, move, scores[i], rng, i)
      end
      if Game3.aiHasFlag(flags, Game3.AI_CHECK_VIABILITY) then
        scores[i] = self:aiCheckViability(mon, target, move, scores[i], rng, i)
      end
      if Game3.aiHasFlag(flags, Game3.AI_TRY_TO_FAINT) then
        scores[i] = self:aiTryToFaint(mon, target, move, scores[i], rng, i)
      end
      if Game3.aiHasFlag(flags, Game3.AI_SETUP_FIRST_TURN) then
        scores[i] = self:aiSetupFirstTurn(mon, move, scores[i])
      end
      if Game3.aiHasFlag(flags, Game3.AI_RISKY) then
        scores[i] = self:aiRisky(mon, target, move, scores[i])
      end
      if Game3.aiHasFlag(flags, Game3.AI_PREFER_STRONGEST) then
        scores[i] = self:aiPreferStrongest(mon, target, move, scores[i], rng, i)
      end
      if Game3.aiHasFlag(flags, Game3.AI_PREFER_BATON_PASS) then
        scores[i] = self:aiPreferBatonPass(mon, target, move, scores[i], rng, i)
      end
      if Game3.aiHasFlag(flags, Game3.AI_DOUBLE_BATTLE) then
        scores[i] = self:aiDoubleBattle(mon, target, move, scores[i], rng, i)
      end
      if Game3.aiHasFlag(flags, Game3.AI_HP_AWARE) then
        scores[i] = self:aiHpAware(mon, target, move, scores[i])
      end
    end
  end
  return scores
end

function Game3:aiPickMove(mon, target)
  local scores = self:aiScoreMoves(mon, target)
  if not scores then return nil end
  local best, tied = nil, {}
  for i = 1, #scores do
    if self:moveUsable(mon, mon.moves[i]) then
      if best == nil or scores[i] > best then
        best = scores[i]
        tied = { i }
      elseif scores[i] == best then
        tied[#tied + 1] = i
      end
    end
  end
  if #tied < 1 then return nil end
  return mon.moves[tied[self:rand(#tied)]]
end

-- AI_CheckViability, the third and largest of the four AI scripts: roughly a
-- hundred effects dispatched to seventy branch bodies, each nudging the score
-- by a point or three. The labels below keep the cart's names so the two can
-- be read side by side.
--
-- Two conversions run throughout. The ROM keeps stat stages as 0..12 with 6
-- neutral, while Game3 keeps them as -6..+6, so `stage` adds six. And
-- `if_random_less_than N` is `Random() % 256 < N`, so a bigger N means the
-- branch is taken more often -- usually the branch that does nothing.

