-- The context every branch reads. Building it once a move keeps the branch
-- bodies as close to the script text as they can get.
function Game3:aiViabilityContext(attacker, defender, move, rng, index)
  local self_ = self
  local c = {
    user = attacker,
    foe = defender,
    move = move,
    bonus = self:aiDamageBonus(attacker, defender, move),
    first = self:aiWouldGoFirst(attacker, defender),
    firstTurn = (attacker.isFirstTurn or 0) > 0,
    foeMove = self:aiFoeMove(defender),
  }
  function c.roll(n) return (self_:gbaRandom() % 256) < n end
  function c.hp(mon)
    local maxHp = mon.maxHp or 1
    if maxHp < 1 then return 0 end
    return math.floor(100 * (mon.hp or 0) / maxHp)
  end
  function c.stage(mon, stat) return ((mon.stages or {})[stat] or 0) + 6 end
  function c.statused(mon) return mon.status ~= nil end
  c.rank = function() return self_:aiPowerRank(attacker, defender, move, rng, index) end
  return c
end

-- GetWhoStrikesFirst, which the AI runs with the ignore-priority flag set, so
-- it is a plain speed comparison.
function Game3:aiWouldGoFirst(attacker, defender)
  return self:speedOf(attacker) >= self:speedOf(defender)
end

-- get_move TARGET reads the move the target is expected to use. The engine has
-- no committed choice for the player at this point, so the last one it used is
-- the closest honest stand-in.
function Game3:aiFoeMove(defender)
  local last = defender and defender.lastMove
  if not last or last == 0 then return nil end
  local byId = self.data and self.data.moves and self.data.moves.byId
  return byId and byId[last] or nil
end

function Game3:aiFoeMoveEffect(c)
  return c.foeMove and self:moveEffect(c.foeMove) or nil
end

-- if_move_effect TARGET reads AI_BATTLE_HISTORY's record of what the target
-- has actually used. The engine keeps no such history, so this stands in the
-- target's known moveset -- broader than the cart, never narrower.
function Game3:aiFoeKnowsEffect(defender, effect)
  for i = 1, #((defender and defender.moves) or {}) do
    local mv = defender.moves[i]
    if mv and self:moveEffect(mv) == effect then return true end
  end
  return false
end

-- AI_CV_*. Each takes the running score and hands back what the script leaves.
Game3.AI_CV = {}
local CV = Game3.AI_CV

CV[Game3.EFFECT_SLEEP] = function(self, c, s)
  if self:aiFoeKnowsEffect(c.foe, Game3.EFFECT_DREAM_EATER)
      or self:aiFoeKnowsEffect(c.foe, Game3.EFFECT_NIGHTMARE) then
    if not c.roll(128) then s = s + 1 end
  end
  return s
end

CV[Game3.EFFECT_ABSORB] = function(self, c, s)
  if c.bonus == 20 or c.bonus == 10 then
    if not c.roll(50) then s = s - 3 end
  end
  return s
end

-- AI_CV_SelfKO covers Explosion and Memento alike.
CV[Game3.EFFECT_EXPLOSION] = function(self, c, s)
  local eva = c.stage(c.foe, "eva")
  if eva >= 7 then
    s = s - 1
    if eva >= 10 and not c.roll(128) then s = s - 1 end
  end
  local hp = c.hp(c.user)
  if hp >= 80 and not c.first then
    if c.roll(50) then return s end
    return s - 3
  end
  if hp > 50 then
    if not c.roll(50) then s = s - 1 end
    return s
  end
  if not c.roll(128) then s = s + 1 end
  if hp <= 30 and not c.roll(50) then s = s + 1 end
  return s
end

CV[Game3.EFFECT_MEMENTO] = CV[Game3.EFFECT_EXPLOSION]

CV[Game3.EFFECT_DREAM_EATER] = function(self, c, s)
  if c.bonus == 10 or c.bonus == 20 then return s - 1 end
  return s
end

CV[Game3.EFFECT_MIRROR_MOVE] = function(self, c, s)
  local worth = c.foeMove and Game3.AI_CV_MIRROR_WORTH[c.foeMove.id or 0]
  if c.first then
    if not worth and not c.roll(80) then s = s - 1 end
    return s
  end
  if worth and not c.roll(128) then s = s + 2 end
  return s
end

-- The four "raise one of my own stats" bodies share a shape: discourage once
-- the stage is already high, encourage at full HP, and discourage again when
-- hurt. Only the thresholds differ.
local function statUpBody(stat, cap, hurtRoll)
  return function(self, c, s)
    if c.stage(c.user, stat) >= 9 then
      if not c.roll(100) then s = s - 1 end
    elseif c.hp(c.user) == 100 and not c.roll(128) then
      s = s + 2
    end
    local hp = c.hp(c.user)
    if hp > 70 then return s end
    if hp < 40 then return s - 2 end
    if c.roll(hurtRoll) then return s end
    return s - 2
  end
end

CV[Game3.EFFECT_ATTACK_UP] = statUpBody("atk", 9, 40)
CV[Game3.EFFECT_ATTACK_UP_2] = CV[Game3.EFFECT_ATTACK_UP]
CV[Game3.EFFECT_SPATK_UP] = statUpBody("spa", 9, 70)
CV[Game3.EFFECT_SPATK_UP_2] = CV[Game3.EFFECT_SPATK_UP]

-- Defense and Sp. Def add a look at what the target last threw: raising
-- Defense against a special attacker is wasted, and the other way round.
local function defUpBody(stat, physicalWanted)
  return function(self, c, s)
    if c.stage(c.user, stat) >= 9 then
      if not c.roll(100) then s = s - 1 end
    elseif c.hp(c.user) == 100 and not c.roll(128) then
      s = s + 2
    end
    local hp = c.hp(c.user)
    if hp >= 70 and c.roll(200) then return s end
    if hp < 40 then return s - 2 end
    local power = (c.foeMove and c.foeMove.power) or 0
    if power > 0 then
      local t = (c.foeMove and c.foeMove.type) or 0
      local physical = Game3.AI_CV_PHYSICAL_TYPES[t] and true or false
      if physical ~= physicalWanted then return s - 2 end
    end
    if c.roll(60) then return s end
    return s - 2
  end
end

CV[Game3.EFFECT_DEFENSE_UP] = defUpBody("def", true)
CV[Game3.EFFECT_DEFENSE_UP_2] = CV[Game3.EFFECT_DEFENSE_UP]
CV[Game3.EFFECT_BULK_UP] = CV[Game3.EFFECT_DEFENSE_UP]
CV[Game3.EFFECT_SPDEF_UP] = defUpBody("spd", false)
CV[Game3.EFFECT_SPDEF_UP_2] = CV[Game3.EFFECT_SPDEF_UP]
CV[Game3.EFFECT_COSMIC_POWER] = CV[Game3.EFFECT_SPDEF_UP]
CV[Game3.EFFECT_CALM_MIND] = CV[Game3.EFFECT_SPDEF_UP]

CV[Game3.EFFECT_SPEED_UP] = function(self, c, s)
  if not c.first then return s - 3 end
  if not c.roll(70) then s = s + 3 end
  return s
end
CV[Game3.EFFECT_SPEED_UP_2] = CV[Game3.EFFECT_SPEED_UP]

CV[Game3.EFFECT_EVASION_UP] = function(self, c, s)
  if c.hp(c.user) >= 90 and not c.roll(100) then s = s + 3 end
  if c.stage(c.user, "eva") >= 9 and not c.roll(128) then s = s - 1 end
  -- Anything already ticking away at the target makes stalling worthwhile.
  if Game3.isPoisonStatus(c.foe.status) then
    if c.hp(c.user) > 50 or not c.roll(80) then
      if not c.roll(50) then s = s + 3 end
    end
  end
  if c.foe.leechSeed and not c.roll(70) then s = s + 3 end
  if c.user.rooted and not c.roll(128) then s = s + 2 end
  if c.foe.cursed and not c.roll(70) then s = s + 3 end
  local hp = c.hp(c.user)
  if hp > 70 or c.stage(c.user, "eva") == 6 then return s end
  if hp < 40 or c.hp(c.foe) < 40 then return s - 2 end
  if c.roll(70) then return s end
  return s - 2
end
CV[Game3.EFFECT_MINIMIZE] = CV[Game3.EFFECT_EVASION_UP]
-- The script also routes EVASION_UP_2 here, but no Ruby move carries that
-- effect, so Game3 has no constant for it and there is nothing to hook.

CV[Game3.EFFECT_ALWAYS_HIT] = function(self, c, s)
  local eva, acc = c.stage(c.foe, "eva"), c.stage(c.user, "acc")
  if eva > 10 or acc < 2 then
    s = s + 1
    if not c.roll(100) then s = s + 1 end
    return s
  end
  if eva > 8 or acc < 4 then
    if not c.roll(100) then s = s + 1 end
  end
  return s
end

-- AI_CV_AttackDown and AI_CV_SpAtkDown are the same body with a different
-- stat and type list -- including the ROM's own slip, where SpAtkDown's first
-- test reads ATTACK rather than SP_ATTACK.
local function offenceDownBody(stat, firstStat, types)
  return function(self, c, s)
    if c.stage(c.foe, firstStat) ~= 6 then
      s = s - 1
      if c.hp(c.user) <= 90 then s = s - 1 end
      if c.stage(c.foe, stat) <= 3 + 6 and not c.roll(50) then s = s - 2 end
    end
    if c.hp(c.foe) <= 70 then s = s - 2 end
    if types[c.user.type1 or 0] or types[c.foe.type1 or 0] then return s end
    if c.roll(50) then return s end
    return s - 2
  end
end

CV[Game3.EFFECT_ATTACK_DOWN] =
  offenceDownBody("atk", "atk", Game3.AI_CV_ATTACK_DOWN_TYPES)
CV[Game3.EFFECT_ATTACK_DOWN_2] = CV[Game3.EFFECT_ATTACK_DOWN]
-- if_stat_level_equal TARGET, ATTACK, 6 -- the cart really does read ATTACK
-- here before going on to test SP_ATTACK.
CV[Game3.EFFECT_SPECIAL_ATTACK_DOWN_2] =
  offenceDownBody("spa", "atk", Game3.AI_CV_SPECIAL_TYPES)

local function defenceDownBody(stat)
  return function(self, c, s)
    if c.hp(c.user) >= 70 and c.stage(c.foe, stat) > 3 + 6 then
      -- straight to the target-HP test
    elseif not c.roll(50) then
      s = s - 2
    end
    if c.hp(c.foe) <= 70 then s = s - 2 end
    return s
  end
end

CV[Game3.EFFECT_DEFENSE_DOWN] = defenceDownBody("def")
CV[Game3.EFFECT_DEFENSE_DOWN_2] = CV[Game3.EFFECT_DEFENSE_DOWN]
CV[Game3.EFFECT_TICKLE] = CV[Game3.EFFECT_DEFENSE_DOWN]
CV[Game3.EFFECT_SPECIAL_DEFENSE_DOWN_2] = defenceDownBody("spd")
CV[Game3.EFFECT_EVASION_DOWN] = defenceDownBody("eva")
CV[Game3.EFFECT_EVASION_DOWN_2] = CV[Game3.EFFECT_EVASION_DOWN]

CV[Game3.EFFECT_SPEED_DOWN] = function(self, c, s)
  if not c.first then return s - 3 end
  if not c.roll(70) then s = s + 2 end
  return s
end
CV[Game3.EFFECT_SPEED_DOWN_2] = CV[Game3.EFFECT_SPEED_DOWN]

-- Only these three of the speed-drop-on-hit moves get the treatment.
Game3.AI_CV_SPEED_DOWN_HIT_MOVES = { [196] = true, [317] = true, [341] = true }
CV[Game3.EFFECT_SPEED_DOWN_HIT] = function(self, c, s)
  if not Game3.AI_CV_SPEED_DOWN_HIT_MOVES[c.move.id or 0] then return s end
  return CV[Game3.EFFECT_SPEED_DOWN](self, c, s)
end

CV[Game3.EFFECT_ACCURACY_DOWN] = function(self, c, s)
  if c.hp(c.user) >= 70 and c.hp(c.foe) <= 70 then
    if not c.roll(100) then s = s - 1 end
  end
  if c.stage(c.user, "acc") <= 4 + 6 and not c.roll(80) then s = s - 2 end
  if Game3.isPoisonStatus(c.foe.status) and not c.roll(70) then s = s + 2 end
  if c.foe.leechSeed and not c.roll(70) then s = s + 2 end
  if c.user.rooted and not c.roll(128) then s = s + 1 end
  if c.foe.cursed and not c.roll(70) then s = s + 2 end
  local hp = c.hp(c.user)
  if hp > 70 or c.stage(c.foe, "acc") == 6 then return s end
  if hp < 40 or c.hp(c.foe) < 40 then return s - 2 end
  if c.roll(70) then return s end
  return s - 2
end
CV[Game3.EFFECT_ACCURACY_DOWN_2] = CV[Game3.EFFECT_ACCURACY_DOWN]

CV[Game3.EFFECT_HAZE] = function(self, c, s)
  local mine, theirs = 0, 0
  for _, k in ipairs({ "atk", "def", "spa", "spd", "eva" }) do
    if c.stage(c.user, k) > 8 then mine = mine + 1 end
    if c.stage(c.foe, k) > 8 then theirs = theirs + 1 end
  end
  for _, k in ipairs({ "atk", "def", "spa", "spd", "acc" }) do
    if c.stage(c.foe, k) < 4 then mine = mine + 1 end
    if c.stage(c.user, k) < 4 then theirs = theirs + 1 end
  end
  -- Anything the user has built up, or has taken off the target, is thrown
  -- away by its own Haze.
  if mine > 0 and not c.roll(50) then s = s - 3 end
  if theirs > 0 then
    if not c.roll(50) then s = s + 3 end
    return s
  end
  if not c.roll(50) then s = s - 1 end
  return s
end

CV[Game3.EFFECT_BIDE] = function(self, c, s)
  if c.hp(c.user) <= 90 then return s - 2 end
  return s
end

CV[Game3.EFFECT_ROAR] = function(self, c, s)
  local any = false
  for _, k in ipairs({ "atk", "def", "spa", "spd", "eva" }) do
    if c.stage(c.foe, k) > 8 then any = true end
  end
  if not any then return s - 3 end
  if not c.roll(128) then s = s + 2 end
  return s
end

CV[Game3.EFFECT_CONVERSION] = function(self, c, s)
  if c.hp(c.user) <= 90 then s = s - 2 end
  if not c.firstTurn and c.roll(200) then s = s - 2 end
  return s
end

-- AI_CV_Heal, which Softboiled, Swallow and the weather healers all reach.
local function healBody(self, c, s)
  if c.hp(c.user) == 100 then return s - 3 end
  if not c.first then return s - 8 end
  if c.hp(c.user) >= 70 and c.roll(30) == false then
    -- falls into the encouraging branch
  elseif c.hp(c.user) >= 70 then
    return s - 3
  end
  if self:aiFoeKnowsEffect(c.foe, Game3.EFFECT_SNATCH) and c.roll(100) then
    return s
  end
  if c.roll(20) then return s end
  return s + 2
end

CV[Game3.EFFECT_RESTORE_HP] = healBody
CV[Game3.EFFECT_SOFTBOILED] = healBody
CV[Game3.EFFECT_SWALLOW] = healBody

local function healWeatherBody(self, c, s)
  local w = self.battle and self.battle.weather
  if w and w ~= 0 and w ~= Game3.WEATHER_SUN then s = s - 2 end
  return healBody(self, c, s)
end
CV[Game3.EFFECT_MORNING_SUN] = healWeatherBody
CV[Game3.EFFECT_SYNTHESIS] = healWeatherBody
CV[Game3.EFFECT_MOONLIGHT] = healWeatherBody

-- AI_CV_Toxic, which Leech Seed shares: a slow burn is only worth it when
-- there is time left to collect on it.
local function toxicBody(self, c, s)
  if c.hp(c.user) <= 50 and not c.roll(50) then s = s - 3 end
  if c.hp(c.foe) <= 50 and not c.roll(50) then s = s - 3 end
  if self:aiFoeKnowsEffect(c.user, Game3.EFFECT_SPDEF_UP)
      or self:aiFoeKnowsEffect(c.user, Game3.EFFECT_PROTECT) then
    if not c.roll(60) then s = s + 2 end
  end
  return s
end
CV[Game3.EFFECT_TOXIC] = toxicBody
CV[Game3.EFFECT_LEECH_SEED] = toxicBody

local function screenBody(types)
  return function(self, c, s)
    if c.hp(c.user) < 50 then return s - 2 end
    if types[c.user.type1 or 0] or types[c.foe.type1 or 0] then return s end
    if c.roll(50) then return s end
    return s - 2
  end
end
CV[Game3.EFFECT_LIGHT_SCREEN] = screenBody(Game3.AI_CV_SPECIAL_TYPES)
CV[Game3.EFFECT_REFLECT] = screenBody(Game3.AI_CV_PHYSICAL_TYPES)

CV[Game3.EFFECT_REST] = function(self, c, s)
  if not c.first then
    if c.hp(c.user) == 100 then return s - 8 end
    if c.hp(c.user) >= 40 then
      if c.hp(c.user) > 50 or c.roll(70) == false then return s - 3 end
    end
  else
    if c.hp(c.user) >= 60 then
      if c.hp(c.user) > 70 or c.roll(50) == false then return s - 3 end
    end
  end
  if self:aiFoeKnowsEffect(c.foe, Game3.EFFECT_SNATCH) and c.roll(50) then
    return s
  end
  if c.roll(10) then return s end
  return s + 3
end

CV[Game3.EFFECT_SUPER_FANG] = function(self, c, s)
  if c.hp(c.foe) <= 50 then return s - 1 end
  return s
end

-- Trapping is worth a point when something else is already draining them.
local function trapBody(self, c, s)
  if Game3.isPoisonStatus(c.foe.status) or c.foe.cursed
      or (c.foe.perishSong or 0) > 0 or c.foe.infatuated then
    if not c.roll(128) then s = s + 1 end
  end
  return s
end
CV[Game3.EFFECT_TRAP] = trapBody
CV[Game3.EFFECT_MEAN_LOOK] = trapBody

CV[Game3.EFFECT_HIGH_CRITICAL] = function(self, c, s)
  if c.bonus == 10 or c.bonus == 20 then return s end
  if c.bonus == 80 or c.bonus == 160 then
    if not c.roll(128) then s = s + 1 end
    return s
  end
  if c.roll(128) then return s end
  if not c.roll(128) then s = s + 1 end
  return s
end
CV[Game3.EFFECT_BLAZE_KICK] = CV[Game3.EFFECT_HIGH_CRITICAL]
CV[Game3.EFFECT_POISON_TAIL] = CV[Game3.EFFECT_HIGH_CRITICAL]

local function confuseBody(self, c, s)
  local hp = c.hp(c.foe)
  if hp > 70 then return s end
  if not c.roll(128) then s = s - 1 end
  if hp > 50 then return s end
  s = s - 1
  if hp > 30 then return s end
  return s - 1
end
CV[Game3.EFFECT_CONFUSE] = confuseBody
CV[Game3.EFFECT_FLATTER] = function(self, c, s)
  if not c.roll(128) then s = s + 1 end
  return confuseBody(self, c, s)
end

CV[Game3.EFFECT_POISON] = function(self, c, s)
  if c.hp(c.user) < 50 or c.hp(c.foe) <= 50 then return s - 1 end
  return s
end

CV[Game3.EFFECT_PARALYZE] = function(self, c, s)
  if not c.first then
    if c.hp(c.user) <= 70 then s = s - 1 end
    return s
  end
  if not c.roll(20) then s = s + 3 end
  return s
end

CV[Game3.EFFECT_VITAL_THROW] = function(self, c, s)
  if c.first or c.hp(c.user) > 60 then return s end
  if c.hp(c.user) >= 40 and c.roll(180) then return s end
  if c.roll(50) then return s end
  return s - 1
end

CV[Game3.EFFECT_SUBSTITUTE] = function(self, c, s)
  local hp = c.hp(c.user)
  if hp <= 50 and c.roll(100) == false then s = s - 1 end
  if hp <= 70 and c.roll(100) == false then s = s - 1 end
  if hp <= 90 and c.roll(100) == false then s = s - 1 end
  if not c.first then return s end
  -- Worth putting up when the target is winding up something it can no longer
  -- land through the doll.
  local fe = self:aiFoeMoveEffect(c)
  local blocks = false
  if fe == Game3.EFFECT_SLEEP or fe == Game3.EFFECT_TOXIC
      or fe == Game3.EFFECT_POISON or fe == Game3.EFFECT_PARALYZE
      or fe == Game3.EFFECT_WILL_O_WISP then
    blocks = not c.statused(c.foe)
  elseif fe == Game3.EFFECT_CONFUSE then
    blocks = (c.foe.confuseTurns or 0) < 1
  elseif fe == Game3.EFFECT_LEECH_SEED then
    blocks = not c.foe.leechSeed
  end
  if blocks and not c.roll(100) then s = s + 1 end
  return s
end

CV[Game3.EFFECT_RECHARGE] = function(self, c, s)
  if c.bonus == 10 or c.bonus == 20 then return s - 1 end
  if not c.first then
    if c.hp(c.user) > 40 then return s - 1 end
    return s
  end
  if c.hp(c.user) < 60 then return s end
  return s - 1
end

CV[Game3.EFFECT_DISABLE] = function(self, c, s)
  if c.first then return s end
  if ((c.foeMove and c.foeMove.power) or 0) ~= 0 then return s + 1 end
  if c.roll(100) then return s end
  return s - 1
end

-- Counter and Mirror Coat share a body, differing only in which types of
-- incoming move they are waiting for.
local function counterBody(types)
  return function(self, c, s)
    if c.foe.status == Game3.STATUS_SLP or c.foe.infatuated
        or (c.foe.confuseTurns or 0) > 0 then
      return s - 1
    end
    if c.hp(c.user) <= 30 and not c.roll(10) then s = s - 1 end
    if c.hp(c.user) <= 50 and not c.roll(100) then s = s - 1 end
    local power = (c.foeMove and c.foeMove.power) or 0
    if power ~= 0 then
      if (c.user.tauntTurns or 0) > 0 and not c.roll(100) then s = s + 1 end
      local t = (c.foeMove and c.foeMove.type) or 0
      if not types[t] then return s - 1 end
      if c.roll(100) then return s end
      return s + 1
    end
    if (c.user.tauntTurns or 0) > 0 and not c.roll(100) then s = s + 1 end
    if types[c.user.type1 or 0] or types[c.foe.type1 or 0] then return s end
    if c.roll(50) then return s end
    return s - 1
  end
end
CV[Game3.EFFECT_COUNTER] = counterBody(Game3.AI_CV_PHYSICAL_TYPES)
CV[Game3.EFFECT_MIRROR_COAT] = counterBody(Game3.AI_CV_SPECIAL_TYPES)

CV[Game3.EFFECT_ENCORE] = function(self, c, s)
  local worthy = false
  if ((c.foeMove and c.foeMove.power) or 0) == 0 then
    worthy = true
  elseif c.first then
    worthy = Game3.AI_CV_ENCORE_EFFECTS[self:aiFoeMoveEffect(c) or -1] or false
  end
  if not worthy then return s - 2 end
  if c.roll(30) then return s end
  return s + 3
end

CV[Game3.EFFECT_PAIN_SPLIT] = function(self, c, s)
  if c.hp(c.foe) < 80 then return s - 1 end
  if c.first then
    if c.hp(c.user) > 60 then return s - 1 end
    return s + 1
  end
  if c.hp(c.user) > 40 then return s - 1 end
  return s + 1
end

CV[Game3.EFFECT_SNORE] = function(self, c, s) return s + 2 end
CV[Game3.EFFECT_SLEEP_TALK] = function(self, c, s) return s + 2 end
CV[Game3.EFFECT_FAKE_OUT] = function(self, c, s) return s + 2 end

CV[Game3.EFFECT_LOCK_ON] = function(self, c, s)
  if not c.roll(128) then s = s + 2 end
  return s
end

CV[Game3.EFFECT_DESTINY_BOND] = function(self, c, s)
  s = s - 1
  if c.first or c.hp(c.user) > 70 then return s end
  if not c.roll(128) then s = s + 1 end
  if c.hp(c.user) > 50 then return s end
  if not c.roll(128) then s = s + 1 end
  if c.hp(c.user) > 30 then return s end
  if c.roll(100) then return s end
  return s + 2
end

CV[Game3.EFFECT_FLAIL] = function(self, c, s)
  local hp = c.hp(c.user)
  if c.first then
    if hp > 60 then return s - 1 end
    if hp > 40 then return s end
  else
    if hp > 33 then return s - 1 end
    if hp > 20 then return s end
    if hp < 8 then s = s + 1 end
  end
  if c.roll(100) then return s end
  return s + 1
end

CV[Game3.EFFECT_HEAL_BELL] = function(self, c, s)
  if c.statused(c.user) then return s end
  for i = 1, #(self.party or {}) do
    local mon = self.party[i]
    if mon and mon.status then return s end
  end
  return s - 5
end

CV[Game3.EFFECT_THIEF] = function(self, c, s)
  local hold = self:holdEffectOf(c.foe)
  if not Game3.AI_CV_THIEF_HOLD_EFFECTS[hold or -1] then return s - 2 end
  if c.roll(50) then return s end
  return s + 1
end

CV[Game3.EFFECT_CURSE] = function(self, c, s)
  if Game3.hasType(c.user, Game3.TYPE_GHOST)
      or Game3.hasType(c.foe, Game3.TYPE_GHOST) then
    if c.hp(c.user) <= 80 then return s - 1 end
    return s
  end
  local def = c.stage(c.user, "def")
  if def > 9 then return s end
  if not c.roll(128) then s = s + 1 end
  if def > 7 then return s end
  if not c.roll(128) then s = s + 1 end
  if def > 6 then return s end
  if not c.roll(128) then s = s + 1 end
  return s
end

CV[Game3.EFFECT_PROTECT] = function(self, c, s)
  local lockOn = self:aiFoeMoveEffect(c) == Game3.EFFECT_LOCK_ON
  if (c.user.protectStreak or 0) > 1 then return s - 2 end
  -- Anything already eating the user makes stalling a bad idea; anything
  -- eating the target makes it a good one.
  local userBleeding = Game3.isPoisonStatus(c.user.status) or c.user.cursed
    or (c.user.perishSong or 0) > 0 or c.user.infatuated or c.user.leechSeed
    or (c.user.yawnTurns or 0) > 0
    or self:aiFoeKnowsEffect(c.foe, Game3.EFFECT_RESTORE_HP)
    or self:aiFoeKnowsEffect(c.foe, Game3.EFFECT_DEFENSE_CURL)
  if userBleeding then
    if not lockOn then return s end
    return s - 2
  end
  local foeBleeding = Game3.isPoisonStatus(c.foe.status) or c.foe.cursed
    or (c.foe.perishSong or 0) > 0 or c.foe.infatuated or c.foe.leechSeed
    or (c.foe.yawnTurns or 0) > 0
  if foeBleeding or not lockOn then s = s + 2 end
  if (c.user.protectStreak or 0) == 0 then return s end
  s = s - 1
  if c.roll(128) then return s end
  return s - 1
end
CV[Game3.EFFECT_ENDURE] = function(self, c, s)
  local hp = c.hp(c.user)
  if hp < 4 or hp >= 35 then return s - 1 end
  if c.roll(70) then return s end
  return s + 1
end

CV[Game3.EFFECT_FORESIGHT] = function(self, c, s)
  if Game3.hasType(c.user, Game3.TYPE_GHOST)
      or Game3.hasType(c.foe, Game3.TYPE_GHOST) then
    if c.roll(80) then return s end
  elseif c.stage(c.user, "eva") <= 8 then
    return s - 2
  end
  if c.roll(80) then return s end
  return s + 2
end

CV[Game3.EFFECT_BATON_PASS] = function(self, c, s)
  local built = false
  for _, k in ipairs({ "atk", "def", "spa", "spd", "eva" }) do
    if c.stage(c.user, k) > 8 then built = true end
  end
  if built then
    if c.first and c.hp(c.user) > 70 then return s end
    if not c.first and c.hp(c.user) > 60 then return s end
    if c.roll(80) then return s end
    return s + 2
  end
  local some = false
  for _, k in ipairs({ "atk", "def", "spa", "spd", "eva" }) do
    if c.stage(c.user, k) > 7 then some = true end
  end
  if not some then return s - 2 end
  if c.first then
    if c.hp(c.user) < 70 then return s end
    return s - 2
  end
  if c.hp(c.user) > 60 then return s - 2 end
  return s
end

CV[Game3.EFFECT_PURSUIT] = function(self, c, s)
  if not c.firstTurn then return s end
  local t = { Game3.TYPE_GHOST, Game3.TYPE_PSYCHIC }
  local worth = false
  for _, ty in ipairs(t) do
    if (c.user.type1 or 0) == ty or (c.foe.type1 or 0) == ty then worth = true end
  end
  if not worth then return s end
  if c.roll(128) then return s end
  return s + 1
end

CV[Game3.EFFECT_RAIN_DANCE] = function(self, c, s)
  local w = self.battle and self.battle.weather
  if not c.first or self:hasAbility(c.user, Game3.ABILITY_SWIFT_SWIM) then
    if self:hasAbility(c.user, Game3.ABILITY_SWIFT_SWIM) then return s + 1 end
  end
  if c.hp(c.user) < 40 then return s - 1 end
  if (w and w ~= 0 and w ~= Game3.WEATHER_RAIN)
      or self:hasAbility(c.user, Game3.ABILITY_RAIN_DISH) then
    return s + 1
  end
  return s
end

CV[Game3.EFFECT_SUNNY_DAY] = function(self, c, s)
  if c.hp(c.user) < 40 then return s - 1 end
  local w = self.battle and self.battle.weather
  if w and w ~= 0 and w ~= Game3.WEATHER_SUN then return s + 1 end
  return s
end

CV[Game3.EFFECT_HAIL] = function(self, c, s)
  if c.hp(c.user) < 40 then return s - 1 end
  local w = self.battle and self.battle.weather
  if w and w ~= 0 and w ~= Game3.WEATHER_HAIL then return s + 1 end
  return s
end

CV[Game3.EFFECT_BELLY_DRUM] = function(self, c, s)
  if c.hp(c.user) < 90 then return s - 2 end
  return s
end

CV[Game3.EFFECT_PSYCH_UP] = function(self, c, s)
  local worth = false
  for _, k in ipairs({ "atk", "def", "spa", "spd", "eva" }) do
    if c.stage(c.foe, k) > 8 then worth = true end
  end
  if not worth then return s - 2 end
  local behind = false
  for _, k in ipairs({ "atk", "def", "spa", "spd" }) do
    if c.stage(c.user, k) < 7 then behind = true end
  end
  if behind then
    if c.roll(128) then return s end
    return s + 1
  end
  if c.stage(c.user, "eva") < 7 then
    s = s + 1
    if c.roll(128) then return s end
    return s + 1
  end
  if c.roll(50) then return s end
  return s - 2
end

local function chargeUpBody(self, c, s)
  if c.bonus == 10 or c.bonus == 20 then return s - 2 end
  if self:aiFoeKnowsEffect(c.foe, Game3.EFFECT_PROTECT) then return s - 2 end
  if c.hp(c.user) > 38 then return s end
  return s - 1
end
CV[Game3.EFFECT_RAZOR_WIND] = chargeUpBody
CV[Game3.EFFECT_SKY_ATTACK] = chargeUpBody
CV[Game3.EFFECT_SKULL_BASH] = chargeUpBody
CV[Game3.EFFECT_SOLARBEAM] = chargeUpBody

CV[Game3.EFFECT_FLY] = function(self, c, s)
  if self:aiFoeKnowsEffect(c.foe, Game3.EFFECT_PROTECT) then return s - 1 end
  local worth = Game3.isPoisonStatus(c.foe.status) or c.foe.cursed
    or c.foe.leechSeed
  local w = self.battle and self.battle.weather
  if not worth and w == Game3.WEATHER_HAIL then
    worth = Game3.AI_CV_FLY_TYPES[c.user.type2 or 0]
      or Game3.AI_CV_FLY_TYPES[c.foe.type2 or 0] or false
  elseif not worth and w == Game3.WEATHER_SAND then
    worth = (c.user.type2 or 0) == Game3.TYPE_ICE
      or (c.foe.type2 or 0) == Game3.TYPE_ICE
  end
  if not worth then
    if c.first then return s end
    if self:aiFoeMoveEffect(c) == Game3.EFFECT_LOCK_ON then return s end
  end
  if c.roll(80) then return s end
  return s + 1
end

CV[Game3.EFFECT_SPIT_UP] = function(self, c, s)
  if (c.user.stockpile or 0) < 2 then return s end
  if c.roll(80) then return s end
  return s + 2
end

CV[Game3.EFFECT_FACADE] = function(self, c, s)
  local st = c.foe.status
  if Game3.isPoisonStatus(st) or st == Game3.STATUS_BRN
      or st == Game3.STATUS_PAR then
    return s + 1
  end
  return s
end

CV[Game3.EFFECT_FOCUS_PUNCH] = function(self, c, s)
  if c.bonus == 10 or c.bonus == 20 then return s - 1 end
  if c.foe.status == Game3.STATUS_SLP then return s + 1 end
  if c.foe.infatuated or (c.foe.confuseTurns or 0) > 0 then
    if c.roll(100) then return s end
    return s + 1
  end
  if c.firstTurn then return s end
  if c.roll(100) then return s end
  return s + 1
end

CV[Game3.EFFECT_SMELLINGSALT] = function(self, c, s)
  if c.foe.status == Game3.STATUS_PAR then return s + 1 end
  return s
end

CV[Game3.EFFECT_ROLE_PLAY] = function(self, c, s)
  if Game3.AI_CV_ABILITIES_TO_COPY[c.user.ability or 0] then return s - 1 end
  if not Game3.AI_CV_ABILITIES_TO_COPY[c.foe.ability or 0] then return s - 1 end
  if c.roll(50) then return s end
  return s + 2
end
CV[Game3.EFFECT_SKILL_SWAP] = CV[Game3.EFFECT_ROLE_PLAY]

CV[Game3.EFFECT_TRICK] = function(self, c, s)
  local mine = self:holdEffectOf(c.user) or 0
  local theirs = self:holdEffectOf(c.foe) or 0
  if Game3.AI_CV_TRICK_PRIZE[mine] then
    -- Trading a Choice Band for a Choice Band gains nothing.
    if Game3.AI_CV_TRICK_PRIZE[theirs] then return s - 3 end
    return s + 5
  end
  if not Game3.AI_CV_TRICK_JUNK[mine] then return s - 3 end
  if Game3.AI_CV_TRICK_JUNK[theirs] then return s - 3 end
  if c.roll(50) then return s end
  return s + 2
end

CV[Game3.EFFECT_SNATCH] = function(self, c, s)
  local worthTaking = self:aiFoeKnowsEffect(c.foe, Game3.EFFECT_RESTORE_HP)
    or self:aiFoeKnowsEffect(c.foe, Game3.EFFECT_DEFENSE_CURL)
  if c.firstTurn then
    if c.roll(150) then return s end
    return s + 2
  end
  if c.roll(30) then return s end
  local discourage
  if c.first then
    if c.hp(c.foe) > 25 then
      discourage = true
    elseif worthTaking then
      if c.roll(150) then return s end
      return s + 2
    else
      if not c.roll(230) then return s + 1 end
      discourage = true
    end
  else
    if c.hp(c.user) ~= 100 or c.hp(c.foe) < 70 then
      discourage = true
    elseif c.roll(60) then
      return s
    else
      discourage = true
    end
  end
  if discourage then
    if c.roll(30) then return s end
    return s - 2
  end
  return s
end

CV[Game3.EFFECT_SUPERPOWER] = function(self, c, s)
  if c.bonus == 10 or c.bonus == 20 then return s - 1 end
  if c.stage(c.user, "atk") < 6 then return s - 1 end
  if c.first then
    if c.hp(c.user) < 60 then return s end
    return s - 1
  end
  if c.hp(c.user) > 40 then return s - 1 end
  return s
end

CV[Game3.EFFECT_MAGIC_COAT] = function(self, c, s)
  if c.hp(c.foe) <= 30 and not c.roll(100) then s = s - 1 end
  if c.firstTurn then
    if c.roll(150) then return s end
    return s + 1
  end
  if c.roll(30) then return s end
  return s - 1
end

CV[Game3.EFFECT_RECYCLE] = function(self, c, s)
  if (tonumber(c.user.usedItem) or 0) == 0 then return s - 2 end
  if c.roll(50) then return s end
  return s + 1
end

CV[Game3.EFFECT_REVENGE] = function(self, c, s)
  if c.foe.status == Game3.STATUS_SLP or c.foe.infatuated
      or (c.foe.confuseTurns or 0) > 0 or c.roll(180) then
    return s - 2
  end
  return s + 2
end

CV[Game3.EFFECT_BRICK_BREAK] = function(self, c, s)
  local screens = self.battle and self.battle.screens
  local row = screens and screens[self:screenSide(c.foe)]
  if type(row) == "table" and (row.reflect or 0) > 0 then return s + 1 end
  return s
end

CV[Game3.EFFECT_KNOCK_OFF] = function(self, c, s)
  if c.hp(c.foe) < 30 or c.firstTurn or c.roll(180) then return s end
  return s + 1
end

CV[Game3.EFFECT_ENDEAVOR] = function(self, c, s)
  if c.hp(c.foe) < 70 then return s - 1 end
  if c.first then
    if c.hp(c.user) > 50 then return s - 1 end
    return s + 1
  end
  if c.hp(c.user) > 40 then return s - 1 end
  return s + 1
end

CV[Game3.EFFECT_ERUPTION] = function(self, c, s)
  if c.bonus == 10 or c.bonus == 20 then return s - 1 end
  if c.first then
    if c.hp(c.foe) > 70 then return s end
    return s - 1
  end
  if c.hp(c.foe) > 50 then return s end
  return s - 1
end

CV[Game3.EFFECT_IMPRISON] = function(self, c, s)
  if c.firstTurn or c.roll(100) then return s end
  return s + 2
end

CV[Game3.EFFECT_REFRESH] = function(self, c, s)
  if c.hp(c.foe) < 50 then return s - 1 end
  return s
end

CV[Game3.EFFECT_MUD_SPORT] = function(self, c, s)
  if c.hp(c.user) < 50 then return s - 1 end
  if (c.user.type1 or 0) == Game3.TYPE_ELECTRIC
      or (c.foe.type1 or 0) == Game3.TYPE_ELECTRIC then
    return s + 1
  end
  return s - 1
end

CV[Game3.EFFECT_WATER_SPORT] = function(self, c, s)
  if c.hp(c.user) < 50 then return s - 1 end
  if (c.user.type1 or 0) == Game3.TYPE_FIRE
      or (c.foe.type1 or 0) == Game3.TYPE_FIRE then
    return s + 1
  end
  return s - 1
end

CV[Game3.EFFECT_OVERHEAT] = function(self, c, s)
  if c.bonus == 10 or c.bonus == 20 then return s - 1 end
  if c.first then
    if c.hp(c.user) > 80 then return s end
    return s - 1
  end
  if c.hp(c.user) > 60 then return s end
  return s - 1
end

CV[Game3.EFFECT_DRAGON_DANCE] = function(self, c, s)
  if c.first then
    if c.roll(128) then return s end
    return s + 1
  end
  if c.hp(c.user) > 50 or c.roll(70) then return s end
  return s - 1
end

CV[Game3.EFFECT_OHKO] = function(self, c, s) return s end

function Game3:aiCheckViability(attacker, defender, move, score, rng, index)
  local fn = Game3.AI_CV[self:moveEffect(move)]
  if not fn then return score end
  local c = self:aiViabilityContext(attacker, defender, move, rng, index)
  return fn(self, c, score)
end

function Game3:pickEnemyMove(mon)
  if mon and (mon.uproarTurns or 0) > 0 and mon.uproarMove then
    return mon.uproarMove
  end
  if mon and (mon.rampage or 0) > 0 and mon.rampageMove then
    return mon.rampageMove
  end
  -- Rollout sets STATUS2_MULTIPLETURNS and gLockedMoves the same way a
  -- rampage does, so the mon keeps rolling until the timer runs out.
  if mon and (mon.rolloutTimer or 0) > 0 and mon.rolloutMove then
    return mon.rolloutMove
  end
  if mon and (mon.encoreTurns or 0) > 0 and mon.encoreMove then
    return mon.encoreMove
  end
  if mon and mon.charging and mon.charging.move then
    return mon.charging.move
  end
  local moves = mon.moves or {}
  local damaging = {}
  local ready = {}
  for i = 1, #moves do
    local m = moves[i]
    if self:moveUsable(mon, m) then
      ready[#ready + 1] = m
      if (m.power or 0) > 0 then damaging[#damaging + 1] = m end
    end
  end
  local pool = #damaging > 0 and damaging or ready
  -- Out of PP the ROM forces Struggle, not some arbitrary move.
  if #pool < 1 then return self:struggleMove() end
  -- A trainer with AI flags scores its moves; a wild mon and the eight
  -- trainers with no flags at all still pick at random, as the cart does.
  local target = self:aiTargetFor(mon)
  local scored = target and self:aiPickMove(mon, target)
  if scored then return scored end
  return pool[self:rand(#pool)]
end

function Game3:speedOf(mon)
  if not mon then return 0 end
  local s = staged(mon, "spe")
  if mon.status == Game3.STATUS_PAR then
    s = math.max(1, math.floor(s / 4))
  end
  if not self:weatherSuppressed() then
    local w = self.battle and self.battle.weather
    if w == Game3.WEATHER_RAIN
        and self:hasAbility(mon, Game3.ABILITY_SWIFT_SWIM) then
      s = s * 2
    elseif w == Game3.WEATHER_SUN
        and self:hasAbility(mon, Game3.ABILITY_CHLOROPHYLL) then
      s = s * 2
    end
  end
  return s
end

-- pokeruby battle_main.c: one gRandomTurnNumber per turn. Quick Claw
-- (param 20) sets speed to UINT_MAX when roll < (param * 0xFFFF) / 100.
function Game3.quickClawThreshold(param)
  return math.floor((tonumber(param) or 0) * 65535 / 100)
end

function Game3:turnSpeed(mon, turnRoll)
  local s = self:speedOf(mon)
  local effect, param = self:holdEffectOf(mon)
  if effect == Game3.HOLD_EFFECT_QUICK_CLAW
      and (tonumber(turnRoll) or 0) < Game3.quickClawThreshold(param) then
    return Game3.QUICK_CLAW_SPEED
  end
  return s
end

function Game3:turnOrder(playerMove, enemyMove)
  local pp = (playerMove and playerMove.priority) or 0
  local ep = (enemyMove and enemyMove.priority) or 0
  if pp ~= ep then return pp > ep end
  return self:speedOf(self.battle.player) >= self:speedOf(self.battle.enemy)
end

function Game3:queueBattlerMove(move, target)
  local b = self.battle
  if not b then return end
  local lead = self:menuBattler()
  if b.doubles and lead == b.player and Game3.aliveMon(b.player2) then
    b.pendingMove = move
    b.pendingTarget = target
    b.chooser = "player2"
    b.kind = "menu"
    b.cursor = 0
    b.fightCursor = 0
    return
  end
  self:beginTurn(move, target)
end

function Game3:beginTurn(playerMove, chosen)
  local b = self.battle
  b.moveAnim = nil
  local lead = self:menuBattler()
  if lead and lead.charging and lead.charging.move then
    playerMove = lead.charging.move
  elseif lead and (lead.encoreTurns or 0) > 0 and lead.encoreMove then
    playerMove = lead.encoreMove
  elseif lead and (lead.rolloutTimer or 0) > 0 and lead.rolloutMove then
    playerMove = lead.rolloutMove
  elseif lead and (lead.rampage or 0) > 0 and lead.rampageMove then
    -- STATUS2_MULTIPLETURNS: Thrash picks its own target and move until the
    -- counter runs out, so the menu never opens.
    playerMove = lead.rampageMove
  end
  -- YAWN falling asleep, WISH healing and FUTURE SIGHT landing all speak at
  -- the top of the turn, before `queue` below exists. They were appending to
  -- a bare `texts`, which is a nil global -- so the moment any of the three
  -- actually resolved (they return {} otherwise, which is why it took a
  -- specific battle to hit) beginTurn died on #texts.
  local startTexts = {}
  local mons = { b.player, b.player2, b.enemy, b.enemy2 }
  for i = 1, 4 do
    local mon = mons[i]
    if mon then
      mon.flinch = nil
      mon.protected = nil
      mon.endured = nil
      -- gProtectStructs is zeroed each turn, so COUNTER only ever answers a
      -- hit taken this turn.
      mon.counterPhysical = nil
      mon.counterPhysicalFrom = nil
      mon.counterSpecial = nil
      mon.counterSpecialFrom = nil
      -- DESTINY_BOND only reaches into the turn it was used.
      mon.destinyBond = nil
      if (mon.disableTurns or 0) > 0 then
        mon.disableTurns = mon.disableTurns - 1
        if mon.disableTurns <= 0 then
          mon.disabledMove = nil
          mon.disableTurns = nil
        end
      end
      if (mon.encoreTurns or 0) > 0 then
        mon.encoreTurns = mon.encoreTurns - 1
        if mon.encoreTurns <= 0 or (mon.encoreMove and (mon.encoreMove.pp or 0) <= 0) then
          mon.encoreMove = nil
          mon.encoreSlot = nil
          mon.encoreTurns = nil
        end
      end
      -- YAWN and WISH are NOT start-of-turn: battle_util.c puts YAWN in the
      -- per-battler end-turn list (ENDTURN_YAWN, after TAUNT) and WISH in the
      -- field one (ENDTURN_WISH, ahead of the weathers). Ticking them here
      -- made a yawned battler fall asleep before it had moved, so it lost the
      -- turn the cart still gives it. Both moved to the residual pass below.
      -- FUTURE SIGHT stays: I did not find its phase in the decomp, so it is
      -- left where it was rather than moved on a guess.
      for _, line in ipairs(self:tickFutureSight(mon)) do
        startTexts[#startTexts + 1] = line
      end
      if (mon.chargeTurns or 0) > 0 then
        mon.chargeTurns = mon.chargeTurns - 1
        if mon.chargeTurns <= 0 then mon.chargeTurns = nil end
      end
      -- gProtectStructs is zeroed each turn, so HELPING HAND, MAGIC COAT
      -- and SNATCH only ever cover the turn they were set on.
      mon.helpingHand = nil
      mon.magicCoat = nil
      mon.snatch = nil
      if (mon.tauntTurns or 0) > 0 then
        mon.tauntTurns = mon.tauntTurns - 1
        if mon.tauntTurns <= 0 then mon.tauntTurns = nil end
      end
      if (mon.sureHitTurns or 0) > 0 then
        mon.sureHitTurns = mon.sureHitTurns - 1
        if mon.sureHitTurns <= 0 then
          mon.sureHitTurns = nil
          mon.sureHitFrom = nil
        end
      end
      if type(mon.isFirstTurn) == "number" and mon.isFirstTurn > 0 then
        mon.isFirstTurn = mon.isFirstTurn - 1
      end
    end
  end
  local turnRoll = self:rand(65536) - 1
  local actions = {}
  b.aiSwitchReserved = nil
  local function add(mon, move, side, slot, pick, item, switchCand)
    if not Game3.aliveMon(mon) and not switchCand then return end
    if not move and not item and not switchCand then return end
    actions[#actions + 1] = {
      mon = mon, move = move, item = item, side = side, slot = slot,
      chosen = pick, switchCand = switchCand,
      -- Items and switches share the high priority band (cart B_ACTION_USE_ITEM /
      -- B_ACTION_SWITCH both beat moves).
      pri = (item or switchCand) and 7 or ((move and move.priority) or 0),
      spe = self:turnSpeed(mon, turnRoll),
    }
  end
  local function moveFor(mon)
    if (mon.uproarTurns or 0) > 0 and mon.uproarMove then
      return mon.uproarMove, chosen
    end
    if mon == lead then return playerMove, chosen end
    if mon == b.player and b.pendingMove then
      return b.pendingMove, b.pendingTarget
    end
    return self:pickEnemyMove(mon)
  end
  if Game3.aliveMon(b.player) then
    local mv, pick = moveFor(b.player)
    add(b.player, mv, 0, 0, pick)
  end
  if Game3.aliveMon(b.player2) then
    local mv, pick = moveFor(b.player2)
    add(b.player2, mv, 0, 1, pick)
  end
  if Game3.aliveMon(b.enemy) then
    local kind, payload = self:aiDecideSwitchOrItem(b.enemy)
    if kind == "switch" then
      add(b.enemy, nil, 1, 0, nil, nil, payload)
    elseif kind == "item" then
      add(b.enemy, nil, 1, 0, nil, payload)
    else
      add(b.enemy, self:pickEnemyMove(b.enemy), 1, 0)
    end
  end
  if Game3.aliveMon(b.enemy2) then
    local kind, payload = self:aiDecideSwitchOrItem(b.enemy2)
    if kind == "switch" then
      add(b.enemy2, nil, 1, 1, nil, nil, payload)
    elseif kind == "item" then
      add(b.enemy2, nil, 1, 1, nil, payload)
    else
      add(b.enemy2, self:pickEnemyMove(b.enemy2), 1, 1)
    end
  end
  b.pendingMove, b.pendingTarget = nil, nil
  b.chooser = "player"
  table.sort(actions, function(a, c)
    if a.pri ~= c.pri then return a.pri > c.pri end
    if a.spe ~= c.spe then return a.spe > c.spe end
    if a.side ~= c.side then return a.side < c.side end
    return a.slot < c.slot
  end)
  local queue = {}
  -- Start-of-turn lines come before anything the turn's moves say.
  for i = 1, #startTexts do queue[#queue + 1] = startTexts[i] end
  local function run(attacker, pick, move)
    if (attacker.hp or 0) <= 0 then return end
    local targets
    local t = (move and move.target) or 0
    if t == Game3.TARGET_USER then
      targets = { attacker }
    elseif Game3.isSpreadTarget(t) then
      targets = self:spreadTargets(attacker, move)
    else
      local one = pick
      if not Game3.aliveMon(one) then one = self:defaultTarget(attacker) end
      targets = one and { one } or {}
    end
    if #targets < 1 then return end
    local skip, msgs = self:statusBlocks(attacker, move)
    for i = 1, #msgs do queue[#queue + 1] = msgs[i] end
    if skip then
      self:cancelMultiTurn(attacker)
      return
    end
    skip, msgs = self:confuseBlocks(attacker)
    for i = 1, #msgs do queue[#queue + 1] = msgs[i] end
    if skip then
      self:cancelMultiTurn(attacker)
      return
    end
    if attacker.flinch then
      attacker.flinch = nil
      self:cancelMultiTurn(attacker)
      queue[#queue + 1] = ("%s flinched and couldn't move!"):format(
        attacker.name)
      return
    end
    move.spreadHits = #targets > 1
    local exploding = self:moveEffect(move) == Game3.EFFECT_EXPLOSION
    for i = 1, #targets do
      if (attacker.hp or 0) <= 0 and not exploding then break end
      if Game3.aliveMon(targets[i]) then
        local texts = self:useMove(attacker, targets[i], move, i > 1)
        for j = 1, #texts do queue[#queue + 1] = texts[j] end
        if attacker.charging then break end
      end
    end
    move.spreadHits = nil
  end
  for i = 1, #actions do
    local act = actions[i]
    if act.switchCand then
      local texts = self:aiPerformSwitch(act.mon, act.switchCand)
      for j = 1, #(texts or {}) do queue[#queue + 1] = texts[j] end
    elseif act.item then
      local texts = self:applyTrainerItem(act.mon, act.item)
      for j = 1, #texts do queue[#queue + 1] = texts[j] end
    else
      run(act.mon, act.chosen, act.move)
    end
    self:clearFaintedStatus()
    if b.fled then break end
  end
  if not b.fled then
    local function residual(mon)
      if not mon then return end
      local texts = self:ingrainResidual(mon)
      for i = 1, #texts do queue[#queue + 1] = texts[i] end
      texts = self:leechSeedResidual(mon)
      for i = 1, #texts do queue[#queue + 1] = texts[i] end
      texts = self:wrapResidual(mon)
      for i = 1, #texts do queue[#queue + 1] = texts[i] end
      texts = self:nightmareResidual(mon)
      for i = 1, #texts do queue[#queue + 1] = texts[i] end
      texts = self:statusResidual(mon)
      for i = 1, #texts do queue[#queue + 1] = texts[i] end
      texts = self:speedBoostResidual(mon)
      for i = 1, #texts do queue[#queue + 1] = texts[i] end
      texts = self:tickHeldItem(mon)
      for i = 1, #texts do queue[#queue + 1] = texts[i] end
      texts = self:uproarResidual(mon)
      for i = 1, #texts do queue[#queue + 1] = texts[i] end
      -- ENDTURN_YAWN sits here, after TAUNT and before ITEMS2.
      texts = self:tickYawn(mon)
      for i = 1, #texts do queue[#queue + 1] = texts[i] end
      texts = self:perishSongResidual(mon)
      for i = 1, #texts do queue[#queue + 1] = texts[i] end
    end
    residual(b.player)
    residual(b.player2)
    residual(b.enemy)
    residual(b.enemy2)
    -- ENDTURN_WISH comes before the weathers in DoFieldEndTurnEffects.
    for _, side in ipairs({ b.player, b.player2, b.enemy, b.enemy2 }) do
      if side then
        local wish = self:tickWish(side)
        for i = 1, #wish do queue[#queue + 1] = wish[i] end
      end
    end
    local wtexts = self:tickWeather()
    for i = 1, #wtexts do queue[#queue + 1] = wtexts[i] end
    local stexts = self:tickScreens()
    for i = 1, #stexts do queue[#queue + 1] = stexts[i] end
    local function awardFoe(foe)
      if not foe or (foe.hp or 0) > 0 or foe.expPaid then return end
      local winner = Game3.aliveMon(b.player) and b.player
        or (Game3.aliveMon(b.player2) and b.player2)
      if not winner then return end
      foe.expPaid = true
      local texts = self:awardExp(winner, foe, b.isTrainer)
      for i = 1, #texts do queue[#queue + 1] = texts[i] end
    end
    awardFoe(b.enemy)
    awardFoe(b.enemy2)
  end
  self:tickMist()
  b.turns = (b.turns or 0) + 1
  b.queue = queue
  b.qi = 1
  b.kind = "text"
  b.text = queue[1] or ""
  -- Typed moveAnim arms animT; status-only turns get a soft pulse.
  if not b.moveAnim then
    b.animT = 0.18
  end
end

function Game3:advanceBattleText()
  local b = self.battle
  b.qi = (b.qi or 1) + 1
  if b.queue and b.qi <= #b.queue then
    b.text = b.queue[b.qi]
    b.textPage = 0
    b.printSrc = nil
    return
  end
  if b.thenLearnAsk then
    b.thenLearnAsk = nil
    self:openLearnYesNo()
    return
  end
  self:afterBattleMessages()
end

function Game3:afterBattleMessages()
  local b = self.battle
  -- atk1B_cleareffectsonfaint fires as part of the faint itself, so by the
  -- time the faint's messages are done the status byte is already gone.
  self:clearFaintedStatus()
  if self:startPendingLearn() then return end
  if b.pickupDone then
    self:endBattle()
    return
  end
  if b.fled then
    local outcome = Game3.B_OUTCOME_RAN
    if b.safari then
      outcome = Game3.B_OUTCOME_MON_FLED
    elseif b.forcedOut then
      outcome = Game3.B_OUTCOME_PLAYER_TELEPORTED
    end
    self:recordBattleEnd(outcome)
    self:endBattle()
    return
  end
  if b.safariOver then
    self:endBattle()
    return
  end
  if b.caught then
    if b.showDexEntry then
      local species = b.showDexEntry
      b.showDexEntry = nil
      self:openDexEntry(species, { fromCatch = true })
      return
    end
    if b.askCaughtNick then
      self:openCaughtNickAsk()
      return
    end
    self:finishBattle()
  elseif (not Game3.aliveMon(b.enemy) and not Game3.aliveMon(b.enemy2))
      or (b.doubles and (not Game3.aliveMon(b.enemy) or not Game3.aliveMon(b.enemy2))) then
    local noEnemies = not Game3.aliveMon(b.enemy) and not Game3.aliveMon(b.enemy2)
    if b.isTrainer then
      if self:canOfferShift() then
        b.kind = "switch_ask"
        b.cursor = 0
        b.text = "Will you switch POKeMON?"
        b.queue = nil
        return
      elseif self:sendTrainerReplacement() then
        return
      elseif noEnemies then
        self:openTrainerVictory()
      else
        self:afterFaintContinue()
      end
    elseif noEnemies then
      self:recordBattleEnd(Game3.B_OUTCOME_WON)
      self:finishBattle()
    else
      self:afterFaintContinue()
    end
  else
    self:afterFaintContinue()
  end
end

function Game3:stepBattle(dt)
  local b = self.battle
  if not b then return end
  dt = dt or 0
  self:stepShinySparkles(dt)
  if self.stepBattleFx then self:stepBattleFx(dt) end
  if b.kind == "intro" then
    self:stepIntroCinema(dt)
  elseif b.introCinema and b.introCinema.phase ~= "done"
      and b.introCinema.phase ~= "hold" then
    -- Mid-battle player_switch cinema can run under kind=text.
    self:stepIntroCinema(dt)
  end
  if (b.animT or 0) > 0 then
    b.animT = b.animT - dt
    if b.animT < 0 then b.animT = 0 end
  end
  local ma = b.moveAnim
  if ma then
    ma.t = (ma.t or 0) + dt
    if (ma.t or 0) >= (ma.dur or 0) then
      b.moveAnim = nil
      self:flushPendingHitSe()
    end
  elseif b.pendingHitSe then
    self:flushPendingHitSe()
  end
  if b.catchAnim then
    local ca = b.catchAnim
    self:stepCatchSe(ca)
    if not ca.hold then
      ca.t = (ca.t or 0) + dt
      if (ca.t or 0) >= Game3.catchAnimDuration(ca) then
        if ca.ok then
          -- Keep sealed ball visible through Gotcha / nick / dex text.
          ca.hold = true
          ca.t = Game3.catchAnimDuration(ca)
        else
          b.catchAnim = nil
        end
      end
    end
  end
  self:maybePlayFaintSeFromText(b)
  self:updateLowHpSe()
  if b.kind == "dex_entry" then
    self:stepDexEntry(b)
    return
  end
  if b.kind == "catch_nick" then
    self:stepPrinter(b, dt)
    if Input:wasPressed("up") or Input:wasPressed("down") then
      b.cursor = 1 - (b.cursor or 0)
    elseif Input:wasPressed("a") then
      if self:printerBusy(b) then
        self:printerFinish(b)
        return
      end
      self:answerCaughtNick((b.cursor or 0) == 0)
    elseif Input:wasPressed("b") then
      if self:printerBusy(b) then
        self:printerFinish(b)
        return
      end
      self:answerCaughtNick(false)
    end
    return
  end
  if b.kind == "intro" or b.kind == "menu_msg" or b.kind == "text"
      or b.kind == "ran" or b.kind == "won_trainer" or b.kind == "blackout"
      or b.kind == "switch_ask" or b.kind == "evolve"
      or b.kind == "learn_yesno" or b.kind == "learn_stop"
      or b.kind == "learn_msg" or b.kind == "learn_forget"
      or b.kind == "catch_nick" then
    self:stepPrinter(b, dt)
  end
  if b.kind == "evolve" then
    self:stepEvolve(dt)
    return
  end
  if b.kind == "switch_ask" then
    if Input:wasPressed("up") or Input:wasPressed("down") then
      b.cursor = 1 - (b.cursor or 0)
    elseif Input:wasPressed("a") then
      if self:printerBusy(b) then
        self:printerFinish(b)
        return
      end
      if (b.cursor or 0) == 0 then
        b.kind = "party"
        b.shiftSwitch = true
        b.mustSwitch = false
        b.partyCursor = 0
        b.text = nil
      else
        self:sendTrainerReplacement()
      end
    elseif Input:wasPressed("b") then
      if self:printerBusy(b) then
        self:printerFinish(b)
        return
      end
      self:sendTrainerReplacement()
    end
    return
  end
  if b.kind == "learn_yesno" then
    if Input:wasPressed("up") or Input:wasPressed("down") then
      b.cursor = 1 - (b.cursor or 0)
    elseif Input:wasPressed("a") then
      if self:printerBusy(b) then
        self:printerFinish(b)
        return
      end
      self:answerLearnYesNo((b.cursor or 0) == 0)
    elseif Input:wasPressed("b") then
      if self:printerBusy(b) then
        self:printerFinish(b)
        return
      end
      self:answerLearnYesNo(false)
    end
    return
  end
  if b.kind == "learn_stop" then
    if Input:wasPressed("up") or Input:wasPressed("down") then
      b.cursor = 1 - (b.cursor or 0)
    elseif Input:wasPressed("a") then
      if self:printerBusy(b) then
        self:printerFinish(b)
        return
      end
      self:answerLearnStop((b.cursor or 0) == 0)
    elseif Input:wasPressed("b") then
      if self:printerBusy(b) then
        self:printerFinish(b)
        return
      end
      self:answerLearnStop(false)
    end
    return
  end
  if b.kind == "learn_forget" then
    local mon = self.learnMove and self.learnMove.mon
    local moves = mon and mon.moves or {}
    local n = #moves + 1
    if n < 1 then n = 1 end
    if Input:wasPressed("down") then
      b.cursor = ((b.cursor or 0) + 1) % n
    elseif Input:wasPressed("up") then
      b.cursor = ((b.cursor or 0) - 1) % n
      if b.cursor < 0 then b.cursor = n - 1 end
    elseif Input:wasPressed("a") then
      self:chooseLearnForget((b.cursor or 0) + 1)
    elseif Input:wasPressed("b") then
      self:openLearnStop()
    end
    return
  end
  if b.kind == "learn_msg" then
    if Input:wasPressed("a") or Input:wasPressed("b") then
      if self:printerBusy(b) then
        self:printerFinish(b)
        return
      end
      if self:advanceDialogue(b) then return end
      b.qi = (b.qi or 1) + 1
      if b.queue and b.qi <= #b.queue then
        b.text = b.queue[b.qi]
        b.textPage = 0
        b.printSrc = nil
        return
      end
      self:finishLearnMessage()
    end
    return
  end
  if b.kind == "menu" then
    local lead = self:menuBattler()
    if lead and lead.charging then
      self:beginTurn(lead.charging.move)
      return
    end
    if Input:wasPressed("b") and b.doubles and b.chooser == "player2" then
      b.chooser = "player"
      b.pendingMove, b.pendingTarget = nil, nil
      b.cursor = 0
      return
    end
    if Input:wasPressed("right") or Input:wasPressed("left") then
      b.cursor = b.cursor % 2 == 0 and b.cursor + 1 or b.cursor - 1
    elseif Input:wasPressed("down") or Input:wasPressed("up") then
      b.cursor = (b.cursor + 2) % 4
    elseif Input:wasPressed("a") then
      if b.safari then
        if b.cursor == 0 then
          self:throwBall(Game3.ITEM_SAFARI_BALL)
        elseif b.cursor == 1 then
          self:openSafariPokeblockCase()
        elseif b.cursor == 2 then
          self:safariGoNear()
        elseif b.cursor == 3 then
          b.text = "Got away safely!"
          b.kind = "ran"
        end
      elseif b.cursor == 0 then
        -- battle_util.c AreAllMovesUnusable runs at selection time: with
        -- nothing usable it prints BattleText_NoMovesLeft and the turn
        -- goes ahead with Struggle instead of opening the move list.
        local acting = self:menuBattler() or b.player
        if self:allMovesUnusable(acting) then
          b.text = ("%s has no\r\nmoves left!"):format(
            (acting and acting.name) or "POKeMON")
          b.kind = "menu_msg"
          b.thenStruggle = true
        else
          b.kind = "fight"
        end
      elseif b.cursor == 1 then
        self:openBattleBag()
      elseif b.cursor == 2 then
        b.kind = "party"
        b.partyCursor = 0
        b.itemUse = nil
      elseif b.cursor == 3 then
        if b.isTrainer or b.chase or b.wallyTutorial then
          b.text = (b.chase or b.wallyTutorial)
            and "There's no running from this battle!"
            or "No! There's no running from a TRAINER battle!"
          b.kind = "menu_msg"
        else
          -- Two separate gates in the cart, in this order. CanRunFromBattle
          -- runs at SELECTION time and costs no turn (battle_main.c
          -- HandleInputChooseAction); TryRunFromBattle is the roll, and
          -- losing it burns the turn, so the wild POKeMON still attacks.
          local acting = self:menuBattler() or b.player
          local code, foe, ability = self:canRunFromBattle(acting)
          if code == 2 then
            b.text = ("%s prevents" .. string.char(10)
              .. "escape with %s!"):format(
              (foe and foe.name) or "The foe", Game3.abilityName(ability))
            b.kind = "menu_msg"
          elseif code ~= 0 then
            b.text = "Can't escape!"
            b.kind = "menu_msg"
          elseif self:tryRunFromBattle(acting) then
            b.text = "Got away safely!"
            b.kind = "ran"
          else
            -- gNoEscapeStringIds[3], then the turn plays out.
            self:commitBattleItem("Can't escape!")
          end
        end
      end
    end
    return
  end
  if b.kind == "pokeblock_case" then
    local labels = b.pokeblockLabels or { "CANCEL" }
    local n = #labels
    if n < 1 then n = 1 end
    if Input:wasPressed("b") then
      b.kind = "menu"
    elseif Input:wasPressed("down") then
      b.pokeblockCursor = ((b.pokeblockCursor or 0) + 1) % n
    elseif Input:wasPressed("up") then
      b.pokeblockCursor = ((b.pokeblockCursor or 0) - 1) % n
      if b.pokeblockCursor < 0 then b.pokeblockCursor = n - 1 end
    elseif Input:wasPressed("a") then
      self:pickSafariPokeblock(b.pokeblockCursor or 0)
    end
    return
  end
  if b.kind == "bag" then
    local pocket = b.bagPocket or self.lastBagPocket or self:firstFilledPocket()
    if pocket < Game3.POCKET_ITEMS then pocket = Game3.POCKET_ITEMS end
    if pocket > Game3.POCKET_KEY then pocket = Game3.POCKET_KEY end
    b.bagPocket = pocket
    self.lastBagPocket = pocket
    local list = self:bagSlotsIn(pocket)
    local n = #list + 1
    if Input:wasPressed("b") then
      b.kind = "menu"
    elseif Input:wasPressed("right") then
      b.bagPocket = Game3.wrapPocket(pocket, 1)
      b.bagCursor = 0
      self.lastBagPocket = b.bagPocket
    elseif Input:wasPressed("left") then
      b.bagPocket = Game3.wrapPocket(pocket, -1)
      b.bagCursor = 0
      self.lastBagPocket = b.bagPocket
    elseif Input:wasPressed("down") then
      b.bagCursor = ((b.bagCursor or 0) + 1) % n
    elseif Input:wasPressed("up") then
      b.bagCursor = ((b.bagCursor or 0) - 1) % n
      if b.bagCursor < 0 then b.bagCursor = n - 1 end
    elseif Input:wasPressed("a") then
      local slot = list[(b.bagCursor or 0) + 1]
      if not slot then
        b.kind = "menu"
      elseif Game3.needsBattleParty(slot.id) then
        b.kind = "party"
        b.itemUse = slot.id
        b.partyCursor = 0
      else
        self:useBattleItem(slot.id)
      end
    end
    return
  end
  if b.kind == "party" then
    local n = #(self.party or {})
    if n < 1 then n = 1 end
    if Input:wasPressed("b") then
      if b.mustSwitch then
        return
      elseif b.itemUse then
        b.itemUse = nil
        b.kind = "bag"
      elseif b.shiftSwitch then
        b.shiftSwitch = false
        self:sendTrainerReplacement()
      else
        b.kind = "menu"
      end
    elseif Input:wasPressed("down") then
      b.partyCursor = ((b.partyCursor or 0) + 1) % n
    elseif Input:wasPressed("up") then
      b.partyCursor = ((b.partyCursor or 0) - 1) % n
      if b.partyCursor < 0 then b.partyCursor = n - 1 end
    elseif Input:wasPressed("a") then
      if b.itemUse and not b.mustSwitch then
        local party = self.party or {}
        local index = (b.partyCursor or 0) + 1
        local target = party[index]
        if target and target.isEgg then
          self:failBattleItem("It won't have any effect.")
          b.partyMsg = true
          return
        end
        if Game3.needsMovePick(b.itemUse) then
          b.kind = "item_pp"
          b.ppIndex = index
          b.ppCursor = 0
          return
        end
        if self:useBattleItem(b.itemUse, target) then
          b.itemUse = nil
        end
        return
      end
      -- PURSUIT catches the outgoing mon on the way out, at double damage.
      local pursuitQueue = {}
      local pursued = false
      if not b.mustSwitch and b[b.switchSlot or "player"] then
        pursued = self:pursuitOnSwitch(b[b.switchSlot or "player"], pursuitQueue)
      end
      local ok, msg, extra = self:switchTo((b.partyCursor or 0) + 1)
      if not ok then
        -- ROM DisplayPartyMenuMessage then Task_80954C0 (stay on party).
        b.text = msg or "It won't have any effect."
        b.kind = "menu_msg"
        b.partyMsg = true
        return
      end
      if b.shiftSwitch then
        b.shiftSwitch = false
        self:sendTrainerReplacement()
        return
      end
      local queue = { msg }
      for i = 1, #(extra or {}) do queue[#queue + 1] = extra[i] end
      if b.mustSwitch then
        b.mustSwitch = false
      elseif pursued then
        -- gActionsByTurnOrder marks the pursuer as having acted, so it
        -- does not get a second move this turn.
      elseif (b.enemy.hp or 0) > 0 then
        self:queueEnemyAction(queue)
      end
      for i = #pursuitQueue, 1, -1 do table.insert(queue, 1, pursuitQueue[i]) end
      b.queue = queue
      b.qi = 1
      b.kind = "text"
      b.text = queue[1]
    end
    return
  end
  if b.kind == "item_pp" then
    local mon = (self.party or {})[b.ppIndex or 1]
    local moves = mon and mon.moves or {}
    local n = #moves + 1
    if n < 1 then n = 1 end
    if Input:wasPressed("b") then
      b.kind = "party"
      return
    elseif Input:wasPressed("down") then
      b.ppCursor = ((b.ppCursor or 0) + 1) % n
    elseif Input:wasPressed("up") then
      b.ppCursor = ((b.ppCursor or 0) - 1) % n
      if b.ppCursor < 0 then b.ppCursor = n - 1 end
    elseif Input:wasPressed("a") then
      local slot = (b.ppCursor or 0) + 1
      if slot > #moves then
        b.kind = "party"
        return
      end
      if self:useBattleItem(b.itemUse, mon, slot) then
        b.itemUse = nil
      else
        b.kind = "party"
      end
    end
    return
  end
  if b.kind == "fight" then
    local battler = self:menuBattler() or b.player
    local n = #((battler and battler.moves) or {})
    if n < 1 then n = 1 end
    local dir = Input:wasPressed("left") and "left"
      or Input:wasPressed("right") and "right"
      or Input:wasPressed("up") and "up"
      or Input:wasPressed("down") and "down" or nil
    -- sub_802CA60: a live dest cursor means SELECT already marked a slot.
    -- A / SELECT swap (if dest ~= source); B cancels; D-pad moves dest.
    if b.moveSwap ~= nil then
      if Input:wasPressed("a") or Input:wasPressed("select") then
        if b.moveSwap ~= (b.fightCursor or 0) then
          self:swapMoveSlots(battler, b.fightCursor or 0, b.moveSwap)
        end
        b.fightCursor = b.moveSwap
        b.moveSwap = nil
      elseif Input:wasPressed("b") then
        b.moveSwap = nil
      elseif dir then
        b.moveSwap = Game3.moveCursorStep(b.moveSwap, dir, n)
      end
      return
    end
    if Input:wasPressed("b") then
      b.kind = "menu"
    elseif dir then
      b.fightCursor = Game3.moveCursorStep(b.fightCursor, dir, n)
    elseif Input:wasPressed("a") then
      local move = battler and battler.moves and battler.moves[b.fightCursor + 1]
      if not move then return end
      if (move.pp or 0) <= 0 then
        b.text = "There's no PP left!"
        b.kind = "menu_msg"
      else
        local opts = self:selectableTargets(battler, move)
        if b.doubles and #opts > 1 then
          b.kind = "target"
          b.targetMove = move
          b.targetList = opts
          b.targetCursor = 0
        else
          self:queueBattlerMove(move)
        end
      end
    elseif Input:wasPressed("select") and n > 1 then
      -- HandleAction_ChooseMove SELECT: ignored with one move or in link.
      b.moveSwap = Game3.moveSwapDest(b.fightCursor or 0)
    end
    return
  end
  if b.kind == "target" then
    local list = b.targetList or {}
    local n = #list
    if n < 1 then n = 1 end
    if Input:wasPressed("b") then
      b.kind = "fight"
    elseif Input:wasPressed("right") or Input:wasPressed("left")
        or Input:wasPressed("down") or Input:wasPressed("up") then
      b.targetCursor = ((b.targetCursor or 0) + 1) % n
    elseif Input:wasPressed("a") then
      local pick = list[(b.targetCursor or 0) + 1]
      self:queueBattlerMove(b.targetMove, pick)
    end
    return
  end
  if not (Input:wasPressed("a") or (b.kind == "intro" and Input:wasPressed("b"))) then
    return
  end
  if self:advanceDialogue(b) then
    return
  end
  if b.kind == "intro" or b.kind == "menu_msg" then
    if b.kind == "intro" then
      self:onIntroConfirm()
    elseif b.thenStruggle then
      -- BattleScript_NoMovesLeft is a SELECTION script: the message shows,
      -- then the turn runs with Struggle already chosen.
      b.thenStruggle = nil
      b.text = nil
      self:queueBattlerMove(self:struggleMove())
    elseif b.itemUse or b.partyMsg then
      b.partyMsg = nil
      b.kind = "party"
      b.text = nil
    else
      b.kind = "menu"
      b.text = nil
    end
  elseif b.kind == "text" then
    self:advanceBattleText()
  elseif b.kind == "ran" then
    self:recordBattleEnd(Game3.B_OUTCOME_RAN)
    self:endBattle()
  elseif b.kind == "won_trainer" then
    self:confirmTrainerWin()
  elseif b.kind == "blackout" then
    self:blackout()
  end
end

function Game3:battlePic(species, which, shiny)
  species = tonumber(species)
  if not species then return nil end
  local pack = self.data.encounters or {}
  local paths
  if shiny then
    paths = (which == "back") and pack.backsShiny or pack.frontsShiny
  else
    paths = (which == "back") and pack.backs or pack.fronts
  end
  local path = paths and (paths[species] or paths[tostring(species)])
  if type(path) ~= "string" then
    local folder = "front"
    if which == "back" then folder = "back" end
    if shiny then folder = folder .. "_shiny" end
    path = ("assets/generated/battle/%s/%d.png"):format(folder, species)
  end
  self.battlePicCache = self.battlePicCache or {}
  local key = (shiny and "shiny:" or "") .. which .. ":" .. species
  if self.battlePicCache[key] ~= nil then
    return self.battlePicCache[key] or nil
  end
  local img = self:grabImage(path)
  -- Missing shiny PNG: fall back to normal so battles still draw.
  if not img and shiny then
    return self:battlePic(species, which, false)
  end
  self.battlePicCache[key] = img or false
  return img
end

function Game3.fontCode(ch)
  if type(ch) ~= "string" or ch == "" then return 0x00 end
  if ch == "é" or ch == "è" or ch == "ê" or ch == "ë" then return 0xD9 end
  if ch == "É" or ch == "È" or ch == "Ê" or ch == "Ë" then return 0xBF end
  if ch == "♂" then return Game3.FONT_MALE end
  if ch == "♀" then return Game3.FONT_FEMALE end
  if ch == "…" then return 0xB0 end
  if ch == "“" then return 0xB1 end
  if ch == "”" then return 0xB2 end
  if ch == "‘" then return 0xB3 end
  if #ch > 1 then ch = ch:sub(1, 1) end
  local b = ch:byte()
  if ch == " " then return 0x00 end
  if b >= 65 and b <= 90 then return 0xBB + (b - 65) end
  if b >= 97 and b <= 122 then return 0xD5 + (b - 97) end
  if b >= 48 and b <= 57 then return 0xA1 + (b - 48) end
  if ch == "!" then return 0xAB end
  if ch == "?" then return 0xAC end
  if ch == "." then return 0xAD end
  if ch == "-" then return 0xAE end
  if ch == "'" then return 0xB4 end
  if ch == "," then return 0xB8 end
  if ch == "/" then return 0xBA end
  if ch == ":" then return 0xF0 end
  return 0x00
end

function Game3.stdWindowRect(left, top, right, bottom)
  local t = Game3.MENU_TILE
  left = tonumber(left) or 0
  top = tonumber(top) or 0
  right = tonumber(right) or left
  bottom = tonumber(bottom) or top
  return left * t, top * t, (right - left + 1) * t, (bottom - top + 1) * t
end

function Game3.font3Widths(spec)
  local w = spec and spec.widths
  if type(w) == "table" and #w >= 254 then return w end
  return Game3.FONT3_WIDTHS
end

function Game3.glyphWidth(code, widths)
  widths = widths or Game3.FONT3_WIDTHS
  code = math.floor(tonumber(code) or 0)
  if code < 0 then code = 0 elseif code > 255 then code = 255 end
  return tonumber(widths[code + 1]) or Game3.MSG_GLYPH_PX
end

-- Walk a decoded Latin string the same way drawText does, including é/♂/♀.
function Game3.forEachGlyph(text, fn)
  text = tostring(text or "")
  local i = 1
  while i <= #text do
    local b = text:byte(i)
    local ch = text:sub(i, i)
    local skip = 1
    local code
    if b == 0xC3 and i < #text then
      local n = text:byte(i + 1)
      if n == 0xA9 or n == 0xA8 or n == 0xAA or n == 0xAB then
        ch = "e"
        skip = 2
      elseif n == 0x89 or n == 0x88 or n == 0x8A or n == 0x8B then
        ch = "E"
        skip = 2
      end
    elseif b == 0xE2 and i + 2 <= #text and text:byte(i + 1) == 0x99 then
      local n = text:byte(i + 2)
      if n == 0x82 then
        code = Game3.FONT_MALE
        skip = 3
      elseif n == 0x80 then
        code = Game3.FONT_FEMALE
        skip = 3
      end
    elseif b == 0xE2 and i + 2 <= #text and text:byte(i + 1) == 0x80 then
      -- OTHERS page punctuation: ellipsis/quotes -> FONT3 B0-B3
      local n = text:byte(i + 2)
      if n == 0xA6 then
        code = 0xB0
        skip = 3
      elseif n == 0x9C then
        code = 0xB1
        skip = 3
      elseif n == 0x9D then
        code = 0xB2
        skip = 3
      elseif n == 0x98 then
        code = 0xB3
        skip = 3
      end
    end
    if not code then code = Game3.fontCode(ch) end
    fn(code, i, skip)
    i = i + skip
  end
end

function Game3.textWidth(text, widths)
  widths = widths or Game3.FONT3_WIDTHS
  local n = 0
  Game3.forEachGlyph(text, function(code)
    n = n + Game3.glyphWidth(code, widths)
  end)
  return n
end

function Game3:font3WidthTable()
  return Game3.font3Widths(self.data and self.data.font)
end

function Game3:fontImage()
  if self._fontImage ~= nil then return self._fontImage or nil end
  local spec = self.data and self.data.font
  local path = spec and spec.image or "assets/generated/fonts/font.png"
  local img = self:grabImage(path)
  self._fontImage = img or false
  return img
end

function Game3:uiFont()
  if self._uiFont ~= nil then return self._uiFont or nil end
  if not (love and love.graphics and love.graphics.newFont) then
    self._uiFont = false
    return nil
  end
  local ok, font = pcall(love.graphics.newFont, 8)
  self._uiFont = (ok and font) or false
  return self._uiFont or nil
end

function Game3:fontInkShader()
  if self._fontInkShader ~= nil then return self._fontInkShader or nil end
  local G = love and love.graphics
  if not (G and G.newShader) then
    self._fontInkShader = false
    return nil
  end
  local ok, shader = pcall(G.newShader, Game3.FONT_INK_SHADER)
  self._fontInkShader = (ok and shader) or false
  return self._fontInkShader or nil
end

function Game3.shadowForInk(ink)
  local r = (ink and ink[1]) or 0
  local g = (ink and ink[2]) or 0
  local b = (ink and ink[3]) or 0
  if r + g + b > 1.5 then return Game3.BATTLE_TEXT_SHADOW end
  return Game3.TEXT_SHADOW
end

function Game3:setTextInk(ink)
  local c = ink or Game3.TEXT_INK
  love.graphics.setColor(c[1], c[2], c[3], c[4] or 1)
end

-- Recolor FONT3: current colour is fg, shadowForInk is 0xE. No shader
-- means the sheet is already black+gray, so draw it un-tinted.
function Game3:bindFontInk(cr, cg, cb, ca)
  local shader = self:fontInkShader()
  if not shader then
    love.graphics.setColor(1, 1, 1, 1)
    return nil
  end
  local sh = Game3.shadowForInk({ cr, cg, cb, ca })
  if shader.send then
    pcall(shader.send, shader, "shadowColor",
      { sh[1], sh[2], sh[3], sh[4] or 1 })
  end
  love.graphics.setColor(cr, cg, cb, ca)
  return shader
end

function Game3:drawFallbackText(text, x, y)
  local G = love.graphics
  local font = self:uiFont()
  local prev
  if font and G.setFont then
    if G.getFont then prev = G.getFont() end
    G.setFont(font)
  end
  G.print(text, x, y)
  if prev and G.setFont then G.setFont(prev) end
end

function Game3:drawGlyph(code, x, y)
  local img = self:fontImage()
  local quad, gw = self:fontQuad(code)
  if img and quad then
    local G = love.graphics
    local cr, cg, cb, ca = 1, 1, 1, 1
    if G.getColor then cr, cg, cb, ca = G.getColor() end
    local prev
    if G.getShader then prev = G.getShader() end
    local shader = self:bindFontInk(cr, cg, cb, ca)
    if shader then G.setShader(shader) end
    G.draw(img, quad, x, y)
    if shader and G.setShader then G.setShader(prev) end
    G.setColor(cr, cg, cb, ca)
  end
  return gw or 8
end

function Game3:fontQuad(code)
  code = tonumber(code) or 0
  local spec = self.data and self.data.font or {}
  local gw = spec.glyphW or 8
  local gh = spec.glyphH or 16
  local cols = spec.cols or 16
  local img = self:fontImage()
  local sw, sh = cols * gw, 16 * gh
  if img and img.getDimensions then
    sw, sh = img:getDimensions()
  end
  local col = code % cols
  local row = math.floor(code / cols)
  local key = ("font:%d:%d:%d"):format(code, sw, sh)
  self.quads = self.quads or {}
  local q = self.quads[key]
  if not q and love.graphics.newQuad then
    q = love.graphics.newQuad(col * gw, row * gh, gw, gh, sw, sh)
    self.quads[key] = q
  end
  return q, gw, gh
end

function Game3:drawText(text, x, y)
  text = tostring(text or "")
  local G = love.graphics
  local img = self:fontImage()
  if not img then
    self:drawFallbackText(text, x, y)
    return
  end
  local cr, cg, cb, ca = 1, 1, 1, 1
  if G.getColor then
    cr, cg, cb, ca = G.getColor()
  end
  local prevShader
  if G.getShader then prevShader = G.getShader() end
  local shader = self:bindFontInk(cr, cg, cb, ca)
  if shader then G.setShader(shader) end
  local gx = x
  local i = 1
  while i <= #text do
    local b = text:byte(i)
    local ch = text:sub(i, i)
    local skip = 1
    local code
    if b == 0xC3 and i < #text then
      local n = text:byte(i + 1)
      if n == 0xA9 or n == 0xA8 or n == 0xAA or n == 0xAB then
        ch = "e"
        skip = 2
      elseif n == 0x89 or n == 0x88 or n == 0x8A or n == 0x8B then
        ch = "E"
        skip = 2
      end
    elseif b == 0xE2 and i + 2 <= #text and text:byte(i + 1) == 0x99 then
      local n = text:byte(i + 2)
      if n == 0x82 then
        code = Game3.FONT_MALE
        skip = 3
      elseif n == 0x80 then
        code = Game3.FONT_FEMALE
        skip = 3
      end
    elseif b == 0xE2 and i + 2 <= #text and text:byte(i + 1) == 0x80 then
      -- OTHERS page punctuation: ellipsis/quotes -> FONT3 B0-B3
      local n = text:byte(i + 2)
      if n == 0xA6 then
        code = 0xB0
        skip = 3
      elseif n == 0x9C then
        code = 0xB1
        skip = 3
      elseif n == 0x9D then
        code = 0xB2
        skip = 3
      elseif n == 0x98 then
        code = 0xB3
        skip = 3
      end
    end
    if not code then code = Game3.fontCode(ch) end
    local quad = self:fontQuad(code)
    local advance = Game3.glyphWidth(code, self:font3WidthTable())
    if quad then
      G.draw(img, quad, gx, y)
    end
    gx = gx + advance
    i = i + skip
  end
  if shader and G.setShader then G.setShader(prevShader) end
  G.setColor(cr, cg, cb, ca)
end

function Game3:textDelay()
  local n = (self.options and self.options.textSpeed) or 2
  return Game3.TEXT_DELAY[n] or Game3.TEXT_DELAY[2]
end

function Game3.dialoguePageText(text, page, widths)
  local lines = Game3.wrapDialogue(text, nil, widths)
  page = page or 0
  local chunk = {}
  for i = 1, Game3.MSG_LINES do
    if lines[page + i] then chunk[#chunk + 1] = lines[page + i] end
  end
  return table.concat(chunk, "\r\n")
end

function Game3:printerBusy(box)
  if type(box) ~= "table" or not box.printLive then return false end
  local page = Game3.dialoguePageText(box.fullText or box.text or "",
    box.textPage or 0, self:font3WidthTable())
  return (box.printN or 0) < #page
end

function Game3:printedText(box)
  if type(box) ~= "table" then return "" end
  local page = Game3.dialoguePageText(box.fullText or box.text or "",
    box.textPage or 0, self:font3WidthTable())
  if not box.printLive then return page end
  return page:sub(1, box.printN or 0)
end

function Game3.wrapDialogue(text, maxPx, widths)
  maxPx = maxPx or Game3.MSG_WIDTH_PX
  widths = widths or Game3.FONT3_WIDTHS
  local spaceW = Game3.glyphWidth(0x00, widths)
  text = tostring(text or ""):gsub("\r\n", "\r\n")
  local lines = {}
  local function emit(line)
    if line and line ~= "" then lines[#lines + 1] = line end
  end
  local function wrapPara(para)
    local line, width = "", 0
    local function flush()
      emit(line)
      line, width = "", 0
    end
    local function take(word)
      local wpx = Game3.textWidth(word, widths)
      if line ~= "" and width + spaceW + wpx > maxPx then
        flush()
      end
      if line == "" and wpx > maxPx then
        local chunk, chunkW = "", 0
        Game3.forEachGlyph(word, function(code, i, skip)
          local gw = Game3.glyphWidth(code, widths)
          if chunk ~= "" and chunkW + gw > maxPx then
            emit(chunk)
            chunk, chunkW = "", 0
          end
          chunk = chunk .. word:sub(i, i + skip - 1)
          chunkW = chunkW + gw
        end)
        line, width = chunk, chunkW
        return
      end
      if line == "" then
        line, width = word, wpx
      else
        line = line .. " " .. word
        width = width + spaceW + wpx
      end
    end
    for word in para:gmatch("%S+") do
      take(word)
    end
    flush()
  end
  if text:find("\r\n", 1, true) then
    local start = 1
    while true do
      local at = text:find("\r\n", start, true)
      if not at then
        wrapPara(text:sub(start))
        break
      end
      wrapPara(text:sub(start, at - 1))
      start = at + 1
    end
  else
    wrapPara(text)
  end
  if #lines < 1 then lines[1] = "" end
  return lines
end

function Game3:dialogueHasMore(box)
  if type(box) ~= "table" then return false end
  local lines = Game3.wrapDialogue(box.fullText or box.text or "",
    nil, self:font3WidthTable())
  return (box.textPage or 0) + Game3.MSG_LINES < #lines
end

-- Std_MsgboxYesNo is message + waitmessage, then yesnobox. Extra wrapped
-- lines (lost \p) must page on A before the YES/NO window can steal it.
function Game3:yesNoReady(box)
  return not self:printerBusy(box) and not self:dialogueHasMore(box)
end

function Game3:holdYesNoForDialogue(box)
  if type(box) ~= "table" or self:yesNoReady(box) then return false end
  if Input:wasPressed("a") or Input:wasPressed("b") then
    self:advanceDialogue(box)
  end
  return true
end

function Game3:advanceDialogue(box)
  if type(box) ~= "table" then return false end
  if self:printerBusy(box) then
    self:printerFinish(box)
    return true
  end
  if self:dialogueHasMore(box) then
    box.textPage = (box.textPage or 0) + Game3.MSG_LINES
    box.printSrc = nil
    box.printN = 0
    return true
  end
  return false
end

-- Top of the first message line: the frame's interior top plus the even
-- padding that centres two lines in it. See DLG_FRAME_TOP.
function Game3.dialogueTextY()
  return (Game3.DLG_FRAME_TOP + 1) * Game3.MENU_TILE + Game3.DLG_TEXT_PAD_Y
end

function Game3:drawDialogue(box, x, y, ink)
  if type(box) ~= "table" then return end
  x = x or Game3.DLG_TEXT_COL * Game3.MENU_TILE
  y = y or Game3.dialogueTextY()
  local lines = Game3.wrapDialogue(self:printedText(box), nil,
    self:font3WidthTable())
  self:setTextInk(ink or Game3.TEXT_INK)
  for i = 1, Game3.MSG_LINES do
    local line = lines[i]
    if line and line ~= "" then
      self:drawText(line, x, y + (i - 1) * Game3.MSG_LINE_H)
    end
  end
  -- text.c WaitWithDownArrow: prompt while waiting for A/B once the page
  -- has typed out (more pages OR dismiss). Static notes without printLive
  -- stay arrow-free (decor PC explainers, etc.).
  -- X is past MSG_WIDTH (right margin of the window) so the 8x16 arrow
  -- never covers the last glyph on a full second line.
  if box.printLive and not self:printerBusy(box) then
    self:drawDialogueContinueArrow(
      x + Game3.MSG_WIDTH_PX,
      y + Game3.MSG_LINE_H)
  end
end

-- pokeruby text.c sDownArrowTiles / DrawDownArrow: 4 frames of two 8x8
-- tiles (8x16) from graphics/fonts/down_arrow. GBA palette index 0 is
-- transparent; the baked PNG keys black to alpha. Not a "v" glyph.
function Game3:drawDialogueContinueArrow(x, y)
  local G = love.graphics
  local img = self:uiPic("down_arrow")
  if not img then
    img = self:grabImage("assets/generated/ui/down_arrow.png")
  end
  -- downArrowPos cycles 0..3 every few frames (UpdateDownArrowAnimation).
  local frame = math.floor(((self.vblankCounter or 0) / 8) % 4)
  if img then
    self._arrowQuads = self._arrowQuads or {}
    local q = self._arrowQuads[frame]
    if not q then
      local iw, ih = img:getDimensions()
      -- Prefer stock 8x16 strip (4 frames); fall back to 8x8 cells.
      local fh = (ih >= 64) and 16 or math.max(1, math.floor(ih / 4))
      q = love.graphics.newQuad(0, frame * fh, math.min(8, iw), fh, iw, ih)
      self._arrowQuads[frame] = q
    end
    -- Transparent matte + red ink; alpha blend, no opaque backing rect.
    local prevMode, prevAlpha = G.getBlendMode()
    G.setBlendMode("alpha")
    G.setColor(1, 1, 1, 1)
    G.draw(img, q, x, y)
    G.setBlendMode(prevMode, prevAlpha)
    return
  end
  G.setColor(0.90, 0.20, 0.18, 1)
  G.polygon("fill", x + 1, y + 2, x + 7, y + 2, x + 4, y + 8)
  G.setColor(1, 1, 1, 1)
end

function Game3:printerFinish(box)
  if type(box) ~= "table" then return end
  local text = box.fullText or box.text or ""
  box.fullText = text
  box.printN = #Game3.dialoguePageText(text, box.textPage or 0,
    self:font3WidthTable())
end

function Game3:stepPrinter(box, dt)
  if type(box) ~= "table" then return end
  dt = dt or 0
  if dt <= 0 then return end
  local text = box.text or ""
  local page = box.textPage or 0
  local key = text .. "\0" .. tostring(page)
  if box.printSrc ~= key then
    box.printSrc = key
    box.fullText = text
    box.printN = 0
    box.printWait = 0
  end
  box.printLive = true
  local pageText = Game3.dialoguePageText(text, page, self:font3WidthTable())
  if (box.printN or 0) >= #pageText then return end
  local delay = self:textDelay()
  if Input:isDown("a") or Input:isDown("b") then delay = 0 end
  if delay <= 0 then
    box.printN = #pageText
    return
  end
  box.printWait = (box.printWait or 0) + dt
  while box.printWait >= delay and (box.printN or 0) < #pageText do
    box.printWait = box.printWait - delay
    box.printN = (box.printN or 0) + 1
  end
end

-- Generated window chrome, keyed the same way as the boot cinema PNGs so a
-- cache from before the UI import just falls back to the flat rectangles.
function Game3:uiPic(name)
  local ui = self.data and self.data.ui
  local path = ui and ui[name]
  if type(path) ~= "string" then return nil end
  self._uiCache = self._uiCache or {}
  if self._uiCache[name] ~= nil then return self._uiCache[name] or nil end
  local img = self:grabImage(path)
  self._uiCache[name] = img or false
  return img
end

-- text_window.c TextWindow_GetFrameGraphics clamps unknown styles to frame 1.
function Game3:windowFrameStyle()
  local style = tonumber((self.options or {}).windowFrame) or 0
  if style < 0 or style >= Game3.WINDOW_FRAME_STYLES then return 0 end
  return math.floor(style)
end

function Game3:windowFrameQuad(sheet, col, row, style)
  self._frameQuads = self._frameQuads or {}
  local key = style .. ":" .. col .. ":" .. row
  local quad = self._frameQuads[key]
  if not quad then
    local T = Game3.MENU_TILE
    quad = love.graphics.newQuad(col * T, (style * 3 + row) * T, T, T,
      sheet:getDimensions())
    self._frameQuads[key] = quad
  end
  return quad
end

-- text_window.c DrawStandardFrame: the 9 ROM tiles are corners, edges and a
-- fill, repeated across the rect. Rects here are already tile-aligned.
function Game3:drawWindow(x, y, w, h)
  local G = love.graphics
  local sheet = self:uiPic("frames")
  if sheet then
    local T = Game3.MENU_TILE
    local style = self:windowFrameStyle()
    local cols = math.max(2, math.floor(w / T))
    local rows = math.max(2, math.floor(h / T))
    G.setColor(1, 1, 1, 1)
    for r = 0, rows - 1 do
      local sy = (r == 0) and 0 or ((r == rows - 1) and 2 or 1)
      for c = 0, cols - 1 do
        local sx = (c == 0) and 0 or ((c == cols - 1) and 2 or 1)
        G.draw(sheet, self:windowFrameQuad(sheet, sx, sy, style),
          x + c * T, y + r * T)
      end
    end
    return
  end
  -- pokeruby WINDOW_NORMAL: black outer, white fill, 2px blue inner frame.
  G.setColor(0.06, 0.06, 0.08, 1)
  G.rectangle("fill", x, y, w, h)
  G.setColor(0.97, 0.97, 0.94, 1)
  G.rectangle("fill", x + 1, y + 1, w - 2, h - 2)
  G.setColor(0.36, 0.56, 0.84, 1)
  G.rectangle("fill", x + 2, y + 2, w - 4, 2)
  G.rectangle("fill", x + 2, y + h - 4, w - 4, 2)
  G.rectangle("fill", x + 2, y + 2, 2, h - 4)
  G.rectangle("fill", x + w - 4, y + 2, 2, h - 4)
end

function Game3:drawStdWindow(left, top, right, bottom)
  local x, y, w, h = Game3.stdWindowRect(left, top, right, bottom)
  self:drawWindow(x, y, w, h)
end

function Game3:drawDialogueFrame()
  self:drawStdWindow(
    Game3.DLG_FRAME_LEFT, Game3.DLG_FRAME_TOP,
    Game3.DLG_FRAME_RIGHT, Game3.DLG_FRAME_BOTTOM)
end

-- pokeruby GetStringWidthInTilesForScriptMenu: GetStringWidth, ceil to 8px.
function Game3.stringWidthTiles(text, widths)
  local px = Game3.textWidth(text, widths)
  if px < 1 then return 1 end
  return math.floor((px + Game3.MENU_TILE - 1) / Game3.MENU_TILE)
end

-- pokeruby script_menu.c DrawMultichoiceMenu: left/top/right/bottom tiles.
function Game3.multichoiceFrame(left, top, labels)
  labels = labels or {}
  local count = #labels
  if count < 1 then count = 1 end
  local width = 1
  for i = 1, #labels do
    local w = Game3.stringWidthTiles(labels[i])
    if w > width then width = w end
  end
  left = tonumber(left) or 0
  top = tonumber(top) or 0
  local right = width + left + 1
  if right > Game3.MULTI_MAX_RIGHT then
    left = left + (Game3.MULTI_MAX_RIGHT - right)
    right = Game3.MULTI_MAX_RIGHT
    if left < 0 then left = 0 end
  end
  local bottom = top + (2 * count + 1)
  return left, top, right, bottom
end

function Game3:drawMenuListWindow(left, top, labels, cursor, perRow)
  labels = labels or {}
  local count = #labels
  if count < 1 then return end
  local tile = Game3.MENU_TILE
  local cols = tonumber(perRow) or 0
  if cols < 2 then cols = 1 end
  local rows = math.ceil(count / cols)
  local left0, top0, right, bottom
  if cols > 1 then
    local width = 1
    for i = 1, count do
    local w = Game3.stringWidthTiles(labels[i], self:font3WidthTable())
      if w > width then width = w end
    end
    left0 = tonumber(left) or 0
    top0 = tonumber(top) or 0
    right = left0 + cols * (width + 1) + 1
    if right > Game3.MULTI_MAX_RIGHT then right = Game3.MULTI_MAX_RIGHT end
    bottom = top0 + (2 * rows + 1)
  else
    left0, top0, right, bottom = Game3.multichoiceFrame(left, top, labels)
  end
  local x = left0 * tile
  local y = top0 * tile
  local w = (right - left0 + 1) * tile
  local h = (bottom - top0 + 1) * tile
  self:drawWindow(x, y, w, h)
  local cur = cursor or 0
  local colW = cols > 1 and math.floor((right - left0) / cols) * tile or 0
  for i = 0, count - 1 do
    local col, row
    if cols > 1 then
      col = i % cols
      row = math.floor(i / cols)
    else
      col, row = 0, i
    end
    local tx = (left0 + 1) * tile + col * (colW > 0 and colW or 0)
    local ty = (top0 + 1) * tile + row * 16
    if i == cur then
      love.graphics.setColor(0.90, 0.28, 0.22, 1)
      self:drawCursor(tx, ty)
    end
    love.graphics.setColor(0.10, 0.10, 0.12, 1)
    self:drawText(labels[i + 1] or "", tx + 10, ty)
  end
end

function Game3:drawYesNoWindow(left, top, cursor)
  local tile = Game3.MENU_TILE
  left = tonumber(left) or Game3.YESNO_LEFT
  top = tonumber(top) or Game3.YESNO_TOP
  local w = (Game3.YESNO_RIGHT_OFF + 1) * tile
  local h = (Game3.YESNO_BOTTOM_OFF + 1) * tile
  self:drawWindow(left * tile, top * tile, w, h)
  local labels = { "YES", "NO" }
  for i = 0, 1 do
    local y = (top + 1) * tile + i * 16
    local x = (left + 1) * tile
    if i == (cursor or 0) then
      love.graphics.setColor(0.90, 0.28, 0.22, 1)
      self:drawCursor(x, y)
    end
    love.graphics.setColor(0.10, 0.10, 0.12, 1)
    self:drawText(labels[i + 1], x + 10, y)
  end
end

function Game3:drawCursor(x, y, color)
  local G = love.graphics
  if color then
    G.setColor(color[1], color[2], color[3], color[4] or 1)
  else
    G.setColor(0.22, 0.22, 0.28, 1)
  end
  if G.polygon then
    G.polygon("fill", x, y + 2, x, y + 12, x + 6, y + 7)
  else
    G.rectangle("fill", x, y + 4, 6, 6)
  end
end

-- battle_controller_player.c: a 1px red outline around the command / move,
-- not the field triangle. menu.pal index 2.
function Game3:drawBattleCursor(x, y, w, h, color)
  local G = love.graphics
  local c = color or Game3.BATTLE_CURSOR
  G.setColor(c[1], c[2], c[3], c[4] or 1)
  G.rectangle("line", x, y, w, h or 14)
end

-- gSpriteAnim_83F76FC: selected ball wiggles tiles 16/0/32 then rests.
function Game3.starterBallAnimFrame(selected, seconds)
  if not selected then return 0 end
  local cycle = math.floor((seconds or 0) * 60) % 64
  if cycle >= 32 then return 0 end
  local step = math.floor(cycle / 4) % 4
  if step == 0 then return 1 end
  if step == 2 then return 2 end
  return 0
end

-- sub_810A62C: y2 = Sin(data[1], 8); data[1] += 4 per vblank (256-step circle).
function Game3.starterHandBob(seconds)
  local idx = (math.floor((seconds or 0) * 60) * 4) % 256
  return math.sin(idx * 2 * math.pi / 256) * 8
end

-- Circle AFFINEANIMCMD 20 then +20 x15; poke 16 then +16 x15; both walk to
-- STARTER_PKMN_POS at 4px/2px per frame (StarterPokemonSpriteAnimCallback).
function Game3.starterRevealState(fromX, fromY, seconds)
  local frames = math.floor((seconds or 0) * 60)
  if frames < 0 then frames = 0 end
  local tx = Game3.STARTER_PKMN_POS[1]
  local ty = Game3.STARTER_PKMN_POS[2]
  local x, y = fromX, fromY
  local dx = 4 * frames
  local dy = 2 * frames
  if x < tx then
    x = x + dx
    if x > tx then x = tx end
  elseif x > tx then
    x = x - dx
    if x < tx then x = tx end
  end
  if y < ty then
    y = y + dy
    if y > ty then y = ty end
  elseif y > ty then
    y = y - dy
    if y < ty then y = ty end
  end
  local grow = frames
  if grow > Game3.STARTER_REVEAL_FRAMES then grow = Game3.STARTER_REVEAL_FRAMES end
  return x, y, (20 + 20 * grow) / 256, (16 + 16 * grow) / 256
end

-- starter_choose.c: Task_StarterChoose1 prints the rescue banner once and it
-- stays up through browsing; Task_StarterChoose3/4 wait for the ball-open
-- circle before showing the front sprite + "Do you choose this POKeMON?"
function Game3:drawStarterChoose(f)
  local G = love.graphics
  local pick = f.cursor or 1
  if f.kind == "starter_yesno" then pick = f.pick or pick end
  local t = self.playSeconds or 0
  local revealing = f.kind == "starter_yesno"
  local revealSec = 0
  if revealing then
    revealSec = t - (f.revealStart or 0)
    if revealSec < 0 then revealSec = 0 end
  end
  local bg = self.cinemaPic and self:cinemaPic("starterBg")
  local balls = self.cinemaPic and self:cinemaPic("starterBalls")
  local circle = self.cinemaPic and self:cinemaPic("starterCircle")
  if bg then
    G.setColor(1, 1, 1, 1)
    G.draw(bg, 0, 0)
  else
    G.setColor(0.42, 0.74, 0.38, 1)
    G.rectangle("fill", 0, 0, Game3.SCREEN_W, Game3.SCREEN_H)
    G.setColor(0.32, 0.62, 0.28, 1)
    for y = 0, Game3.SCREEN_H, 8 do
      G.rectangle("fill", 0, y, Game3.SCREEN_W, 3)
    end
    if self.drawOwSprite then
      self:drawOwSprite(Game3.GFX_BIRCHS_BAG, 3.5, 6.5, "south", false, 0, 0)
    end
  end
  local bounce = math.floor(math.sin(t * 10) * 3 + 0.5)
  for i = 1, #Game3.STARTERS do
    local xy = Game3.STARTER_BALL_XY[i] or { 120, 80 }
    local x, y = xy[1], xy[2]
    local isPick = (i - 1) == pick
    if balls then
      local frame = Game3.starterBallAnimFrame(isPick, t)
      self:drawSpriteCenter(balls, x, y, frame * Game3.STARTER_BALL_SIZE, 0,
        Game3.STARTER_BALL_SIZE, Game3.STARTER_BALL_SIZE)
    else
      if isPick and not revealing then y = y - 4 - bounce end
      if isPick and revealing then
        local r = 8 + math.min(1, revealSec / Game3.STARTER_REVEAL_DUR) * 20
        G.setColor(1, 1, 1, 1)
        G.circle("fill", x, y, r)
      else
        G.setColor(0.93, 0.22, 0.22, 1)
        G.circle("fill", x, y, 8)
        G.setColor(1, 1, 1, 1)
        G.circle("fill", x, y, 7)
        G.setColor(0.93, 0.22, 0.22, 1)
        G.rectangle("fill", x - 7, y - 2, 14, 4)
        G.setColor(0.12, 0.12, 0.14, 1)
        G.circle("fill", x, y, 2)
        if isPick and not revealing then
          G.setColor(0.98, 0.82, 0.22, 1)
          G.polygon("fill", x - 4, y - 16, x + 4, y - 16, x, y - 10)
        end
      end
    end
  end
  if revealing then
    local from = Game3.STARTER_BALL_XY[pick + 1] or Game3.STARTER_PKMN_POS
    local species = f.species or Game3.STARTERS[pick + 1]
    local img = self:battlePic(species, "front")
    if circle or balls then
      local cx, cy, cscale, pscale = Game3.starterRevealState(
        from[1], from[2], revealSec)
      if circle then
        self:drawSpriteCenter(circle, cx, cy, 0, 0,
          Game3.STARTER_CIRCLE_SIZE, Game3.STARTER_CIRCLE_SIZE, cscale)
      else
        G.setColor(1, 1, 1, 1)
        G.circle("fill", cx, cy, 8 + math.min(1, cscale) * 24)
      end
      if img then
        G.setColor(1, 1, 1, 1)
        self:drawSpriteCenter(img, cx, cy, nil, nil, nil, nil, pscale)
      end
    elseif img and revealSec >= Game3.STARTER_REVEAL_DUR then
      local iw, ih = img:getDimensions()
      G.setColor(1, 1, 1, 1)
      G.draw(img, from[1] - iw / 2, from[2] - ih / 2)
    end
  end
  if balls then
    local hxy = Game3.STARTER_HAND_XY[pick + 1] or { 120, 56 }
    self:drawSpriteCenter(balls, hxy[1], hxy[2] + Game3.starterHandBob(t),
      Game3.STARTER_HAND_FRAME * Game3.STARTER_BALL_SIZE, 0,
      Game3.STARTER_BALL_SIZE, Game3.STARTER_BALL_SIZE)
  end
  -- CreateStarterPokemonLabel: ROM erases it when A opens the ball.
  if not revealing then
    local species = Game3.STARTERS[(pick or 0) + 1]
    if bg then
      local at = Game3.STARTER_LABEL_AT[pick + 1] or { 16, 10 }
      G.setColor(1, 1, 1, 1)
      self:drawText(self:starterCategoryText(species), at[1] * 8, at[2] * 8)
      self:drawText(self:speciesName(species), at[1] * 8, at[2] * 8 + 16)
    else
      G.setColor(0.10, 0.10, 0.12, 1)
      self:drawText(self:starterCategoryText(species), 150, 40)
      self:drawText(self:speciesName(species), 150, 52)
    end
  end
  self:drawDialogueFrame()
  G.setColor(0.10, 0.10, 0.12, 1)
  if revealing then
    self:drawText(f.text or Game3.TEXT_DO_YOU_CHOOSE_POKE, 10, 116)
    local labels = { "YES", "NO" }
    for i = 0, 1 do
      local y = 134 + i * 10
      if i == (f.cursor or 0) then self:drawCursor(8, y) end
      G.setColor(0.10, 0.10, 0.12, 1)
      self:drawText(labels[i + 1], 18, y)
    end
  else
    self:drawText(Game3.TEXT_BIRCH_IN_TROUBLE_1, 10, 116)
    self:drawText(Game3.TEXT_BIRCH_IN_TROUBLE_2, 10, 128)
  end
end

-- starter_choose.c CreateStarterPokemonLabel: category + name, not gated on
-- the dex "seen" flag the way dexCategoryText is (you haven't seen it yet).
function Game3:starterCategoryText(species)
  local row = self:speciesRow(species)
  local cat = row and row.category
  if type(cat) ~= "string" or cat == "" then return "" end
  return cat .. " POKeMON"
end

function Game3:drawMartMenu(f)
  local G = love.graphics
  local mode = f.mode or "root"
  G.setColor(0.10, 0.10, 0.12, 1)
  if mode == "root" then
    local labels = f.martKind == "decor" and { "BUY", "QUIT" }
      or { "BUY", "SELL", "QUIT" }
    local bottom = #labels * 2 + 1
    self:drawStdWindow(0, 0, 10, bottom)
    for i = 0, #labels - 1 do
      local y = 8 + i * 16
      if i == (f.cursor or 0) then self:drawCursor(8, y) end
      G.setColor(0.10, 0.10, 0.12, 1)
      self:drawText(labels[i + 1], 18, y)
    end
    return
  end
  self:drawStdWindow(14, 0, 29, 13)
  local list, nameOf, priceOf
  if mode == "sell" or (mode == "qty" and f.qtyFrom == "sell") then
    list = f.sellSlots or self:martSellSlots()
    nameOf = function(slot) return self:itemName(slot.id) end
    priceOf = function(slot)
      return math.floor((self:itemPrice(slot.id) or 0) / 2)
    end
  else
    list = f.items or {}
    nameOf = function(id)
      if f.martKind == "decor" then return self:decorationName(id) end
      return self:itemName(id)
    end
    priceOf = function(id)
      if f.martKind == "decor" then return self:decorationPrice(id) end
      return self:itemPrice(id)
    end
  end
  local start = f.listCursor or f.cursor or 0
  if mode ~= "qty" then start = f.cursor or 0 end
  local rows = 6
  if #list < 1 then
    G.setColor(0.10, 0.10, 0.12, 1)
    self:drawText("There's nothing here.", 120, 16)
  else
    for i = 0, rows - 1 do
      local row = list[start + i + 1]
      local y = 8 + i * 16
      if i == 0 and mode ~= "qty" then self:drawCursor(116, y) end
      G.setColor(0.10, 0.10, 0.12, 1)
      if row then
        local name = nameOf(row)
        local price = priceOf(row)
        self:drawText(name, 126, y)
        self:drawText(("$%d"):format(price or 0), 188, y)
      end
    end
  end
  if mode == "qty" then
    local qty = f.qty or 1
    local unit = 0
    if f.qtyFrom == "sell" then
      unit = math.floor((self:itemPrice(f.qtyItem) or 0) / 2)
    elseif f.martKind == "decor" then
      unit = self:decorationPrice(f.qtyItem)
    else
      unit = self:itemPrice(f.qtyItem)
    end
    self:drawStdWindow(0, 8, 13, 13)
    G.setColor(0.10, 0.10, 0.12, 1)
    self:drawText(("x %d"):format(qty), 12, 80)
    self:drawText(("$%d"):format(unit * qty), 12, 96)
  end
  if f.note then
    self:drawDialogueFrame()
    G.setColor(0.10, 0.10, 0.12, 1)
    self:drawText(f.note, 10, 128)
  end
end

-- battle_controller_player.c move selection: the four moves are a 2x2 grid
-- where bit 0 is the column and bit 1 the row. A press flips its bit only
-- when the slot it would land on actually holds a move, so the cursor never
-- wraps and never lands on an empty slot.
function Game3.moveCursorStep(cursor, dir, count)
  local bit = (dir == "left" or dir == "right") and 1 or 2
  local toward = (dir == "right" or dir == "down") and 1 or 0
  cursor = cursor or 0
  if math.floor(cursor / bit) % 2 == toward then return cursor end
  local moved = (toward == 1) and (cursor + bit) or (cursor - bit)
  if moved >= (count or 0) then return cursor end
  return moved
end

-- HandleAction_ChooseMove SELECT: dest starts at slot 0 unless the
-- source already is 0, then source+1. Never opens on the same slot.
function Game3.moveSwapDest(source)
  source = source or 0
  if source ~= 0 then return 0 end
  return source + 1
end

-- sub_802CA60: swap the two move records (id, PP, max PP travel
-- together). The battler is the party slot, so the order sticks after
-- the fight, matching the cart's party write (skipped only while
-- STATUS2_TRANSFORMED, which this port does not implement yet).
function Game3:swapMoveSlots(battler, a, b)
  if not battler or a == b then return false end
  local moves = battler.moves
  if type(moves) ~= "table" then return false end
  local i, j = (a or 0) + 1, (b or 0) + 1
  if not (moves[i] and moves[j]) then return false end
  moves[i], moves[j] = moves[j], moves[i]
  return true
end

-- battle_bg.c LoadBattleTextboxAndBackground: the bar is a band of the
-- cart's own tilemap. Extracted PNGs used the teal backgroundColor; the
-- fallback panels match the visible ROM fill instead.
function Game3:drawBattleBar(layout)
  -- battle*.png interiors were baked with menu.pal index 15 (teal), which is
  -- the window template's backgroundColor, not the painted fill. Blitting
  -- them covers the lavender panel. Callers fall back to drawBattlePanel.
  return false
end

-- menu.pal frame/fill when gBattleTextboxTilemap is not in the cache.
function Game3:drawBattlePanel(x, y, w, h)
  local G = love.graphics
  local frame, fill = Game3.BATTLE_BAR_FRAME, Game3.BATTLE_BAR_FILL
  G.setColor(frame[1], frame[2], frame[3], 1)
  G.rectangle("fill", x, y, w, h)
  G.setColor(fill[1], fill[2], fill[3], 1)
  G.rectangle("fill", x + 2, y + 2, w - 4, h - 4)
end

-- GetHPBarLevel / GetScaledHPFraction(..., 48): red when fraction < 10 (~20%).
-- HandleLowHpMusicChange plays SE_LOW_HEALTH at level 1; we also blink the
-- fill while that song would be armed (battle.lowHpSe).
Game3.LOW_HP_BLINK_FRAMES = 8

function Game3:hpBarRatio(hp, maxHp)
  hp, maxHp = tonumber(hp) or 0, tonumber(maxHp) or 0
  if maxHp <= 0 then return 0 end
  return hp / maxHp
end

function Game3:hpBarIsRed(hp, maxHp)
  local hpN, maxN = tonumber(hp) or 0, tonumber(maxHp) or 0
  if maxN <= 0 or hpN <= 0 then return false end
  -- Match updateLowHpSe / GetHPBarLevel == 1 (scaled fraction < 10 of 48).
  return (hpN / maxN) <= 0.2
end

function Game3:lowHpBarBlinkOn()
  local period = Game3.LOW_HP_BLINK_FRAMES
  return math.floor((self.vblank or 0) / period) % 2 == 0
end

function Game3:drawHpBar(x, y, w, hp, maxHp, opts)
  local G = love.graphics
  G.setColor(0.12, 0.12, 0.14, 1)
  G.rectangle("fill", x, y, w, 4)
  local fill = 0
  if maxHp and maxHp > 0 then fill = math.floor(w * (hp or 0) / maxHp) end
  if fill < 0 then fill = 0 elseif fill > w then fill = w end
  local ratio = self:hpBarRatio(hp, maxHp)
  local red = ratio > 0 and ratio <= 0.2
  if red then G.setColor(0.90, 0.28, 0.22, 1)
  elseif ratio > 0.5 then G.setColor(0.35, 0.82, 0.38, 1)
  else G.setColor(0.90, 0.78, 0.22, 1) end
  -- Low-HP visual blink synced with SE_LOW_HEALTH (HandleLowHpMusicChange).
  if red and opts and opts.blink and not self:lowHpBarBlinkOn() then
    fill = 0
  end
  if fill > 0 then G.rectangle("fill", x, y, fill, 4) end
  G.setColor(1, 1, 1, 1)
end

function Game3:picYOffset(species, which)
  local pack = self.data.encounters or {}
  local ys = pack.frontY
  if which == "back" then ys = pack.backY end
  if type(ys) ~= "table" then return 0 end
  return ys[species] or ys[tostring(species)] or 0
end

function Game3.battlerCenter(side, doubles)
  local cx = doubles and Game3.BATTLER_CX_DOUBLES or Game3.BATTLER_CX
  local cy = doubles and Game3.BATTLER_CY_DOUBLES or Game3.BATTLER_CY
  return cx[side] or 72, cy[side] or 80
end

function Game3:battlerTopLeft(side, species, which)
  local cx, cy = Game3.battlerCenter(side, self.battle and self.battle.doubles)
  return cx - 32, cy - 32 + self:picYOffset(species, which)
end

function Game3:healthboxXY(side)
  local pack = (self.battle and self.battle.doubles)
    and Game3.HEALTHBOX_XY_DOUBLES or Game3.HEALTHBOX_XY
  local xy = pack[side] or Game3.HEALTHBOX_XY.player
  return xy[1], xy[2]
end

function Game3:drawBattleBackground()
  local G = love.graphics
  local env = self:battleEnvironment()
  local pack = self.data.encounters or {}
  local path = pack.bgs and (pack.bgs[env] or pack.bgs[tostring(env)])
  local img = type(path) == "string" and self:grabImage(path)
  if img then
    G.setColor(1, 1, 1, 1)
    G.draw(img, 0, 0)
    return
  end
  local fill = ({
    [0] = { 0.45, 0.72, 0.42 },
    [1] = { 0.38, 0.62, 0.32 },
    [2] = { 0.78, 0.70, 0.42 },
    [3] = { 0.18, 0.38, 0.62 },
    [4] = { 0.22, 0.48, 0.70 },
    [5] = { 0.32, 0.58, 0.62 },
    [6] = { 0.55, 0.48, 0.38 },
    [7] = { 0.32, 0.28, 0.28 },
    [8] = { 0.55, 0.52, 0.48 },
    [9] = { 0.62, 0.70, 0.48 },
  })[env] or { 0.55, 0.78, 0.62 }
  G.setColor(fill[1], fill[2], fill[3], 1)
  G.rectangle("fill", 0, 0, Game3.SCREEN_W, 112)
  G.setColor(fill[1] * 0.75, fill[2] * 0.75, fill[3] * 0.75, 1)
  G.ellipse("fill", 176, 56, 56, 14)
  G.ellipse("fill", 56, 96, 52, 12)
end

-- Interiors measured off the extracted frames. The cart bakes "Lv" and the
-- EXP track into the art, so the level digits and the EXP fill are placed
-- to line up with them.
-- UpdateHpTextInHealthbox / RenderTextHandleBold (gWindowTemplate_81E6C74):
-- HP digits use the 8px-tall bold/font4 face (same sheet party drawSmallText
-- already extracts), not FONT3. Fall back to FONT3 with right-align into
-- hpTextRight when that sheet is missing.
-- draw_status_ailment_maybe: status pills on BOTH player and enemy boxes
-- (player singles tile off 0x1A ~= px 16,24; enemy off 0x11 ~= 8,16).
Game3.HEALTHBOX_LAYOUT = {
  player = {
    frame = "healthboxPlayer",
    nameX = 14, nameY = 2, levelX = 82, levelY = 2,
    barX = 14, barY = 21, barW = 46,
    -- Font4 / UpdateHpTextInHealthbox digit row (8px tall).
    hpTextX = 64, hpTextY = 24, hpTextRight = 112,
    -- Status left of HP digits, just under the bar fill (barY=21 h=4).
    -- ROM overwrites healthbox tiles at r8=0x1A; we overlay here.
    statusX = 16, statusY = 24,
    expX = 32, expY = 35, expW = 68,
    fallbackW = 128, fallbackH = 40,
  },
  enemy = {
    frame = "healthboxEnemy",
    nameX = 6, nameY = 2, levelX = 74, levelY = 2,
    barX = 26, barY = 19, barW = 60,
    -- draw_status_ailment_maybe enemy r8=0x11 -> (~8,16).
    statusX = 8, statusY = 16, statusBarX = 44,
    caughtX = 88, caughtY = 8,
    fallbackW = 110, fallbackH = 28,
  },
}

-- GetHealthboxElementGfxPtr bases used by draw_status_ailment_maybe /
-- sub_80457E8 for battler 0 (same glyph for tox as psn; ROM uses STATUS1_PSN_ANY).
Game3.HEALTHBOX_STATUS_TILE = {
  psn = 0x15, tox = 0x15, par = 0x18, slp = 0x1B, frz = 0x1E, brn = 0x21,
}
Game3.HEALTHBOX_STATUS_W = 24  -- 3 tiles
Game3.HEALTHBOX_STATUS_H = 8
Game3.HEALTHBOX_ELEMENTS_COLS = 16

-- Battle interface status pills (pokeruby graphics/battle_interface/status_*.png):
-- 24x8, DynPal colours already baked (status.pal / gBattleInterfaceStatusIcons_DynPal).
-- Prefer these over party gStatusGfx_Icons (32px / 4 tiles).
Game3.BATTLE_STATUS_PILL_SHEET = "assets/generated/ui/battle_status_pills.png"
Game3.BATTLE_STATUS_PILL_ORDER = { "psn", "par", "slp", "frz", "brn" }
Game3.BATTLE_STATUS_PILL_PATH = {
  psn = "assets/generated/ui/battle_status_psn.png",
  tox = "assets/generated/ui/battle_status_psn.png",
  par = "assets/generated/ui/battle_status_par.png",
  slp = "assets/generated/ui/battle_status_slp.png",
  frz = "assets/generated/ui/battle_status_frz.png",
  brn = "assets/generated/ui/battle_status_brn.png",
}

-- Map mon.status onto gStatusGfx_Icons / healthbox element keys.
-- draw_status_ailment_maybe treats STATUS1_PSN|STATUS1_TOXIC as the PSN pill.
function Game3:healthboxStatusKey(status)
  if not status or status == "" or status == "none" then return nil end
  if Game3.isPoisonStatus(status) then return Game3.STATUS_PSN end
  if status == Game3.STATUS_BRN or status == Game3.STATUS_PAR
      or status == Game3.STATUS_SLP or status == Game3.STATUS_FRZ then
    return status
  end
  return nil
end

-- Battle healthbox status: prefer 24px battle-interface pills (status_*.png /
-- gHealthboxElementsGfxTable + DynPal), then healthbox sheet crop, then party
-- 32px icons, then FONT3 tag. ROM: draw_status_ailment_maybe.
function Game3:battleStatusPillImg(key)
  if not key then return nil end
  local path = Game3.BATTLE_STATUS_PILL_PATH and Game3.BATTLE_STATUS_PILL_PATH[key]
  if type(path) ~= "string" then return nil end
  self._battleStatusPill = self._battleStatusPill or {}
  if self._battleStatusPill[key] ~= nil then
    return self._battleStatusPill[key] or nil
  end
  local img = self:grabImage(path)
  if not img then
    -- Optional: live pokeruby tree (same as MoveAnim sprite fallback).
    local alt = ("misc/pokeruby-master/pokeruby-master/graphics/battle_interface/status_%s.png")
      :format(key == "tox" and "psn" or key)
    img = self:grabImage(alt)
  end
  self._battleStatusPill[key] = img or false
  return img
end

function Game3:drawBattleStatusPill(key, x, y)
  if not key then return false end
  local G = love.graphics
  if not G then return false end
  -- Sheet first (one decode); per-status PNGs as fallback.
  local sheetPath = Game3.BATTLE_STATUS_PILL_SHEET
  if type(sheetPath) == "string" and G.newQuad then
    self._battleStatusSheet = self._battleStatusSheet or self:grabImage(sheetPath) or false
    local sheet = self._battleStatusSheet
    if sheet then
      local order = Game3.BATTLE_STATUS_PILL_ORDER or {}
      local row
      local want = (key == "tox") and "psn" or key
      for i = 1, #order do
        if order[i] == want then
          row = i - 1
          break
        end
      end
      if row then
        self._battleStatusQuads = self._battleStatusQuads or {}
        local quad = self._battleStatusQuads[row]
        if not quad then
          quad = G.newQuad(0, row * Game3.HEALTHBOX_STATUS_H,
            Game3.HEALTHBOX_STATUS_W, Game3.HEALTHBOX_STATUS_H,
            sheet:getDimensions())
          self._battleStatusQuads[row] = quad
        end
        G.setColor(1, 1, 1, 1)
        G.draw(sheet, quad, x, y)
        return true
      end
    end
  end
  local img = self:battleStatusPillImg(key == "tox" and "psn" or key)
  if not img then return false end
  G.setColor(1, 1, 1, 1)
  G.draw(img, x, y)
  return true
end

function Game3:drawHealthboxStatus(status, x, y)
  local key = self:healthboxStatusKey(status)
  if not key then return false end
  local G = love.graphics
  -- 1) Battle interface 24px pills (ROM draw_status_ailment_maybe).
  if self:drawBattleStatusPill(key, x, y) then
    return true
  end
  -- 2) gHealthboxElementsGfxTable crop from extracted ui.healthbox sheet.
  local sheet = self:uiPic("healthbox")
  local tile = Game3.HEALTHBOX_STATUS_TILE[key]
  if sheet and tile and G.newQuad then
    self._hbStatusQuads = self._hbStatusQuads or {}
    local quad = self._hbStatusQuads[tile]
    if not quad then
      local cols = Game3.HEALTHBOX_ELEMENTS_COLS
      quad = G.newQuad(
        (tile % cols) * 8,
        math.floor(tile / cols) * 8,
        Game3.HEALTHBOX_STATUS_W, Game3.HEALTHBOX_STATUS_H,
        sheet:getDimensions())
      self._hbStatusQuads[tile] = quad
    end
    G.setColor(1, 1, 1, 1)
    G.draw(sheet, quad, x, y)
    return true
  end
  -- 3) Party gStatusGfx_Icons (32px) — wrong width for healthbox, last art resort.
  local art = self:menuArt("party")
  if art and self:drawPartyStatusIcon(art, key, x, y) then
    return true
  end
  -- 4) FONT3 tag.
  local tag = Game3.statusTag(status)
  if tag == "" then return false end
  G.setColor(0.70, 0.22, 0.22, 1)
  self:drawText(tag, x, y)
  G.setColor(1, 1, 1, 1)
  return true
end

-- UpdateHpTextInHealthbox: prefer font4 (RenderTextHandleBold / party sheet).
function Game3:drawHealthboxHpText(mon, x, y, L)
  local hpStr = ("%d/%d"):format(mon.hp or 0, mon.maxHp or 0)
  local art = self:menuArt("party")
  local right = x + (L.hpTextRight or (L.hpTextX + 48))
  local ty = y + L.hpTextY
  if art and art.font then
    local tw = self:smallTextWidth(art, hpStr)
    self:drawSmallText(art, hpStr, right - tw, ty)
    return
  end
  -- FONT3 fallback: right-align into the same slot so wide totals do not
  -- spill into the Lv column (HEALTHBOX_LAYOUT.hpTextRight).
  love.graphics.setColor(0.10, 0.10, 0.12, 1)
  local tw = Game3.textWidth(hpStr)
  self:drawText(hpStr, right - tw, ty)
  love.graphics.setColor(1, 1, 1, 1)
end

function Game3:drawHealthbox(mon, x, y, kind)
  if not mon then return end
  local G = love.graphics
  local player = kind == "player"
  local L = Game3.HEALTHBOX_LAYOUT[player and "player" or "enemy"]
  local frame = self:uiPic(L.frame)
  if frame then
    G.setColor(1, 1, 1, 1)
    G.draw(frame, x, y)
  else
    local w, h = L.fallbackW, L.fallbackH
    G.setColor(0.22, 0.22, 0.26, 1)
    G.rectangle("fill", x, y, w, h)
    G.setColor(0.97, 0.97, 0.90, 1)
    G.rectangle("fill", x + 1, y + 1, w - 2, h - 2)
  end
  G.setColor(0.10, 0.10, 0.12, 1)
  local name = mon.name or "POKeMON"
  self:drawText(name, x + L.nameX, y + L.nameY)
  local gend = self:monGender(mon)
  local gx = x + L.nameX + Game3.textWidth(name) + 2
  if gend == Game3.MON_MALE then
    self:drawGlyph(Game3.FONT_MALE, gx, y + L.nameY)
  elseif gend == Game3.MON_FEMALE then
    self:drawGlyph(Game3.FONT_FEMALE, gx, y + L.nameY)
  end
  G.setColor(0.10, 0.10, 0.12, 1)
  -- The frame already draws "Lv", so only the digits go here.
  self:drawText(tostring(mon.level or 1), x + L.levelX, y + L.levelY)
  local barX = L.barX
  if not player then
    if self:hasCaught(mon.species) then
      G.setColor(0.85, 0.22, 0.22, 1)
      if G.circle then
        G.circle("fill", x + L.caughtX, y + L.caughtY, 3)
        G.setColor(0.97, 0.97, 0.90, 1)
        G.circle("fill", x + L.caughtX - 1, y + L.caughtY - 1, 1)
      else
        G.rectangle("fill", x + L.caughtX - 3, y + L.caughtY - 3, 6, 6)
      end
    end
  end
  -- draw_status_ailment_maybe: player AND enemy (was player-missing).
  local hasStatus = self:healthboxStatusKey(mon.status) ~= nil
  if hasStatus and L.statusX then
    self:drawHealthboxStatus(mon.status, x + L.statusX, y + L.statusY)
    -- Enemy singles shift the HP bar right of the pill (statusBarX).
    if (not player) and L.statusBarX then
      barX = L.statusBarX
    end
  end
  local barW = L.barW - (barX - L.barX)
  local blink = player and self.battle and self.battle.lowHpSe
    and self:hpBarIsRed(mon.hp, mon.maxHp)
  self:drawHpBar(x + barX, y + L.barY, barW, mon.hp, mon.maxHp,
    { blink = blink })
  if player then
    self:drawHealthboxHpText(mon, x, y, L)
    local fill = Game3.expBarFill(mon)
    local ew = math.floor(L.expW * fill)
    if ew > 0 then
      G.setColor(0.32, 0.62, 0.95, 1)
      G.rectangle("fill", x + L.expX, y + L.expY, ew, 2)
    end
  end
  G.setColor(1, 1, 1, 1)
end


-- TryShinyAnimation (battle_anim_special.c): after the battler sprite is
-- visible, wait 60 frames, then two tasks each spawn 5 star particles every
-- 4 frames. Stream 0 orbits (Sin/Cos r=24); stream 1 streaks diagonally and
-- plays SE_SHINY once. Gate stays isShinyMon (shinyValue < 8).
-- Graphics: ANIM_TAG_GOLD_STARS = gBattleAnimPicTable[233] (16x24 sheet:
-- 16x16 frame for spawn 0, 8x8 tiles 4/5 for later spawns).
Game3.SHINY_SPARKLE_DELAY = 60 / 60
Game3.SHINY_SPARKLE_SPAWN_GAP = 4 / 60
Game3.SHINY_SPARKLE_COUNT = 5
Game3.SHINY_SPARKLE_ORBIT_LIFE = (256 / 12) / 60
Game3.SHINY_SPARKLE_STREAK_LIFE = (4 + 7) / 60
-- Keep a soft upper bound so a stalled particle cannot linger forever.
Game3.SHINY_SPARKLE_DUR = Game3.SHINY_SPARKLE_DELAY
  + Game3.SHINY_SPARKLE_COUNT * Game3.SHINY_SPARKLE_SPAWN_GAP
  + Game3.SHINY_SPARKLE_ORBIT_LIFE + 0.05
Game3.SHINY_GOLD_STARS_PATH = "assets/generated/battle/gold_stars.png"

function Game3:shinyGoldStarsImg()
  if self._shinyGoldStars ~= nil then
    return self._shinyGoldStars or nil
  end
  local img = self:grabImage(Game3.SHINY_GOLD_STARS_PATH)
  if not img then
    -- Dev fallback: pokeruby graphics tree (not shipped; never copy into git).
    local alt = "misc/pokeruby-master/pokeruby-master/graphics/battle_anims/sprites/233.png"
    img = self:grabImage(alt)
  end
  self._shinyGoldStars = img or false
  return img
end

function Game3:armShinySparkle(side, mon)
  local b = self.battle
  if not b or not mon or not self:isShinyMon(mon) then return end
  b.shinySparkles = b.shinySparkles or {}
  local cx, cy = Game3.battlerCenter(side, b.doubles and true or false)
  b.shinySparkles[#b.shinySparkles + 1] = {
    side = side,
    t = 0,
    cx = cx,
    cy = cy + 4,
    spawned = 0,
    nextSpawn = Game3.SHINY_SPARKLE_DELAY,
    sePlayed = false,
    particles = {},
  }
end

function Game3:stepShinySparkles(dt)
  local b = self.battle
  local list = b and b.shinySparkles
  if type(list) ~= "table" or #list == 0 then return end
  local keep = {}
  for i = 1, #list do
    local s = list[i]
    s.t = (s.t or 0) + dt
    s.particles = s.particles or {}
    while (s.spawned or 0) < Game3.SHINY_SPARKLE_COUNT
        and (s.t or 0) >= (s.nextSpawn or 0) do
      local idx = s.spawned or 0
      -- Two ROM tasks: orbit callback + streak callback per spawn index.
      s.particles[#s.particles + 1] = {
        kind = "orbit", age = 0, seed = idx,
      }
      s.particles[#s.particles + 1] = {
        kind = "streak", age = 0, seed = idx,
      }
      if not s.sePlayed and self.playSe then
        self:playSe(Game3.SE_SHINY)
        s.sePlayed = true
      end
      s.spawned = idx + 1
      s.nextSpawn = (s.nextSpawn or 0) + Game3.SHINY_SPARKLE_SPAWN_GAP
    end
    local alive = {}
    for p = 1, #s.particles do
      local part = s.particles[p]
      part.age = (part.age or 0) + dt
      local life = (part.kind == "streak")
        and Game3.SHINY_SPARKLE_STREAK_LIFE
        or Game3.SHINY_SPARKLE_ORBIT_LIFE
      if part.age < life then
        alive[#alive + 1] = part
      end
    end
    s.particles = alive
    local done = (s.spawned or 0) >= Game3.SHINY_SPARKLE_COUNT and #alive == 0
    if not done and (s.t or 0) < Game3.SHINY_SPARKLE_DUR + 0.25 then
      keep[#keep + 1] = s
    elseif not done then
      -- safety timeout
    end
  end
  b.shinySparkles = keep
end

function Game3:drawShinySparkles()
  local b = self.battle
  local list = b and b.shinySparkles
  if type(list) ~= "table" or #list == 0 then return end
  local G = love.graphics
  local sheet = self:shinyGoldStarsImg()
  local quads = self._shinyGoldQuads
  if sheet and not quads and G.newQuad then
    -- 233.png is 16x24: tiles [0..3]=16x16, tile4=(0,16) 8x8, tile5=(8,16) 8x8.
    quads = {
      G.newQuad(0, 0, 16, 16, 16, 24),
      G.newQuad(0, 16, 8, 8, 16, 24),
      G.newQuad(8, 16, 8, 8, 16, 24),
    }
    self._shinyGoldQuads = quads
  end
  local function star(x, y, seed, a)
    if a <= 0 then return end
    seed = seed or 0
    if sheet and quads then
      local q = quads[1]
      local ox, oy = 8, 8
      if seed >= 4 then
        q = quads[3]
        ox, oy = 4, 4
      elseif seed >= 1 then
        q = quads[2]
        ox, oy = 4, 4
      end
      G.setColor(1, 1, 1, a)
      G.draw(sheet, q, x - ox, y - oy)
      return
    end
    -- Procedural fallback when gold_stars.png is missing from the cache.
    local sz = (seed == 0) and 3.2 or 2.2
    G.setColor(1, 0.95, 0.35, a)
    if G.circle then G.circle("fill", x, y, sz) end
    G.setColor(1, 1, 1, a * 0.75)
    if G.circle then G.circle("fill", x, y, sz * 0.4) end
    G.setColor(1, 0.98, 0.55, a * 0.85)
    G.rectangle("fill", x - 0.5, y - sz * 1.6, 1, sz * 3.2)
    G.rectangle("fill", x - sz * 1.6, y - 0.5, sz * 3.2, 1)
  end
  for i = 1, #list do
    local s = list[i]
    local parts = s.particles or {}
    for p = 1, #parts do
      local part = parts[p]
      local age = part.age or 0
      if part.kind == "orbit" then
        -- sub_8141B20: x2 = Sin(ang, 24); y2 = Cos(ang, 24); ang += 12 /frame
        local ang = (age * 60 * 12) * (math.pi / 128)
        local x = s.cx + math.sin(ang) * 24
        local y = s.cy + math.cos(ang) * 24
        local life = Game3.SHINY_SPARKLE_ORBIT_LIFE
        local fade = 1 - (age / life)
        star(x, y, part.seed, fade)
      else
        -- sub_8141B74: invisible 4 frames, then x2 += 5, y2 -= 5 from (-32,32)
        local wait = 4 / 60
        if age >= wait then
          local u = age - wait
          local frames = u * 60
          local x = s.cx - 32 + frames * 5
          local y = s.cy + 32 - frames * 5
          local life = Game3.SHINY_SPARKLE_STREAK_LIFE
          local fade = 1 - (age / life)
          star(x, y, part.seed, fade)
        end
      end
    end
  end
  G.setColor(1, 1, 1, 1)
end

function Game3:drawBattlePic(species, which, x, y, scale, drop, flash, shiny)
  local G = love.graphics
  scale = scale or 1
  drop = drop or 0
  if type(shiny) == "table" then
    shiny = self:isShinyMon(shiny)
  end
  local img = self:battlePic(species, which, shiny and true or false)
  if flash then
    G.setColor(1, 1, 1, 0.45)
  else
    G.setColor(1, 1, 1, 1)
  end
  if img then
    G.draw(img, x, y + drop, 0, scale, scale)
  else
    local w = math.floor(48 * scale)
    if which == "back" then
      G.setColor(0.93, 0.28, 0.22, flash and 0.45 or 1)
    else
      G.setColor(0.25, 0.18, 0.22, flash and 0.45 or 1)
    end
    G.rectangle("fill", x + 16, y + 12 + drop, w, w)
  end
end

function Game3:drawMoveAnimBurst(cx, cy, ma, hitLeft, dur)
  local G = love.graphics
  dur = dur or 0.28
  local progress = 1 - (hitLeft / dur)
  if progress < 0 then progress = 0 elseif progress > 1 then progress = 1 end
  -- Soft peak alpha so generic typed FX match ROM-like translucency (enemy + player).
  local fade = (hitLeft / dur) * 0.82
  if fade < 0 then fade = 0 elseif fade > 1 then fade = 1 end
  if G.setBlendMode then pcall(G.setBlendMode, "alpha") end
  local r, g, b = Game3.typeRgb(ma and ma.type)
  local kind = ma and ma.kind or "physical"
  if kind == "special" then
    -- Beam of type-colored sparks toward the target.
    local n = 5
    for i = 0, n - 1 do
      local u = (progress * 1.2 - i * 0.12)
      if u > 0 and u < 1 then
        local ox = (ma and ma.onEnemy) and (-40 + 40 * u) or (40 - 40 * u)
        local oy = -8 + math.sin(u * math.pi * 2) * 4
        local a = fade * (1 - math.abs(u - 0.5) * 1.5)
        G.setColor(r, g, b, math.max(0, a))
        if G.circle then
          G.circle("fill", cx + ox, cy + oy, 2 + (1 - u) * 3)
        else
          G.rectangle("fill", cx + ox - 2, cy + oy - 2, 4, 4)
        end
      end
    end
    G.setColor(r, g, b, fade * 0.85)
    if G.circle then
      G.circle("fill", cx, cy, 4 + progress * 10)
      G.setColor(1, 1, 1, fade * 0.55)
      G.circle("fill", cx, cy, 2 + progress * 4)
    end
  elseif kind == "status" then
    local a = fade * 0.75
    G.setColor(r, g, b, a)
    if G.circle then
      G.circle("line", cx, cy, 6 + progress * 14)
      G.circle("line", cx, cy, 10 + progress * 10)
    end
    for i = 0, 3 do
      local ang = i * (math.pi / 2) + progress * math.pi
      local sx = cx + math.cos(ang) * (8 + progress * 10)
      local sy = cy + math.sin(ang) * (8 + progress * 10)
      G.setColor(r, g, b, a)
      G.rectangle("fill", sx - 1, sy - 1, 3, 3)
    end
  else
    -- Physical impact discs + cross.
    local burst = 5 + math.floor(progress * 12)
    G.setColor(r, g, b, fade)
    if G.circle then
      G.circle("fill", cx, cy, burst)
      G.setColor(1, 1, 1, fade * 0.7)
      G.circle("fill", cx, cy, math.max(2, burst * 0.4))
    else
      G.rectangle("fill", cx - burst, cy - burst, burst * 2, burst * 2)
    end
    G.setColor(r, g, b, fade * 0.9)
    G.rectangle("fill", cx - burst - 2, cy - 1, burst * 2 + 4, 3)
    G.rectangle("fill", cx - 1, cy - burst - 2, 3, burst * 2 + 4)
  end
  G.setColor(1, 1, 1, 1)
end

-- ROM Poké Ball sheets (Wave 5 Part B): palette-0 alpha extracts from pokeruby
-- graphics/interface/ball/*.png, horizontalized for quads.
Game3.RUBY_BALL_DIR = "assets/generated/battle/ruby_balls/"
Game3.RUBY_BALL_SIZE = 16
Game3.RUBY_BALL_BY_ITEM = {
  -- item ids: Master=1 Ultra=2 Great=3 Poke=4 Safari=5 ...
  [1] = "master",
  [2] = "ultra",
  [3] = "great",
  [4] = "poke",
  [5] = "safari",
  -- Net/Dive/Nest/Repeat/Timer/Luxury/Premier follow bag ids when present
  [6] = "net",
  [7] = "dive",
  [8] = "nest",
  [9] = "repeat",
  [10] = "timer",
  [11] = "luxury",
  [12] = "premier",
}

function Game3.rubyBallNameForItem(itemId)
  itemId = tonumber(itemId) or Game3.ITEM_POKE_BALL
  return Game3.RUBY_BALL_BY_ITEM[itemId] or "poke"
end

function Game3:loadRubyBallSheet(name)
  name = name or "poke"
  self._rubyBallSheets = self._rubyBallSheets or {}
  if self._rubyBallSheets[name] ~= nil then
    return self._rubyBallSheets[name] or nil
  end
  local path = (Game3.RUBY_BALL_DIR or "assets/generated/battle/ruby_balls/") .. name .. ".png"
  local img = nil
  if self.grabImage then
    img = self:grabImage(path)
  end
  if (not img) and love and love.graphics and love.graphics.newImage then
    -- Prefer ImageData so any residual pad can be keyed; files already have alpha.
    if love.image and love.image.newImageData then
      local okData, data = pcall(love.image.newImageData, path)
      if okData and data then
        local okImg, keyed = pcall(love.graphics.newImage, data)
        if okImg and keyed then img = keyed end
      end
    end
    if not img then
      local ok, raw = pcall(love.graphics.newImage, path)
      if ok and raw then img = raw end
    end
  end
  if img and img.setFilter then img:setFilter("nearest", "nearest") end
  self._rubyBallSheets[name] = img or false
  return img
end

function Game3:drawRubyBallSheet(bx, by, scale, open, opts)
  opts = opts or {}
  local name = opts.ballName or Game3.rubyBallNameForItem(opts.itemId)
  local ball = self:loadRubyBallSheet(name)
  if not (ball and ball.getDimensions) then
    -- Fall back to trade-ball extract (spin frames) as closed/open pair.
    ball = self:loadRubyBallSheet("trade_ball")
    if not (ball and ball.getDimensions) then return false end
    name = "trade_ball"
  end
  local G = love.graphics
  local iw, ih = ball:getDimensions()
  local fw = Game3.RUBY_BALL_SIZE or 16
  if fw > iw then fw = iw end
  local frames = math.max(1, math.floor(iw / fw))
  local frame = opts.frame
  if frame == nil then
    if open then
      frame = math.min(frames - 1, 1)
    else
      frame = 0
    end
  end
  if frame < 0 then frame = 0 elseif frame >= frames then frame = frames - 1 end
  local key = "rubyball:" .. name .. ":" .. frame
  self.quads = self.quads or {}
  local q = self.quads[key]
  if not q then
    q = love.graphics.newQuad(frame * fw, 0, fw, ih, iw, ih)
    self.quads[key] = q
  end
  local angle = opts.angle or 0
  local alpha = opts.alpha or 1
  local ds = scale or 1
  G.setColor(1, 1, 1, alpha)
  G.draw(ball, q, bx, by, angle, ds, ds, fw / 2, ih / 2)
  return true
end

-- Guaranteed textured Poké Ball for send-out (never rely on circle primitives).
-- tradeBall cinema sheet is often missing from assets/generated/trade/; catch can
-- still fall back to procedural, but foe send-out must stay unmistakable.
function Game3:ensureSendOutBallImg()
  if self._sendOutBallImg16 then return self._sendOutBallImg16 end
  if not (love and love.image and love.image.newImageData and love.graphics and love.graphics.newImage) then
    return nil
  end
  -- 16px matches tradeBall / real GBA Poke Ball on 240x160.
  local size = 16
  local ok, data = pcall(love.image.newImageData, size, size)
  if not ok or not data then return nil end
  local cx = (size - 1) * 0.5
  local cy = (size - 1) * 0.5
  local R = size * 0.5 - 0.75
  data:mapPixel(function(x, y)
    local dx = x - cx
    local dy = y - cy
    local dist = math.sqrt(dx * dx + dy * dy)
    if dist > R then
      return 0, 0, 0, 0
    end
    -- Outer outline
    if dist > R - 0.9 then
      return 0.05, 0.05, 0.08, 1
    end
    -- Center button
    if dist <= 2.6 then
      if dist <= 1.2 then
        return 1, 1, 1, 1
      end
      return 0.08, 0.08, 0.10, 1
    end
    -- Equator band
    if math.abs(dy) <= 1.0 then
      return 0.08, 0.08, 0.10, 1
    end
    -- Red top / white bottom
    if dy < 0 then
      return 0.92, 0.16, 0.16, 1
    end
    return 1, 1, 1, 1
  end)
  local ok2, img = pcall(love.graphics.newImage, data)
  if not ok2 or not img then return nil end
  if img.setFilter then img:setFilter("nearest", "nearest") end
  self._sendOutBallImg16 = img
  return img
end

function Game3:drawSendOutBall(bx, by, scale, open, opts)
  opts = opts or {}
  opts.sendOut = true
  opts.preferProcedural = false
  return self:drawCatchBall(bx, by, scale, open, opts)
end

function Game3:drawCatchBall(bx, by, scale, open, opts)
  local G = love.graphics
  scale = scale or 1
  opts = opts or {}
  local angle = opts.angle or 0
  local alpha = opts.alpha or 1
  local frameHint = opts.frame
  local itemId = opts.itemId
  local r = 7 * scale
  -- Send-out must use a textured Image draw (tradeBall or generated
  -- _sendOutBallImg16). Procedural circles are invisible on some battle
  -- draw paths; catch cinema keeps the existing tradeBall/procedural path.
  local sendOut = opts.sendOut and true or false
  if sendOut then
    opts.preferProcedural = false
  end
  -- Prefer ROM interface ball sheets (palette-0 alpha, ~16px).
  if not opts.preferProcedural then
    local okRom = self:drawRubyBallSheet(bx, by, scale, open, {
      itemId = itemId,
      frame = frameHint,
      angle = angle,
      alpha = alpha,
      ballName = opts.ballName,
    })
    if okRom then return end
  end
  local ball = (not opts.preferProcedural) and self.cinemaPic and self:cinemaPic("tradeBall")
  if ball and ball.getDimensions then
    local iw, ih = ball:getDimensions()
    local fw = Game3.TRADE_BALL_SIZE or 16
    if fw > iw then fw = iw end
    local frames = math.max(1, math.floor(iw / fw))
    local frame = frameHint
    if frame == nil then
      frame = open and math.min(frames - 1, 1) or 0
    end
    if frame < 0 then frame = 0 elseif frame >= frames then frame = frames - 1 end
    local key = "catchball:" .. tostring(ball) .. ":" .. frame
    local q = self.quads and self.quads[key]
    if not q then
      q = love.graphics.newQuad(frame * fw, 0, fw, ih, iw, ih)
      self.quads = self.quads or {}
      self.quads[key] = q
    end
    -- Send-out: tradeBall is 16px; caller scale (~1.0-1.55) sets on-screen size.
    local ds = scale
    G.setColor(1, 1, 1, alpha)
    G.draw(ball, q, bx, by, angle, ds, ds, fw / 2, ih / 2)
    return
  end
  -- Guaranteed send-out texture when cinema tradeBall is missing.
  if sendOut then
    local img = self:ensureSendOutBallImg()
    if img and img.getDimensions then
      local iw, ih = img:getDimensions()
      G.setColor(1, 1, 1, alpha)
      -- 16px generated ball; caller scale ~1.0-1.55 -> ~16-24px on 240x160.
      G.draw(img, bx, by, angle, scale, scale, iw / 2, ih / 2)
      return
    end
  end
  -- Procedural half-colored / half-white Poke Ball (item-tinted; catch only).
  local top = Game3.catchBallColors(itemId)
  if G.circle then
    if open then
      local gap = 3 * scale
      G.setColor(top[1], top[2], top[3], alpha)
      G.circle("fill", bx, by - gap, r)
      G.setColor(1, 1, 1, alpha)
      G.circle("fill", bx, by + gap, r)
      G.setColor(0.10, 0.10, 0.12, alpha)
      G.rectangle("fill", bx - r, by - gap - 1 * scale, r * 2, 2 * scale)
      G.rectangle("fill", bx - r, by + gap - 1 * scale, r * 2, 2 * scale)
      G.setColor(1, 0.92, 0.45, alpha * 0.9)
      G.circle("line", bx, by, r + 4 * scale)
    else
      G.setColor(top[1], top[2], top[3], alpha)
      G.circle("fill", bx, by, r)
      G.setColor(1, 1, 1, alpha)
      G.rectangle("fill", bx - r, by, r * 2 + 0.5, r + 0.5)
      G.setColor(0.10, 0.10, 0.12, alpha)
      G.rectangle("fill", bx - r, by - 1 * scale, r * 2, 2 * scale)
      G.setColor(1, 1, 1, alpha)
      G.circle("fill", bx, by, 2.5 * scale)
      G.setColor(0.10, 0.10, 0.12, alpha)
      G.circle("line", bx, by, 2.5 * scale)
    end
  else
    G.setColor(top[1], top[2], top[3], alpha)
    G.rectangle("fill", bx - r, by - r, r * 2, r * 2)
  end
end

function Game3:drawCatchOpenBurst(cx, cy, u, itemId)
  local G = love.graphics
  local top = Game3.catchBallColors(itemId)
  local fade = 1 - u
  if fade < 0 then fade = 0 end
  for i = 0, 11 do
    local ang = i * (math.pi / 6) + u * 1.2
    local rad = 4 + u * 22
    local sx = cx + math.cos(ang) * rad
    local sy = cy + math.sin(ang) * rad
    local a = fade * (0.85 - (i % 3) * 0.12)
    G.setColor(top[1], top[2] * 0.85 + 0.15, top[3] * 0.5 + 0.2, a)
    if G.circle then
      G.circle("fill", sx, sy, 1.5 + (1 - u) * 2)
    else
      G.rectangle("fill", sx - 1, sy - 1, 3, 3)
    end
  end
  G.setColor(1, 0.92, 0.45, fade)
  if G.circle then
    G.circle("line", cx, cy, 5 + u * 16)
    G.setColor(1, 1, 1, fade * 0.7)
    G.circle("fill", cx, cy, 2 + u * 5)
  end
end

function Game3:drawCatchCinema(catch, catchT, catchDur)
  local b = self.battle
  if not (b and b.enemy and catch) then return end
  local G = love.graphics
  local epx, epy = self:battlerTopLeft("enemy", b.enemy.species, "front")
  epx = epx + 24
  epy = epy + 24
  local ppx, ppy = 48, 88
  local throw = catch.throw or Game3.CATCH_THROW
  local open = catch.open or 0
  local bounce = catch.bounce or 0
  local per = catch.perShake or Game3.CATCH_SHAKE
  local shakes = catch.shakes or 0
  local itemId = catch.itemId or Game3.ITEM_POKE_BALL
  local bx, by = epx, epy
  local ballOpen = false
  local scale = 1
  local angle = 0
  local frame = 0
  local afterOpen = throw + open
  local afterBounce = afterOpen + bounce
  local afterShakes = afterBounce + shakes * per

  if catchT < throw then
    local u = catchT / math.max(throw, 0.01)
    if u > 1 then u = 1 end
    local arc = math.sin(u * math.pi) * 36
    bx = ppx + (epx - ppx) * u
    by = ppy + (epy - ppy) * u - arc
    scale = 0.70 + 0.30 * u
    angle = u * math.pi * 2.5
    frame = math.floor(u * 6) % 2
  elseif catchT < afterOpen then
    local u = (catchT - throw) / math.max(open, 0.01)
    if u > 1 then u = 1 end
    ballOpen = u < 0.72
    frame = ballOpen and 1 or 2
    scale = 1 + 0.18 * math.sin(math.min(u, 1) * math.pi)
    bx, by = epx, epy
    if u < 0.55 then
      self:drawCatchOpenBurst(epx, epy, u / 0.55, itemId)
    end
  elseif catchT < afterBounce then
    local u = (catchT - afterOpen) / math.max(bounce, 0.01)
    if u > 1 then u = 1 end
    local bounceN = math.min(3, math.floor(u * 4))
    local localU = (u * 4) - bounceN
    local amp = 18 - bounceN * 4
    if amp < 4 then amp = 4 end
    by = epy - math.abs(math.cos(localU * math.pi)) * amp * (1 - u * 0.15)
    bx = epx
    frame = 0
    scale = 1
  else
    local shakeT = catchT - afterBounce
    local shakeN = math.floor(shakeT / per)
    local frac = shakeT / per - shakeN
    bx, by = epx, epy
    frame = 0
    if shakeN < shakes then
      if frac < 0.18 then
        bx = epx
      elseif frac < 0.82 then
        local w = (frac - 0.18) / 0.64
        local dir = ((shakeN % 2) == 0) and 1 or -1
        bx = epx + dir * math.sin(w * math.pi) * 8
        angle = dir * math.sin(w * math.pi) * 0.35
        by = epy - math.abs(math.sin(w * math.pi * 2)) * 2
      end
    end
  end

  local drawBall = true
  if (not catch.ok) and catch.breakout and catchT > afterShakes then
    local u = (catchT - afterShakes) / math.max(catch.breakout, 0.01)
    if u > 1 then u = 1 end
    ballOpen = true
    frame = 1
    self:drawCatchOpenBurst(epx, epy, math.min(1, u * 1.4), itemId)
    if u < 0.55 then
      self:drawCatchBall(bx - 6 - u * 10, by - 2, scale, true, {
        itemId = itemId, frame = 1, alpha = 1 - u,
      })
      self:drawCatchBall(bx + 6 + u * 10, by + 2, scale, true, {
        itemId = itemId, frame = 1, alpha = 1 - u,
      })
      drawBall = false
    else
      drawBall = false
    end
  end
  if drawBall then
    self:drawCatchBall(bx, by, scale, ballOpen, {
      itemId = itemId, angle = angle, frame = frame,
    })
  end

  if catch.ok and catchT > afterShakes then
    local sparkT = catchT - afterShakes
    local fade = 1 - (sparkT / math.max(catch.stars or Game3.CATCH_STARS, 0.01))
    if fade < 0 then fade = 0 end
    for i = 0, 7 do
      local ang = i * (math.pi / 4) + sparkT * 3.2
      local rad = 7 + (sparkT % 0.28) * 34 + (i % 2) * 3
      local sx = bx + math.cos(ang) * rad
      local sy = by + math.sin(ang) * rad - sparkT * 6
      G.setColor(1, 1, 0.35, fade * 0.95)
      G.rectangle("fill", sx - 1, sy - 1, 3, 3)
      G.setColor(1, 0.95, 0.7, fade * 0.7)
      if G.circle then
        G.circle("fill", sx, sy, 1.2)
      end
    end
    G.setColor(1, 1, 0.55, fade * 0.75)
    if G.circle then
      G.circle("line", bx, by, 9 + (sparkT % 0.22) * 18)
    end
    if sparkT < 0.12 then
      G.setColor(1, 1, 1, (1 - sparkT / 0.12) * 0.85)
      if G.circle then
        G.circle("fill", bx, by, 3 + sparkT * 20)
      end
    end
  end
end

function Game3:drawBattle()
  local G = love.graphics
  local b = self.battle
  if b and b.kind == "dex_entry" then
    self:drawDexEntry(b)
    return
  end
  local iv = self:introCinemaVisuals()
  local hit = (b and b.animT) or 0
  local ma = b and b.moveAnim
  local animDur = (ma and ma.dur) or 0.28
  local lunge = 0
  if hit > 0 then
    local kind = ma and ma.kind
    local amp = (kind == "status") and 3 or ((kind == "special") and 5 or 8)
    lunge = math.floor(amp * math.sin(hit / animDur * math.pi) + 0.5)
  end
  local flash = hit > 0 and math.floor(hit * 24) % 2 == 1
  local catch = b and b.catchAnim
  local catchT = catch and (catch.t or 0) or 0
  local catchDur = Game3.catchAnimDuration(catch)
  local catching = catch and catchDur > 0 and (catchT < catchDur or catch.hold)
  self:drawBattleBackground()
  -- Opponent trainer (entrance / throw exit).
  if iv.showEnemyTrainer then
    local img = self:opponentTrainerImage(b and b.npc)
    local ex = (Game3.BATTLER_CX.enemy or 176) - 32 + (iv.enemyTrainerX or 0)
    local ey = (Game3.BATTLER_CY.enemy or 40) - 32
    self:drawBattleTrainerPic(img, ex, ey, 1, iv.enemyTrainerA or 1, false)
  end
  -- Player trainer back (entrance / throw exit).
  if iv.showPlayerTrainer then
    local img = self:playerTrainerBattleImage()
    local px = (Game3.BATTLER_CX.player or 72) - 32 - (iv.playerTrainerX or 0)
    local py = (Game3.BATTLER_CY.player or 80) - 40
    self:drawBattleTrainerPic(img, px, py, 1, iv.playerTrainerA or 1, true)
  end
  if b and b.enemy then
    local drop = ((b.enemy.hp or 0) <= 0) and 28 or 0
    local enemySpecies = b.enemy.species
    local enemyShiny = self:isShinyMon(b.enemy)
    if iv.recallSide == "enemy" and iv.recallSpecies then
      enemySpecies = iv.recallSpecies
      enemyShiny = iv.recallShiny and true or false
      drop = 0
    end
    local px, py = self:battlerTopLeft("enemy", enemySpecies, "front")
    local enemyLunge = (ma and ma.onEnemy) and lunge or ((ma and not ma.onEnemy) and -math.floor(lunge * 0.35) or lunge)
    px = px + math.floor(iv.enemySlide or 0) + enemyLunge
    local hideEnemy, enemyScale, enemyYOff, enemyAlpha =
      iv.enemyHide, iv.enemyScale or 1, 0, iv.enemyAlpha or 1
    if catching then
      hideEnemy, enemyScale, enemyYOff, enemyAlpha =
        Game3.catchEnemyVisual(catch, catchT)
    end
    -- Wave-4: Fly/Dig/Dive STATUS2_* hide between charge and hit turns.
    if b.enemy.invuln and iv.recallSide ~= "enemy" then hideEnemy = true end
    if not hideEnemy then
      local drawScale = enemyScale or 1
      local ox = math.floor(32 * (1 - drawScale) + 0.5)
      local oy = math.floor(32 * (1 - drawScale) + 0.5) + (enemyYOff or 0)
      if (enemyAlpha or 1) < 1 then
        love.graphics.setColor(1, 1, 1, enemyAlpha)
      end
      self:drawBattlePic(enemySpecies, "front",
        px + ox, py + oy + (flash and 1 or 0),
        drawScale, drop, flash, enemyShiny)
      if (enemyAlpha or 1) < 1 then
        love.graphics.setColor(1, 1, 1, 1)
      end
    end
    if hit > 0 and (not ma or ma.onEnemy) then
      self:drawMoveAnimBurst(px + 32, py + 32, ma, hit, animDur)
    end
    if not iv.hideBoxes then
      local hx, hy = self:healthboxXY("enemy")
      self:drawHealthbox(b.enemy, hx, hy, "enemy")
    end
  end
  if b and b.enemy2 then
    local drop = ((b.enemy2.hp or 0) <= 0) and 20 or 0
    local e2Species = b.enemy2.species
    local e2Shiny = self:isShinyMon(b.enemy2)
    if iv.recallSide == "enemy2" and iv.recallSpecies then
      e2Species = iv.recallSpecies
      e2Shiny = iv.recallShiny and true or false
      drop = 0
    end
    local px, py = self:battlerTopLeft("enemy2", e2Species, "front")
    if not iv.enemy2Hide then
      local drawScale = iv.enemy2Scale or 1
      local ox = math.floor(32 * (1 - drawScale) + 0.5)
      local oy = math.floor(32 * (1 - drawScale) + 0.5)
      if (iv.enemy2Alpha or 1) < 1 then love.graphics.setColor(1, 1, 1, iv.enemy2Alpha) end
      self:drawBattlePic(e2Species, "front", px + ox, py + oy, drawScale, drop, flash, e2Shiny)
      if (iv.enemy2Alpha or 1) < 1 then love.graphics.setColor(1, 1, 1, 1) end
    end
    if not iv.hideBoxes then
      local hx, hy = self:healthboxXY("enemy2")
      self:drawHealthbox(b.enemy2, hx, hy, "enemy")
    end
  end
  if b and b.player then
    local drop = ((b.player.hp or 0) <= 0) and 20 or 0
    local evo = self.evolve
    local species = b.player.species
    local scale, evoFlash = 1, false
    local playerShiny = self:isShinyMon(b.player)
    if evo and evo.mon == b.player then
      scale, evoFlash, species = self:evolveDraw()
    end
    if iv.recallSide == "player" and iv.recallSpecies then
      species = iv.recallSpecies
      playerShiny = iv.recallShiny and true or false
      drop = 0
    end
    local px, py = self:battlerTopLeft("player", species, "back")
    local playerLunge = (ma and not ma.onEnemy) and lunge
      or ((ma and ma.onEnemy) and -math.floor(lunge * 0.35) or -lunge)
    px = px - math.floor(iv.playerSlide or 0) + playerLunge
    local playerHide = iv.playerHide or (b.player and b.player.invuln)
    if not playerHide then
      local drawScale = (scale or 1) * (iv.playerScale or 1)
      local ox = math.floor(32 * (1 - drawScale) + 0.5)
      local oy = math.floor(32 * (1 - drawScale) + 0.5)
      if scale ~= 1 and (iv.playerScale or 1) == 1 then
        ox = math.floor(32 * (1 - scale))
        oy = math.floor(32 * (1 - scale))
        drawScale = scale
      end
      if (iv.playerAlpha or 1) < 1 then love.graphics.setColor(1, 1, 1, iv.playerAlpha) end
      self:drawBattlePic(species, "back", px + ox, py + oy, drawScale, drop, evoFlash, self:isShinyMon(b.player))
      if (iv.playerAlpha or 1) < 1 then love.graphics.setColor(1, 1, 1, 1) end
    end
    if hit > 0 and ma and not ma.onEnemy then
      self:drawMoveAnimBurst(px + 32, py + 32, ma, hit, animDur)
    end
    if not iv.hideBoxes and not iv.hidePlayerBox then
      local hx, hy = self:healthboxXY("player")
      self:drawHealthbox(b.player, hx, hy, "player")
    end
  end
  if b and b.player2 then
    local drop = ((b.player2.hp or 0) <= 0) and 16 or 0
    local p2Species = b.player2.species
    local p2Shiny = self:isShinyMon(b.player2)
    if iv.recallSide == "player2" and iv.recallSpecies then
      p2Species = iv.recallSpecies
      p2Shiny = iv.recallShiny and true or false
      drop = 0
    end
    local px, py = self:battlerTopLeft("player2", p2Species, "back")
    if not iv.player2Hide then
      local drawScale = iv.player2Scale or 1
      local ox = math.floor(32 * (1 - drawScale) + 0.5)
      local oy = math.floor(32 * (1 - drawScale) + 0.5)
      if (iv.player2Alpha or 1) < 1 then love.graphics.setColor(1, 1, 1, iv.player2Alpha) end
      self:drawBattlePic(p2Species, "back", px + ox, py + oy, drawScale, drop, false, p2Shiny)
      if (iv.player2Alpha or 1) < 1 then love.graphics.setColor(1, 1, 1, 1) end
    end
    if not iv.hideBoxes and not iv.hidePlayerBox then
      local hx, hy = self:healthboxXY("player2")
      self:drawHealthbox(b.player2, hx, hy, "player")
    end
  end
  -- Send-out ball overlay (reuse catch ball drawing).
  -- Prefer intro/switch send-out ball over catch cinema if both ever overlap.
  -- Drawn after trainers/mons so the foe throw is never buried under pics.
  local sendBalls = iv.balls or (iv.ball and { iv.ball }) or nil
  if sendBalls and #sendBalls > 0 then
    local G = love.graphics
    for bi = 1, #sendBalls do
      local ball = sendBalls[bi]
      if G.setColor then G.setColor(1, 1, 1, 1) end
      -- Ruby-ish size: 16px tradeBall / 16px fallback at ~1.0-1.55 -> 16-24px.
      local sc = (ball.scale or 1) * (ball.sendOut and 1.0 or 1.35)
      if ball.burst then
        self:drawCatchOpenBurst(ball.x, ball.y, ball.burst, Game3.ITEM_POKE_BALL)
        -- Second brighter ring so open flash reads on busy BGs.
        local G2 = love.graphics
        local u = ball.burst
        if G2.circle then
          G2.setColor(1, 0.92, 0.45, 1 - u)
          G2.circle("line", ball.x, ball.y, 10 + u * 26)
          G2.setColor(1, 1, 1, (1 - u) * 0.9)
          G2.circle("fill", ball.x, ball.y, 4 + u * 8)
        end
      end
      -- Ruby send-out: ball sprite only (no dark halo / debug outline).
      -- Send-out: textured tradeBall / _sendOutBallImg16 (never procedural circles).
      self:drawSendOutBall(ball.x, ball.y, sc, ball.open, {
        itemId = Game3.ITEM_POKE_BALL, angle = ball.angle or 0, frame = ball.frame,
        preferProcedural = false, alpha = 1,
      })
    end
  elseif catching then
    self:drawCatchCinema(catch, catchT, catchDur)
  end
  self:drawShinySparkles()
  if self.drawBattleFx then self:drawBattleFx() end
  if b and b.kind == "menu" then
    if not self:drawBattleBar("Actions") then
      self:drawBattlePanel(0, Game3.BATTLE_BAR_Y, 136, Game3.BATTLE_BAR_H)
      self:drawBattlePanel(136, Game3.BATTLE_BAR_Y, 104, Game3.BATTLE_BAR_H)
    end
    self:setTextInk(Game3.BATTLE_TEXT_INK)
    self:drawText("What will", 8, Game3.BATTLE_ACTION_Y)
    local pname = (b.player and b.player.name) or "POKeMON"
    self:drawText(pname .. " do?", 8, Game3.BATTLE_ACTION_Y + Game3.BATTLE_ACTION_ROW)
    local labels = { "FIGHT", "BAG", "POKeMON", "RUN" }
    if b.safari then
      labels = { "BALL", "POKeBLOCK", "GO NEAR", "RUN" }
    end
    for i = 0, 3 do
      local x = Game3.BATTLE_ACTION_X + (i % 2) * Game3.BATTLE_ACTION_COL
      local y = Game3.BATTLE_ACTION_Y + math.floor(i / 2) * Game3.BATTLE_ACTION_ROW
      if i == b.cursor then
        self:drawBattleCursor(x, y, Game3.BATTLE_ACTION_COL - 4)
      end
      self:setTextInk(Game3.BATTLE_TEXT_INK)
      self:drawText(labels[i + 1], x + 4, y)
    end
  elseif b and b.kind == "fight" then
    local battler = self:menuBattler() or b.player
    local moves = (battler and battler.moves) or {}
    if not self:drawBattleBar("Moves") then
      self:drawBattlePanel(0, Game3.BATTLE_BAR_Y, 176, Game3.BATTLE_BAR_H)
      self:drawBattlePanel(176, Game3.BATTLE_BAR_Y, 64, Game3.BATTLE_BAR_H)
    end
    -- 2x2, matching the cursor's bit 0 = column, bit 1 = row.
    -- During SELECT reorder, fightCursor is the source and moveSwap the dest
    -- (palette 0x1D vs 0x1B on the cart).
    local source = b.fightCursor or 0
    local dest = b.moveSwap
    for i = 0, 3 do
      local mv = moves[i + 1]
      local x = Game3.BATTLE_MOVE_X + (i % 2) * Game3.BATTLE_MOVE_COL
      local y = Game3.BATTLE_MOVE_Y + math.floor(i / 2) * Game3.BATTLE_MOVE_ROW
      if dest ~= nil then
        if i == dest then
          self:drawBattleCursor(x, y, Game3.BATTLE_MOVE_COL - 8)
        elseif i == source then
          self:drawBattleCursor(x, y, Game3.BATTLE_MOVE_COL - 8, 14,
            { 0.55, 0.55, 0.62, 1 })
        end
      elseif i == source then
        self:drawBattleCursor(x, y, Game3.BATTLE_MOVE_COL - 8)
      end
      self:setTextInk(Game3.BATTLE_TEXT_INK)
      self:drawText(mv and (mv.name or "-") or "-", x + 4, y)
    end
    local ix = Game3.BATTLE_MOVE_INFO_X
    self:setTextInk(Game3.BATTLE_TEXT_INK)
    if dest ~= nil then
      self:drawText(Game3.TEXT_SWITCH_WHICH, ix, Game3.BATTLE_MOVE_Y)
      self:drawText(Game3.TEXT_SWITCH_WHICH_2, ix,
        Game3.BATTLE_MOVE_Y + Game3.BATTLE_MOVE_ROW)
    else
      local cur = moves[source + 1]
      self:drawText("PP", ix, Game3.BATTLE_MOVE_Y)
      if cur then
        self:drawText(("%d/%d"):format(cur.pp or 0, cur.maxPp or 0), ix + 18,
          Game3.BATTLE_MOVE_Y)
      else
        self:drawText("--", ix + 18, Game3.BATTLE_MOVE_Y)
      end
      self:drawText(cur and Game3.typeName(cur.type) or "???", ix,
        Game3.BATTLE_MOVE_Y + Game3.BATTLE_MOVE_ROW)
    end
  elseif b and b.kind == "pokeblock_case" then
    self:drawMenuListWindow(0, 1, b.pokeblockLabels or { "CANCEL" },
      b.pokeblockCursor or 0)
  elseif b and b.kind == "bag" then
    -- item_menu.c RETURN_TO_BATTLE: the same pack screen as the field.
    self:drawBag({
      pocket = b.bagPocket or self.lastBagPocket or Game3.POCKET_ITEMS,
      cursor = b.bagCursor or 0,
    })
  else
  if not self:drawBattleBar("Message") then
    self:drawBattlePanel(0, Game3.BATTLE_BAR_Y, Game3.SCREEN_W, Game3.BATTLE_BAR_H)
  end
  if b and b.kind == "target" then
    local list = b.targetList or {}
    self:setTextInk(Game3.BATTLE_TEXT_INK)
    self:drawText("Aim at", 8, Game3.BATTLE_ACTION_Y)
    for i = 1, #list do
      local mon = list[i]
      local y = Game3.BATTLE_ACTION_Y + i * Game3.BATTLE_ACTION_ROW
      if i - 1 == (b.targetCursor or 0) then
        self:drawBattleCursor(6, y, 140, 14)
      end
      self:setTextInk(Game3.BATTLE_TEXT_INK)
      if mon then self:drawText(mon.name or "FOE", 18, y) end
    end
  elseif b and b.kind == "party" then
    -- battle_party_menu.c shows the same screen the field does.
    -- IsDoubleBattle() selects PARTY_MENU_LAYOUT_DOUBLE (two lead boxes
    -- stacked left); singles stay STANDARD. Both sides count slots from
    -- zero -- that is why CANCEL is 6 and not 7 -- so b.partyCursor
    -- passes straight through.
    local prompt = "Choose a POKeMON."
    if b.itemUse then prompt = "Use an item on which POKeMON?" end
    local layout = b.partyLayout
    if layout == nil and b.doubles then
      layout = Game3.PARTY_MENU_LAYOUT_DOUBLE
    end
    self:drawPartyScreen({
      kind = "party",
      cursor = b.partyCursor or 0,
      prompt = prompt,
      -- The mon already out cannot be sent out again, and neither can a
      -- fainted one; Ruby dims both instead of hiding them.
      noCancel = b.mustSwitch and true or nil,
      layout = layout,
    })
  elseif b and b.kind == "item_pp" then
    local mon = (self.party or {})[b.ppIndex or 1]
    local moves = mon and mon.moves or {}
    local actions = {}
    for i = 1, #moves do
      actions[i] = (moves[i] and moves[i].name) or "MOVE"
    end
    actions[#actions + 1] = "CANCEL"
    self:drawPartyAction({
      monIndex = b.ppIndex, cursor = b.ppCursor, actions = actions,
    })
  elseif b and b.kind == "switch_ask"
      or (b and (b.kind == "learn_yesno" or b.kind == "learn_stop"
        or b.kind == "catch_nick")) then
    self:setTextInk(Game3.BATTLE_TEXT_INK)
    self:drawText(self:printedText(b), 10, Game3.BATTLE_ACTION_Y)
    local labels = { "YES", "NO" }
    for i = 0, 1 do
      local y = 132 + i * 10
      if i == (b.cursor or 0) then
        self:drawBattleCursor(6, y, 80, 12)
      end
      self:setTextInk(Game3.BATTLE_TEXT_INK)
      self:drawText(labels[i + 1], 18, y)
    end
  elseif b and b.kind == "learn_forget" then
    local mon = self.learnMove and self.learnMove.mon
    local moves = mon and mon.moves or {}
    self:setTextInk(Game3.BATTLE_TEXT_INK)
    self:drawText("Forget which?", 8, 114)
    local n = #moves + 1
    for i = 0, n - 1 do
      local y = 124 + i * 8
      if i == (b.cursor or 0) then
        self:drawBattleCursor(6, y, 148, 12)
      end
      self:setTextInk(Game3.BATTLE_TEXT_INK)
      if i < #moves then
        self:drawText((moves[i + 1] and moves[i + 1].name) or "MOVE", 18, y)
      else
        self:drawText("CANCEL", 18, y)
      end
    end
  else
    self:drawDialogue(b, nil, nil, Game3.BATTLE_TEXT_INK)
  end
  end
  -- Final send-out ball pass: guarantee foe/player throw stays above the
  -- message bar chrome and any late UI (root cause of "invisible" foe ball
  -- when drawn only mid-pass under busy trainer fronts).
  local finalBalls = iv and (iv.balls or (iv.ball and { iv.ball })) or nil
  if finalBalls then
    for bi = 1, #finalBalls do
      local ball = finalBalls[bi]
      if ball and ball.sendOut then
        local G = love.graphics
        local sc = (ball.scale or 1) * 1.0
        if G.setColor then G.setColor(1, 1, 1, 1) end
        if ball.burst then
          self:drawCatchOpenBurst(ball.x, ball.y, ball.burst, Game3.ITEM_POKE_BALL)
        end
        -- No dark halo on final pass either (ROM send-out ball is unshadowed).
        self:drawSendOutBall(ball.x, ball.y, sc, ball.open, {
          itemId = Game3.ITEM_POKE_BALL, angle = ball.angle or 0, frame = ball.frame,
          preferProcedural = false, alpha = 1,
        })
      end
    end
  end
end

function Game3:walkHeld(dt)
  if self.phase == "play" then
    self.playSeconds = (self.playSeconds or 0) + (dt or 0)
    local frames = math.floor((dt or 0) * 60 + 0.0001)
    self.vblankCounter = (self.vblankCounter or 0) + frames
    self:tickBerryTrees(dt or 0)
    self:stepGrassRustle(dt or 0)
    self:stepTilesetAnim()
    -- field_tasks.c Task_RunPerStepCallback is an ordinary task, so it runs
    -- EVERY FRAME, not once per step: PerStepCallback_806A07C decrements
    -- data[4] / data[7] on each of them. Ticking this from the step callback
    -- instead meant a cracked floor only counted down while the player kept
    -- walking -- stand still on one and it never collapsed at all.
    self:tickCrackedFloors(frames)
    -- field_tasks.c Task_RunPerStepCallback runs every frame; STEP_CB_TRUCK
    -- is EndTruckSequence (box x2/y2 reset when cinema is idle).
    if self.stepCallback == Game3.STEP_CB_TRUCK then
      self:endTruckSequence()
    end
  end
  if self.phase == "battle_transition" then
    self:stepBattleEntrance(dt)
    return
  end
  if self.phase == "battle" then
    self:stepBattle(dt)
    return
  end
  if self.phase ~= "play" then return end
  self:stepCinemaWaits(dt or 0)
  self:stepScreenFade(dt or 0)
  self:stepDoorAnim(dt or 0)
  if self.field then
    if self.field.kind == "fishing" then
      self:stepFishing(dt or 0)
      self:clampCamera()
      return
    end
    if self.field.kind == "truck_seq" then
      self:stepTruckSequence(dt or 0)
      return
    end
    if self.field.kind == "cable_car" then
      self:stepCableCar(dt or 0)
      return
    end
    if self.field.kind == "porthole" then
      self:stepPorthole(dt or 0)
      return
    end
    if self.field.kind == "egg_hatch" then
      self:stepEggHatch(dt or 0)
      return
    end
    if self.field.kind == "trade_scene" then
      self:stepTradeScene(dt or 0)
      self:stepPrinter(self.field, dt or 0)
      return
    end
    if self.field.kind == "talk" or self.field.kind == "script_yesno"
        or self.field.kind == "safari_retire"
        or self.field.kind == "learn_yesno" or self.field.kind == "learn_stop"
        or self.field.kind == "egg_nick" then
      self:stepPrinter(self.field, dt or 0)
    end
    if self.field.kind == "evolve" then
      self:stepPrinter(self.field, dt or 0)
      self:stepEvolve(dt or 0)
      self:clampCamera()
      return
    end
    if self.field.kind == "trainer_approach" then
      self:stepTrainerApproach(dt or 0)
      self:clampCamera()
      return
    end
    if self.field.kind == "move" then
      self:stepScriptMove(dt or 0)
      self:clampCamera()
      if not self:scriptMoving() then self:resumeMoveScript() end
      return
    end
    -- field_fadetransition.c Task_DoDoorWarp: open → walk north → close → warp.
    if self.field.kind == "door_enter" then
      local f = self.field
      if f.phase == "open" then
        if not self:doorAnimating() then
          self:applyMovement(Game3.LOCALID_PLAYER, { { kind = "walk", dir = "north" } })
          f.phase = "walk"
        end
      elseif f.phase == "walk" then
        self:stepScriptMove(dt or 0)
        self:clampCamera()
        if not self:scriptMoving() then
          -- SetPlayerVisibility(FALSE) while the door closes over the mat.
          self.invisible = true
          self:closeDoor(f.x, f.y, true)
          f.phase = "close"
        end
      elseif f.phase == "close" then
        if not self:doorAnimating() then
          local w = self.pendingDoorWarp
          self.pendingDoorWarp = nil
          self.field = nil
          self.invisible = nil
          if w then self:followWarp(w) end
        end
      end
      return
    end
    -- field_fadetransition.c sub_8080B9C cases 1-3: waits for the forced
    -- entry step (queued by lightExitDoors), then plays the door closing
    -- behind the player. A standalone field kind rather than "move" so
    -- finishing it never runs resumeMoveScript against no active script.
    if self.field.kind == "door_arrival" then
      self:stepScriptMove(dt or 0)
      self:clampCamera()
      if not self:scriptMoving() then
        local f = self.field
        self.field = nil
        -- A non-animated door has no door to shut.
        if f.x then self:closeDoor(f.x, f.y, true) end
      end
      return
    end
    if self.field.kind == "delay" then
      self.delayLeft = (self.delayLeft or 0) - (dt or 0)
      if self.delayLeft < 0 then self.delayLeft = 0 end
      if not self:scriptDelaying() then self:resumeMoveScript() end
      return
    end
    if self.field.kind == "wait" then
      -- waitstate after a sync warp never arms scriptWait; resume so the
      -- player is not frozen on an idle wait tile.
      if self.flashAnim then
        self:stepFlashAnimDt(dt or 0)
      end
      -- logicStep() already calls stepFanfareWait() once, unconditionally,
      -- at the top of the frame (before phase/field dispatch even runs),
      -- so waitingFanfare is already resolved by the time we get here.
      -- A second stepFanfareWait() call here used to double-tick
      -- fanfareWaitAcc every frame and, worse, could itself resolve the
      -- wait and run the script all the way to a fresh pause (e.g. the
      -- "rest again?" yes/no after a heal fanfare). The unconditional
      -- resumeMoveScript() below would then fire AGAIN on that same
      -- frame and consume the fresh pause using the previous answer's
      -- stale VAR_RESULT -- auto-selecting YES before the prompt was
      -- ever drawn, which is why the old lady's rest stop looked like it
      -- healed forever with no visible prompt.
      if self.field and self.field.kind == "wait" and not self:scriptWaiting() then
        self:resumeMoveScript()
      end
      return
    end
    self:clampCamera()
    if not self._scriptPause then
      self:stepNpcs(dt or 0)
    end
    return
  end
  if self:flushPendingMapScripts() then
    self:clampCamera()
    self:stepNpcs(dt or 0)
    return
  end
  -- SetUpPlacingDecorationPlayerAvatar swaps the avatar's callback out, so
  -- the keypad drives the cursor and the player does not walk. Must beat
  -- the movement block below, not just the A/B one in update().
  if self:decorPlacingActive() then
    self:clampCamera()
    self:stepNpcs(dt or 0)
    return
  end
  -- gPlayerAvatar.preventStep while a mat's task owns the avatar.
  if self:stepSecretBaseMat(dt) then
    self:clampCamera()
    self:stepNpcs(dt or 0)
    return
  end
  if self:tryMapFrameScript() then
    self:clampCamera()
    self:stepNpcs(dt or 0)
    return
  end
  -- ScriptContext2 still enabled but field was cleared (battle start gap,
  -- failed presentScript, etc.): keep the avatar frozen and resume if a
  -- pause is still armed.
  if not self.field and self.fieldControlsLocked then
    if self._scriptPause then
      self:resumeMoveScript()
    end
    self:clampCamera()
    self:stepNpcs(dt or 0)
    return
  end
  if dt and dt > 1 / 20 then dt = 1 / 20 end
  local wasWalking = (self.walkCooldown or 0) > 0
  self.walkCooldown = (self.walkCooldown or 0) - (dt or 0)
  if self.walkCooldown > 0 then
    self:clampCamera()
  else
    if wasWalking then
      self.walkCooldown = 0
      self.hopping = nil
      -- PlayerAllowForcedMovementIfMovingSameDirection: once the player
      -- has actually moved, forced movement is allowed to trigger again.
      self.forcedMoveLatch = nil
      self:clampCamera()
      if self:tryTrainerSpot() then
        self:stepNpcs(dt or 0)
        return
      end
      if self.field then
        self:stepNpcs(dt or 0)
        return
      end
      if self:tryWildEncounter() then
        self:stepNpcs(dt or 0)
        return
      end
    end
    -- Forced movement beats keypad (player_step). One tile per cycle.
    if self:tryForcedMovement() then
      -- ice / current / slide / muddy; facing may stay locked
    else
      local dx, dy = 0, 0
      if Input:isDown("left") then dx = -1
      elseif Input:isDown("right") then dx = 1
      elseif Input:isDown("up") then dy = -1
      elseif Input:isDown("down") then dy = 1
      end
      if dx ~= 0 or dy ~= 0 then
        if self.warpSettle then
          -- Held input from the previous map must not walk us back into
          -- the stair warp. Wait for a release.
        else
          self.running = self:wantRun()
          local dir = Game3.facingFromDelta(dx, dy)
          if dir ~= self.facing then
            self.facing = dir
            -- ROM ProcessPlayerFieldInput: after facing matches dpad,
            -- mapheader_run_first_tag2 warps on the arrow mat. A tap
            -- that only turned still leaves.
            self:tryArrowWarpOnTile(dx, dy)
          else
            self:tryWalk(dx, dy)
          end
        end
      else
        self.running = nil
        self.warpSettle = nil
        -- ROM has no sticky ignoreWarp; landing faces away from the
        -- door. After the held key is released the next press may leave.
        self.ignoreWarp = false
      end
    end
  end
  self:clampCamera()
  self:stepNpcs(dt or 0)
  self:stepMapNamePopup(dt or 0)
end

function Game3:facingNpc()
  local map = self.map
  if not map then return nil end
  local dx, dy = Game3.deltaFromFacing(self.facing)
  local x, y = self.playerX + dx, self.playerY + dy
  local npc = self:npcAt(map, x, y)
  if npc then return npc end
  if Game3.isCounter(self:behaviorAt(map, x, y)) then
    return self:npcAt(map, x + dx, y + dy)
  end
end

function Game3.dirId(facing)
  local names = Game3.DIR_FACING
  for i = 1, #names do
    if names[i] == facing then return i end
  end
  return Game3.DIR_SOUTH
end

function Game3:rememberTalk(npc)
  self.scriptVars = self.scriptVars or {}
  self.scriptVars[Game3.VAR_LAST_TALKED] = (npc and npc.localId) or 0
  self.scriptVars[Game3.VAR_FACING] = Game3.dirId(self.facing)
end

-- event_object_lock.c sub_8064EAC: ObjectEventFaceOppositeDirection(
-- &gObjectEvents[gSelectedObjectEvent], gSpecialVar_Facing). gSelectedObjectEvent
-- / gSpecialVar_Facing are set together at interaction time
-- (field_control_avatar.c) -- self._scriptNpc / scriptVars[VAR_FACING] are
-- their Lua counterparts, set by rememberTalk the same way. Secret base
-- chair scripts use this to turn the seat to face the challenger.
local OPPOSITE_FACING = { north = "south", south = "north", west = "east", east = "west" }
function Game3:faceSelectedObjectOpposite()
  local npc = self._scriptNpc
  if not npc then return end
  local dir = Game3.DIR_FACING[self.scriptVars and self.scriptVars[Game3.VAR_FACING]]
  npc.facing = OPPOSITE_FACING[dir] or npc.facing
end

-- event_object_lock.c sub_8064ED4: ObjectEventClearHeldMovementIfActive.
function Game3:clearSelectedObjectMovement()
  local npc = self._scriptNpc
  if not npc or not npc.localId then return end
  local jobs = self.moveJobs
  if type(jobs) ~= "table" then return end
  for i = #jobs, 1, -1 do
    if jobs[i].localId == npc.localId then table.remove(jobs, i) end
  end
end

function Game3:tryTalk()
  local npc = self:facingNpc()
  if npc then
    self:rememberTalk(npc)
    local opp = { north = "south", south = "north", west = "east", east = "west" }
    npc.facing = opp[self.facing] or "south"
    npc.talkLock = true
    self:revealHiddenTrainer(npc)
    self._scriptNpc = npc
    local gid = npc.graphicsId or 0
    -- ROM nurse / Mom scripts own the heal. The stubs are only for maps
    -- whose objects have no script (unit tests, missing cache).
    if gid == Game3.GFX_NURSE and not npc.script
        and Game3.isNurseHealMap(self.map) then
      self:healParty()
      self:markHealPoint()
      self:incrementGameStat(Game3.GAME_STAT_USED_POKECENTER)
      self.field = { kind = "talk", text = "Your POKeMON were restored to full health!" }
    elseif gid == Game3.GFX_MOM and not npc.script
        and Game3.isMomHealMap(self.map) then
      self:healParty()
      self:markHealPoint()
      self:incrementGameStat(Game3.GAME_STAT_RESTED_AT_HOME)
      self.field = { kind = "talk", text = "MOM: You should rest a bit." }
    -- OLD_MAN_2 / OLD_WOMAN_2 are shared sprites (Route 109 beach grandpa,
    -- Berry Master's wife, Lavaridge mart, Mt. Pyre, …). Only stub Day Care
    -- when the map object has no ROM script — same gate as nurse / Mom / Teala.
    elseif gid == Game3.GFX_DAYCARE_MAN
        and not npc.script
        and (self.map and self.map.mapType) == Game3.MAP_TYPE_ROUTE then
      return self:talkDaycareMan()
    elseif gid == Game3.GFX_DAYCARE_LADY
        and not npc.script
        and (self.map and self.map.mapType) == Game3.MAP_TYPE_INDOOR then
      return self:openDaycare()
    elseif gid == Game3.GFX_TEALA
        and not npc.script
        and Game3.isContestLobbyMap(self.map) then
      return self:openContest()
    elseif npc.script then
      self._scriptNpc = npc
      if self:runNpcScript(npc.script) then return true end
      if (npc.trainerType or 0) > 0 and not npc.defeated
          and type(npc.party) == "table" and #npc.party > 0 then
        return self:startTrainerBattle(npc)
      end
      -- field_control_avatar.c TryStartInteractionScript: a script that
      -- runs but shows nothing (no msgbox reached) still consumes the A
      -- press in vanilla, but no textbox appears -- "..." was never real
      -- ROM dialogue, just this recomp inventing a box vanilla never
      -- shows.
      npc.talkLock = nil
    elseif (npc.trainerType or 0) > 0 and not npc.defeated
        and type(npc.party) == "table" and #npc.party > 0 then
      return self:startTrainerBattle(npc)
    elseif npc.itemId and not npc.hidden then
      return self:pickupItem(npc)
    -- Gfx 83 is also Oldale's street greeter and Route 110 cycling guards.
    -- Only open a shop when stock was baked from pokemart, or a test map
    -- opts in with martStub (default list = one POKe BALL).
    elseif (npc.mart and #npc.mart > 0)
        or (gid == Game3.GFX_MART and self.map and self.map.martStub) then
      return self:openMart(npc)
    elseif self:isStarterGiver(npc) and not self:hasStarter() then
      return self:openStarterMenu(npc)
    elseif gid == Game3.GFX_BIRCH and self:hasStarter() and not self:hasPokedex() then
      return self:givePokedex()
    elseif gid == Game3.GFX_BIRCH and self:giveNationalDex() then
      return true
    elseif self:talkRival(npc) then
      return true
    else
      -- field_control_avatar.c GetInteractedObjectEventScript: an object
      -- event with a NULL script pointer (Wally standing around before
      -- his scene, a hidden-rival cameo slot, plain decoration) makes A
      -- do nothing at all in vanilla -- no textbox, not even "...". This
      -- recomp used to invent one; matching the ROM data means showing
      -- nothing here too.
      npc.talkLock = nil
    end
    return true
  end
  -- field_control_avatar.c ProcessPlayerFieldInput runs these in a fixed
  -- order: object events, then BACKGROUND events, then metatile scripts,
  -- then water. tryBgEvent was last here, so a bg event sharing a tile with
  -- a scripted behaviour lost to the behaviour. Every such tile in Ruby is
  -- a BG_EVENT_SECRET_BASE (kind 8), which activateBg declines anyway, so
  -- this changes nothing on the shipped data -- it just stops the order
  -- from being wrong the next time a bg event lands on a live behaviour.
  if self:tryBgEvent() then return true end
  if self:tryInteractedMetatile() then return true end
  if self:tryPc() then return true end
  if self:trySecretBaseMetatile() then return true end
  if self:tryWaterfallInteract() then return true end
  if self:trySecretPowerInteract() then return true end
  -- GetInteractedWaterScript is last of the four.
  if self:canOfferSurf() then return self:openSurfPrompt() end
  return false
end

-- field_control_avatar.c GetInteractedMetatileScript. The behaviours were all
-- extracted and most of the handlers already existed, but nothing dispatched
-- on them, so pressing A on a bookshelf, vase, trash can, shop shelf,
-- blueprint, region map, running-shoes manual, link battle records, a
-- Pokeblock feeder, a Trick House puzzle door or a TV did nothing at all.
Game3.VAR_TRICK_HOUSE_ROOMS_COMPLETED = 0x4044
Game3.MB_CLOSED_SOOTOPOLIS_DOOR = 0x8B
Game3.MB_RUNNING_SHOES_MANUAL = 0x8E
Game3.GAME_STAT_WATCHED_TV = 44
Game3.MT_TRICK_HOUSE_STAIRS_DOWN = 0x20B

-- check_furniture.inc: each of these is a single msgbox and nothing else.
Game3.FURNITURE_TEXT = {
  [Game3.MB_PICTURE_BOOK_SHELF] =
    "There's a set of POKeMON picture books.",
  [Game3.MB_BOOKSHELF] =
    "It's filled with all sorts of books.",
  [Game3.MB_POKEMON_CENTER_BOOKSHELF] =
    "POKeMON magazines!\r\nPOKeMON PAL...\r\n"
      .. "POKeMON HANDBOOK...\r\nADORABLE POKeMON...",
  [Game3.MB_VASE] =
    "This vase looks expensive...\r\nPeered inside...\r\nBut, it was empty.",
  [Game3.MB_TRASH_CAN] = "It's empty.",
  [Game3.MB_SHOP_SHELF] =
    "The shelves brim with all sorts of\r\nPOKeMON merchandise.",
  [Game3.MB_BLUEPRINT] =
    "A blueprint of some sort?\r\nIt's too complicated!",
}

-- LittlerootTown_BrendansHouse_1F UnknownString_81728E3.
Game3.RUNNING_SHOES_MANUAL_TEXT =
  "It's the instruction booklet for the\r\nRUNNING SHOES.\r\n"
    .. "\"Press the B Button to run while\r\nwearing your RUNNING SHOES.\r\n"
    .. "\"Lace up your RUNNING SHOES and hit\r\nthe road running!\""

-- Route110_TrickHousePuzzle_EventScript_Door. All eight puzzle rooms share
-- the same door: the scroll has to have been read (the room's own state var
-- is non-zero), and then the door tile at (13,1) becomes the stairs out.
Game3.TRICK_HOUSE_PUZZLE_STATE = {
  [0] = 0x40AB, 0x40AC, 0x40AD, 0x40AE, 0x40AF, 0x40B0, 0x40B1, 0x40B2,
}

function Game3:trickHousePuzzleDoor()
  local rooms = self:varGet(Game3.VAR_TRICK_HOUSE_ROOMS_COMPLETED) or 0
  local stateVar = Game3.TRICK_HOUSE_PUZZLE_STATE[rooms]
  if not stateVar then return false end
  if (self:varGet(stateVar) or 0) == 0 then
    -- Route110_TrickHousePuzzle_EventScript_DoorLocked
    self.field = { kind = "talk", text =
      "The door is locked.\r\n...On closer inspection, this is written\r\n"
      .. "on it: \"Write the secret code here.\"" }
    return true
  end
  self:playSe(Game3.SE_PIN)
  self:setScriptVar(stateVar, 2)
  self:setMetatile(13, 1, Game3.MT_TRICK_HOUSE_STAIRS_DOWN, 0)
  self.field = { kind = "talk", text =
    ("%s wrote down the secret code\r\non the door.\r\n"):format(self:playerName())
    .. "\"TRICK MASTER is fabulous.\"\r\n... ... ... ... ... ... ... ...\r\n"
    .. "The lock clicked open!" }
  return true
end

-- safari_zone.inc gUnknown_081C346A.
function Game3:usePokeblockFeeder()
  local inFeeder = self:safariZoneGetPokeblockNameInFeeder()
  if inFeeder ~= 0xFFFF then
    -- UnknownString_81C3583, with STR_VAR_1 already set by the getter.
    self.field = { kind = "talk", text =
      ("The %s you left\r\nbefore is still here."):format(
        (self.stringVars and self.stringVars[1]) or "POKeBLOCK") }
    return true
  end
  self:openDecorYesNo(
    "Would you like to place a POKeBLOCK\r\non the POKeBLOCK FEEDER?",
    "openPokeblockCaseOnFeeder", true)
  return true
end

-- tv.inc Event_TV.
function Game3:watchTV()
  self:incrementGameStat(Game3.GAME_STAT_WATCHED_TV)
  self.tvShowState = 0
  local news = self:checkForBigMovieOrEmergencyNewsOnTV()
  if news == 2 then
    -- PlayersHouse_1F_Text_TheresAMovieOnTV: no TurnOffTVScreen on this one.
    self.field = { kind = "talk", text =
      "There is a movie on TV.\r\nTwo men are dancing on a big piano\r\n"
      .. "keyboard.\r\nBetter get going!" }
    return true
  end
  if news == 1 then
    -- Ruby's bulletin is the blue flying POKeMON; Sapphire's is the red one.
    self.field = { kind = "talk", text =
      "We bring you a special news bulletin.\r\n"
      .. "We've received reports of a blue FLYING\r\nPOKeMON in various HOENN "
      .. "locales.\r\nThe identity of this POKeMON has not\r\nyet been determined."
      .. "\r\nWe now return you to your regular\r\nmovie presentation." }
    self:initRoamer()
    self.flags = self.flags or {}
    self.flags[Game3.FLAG_SYS_TV_LATI] = nil
    self.flags[Game3.FLAG_LATIOS_OR_LATIAS_ROAMING] = true
    self:turnOffTVScreen()
    return true
  end
  self.flags = self.flags or {}
  if not self.flags[Game3.FLAG_SYS_TV_START]
      or self.flags[Game3.FLAG_SYS_TV_WATCH] then
    -- EventScript_1A6EF1: nothing is on, so it is just Mom or Dad's line.
    self:getMomOrDadStringForTVMessage()
    self.field = { kind = "talk", text =
      ("%s might like this program.\r\n"):format((self.stringVars and self.stringVars[1]) or "MOM")
      .. "... ... ... ... ... ... ... ... ... ... ... ... ... ... ... ...\r\n"
      .. "Better get going!" }
    self:turnOffTVScreen()
    return true
  end
  -- DoPokeNews sets VAR_RESULT; 0 means nothing was on and the script
  -- falls through to the show branch. 0 is truthy in Lua, so compare it.
  if (self:doPokeNews() or 0) ~= 0 then
    self.flags[Game3.FLAG_SYS_TV_WATCH] = true
    return true
  end
  -- EventScript_1A6EBB: a real show, if one is active.
  if self:special0x44() == Game3.TV_NO_SHOW then
    self:turnOffTVScreen()
    self.flags[Game3.FLAG_SYS_TV_WATCH] = true
    return true
  end
  local show = self:getNonMassOutbreakActiveTVShow()
  if show == Game3.TV_NO_SHOW then
    self:turnOffTVScreen()
    self.flags[Game3.FLAG_SYS_TV_WATCH] = true
    return true
  end
  self:setScriptVar(0x8004, show)
  self:doTVShow()
  self.flags[Game3.FLAG_SYS_TV_WATCH] = true
  return true
end

-- The dispatch itself, in GetInteractedMetatileScript's own order. The PC and
-- the four elevation-gated secret base tiles keep their existing entry points
-- (tryPc / trySecretBaseMetatile), which tryTalk still calls after this.
function Game3:tryInteractedMetatile()
  local map = self.map
  if not map then return false end
  local x, y = self:facingCell()
  local b = self:behaviorAt(map, x, y)

  -- MetatileBehavior_IsPlayerFacingTVScreen only answers TRUE facing north.
  if b == Game3.MB_TELEVISION then
    if self.facing ~= "north" then return false end
    return self:watchTV()
  end
  if b == Game3.MB_CLOSED_SOOTOPOLIS_DOOR then
    self.field = { kind = "talk", text = "The door is closed." }
    return true
  end
  if b == Game3.MB_LINK_BATTLE_RECORDS then
    self:showLinkBattleRecords()
    return true
  end
  if b == Game3.MB_POKEBLOCK_FEEDER then
    return self:usePokeblockFeeder()
  end
  if b == Game3.MB_TRICK_HOUSE_PUZZLE_DOOR then
    return self:trickHousePuzzleDoor()
  end
  if b == Game3.MB_REGION_MAP then
    -- EventScript_RegionMap: the line first, then the map behind a fadescreen.
    self.field = { kind = "talk", afterRegionMap = true, text =
      ("%s took a closer look at the\r\nHOENN region map."):format(
        self:playerName()) }
    return true
  end
  if b == Game3.MB_RUNNING_SHOES_MANUAL then
    self.field = { kind = "talk", text = Game3.RUNNING_SHOES_MANUAL_TEXT }
    return true
  end
  local furniture = Game3.FURNITURE_TEXT[b]
  if furniture then
    self.field = { kind = "talk", text = furniture }
    return true
  end
  return false
end

-- field_control_avatar.c GetInteractedMetatileScript, the block gated on
-- the player standing at the tile's own elevation: the secret base PC, the
-- record mixing PC, the sand ornament, and the shield / toy TV.
function Game3:trySecretBaseMetatile()
  local map = self.map
  if not map then return false end
  local x, y = self:facingCell()
  local b = self:behaviorAt(map, x, y)
  if Game3.isSecretBasePc(b) then
    return self:startSecretBasePC()
  end
  if b == Game3.MB_RECORD_MIXING_SECRET_BASE_PC then
    return self:startRecordMixingPC()
  end
  if b == Game3.MB_SECRET_BASE_SAND_ORNAMENT then
    -- SecretBase_EventScript_SandOrnament: dofieldeffect FLDEFF_SAND_PILLAR
    -- then waitstate. The pillar crumbles the ornament's own metatiles.
    self:doFieldEffect(Game3.FLDEFF_SAND_PILLAR)
    return true
  end
  if b == Game3.MB_SECRET_BASE_SHIELD_OR_TOY_TV then
    return self:secretBaseShieldOrToyTV()
  end
  return false
end

-- shared_secret_base.inc SecretBase_EventScript_PC: playse SE_PC_LOGIN,
-- "{PLAYER} booted up the PC.", the turn-on field effect behind a
-- waitstate, then the main menu.
function Game3:startSecretBasePC()
  self:playSe(Game3.SE_PC_LOGIN)
  self._afterSecretBasePcBoot = true
  self.field = {
    kind = "talk",
    text = ("%s booted up the PC."):format(self:playerName()),
    afterSecretBasePc = true,
  }
  self:doFieldEffect(Game3.FLDEFF_SECRET_BASE_PC_TURN_ON)
  return true
end

-- SecretBase_EventScript_PCShowMainMenu: multichoice 6 once
-- FLAG_SECRET_BASE_REGISTRY_ENABLED is up, otherwise multichoice 5.
function Game3:openSecretBasePCMenu()
  local withRegistry = self.flags
    and self.flags[Game3.FLAG_SECRET_BASE_REGISTRY_ENABLED]
  local labels = Game3.MULTICHOICE[withRegistry and 6 or 5]
  self.field = {
    kind = "decor_menu",
    labels = labels,
    note = "What would you like to do?",
    cursor = 0,
    onPick = "pickSecretBasePCMenu",
  }
  return true
end

function Game3:pickSecretBasePCMenu(index)
  local withRegistry = self.flags
    and self.flags[Game3.FLAG_SECRET_BASE_REGISTRY_ENABLED]
  if index == 0 then return self:secretBasePCDecoration() end
  if index == 1 then return self:openSecretBasePCPackUp() end
  if withRegistry and index == 2 then
    return self:runSpecial(Game3.SPECIAL_SECRET_BASE_PC_REGISTRY)
  end
  -- SecretBase_EventScript_PCTurnOff.
  self:closeField()
  self:doSecretBasePCTurnOffEffect()
end

-- SecretBase_EventScript_PCPackUp: the decorations warning, then
-- MoveOutOfSecretBase.
function Game3:openSecretBasePCPackUp()
  self:openDecorYesNo(
    "All decorations and furniture in your\r\nSECRET BASE will be returned "
      .. "to your PC.\r\nIs that okay?",
    "confirmSecretBasePackUp")
end

function Game3:confirmSecretBasePackUp()
  self:closeField()
  self:runSpecial(Game3.SPECIAL_MOVE_OUT_OF_SECRET_BASE)
end

-- SecretBase_EventScript_RecordMixingPC: the same boot-up, then the record
-- mixing menu. There is no link cable here, so it boots and turns off.
function Game3:startRecordMixingPC()
  self:playSe(Game3.SE_PC_LOGIN)
  self.field = {
    kind = "talk",
    text = ("%s booted up the PC."):format(self:playerName()),
    afterSecretBasePcOff = true,
  }
  self:doFieldEffect(Game3.FLDEFF_SECRET_BASE_PC_TURN_ON)
  return true
end

-- SecretBase_EventScript_ShieldOrToyTV: special 307 picks which of the
-- four signs to show.
Game3.SECRET_BASE_TV_TEXT = {
  [1] = "A realistic toy TV. It could be easily\r\nmistaken for the real thing.",
  [2] = "A toy TV shaped like a SEEDOT.\r\nIt looks ready to roll away on its own...",
  [3] = "A toy TV shaped like a SKITTY.\r\nIt looks ready to stroll away...",
}

function Game3:secretBaseShieldOrToyTV()
  local v = self:getShieldToyTVDecorationInfo()
  if v == 0 then
    self.field = { kind = "talk", text =
      ("A shield of %s that marks winning\r\n%s times in a row at the "
        .. "BATTLE TOWER."):format(self.stringVars[2] or "",
        self.stringVars[1] or "") }
    return true
  end
  local text = Game3.SECRET_BASE_TV_TEXT[v]
  if not text then return false end
  self.field = { kind = "talk", text = text }
  return true
end

function Game3:sayScript(text)
  if type(text) ~= "string" or text == "" then return end
  self._scriptSays = self._scriptSays or {}
  self._scriptSays[#self._scriptSays + 1] = self:expandScriptText(text)
end

function Game3:openScriptYesNo(text)
  local box = self._scriptYesNo or {}
  self._scriptYesNo = nil
  local x, y = box.x, box.y
  if x == nil then x = Game3.YESNO_LEFT end
  if y == nil then y = Game3.YESNO_TOP end
  self.field = {
    kind = "script_yesno",
    text = text or "...",
    cursor = 0,
    boxX = x,
    boxY = y,
  }
  return true
end

-- script_menu.c gMultichoiceLists, read straight off the ROM at import
-- (RomExtractorGen3.parseMultichoiceLists) -- all 73 of them. The table below
-- is ten lists somebody typed in by hand as each empty menu was noticed, so
-- anything not on that list had no options at all: the Battle Tower ferry
-- asks for list 53 and simply got nothing, which is why you could not sail
-- back. Kept as the fallback for a cache built before the table was read.
function Game3:multichoiceLabels(id)
  id = tonumber(id) or 0
  local menus = self.data and self.data.menus
  local rom = menus and menus.multichoice
  if type(rom) == "table" then
    local row = rom[id]
    if type(row) == "table" and #row > 0 then return row end
  end
  local row = Game3.MULTICHOICE[id]
  if type(row) == "table" and #row > 0 then return row end
end

function Game3:openScriptChoice(text, choice)
  choice = choice or self._scriptChoice or {}
  local labels = choice.labels or { "CANCEL" }
  local cursor = choice.cursor or 0
  if cursor < 0 or cursor >= #labels then cursor = 0 end
  self.field = {
    kind = "script_choice",
    text = text,
    labels = labels,
    cursor = cursor,
    ignoreB = choice.ignoreB and true or nil,
    boxX = choice.x or 0,
    boxY = choice.y or 0,
    perRow = choice.perRow,
  }
  return true
end

function Game3:answerScriptChoice(index)
  self.scriptVars = self.scriptVars or {}
  self.scriptVars[Gen3Script.VAR_RESULT] = tonumber(index) or Game3.MULTI_B_PRESSED
  self._scriptChoice = nil
  local pause = self._scriptPause
  self._scriptPause = nil
  if type(pause) ~= "table" or type(pause.ops) ~= "table" then
    self:closeField()
    self:endScriptRun()
    return false
  end
  self._scriptSays = {}
  local _, again = self:continueScript(pause.ops, pause.at)
  return self:presentScript(again)
end

function Game3:presentScript(pause)
  local says = self._scriptSays or {}
  self._scriptSays = nil
  if pause == "yesno" then
    local prompt = says[#says] or "..."
    local prior = {}
    for i = 1, #says - 1 do prior[i] = says[i] end
    self:fadeInFromBlack()
    if #prior > 0 then
      self.field = {
        kind = "talk", text = prior[1], queue = prior, qi = 1,
        thenYesNo = prompt,
      }
    else
      self:openScriptYesNo(prompt)
    end
    return true
  end
  if pause == "choice" then
    local prompt = says[#says]
    if not prompt and self.field and self.field.kind == "talk" then
      prompt = self.field.text
    end
    self:openScriptChoice(prompt, self._scriptChoice)
    return true
  end
  if pause == "msg" then
    if #says < 1 then return self:resumeMoveScript() end
    -- msgbox after fadescreen (TV, notebook, item text, …) must not stay
    -- under the held TO_BLACK veil.
    self:fadeInFromBlack()
    self.field = {
      kind = "talk", text = says[1], queue = says, qi = 1,
      thenContinue = true,
    }
    return true
  end
  if pause == "mart" then
    if not (self.field and self.field.kind == "mart") then
      self:openMartList(nil)
    end
    return true
  end
  if pause == "move" or pause == "delay" or pause == "wait" then
    -- StartWallClock / slots already own the field. Replacing them with
    -- the queued ClockIsStopped line left field=wait after A, so the
    -- setter never ran and waitstate never ended.
    if pause == "wait" and self.field and self.field.kind
        and self.field.kind ~= "wait" and self.field.kind ~= "talk" then
      return true
    end
    -- msgbox then waitmovement is the Route 101 shove: keep the line on
    -- screen and only start the walk after A, matching pokeruby.
    if #says > 0 then
      self:fadeInFromBlack()
      self.field = {
        kind = "talk", text = says[1], queue = says, qi = 1,
        thenPause = pause,
      }
      return true
    end
    if pause == "wait" and self.phase == "battle" then
      return true
    end
    self.field = { kind = pause }
    return true
  end
  if #says > 0 then
    self:fadeInFromBlack()
    self.field = { kind = "talk", text = says[1], queue = says, qi = 1 }
    self:endScriptRun()
    return true
  end
  -- A script can raise its own window without queueing a single line of
  -- dialogue, and braillemessage is the one op that does. Falling through to
  -- closeField threw that window away in the same frame it was created and
  -- reported the script as a no-op, so activateBg -> tryBgEvent -> tryTalk
  -- all returned false and A on a braille panel did nothing at all -- you
  -- could walk straight off the tile, as if the panel had no script.
  if self.field and self.field.kind == "braille" then
    self:endScriptRun()
    return true
  end
  self:closeField()
  self:endScriptRun()
  return false
end

function Game3:continueScript(ops, at)
  local said, pause = Gen3Script.run(self, ops, at)
  while not pause do
    local stack = self._scriptReturn
    if type(stack) ~= "table" or #stack < 1 then break end
    local frame = table.remove(stack)
    self._scriptLoaded = frame.loaded
    self._scriptCmp = frame.result
    local more
    more, pause = Gen3Script.run(self, frame.ops, frame.at)
    if more then said = true end
  end
  return said, pause
end

function Game3:answerScriptYesNo(yes)
  self.scriptVars = self.scriptVars or {}
  self.scriptVars[Gen3Script.VAR_RESULT] = yes and 1 or 0
  local pause = self._scriptPause
  self._scriptPause = nil
  if type(pause) ~= "table" or type(pause.ops) ~= "table" then
    self:closeField()
    self:endScriptRun()
    return false
  end
  self._scriptSays = {}
  local _, again = self:continueScript(pause.ops, pause.at)
  return self:presentScript(again)
end

function Game3:runNpcScript(ops)
  if type(ops) ~= "table" or #ops < 1 then return false end
  self._scriptSays = {}
  self._scriptPause = nil
  self._scriptReturn = nil
  self._scriptLoaded = nil
  self._scriptCmp = 0
  -- A leftover waitstate (heal, flash, unused dofieldeffect) must not
  -- pin the next talk box: resumeMoveScript fromMsg returns without
  -- advancing when scriptWaiting() is still true.
  self.scriptWait = nil
  self.waitButton = nil
  self._waitButtonDone = nil
  self:beginScriptRun()
  local _, pause = Gen3Script.run(self, ops)
  return self:presentScript(pause)
end

function Game3:pickupHidden(ev)
  if not ev or not ev.itemId or ev.itemId < 1 then return false end
  local flag = Game3.hiddenFlag(ev.hiddenId)
  self.flags = self.flags or {}
  if self.flags[flag] then return false end
  self:addItem(ev.itemId, 1)
  self.flags[flag] = true
  self.field = { kind = "talk", text = ("Found %s!"):format(self:itemName(ev.itemId)) }
  return true
end

function Game3:isClockBg(ev)
  local t = ev and ev.text
  return type(t) == "string" and t:find("clock is stopped", 1, true) ~= nil
end

-- No-script fallback for the bedroom clock BG. Own bedroom only: open the
-- real StartWallClock UI; confirm applies intro/mover flags. Rival house
-- must not migrate Mom or advance VAR_LITTLEROOT_INTRO_STATE.
function Game3:setWallClock()
  if not self:isPlayerBedroomMap(self.map) then
    self.field = { kind = "talk", text = "It's a wall clock." }
    return true
  end
  if self.flags and self.flags[Game3.FLAG_SET_WALL_CLOCK] then
    self:viewWallClock()
    return true
  end
  self._wallClockStubIntro = true
  self:startWallClock()
  return true
end

function Game3:activateBg(ev)
  if not ev then return false end
  local kind = ev.kind or 0
  if kind == Game3.BG_HIDDEN_ITEM or kind == 5 or kind == 6 then
    return self:pickupHidden(ev)
  end
  if kind > 4 then return false end
  if not Game3.bgFacingOk(kind, self.facing) then return false end
  local clockBg = self:isClockBg(ev)
  local clockSet = self.flags and self.flags[Game3.FLAG_SET_WALL_CLOCK]
  -- Gate the set-clock script on the rival bedroom so it cannot steal intro
  -- (Mom cinema / mover hide / INTRO_STATE 6). After the player clock is set,
  -- both houses may ViewWallClock via their scripts.
  if type(ev.script) == "table" and #ev.script > 0 then
    if clockBg and not clockSet and not self:isPlayerBedroomMap(self.map) then
      self.field = { kind = "talk", text = ev.text or "It's a wall clock." }
      return true
    end
    return self:runNpcScript(ev.script)
  end
  if clockBg then
    if clockSet then
      self:viewWallClock()
      return true
    end
    return self:setWallClock()
  end
  self.field = { kind = "talk", text = ev.text or "..." }
  return true
end

function Game3:tryBgEvent()
  local map = self.map
  if not map then return false end
  local dx, dy = Game3.deltaFromFacing(self.facing)
  local x, y = self.playerX + dx, self.playerY + dy
  if self:activateBg(Game3.bgAt(map, x, y)) then return true end
  if Game3.isCounter(self:behaviorAt(map, x, y)) then
    return self:activateBg(Game3.bgAt(map, x + dx, y + dy))
  end
  return false
end

function Game3:closeField()
  if self.field and self.field.kind == "mart" then
    self:hideMoneyBox()
  end
  local chase = self.field and self.field.chase
  self.field = nil
  self:unlockScriptNpcs()
  if self:startPendingLearn() then return end
  if chase then self:startBirchChase() end
end

function Game3:finishFieldItem(msg)
  if self.phase == "battle" then return end
  local f = self.field
  -- party_give is deliberately not here: giving a held item ends with
  -- "X was given the Y to hold.", so the message has to be shown.
  if f and (f.kind == "fly" or f.kind == "secret_base_move"
      or f.kind == "party_teach" or f.kind == "party_use"
      or f.kind == "party_forget" or f.kind == "party_pp"
      or f.kind == "candy_stats" or f.kind == "mail_read"
      or f.kind == "pokeblock_case" or f.kind == "tm_yesno"
      or f.kind == "fishing") then
    return
  end
  if msg == nil then return end
  -- CleanUpItemMenuMessage vs CleanUpOverworldMessage: bag USE
  -- (not giveHeld) returns to the pack after the line.
  local fromBag = Game3.isBagField(f) and not f.giveTo
  self.field = { kind = "talk", text = msg, thenBag = fromBag or nil }
end

-- item_menu.c sItemPopupMenuChoicesTable. Picking an item in the bag opens a
-- popup first; it does not use the item outright. Without it there was no way
-- to reach GIVE from the bag at all, so a held item like the EXP. SHARE could
-- only answer with DAD's advice -- the "you can't use that here" line.
-- ITEM_ACTION_NONE entries in the cart's table are padding and are dropped.
Game3.BAG_ACTION_USE = "USE"
Game3.BAG_ACTION_TOSS = "TOSS"
Game3.BAG_ACTION_GIVE = "GIVE"
Game3.BAG_ACTION_REGISTER = "REGISTER"
Game3.BAG_ACTION_CHECK_TAG = "CHECK TAG"
Game3.BAG_ACTION_CANCEL = "CANCEL"

function Game3:bagActionsFor(pocket)
  pocket = tonumber(pocket) or Game3.POCKET_ITEMS
  if pocket == Game3.POCKET_BALLS then
    return { Game3.BAG_ACTION_GIVE, Game3.BAG_ACTION_TOSS,
      Game3.BAG_ACTION_CANCEL }
  end
  if pocket == Game3.POCKET_TMHM then
    return { Game3.BAG_ACTION_USE, Game3.BAG_ACTION_GIVE,
      Game3.BAG_ACTION_CANCEL }
  end
  if pocket == Game3.POCKET_BERRIES then
    return { Game3.BAG_ACTION_CHECK_TAG, Game3.BAG_ACTION_USE,
      Game3.BAG_ACTION_TOSS, Game3.BAG_ACTION_GIVE, Game3.BAG_ACTION_CANCEL }
  end
  if pocket == Game3.POCKET_KEY then
    return { Game3.BAG_ACTION_USE, Game3.BAG_ACTION_REGISTER,
      Game3.BAG_ACTION_CANCEL }
  end
  return { Game3.BAG_ACTION_USE, Game3.BAG_ACTION_TOSS,
    Game3.BAG_ACTION_GIVE, Game3.BAG_ACTION_CANCEL }
end

function Game3:openBagActions(slot, pocket)
  if not slot then return false end
  self.field = {
    kind = "bag_actions",
    cursor = 0,
    item = slot.id,
    count = slot.count or 1,
    pocket = pocket,
    actions = self:bagActionsFor(pocket),
  }
  return true
end

-- HandlePopupMenuAction_Give: the party opens so you can pick who holds it.
function Game3:openPartyGive(item)
  self.field = {
    kind = "party_give",
    cursor = 0,
    item = item,
    from = "bag",
    prompt = "Give to which POKeMON?",
  }
  return true
end

function Game3:chooseGiveMon(monIndex)
  local item = self.field and self.field.item
  local ok, msg = self:giveHeldItem(monIndex, item)
  self:finishFieldItem(msg)
  return ok
end

-- HandlePopupMenuAction_Toss, minus the quantity picker: one confirm, then the
-- slot goes. Key items are not tossable, which is why the KEY pocket's table
-- has no TOSS entry at all.
function Game3:tossBagItem(id, n)
  id = tonumber(id) or 0
  n = tonumber(n) or 1
  if self:itemPocket(id) == Game3.POCKET_KEY then
    return false, "That's much too important to toss out!"
  end
  if not self:takeItem(id, n) then
    return false, "You have none left!"
  end
  return true, ("Threw away %s."):format(self:itemName(id))
end

function Game3:stepBagActions(f)
  local actions = f.actions or { Game3.BAG_ACTION_CANCEL }
  local n = #actions
  if n < 1 then n = 1 end
  if Input:wasPressed("b") then
    self:openBag()
    return
  end
  if Input:wasPressed("down") then
    f.cursor = ((f.cursor or 0) + 1) % n
    return
  end
  if Input:wasPressed("up") then
    f.cursor = ((f.cursor or 0) - 1) % n
    if f.cursor < 0 then f.cursor = n - 1 end
    return
  end
  if not Input:wasPressed("a") then return end
  local pick = actions[(f.cursor or 0) + 1]
  local id = f.item
  if pick == Game3.BAG_ACTION_USE then
    local _, msg = self:useFieldItem(id)
    self:finishFieldItem(msg)
  elseif pick == Game3.BAG_ACTION_GIVE then
    if #(self.party or {}) < 1 then
      self.field = { kind = "talk", text = "There is no\r\nPOKeMON." }
      return
    end
    self:openPartyGive(id)
  elseif pick == Game3.BAG_ACTION_TOSS then
    local _, msg = self:tossBagItem(id, 1)
    self:finishFieldItem(msg)
  elseif pick == Game3.BAG_ACTION_REGISTER then
    local _, msg = self:toggleRegisteredItem(id)
    self:openBag()
    if self.field then self.field.note = msg end
  elseif pick == Game3.BAG_ACTION_CHECK_TAG then
    self.field = { kind = "talk",
      text = ("%s\r\n%s"):format(self:itemName(id), self:itemDescription(id)) }
  else
    self:openBag()
  end
end

function Game3:drawBagActions(f)
  self:drawBag({ kind = "bag", pocket = f.pocket, cursor = 0, quiet = true })
  local actions = (f and f.actions) or { Game3.BAG_ACTION_CANCEL }
  local n = #actions
  local boxW = 92
  local boxH = n * 14 + 12
  local boxX = Game3.SCREEN_W - boxW - 4
  local boxY = Game3.SCREEN_H - boxH - 4
  self:drawWindow(boxX, boxY, boxW, boxH)
  for i = 0, n - 1 do
    local y = boxY + 6 + i * 14
    if i == (f and f.cursor or 0) then self:drawCursor(boxX + 4, y) end
    love.graphics.setColor(0.10, 0.10, 0.12, 1)
    self:drawText(actions[i + 1], boxX + 14, y)
  end
  love.graphics.setColor(1, 1, 1, 1)
end

function Game3:stepBag(f)
  local pick = f.pickBerry
  local pocket = f.pocket or self.lastBagPocket or Game3.POCKET_ITEMS
  if pick then
    pocket = Game3.POCKET_BERRIES
  elseif pocket < Game3.POCKET_ITEMS then pocket = Game3.POCKET_ITEMS
  elseif pocket > Game3.POCKET_KEY then pocket = Game3.POCKET_KEY end
  f.pocket = pocket
  if not pick then self.lastBagPocket = pocket end
  local list = self:bagSlotsIn(pocket)
  local n = #list + 1
  local function closeBag()
    if pick then
      self:finishBerryPick(0)
      return
    end
    if f.giveTo then
      local index = f.giveTo
      self.field = {
        kind = "party_item",
        cursor = 0,
        monIndex = index,
        actions = self:partyItemActions((self.party or {})[index]),
      }
    else
      self:backToStart("BAG")
    end
  end
  if Input:wasPressed("b") then
    closeBag()
  elseif Input:wasPressed("right") then
    if pick then return end
    f.pocket = Game3.wrapPocket(pocket, 1)
    f.cursor = 0
    self.lastBagPocket = f.pocket
  elseif Input:wasPressed("left") then
    if pick then return end
    f.pocket = Game3.wrapPocket(pocket, -1)
    f.cursor = 0
    self.lastBagPocket = f.pocket
  elseif Input:wasPressed("down") then
    f.cursor = ((f.cursor or 0) + 1) % n
  elseif Input:wasPressed("up") then
    f.cursor = ((f.cursor or 0) - 1) % n
    if f.cursor < 0 then f.cursor = n - 1 end
  elseif Input:wasPressed("a") then
    local slot = list[(f.cursor or 0) + 1]
    if not slot then
      closeBag()
    elseif pick then
      self:finishBerryPick(slot.id)
    elseif f.giveTo then
      local _, msg = self:giveHeldItem(f.giveTo, slot.id)
      self:finishFieldItem(msg)
    else
      -- item_menu.c opens the popup here; USE is one entry in it, not the
      -- whole interaction.
      self:openBagActions(slot, pocket)
    end
  elseif Input:wasPressed("select") then
    if pick then return end
    local slot = list[(f.cursor or 0) + 1]
    if slot then
      local _, msg = self:toggleRegisteredItem(slot.id)
      f.note = msg
    end
  end
end

-- HandleDefaultPartyMenuInput: filled slots, then CANCEL at sprite 7
-- (cursor 6). A on CANCEL is B.
function Game3:partyItemUseKind(kind)
  return kind == "party_teach" or kind == "party_use"
      or kind == "party_give"
end

function Game3:stepPartyCursor(f, delta)
  local n = #(self.party or {})
  if n < 1 then n = 1 end
  local c = f.cursor or 0
  local cancel = self:partyItemUseKind(f.kind)
  if delta > 0 then
    if c < n - 1 then
      f.cursor = c + 1
    elseif cancel and c ~= 6 then
      f.cursor = 6
    else
      f.cursor = 0
    end
  else
    if c == 0 then
      f.cursor = cancel and 6 or (n - 1)
    elseif c == 6 then
      f.cursor = n - 1
    else
      f.cursor = c - 1
    end
  end
end

function Game3:stepParty(f)
  if Input:wasPressed("b") then
    if self:partyItemUseKind(f.kind) then
      self:leavePartyItemUse()
      return
    end
    self:backToStart("POKeMON")
    return
  end
  local n = #(self.party or {})
  if n < 1 then n = 1 end
  if Input:wasPressed("down") then
    if self:partyItemUseKind(f.kind) then
      self:stepPartyCursor(f, 1)
    else
      f.cursor = ((f.cursor or 0) + 1) % n
    end
  elseif Input:wasPressed("up") then
    if self:partyItemUseKind(f.kind) then
      self:stepPartyCursor(f, -1)
    else
      f.cursor = ((f.cursor or 0) - 1) % n
      if f.cursor < 0 then f.cursor = n - 1 end
    end
  elseif Input:wasPressed("a") then
    -- sprite data[0] == 7: A on CANCEL returns B_BUTTON.
    if self:partyItemUseKind(f.kind) and (f.cursor or 0) == 6 then
      self:leavePartyItemUse()
      return
    end
    if f.kind == "party_teach" then
      self:chooseTeachMon((f.cursor or 0) + 1)
    elseif f.kind == "party_give" then
      self:chooseGiveMon((f.cursor or 0) + 1)
    elseif f.kind == "party_use" then
      self:chooseUseMon((f.cursor or 0) + 1)
    else
      self:openPartyAction((f.cursor or 0) + 1)
    end
  end
end

function Game3:stepPartyAction(f)
  local actions = f.actions or { "CANCEL" }
  local n = #actions
  if n < 1 then n = 1 end
  if Input:wasPressed("b") then
    if f.kind == "party_item" then
      self:openPartyAction(f.monIndex or 1)
    else
      self.field = { kind = "party", cursor = (f.monIndex or 1) - 1 }
    end
    return
  end
  if Input:wasPressed("down") then
    f.cursor = ((f.cursor or 0) + 1) % n
  elseif Input:wasPressed("up") then
    f.cursor = ((f.cursor or 0) - 1) % n
    if f.cursor < 0 then f.cursor = n - 1 end
  elseif Input:wasPressed("a") then
    local name = actions[(f.cursor or 0) + 1]
    local index = f.monIndex or 1
    if name == "SUMMARY" then
      self:openPartySummary(index)
    elseif name == "SWITCH" then
      self.field = {
        kind = "party_switch",
        cursor = index - 1,
        monIndex = index,
      }
    elseif name == "ITEM" then
      local mon = (self.party or {})[index]
      self.field = {
        kind = "party_item",
        cursor = 0,
        monIndex = index,
        actions = self:partyItemActions(mon),
      }
    elseif name == "GIVE" then
      self:openBagForGive(index)
    elseif name == "TAKE" then
      local _, msg = self:takeHeldItem(index)
      self:finishFieldItem(msg)
    elseif name == "CANCEL" or not name then
      if f.kind == "party_item" then
        self:openPartyAction(index)
      else
        self.field = { kind = "party", cursor = index - 1 }
      end
    else
      local mon = (self.party or {})[index]
      local _, msg = self:usePartyFieldMoveNamed(mon, name)
      self:finishFieldItem(msg)
    end
  end
end

function Game3:stepPartySwitch(f)
  local n = #(self.party or {})
  if n < 1 then n = 1 end
  if Input:wasPressed("b") then
    self:openPartyAction(f.monIndex or 1)
    return
  end
  if Input:wasPressed("down") then
    f.cursor = ((f.cursor or 0) + 1) % n
  elseif Input:wasPressed("up") then
    f.cursor = ((f.cursor or 0) - 1) % n
    if f.cursor < 0 then f.cursor = n - 1 end
  elseif Input:wasPressed("a") then
    local from = f.monIndex or 1
    local to = (f.cursor or 0) + 1
    self:swapParty(from, to)
    self.field = { kind = "party", cursor = (f.cursor or 0) }
  end
end

function Game3:stepPartyForget(f)
  local mon = (self.party or {})[f.monIndex or 1]
  local moves = mon and mon.moves or {}
  local n = #moves + 1
  if n < 1 then n = 1 end
  if Input:wasPressed("b") then
    self.field = { kind = "party_teach", cursor = (f.monIndex or 1) - 1, item = f.item }
    return
  end
  if Input:wasPressed("down") then
    f.cursor = ((f.cursor or 0) + 1) % n
  elseif Input:wasPressed("up") then
    f.cursor = ((f.cursor or 0) - 1) % n
    if f.cursor < 0 then f.cursor = n - 1 end
  elseif Input:wasPressed("a") then
    local slot = (f.cursor or 0) + 1
    if slot > #moves then
      self.field = { kind = "party_teach", cursor = (f.monIndex or 1) - 1, item = f.item }
      return
    end
    if Game3.isHmMove(moves[slot] and moves[slot].id) then
      self.field = { kind = "talk", text = "HM moves can't be forgotten now." }
      return
    end
    local _, msg = self:teachTMHM(f.monIndex or 1, f.item, slot)
    self.field = { kind = "talk", text = msg }
  end
end

function Game3:stepPartyPp(f)
  local mon = (self.party or {})[f.monIndex or 1]
  local moves = mon and mon.moves or {}
  local n = #moves + 1
  if n < 1 then n = 1 end
  if Input:wasPressed("b") then
    self.field = {
      kind = "party_use",
      cursor = (f.monIndex or 1) - 1,
      item = f.item,
      from = f.from,
      prompt = "Use on which POKeMON?",
    }
    return
  end
  if Input:wasPressed("down") then
    f.cursor = ((f.cursor or 0) + 1) % n
  elseif Input:wasPressed("up") then
    f.cursor = ((f.cursor or 0) - 1) % n
    if f.cursor < 0 then f.cursor = n - 1 end
  elseif Input:wasPressed("a") then
    local slot = (f.cursor or 0) + 1
    if slot > #moves then
      self.field = {
        kind = "party_use",
        cursor = (f.monIndex or 1) - 1,
        item = f.item,
        from = f.from,
        prompt = "Use on which POKeMON?",
      }
      return
    end
    self:presentItemUseResult(mon, f.item, f.from, f.monIndex, slot)
  end
end

function Game3:stepPartySummary(f)
  if Input:wasPressed("b") or Input:wasPressed("a") then
    if f.fromPc then
      self.field = f.fromPc
      if self.field.kind == "pc" then self:pcRefreshMsg() end
      return
    end
    self:openPartyAction(f.monIndex or 1)
  elseif Input:wasPressed("right") then
    f.page = ((f.page or 0) + 1) % Game3.PARTY_SUMMARY_PAGES
  elseif Input:wasPressed("left") then
    f.page = ((f.page or 0) - 1) % Game3.PARTY_SUMMARY_PAGES
    if f.page < 0 then f.page = Game3.PARTY_SUMMARY_PAGES - 1 end
  end
end

function Game3:stepField()
  local f = self.field
  if not f then return end
  if f.kind == "roulette" then
    self:stepRoulette()
  end
  if f.kind == "move" or f.kind == "delay" or f.kind == "wait"
      or f.kind == "trainer_approach" or f.kind == "evolve"
      or f.kind == "fishing" or f.kind == "cable_car"
      or f.kind == "egg_hatch" or f.kind == "porthole" then
    return
  end
  if f.kind == "trade_scene" then
    self:stepTradeScene()
    return
  end
  if f.kind == "talk" then
    if Input:wasPressed("a") or Input:wasPressed("b") then
      if self:advanceDialogue(f) then
        return
      end
      local queue, qi = f.queue, f.qi or 1
      if type(queue) == "table" and qi < #queue then
        f.qi = qi + 1
        f.text = queue[f.qi]
        f.textPage = 0
        f.printSrc = nil
      elseif f.afterSecretBasePc then
        -- SecretBase_EventScript_PC: waitbuttonpress, playse SE_SELECT,
        -- then goto SecretBase_EventScript_PCShowMainMenu.
        self:playSe(Game3.SE_SELECT)
        self:openSecretBasePCMenu()
      elseif f.afterRegionMap then
        -- EventScript_RegionMap: msgbox, then fadescreen and
        -- FieldShowRegionMap behind a waitstate.
        self:fieldShowRegionMap()
      elseif f.afterSecretBasePcOff then
        self:closeField()
        self:doSecretBasePCTurnOffEffect()
      elseif f.afterDecor then
        -- decoration.c DisplayItemMessageOnField(..., sub_80FE428, 0):
        -- every one of the PC's refusals drops back to its menu.
        self:secretBasePCDecorationReopen()
      elseif f.thenSecretBaseEnter then
        local pending = self._secretPowerEnter
        self._secretPowerEnter = nil
        self:closeField()
        self:enterNewSecretBase(pending)
      elseif f.thenSafariExit then
        self:leaveSafari()
      elseif f.thenWhiteout then
        self:blackout()
      elseif f.thenTmAsk then
        self:openTmYesNo()
      elseif f.thenEggHatch then
        self:eggHatch()
      elseif f.thenEggNick then
        self:openEggNickAsk()
      elseif f.thenCandy then
        self.field = {
          kind = "candy_stats",
          growth = f.thenCandy,
          page = 0,
          thenBag = f.thenBag,
          thenPending = f.thenPending,
        }
      elseif f.thenPending then
        if f.thenBag then self.itemUseThenBag = true end
        if self:startPendingLearn() then return end
        if self:startPendingEvolve() then return end
        if f.thenBag then
          self.itemUseThenBag = nil
          self:openBag()
        else
          self:closeField()
        end
      elseif f.thenBag then
        self:openBag()
      elseif f.thenYesNo then
        self:openScriptYesNo(f.thenYesNo)
      elseif f.thenLearnAsk then
        self:openLearnYesNo()
      elseif f.thenLearn then
        self:finishLearnMessage()
      elseif f.thenContinue then
        self:resumeMoveScript()
      elseif f.thenPause then
        local pause = f.thenPause
        self.field = { kind = pause }
        if pause == "move" and not self:scriptMoving() then
          self:resumeMoveScript()
        elseif pause == "delay" and not self:scriptDelaying() then
          self:resumeMoveScript()
        elseif pause == "wait" and not self:scriptWaiting() then
          self:resumeMoveScript()
        end
      else
        self:closeField()
      end
    end
    return
  end
  if f.kind == "option" then
    self:stepOptionMenu(f, function()
      self:backToStart("OPTION")
    end)
    return
  end
  if f.kind == "trainer_card" then
    -- pokeruby TrainerCard_WaitForKeys: B closes; A flips front->back,
    -- or closes when already on the back (no flip back to front).
    if Input:wasPressed("b") then
      self:backToStart(self:playerName())
    elseif Input:wasPressed("a") then
      if f.face == "back" then
        self:backToStart(self:playerName())
      else
        f.face = "back"
      end
    end
    return
  end
  if f.kind == "pokenav" then
    self:stepRegionMap(f)
    return
  end
  if f.kind == "pokenav_menu" then
    self:stepPokenavMenu(f)
    return
  end
  if f.kind == "trainers_eye" then
    self:stepTrainersEye(f)
    return
  end
  if f.kind == "pokenav_condition" then
    self:stepPokenavCondition(f)
    return
  end
  if f.kind == "pokenav_ribbons" then
    self:stepPokenavRibbons(f)
    return
  end
  if f.kind == "save_ask" then
    if Input:wasPressed("up") or Input:wasPressed("down") then
      f.cursor = 1 - (f.cursor or 0)
    elseif Input:wasPressed("a") then
      if (f.cursor or 0) == 0 then
        self:confirmSave()
      else
        self:backToStart("SAVE")
      end
    elseif Input:wasPressed("b") then
      self:backToStart("SAVE")
    end
    return
  end
  if f.kind == "bag" then
    self:stepBag(f)
    return
  end
  if f.kind == "bag_actions" then
    self:stepBagActions(f)
    return
  end
  if f.kind == "dex_start" then
    self:stepDexStartMenu(f)
    return
  end
  if f.kind == "dex_search" then
    self:stepDexSearch(f)
    return
  end
  if f.kind == "party" or f.kind == "party_teach" or f.kind == "party_use"
      or f.kind == "party_give" then
    self:stepParty(f)
    return
  end
  if f.kind == "party_action" or f.kind == "party_item" then
    self:stepPartyAction(f)
    return
  end
  if f.kind == "party_switch" then
    self:stepPartySwitch(f)
    return
  end
  if f.kind == "party_forget" then
    self:stepPartyForget(f)
    return
  end
  if f.kind == "party_pp" then
    self:stepPartyPp(f)
    return
  end
  if f.kind == "party_summary" then
    self:stepPartySummary(f)
    return
  end
  if f.kind == "pc" then
    self:stepPc()
    return
  end
  if f.kind == "gender" then
    if Input:wasPressed("down") or Input:wasPressed("up") then
      f.cursor = 1 - (f.cursor or 0)
    elseif Input:wasPressed("a") then
      self:chooseGender((f.cursor or 0) == 1
        and Game3.GENDER_FEMALE or Game3.GENDER_MALE)
    end
    return
  end
  if f.kind == "nickname" then
    local Naming = require("src.ui.gen3.NamingScreen")
    Naming.step(self, f, Input)
    return
  end
  if f.kind == "starter" then
    local n = #Game3.STARTERS
    if Input:wasPressed("down") then
      f.cursor = ((f.cursor or 0) + 1) % n
    elseif Input:wasPressed("up") then
      f.cursor = ((f.cursor or 0) - 1) % n
      if f.cursor < 0 then f.cursor = n - 1 end
    elseif Input:wasPressed("right") then
      f.cursor = math.min(n - 1, (f.cursor or 0) + 1)
    elseif Input:wasPressed("left") then
      f.cursor = math.max(0, (f.cursor or 0) - 1)
    elseif Input:wasPressed("a") then
      local species = Game3.STARTERS[(f.cursor or 0) + 1]
      f.kind = "starter_yesno"
      f.species = species
      f.pick = f.cursor
      f.cursor = 0
      f.text = Game3.TEXT_DO_YOU_CHOOSE_POKE
      f.revealStart = self.playSeconds or 0
    end
    return
  end
  if f.kind == "starter_yesno" then
    -- f.revealStart drives the ball-open circle / front-sprite draw
    -- animation only; Yes/No stays responsive (a player mashing A should
    -- not feel blocked by a cosmetic reveal).
    if Input:wasPressed("down") or Input:wasPressed("up") then
      f.cursor = 1 - (f.cursor or 0)
    elseif Input:wasPressed("a") then
      if (f.cursor or 0) ~= 0 then
        f.kind = "starter"
        f.cursor = f.pick or 0
        f.text = nil
        return
      end
      if f.scripted then
        self:setScriptVar(Gen3Script.VAR_RESULT, Game3.starterIndex(f.species) or 0)
        self:giveMon(f.species, Game3.STARTER_LEVEL)
        self.field = nil
        self:startBirchChase()
        return
      end
      local ok, msg = self:giveStarter(f.species, f.npc)
      local chase = self.pendingChase
      self.pendingChase = nil
      self.field = { kind = "talk", text = msg or "Got it!", chase = chase }
    elseif Input:wasPressed("b") then
      f.kind = "starter"
      f.cursor = f.pick or 0
      f.text = nil
    end
    return
  end
  if f.kind == "clock_set" then
    if Input:wasPressed("left") then
      self:advanceClock(-1)
    elseif Input:wasPressed("right") then
      self:advanceClock(1)
    elseif Input:wasPressed("up") then
      for _ = 1, 60 do self:advanceClock(1) end
    elseif Input:wasPressed("down") then
      for _ = 1, 60 do self:advanceClock(-1) end
    elseif Input:wasPressed("a") then
      f.kind = "clock_yesno"
      -- Task_SetClock3 InitMenu(..., initialCursorPos 1) starts on NO.
      f.cursor = 1
    end
    return
  end
  if f.kind == "clock_yesno" then
    if Input:wasPressed("up") or Input:wasPressed("down") then
      f.cursor = 1 - (f.cursor or 0)
    elseif Input:wasPressed("a") then
      if (f.cursor or 0) == 0 then
        self:confirmWallClock()
      else
        f.kind = "clock_set"
      end
    elseif Input:wasPressed("b") then
      f.kind = "clock_set"
    end
    return
  end
  if f.kind == "clock_view" then
    if Input:wasPressed("a") or Input:wasPressed("b") then
      self:closeWallClock()
    end
    return
  end
  if f.kind == "diploma" then
    if Input:wasPressed("a") or Input:wasPressed("b") then
      self:closeDiploma()
    end
    return
  end
  if f.kind == "hof" then
    if Input:wasPressed("a") or Input:wasPressed("b") then
      self:hofCinemaPressed()
    end
    return
  end
  if f.kind == "credits" then
    if Input:wasPressed("a") or Input:wasPressed("b") then
      self:creditsPressed()
    end
    return
  end
  if f.kind == "braille" then
    -- the script's own waitbuttonpress releases too; this covers a braille
    -- box shown outside a script
    if Input:wasPressed("a") or Input:wasPressed("b") then
      self:closeField()
    end
    return
  end
  if f.kind == "link_records" or f.kind == "tower_records" then
    if Input:wasPressed("a") or Input:wasPressed("b") then
      self:closeField()
    end
    return
  end
  if f.kind == "tower_party" then
    local n = #(self.party or {})
    if n < 1 then n = 1 end
    if Input:wasPressed("b") then
      self:cancelTowerParty()
    elseif Input:wasPressed("start") then
      self:confirmTowerParty()
    elseif Input:wasPressed("down") then
      f.cursor = ((f.cursor or 0) + 1) % n
    elseif Input:wasPressed("up") then
      f.cursor = ((f.cursor or 0) - 1) % n
      if f.cursor < 0 then f.cursor = n - 1 end
    elseif Input:wasPressed("a") then
      self:toggleTowerPartySlot((f.cursor or 0) + 1)
    end
    return
  end
  if f.kind == "hof_pc" then
    if Input:wasPressed("b") then
      self:closeHofPc()
    elseif Input:wasPressed("a") then
      self:hofPcAdvance()
    elseif Input:wasPressed("up") or Input:wasPressed("down") then
      local teams = self.hallOfFameTeams or {}
      local team = teams[tonumber(f.teamIndex) or 0] or {}
      local n = #team
      if n > 0 then
        local sel = tonumber(f.pokeIndex) or 1
        if Input:wasPressed("up") then
          sel = sel - 1
          if sel < 1 then sel = n end
        else
          sel = sel + 1
          if sel > n then sel = 1 end
        end
        f.pokeIndex = sel
        local mon = team[sel]
        if mon and mon.species and (tonumber(mon.species) or 0) ~= 0
            and mon.species ~= Game3.SPECIES_EGG then
          self:playMonCry(mon.species)
        end
      end
    end
    return
  end
  if f.kind == "slots" then
    if f.windows then
      if Input:wasPressed("a") then
        f.windows = nil
        f.payout = nil
      elseif Input:wasPressed("b") then
        self:closeSlots()
      end
      return
    end
    if Input:wasPressed("left") then
      f.bet = math.max(1, (f.bet or 1) - 1)
    elseif Input:wasPressed("right") then
      f.bet = math.min(3, (f.bet or 1) + 1)
    elseif Input:wasPressed("a") then
      if f.replay or self:getCoins() >= (f.bet or 1) then
        self:spinSlots()
      end
    elseif Input:wasPressed("b") then
      self:closeSlots()
    end
    return
  end
  if f.kind == "roulette" then
    if f.spinning then
      return
    end
    if Input:wasPressed("up") then
      self:moveRouletteCursor(0)
    elseif Input:wasPressed("down") then
      self:moveRouletteCursor(1)
    elseif Input:wasPressed("left") then
      self:moveRouletteCursor(2)
    elseif Input:wasPressed("right") then
      self:moveRouletteCursor(3)
    elseif Input:wasPressed("a") then
      self:spinRoulette()
    elseif Input:wasPressed("b") then
      self:closeRoulette()
    end
    return
