      end
    elseif mode == "buy" or mode == "sell" then
      local list = mode == "sell" and (f.sellSlots or self:martSellSlots())
        or (f.items or {})
      local n = #list
      if n < 1 then n = 1 end
      if Input:wasPressed("down") then
        f.cursor = ((f.cursor or 0) + 1) % n
      elseif Input:wasPressed("up") then
        f.cursor = ((f.cursor or 0) - 1) % n
        if f.cursor < 0 then f.cursor = n - 1 end
      elseif Input:wasPressed("a") then
        if mode == "sell" then
          local slot = list[(f.cursor or 0) + 1]
          if not slot then
            f.note = "You have nothing to sell."
          else
            f.mode = "qty"
            f.qtyFrom = "sell"
            f.qtyItem = slot.id
            f.qtyMax = math.min(Game3.MART_QTY_MAX, slot.count or 1)
            f.qty = 1
            f.listCursor = f.cursor
          end
        else
          local id = list[(f.cursor or 0) + 1]
          if not id then return end
          if f.martKind == "decor" then
            local _, msg = self:buyMartItem(id, f.martKind, 1)
            f.note = msg
            self:updateMoneyBox()
          else
            local unit = self:itemPrice(id)
            local maxQty = Game3.MART_QTY_MAX
            if unit > 0 then
              maxQty = math.floor((self.money or 0) / unit)
              if maxQty > Game3.MART_QTY_MAX then maxQty = Game3.MART_QTY_MAX end
            end
            if maxQty < 1 then
              f.note = "You don't have enough money."
            else
              f.mode = "qty"
              f.qtyFrom = "buy"
              f.qtyItem = id
              f.qtyMax = maxQty
              f.qty = 1
              f.listCursor = f.cursor
            end
          end
        end
      end
    elseif mode == "qty" then
      local maxQty = f.qtyMax or 1
      if maxQty < 1 then maxQty = 1 end
      local function bump(d)
        f.qty = (f.qty or 1) + d
        if f.qty < 1 then f.qty = maxQty
        elseif f.qty > maxQty then f.qty = 1 end
      end
      if Input:wasPressed("right") or Input:wasPressed("up") then
        bump(1)
      elseif Input:wasPressed("left") or Input:wasPressed("down") then
        bump(-1)
      elseif Input:wasPressed("a") then
        local qty = f.qty or 1
        local id = f.qtyItem
        local ok, msg
        if f.qtyFrom == "sell" then
          ok, msg = self:sellMartItem(id, qty)
          f.sellSlots = self:martSellSlots()
        else
          ok, msg = self:buyMartItem(id, f.martKind, qty)
        end
        f.note = msg
        f.mode = f.qtyFrom or "buy"
        f.cursor = f.listCursor or 0
        f.qty, f.qtyItem, f.qtyFrom = nil, nil, nil
        self:updateMoneyBox()
      end
    end
    return
  end
  if f.kind == "dex" then
    self:stepDexList(f)
    return
  end
  if f.kind == "dex_entry" then
    self:stepDexEntry(f)
    return
  end
  if f.kind ~= "menu" then
    return
  end
  if Input:wasPressed("start") or Input:wasPressed("b") then
    self:closeField()
    return
  end
  local labels = self:startMenuItems()
  local n = #labels
  if n < 1 then n = 1 end
  if Input:wasPressed("up") then
    f.cursor = ((f.cursor or 0) - 1) % n
    if f.cursor < 0 then f.cursor = n - 1 end
  elseif Input:wasPressed("down") then
    f.cursor = ((f.cursor or 0) + 1) % n
  elseif Input:wasPressed("a") then
    local name = labels[(f.cursor or 0) + 1]
    if name == "POKeDEX" then
      self:openDex()
    elseif name == "POKeMON" then
      self:openParty()
    elseif name == "BAG" then
      self:openBag()
    elseif name == "POKeNAV" then
      self:openPokeNav()
    elseif name == "SAVE" then
      self:openSaveAsk()
    elseif name == "RETIRE" then
      self:openSafariRetirePrompt()
    elseif name == "OPTION" then
      self.field = { kind = "option", cursor = 0 }
    elseif name == self:playerName() then
      self:openTrainerCard()
    else
      self:closeField()
    end
  end
end

function Game3:drawStartMenu(f)
  if self:inSafariMode() then
    -- start_menu.c DisplaySafariBallsWindow: (0, 0, 10, 5), text at 1, 1.
    self:drawStdWindow(0, 0, Game3.SAFARI_STOCK_RIGHT, Game3.SAFARI_STOCK_BOTTOM)
    love.graphics.setColor(0.10, 0.10, 0.12, 1)
    self:drawText("SAFARI BALLS", Game3.MENU_TILE, Game3.MENU_TILE)
    self:drawText(("Stock: %d"):format(self.safariBalls or 0),
      Game3.MENU_TILE, Game3.MENU_TILE * 3)
  end
  local labels = self:startMenuItems()
  local n = #labels
  -- Menu_DrawStdWindowFrame(22, 0, 29, n * 2 + 3)
  local bottom = n * 2 + 3
  self:drawStdWindow(Game3.START_LEFT, Game3.START_TOP, Game3.START_RIGHT, bottom)
  local tx = Game3.START_TEXT_COL * Game3.MENU_TILE
  for i = 0, n - 1 do
    local y = (Game3.START_TEXT_ROW + i * 2) * Game3.MENU_TILE
    if i == (f.cursor or 0) then
      self:drawCursor(tx - Game3.MENU_TILE, y)
    end
    love.graphics.setColor(0.10, 0.10, 0.12, 1)
    self:drawText(labels[i + 1], tx, y)
  end
end

-- pokeruby trainer_card.c front/back. Assets from tools/bake_trainer_card.py
-- (graphics/trainer_card/*). Tile positions: name (7,5), ID (20,2), money
-- right@16,8, dex right@16,10, time (10,12), trainer pic tiles (19,5) 64x64,
-- stars row 6 cols 15+, badges rows 15-16 cols 4+3*i.
Game3.TRAINER_CARD_DIR = "assets/generated/trainer_card/"

function Game3:trainerCardImage(name)
  return self:grabImage((Game3.TRAINER_CARD_DIR or "assets/generated/trainer_card/") .. name)
end

function Game3:drawTrainerCardTextRight(text, rightTile, topTile)
  local s = tostring(text or "")
  local tw = Game3.textWidth(s, self:font3WidthTable())
  local x = rightTile * Game3.MENU_TILE - tw
  local y = topTile * Game3.MENU_TILE
  self:drawText(s, x, y)
end

function Game3:drawTrainerCardFront()
  local G = love.graphics
  local stars = self:cardStars()
  if stars < 0 then stars = 0 end
  if stars > 4 then stars = 4 end
  local bg = self:trainerCardImage(("ruby_front_%d.png"):format(stars))
  G.setColor(1, 1, 1, 1)
  if bg then
    G.draw(bg, 0, 0)
  else
    G.setColor(0.55, 0.38, 0.45, 1)
    G.rectangle("fill", 0, 0, Game3.SCREEN_W, Game3.SCREEN_H)
  end

  local picName = self:isFemale() and "ruby_may.png" or "ruby_brendan.png"
  local pic = self:trainerCardImage(picName)
  if pic then
    G.setColor(1, 1, 1, 1)
    G.draw(pic, 19 * Game3.MENU_TILE, 5 * Game3.MENU_TILE)
  end

  local starImg = self:trainerCardImage("ruby_star.png")
  if starImg and stars > 0 then
    G.setColor(1, 1, 1, 1)
    for i = 0, stars - 1 do
      G.draw(starImg, (15 + i) * Game3.MENU_TILE, 6 * Game3.MENU_TILE)
    end
  end

  -- TrainerCard_ClearPokedexLabel: blank tile rows 10-11, cols 3..16 when
  -- FLAG_SYS_POKEDEX_GET is clear (label is baked into the front map).
  if not self:hasPokedex() then
    G.setColor(0.90, 1.0, 0.87, 1)
    G.rectangle("fill", 3 * Game3.MENU_TILE, 10 * Game3.MENU_TILE,
      14 * Game3.MENU_TILE, 2 * Game3.MENU_TILE)
  end

  G.setColor(0.10, 0.10, 0.12, 1)
  self:drawText(self:playerName(), 7 * Game3.MENU_TILE, 5 * Game3.MENU_TILE)
  self:drawText(self:trainerIdString(), 20 * Game3.MENU_TILE, 2 * Game3.MENU_TILE)
  self:drawTrainerCardTextRight(self:moneyString(), 16, 8)
  if self:hasPokedex() then
    local seen = self:dexCounts()
    self:drawTrainerCardTextRight(tostring(seen), 16, 10)
  end
  -- Play time at tiles (10,12); blink colon like ROM showColon.
  local sec = math.floor(tonumber(self.playSeconds) or 0)
  local m = math.floor(sec / 60)
  local h = math.floor(m / 60)
  m = m % 60
  if h > 999 then h = 999; m = 59 end
  local colon = (math.floor(sec) % 2 == 0) and ":" or " "
  self:drawText(("%d%s%02d"):format(h, colon, m), 10 * Game3.MENU_TILE, 12 * Game3.MENU_TILE)

  local badges = self:trainerCardImage("ruby_badges.png")
  if badges then
    G.setColor(1, 1, 1, 1)
    -- Cache quads once on the image userdata via a weak side table.
    local cache = self._trainerBadgeQuads
    if not cache or cache.img ~= badges then
      cache = { img = badges, quads = {} }
      for i = 1, 8 do
        cache.quads[i] = love.graphics.newQuad((i - 1) * 16, 0, 16, 16, badges:getDimensions())
      end
      self._trainerBadgeQuads = cache
    end
    for i = 1, 8 do
      if self:hasBadge(i) then
        local col = 4 + (i - 1) * 3
        G.draw(badges, cache.quads[i], col * Game3.MENU_TILE, 15 * Game3.MENU_TILE)
      end
    end
  end
end

function Game3:drawTrainerCardBack()
  local G = love.graphics
  local stars = self:cardStars()
  if stars < 0 then stars = 0 end
  if stars > 4 then stars = 4 end
  local bg = self:trainerCardImage(("ruby_back_%d.png"):format(stars))
  G.setColor(1, 1, 1, 1)
  if bg then
    G.draw(bg, 0, 0)
  else
    G.setColor(0.55, 0.38, 0.45, 1)
    G.rectangle("fill", 0, 0, Game3.SCREEN_W, Game3.SCREEN_H)
  end

  G.setColor(0.10, 0.10, 0.12, 1)
  local title = self:playerName() .. "'s TRAINER CARD"
  self:drawTrainerCardTextRight(title, 28, 2)

  local hof = self:getGameStat(Game3.GAME_STAT_FIRST_HOF_PLAY_TIME) or 0
  if hof ~= 0 then
    self:drawText("FIRST HALL OF FAME", 3 * Game3.MENU_TILE, 5 * Game3.MENU_TILE)
    local ha = math.floor(hof / 65536)
    local hb = math.floor((hof % 65536) / 256)
    local hc = hof % 256
    self:drawTrainerCardTextRight(("%d : %02d : %02d"):format(ha, hb, hc), 28, 5)
  end

  local lw = self:getGameStat(Game3.GAME_STAT_LINK_BATTLE_WINS) or 0
  local ll = self:getGameStat(Game3.GAME_STAT_LINK_BATTLE_LOSSES) or 0
  if lw ~= 0 or ll ~= 0 then
    self:drawText("LINK CABLE BATTLES", 3 * Game3.MENU_TILE, 7 * Game3.MENU_TILE)
    self:drawTrainerCardTextRight(tostring(lw), 22, 7)
    self:drawTrainerCardTextRight(tostring(ll), 28, 7)
  end

  local trades = self:getGameStat(21) or 0 -- GAME_STAT_POKEMON_TRADES
  if trades ~= 0 then
    self:drawText("POKeMON TRADES", 3 * Game3.MENU_TILE, 9 * Game3.MENU_TILE)
    self:drawTrainerCardTextRight(tostring(trades), 28, 9)
  end

  local pokeblocks = self:getGameStat(34) or 0 -- GAME_STAT_POKEBLOCKS_WITH_FRIENDS
  if pokeblocks ~= 0 then
    self:drawText("POKeBLOCKS W/FRIENDS", 3 * Game3.MENU_TILE, 11 * Game3.MENU_TILE)
    self:drawTrainerCardTextRight(tostring(pokeblocks), 28, 11)
  end

  local contests = self:getGameStat(Game3.GAME_STAT_WON_LINK_CONTEST) or 0
  if contests ~= 0 then
    self:drawText("CONTESTS W/FRIENDS", 3 * Game3.MENU_TILE, 13 * Game3.MENU_TILE)
    self:drawTrainerCardTextRight(tostring(contests), 28, 13)
  end

  local tower = self:ensureBattleTower()
  local tw = tonumber(tower and tower.totalWins) or 0
  local ts = tonumber(tower and tower.bestStreak) or 0
  if tw ~= 0 or ts ~= 0 then
    self:drawText("BATTLE TOWER W/  STRAIGHT", 3 * Game3.MENU_TILE, 15 * Game3.MENU_TILE)
    G.setColor(0.10, 0.10, 0.12, 1)
    self:drawText(("%d"):format(tw), 112, 120)
    self:drawText(("%d"):format(ts), 149, 120)
  end
end

function Game3:drawTrainerCard()
  local f = self.field
  if f and f.face == "back" then
    self:drawTrainerCardBack()
  else
    self:drawTrainerCardFront()
  end
end

function Game3:drawSaveAsk(f)
  local G = love.graphics
  G.setColor(0.10, 0.22, 0.45, 1)
  G.rectangle("fill", 0, 0, Game3.SCREEN_W, Game3.SCREEN_H)
  self:drawWindow(16, 8, 208, 96)
  G.setColor(0.10, 0.10, 0.12, 1)
  self:drawText(self:saveMapName(), 24, 16)
  self:drawText("PLAYER", 24, 32)
  self:drawText(self:playerName(), 120, 32)
  self:drawText("BADGES", 24, 48)
  self:drawText(tostring(self:badgeCount()), 120, 48)
  local y = 64
  if self:hasPokedex() then
    local seen = self:dexCounts()
    self:drawText("POKeDEX", 24, y)
    self:drawText(tostring(seen), 120, y)
    y = y + 16
  end
  self:drawText("TIME", 24, y)
  self:drawText(self:playTimeString(), 120, y)
  self:drawWindow(16, 112, 208, 40)
  G.setColor(0.10, 0.10, 0.12, 1)
  self:drawText(f and f.text or "Would you like to SAVE the game?", 24, 116)
  local cursor = f and f.cursor or 0
  local labels = { "YES", "NO" }
  for i = 0, 1 do
    local x = 48 + i * 80
    if i == cursor then self:drawCursor(x, 132) end
    G.setColor(0.10, 0.10, 0.12, 1)
    self:drawText(labels[i + 1], x + 12, 132)
  end
end

function Game3:itemDescription(id)
  local row = self:itemRow(id)
  if row and type(row.description) == "string" and row.description ~= "" then
    return row.description
  end
  return self:itemName(id)
end

-- item_menu.c pocket printers: ITEMS/BALLS name xN, KEY name (+ SELECT),
-- TM "## MOVE" xN / HM "# MOVE", BERRY "## NAME" xN.
function Game3:bagListLabel(slot, pocket)
  if not slot then return "" end
  local id = slot.id
  local count = slot.count or 0
  pocket = tonumber(pocket) or self:itemPocket(id)
  if pocket == Game3.POCKET_KEY then
    local mark = ((self.registeredItem or 0) == id) and " [SEL]" or ""
    return self:itemName(id) .. mark
  end
  if pocket == Game3.POCKET_TMHM then
    local moveName = self:tmhmMoveName(id) or ""
    local label = self:itemName(id)
    if moveName ~= "" then label = label .. " " .. moveName end
    if id < Game3.ITEM_HM_CUT then
      label = label .. ("  x%d"):format(count)
    end
    return label
  end
  if pocket == Game3.POCKET_BERRIES then
    local num = id - Game3.ITEM_CHERI_BERRY + 1
    if num < 1 then num = 1 end
    return ("%02d %s  x%d"):format(num, self:itemName(id), count)
  end
  return ("%s  x%d"):format(self:itemName(id), count)
end

-- CLOSE BAG destination line (gUnknown_0840E740[sReturnLocation]).
function Game3:bagCloseDestination(f)
  if self.phase == "battle" then return "the battle." end
  if f and f.giveTo then return "the POKeMON list." end
  if f and f.pickBerry then return "the previous menu." end
  return "the field."
end

function Game3:drawBagLines(text, x, y, lineH, maxLines)
  lineH = lineH or 16
  maxLines = maxLines or 3
  text = tostring(text or "")
  local lines = {}
  for line in (text .. "\n"):gmatch("(.-)\n") do
    lines[#lines + 1] = line
  end
  if #lines == 0 then lines[1] = text end
  for i = 1, math.min(#lines, maxLines) do
    self:drawText(lines[i], x, y + (i - 1) * lineH)
  end
end

function Game3:drawBag(f)
  local G = love.graphics
  local pocket = (f and f.pocket) or Game3.POCKET_ITEMS
  local list = self:bagSlotsIn(pocket)
  local total = #list + 1
  local cursor = f and f.cursor or 0
  if cursor < 0 then cursor = 0 end
  if cursor >= total then cursor = total - 1 end
  local rows = Game3.BAG_ROWS
  local start = 0
  if cursor >= rows then start = cursor - rows + 1 end

  -- Pocket-switch bob (item_menu.c bag sprite animNum + y wobble).
  local bob = 0
  local animT = f and f.pocketAnim or 0
  if animT and animT > 0 then
    bob = -math.floor(4 * math.sin((1 - animT) * math.pi))
  end

  -- item_menu.c: tan fill, bag + pocket on the left (tiles 0-13), list on
  -- the right from tile 14, CLOSE BAG last, description bottom-left.
  G.setColor(0.72, 0.55, 0.22, 1)
  G.rectangle("fill", 0, 0, Game3.SCREEN_W, Game3.SCREEN_H)
  self:drawWindow(4, 4 + bob, 104, 56)
  G.setColor(0.10, 0.10, 0.12, 1)
  self:drawText("BAG", 12, 10 + bob)
  if not (f and f.pickBerry) then
    self:drawText("<", 12, 28 + bob)
  end
  self:drawText(self:pocketName(pocket), 22, 28 + bob)
  if not (f and f.pickBerry) then
    self:drawText(">", 96, 28 + bob)
  end
  -- Five pocket dots under the bag (DrawPocketIndicatorDots).
  for i = 1, Game3.POCKET_COUNT do
    local dx = 20 + (i - 1) * 14
    if i == pocket then
      G.setColor(0.95, 0.85, 0.35, 1)
      G.circle("fill", dx, 52 + bob, 3)
    else
      G.setColor(0.45, 0.35, 0.20, 1)
      G.circle("fill", dx, 52 + bob, 2)
    end
  end

  self:drawWindow(112, 4, 124, 152)
  for i = 0, rows - 1 do
    local idx = start + i
    local y = 12 + i * 16
    if idx == cursor then self:drawCursor(116, y) end
    G.setColor(0.10, 0.10, 0.12, 1)
    if idx < #list then
      local slot = list[idx + 1]
      self:drawText(self:bagListLabel(slot, pocket), 128, y)
    elseif idx == #list then
      self:drawText(Game3.BAG_CLOSE, 128, y)
    end
  end
  -- Vertical scroll arrows (CreateVerticalScrollIndicators).
  if start > 0 then
    G.setColor(0.10, 0.10, 0.12, 1)
    self:drawText("^", 220, 4)
  end
  if start + rows < total then
    G.setColor(0.10, 0.10, 0.12, 1)
    self:drawText("v", 220, 148)
  end

  self:drawWindow(4, 104, 104, 52)
  G.setColor(0.10, 0.10, 0.12, 1)
  if cursor >= #list then
    -- ItemListMenu_InitDescription CLOSE BAG: "Return to" / destination.
    self:drawText("Return to", 12, 112)
    self:drawText(self:bagCloseDestination(f), 12, 128)
  else
    local slot = list[cursor + 1]
    if slot then
      self:drawBagLines(self:itemDescription(slot.id), 12, 112, 16, 3)
    end
  end
end

-- ---------- Party menu ----------
--
-- Ruby builds this screen out of one 116-tile sheet stamped into a tilemap
-- (party_menu.c sub_806B9A4 / sub_806BA94). A box's state is carried by
-- its palette rather than by different tiles, which is why there is no
-- cursor sprite here: the selected box simply lights up.

-- pokemon_icon.c sMonIconAnims, VBlanks between the two icon frames,
-- fastest first. The last entry repeats frame 0, so it does not bob.
Game3.ICON_BOB_DELAYS = { 6, 8, 14, 22, 0 }

-- party_menu.h PARTY_MENU_LAYOUT_*. Field START POKeMON is always
-- STANDARD. Battle party uses DOUBLE when b.doubles; LINK_DOUBLE /
-- MULTI are selected when f.layout (or b.partyLayout) asks for them.
Game3.PARTY_MENU_LAYOUT_STANDARD = 0
Game3.PARTY_MENU_LAYOUT_DOUBLE = 1
Game3.PARTY_MENU_LAYOUT_LINK_DOUBLE = 2
Game3.PARTY_MENU_LAYOUT_MULTI = 3

function Game3:menuArt(group)
  local menus = self.data and self.data.menus
  local art = menus and menus[group]
  if type(art) ~= "table" then return nil end
  return art
end

function Game3:menuPic(path)
  if type(path) ~= "string" then return nil end
  self._menuCache = self._menuCache or {}
  if self._menuCache[path] ~= nil then return self._menuCache[path] or nil end
  local img = self:grabImage(path)
  self._menuCache[path] = img or false
  return img
end

-- The tile atlas is laid out one row of tiles per palette, so a tile in a
-- given colour is a single quad lookup.
function Game3:partyTileQuad(sheet, id, pal)
  self._partyQuads = self._partyQuads or {}
  local key = id * 16 + pal
  local quad = self._partyQuads[key]
  if not quad then
    quad = love.graphics.newQuad(id * 8, pal * 8, 8, 8, sheet:getDimensions())
    self._partyQuads[key] = quad
  end
  return quad
end

function Game3:stampPartyBox(batch, sheet, shape, tx, ty, pal)
  if type(shape) ~= "table" then return end
  for r = 1, #shape do
    local row = shape[r]
    for c = 1, #row do
      batch:add(self:partyTileQuad(sheet, row[c], pal),
        (tx + c - 1) * 8, (ty + r - 1) * 8)
    end
  end
end

-- sub_806BF24: fainted mons get their own palette, and being under the
-- cursor shifts either colour up by four.
function Game3:partyBoxPalette(art, mon, selected)
  local pal = art.palNormal or 3
  if mon and (mon.hp or 0) <= 0 then pal = art.palFainted or 5 end
  if selected then pal = pal + (art.palSelected or 4) end
  return pal
end

-- GetHPBarLevel, which scales the bar into eighths before bucketing it.
function Game3:hpBarLevel(hp, maxHp)
  hp, maxHp = tonumber(hp) or 0, tonumber(maxHp) or 0
  if maxHp <= 0 then return 0 end
  if hp >= maxHp then return 3 end
  local eighths = math.floor(hp * 8 / maxHp + 0.5)
  if eighths > 4 then return 3 end
  if eighths == 4 then return 2 end
  if eighths > 1 then return 1 end
  return 0
end

-- SetMonIconAnimByHP: a mon at full health bobs fastest and one on its
-- last legs holds still.
function Game3:monIconFrame(mon)
  if not mon then return 0 end
  local hp, maxHp = mon.hp or 0, mon.maxHp or 0
  local anim = 1
  if hp ~= maxHp then
    local level = self:hpBarLevel(hp, maxHp)
    anim = ({ [3] = 2, [2] = 3, [1] = 4 })[level] or 5
  end
  local delay = Game3.ICON_BOB_DELAYS[anim] or 0
  if delay <= 0 then return 0 end
  return math.floor((self.vblank or 0) / delay) % 2
end

function Game3:drawMonIcon(species, x, y, frame)
  local art = self:menuArt("icons")
  local sheet = art and self:menuPic(art.atlas)
  if not sheet then return false end
  species = tonumber(species) or 0
  local cols = art.columns or 20
  local cw, ch = art.cellW or 32, art.cellH or 64
  local fh = art.frameH or 32
  self._iconQuads = self._iconQuads or {}
  local key = species * 2 + (frame or 0)
  local quad = self._iconQuads[key]
  if not quad then
    quad = love.graphics.newQuad(
      (species % cols) * cw,
      math.floor(species / cols) * ch + (frame or 0) * fh,
      cw, fh, sheet:getDimensions())
    self._iconQuads[key] = quad
  end
  love.graphics.setColor(1, 1, 1, 1)
  love.graphics.draw(sheet, quad, x, y)
  return true
end

-- gStatusGfx_Icons, four tiles per condition in STATUS_ORDER.
function Game3:drawPartyStatusIcon(art, status, x, y)
  local sheet = self:menuPic(art.status)
  if not sheet or not status then return false end
  local order = art.statusOrder or {}
  local row
  for i = 1, #order do
    if order[i] == status then row = i - 1 break end
  end
  if not row then return false end
  local w = (art.statusTiles or 4) * 8
  self._statusQuads = self._statusQuads or {}
  local quad = self._statusQuads[row]
  if not quad then
    quad = love.graphics.newQuad(0, row * 8, w, 8, sheet:getDimensions())
    self._statusQuads[row] = quad
  end
  love.graphics.setColor(1, 1, 1, 1)
  love.graphics.draw(sheet, quad, x, y)
  return true
end

-- DrawPartyMonBackground: STANDARD unless the caller (battle doubles)
-- asked for another row. Field START POKeMON never sets this.
function Game3:partyMenuLayout(f)
  if f and type(f.layout) == "number" then return f.layout end
  return Game3.PARTY_MENU_LAYOUT_STANDARD
end

-- Overlay layout rows onto the cached STANDARD art without mutating it.
-- ruby41 caches have no `layouts` field; Party.layoutFields supplies them.
function Game3:partyLayoutArt(art, layout)
  layout = layout or Game3.PARTY_MENU_LAYOUT_STANDARD
  if layout == Game3.PARTY_MENU_LAYOUT_STANDARD then return art end
  local fields = art.layouts and art.layouts[layout]
  if not fields then
    local Party = require("src.import.RomExtractorGen3Party")
    fields = Party.layoutFields(layout)
  end
  if not fields then return art end
  return setmetatable({
    boxAt = fields.boxAt,
    iconAt = fields.iconAt,
    nameAt = fields.nameAt,
    nameBox = fields.nameBox,
    levelAt = fields.levelAt,
    hpBarAt = fields.hpBarAt,
  }, { __index = art })
end

function Game3:partyBoxShape(art, layout, slot, mon)
  local Party = require("src.import.RomExtractorGen3Party")
  if Party.isLeadSlot(layout, slot) then return art.leadBox end
  return mon and art.slotBox or art.emptyBox
end

function Game3:drawPartyScreen(f)
  local art = self:menuArt("party")
  local sheet = art and self:menuPic(art.tiles)
  if not art or not sheet then return self:drawPartyScreenFallback(f) end

  local layout = self:partyMenuLayout(f)
  art = self:partyLayoutArt(art, layout)

  local G = love.graphics
  local party = self.party or {}
  local cursor = f and f.cursor or 0
  local from = f and f.kind == "party_switch" and ((f.monIndex or 1) - 1) or nil

  local bg = self:menuPic(art.background)
  if bg then
    G.setColor(1, 1, 1, 1)
    G.draw(bg, 0, 0)
  else
    G.setColor(0.16, 0.36, 0.28, 1)
    G.rectangle("fill", 0, 0, Game3.SCREEN_W, Game3.SCREEN_H)
  end

  self._partyBatch = self._partyBatch
    or G.newSpriteBatch(sheet, 512, "stream")
  local batch = self._partyBatch
  batch:clear()
  for slot = 0, 5 do
    local mon = party[slot + 1]
    local at = (art.boxAt or {})[slot + 1]
    if at then
      -- A mon being moved reads as selected too, so both ends of a switch
      -- stay lit while the player picks the destination.
      local lit = slot == cursor or slot == from
      local pal = self:partyBoxPalette(art, mon, lit)
      local shape = self:partyBoxShape(art, layout, slot, mon)
      self:stampPartyBox(batch, sheet, shape, at[1], at[2], pal)
    end
  end
  G.setColor(1, 1, 1, 1)
  G.draw(batch)

  for slot = 0, 5 do
    local mon = party[slot + 1]
    if mon then
      local at = (art.iconAt or {})[slot + 1]
      if at then
        self:drawMonIcon(mon.species, at[1], at[2], self:monIconFrame(mon))
        self:drawPartyHeldItem(art, mon, at[1], at[2])
      end
      self:drawPartySlotText(art, slot, mon, f)
    end
  end

  -- A forced switch has no way out, so Ruby offers no CANCEL.
  if not (f and f.noCancel) then self:drawPartyCancel(art, cursor) end
  self:drawPartyPrompt(f)
end

-- PartyMenuDoDrawHPBar: the "HP" label, six tiles of bar and the end cap,
-- with the fill's palette chosen by how much health is left.
function Game3:drawPartyHpBar(art, slot, mon)
  local G = love.graphics
  local at = (art.hpBarAt or {})[slot + 1]
  local sheet = self:menuPic(art.hpbar)
  if not at then return end
  local hp, maxHp = mon.hp or 0, mon.maxHp or 0
  local barTiles = art.hpBarTiles or 6
  local x, y = at[1] * 8, at[2] * 8
  if not sheet then
    self:drawHpBar(x, y, barTiles * 8, hp, maxHp)
    return
  end

  local labelPal = art.hpTilePal or 3
  local label = art.hpTileLabel or 9
  self:drawHpBarTile(sheet, label, labelPal, x - 16, y)
  self:drawHpBarTile(sheet, label + 1, labelPal, x - 8, y)
  self:drawHpBarTile(sheet, art.hpTileCap or 11, labelPal, x + barTiles * 8, y)

  local level = self:hpBarLevel(hp, maxHp)
  local pal = (art.hpFillPal or {})[level] or 6
  -- The bar is filled in eighths of a tile, so scale to pixels and let each
  -- tile take whichever of the nine fill tiles matches its own eighth.
  local filled = 0
  if maxHp > 0 then filled = math.floor(hp * barTiles * 8 / maxHp + 0.5) end
  if hp > 0 and filled < 1 then filled = 1 end
  for i = 0, barTiles - 1 do
    local eighths = filled - i * 8
    if eighths < 0 then eighths = 0 elseif eighths > 8 then eighths = 8 end
    self:drawHpBarTile(sheet, eighths, pal, x + i * 8, y)
  end
end

function Game3:drawHpBarTile(sheet, id, pal, x, y)
  self._hpQuads = self._hpQuads or {}
  local key = id * 16 + pal
  local quad = self._hpQuads[key]
  if not quad then
    quad = love.graphics.newQuad(id * 8, pal * 8, 8, 8, sheet:getDimensions())
    self._hpQuads[key] = quad
  end
  love.graphics.setColor(1, 1, 1, 1)
  love.graphics.draw(sheet, quad, x, y)
end

-- Font 4: 8x8 cells indexed by character code, already resolved through
-- sFontType1Map by the extractor. Used for the level and HP counts, which
-- the ROM prints only 8 pixels tall; nicknames stay on the 8x16 font.
function Game3:smallTextWidth(art, text)
  local widths = art and art.fontWidths
  if not widths then return #tostring(text or "") * 8 end
  local total = 0
  text = tostring(text or "")
  for i = 1, #text do
    total = total + (widths[Game3.fontCode(text:sub(i, i))] or 8)
  end
  return total
end

function Game3:drawSmallText(art, text, x, y)
  local sheet = art and self:menuPic(art.font)
  if not sheet then
    self:drawText(text, x, y)
    return
  end
  local G = love.graphics
  local widths = art.fontWidths or {}
  self._smallQuads = self._smallQuads or {}
  text = tostring(text or "")
  G.setColor(1, 1, 1, 1)
  local gx = x
  for i = 1, #text do
    local code = Game3.fontCode(text:sub(i, i))
    local quad = self._smallQuads[code]
    if not quad then
      quad = G.newQuad((code % 16) * 8, math.floor(code / 16) * 8, 8, 8,
        sheet:getDimensions())
      self._smallQuads[code] = quad
    end
    G.draw(sheet, quad, gx, y)
    gx = gx + (widths[code] or 8)
  end
end

-- A single tile out of gPartyMenuOrderText_Gfx. Returns false when the
-- sheet is missing so callers can fall back to drawn text.
function Game3:drawOrderTile(art, tile, x, y)
  local sheet = art and self:menuPic(art.order)
  if not (sheet and tile) then return false end
  local cols = art.orderCols or 16
  self._orderQuads = self._orderQuads or {}
  local quad = self._orderQuads[tile]
  if not quad then
    quad = love.graphics.newQuad((tile % cols) * 8,
      math.floor(tile / cols) * 8, 8, 8, sheet:getDimensions())
    self._orderQuads[tile] = quad
  end
  love.graphics.setColor(1, 1, 1, 1)
  love.graphics.draw(sheet, quad, x, y)
  return true
end

-- SpriteCB_HeldItemIcon parents the icon to the mon icon sprite, so it
-- rides along with the bob rather than sitting at a fixed offset.
function Game3:drawPartyHeldItem(art, mon, ix, iy)
  local item = mon and mon.item
  if not item or item == 0 or item == Game3.ITEM_NONE then return end
  local sheet = art and self:menuPic(art.hold)
  if not sheet then return end
  local frame = Game3.isMailItem(item) and (art.holdFrameMail or 1)
    or (art.holdFrameItem or 0)
  self._holdQuads = self._holdQuads or {}
  local quad = self._holdQuads[frame]
  if not quad then
    quad = love.graphics.newQuad(frame * 8, 0, 8, 8, sheet:getDimensions())
    self._holdQuads[frame] = quad
  end
  local at = art.holdAt or { 16, 22 }
  love.graphics.setColor(1, 1, 1, 1)
  love.graphics.draw(sheet, quad, ix + at[1], iy + at[2])
end

Game3.SPECIES_NIDORAN_F = 29
Game3.SPECIES_NIDORAN_M = 32

-- ShouldHideGenderIcon: the Nidoran lines carry their gender in the
-- species name, so the symbol is suppressed unless the mon was renamed.
function Game3:showsGenderIcon(mon)
  if not mon or mon.isEgg then return false end
  local species = mon.species
  if species ~= Game3.SPECIES_NIDORAN_M and species ~= Game3.SPECIES_NIDORAN_F then
    return true
  end
  return (mon.name or "") ~= (self:speciesName(species) or "")
end

-- PartyMenuDoPrintGenderIcon: tile 0x42 / 0x44 from GetMonGender. The
-- switch has no MON_GENDERLESS case, so Magnemite etc. stamp nothing.
-- makeMon never writes mon.gender; healthboxes already use monGender.
function Game3:partyGenderTile(mon, art)
  if not self:showsGenderIcon(mon) then return nil end
  local gender = self:monGender(mon)
  if gender == Game3.MON_MALE then
    return (art and art.tileMale) or 0x42
  end
  if gender == Game3.MON_FEMALE then
    return (art and art.tileFemale) or 0x44
  end
  return nil
end

function Game3:drawPartyGender(art, mon, lx, ly)
  local tile = self:partyGenderTile(mon, art)
  if not tile then return end
  -- PartyMenuDoPrintGenderIcon sits four tiles right of the "Lv" tile.
  self:drawOrderTile(art, tile, lx + 32, ly)
end

function Game3:drawPartySlotText(art, slot, mon, f)
  local G = love.graphics
  local name = (art.nameAt or {})[slot + 1]
  local level = (art.levelAt or {})[slot + 1]
  if not (name and level) then return end
  G.setColor(1, 1, 1, 1)
  -- The nickname shares gWindowTemplate_81E6CAC with the level and HP, so
  -- it is font 4 too. It copies both tile rows where they copy only the
  -- lower one, but every letter's upper tile is the blank, so what shows
  -- is the same 8 pixel text.
  self:drawSmallText(art, mon.name or "POKeMON", name[1] * 8, name[2] * 8 + 8)

  -- PartyMenuDoPrintLevel puts the "Lv" tile one column left and one row
  -- below the recorded position, with the number following it. A status
  -- condition takes over those same tiles instead.
  local lx, ly = (level[1] - 1) * 8, (level[2] + 1) * 8
  local status = mon.status
  local shown = false
  if status and status ~= "" and status ~= "none" then
    shown = self:drawPartyStatusIcon(art, status, lx, ly)
  end
  if not shown then
    -- "Lv" is a cart tile, not text; only the number is printed, and it
    -- starts 8 pixels in because the string carries a skip-to-x of 8.
    if self:drawOrderTile(art, art.tileLv, lx, ly) then
      self:drawSmallText(art, tostring(mon.level or 1), lx + 8, ly)
    else
      self:drawSmallText(art, ("Lv%d"):format(mon.level or 1), lx, ly)
    end
  end

  -- Gender is printed whether the slot shows a level or a status.
  self:drawPartyGender(art, mon, lx, ly)

  -- sub_808AE8C / sub_806D668: a TM/HM teach hides the HP bar and numbers
  -- and stamps ABLE / NOT ABLE / LEARNED in that row.
  local able = f and f.kind == "party_teach"
    and self:tmhmPartyLabel(mon, f.item)
  local at = (art.hpBarAt or {})[slot + 1]
  if able then
    if at then
      self:drawSmallText(art, able, (at[1] - 2) * 8, at[2] * 8)
    end
    return
  end

  self:drawPartyHpBar(art, slot, mon)

  -- PartyMenuDoPrintHP right-aligns both numbers, on the row under the bar.
  if at then
    local text = ("%d/%d"):format(mon.hp or 0, mon.maxHp or 0)
    local right = (at[1] + (art.hpBarTiles or 6) + 1) * 8
    self:drawSmallText(art, text, right - self:smallTextWidth(art, text),
      (at[2] + 1) * 8)
  end
end

function Game3:drawPartyCancel(art, cursor)
  local at = art.cancelAt or { 196, 136 }
  love.graphics.setColor(1, 1, 1, 1)
  if cursor == 6 then self:drawCursor(at[1] - 10, at[2]) end
  self:drawText("CANCEL", at[1], at[2])
end

function Game3:drawPartyPrompt(f)
  local kind = f and f.kind
  local prompt
  if kind == "party_switch" then prompt = "Move to where?" end
  if kind == "party_teach" then prompt = "Teach which POKeMON?" end
  if kind == "party_use" then prompt = "Use on which POKeMON?" end
  if kind == "party_pp" then
    prompt = Game3.PP_UP[f.item] and "Boost PP of which move?"
      or "Restore which move?"
  end
  -- The battle party menu supplies its own line.
  if f and f.prompt then prompt = f.prompt end
  if not prompt then return end
  -- The sixth slot box is stamped at tile row 13, so it runs to y 128.
  -- Anything starting above that buries a party member. The strip below
  -- is all that is free, and CANCEL lives in its right hand end.
  self:drawWindow(0, 128, 184, 32)
  love.graphics.setColor(1, 1, 1, 1)
  self:drawText(prompt, 8, 136)
end

-- Kept for caches imported before the party art existed, and for tests
-- that build a Game3 with no menu registry at all.
function Game3:drawPartyScreenFallback(f)
  local G = love.graphics
  G.setColor(0.22, 0.48, 0.38, 1)
  G.rectangle("fill", 0, 0, Game3.SCREEN_W, Game3.SCREEN_H)
  self:drawWindow(4, 4, 232, 152)
  G.setColor(0.10, 0.10, 0.12, 1)
  local title = "POKeMON"
  if f and f.kind == "party_switch" then title = "Move to where?" end
  if f and f.kind == "party_teach" then title = "Teach which?" end
  if f and f.kind == "party_use" then title = "Use on which?" end
  self:drawText(title, 16, 10)
  self:drawPartySlots(f)
end

function Game3:drawPartySlots(f)
  local G = love.graphics
  local party = self.party or {}
  local cursor = f and f.cursor or 0
  local from = f and f.kind == "party_switch" and ((f.monIndex or 1) - 1) or nil
  local compact = f and f.compact
  local rowW = compact and 136 or 208
  for i = 0, 5 do
    local mon = party[i + 1]
    local y = 16 + i * 22
    if from ~= nil and i == from then
      G.setColor(0.85, 0.78, 0.55, 1)
      G.rectangle("fill", 16, y - 2, rowW, 20)
    end
    if i == cursor then self:drawCursor(18, y) end
    G.setColor(0.10, 0.10, 0.12, 1)
    if mon then
      self:drawText(mon.name or "POKeMON", 28, y)
      local able = f and f.kind == "party_teach"
        and self:tmhmPartyLabel(mon, f.item)
      if able then
        self:drawText(("Lv%d"):format(mon.level or 1), 120, y)
        self:drawText(able, 148, y)
      elseif compact then
        self:drawText(("%d/%d"):format(mon.hp or 0, mon.maxHp or 0), 100, y)
      else
        self:drawText(("Lv%d"):format(mon.level or 1), 120, y)
        self:drawHpBar(148, y + 6, 48, mon.hp, mon.maxHp)
        self:drawText(("%d/%d"):format(mon.hp or 0, mon.maxHp or 0), 200, y)
      end
    else
      G.setColor(0.55, 0.55, 0.58, 1)
      self:drawText("----", 28, y)
    end
  end
end

function Game3:drawCandyStats(f)
  self:drawPartyScreen({
    kind = "party_use",
    cursor = 0,
    prompt = " ",
  })
  local growth = f.growth or {}
  self:drawWindow(88, 0, 152, 64)
  love.graphics.setColor(0.10, 0.10, 0.12, 1)
  local page = f.page or 0
  for i = 1, #growth do
    local row = growth[i]
    local col = i > 3 and 1 or 0
    local line = (i - 1) % 3
    local x = 96 + col * 72
    local y = 6 + line * 18
    self:drawText(row.name or "STAT", x, y)
    local shown
    if page < 1 then
      shown = ("+%d"):format(row.delta or 0)
    else
      shown = tostring(row.value or 0)
    end
    self:drawText(shown, x + 48, y)
  end
end

function Game3:drawPartyAction(f)
  self:drawPartyScreen({
    kind = "party",
    cursor = (f and f.monIndex or 1) - 1,
    compact = true,
  })
  local actions = (f and f.actions) or { "CANCEL" }
  local n = #actions
  local boxH = n * 14 + 12
  if boxH < 40 then boxH = 40 end
  local boxW = 88
  local boxX = Game3.SCREEN_W - boxW - 4
  local boxY = 20
  self:drawWindow(boxX, boxY, boxW, boxH)
  for i = 0, n - 1 do
    local y = boxY + 6 + i * 14
    if i == (f and f.cursor or 0) then self:drawCursor(boxX + 4, y) end
    love.graphics.setColor(0.10, 0.10, 0.12, 1)
    self:drawText(actions[i + 1], boxX + 14, y)
  end
end

function Game3:drawPartySummary(f)
  local G = love.graphics
  local mon = (f and f.mon) or (self.party or {})[(f and f.monIndex) or 1]
  local page = (f and f.page) or 0
  G.setColor(0.22, 0.38, 0.62, 1)
  G.rectangle("fill", 0, 0, Game3.SCREEN_W, Game3.SCREEN_H)
  self:drawWindow(8, 8, 224, 144)
  if not mon then return end
  local shiny = self:isShinyMon(mon)
  -- pokemon_summary_screen.c: GetMonSpritePalStructFromOtIdPersonality +
  -- sub_809FA94 palette swap (cream No. tiles when shiny).
  if mon.species and not mon.isEgg then
    self:drawBattlePic(mon.species, "front", 168, 36, 1, 0, false, shiny)
  end
  local titles = { "INFO", "SKILLS", "MOVES" }
  if shiny then
    -- sUnknown_083C157E RGB(30,30,27) vs normal RGB(26,26,23).
    G.setColor(30 / 31, 30 / 31, 27 / 31, 1)
  else
    G.setColor(0.10, 0.10, 0.12, 1)
  end
  self:drawText(mon.name or "POKeMON", 16, 14)
  if shiny then
    G.setColor(1.0, 0.92, 0.35, 1)
    self:drawText("*", 16 + #(mon.name or "POKeMON") * 6 + 4, 14)
  end
  G.setColor(0.10, 0.10, 0.12, 1)
  self:drawText(("Lv%d"):format(mon.level or 1), 120, 14)
  self:drawText(titles[page + 1] or "INFO", 176, 14)
  if page == 0 then
    self:drawText("OT", 16, 36)
    self:drawText(self:playerName(), 88, 36)
    self:drawText("IDNo.", 16, 52)
    self:drawText(self:trainerIdString(), 88, 52)
    self:drawText("NATURE", 16, 68)
    self:drawText(Game3.natureName(mon.pid), 88, 68)
    local t1 = Game3.typeName(mon.type1)
    local t2 = Game3.typeName(mon.type2)
    self:drawText("TYPE", 16, 84)
    if mon.type2 and mon.type2 ~= mon.type1 then
      self:drawText(t1 .. "/" .. t2, 88, 84)
    else
      self:drawText(t1, 88, 84)
    end
    self:drawText("EXP", 16, 100)
    self:drawText(tostring(mon.exp or 0), 88, 100)
    self:drawText("ITEM", 16, 116)
    if mon.item then
      self:drawText(self:itemName(mon.item), 88, 116)
    else
      self:drawText("NONE", 88, 116)
    end
  elseif page == 1 then
    local rows = {
      { "HP", ("%d/%d"):format(mon.hp or 0, mon.maxHp or 0) },
      { "ATTACK", tostring(mon.atk or 0) },
      { "DEFENSE", tostring(mon.def or 0) },
      { "SP. ATK", tostring(mon.spa or 0) },
      { "SP. DEF", tostring(mon.spd or 0) },
      { "SPEED", tostring(mon.spe or 0) },
    }
    for i = 1, #rows do
      local y = 32 + (i - 1) * 14
      self:drawText(rows[i][1], 16, y)
      self:drawText(rows[i][2], 120, y)
    end
    self:drawText("ABILITY", 16, 122)
    self:drawText(Game3.abilityName(mon.ability), 88, 122)
  else
    local moves = mon.moves or {}
    for i = 1, 4 do
      local mv = moves[i]
      local y = 36 + (i - 1) * 24
      if mv then
        self:drawText(mv.name or "MOVE", 16, y)
        self:drawText(Game3.typeName(mv.type), 120, y)
        self:drawText(("%d/%d"):format(mv.pp or 0, mv.maxPp or 0), 176, y)
      else
        G.setColor(0.55, 0.55, 0.58, 1)
        self:drawText("-", 16, y)
        G.setColor(0.10, 0.10, 0.12, 1)
      end
    end
  end
  G.setColor(0.10, 0.10, 0.12, 1)
  self:drawText("< > pages  A/B back", 16, 138)
end

-- gPokedexMenu2_Gfx laid out eight tiles across. Each band is one label; the
-- engine draws from it rather than typing the words itself.
function Game3:dexInterfaceBand(name, width)
  local art = self:dexArt()
  local sheet = art and art.interface and self:menuPic(art.interface)
  if not sheet then return nil end
  local bands = art.interfaceBands or {}
  local band = bands[name]
  if not band then return nil end
  local w = width or band[3] or art.interfaceW or 64
  local key = name .. ':' .. tostring(w)
  self._dexBandQuads = self._dexBandQuads or {}
  local quad = self._dexBandQuads[key]
  if not quad then
    quad = love.graphics.newQuad(0, band[1], w, band[2], sheet:getDimensions())
    self._dexBandQuads[key] = quad
  end
  return sheet, quad, band[2], w
end

function Game3:drawDexBand(name, x, y, width)
  local sheet, quad = self:dexInterfaceBand(name, width)
  if not sheet then return false end
  love.graphics.setColor(1, 1, 1, 1)
  love.graphics.draw(sheet, quad, x, y)
  return true
end

-- CreateInterfaceSprites (pokeruby): SEEN/OWN are 64x32 OAM sprites on the
-- LEFT panel at centres (32,40)/(32,72). START/MENU/SELECT/SEARCH are the
-- bottom-left prompts at (16,138)/(48,138)/(16,158)/(48,158). The old code
-- put SEEN/OWN at the bottom and never drew the prompts or scroll arrows.
-- Coordinates below are top-left corners (OAM centre converted).
Game3.DEX_BACKDROP = { 123 / 255, 131 / 255, 0 / 255 }
Game3.DEX_ROW_H = 16
Game3.DEX_LIST_TOP = 16
Game3.DEX_BALL_X = 0x11 * 8
Game3.DEX_NUM_X = 0x12 * 8
Game3.DEX_NAME_X = 0x17 * 8
-- SEEN/OWN 64x32 at centres (32,40)/(32,72) -> top-left (0,24)/(0,56)
Game3.DEX_SEEN_X = 0
Game3.DEX_SEEN_Y = 24
Game3.DEX_OWN_Y = 56
-- Digits are 8x16 at centres (28,48)/(34,48)/(40,48) and (28,80)/(34,80)/(40,80)
Game3.DEX_DIGIT_XS = { 24, 30, 36 }
Game3.DEX_DIGIT_Y_SEEN = 40
Game3.DEX_DIGIT_Y_OWN = 72
-- START/MENU 64x32 at (16,138)/(48,138); SELECT/SEARCH at (16,158)/(48,158)
Game3.DEX_START_X = -16
Game3.DEX_START_Y = 122
Game3.DEX_MENU_X = 16
Game3.DEX_SELECT_Y = 142
Game3.DEX_SEARCH_X = 16
-- Scroll arrows 16x8 at centres (184,4)/(184,156)
Game3.DEX_ARROW_X = 176
Game3.DEX_ARROW_TOP_Y = 0
Game3.DEX_ARROW_BOTTOM_Y = 152
-- Scrollbar 8x8 at centre (234,20)
Game3.DEX_SCROLLBAR_X = 230
Game3.DEX_SCROLLBAR_Y0 = 20
Game3.DEX_SCROLLBAR_TRAVEL = 120
-- List-selected mon sprite: CreatePokedexMonSprite(..., 0x60, 0x50) OAM centre
Game3.DEX_PORTRAIT_X = 0x60
Game3.DEX_PORTRAIT_Y = 0x50
-- Interface sheet: digit frames start at tile 224, two tiles (8x16) each
Game3.DEX_DIGIT_TILE0 = 224
Game3.DEX_INTERFACE_COLS = 8

function Game3:drawDexDigit(digit, x, y)
  local art = self:dexArt()
  local sheet = art and art.interface and self:menuPic(art.interface)
  if not sheet then return false end
  digit = math.floor(tonumber(digit) or 0) % 10
  local tile = Game3.DEX_DIGIT_TILE0 + digit * 2
  local cols = Game3.DEX_INTERFACE_COLS
  local iw, ih = sheet:getDimensions()
  self._dexDigitQuads = self._dexDigitQuads or {}
  local key = digit
  local pair = self._dexDigitQuads[key]
  if not pair then
    local tx = (tile % cols) * 8
    local ty = math.floor(tile / cols) * 8
    local tx2 = ((tile + 1) % cols) * 8
    local ty2 = math.floor((tile + 1) / cols) * 8
    pair = {
      love.graphics.newQuad(tx, ty, 8, 8, iw, ih),
      love.graphics.newQuad(tx2, ty2, 8, 8, iw, ih),
    }
    self._dexDigitQuads[key] = pair
  end
  love.graphics.setColor(1, 1, 1, 1)
  love.graphics.draw(sheet, pair[1], x, y)
  love.graphics.draw(sheet, pair[2], x, y + 8)
  return true
end

function Game3:drawDexCount(n, y)
  n = math.max(0, math.floor(tonumber(n) or 0))
  local hundreds = math.floor(n / 100)
  local tens = math.floor((n % 100) / 10)
  local ones = n % 10
  local xs = Game3.DEX_DIGIT_XS
  local drew = false
  if hundreds ~= 0 then
    drew = self:drawDexDigit(hundreds, xs[1], y) or drew
  end
  if hundreds ~= 0 or tens ~= 0 then
    drew = self:drawDexDigit(tens, xs[2], y) or drew
  end
  drew = self:drawDexDigit(ones, xs[3], y) or drew
  if not drew then
    love.graphics.setColor(1, 1, 1, 1)
    self:drawText(('%3d'):format(n), xs[1], y)
  end
  return true
end

-- Arrow is tile 1 as a 16x8 wide sprite (tiles 1 and 2 on the 8-wide sheet).
function Game3:drawDexScrollArrow(x, y, flipDown)
  local art = self:dexArt()
  local sheet = art and art.interface and self:menuPic(art.interface)
  if not sheet then return false end
  local iw, ih = sheet:getDimensions()
  self._dexArrowQuad = self._dexArrowQuad
    or love.graphics.newQuad(8, 0, 16, 8, iw, ih)
  love.graphics.setColor(1, 1, 1, 1)
  if flipDown then
    love.graphics.draw(sheet, self._dexArrowQuad, x, y + 8, 0, 1, -1)
  else
    love.graphics.draw(sheet, self._dexArrowQuad, x, y)
  end
  return true
end

function Game3:drawDexScrollbar(cursor, count)
  local art = self:dexArt()
  local sheet = art and art.interface and self:menuPic(art.interface)
  if not sheet then return false end
  local iw, ih = sheet:getDimensions()
  -- Tile 3: 8x8 scrollbar nub
  self._dexScrollQuad = self._dexScrollQuad
    or love.graphics.newQuad(24, 0, 8, 8, iw, ih)
  local n = math.max(1, (count or 1) - 1)
  local t = math.max(0, math.min(1, (cursor or 0) / n))
  local y = Game3.DEX_SCROLLBAR_Y0 + t * Game3.DEX_SCROLLBAR_TRAVEL - 4
  love.graphics.setColor(1, 1, 1, 1)
  love.graphics.draw(sheet, self._dexScrollQuad, Game3.DEX_SCROLLBAR_X, y)
  return true
end

-- gSineTable unit: sin(i * 2pi/256) * 256. Used by SpriteCB_RotatingPokeBall.
function Game3.dexSin(i)
  i = math.floor(tonumber(i) or 0) % 256
  return math.floor(math.sin(i * math.pi * 2 / 256) * 256 + 0.5)
end

-- gSpriteAnim_83A0444 FRAME(16): 32x32 poke ball from interface sheet tile 16.
-- Sheet is 8 tiles wide; OAM is 1D, so reassemble 4x4 tiles into a canvas.
function Game3:dexRotatingBallPic()
  if self._dexBallPic ~= nil then
    return self._dexBallPic or nil
  end
  local art = self:dexArt()
  local sheet = art and art.interface and self:menuPic(art.interface)
  if not (sheet and love and love.graphics and love.graphics.newCanvas) then
    self._dexBallPic = false
    return nil
  end
  local cols = Game3.DEX_INTERFACE_COLS or 8
  local tile0 = 16
  local iw, ih = sheet:getDimensions()
  local prev = love.graphics.getCanvas and love.graphics.getCanvas() or nil
  local canvas = love.graphics.newCanvas(32, 32)
  love.graphics.setCanvas(canvas)
  love.graphics.clear(0, 0, 0, 0)
  love.graphics.setColor(1, 1, 1, 1)
  for row = 0, 3 do
    for col = 0, 3 do
      local tid = tile0 + row * 4 + col
      local sx = (tid % cols) * 8
      local sy = math.floor(tid / cols) * 8
      local q = love.graphics.newQuad(sx, sy, 8, 8, iw, ih)
      love.graphics.draw(sheet, q, col * 8, row * 8)
    end
  end
  love.graphics.setCanvas(prev)
  if canvas.setFilter then canvas:setFilter("nearest", "nearest") end
  self._dexBallPic = canvas
  return canvas
end

-- CreateInterfaceSprites: two RotatingPokeBall sprites at (0, 80) with
-- data[1] = 0 and 0x80. SpriteCB_RotatingPokeBall orbits r=40 and spins.
Game3.DEX_BALL_CENTER_X = 0
Game3.DEX_BALL_CENTER_Y = 80
Game3.DEX_BALL_ORBIT = 40

function Game3:drawDexRotatingBalls(rotation)
  local G = love.graphics
  rotation = math.floor(tonumber(rotation) or 0x40) % 256
  local pic = self:dexRotatingBallPic()
  local cx = Game3.DEX_BALL_CENTER_X
  local cy = Game3.DEX_BALL_CENTER_Y
  local radius = Game3.DEX_BALL_ORBIT
  -- OAM objMode=2 (blend); keep them soft so they do not punch through UI.
  local phases = { 0, 0x80 }
  for i = 1, #phases do
    local phase = phases[i]
    local pos = (rotation + phase + 0x40) % 256
    local x = cx + Game3.dexSin(pos + 0x40) * radius / 256
    local y = cy + Game3.dexSin(pos) * radius / 256
    local spin = (rotation + phase) % 256
    local angle = spin * math.pi * 2 / 256
    if pic then
      G.setColor(1, 1, 1, 0.85)
      G.draw(pic, x, y, angle, 1, 1, 16, 16)
    else
      -- Geometric fallback when the interface sheet is missing.
      G.push()
      G.translate(x, y)
      G.rotate(angle)
      G.setColor(0.92, 0.30, 0.26, 0.9)
      G.circle("fill", 0, -4, 8)
      G.setColor(1, 1, 1, 0.9)
      G.circle("fill", 0, 4, 8)
      G.setColor(0.15, 0.15, 0.18, 0.95)
      G.rectangle("fill", -9, -1.5, 18, 3)
      G.setColor(0.15, 0.15, 0.18, 0.95)
      G.circle("line", 0, 0, 8)
      G.pop()
    end
  end
  G.setColor(1, 1, 1, 1)
end

function Game3:drawDexList(f)
  local G = love.graphics
  local art = self:dexArt()
  -- LoadPokedexBgPalette: National unlock swaps the list background palette.
  local bgPath = art and ((self:hasNationalDex() and art.mainNational) or art.main)
  local bg = bgPath and self:menuPic(bgPath)
  if bg then
    G.setColor(Game3.DEX_BACKDROP[1], Game3.DEX_BACKDROP[2],
      Game3.DEX_BACKDROP[3], 1)
    G.rectangle('fill', 0, 0, Game3.SCREEN_W, Game3.SCREEN_H)
    G.setColor(1, 1, 1, 1)
    G.draw(bg, 0, 0)
  else
    G.setColor(0.16, 0.22, 0.38, 1)
    G.rectangle('fill', 0, 0, Game3.SCREEN_W, Game3.SCREEN_H)
  end

  local list = (f and f.list) or {}
  local cursor = f and f.cursor or 0
  local rows = Game3.DEX_LIST_ROWS

  -- SpriteCB_RotatingPokeBall decorative orbit (left of the list).
  self:drawDexRotatingBalls((f and f.pokeBallRotation) or 0x40)

  -- selected mon kept near the middle of the visible window (b - 5 on cart;
  -- with eight on-screen rows the midpoint is still the right anchor)
  local top = cursor - math.floor(rows / 2)
  if top > #list - rows then top = #list - rows end
  if top < 0 then top = 0 end
  if f then f.scroll = top end

  for i = 0, rows - 1 do
    local row = list[top + i + 1]
    local y = Game3.DEX_LIST_TOP + i * Game3.DEX_ROW_H
    if row then
      if top + i == cursor then
        G.setColor(1, 1, 1, 0.22)
        G.rectangle('fill', Game3.DEX_BALL_X - 2, y,
          Game3.SCREEN_W - Game3.DEX_BALL_X + 2, Game3.DEX_ROW_H)
      end
      if row.caught then
        G.setColor(0.92, 0.30, 0.26, 1)
        G.circle('fill', Game3.DEX_BALL_X + 4, y + 8, 4)
        G.setColor(1, 1, 1, 1)
        G.rectangle('fill', Game3.DEX_BALL_X, y + 7, 9, 2)
      end
      -- List text on the olive panel is dark, like PrintMonDexNumAndName.
      G.setColor(0.10, 0.10, 0.12, 1)
      self:drawText(('%03d'):format(self:dexListNumber(row.id)),
        Game3.DEX_NUM_X, y + 2)
      self:drawText(row.name, Game3.DEX_NAME_X, y + 2)
    end
  end

  local sel = list[cursor + 1]
  if sel then
    self:drawDexPortrait(sel.id, Game3.DEX_PORTRAIT_X, Game3.DEX_PORTRAIT_Y)
  end

  local seen, caught = self:dexCounts()
  G.setColor(1, 1, 1, 1)
  -- Left-panel SEEN / OWN (64-wide sheet frames)
  if not self:drawDexBand('seen', Game3.DEX_SEEN_X, Game3.DEX_SEEN_Y, 64) then
    G.setColor(1, 1, 1, 1)
    self:drawText('SEEN', Game3.DEX_SEEN_X, Game3.DEX_SEEN_Y)
  end
  if not self:drawDexBand('own', Game3.DEX_SEEN_X, Game3.DEX_OWN_Y, 64) then
    G.setColor(1, 1, 1, 1)
    self:drawText('OWN', Game3.DEX_SEEN_X, Game3.DEX_OWN_Y)
  end
  self:drawDexCount(seen, Game3.DEX_DIGIT_Y_SEEN)
  self:drawDexCount(caught, Game3.DEX_DIGIT_Y_OWN)

  -- Bottom prompts: START / MENU / SELECT / SEARCH
  self:drawDexBand('start', Game3.DEX_START_X, Game3.DEX_START_Y, 64)
  self:drawDexBand('menu', Game3.DEX_MENU_X, Game3.DEX_START_Y, 64)
  self:drawDexBand('select', Game3.DEX_START_X, Game3.DEX_SELECT_Y, 64)
  self:drawDexBand('search', Game3.DEX_SEARCH_X, Game3.DEX_SELECT_Y, 64)

  if cursor > 0 then
    self:drawDexScrollArrow(Game3.DEX_ARROW_X, Game3.DEX_ARROW_TOP_Y, false)
  end
  if cursor < #list - 1 then
    self:drawDexScrollArrow(Game3.DEX_ARROW_X, Game3.DEX_ARROW_BOTTOM_Y, true)
  end
  if #list > 1 then
    self:drawDexScrollbar(cursor, #list)
  end

  if #list < 1 then
    G.setColor(0.10, 0.10, 0.12, 1)
    self:drawText('No POKeMON seen yet.', Game3.DEX_NUM_X, 72)
  end
end

-- List screen: OAM centre (0x60, 0x50). Info/cry: OAM centre (0x30, 0x38).
function Game3:drawDexPortrait(species, x, y)
  local pic = self:battlePic(species, 'front')
  if pic then
    self:drawSpriteCenter(pic, x, y)
    return true
  end
  return self:drawMonIcon(species, x - 16, y - 16, 0)
end
function Game3:dexArt()
  local art = self:menuArt("dex")
  return type(art) == "table" and art or nil
end

-- pokedex.c loads one tile set for the whole Pokedex and swaps only the
-- tilemap, so each screen has its own background over the same tiles. Before
-- these were extracted the size and cry screens borrowed the entry chrome,
-- which is simply the wrong picture.
function Game3:drawDexChrome(which)
  local art = self:dexArt()
  local img = art and self:menuPic(art[which or "entry"] or art.entry)
  local G = love.graphics
  -- Colour 0 in the chrome is keyed transparent; paint the olive backdrop
  -- first so entry/cry/size panels do not show the overworld through.
  G.setColor(Game3.DEX_BACKDROP[1], Game3.DEX_BACKDROP[2],
    Game3.DEX_BACKDROP[3], 1)
  G.rectangle("fill", 0, 0, Game3.SCREEN_W, Game3.SCREEN_H)
  if img then
    G.setColor(1, 1, 1, 1)
    G.draw(img, 0, 0)
    return true
  end
  self:drawWindow(4, 4, 232, 152)
  return false
end

function Game3:drawDexFootprint(species)
  species = tonumber(species) or 0
  if species < 0 then return end
  local art = self:dexArt()
  local sheet = art and self:menuPic(art.footprints)
  if not sheet then return end
  local cols = tonumber(art.footprintCols) or 20
  local px = tonumber(art.footprintPx) or Game3.DEX_FOOTPRINT_PX
  local col = species % cols
  local row = math.floor(species / cols)
  local x = tonumber(art.footprintTileX)
  local y = tonumber(art.footprintTileY)
  x = (x and x * 8) or Game3.DEX_FOOTPRINT_X
  y = (y and y * 8) or Game3.DEX_FOOTPRINT_Y
  local G = love.graphics
  G.setColor(1, 1, 1, 1)
  self:drawSpriteCenter(sheet, x + px / 2, y + px / 2,
    col * px, row * px, px, px, 1)
end

-- gPokedexScreenSelectBarMain_Tilemap: the PAGE / AREA / CRY / SIZE / CANCEL
-- strip along the bottom, a 32x3 tile map rather than five words the engine
-- draws itself. The highlight is still ours, since the cart moves a sprite
-- cursor over the strip rather than baking one into it.
Game3.DEX_SELECT_BAR_Y = 136
Game3.DEX_SELECT_BAR_SLOT_W = 40
Game3.DEX_SELECT_BAR_X0 = 8

function Game3:drawDexSelectBar(state)
  local G = love.graphics
  local bar = (state and (state.bar or state.screen)) or Game3.DEX_SCREEN_INFO
  local art = self:dexArt()
  -- The info page gets the main bar; AREA, CRY and SIZE each load the
  -- submenu one instead.
  local which = art and art.selectBar
  if bar ~= Game3.DEX_SCREEN_INFO and art and art.selectBarSub then
    which = art.selectBarSub
  end
  local strip = which and self:menuPic(which)
  if strip then
    G.setColor(1, 1, 1, 1)
    G.draw(strip, 0, Game3.DEX_SELECT_BAR_Y)
    local n = #Game3.DEX_SCREEN_NAMES
    local i = math.max(0, math.min(n - 1, bar))
    G.setColor(1, 1, 1, 0.30)
    G.rectangle("fill",
      Game3.DEX_SELECT_BAR_X0 + i * Game3.DEX_SELECT_BAR_SLOT_W,
      Game3.DEX_SELECT_BAR_Y + 2, Game3.DEX_SELECT_BAR_SLOT_W - 2, 12)
    return
  end
  -- No cache yet: the words on their own, which is what shipped before.
  local names = Game3.DEX_SCREEN_NAMES
  local x = 8
  for i = 1, #names do
    if (i - 1) == bar then
      G.setColor(0.90, 0.28, 0.22, 1)
      self:drawCursor(x, 138)
    end
    G.setColor(0.10, 0.10, 0.12, 1)
    self:drawText(names[i], x + 10, 138)
    x = x + 58
  end
end

function Game3:drawDexSizeScreen(state)
  local G = love.graphics
  local species = (state and (state.dexSpecies or state.species)) or 0
  local row = self:speciesRow(species) or {}
  local monScale = Game3.dexAffineScale(row.pokemonScale)
  local trainerScale = Game3.dexAffineScale(row.trainerScale)
  local monOff = tonumber(row.pokemonOffset) or 0
  local trainerOff = tonumber(row.trainerOffset) or 0
  self:drawDexChrome("size")
  G.setColor(0.10, 0.10, 0.12, 1)
  self:drawText(Game3.TEXT_DEX_SIZE_COMPARED .. (self:playerName() or ""),
    16, 12)
  -- pokedex.c CreateSizeScreenTrainerPic / CreateMonSpriteFromNationalDexNumber:
  -- both use sSizeScreenSilhouette_Pal (all black). drawSpriteCenter resets
  -- colour to white, so silhouette must draw its own tinted quad.
  local function silhouette(pic, x, y, scale, fallbackW)
    scale = scale or 1
    if pic and pic.getDimensions then
      local iw, ih = pic:getDimensions()
      local fw, fh = iw, ih
      -- intro3 sheets are 4x 64x64 frames; trainer fronts are 64x64.
      if iw >= 256 and ih >= 64 then
        fw, fh = 64, 64
      elseif iw >= 64 and ih >= 64 and iw ~= ih then
        fw, fh = 64, 64
      end
      local key = ("dexsil:%s:%d:%d"):format(tostring(pic), fw, fh)
      self.quads = self.quads or {}
      local q = self.quads[key]
      if not q then
        q = love.graphics.newQuad(0, 0, fw, fh, iw, ih)
        self.quads[key] = q
      end
      G.setColor(0.05, 0.05, 0.06, 1)
      G.draw(pic, q, x, y, 0, scale, scale, fw / 2, fh / 2)
    else
      local w = math.floor((fallbackW or 48) * scale)
      G.setColor(0.05, 0.05, 0.06, 1)
      G.rectangle("fill", x - w / 2, y - w / 2, w, w)
    end
  end
  silhouette(self:battlePic(species, "front"),
    Game3.DEX_SIZE_MON_X, Game3.DEX_SIZE_MON_Y + monOff, monScale, 48)
  -- CreateSizeScreenTrainerPic(gSaveBlock2.playerGender, 152, 56, 0) uses
  -- gTrainerFrontPicTable[gender]. Prefer intro3 / trainerFront cinema keys
  -- (mayFront/brendanFront never existed and produced the black square).
  local trainer = nil
  if self.playerTrainerBattleImage then
    trainer = self:playerTrainerBattleImage()
  end
  if not trainer and self.cinemaPic then
    if self:isFemale() then
      trainer = self:cinemaPic("trainerFrontMay") or self:cinemaPic("intro3may")
    else
      trainer = self:cinemaPic("trainerFrontBrendan")
        or self:cinemaPic("intro3brendan")
    end
  end
  silhouette(trainer,
    Game3.DEX_SIZE_TRAINER_X, Game3.DEX_SIZE_TRAINER_Y + trainerOff,
    trainerScale, 40)
  self:drawDexSelectBar(state or { screen = Game3.DEX_SCREEN_SIZE })
end

function Game3:drawDexCryScreen(state)
  local G = love.graphics
  local species = (state and (state.dexSpecies or state.species)) or 0
  self:drawDexChrome("cry")
  G.setColor(0.10, 0.10, 0.12, 1)
  self:drawText(Game3.TEXT_DEX_CRY_OF, 80, 16)
  self:drawText(self:speciesName(species), 80, 32)
  do
    local pic = self:battlePic(species, "front")
    if pic then
      self:drawSpriteCenter(pic, Game3.DEX_PIC_X, Game3.DEX_PIC_Y)
    else
      self:drawBattlePic(species, "front", Game3.DEX_PIC_X - 32, Game3.DEX_PIC_Y - 32, 1, 0, false)
    end
  end
  -- Task_LoadCryScreen loads the submenu select bar; PLAY is a chrome tile
  -- on the cry layout, not a hand-drawn green rectangle.
  self:drawDexSelectBar(state or { screen = Game3.DEX_SCREEN_CRY })
end

function Game3:drawDexAreaScreen(state)
  local G = love.graphics
  local species = (state and (state.dexSpecies or state.species)) or 0
  local habitat = self:dexHabitatFor(species)
  local img = self.cinemaPic and self:cinemaPic("regionMap")
  G.setColor(0.05, 0.18, 0.45, 1)
  G.rectangle("fill", 0, 0, Game3.SCREEN_W, Game3.SCREEN_H)
  local pa = Game3RegionMap.ZOOM_PA_OUT
  local function mapXY(mx, my)
    return Game3RegionMap.screenXY(mx, my, 0, 0, pa)
  end
  if img then
    G.setColor(1, 1, 1, 1)
    G.draw(img, Game3RegionMap.ZOOM_CX, Game3RegionMap.ZOOM_CY,
      0, 1, 1, Game3RegionMap.ZOOM_CX, Game3RegionMap.ZOOM_CY)
  end
  local ow = habitat.overworld or {}
  local xmin = Game3RegionMap.CURSOR_X_MIN
  local ymin = Game3RegionMap.CURSOR_Y_MIN
  local xmax = xmin + Game3RegionMap.WIDTH - 1
  local ymax = ymin + Game3RegionMap.HEIGHT - 1
  local pulse = math.floor((self.playSeconds or 0) * 4) % 2 == 1
  local glowA = pulse and 0.55 or 0.35
  for cy = ymin, ymax do
    for cx = xmin, xmax do
      local sec = Game3RegionMap.sectionAt(cx, cy)
      if ow[sec] then
        local x, y = mapXY(cx * 8, cy * 8)
        G.setColor(1, 0.85, 0.15, glowA)
        G.rectangle("fill", x, y, 8, 8)
      end
    end
  end
  local sp = habitat.special or {}
  local blink = math.floor((self.playSeconds or 0) * 6) % 2 == 1
  for sec in pairs(sp) do
    if not blink then
      local cx, cy = Game3RegionMap.cursorForSection(sec)
      local x, y = mapXY(cx * 8 + 4, cy * 8 + 4)
      G.setColor(0.95, 0.25, 0.20, 0.95)
      G.circle("fill", x, y, 5)
      G.setColor(1, 1, 1, 0.95)
      G.circle("line", x, y, 5)
    end
  end
  self:drawStdWindow(0, 0, 12, 3)
  G.setColor(0.10, 0.10, 0.12, 1)
  self:drawText("AREA", 8, 8)
  self:drawText(self:speciesName(species), 8, 20)
  if Game3.dexHabitatCount(habitat) < 1 then
    self:drawStdWindow(6, 7, 23, 11)
    G.setColor(0.10, 0.10, 0.12, 1)
    self:drawText(Game3.TEXT_DEX_AREA_UNKNOWN, 64, 72)
  end
  -- Task_InitAreaScreenMultistep loads the submenu select bar here, the same
  -- as CRY and SIZE; this used to be a hand-written "B back" instead.
  self:drawDexSelectBar(state or { screen = Game3.DEX_SCREEN_AREA })
end

function Game3:drawDexEntry(state)
  local G = love.graphics
  local screen = (state and state.screen) or Game3.DEX_SCREEN_INFO
  local fromCatch = state and (state.dexFromCatch or state.fromCatch)
  if not fromCatch then
    if screen == Game3.DEX_SCREEN_SIZE then
      self:drawDexSizeScreen(state)
      return
    end
    if screen == Game3.DEX_SCREEN_CRY then
      self:drawDexCryScreen(state)
      return
    end
    if screen == Game3.DEX_SCREEN_AREA then
      self:drawDexAreaScreen(state)
      return
    end
  end
  local species = (state and (state.dexSpecies or state.species)) or 0
  local page = (state and (state.dexPage or state.page)) or 0
  local owned = state and state.owned
  if owned == nil then owned = self:hasCaught(species) end
  self:drawDexChrome()
  G.setColor(0.10, 0.10, 0.12, 1)
  if fromCatch then
    self:drawText(Game3.TEXT_DEX_REGISTERED, 16, 8)
  end
  local num = self:dexListNumber(species)
  -- pokedex.c Task_InitPageScreenMultistep prints each field at its own tile
  -- position, and "No", "HT" and "WT" are already tiles in the chrome. The
  -- engine was drawing those labels a second time as text, at coordinates
  -- that matched none of them.
  local dy = fromCatch and Game3.DEX_ENTRY_CATCH_DROP or 0
  self:drawText(("%03d"):format(num), Game3.DEX_ENTRY_NUM_X,
    Game3.DEX_ENTRY_NUM_Y + dy)
  self:drawText(self:speciesName(species), Game3.DEX_ENTRY_NAME_X,
    Game3.DEX_ENTRY_NUM_Y + dy)
  self:drawText(self:dexCategoryText(species, owned),
    Game3.DEX_ENTRY_CATEGORY_X, Game3.DEX_ENTRY_CATEGORY_Y + dy)
  local ht = "??'??\""
  local wt = "????.? lbs."
  if owned then
    local row = self:speciesRow(species)
    ht = Game3.dexHeightText(row and row.height)
    wt = Game3.dexWeightText(row and row.weight)
  end
  self:drawText(ht, Game3.DEX_ENTRY_VALUE_X, Game3.DEX_ENTRY_HT_Y + dy)
  self:drawText(wt, Game3.DEX_ENTRY_VALUE_X, Game3.DEX_ENTRY_WT_Y + dy)
  -- pokedex.c CreateMonSpriteFromNationalDexNumber always loads
  -- gMonPaletteTable (normal). ROM dex INFO/SIZE/CRY never show shiny;
  -- only battle/summary/HoF use GetMonSpritePalFromOtIdPersonality.
  do
    local pic = self:battlePic(species, "front")
    if pic then
      self:drawSpriteCenter(pic, Game3.DEX_PIC_X, Game3.DEX_PIC_Y)
    else
      self:drawBattlePic(species, "front", Game3.DEX_PIC_X - 32, Game3.DEX_PIC_Y - 32, 1, 0, false)
    end
  end
  if owned then
    self:drawDexFootprint(species)
  end
  local flavor = self:dexFlavorText(species, page, owned)
  local lines = Game3.wrapDialogue(flavor, 208)
  local fy = Game3.DEX_ENTRY_TEXT_Y + (fromCatch and 8 or 0)
  local maxLines = fromCatch and 3 or 2
  for i = 1, math.min(maxLines, #lines) do
    self:drawText(lines[i], Game3.DEX_ENTRY_TEXT_X, fy + (i - 1) * 12)
  end
  if not fromCatch then
    self:drawDexSelectBar(state)
  end
end

function Game3:drawRegionMapFlyIcons(f, mapXY)
  local G = love.graphics
  local flags = self.flags or {}
  local t = f.t or 0
  local cx = f.cursorX or Game3RegionMap.CURSOR_X_MIN
  local cy = f.cursorY or Game3RegionMap.CURSOR_Y_MIN
  local sel = Game3.regionMapSectionAt(cx, cy)
  for i = 0, 15 do
    local dest = Game3.FLY_DESTINATIONS[i + 1]
    local visited = dest and flags[dest.flag]
    local ex, ey = Game3.regionMapCursorForSection(i)
    local w, h = Game3RegionMap.entrySize(i)
    local mx, my = mapXY(ex * 8 + 4, ey * 8 + 4)
    local iw, ih = 8, 8
    if w == 2 then iw = 16 elseif h == 2 then ih = 16 end
    local blink = visited and sel == i and math.floor(t / 16) % 2 == 1
    if not blink then
      if visited then
        G.setColor(1, 1, 0.55, 0.85)
      else
        G.setColor(0.30, 0.32, 0.40, 0.55)
      end
      G.rectangle("fill", mx - iw / 2, my - ih / 2, iw, ih)
    end
  end
  if flags[Game3.FLAG_LANDMARK_BATTLE_TOWER] then
    local tx, ty = Game3.regionMapCursorForSection(Game3.MAPSEC_BATTLE_TOWER)
    local mx, my = mapXY(tx * 8, ty * 8)
    local blink = sel == Game3.MAPSEC_BATTLE_TOWER and math.floor(t / 16) % 2 == 1
    if not blink then
      G.setColor(0.90, 0.28, 0.22, 0.90)
      G.rectangle("fill", mx - 8, my - 8, 16, 16)
    end
  end
end

function Game3:drawRegionMap(f)
  local G = love.graphics
  local img = self:cinemaPic("regionMap")
  local pa = f.zoomPA or Game3RegionMap.ZOOM_PA_OUT
  local sx = f.scrollX or 0
  local sy = f.scrollY or 0
  local function mapXY(mx, my)
    return Game3RegionMap.screenXY(mx, my, sx, sy, pa)
  end
  if img then
    G.setColor(1, 1, 1, 1)
    local scale = Game3RegionMap.ZOOM_PA_OUT / pa
    G.draw(img, Game3RegionMap.ZOOM_CX, Game3RegionMap.ZOOM_CY,
      0, scale, scale, sx + Game3RegionMap.ZOOM_CX, sy + Game3RegionMap.ZOOM_CY)
  else
    G.setColor(0.05, 0.18, 0.45, 1)
    G.rectangle("fill", 0, 0, Game3.SCREEN_W, Game3.SCREEN_H)
  end
  local xmin = Game3RegionMap.CURSOR_X_MIN
  local ymin = Game3RegionMap.CURSOR_Y_MIN
  local cx = f.cursorX or xmin
  local cy = f.cursorY or ymin
  local px = f.playerX or cx
  local py = f.playerY or cy
  if f.flyMode or f.kind == "fly" then
    self:drawRegionMapFlyIcons(f, mapXY)
  end
  local iconName = self:isFemale() and "regionMapMay" or "regionMapBrendan"
  local pmx, pmy = mapXY(px * 8 + 4, py * 8 + 4)
  self:drawSpriteCenter(self:cinemaPic(iconName), pmx, pmy)
  local frame = 0
  local t = f.t or 0
  if math.floor(t / Game3.REGION_MAP_CURSOR_FRAMES) % 2 == 1 then
    frame = 1
  end
  local curScale = (f.zoomed or f.zooming) and pa < 200 and 2 or 1
  local cmx, cmy
  if f.zoomed and not f.zooming then
    cmx, cmy = Game3RegionMap.ZOOM_CX, Game3RegionMap.ZOOM_CY
  else
    cmx, cmy = mapXY(cx * 8 + 4, cy * 8 + 4)
  end
  self:drawSpriteCenter(self:cinemaPic("regionMapCursor"),
    cmx, cmy, frame * 16, 0, 16, 16, curScale)
  self:drawStdWindow(21, 0, 29, 3)
  G.setColor(0.10, 0.10, 0.12, 1)
  self:drawText("HOENN", 22 * Game3.MENU_TILE, 1 * Game3.MENU_TILE)
  local sec = Game3.regionMapSectionAt(cx, cy)
  local kind = self:regionMapKind(sec)
  local fly = f.flyMode or f.kind == "fly"
  local showName = kind ~= Game3RegionMap.KIND_NONE
  if fly then
    showName = kind == Game3RegionMap.KIND_FLY or kind == Game3RegionMap.KIND_SPECIAL
  end
  local name = ""
  if showName then name = Game3.regionMapName(sec) end
  local marks = {}
  if not fly and not f.scripted and kind ~= Game3RegionMap.KIND_NONE then
    marks = Game3RegionMap.landmarkNames(sec, Game3RegionMap.areaIndex(cx, cy),
      self.flags)
  end
  local extra = 0
  if name ~= "" and sec == Game3.MAPSEC_EVER_GRANDE
      and self.flags and self.flags[Game3.FLAG_SYS_POKEMON_LEAGUE_FLY]
      and fly then
    extra = 1
  end
  local markLines = #marks
  local top = 16 - markLines * 2 - extra * 2
  if top < 14 then top = 14 end
  self:drawStdWindow(16, top, 29, 19)
  G.setColor(0.10, 0.10, 0.12, 1)
  local ty = (top + 1) * Game3.MENU_TILE
  if name ~= "" then
    self:drawText(name, 17 * Game3.MENU_TILE, ty)
    ty = ty + 16
  end
  if extra == 1 then
    local area = Game3RegionMap.areaIndex(cx, cy)
    self:drawText(area == 0 and "POKeMON LEAGUE" or "POKeMON CENTER",
      17 * Game3.MENU_TILE, ty)
    ty = ty + 16
  end
  for i = 1, markLines do
    self:drawText(marks[i], 17 * Game3.MENU_TILE, ty)
    ty = ty + 16
  end
  if fly then
    G.setColor(0.10, 0.10, 0.12, 1)
    self:drawText("Fly to where?", 8, 0x90)
  end
end

function Game3:drawFieldOverlay()
  local G = love.graphics
  local f = self.field
  if not f or f.kind == "move" or f.kind == "delay" or f.kind == "wait"
      or f.kind == "door_enter" or f.kind == "door_arrival"
      or f.kind == "truck_seq" then
    return
  end
  if f.kind == "cable_car" then
    self:drawCableCar(f)
    return
  end
  if f.kind == "egg_hatch" then
    self:drawEggHatch(f)
    return
  end
  if f.kind == "trainer_approach" then
    if f.stage == "trans" then
      local t = 1 - ((f.wait or 0) / 0.35)
      if t < 0 then t = 0 elseif t > 1 then t = 1 end
      G.setColor(1, 1, 1, t * 0.85)
      G.rectangle("fill", 0, 0, Game3.SCREEN_W, Game3.SCREEN_H)
      local band = math.floor(t * 10)
      for i = 0, band do
        G.setColor(0, 0, 0, 1)
        G.rectangle("fill", 0, i * 16, Game3.SCREEN_W, 8)
        G.rectangle("fill", 0, Game3.SCREEN_H - 8 - i * 16, Game3.SCREEN_W, 8)
      end
    end
    return
  end
  if f.kind == "menu" then
    self:drawStartMenu(f)
    return
  end
  if f.kind == "option" then
    self:drawOptionMenu(f)
    return
  end
  if f.kind == "trainer_card" then
    self:drawTrainerCard()
    return
  end
  if f.kind == "save_ask" then
    self:drawSaveAsk(f)
    return
  end
  if f.kind == "bag" then
    self:drawBag(f)
    return
  end
  if f.kind == "bag_actions" then
    self:drawBagActions(f)
    return
  end
  if f.kind == "dex_start" then
    self:drawDexStartMenu(f)
    return
  end
  if f.kind == "dex_search" then
    self:drawDexSearch(f)
    return
  end
  if f.kind == "starter" or f.kind == "starter_yesno" then
    self:drawStarterChoose(f)
    return
  end
  if f.kind == "mart" then
    self:drawMartMenu(f)
    return
  end
  if f.kind == "party" or f.kind == "party_switch"
      or f.kind == "party_teach" or f.kind == "party_use"
      or f.kind == "party_give" then
    self:drawPartyScreen(f)
    return
  end
  if f.kind == "party_forget" or f.kind == "party_pp" then
    local mon = (self.party or {})[(f.monIndex or 1)]
    local moves = mon and mon.moves or {}
    local actions = {}
    for i = 1, #moves do
      actions[i] = (moves[i] and moves[i].name) or "MOVE"
    end
    actions[#actions + 1] = "CANCEL"
    self:drawPartyAction({
      monIndex = f.monIndex, cursor = f.cursor, actions = actions,
    })
    return
  end
  if f.kind == "learn_forget" then
    local mon = (self.learnMove and self.learnMove.mon) or f.mon
    local moves = mon and mon.moves or {}
    local actions = {}
    for i = 1, #moves do
      actions[i] = (moves[i] and moves[i].name) or "MOVE"
    end
    actions[#actions + 1] = "CANCEL"
    local index = 1
    local party = self.party or {}
    for i = 1, #party do
      if party[i] == mon then index = i break end
    end
    self:drawPartyAction({
      monIndex = index, cursor = f.cursor, actions = actions,
    })
    return
  end
  if f.kind == "party_action" or f.kind == "party_item" then
    self:drawPartyAction(f)
    return
  end
  if f.kind == "party_summary" then
    self:drawPartySummary(f)
    return
  end
  if f.kind == "candy_stats" then
    self:drawCandyStats(f)
    return
  end
  if f.kind == "mail_read" then
    self:drawPartyScreen({ kind = "party", cursor = 0 })
    self:drawWindow(16, 40, 208, 80)
    love.graphics.setColor(0.10, 0.10, 0.12, 1)
    self:drawText(self:itemName(f.item), 32, 56)
    self:drawText("The MAIL is blank.", 32, 80)
    return
  end
  if f.kind == "pokeblock_case" then
    self:drawMenuListWindow(0, 1, f.labels, f.cursor)
    return
  end
  if f.kind == "fishing" then
    if (f.step or 0) < Game3.FISH_START_ROUND then return end
    self:drawDialogueFrame()
    self:drawDialogue(f)
    return
  end
  if f.kind == "trade_scene" then
    self:drawTradeScene(f)
    local pose = Game3.tradeScenePose(f.t)
    if pose.text then
      self:drawDialogueFrame()
      self:drawDialogue(f)
    end
    return
  end
  -- Field/trade EvolutionScene: shiny front via evo.mon OT×PID.
  if f.kind == "evolve" then
    self:drawTradeEvolution(f)
    return
  end
  if f.kind == "dex" then
    self:drawDexList(f)
    return
  end
  if f.kind == "dex_entry" then
    self:drawDexEntry(f)
    return
  end
  if f.kind == "contest_winner" and f.subject then
    self:drawContestPainting(f)
    return
  end
  if f.kind == "pc" then
    self:drawPc(f)
    return
  end
  if f.kind == "braille" then
    self:drawBrailleMessage(f)
    return
  end
  if f.kind == "hof" then
    self:drawHofCinema(f)
    return
  end
  if f.kind == "credits" then
    self:drawCreditsCinema(f)
    return
  end
  if f.kind == "hof_pc" then
    self:drawHofPc(f)
    return
  end
  if f.kind == "slots" or f.kind == "roulette" then
    self:drawGameCorner(f)
    return
  end
  self:drawDialogueFrame()
  if f.kind == "daycare" then
    local labels = { "LEAVE", "TAKE" }
    G.setColor(0.10, 0.10, 0.12, 1)
        self:drawText("DAY CARE", 8, 116)
    for i = 1, #labels do
      local y = 128 + (i - 1) * 12
      if (i - 1) == (f.cursor or 0) then
        G.setColor(0.90, 0.28, 0.22, 1)
        self:drawCursor(8, y)
      end
      G.setColor(0.10, 0.10, 0.12, 1)
        self:drawText(labels[i], 18, y)
    end
  elseif f.kind == "daycare_send" or f.kind == "npc_trade"
      or f.kind == "move_tutor_mon" then
    local party = self.party or {}
    local start = f.cursor or 0
    G.setColor(0.10, 0.10, 0.12, 1)
        self:drawText(f.kind == "daycare_send" and "Leave which?"
          or "Which POKeMON?", 8, 116)
    for i = 0, 1 do
      local mon = party[start + i + 1]
      local y = 128 + i * 12
      if i == 0 then
        G.setColor(0.90, 0.28, 0.22, 1)
        self:drawCursor(8, y)
      end
      G.setColor(0.10, 0.10, 0.12, 1)
      if mon then
        self:drawText(("%s  Lv%d"):format(mon.name, mon.level or 1), 18, y)
      end
    end
  elseif f.kind == "daycare_take" then
    local list = self:daycareTakeRows()
    local start = f.cursor or 0
    G.setColor(0.10, 0.10, 0.12, 1)
        self:drawText("Take which?", 8, 116)
    for i = 0, 1 do
      local row = list[start + i + 1]
      local y = 128 + i * 12
      if i == 0 then
        G.setColor(0.90, 0.28, 0.22, 1)
        self:drawCursor(8, y)
      end
      G.setColor(0.10, 0.10, 0.12, 1)
      if row then
        self:drawText(("%s  Lv%d->$%d"):format(row.name, row.toLevel, row.cost), 18, y)
      end
    end
  elseif f.kind == "fly" then
    self:drawRegionMap(f)
  elseif f.kind == "gender" then
    G.setColor(0.10, 0.10, 0.12, 1)
        self:drawText("Are you a boy or a girl?", 10, 116)
    local labels = { "BOY", "GIRL" }
    for i = 0, 1 do
      local y = 130 + i * 10
      if i == (f.cursor or 0) then
        G.setColor(0.90, 0.28, 0.22, 1)
        self:drawCursor(8, y)
      end
      G.setColor(0.10, 0.10, 0.12, 1)
        self:drawText(labels[i + 1], 18, y)
    end
  elseif f.kind == "nickname" then
    local Naming = require("src.ui.gen3.NamingScreen")
    Naming.draw(self, f)
  elseif f.kind == "clock_set" or f.kind == "clock_yesno" or f.kind == "clock_view" then
    local WallClock = require("src.ui.gen3.WallClock")
    WallClock.draw(self, f)
  elseif f.kind == "diploma" then
    G.setColor(0.10, 0.10, 0.12, 1)
    self:drawText(("%s's DIPLOMA"):format(self:playerName()), 10, 100)
    self:drawText("HOENN POKeDEX", 10, 114)
    self:drawText("A/B close", 8, 148)
  elseif f.kind == "link_records" then
    self:drawLinkBattleRecords()
  elseif f.kind == "tower_records" then
    self:drawBattleTowerRecords()
  elseif f.kind == "slots" then
    G.setColor(0.10, 0.10, 0.12, 1)
    self:drawText("SLOT MACHINE", 10, 100)
    self:drawText(("COINS %d  BET %d  PIKA %d"):format(
        self:getCoins(), f.bet or 1, f.pikaPower or 0), 10, 110)
    local names = Game3.SLOT_SYM_NAME
    if f.windows then
      for r = 1, 3 do
        local w = f.windows[r]
        local row = {}
        for k = 1, 3 do
          row[#row + 1] = names[(w[k] or 0) + 1] or "?"
        end
        self:drawText(table.concat(row, " "), 10, 118 + (r - 1) * 10)
      end
      if f.reelTimeNote then
        self:drawText(("REEL TIME x%d"):format(f.reelTimeNote), 140, 118)
      elseif (f.reelTimeLeft or 0) > 0 then
        self:drawText(("RT %d"):format(f.reelTimeLeft), 140, 118)
      end
      if (f.payout or 0) > 0 then
        self:drawText(("PAYOUT %d"):format(f.payout), 10, 148)
      elseif f.replay then
        self:drawText("REPLAY", 10, 148)
      else
        self:drawText("A again  B exit", 8, 148)
      end
    else
      self:drawText("LEFT/RIGHT bet  A spin  B exit", 8, 140)
    end
  elseif f.kind == "roulette" then
    local labels = Game3.ROULETTE_LABELS
    local cur = f.cursor or 6
    local spinIdx = 0
    if f.spinning then
      spinIdx = math.floor((f.spinT or 0) * 18) % 12
    end
    local flash = Game3.ROULETTE_SLOTS[spinIdx + 1]
    for row = 0, 3 do
      for col = 0, 4 do
        local id = row * 5 + col
        if id ~= 0 then
          local x = 8 + col * 46
          local y = 8 + row * 18
          if id == cur then
            G.setColor(0.95, 0.85, 0.20, 1)
            G.rectangle("fill", x - 2, y - 2, 44, 16)
          end
          if f.spinning and id == flash then
            G.setColor(1, 1, 1, 0.55)
            G.rectangle("fill", x - 2, y - 2, 44, 16)
          end
          if f.landed == id then
            G.setColor(0.20, 0.85, 0.35, 1)
            G.rectangle("fill", x - 2, y - 2, 44, 16)
          end
          G.setColor(0.10, 0.10, 0.12, 1)
          self:drawText(labels[id] or "?", x, y)
        end
      end
    end
    G.setColor(0.10, 0.10, 0.12, 1)
    self:drawText(("COINS %d  BET %d  BALL %d/%d  x%d"):format(
      self:getCoins(), f.minBet or 1, f.balls or 0, Game3.ROULETTE_BALLS,
      self:rouletteMultiplier(cur, f)), 8, 88)
    if f.spinning then
      self:drawText("...", 8, 100)
    elseif f.landed then
      local hit = f.won and ((f.mult == 12 and "JACKPOT") or "HIT") or "NOTHING DOING"
      self:drawText(("%s  %s  +%d"):format(
        hit, labels[f.landed] or "?", f.payout or 0), 8, 100)
      if f.cleared then self:drawText("BOARD CLEARED", 8, 112) end
    else
      self:drawText("DPAD pick  A spin  B exit", 8, 100)
    end
  elseif f.kind == "script_yesno"
      or f.kind == "secret_base_yesno"
      or f.kind == "decor_yesno"
      or f.kind == "safari_retire"
      or f.kind == "learn_yesno" or f.kind == "learn_stop"
      or f.kind == "tm_yesno" or f.kind == "tutor_confirm" or f.kind == "tutor_giveup"
      or f.kind == "surf_yesno"
      or f.kind == "egg_nick" then
    self:drawDialogue(f)
    if self:yesNoReady(f) then
      self:drawYesNoWindow(f.boxX, f.boxY, f.cursor or 0)
    end
  elseif f.kind == "script_choice" then
    if f.text then self:drawDialogue(f) end
    if self:yesNoReady(f) then
      self:drawMenuListWindow(f.boxX, f.boxY, f.labels, f.cursor, f.perRow)
    end
  elseif f.kind == "decor_menu" then
    -- SecretBase_EventScript_PCShowMainMenu is `message` + `waitmessage` +
    -- `multichoice`: a real dialogue box at the bottom with the menu
    -- window over it, not a bare line floating on the map. The decoration
    -- PC's own menus additionally re-print as the cursor moves, since
    -- gUnknown_083EC624 explains whichever entry is highlighted.
    local note = f.note
    if f.notes then note = f.notes[(f.cursor or 0) + 1] end
    if note then
      self:drawDialogueFrame()
      self:drawDialogue({ text = note })
    end
    self:drawMenuListWindow(0, 1, f.labels, f.cursor)
  elseif f.kind == "mauville_menu" or f.kind == "move_tutor_list"
      or f.kind == "move_deleter" or f.kind == "player_pc" then
    local note = f.note
    if note then
      G.setColor(0.10, 0.10, 0.12, 1)
      self:drawText(note, 8, 100)
    end
    self:drawMenuListWindow(0, 1, f.labels, f.cursor)
  elseif self.drawPlayerPcMenus and self:drawPlayerPcMenus(f) then
    return
  elseif f.kind == "easy_chat" then
    G.setColor(0.10, 0.10, 0.12, 1)
    if f.text then self:drawText(f.text, 10, 100) end
    local labels = f.labels or {}
    local cur = f.cursor or 0
    local start = 0
    if #labels > 4 then
      start = math.max(0, math.min(cur, #labels - 4))
    end
    for i = 0, math.min(3, #labels - 1) do
      local idx = start + i
      local y = 116 + i * 10
      if idx == cur then
        G.setColor(0.90, 0.28, 0.22, 1)
        self:drawCursor(8, y)
      end
      G.setColor(0.10, 0.10, 0.12, 1)
      self:drawText(labels[idx + 1] or "", 18, y)
    end
  elseif f.kind == "daycare_egg" or f.kind == "secret_base_move" then
    G.setColor(0.10, 0.10, 0.12, 1)
        self:drawText(f.text or (f.kind == "secret_base_move"
      and "Move your SECRET BASE here?" or "Want the EGG?"), 10, 116)
    local labels = { "YES", "NO" }
    for i = 0, 1 do
      local y = 130 + i * 10
      if i == (f.cursor or 0) then
        G.setColor(0.90, 0.28, 0.22, 1)
        self:drawCursor(8, y)
      end
      G.setColor(0.10, 0.10, 0.12, 1)
        self:drawText(labels[i + 1], 18, y)
    end
  elseif f.kind == "contest_cat" then
    G.setColor(0.10, 0.10, 0.12, 1)
        self:drawText("Which CONTEST?", 8, 116)
    local names = Game3.CONTEST_CAT_NAMES
    local start = f.cursor or 0
    for i = 0, 1 do
      local y = 128 + i * 12
      if i == 0 then
        G.setColor(0.90, 0.28, 0.22, 1)
        self:drawCursor(8, y)
      end
      G.setColor(0.10, 0.10, 0.12, 1)
      local name = names[start + i + 1]
      if name then self:drawText(name, 18, y) end
    end
  elseif f.kind == "contest_mon" then
    local party = self.party or {}
    local start = f.cursor or 0
    G.setColor(0.10, 0.10, 0.12, 1)
        self:drawText("Enter which?", 8, 116)
    for i = 0, 1 do
      local mon = party[start + i + 1]
      local y = 128 + i * 12
      if i == 0 then
        G.setColor(0.90, 0.28, 0.22, 1)
        self:drawCursor(8, y)
      end
      G.setColor(0.10, 0.10, 0.12, 1)
      if mon then
        self:drawText(("%s  Lv%d"):format(mon.name, mon.level or 1), 18, y)
      end
    end
  elseif f.kind == "contest_rank" then
    local ranks = f.ranks or { 0 }
    local start = f.cursor or 0
    G.setColor(0.10, 0.10, 0.12, 1)
        self:drawText("Which rank?", 8, 116)
    for i = 0, 1 do
      local rank = ranks[start + i + 1]
      local y = 128 + i * 12
      if i == 0 then
        G.setColor(0.90, 0.28, 0.22, 1)
        self:drawCursor(8, y)
      end
      G.setColor(0.10, 0.10, 0.12, 1)
      if rank then
        self:drawText(Game3.CONTEST_RANK_NAMES[rank + 1] or "NORMAL", 18, y)
      end
    end
  elseif f.kind == "contest_move" then
    local c = self.contest or {}
    local mon = self.party and self.party[c.monIndex]
    local moves = mon and mon.moves or {}
    local start = f.cursor or 0
    local round = (c.appealNumber or c.turn or 0) + 1
    if round > Game3.CONTEST_TURNS then round = Game3.CONTEST_TURNS end
    local applause = c.applauseLevel or 0
    local meter = string.rep("*", applause) .. string.rep("-", 4 - applause)
    G.setColor(0.10, 0.10, 0.12, 1)
    self:drawText(("APPEAL %d/%d  Crowd %s"):format(
      round, Game3.CONTEST_TURNS, meter), 8, 4)
    if c.mons then
      for row = 0, 3 do
        local who = 0
        while who < 4 and (c.turnOrder and c.turnOrder[who]) ~= row do
          who = who + 1
        end
        if who > 3 then who = row end
        local src = c.mons[who]
        local st = c.status and c.status[who]
        local y = 16 + row * 12
        local mark = (who == (c.playerIndex or 3)) and ">" or " "
        local pts = st and (st.pointTotal or 0) or 0
        local hearts = Contest3.hearts(st and st.appeal or 0)
        G.setColor(0.10, 0.10, 0.12, 1)
        self:drawText(("%s%s  %d  %s"):format(
          mark, (src and src.nickname) or "????", pts,
          string.rep("<", hearts)), 8, y)
      end
    end
    if c.phase == "text" then
      local text = Contest3.currentText(c, self) or ""
      local y = 68
      for line in (text .. "\r\n"):gmatch("(.-)\r\n") do
        G.setColor(0.10, 0.10, 0.12, 1)
        self:drawText(line, 8, y)
        y = y + 12
      end
      self:drawText("A continue", 160, 148)
    else
      G.setColor(0.10, 0.10, 0.12, 1)
      self:drawText("Choose a move.", 8, 68)
      for i = 0, 1 do
        local move = moves[start + i + 1]
        local y = 80 + i * 12
        if i == 0 then
          G.setColor(0.90, 0.28, 0.22, 1)
          self:drawCursor(8, y)
        end
        G.setColor(0.10, 0.10, 0.12, 1)
        if move then
          local id = move.id or 0
          local row = Contest3.moveRow(id)
          local erow = Contest3.effectRow(row.e)
          local a = Contest3.hearts(erow.a)
          local j = Contest3.hearts(erow.j)
          local cats = Game3.CONTEST_CAT_NAMES
          local cat = cats[(row.c or 0) + 1] or ""
          self:drawText(("%s %s +%d -%d"):format(
            move.name or "MOVE", cat, a, j), 18, y)
        end
      end
      local sel = moves[start + 1]
      if sel then
        local desc = Contest3.moveDescription(sel.id or 0)
        local y = 108
        for line in (desc .. "\r\n"):gmatch("(.-)\r\n") do
          G.setColor(0.10, 0.10, 0.12, 1)
          self:drawText(line, 8, y)
          y = y + 12
        end
      end
    end
  elseif f.kind == "contest_results" or f.kind == "contest_winner" then
    if f.kind == "contest_winner" and f.subject then
      self:drawContestPainting(f)
    else
      G.setColor(0.10, 0.10, 0.12, 1)
      self:drawText(f.text or self:contestResultsText(), 8, 128)
      self:drawText("A continue", 160, 148)
    end
  elseif f.kind == "pokenav" then
    self:drawRegionMap(f)
  elseif f.kind == "pokenav_menu" then
    self:drawPokenavMenu(f)
  elseif f.kind == "trainers_eye" then
    self:drawTrainersEye(f)
  elseif f.kind == "pokenav_condition" then
    self:drawPokenavCondition(f)
  elseif f.kind == "pokenav_ribbons" then
    self:drawPokenavRibbons(f)
  elseif f.kind == "blender_berry" then
    local slots = f.slots or {}
    local start = f.cursor or 0
    G.setColor(0.10, 0.10, 0.12, 1)
    self:drawText("Choose a BERRY to blend.", 8, 116)
    for i = 0, 1 do
      local slot = slots[start + i + 1]
      local y = 128 + i * 12
      if i == 0 then
        G.setColor(0.90, 0.28, 0.22, 1)
        self:drawCursor(8, y)
      end
      G.setColor(0.10, 0.10, 0.12, 1)
      if slot then
        self:drawText(self:itemName(slot.id), 18, y)
      end
    end
  elseif f.kind == "blender_spin" then
    self:drawBlenderSpin(f)
  else
    self:drawDialogue(f)
  end
end

function Game3:drawBlenderSpin(f)
  local G = love.graphics
  local cx, cy, r = 120, 70, 42
  G.setColor(0.82, 0.78, 0.70, 1)
  if G.circle then G.circle("fill", cx, cy, r) end
  G.setColor(0.55, 0.42, 0.28, 1)
  if G.circle then G.circle("line", cx, cy, r) end
  -- Player hit wedge (seat 0: var1 32..80 → arrow units).
  local function wedge(a0, a1, rr, gg, bb, aa)
    local steps = 10
    G.setColor(rr, gg, bb, aa)
    for i = 0, steps - 1 do
      local t0 = (a0 + (a1 - a0) * i / steps) / 65536 * math.pi * 2 - math.pi / 2
      local t1 = (a0 + (a1 - a0) * (i + 1) / steps) / 65536 * math.pi * 2 - math.pi / 2
      local x0, y0 = cx + math.cos(t0) * r, cy + math.sin(t0) * r
      local x1, y1 = cx + math.cos(t1) * r, cy + math.sin(t1) * r
      if G.polygon then
        G.polygon("fill", cx, cy, x0, y0, x1, y1)
      end
    end
  end
  -- var1 = arrow/256+24; window [32,80) → arrow [2048,14336); BEST [7168,9216).
  wedge(2048, 14336, 0.35, 0.75, 0.40, 0.55)
  wedge(7168, 9216, 0.95, 0.85, 0.20, 0.85)
  local ang = ((f.arrowPos or 0) / 65536) * math.pi * 2 - math.pi / 2
  local ax = cx + math.cos(ang) * (r - 4)
  local ay = cy + math.sin(ang) * (r - 4)
  G.setColor(0.90, 0.20, 0.18, 1)
  if G.line then
    G.setLineWidth(2)
    G.line(cx, cy, ax, ay)
    G.setLineWidth(1)
  end
  if G.circle then G.circle("fill", ax, ay, 3) end
  local rpm = Game3.blenderRpmFromSpeed(f.speed)
  local scores = f.scores or {}
  G.setColor(0.10, 0.10, 0.12, 1)
  self:drawText(("RPM %d.%02d  MAX %d.%02d"):format(
      math.floor(rpm / 100), rpm % 100,
      math.floor((f.maxRpm or 0) / 100), (f.maxRpm or 0) % 100), 8, 118)
  self:drawText(("BEST %d  GOOD %d  MISS %d"):format(
      scores.best or 0, scores.good or 0, scores.miss or 0), 8, 130)
  local prog = math.min(1000, f.progress or 0)
  self:drawText(("BLEND %d%%"):format(math.floor(prog / 10)), 8, 142)
  self:drawText("A when the arrow is in the yellow!", 8, 152)
  if (f.flashT or 0) > 0 and f.flash then
    local label = string.upper(tostring(f.flash))
    if f.flash == "best" then
      G.setColor(0.95, 0.80, 0.15, 1)
    elseif f.flash == "good" then
      G.setColor(0.25, 0.70, 0.30, 1)
    else
      G.setColor(0.85, 0.20, 0.20, 1)
    end
    self:drawText(label, 180, 118)
  end
end

function Game3:update(dt)
  -- Audio and tilt stay on real time so GAME SPEED does not pitch music
  -- or fling the camera, matching Gen 1/2.
  self:updateMusic(dt)
  require("src.render.Tilt").update(dt)
  local speed = self:logicSpeed()
  FixedStep.maxAccum = math.max(0.25, speed * FixedStep.STEP * 1.5)
  if not self._speedClock then
    FixedStep:init(function(step) self:logicStep(step) end)
    self._speedClock = true
  end
  FixedStep:update((tonumber(dt) or 0) * speed)
end

function Game3:logicStep(dt)
  Input:reconcile()
  Input:step()
  if Input.softResetStep and Input:softResetStep() then
    Input:reset()
    TouchControls:reset()
    self:softResetToBoot()
    return
  end
  if self.waitingCry and not self:cryPlaying() then
    self.waitingCry = nil
    self:endScriptWait()
  end
  if self.waitingSe and not self:sePlaying() then
    self.waitingSe = nil
    self:endScriptWait()
  end
  if self.waitingFanfare then
    self:stepFanfareWait(dt)
  end
  if self.phase == "boot" then
    self:stepBoot(dt)
    return
  end
  -- OPTION ZOOM/TILT land in stepField. Size the view after that so
  -- walkHeld's clamp (and this frame's draw) follow the new scale.
  if self.phase == "play" and Input:wasPressed("start")
      and self:tryAbortContestHall() then
    -- START leaves LinkContestRoom1. The pause menu is eaten while a
    -- waitmovement / startcontest field is up.
  elseif self.phase == "play" and self.field then
    self:stepField()
  elseif self.phase == "play" and self:decorPlacingActive() then
    -- The placing-decoration avatar mode owns the controls: the map is
    -- live but the player does not walk, a cursor does.
    self:stepDecorPlacing()
  elseif Input:wasPressed("start") and self.phase == "play" then
    -- START must never sit under a stuck FADE_TO_BLACK veil.
    self:fadeInFromBlack()
    self.field = { kind = "menu", cursor = 0 }
  elseif Input:wasPressed("select") and self.phase == "play"
      and (self.walkCooldown or 0) <= 0 then
    self:useRegisteredItem()
  elseif Input:wasPressed("a") and self.phase == "play" then
    -- TryStartInteractionScript runs before TrySetupDiveDownScript, so a sign
    -- or a person on the tile you face still wins over diving.
    if not self:tryTalk() then self:tryDiveDown() end
  elseif Input:wasPressed("b") and self.phase == "play"
      and self:tryDiveEmerge() then
    -- handled: B is what surfaces you, not A
  elseif Input:wasPressed("b") and self.phase == "roster" then
    self.phase = "boot"
    self:resetBoot()
  elseif Input:wasPressed("up") then
    self:moveScroll(-1)
  elseif Input:wasPressed("down") then
    self:moveScroll(1)
  end
  if (self.phase == "play" or self.phase == "battle_transition") and self.map then
    self:syncWorldView()
    self:clampCamera()
    self:stepWeatherFx()
  end
  self:walkHeld(dt)
  self:releaseHeldFade()
end

local function letterbox(g, w, h)
  return g:frameScale(w, h)
end

function Game3:drawFallbackMap()
  local G = love.graphics
  local map = self.map
  local x0, y0, x1, y1 = self:visibleRange()
  if not x0 then return end
  for y = y0, y1 do
    for x = x0, x1 do
      if Game3.walkable(map, x, y) then
        G.setColor(0.45, 0.72, 0.38, 1)
      else
        G.setColor(0.22, 0.28, 0.22, 1)
      end
      G.rectangle("fill", x * Game3.TILE, y * Game3.TILE,
        Game3.TILE, Game3.TILE)
    end
  end
end

function Game3:visibleRange(map, originX, originY)
  map = map or self.map
  originX, originY = originX or 0, originY or 0
  local w, h = map.width or 0, map.height or 0
  local vw, vh = self:viewSize()
  local x0 = math.floor(self.camX / Game3.TILE) - originX
  local y0 = math.floor(self.camY / Game3.TILE) - originY
  local x1 = math.floor((self.camX + vw) / Game3.TILE) - originX
  local y1 = math.floor((self.camY + vh) / Game3.TILE) - originY
  x0 = math.max(0, x0)
  y0 = math.max(0, y0)
  x1 = math.min(w - 1, x1)
  y1 = math.min(h - 1, y1)
  if w < 1 or h < 1 or x1 < x0 or y1 < y0 then return nil end
  return x0, y0, x1, y1
end

local function npcKey(map)
  return map and (map.id or map)
end

function Game3:npcsFor(map)
  map = map or self.map
  if not map then return nil end
  local byMap = self.npcByMap
  if not byMap then return nil end
  return byMap[npcKey(map)]
end

function Game3:objectEventHidden(o)
  if not o then return true end
  local flagged = o.flagId and o.flagId ~= 0
    and self.flags and self.flags[o.flagId]
  -- TrySpawnObjectEvent skips any template whose flag is set. Beaten
  -- route trainers still stand because their defeat bit is 0x500+id,
  -- not ObjectEventTemplate.flagId. FLAG_HIDE_* (0x2BC..) on a trainer
  -- is a story spawn, so those stay off the map until a script clears.
  local fid = o.flagId or 0
  local storyHide = fid >= Game3.FLAG_HIDE_BIRCH_STARTERS_BAG
    and fid < Game3.TRAINER_FLAG_START
  local hidden = flagged and ((o.trainerType or 0) == 0 or storyHide)
  local bagGone = (o.graphicsId or 0) == Game3.GFX_BIRCHS_BAG
    and self.flags and (self.flags[Game3.FLAG_HIDE_BIRCH_STARTERS_BAG]
      or self.flags[Game3.FLAG_SYS_POKEMON_GET])
  return hidden or bagGone
end

function Game3:resetNpcs(map)
  map = map or self.map
  if not map then return end
  if not self.npcByMap then self.npcByMap = {} end
  local list = {}
  local objects = map.objects or {}
  for i = 1, #objects do
    local o = objects[i]
    if o and not self:objectEventHidden(o) then
      local npc = self:npcFromTemplate(o, i)
      self:updateNpcZCoord(npc, map)
      list[#list + 1] = npc
    end
  end
  self.npcByMap[npcKey(map)] = list
end

-- Keep live neighbor NPCs across a connection; only hide/show from flags.
function Game3:applyNpcFlags(map)
  map = map or self.map
  local list = self:npcsFor(map)
  if not list then
    self:resetNpcs(map)
    return
  end
  local objects = map.objects or {}
  local have = {}
  for i = 1, #list do
    local npc = list[i]
    if npc and npc.templateIndex then
      have[npc.templateIndex] = npc
      local o = objects[npc.templateIndex]
      npc.hidden = (not o or self:objectEventHidden(o)) or nil
    end
  end
  for i = 1, #objects do
    local o = objects[i]
    if o and not self:objectEventHidden(o) and not have[i] then
      local npc = self:npcFromTemplate(o, i)
      self:updateNpcZCoord(npc, map)
      list[#list + 1] = npc
    end
  end
end

function Game3:warmNpcSprites(map)
  local list = self:npcsFor(map)
  if not list then return end
  local sprites = self.data and self.data.sprites
  for i = 1, #list do
    local npc = list[i]
    if npc and not npc.hidden then
      local spec = Game3.spriteSpec(sprites, npc.graphicsId)
      if spec and spec.path then self:grabImage(spec.path) end
    end
  end
end

function Game3:warmConnectedMaps(map)
  map = map or self.map
  self:eachConnectedMap(map, function(dest)
    self:layersFor(dest.tileset)
    if not self:npcsFor(dest) then
      self:resetNpcs(dest)
    else
      self:applyNpcFlags(dest)
    end
    self:warmNpcSprites(dest)
  end)
end

function Game3:npcAt(map, x, y)
  local npcs = self:npcsFor(map)
  if npcs then
    for i = 1, #npcs do
      local n = npcs[i]
      if n and not n.hidden and n.x == x and n.y == y then
        return n
      end
    end
    return nil
  end
  return Game3.objectAt(map, x, y)
end

function Game3:npcInRange(npc, x, y)
  local rx, ry = npc.rangeX or 0, npc.rangeY or 0
  if Game3.wanderDirs(npc.movementType) ~= nil then
    if rx < 1 then rx = 1 end
    if ry < 1 then ry = 1 end
  end
  return math.abs(x - npc.homeX) <= rx and math.abs(y - npc.homeY) <= ry
end

function Game3:npcVisual(npc)
  local x, y = npc.x, npc.y
  if (npc.cooldown or 0) > 0 then
    local dur = npc.walkDuration or Game3.WALK_PERIOD
    if dur <= 0 then dur = Game3.WALK_PERIOD end
    local t = 1 - npc.cooldown / dur
    if t < 0 then t = 0 elseif t > 1 then t = 1 end
    x = npc.fromX + (npc.x - npc.fromX) * t
    y = npc.fromY + (npc.y - npc.fromY) * t
  end
  return x, y
end

local function roll(n)
  n = n or 1
  if love and love.math and love.math.random then
    return love.math.random(n)
  end
  return math.random(n)
end

function Game3:tryNpcWalk(npc, map, dx, dy)
  if not (npc and map) then return false end
  if npc.talkLock or npc.invisible then return false end
  if not npc.facingLocked then
    npc.facing = Game3.facingFromDelta(dx, dy)
  end
  local nx, ny = npc.x + dx, npc.y + dy
  if not Game3.walkable(map, nx, ny) then return false end
  -- Water is collision 0 (Surf steps on it). Land wanderers would otherwise
  -- walk onto ponds and the ocean; Route 110 cyclists (elevation 4) left
  -- the cycling road. Swimmers spawn on surfable tiles and stay there.
  local srcB = self:behaviorAt(map, npc.x, npc.y)
  local dstB = self:behaviorAt(map, nx, ny)
  if Game3.isSurfable(srcB) ~= Game3.isSurfable(dstB) then return false end
  local i = self:gridIndex(map, nx, ny)
  if i and Game3.zMismatch(npc.elevation or 0, Game3.elevationOf(map.grid[i])) then
    return false
  end
  -- canStep blocks elevation 1 without Surf. Object elevation 0 skips
  -- zMismatch, so land NPCs would still stroll the shallows.
  if i and not Game3.isSurfable(srcB)
      and Game3.elevationOf(map.grid[i]) == 1 then
    return false
  end
  if Game3.warpAt(map, nx, ny) then return false end
  if nx == self.playerX and ny == self.playerY then return false end
  if self:npcAt(map, nx, ny) then return false end
  if not self:npcInRange(npc, nx, ny) then return false end
  npc.fromX, npc.fromY = npc.x, npc.y
  npc.x, npc.y = nx, ny
  npc.walkDuration = Game3.WALK_PERIOD
  npc.cooldown = Game3.WALK_PERIOD
  self:updateNpcZCoord(npc, map)
  self:beginGrassRustle(nx, ny)
  return true
end

function Game3:stepNpcSequence(npc, map)
  local seq = Game3.WALK_SEQUENCES[npc.movementType]
  if not seq then return end
  npc.seqI = npc.seqI or 0
  for _ = 1, 4 do
    local dir = seq[(npc.seqI % 4) + 1]
    local dx, dy = Game3.deltaFromFacing(dir)
    if self:tryNpcWalk(npc, map, dx, dy) then
      return
    end
    npc.seqI = npc.seqI + 1
  end
  npc.wait = 0.4
end

-- ObjectEventIsTrainerAndCloseToPlayer: only while dashing, NORMAL or
-- BURIED, Chebyshev box of trainerRange (inclusive).
function Game3:trainerCloseAndDashing(npc)
  if not self.running then return false end
  if not npc then return false end
  local tt = npc.trainerType or 0
  if tt ~= Game3.TRAINER_TYPE_NORMAL and tt ~= Game3.TRAINER_TYPE_BURIED then
    return false
  end
  local range = npc.trainerRange or 0
  local dx = (self.playerX or 0) - (npc.x or 0)
  local dy = (self.playerY or 0) - (npc.y or 0)
  if dx < 0 then dx = -dx end
  if dy < 0 then dy = -dy end
  return dx <= range and dy <= range
end

-- FACE_DOWN_AND_* / FACE_LEFT_AND_RIGHT / … : stay put, pick a facing
-- from the table (or limited-vector toward a dashing player).
function Game3:stepNpcFaceLook(npc)
  local spec = Game3.FACE_LOOK[npc.movementType]
  if not spec then return end
  local dir
  if self:trainerCloseAndDashing(npc) then
    dir = Game3.limitedVectorDir(
      spec.vec,
      (self.playerX or 0) - npc.x,
      (self.playerY or 0) - npc.y)
  end
  if not dir then
    local dirs = spec.dirs
    dir = dirs[self:rand(#dirs)]
  end
  if not npc.facingLocked then
    npc.facing = dir
  end
  local delays = Game3.MOVEMENT_DELAYS_MEDIUM
  npc.wait = delays[self:rand(#delays)]
end

function Game3:stepNpcs(dt)
  local map = self.map
  local npcs = self:npcsFor(map)
  if not npcs then return end
  for i = 1, #npcs do
    local npc = npcs[i]
    if npc and not npc.hidden and not npc.invisible then
      if (npc.cooldown or 0) > 0 then
        npc.cooldown = npc.cooldown - dt
      elseif npc.talkLock then
        -- Frozen for dialogue: keep facing the player.
      else
        local mode = Game3.wanderDirs(npc.movementType)
        if mode == "place" then
          npc.placeT = (npc.placeT or 0) + dt
        else
          npc.wait = (npc.wait or 0) - dt
          local ready = npc.wait <= 0
          if not ready and mode == "face_look" and self:trainerCloseAndDashing(npc) then
            ready = true
          end
          if ready then
            if mode == "seq" then
              self:stepNpcSequence(npc, map)
              npc.wait = 0
            elseif mode == "rotate_cw" or mode == "rotate_ccw" then
              npc.facing = Game3.nextRotateFacing(npc.facing, mode == "rotate_cw")
              npc.wait = Game3.ROTATE_NPC_DELAY
            elseif mode == "face_look" then
              self:stepNpcFaceLook(npc)
            else
              npc.wait = 0.5 + roll(12) / 10
              if mode == "look" then
                if not npc.facingLocked then
                  local dirs = { "north", "south", "west", "east" }
                  npc.facing = dirs[roll(4)]
                end
              elseif type(mode) == "table" then
                local dir = mode[roll(#mode)]
                local dx, dy = Game3.deltaFromFacing(dir)
                self:tryNpcWalk(npc, map, dx, dy)
              end
            end
          end
        end
      end
    end
  end
end

function Game3:spriteImage(graphicsId)
  local spec = Game3.spriteSpec(self.data.sprites, graphicsId)
  if not spec then return nil end
  local cached = self.spriteCache[graphicsId]
  if cached ~= nil then return cached or nil end
  local img = self:grabImage(spec.path)
  self.spriteCache[graphicsId] = img or false
  return img
end

function Game3:owQuad(spec, image, frame)
  local w, h = spec.width or Game3.TILE, spec.height or Game3.TILE
  local sw, sh = w, h
  if image and image.getDimensions then
    sw, sh = image:getDimensions()
  end
  frame = frame or 0
  local key = "ow:" .. (spec.id or spec.path or "") .. ":" .. frame .. ":" .. sw
  local q = self.quads[key]
  if not q then
    q = love.graphics.newQuad(frame * w, 0, w, h, sw, sh)
    self.quads[key] = q
  end
  return q
end

function Game3:drawOwSprite(graphicsId, tileX, tileY, facing, moving, t, lift, reflect, frameOverride)
  local spec = Game3.spriteSpec(self.data.sprites, graphicsId)
  local img = spec and self:spriteImage(graphicsId)
  if not img then return false end
  local pose = Game3.poseFor(spec, facing, moving, t)
  local px, py = Game3.spriteDrawPos(tileX, tileY, spec.width, spec.height, lift)
  local flip = pose.flip and true or false
  local frame = frameOverride
  if frame == nil then frame = pose.frame or 0 end
  local G = love.graphics
  local quad = self:owQuad(spec, img, frame)
  local w = spec.width or Game3.TILE
  local h = spec.height or Game3.TILE
  if reflect then
    G.setColor(1, 1, 1, 0.35)
    local sx = flip and -1 or 1
    local ox = flip and w or 0
    G.draw(img, quad, px + ox, Game3.reflectionDrawY(py, h), 0, sx, -1)
    G.setColor(1, 1, 1, 1)
    return true
  end
  G.setColor(1, 1, 1, 1)
  if flip then
    G.draw(img, quad, px + w, py, 0, -1, 1)
  else
    G.draw(img, quad, px, py)
  end
  return true
end

function Game3:actorReflects(tileX, tileY, hide, spriteH, map, spriteW, fromX, fromY)
  if hide then return false end
  map = map or self.map
  if not map then return false end
  -- ObjectEventCheckForReflectiveSurface: ceil(size/16) tiles SOUTH of
  -- current and previous coords (event_object_movement.c). The flipped
  -- sprite is drawn there, so a pond to the north must not mirror onto
  -- dry ground (Oldale path south of the Center pond).
  local height = math.floor(((spriteH or (Game3.TILE * 2)) + 8) / 16)
  local width = math.floor(((spriteW or Game3.TILE) + 8) / 16)
  if height < 1 then height = 1 end
  if width < 1 then width = 1 end
  local function column(x, y)
    x = math.floor(tonumber(x) or 0)
    y = math.floor(tonumber(y) or 0)
    for i = 0, height - 1 do
      local ty = y + 1 + i
      if Game3.isReflective(self:behaviorAt(map, x, ty)) then return true end
      for j = 1, width - 1 do
        if Game3.isReflective(self:behaviorAt(map, x + j, ty)) then return true end
        if Game3.isReflective(self:behaviorAt(map, x - j, ty)) then return true end
      end
    end
    return false
  end
  if column(tileX, tileY) then return true end
  if fromX ~= nil and fromY ~= nil then
    if column(fromX, fromY) then return true end
  end
  return false
end

function Game3:markTilesDirty()
  self.tileWindows = {}
  self.borderFillCache = nil
  self.voidPaletteCache = nil
  self.connectedLayoutCache = nil
end

-- fieldmap.c GetBorderBlockAt: 2x2 wrap. 1-based index into map.border.
function Game3.borderIndex(x, y)
  return ((x + 1) % 2) + ((y + 1) % 2) * 2 + 1
end

-- The border cell a baked 32x32 fill texture should put in its own 0/1 cell
-- (bx, by). drawWrapTileFill wrap-tiles that texture with the viewport origin
-- at world pixels, so bx/by stand for WORLD tile parity -- while borderIndex
-- is GetBorderBlockAt, which wants MapGrid coords (they include MAP_OFFSET).
-- Passing bx/by raw transposed the 2x2 diagonally and every border tree came
-- out with its quadrants swapped.
function Game3.borderBakeCell(cells, bx, by)
  if type(cells) ~= "table" then return 0 end
  return cells[Game3.borderIndex(bx + Game3.MAP_OFFSET,
    by + Game3.MAP_OFFSET)] or 0
end

function Game3.borderCell(map, x, y)
  local b = map and map.border
  if type(b) ~= "table" then return nil end
  return b[Game3.borderIndex(x, y)]
end

function Game3:tileBatch(image)
  if not image or not love.graphics.newSpriteBatch then return nil end
  self.tileBatches = self.tileBatches or {}
  local batch = self.tileBatches[image]
  if not batch then
    local ok, made = pcall(love.graphics.newSpriteBatch, image, 1024, "stream")
    if not ok or not made then return nil end
    batch = made
    self.tileBatches[image] = batch
  end
  return batch
end

function Game3:blitMetatile(image, mid, px, py, mode, batch)
  local G = love.graphics
  if not mode or mode == "full" then
    local quad = self:quadFor(mid, image)
    if batch then
      batch:add(quad, px, py)
    else
      G.draw(image, quad, px, py)
    end
    return
  end
  local i0, i1 = 0, 1
  if mode == "bottom8" then i0, i1 = 2, 3 end
  for i = i0, i1 do
    local q = self:quadFor8(mid, i, image)
    local ox = (i % 2) * 8
    local oy = math.floor(i / 2) * 8
    if batch then
      batch:add(q, px + ox, py + oy)
    else
      G.draw(image, q, px + ox, py + oy)
    end
  end
end

-- Remaining rectangles after punching `holes` out of [x0,y0,x1,y1].
-- Overlay/covered border fill uses this so tree-top tiles stay in the
-- void, not on top of the town (BG1 is transparent on paths).
function Game3.splitAround(r, hx0, hy0, hx1, hy1, out)
  local x0, y0, x1, y1 = r[1], r[2], r[3], r[4]
  local ix0 = x0 > hx0 and x0 or hx0
  local iy0 = y0 > hy0 and y0 or hy0
  local ix1 = x1 < hx1 and x1 or hx1
  local iy1 = y1 < hy1 and y1 or hy1
  if ix0 >= ix1 or iy0 >= iy1 then
    out[#out + 1] = r
    return
  end
  if y0 < iy0 then out[#out + 1] = { x0, y0, x1, iy0 } end
  if iy1 < y1 then out[#out + 1] = { x0, iy1, x1, y1 } end
  if x0 < ix0 then out[#out + 1] = { x0, iy0, ix0, iy1 } end
  if ix1 < x1 then out[#out + 1] = { ix1, iy0, x1, iy1 } end
end

function Game3.punchHoles(x0, y0, x1, y1, holes)
  local rects = { { x0, y0, x1, y1 } }
  if type(holes) ~= "table" or x1 <= x0 or y1 <= y0 then return rects end
  for i = 1, #holes do
    local h = holes[i]
    if h then
      local next = {}
      for j = 1, #rects do
        Game3.splitAround(rects[j], h[1], h[2], h[3], h[4], next)
      end
      rects = next
    end
  end
  return rects
end

function Game3:mapCoverRects(map)
  map = map or self.map
  local holes = {}
  if not map then return holes end
  local t = Game3.TILE
  holes[1] = { 0, 0, (map.width or 0) * t, (map.height or 0) * t }
  self:eachConnectedMap(map, function(dest, ox, oy)
    holes[#holes + 1] = {
      ox * t, oy * t,
      (ox + (dest.width or 0)) * t,
      (oy + (dest.height or 0)) * t,
    }
  end)
  return holes
end

function Game3.intersectRect(a, b)
  if not (a and b) then return nil end
  local x0 = a[1] > b[1] and a[1] or b[1]
  local y0 = a[2] > b[2] and a[2] or b[2]
  local x1 = a[3] < b[3] and a[3] or b[3]
  local y1 = a[4] < b[4] and a[4] or b[4]
  if x1 <= x0 or y1 <= y0 then return nil end
  return { x0, y0, x1, y1 }
end

function Game3.expandRect(r, pad)
  if not r then return nil end
  pad = pad or 0
  return { r[1] - pad, r[2] - pad, r[3] + pad, r[4] + pad }
end

-- GBA backup map is only MAP_OFFSET around the layout. Ocean routes still
-- store the general tileset tree wall as that 2x2; wrap-tiling it across
-- a survey zoom painted forest into the water void.
-- Whole trees: see borderPad. MAP_OFFSET stays 7 -- that is the cart's
-- backup-buffer size and other code depends on it -- this is only how far
-- the ring is painted.
Game3.BORDER_PAD_TILES = 8

function Game3:borderPad(map)
  map = map or self.map
  local t = map and (map.mapType or 0) or 0
  if t == Game3.MAP_TYPE_OCEAN_ROUTE or t == Game3.MAP_TYPE_UNDERWATER then
    return 0
  end
  -- GetBorderBlockAt answers for ANY off-map coordinate, so the cart's border
  -- is effectively infinite; MAP_OFFSET is only the size of the backup buffer,
  -- which is all a 240x160 screen ever needs.
  --
  -- BORDER_PAD_TILES is 8, not MAP_OFFSET's 7, because the border block is a
  -- 2x2 and its trees are two metatiles tall: an odd pad cuts the outermost
  -- row of trees in half. 8 finishes that fourth row.
  --
  -- This used to grow to cover the whole view, which is wrong on a tall phone:
  -- the pad reached 480..960px, and since the fill is a rect around the map it
  -- painted straight over the connected maps drawn beside it -- a route would
  -- change and its neighbours turned into flat border. Keep the hardware ring
  -- and let the camera clamp keep the view inside what is drawn.
  return Game3.BORDER_PAD_TILES * Game3.TILE
end

function Game3:borderFillRects(map, x0, y0, x1, y1, topPass, only)
  map = map or self.map
  local covers = self:mapCoverRects(map)
  local placements = self:mapPlacements(map)
  local view = { x0, y0, x1, y1 }
  local clips = {}
  local want = only and (only.id or only)
  local t = Game3.TILE
  for i = 1, #placements do
    local p = placements[i]
    local dest = p and p.map
    if dest and (not want or (dest.id or dest) == want) then
      local cover = {
        (p.ox or 0) * t, (p.oy or 0) * t,
        ((p.ox or 0) + (dest.width or 0)) * t,
        ((p.oy or 0) + (dest.height or 0)) * t,
      }
      local pad = self:borderPad(dest)
      local hit = Game3.intersectRect(view, Game3.expandRect(cover, pad))
      if hit then
        -- Punch the holes on both passes. The bottom pass used to take the
        -- raw rect, so border fill could be laid over a connected map that is
        -- itself drawn -- which is exactly what blanketed the neighbours.
        local parts = Game3.punchHoles(hit[1], hit[2], hit[3], hit[4], covers)
        for j = 1, #parts do
          clips[#clips + 1] = parts[j]
        end
      end
    end
  end
  return clips
end

-- What a metatile is for VOID FILL purposes: never pick a ledge lip,
-- fence, or cycling-road as the representative water/trees tile.
function Game3.voidFillKind(behavior, collision)
  local b = behavior or 0
  if Game3.ledgeDelta(b) then return "reject" end
  if b >= Game3.MB_IMPASSABLE_EAST and b <= Game3.MB_IMPASSABLE_SOUTHWEST then
    return "reject"
  end
  if b == Game3.MB_IMPASSABLE_SOUTH_AND_NORTH
      or b == Game3.MB_IMPASSABLE_WEST_AND_EAST then
    return "reject"
  end
  if b == Game3.MB_WARP_OR_BRIDGE or b == Game3.MB_FORTREE_BRIDGE then
    return "reject"
  end
  if b == Game3.MB_MUDDY_SLOPE then return "reject" end
  if Game3.isArrowWarp(b) then return "reject" end
  if b == Game3.MB_SAND or b == Game3.MB_UNUSED_DEEP_SAND then
    return "sand"
  end
  if Game3.isSurfable(b) then
    if Game3.isWaterfall(b) then return "reject" end
    if b == Game3.MB_SEAWEED
        or b == Game3.MB_SEAWEED_NO_SURFACING then return "reject" end
    return "water"
  end
  if Game3.isLandGrass(b) then return "grass" end
  if (collision or 0) == 0 then return "grass" end
  return "cover"
end

-- VOID FILL only paints the ground atlas. Skip metatiles whose layer type
-- is a cliff split or a fence/wall sandwich, and skip land tiles that carry
-- a BG1 canopy (tree tops floating in open water when the top pass ran).
function Game3:voidFillMetatileOk(map, mid, kind)
  if not map or not mid then return false end
  -- fieldmap.c GetBorderBlockAt wrap-tiles map.border beyond the edges, so
  -- whatever is in the border block is by definition what the cart shows
  -- out there. Never rank one of those out.
  local border = map.border
  if type(border) == "table" then
    for i = 1, #border do
      if Game3.metatileOf(border[i]) == mid then return true end
    end
  end
  local spec = self.data.tilesets and self.data.tilesets.byId
    and self.data.tilesets.byId[map.tileset]
  local layerType = spec and spec.layerType
  local lt = (type(layerType) == "table" and layerType[mid])
    or Game3.LAYER_NORMAL
  if lt == Game3.LAYER_COVERED or lt == Game3.LAYER_SPLIT then
    return false
  end
  -- Water needs the same BG1 test as land. Route 110's Seaside Cycling Road
  -- railings sit on water behaviour, so sampling water without it picked the
  -- railing metatile as "open water" and wrap-tiled a railing/water grid.
  local tiles = spec and spec.tiles
  if type(tiles) == "table" and type(tiles[mid]) == "table" then
    if not self:metatileTopEmpty(map, mid) then return false end
  end
  return true
end

function Game3:mapTerrainPresent(map, kind)
  if not (map and type(map.grid) == "table") then return false end
  local w, h = map.width or 0, map.height or 0
  if w < 1 or h < 1 then return false end
  for y = 0, h - 1 do
    for x = 0, w - 1 do
      local cell = map.grid[y * w + x + 1]
      local mid = Game3.metatileOf(cell)
      local b = self:behaviorAt(map, x, y)
      local k = Game3.voidFillKind(b, Game3.collisionOf(cell))
      if k == kind and self:voidFillMetatileOk(map, mid, kind) then
        return true
      end
    end
  end
  return false
end

-- VOID FILL: what fills the screen beyond the edges of the maps actually
-- drawn. The cart has no real answer for this. GetBorderBlockAt returns
-- the CURRENT map's 2x2 border block for any off-map coordinate, and a
-- 240x160 screen never shows more than a few tiles of it. This port draws
-- whole connected layouts on a tall phone at survey zoom, where two things
-- the hardware never has to cope with become obvious:
--
--   * every map answering for its own void meant 43 different fills across
--     136 outdoor maps, so one patch of sea changed texture -- to sand, to
--     a pink cliff slab, to a sand/water checkerboard -- as the layout
--     around the player changed, and
--   * a map's authored border block is EDGE art: a tree canopy, a cliff
--     lip, a beach run. Wrap-tiled past its own map it becomes rectangular
--     grids of treetops and half-drawn beaches sitting in open water.
--
-- So the void is one thing for the whole world instead of one per map.
-- Hoenn is an archipelago; past the drawn maps is sea. Metatile 368 is
-- gTileset_General's open-sea block and renders byte-identical in all 20
-- tileset pairs any outdoor map uses, so a single cell is right whichever
-- map's atlas happens to draw it. GRASS (metatile 1) is the same deal on
-- land, BLACK paints nothing, and PER-MAP restores the old per-map border
-- rings for comparison.
Game3.VOID_SEA_CELL = 368
Game3.VOID_GRASS_CELL = 1
Game3.VOID_FILLS = { "sea", "grass", "black", "map" }

-- Saves written before the void went global still hold the old names.
Game3.VOID_FILL_ALIASES = { fade = "sea", water = "sea", trees = "grass" }

function Game3.voidFillLabel(mode)
  mode = Game3.VOID_FILL_ALIASES[mode] or mode or "sea"
  if mode == "grass" then return "GRASS" end
  if mode == "black" then return "BLACK" end
  if mode == "map" then return "PER-MAP" end
  return "SEA"
end

function Game3:voidFillMode()
  local m = self.options and self.options.voidFill
  m = Game3.VOID_FILL_ALIASES[m] or m
  for i = 1, #Game3.VOID_FILLS do
    if Game3.VOID_FILLS[i] == m then return m end
  end
  return "sea"
end

-- The one 2x2 the entire void wrap-tiles, or nil for the two modes that
-- still work per map (BLACK draws nothing, PER-MAP goes through
-- voidFillCells for each placement).
function Game3.globalVoidCells(mode)
  local c
  if mode == "sea" then c = Game3.VOID_SEA_CELL
  elseif mode == "grass" then c = Game3.VOID_GRASS_CELL end
  if not c then return nil end
  return { c, c, c, c }
end

function Game3:mapPlacements(map)
  return self:connectedLayout(map)
end

-- One metatile of `kind` ("water" or "grass") from a tileset's own
-- behavior table, found once and cached by tileset id. nil (no
-- representative tile) lets callers drop to FADE, e.g. an indoor
-- tileset with no open water.
function Game3:tilesetRepresentativeTile(tilesetId, kind)
  if not tilesetId then return nil end
  self._voidFillTileCache = self._voidFillTileCache or {}
  local cache = self._voidFillTileCache
  local key = tostring(tilesetId) .. "|" .. kind
  local cached = cache[key]
  if cached ~= nil then return cached or nil end
  local spec = self.data.tilesets and self.data.tilesets.byId
    and self.data.tilesets.byId[tilesetId]
  local behavior = spec and spec.behavior
  local dummy = { tileset = tilesetId }
  local mid
  if type(behavior) == "table" then
    for cell = 0, 1023 do
      local b = behavior[cell]
      if b then
        local k = Game3.voidFillKind(b, 0)
        if kind == "water" and k == "water"
            and self:voidFillMetatileOk(dummy, cell, kind) then
          mid = cell
          break
        elseif kind == "sand" and k == "sand"
            and self:voidFillMetatileOk(dummy, cell, kind) then
          mid = cell
          break
        elseif kind == "grass" and k == "grass"
            and self:voidFillMetatileOk(dummy, cell, kind) then
          mid = cell
          break
        end
      end
    end
  end
  cache[key] = mid or false
  return mid
end

-- Up to two metatiles of `kind` actually painted on this map -- not just
-- any tile the tileset happens to define -- ranked by how often they
-- appear, sampled once and cached per map. Real GBA water is drawn with
-- two (or more) adjacent tile variants alternating in a checkerboard for
-- a "waves" look; wrap-tiling only tilesetRepresentativeTile's single
-- first match stamped the exact same tile everywhere, which reads as an
-- obviously synthetic grid once stretched across a wide survey-zoom view
-- instead of open water. Falls back to that single tileset-wide match
-- when the map has no grid to sample (e.g. a template map in a test).
function Game3:mapRepresentativeTiles(map, kind)
  if not map then return nil end
  self._voidFillMapTileCache = self._voidFillMapTileCache or {}
  local cache = self._voidFillMapTileCache
  local key = tostring(map.id or map) .. "|" .. kind
  local cached = cache[key]
  if cached ~= nil then return cached or nil end
  local counts, order = {}, {}
  local w, h = map.width or 0, map.height or 0
  if type(map.grid) == "table" and w > 0 and h > 0 then
    for y = 0, h - 1 do
      for x = 0, w - 1 do
        local cell = map.grid[y * w + x + 1]
        local mid = Game3.metatileOf(cell)
        local b = self:behaviorAt(map, x, y)
        local k = Game3.voidFillKind(b, Game3.collisionOf(cell))
        if ((kind == "water" and k == "water")
            or (kind == "sand" and k == "sand")
            or (kind == "grass" and k == "grass"))
            and self:voidFillMetatileOk(map, mid, kind) then
          if counts[mid] == nil then order[#order + 1] = mid end
          counts[mid] = (counts[mid] or 0) + 1
        end
      end
    end
  end
  table.sort(order, function(a, b) return counts[a] > counts[b] end)
  local result
  if order[1] and order[2] then
    result = { order[1], order[2] }
  elseif order[1] then
    result = { order[1], order[1] }
  else
    local mid = self:tilesetRepresentativeTile(map.tileset, kind)
    result = mid and { mid, mid } or nil
  end
  cache[key] = result or false
  return result
end

-- The 2x2 block to wrap-tile beyond `map`'s edges under PER-MAP ("black"
-- is handled by the caller and never reaches here). Always ONE metatile
-- repeated, and never the map's own border block. Two things used to come
-- out of here and both were artifacts:
--
--   * a sand/water or two-variant checkerboard, which at survey zoom reads
--     as a chequered grid stamped over the world rather than as scenery,
--     and
--   * map.border, which a safety check used to let through -- that is EDGE
--     art (tree canopy, cliff lip, beach run), so wrap-tiling it produced
--     rectangles of trees, and on the two top passes loose treetops,
--     sitting in open water.
--
-- What is left is one flat, walkable tile sampled from the map itself:
-- open water anywhere the map has water, plain ground inland.
function Game3:voidFillCells(map, mode)
  if not map then return nil end
  local function flat(kind)
    local pair = self:mapRepresentativeTiles(map, kind)
    return pair and pair[1] or nil
  end
  local oceanic = map.mapType == Game3.MAP_TYPE_OCEAN_ROUTE
    or map.mapType == Game3.MAP_TYPE_UNDERWATER
  local mid
  if mode == "water" or oceanic then
    mid = flat("water")
  elseif mode == "grass" or mode == "trees" then
    mid = flat("grass") or flat("sand") or flat("water")
  elseif self:mapTerrainPresent(map, "water") then
    -- A map that touches water at all sits on the coast, and what is past
    -- its edge is the same sea its neighbours fill with -- so water, not a
    -- sand halo around the shoreline.
    mid = flat("water")
  else
    mid = flat("grass") or flat("sand")
  end
  mid = mid or flat("water")
    or self:tilesetRepresentativeTile(map.tileset, "grass")
    or self:tilesetRepresentativeTile(map.tileset, "sand")
  if not mid then return nil end
  return { mid, mid, mid, mid }
end

-- Wrap-tiled 32x32 of each layout's own 2x2 border, under the map body.
-- Pad and tiles come from that map, so walking onto water does not strip
-- the town's tree ring or wallpaper the town's 2x2 over the river.
function Game3:drawBorderFill(_, map, topPass)
  map = map or self.map
  if not map then return end
  -- fieldmap.c GetBorderBlockAt answers from gMapHeader, so the cart shows
  -- exactly one border block: the map the player is on. This port draws a
  -- whole connected layout at once, and a map with no ring reads as
  -- unfinished next to one that has it -- a town like Littleroot has no
  -- trees of its own down either side, the frame IS the border block. So
  -- every placement paints its own ring, not just the current map.
  --
  -- Known consequence, asked for deliberately: where a map's ring reaches
  -- into open void beside a neighbour, it shows as a band of that map's
  -- trees against the fill. borderFillRects still clips the ring off any
  -- real map, so a ring never covers another map's ground.
  local G = love.graphics
  if not G.draw then return end
  local x = math.floor(self.camX or 0)
  local y = math.floor(self.camY or 0)
  local vw, vh = self:viewSize()
  local placements = self:mapPlacements(map)
  for i = 1, #placements do
    local dest = placements[i] and placements[i].map
    if dest and self:borderPad(dest) > 0 then
      local b = dest.border
      if type(b) == "table" and #b >= 4 then
        local bottom, top = self:layersFor(dest.tileset)
        local image = topPass and top or bottom
        local rects = self:borderFillRects(map, x, y, x + vw, y + vh,
          topPass, dest)
        self:drawWrapTileFill(image, dest.tileset, b,
          tostring(dest.id or dest) .. "|ring", topPass, rects)
      end
    end
  end
end

-- Bake `cells` (a 2x2 metatile block, tileset `tilesetId`) into a 32x32
-- wrap-tiled texture -- cached by `cacheKey` plus image/pass/flip, same
-- shape as the 2x2 GBA border ring this was pulled out of -- and draw it
-- across every rect in `rects` as one quad each. Shared by the close-in
-- border ring (drawBorderFill, cells = the map's own border) and the
-- outer void fill (drawVoidFill, cells = whatever VOID FILL mode picks),
-- so a fill of any size costs a handful of draw calls, never a per-tile
-- Lua loop over the visible area.
function Game3:drawWrapTileFill(image, tilesetId, cells, cacheKey, topPass, rects,
    staticBake)
  if not (image and cells and rects and #rects > 0) then return end
  local G = love.graphics
  local flip = (not staticBake) and self:tileAnimFlip() and true or false
  local pass = topPass or "bottom"
  local key = tostring(cacheKey) .. "|" .. tostring(image)
    .. "|" .. pass .. "|" .. tostring(flip)
    .. (staticBake and "|static" or "")
  self.borderFillCache = self.borderFillCache or {}
  local cache = self.borderFillCache
  local img = cache[key]
  if img == nil then
    img = false
    local PixelCanvas = require("src.render.PixelCanvas")
    local okCanvas, canvas = pcall(PixelCanvas.new, 32, 32, "nearest")
    if okCanvas and canvas and canvas.renderTo then
      canvas:renderTo(function()
        G.push()
        G.origin()
        G.setColor(1, 1, 1, 1)
        for by = 0, 1 do
          for bx = 0, 1 do
            local cell = Game3.borderBakeCell(cells, bx, by)
            local mid = Game3.metatileOf(cell)
            local dummy = { tileset = tilesetId, grid = { cell },
              width = 1, height = 1 }
            local mode = "full"
            if topPass then
              mode = Game3.metatileTopPassMode(
                self:layerTypeAt(dummy, 0, 0), topPass,
                self:topIsOverlayAt(dummy, 0, 0))
            end
            if mode ~= "skip" then
              local px, py = bx * Game3.TILE, by * Game3.TILE
              self:blitMetatile(image, mid, px, py, mode, nil)
              if not staticBake then
                self:drawAnimCorners(image, dummy, mid, px, py, topPass,
                  nil, self:behaviorAt(dummy, 0, 0), mode,
                  Game3.collisionOf(cell))
              end
            end
          end
        end
        G.pop()
      end)
      local okImg, made = pcall(function()
        return G.newImage(canvas:newImageData())
      end)
      img = (okImg and made) or canvas
      if img.setWrap then img:setWrap("repeat", "repeat") end
      if img.setFilter then img:setFilter("nearest", "nearest") end
    end
    cache[key] = img
  end
  if not img then return end
  G.setColor(1, 1, 1, 1)
  local q = self.borderFillQuad
  for i = 1, #rects do
    local r = rects[i]
    local rw, rh = r[3] - r[1], r[4] - r[2]
    if rw > 0 and rh > 0 then
      if q and q.setViewport then
        q:setViewport(r[1], r[2], rw, rh, 32, 32)
      elseif G.newQuad then
        q = G.newQuad(r[1], r[2], rw, rh, 32, 32)
        self.borderFillQuad = q
      end
      if q then G.draw(img, q, r[1], r[2]) end
    end
  end
end

-- Beyond every real map: one wrap-tiled block per placement (Gen 1/2's
-- BorderFill idea, generalized to Ruby's several-simultaneous-neighbors
-- layout -- see voidFillCells for what the block is). Drawn under the
-- map + connections, same order as the GBA ring above, so real tiles
-- simply paint over it. Cost is O(placements) -- typically 2-6 -- a
-- handful of wrap-tiled quads, never a per-tile loop over the visible
-- area, so it stays flat regardless of how far survey zoom pulls out.
function Game3:drawVoidFill(which)
  if which ~= "bottom" then return end
  local map = self.map
  if not map or Game3.isIndoorFillMap(map) then return end
  local mode = self:voidFillMode()
  if mode == "black" then return end
  local G = love.graphics
  if not (G and G.draw) then return end
  local x = math.floor(self.camX or 0)
  local y = math.floor(self.camY or 0)
  local vw, vh = self:viewSize()
  if (vw or 0) < 1 or (vh or 0) < 1 then return end
  local view = { x, y, x + vw, y + vh }
  local global = Game3.globalVoidCells(mode)
  if global then
    -- One wrap-tiled quad for the whole view. Nothing here depends on the
    -- map the player happens to be standing on, so nothing here changes
    -- when they walk into the next one.
    local image = self:layersFor(map.tileset)
    if image then
      self:drawWrapTileFill(image, map.tileset, global,
        "global|void|" .. mode, nil, { view }, true)
    end
    return
  end
  local placements = self:mapPlacements(map)
  local t = Game3.TILE
  -- Generous enough to always reach past the edge of the view even at
  -- the deepest survey zoom; a wrap-tiled quad costs the same whether
  -- it is 2 tiles wide or 200, so there is no reason to pinch this.
  local pad = math.max(vw, vh, Game3.SCREEN_W, Game3.SCREEN_H) * 2
  for i = 1, #placements do
    local p = placements[i]
    local dest = p and p.map
    if dest then
      local cover = {
        (p.ox or 0) * t, (p.oy or 0) * t,
        ((p.ox or 0) + (dest.width or 0)) * t,
        ((p.oy or 0) + (dest.height or 0)) * t,
      }
      local hit = Game3.intersectRect(view, Game3.expandRect(cover, pad))
      if hit then
        local cells = self:voidFillCells(dest, mode)
        if cells then
          local bottom = self:layersFor(dest.tileset)
          local image = bottom
          if image then
            self:drawWrapTileFill(image, dest.tileset, cells,
              tostring(dest.id or dest) .. "|void|" .. mode,
              nil, { hit }, true)
          end
        end
      end
    end
  end
end

function Game3:fillLayer(image, map, x0, y0, x1, y1, topPass, batch)
  local w = map.width or 0
  local h = map.height or 0
  for y = y0, y1 do
    for x = x0, x1 do
      if x >= 0 and y >= 0 and x < w and y < h then
        local mode = "full"
        if topPass then
          mode = Game3.metatileTopPassMode(
            self:layerTypeAt(map, x, y), topPass,
            self:topIsOverlayAt(map, x, y))
        end
        if mode ~= "skip" then
          local cell = map.grid[y * w + x + 1]
          local mid = Game3.metatileOf(cell)
          local px = x * Game3.TILE
          local py = y * Game3.TILE
          local behavior = self:behaviorAt(map, x, y)
          self:blitMetatile(image, mid, px, py, mode, batch)
          self:drawAnimCorners(image, map, mid, px, py, topPass, batch,
            behavior, mode, Game3.collisionOf(cell))
        end
      end
    end
  end
end

-- The ground layer is the only thing in the world draw that goes through a
-- SpriteBatch; VOID FILL and the border fill bake with immediate G.draw. On a
-- driver where batch draws land nowhere that shows up as a blank map with the
-- fill still painting -- the map vanishes and nothing errors. Probe it once:
-- draw a one-quad batch into a 1x1 canvas and read the pixel back. Anything
-- unavailable or throwing counts as usable, so this only ever turns the batch
-- path off on a machine that demonstrably cannot draw one.
function Game3:spriteBatchUsable()
  if self._spriteBatchOk ~= nil then return self._spriteBatchOk end
  self._spriteBatchOk = true
  local G = love.graphics
  if not (G and G.newSpriteBatch and G.newImage and G.newQuad) then
    return true
  end
  local ok, result = pcall(function()
    local PixelCanvas = require("src.render.PixelCanvas")
    local canvas = PixelCanvas.new(1, 1, "nearest")
    if not (canvas and canvas.renderTo and canvas.newImageData) then return nil end
    local data = love.image and love.image.newImageData
      and love.image.newImageData(1, 1)
    if not data then return nil end
    data:setPixel(0, 0, 1, 1, 1, 1)
    local image = G.newImage(data)
    local batch = G.newSpriteBatch(image, 1, "dynamic")
    batch:add(G.newQuad(0, 0, 1, 1, 1, 1), 0, 0)
    canvas:renderTo(function()
      G.push()
      G.origin()
      G.setColor(1, 1, 1, 1)
      G.clear(0, 0, 0, 0)
      G.draw(batch)
      G.pop()
    end)
    local _, _, _, a = canvas:newImageData():getPixel(0, 0)
    return a
  end)
  if ok and type(result) == "number" and result <= 0 then
    self._spriteBatchOk = false
    local okLog, Logger = pcall(require, "src.core.Logger")
    if okLog and Logger and Logger.warn then
      Logger.warn("SpriteBatch draws nothing; painting map tiles directly")
    end
  end
  return self._spriteBatchOk
end

function Game3:tileWindow(image, map, x0, y0, x1, y1, topPass)
  local G = love.graphics
  if not (G and G.newSpriteBatch) or not self:spriteBatchUsable() then
    self:fillLayer(image, map, x0, y0, x1, y1, topPass, nil)
    return nil
  end
  local w = map.width or 0
  local h = map.height or 0
  local flip = self:tileAnimFlip() and true or false
  local key = tostring(map.id or map) .. "|" .. tostring(image)
    .. "|" .. tostring(topPass or "bottom")
    .. "|" .. tostring(self._tilesetFrame or 0)
  self.tileWindows = self.tileWindows or {}
  local win = self.tileWindows[key]
  if win and win.flip == flip
      and x0 >= win.x0 and y0 >= win.y0
      and x1 <= win.x1 and y1 <= win.y1 then
    return win.batch
  end
  local mx0 = math.max(0, x0 - Game3.TILE_WINDOW_MARGIN)
  local my0 = math.max(0, y0 - Game3.TILE_WINDOW_MARGIN)
  local mx1 = math.min(w - 1, x1 + Game3.TILE_WINDOW_MARGIN)
  local my1 = math.min(h - 1, y1 + Game3.TILE_WINDOW_MARGIN)
  local batch = win and win.batch
  if not batch then
    local ok, made = pcall(G.newSpriteBatch, image, 2048, "dynamic")
    if not ok or not made then
      self:fillLayer(image, map, x0, y0, x1, y1, topPass, nil)
      return nil
    end
    batch = made
  end
  if batch.clear then batch:clear() end
  self:fillLayer(image, map, mx0, my0, mx1, my1, topPass, batch)
  -- A ground pass covers every cell in the window, so an empty batch means
  -- the quads never landed. Painting the window directly is slower but keeps
  -- the world on screen instead of leaving VOID FILL (or bare background)
  -- showing through where the map should be. Top passes legitimately come
  -- back empty when every cell skips, so they are left alone.
  if not topPass and mx1 >= mx0 and my1 >= my0
      and batch.getCount and batch:getCount() == 0 then
    self:fillLayer(image, map, x0, y0, x1, y1, topPass, nil)
    self.tileWindows[key] = nil
    return nil
  end
  self.tileWindows[key] = {
    batch = batch, x0 = mx0, y0 = my0, x1 = mx1, y1 = my1, flip = flip,
  }
  return batch
end

function Game3:drawLayer(image, map, x0, y0, x1, y1, originX, originY, topPass)
  if not image or not map or x0 == nil then return end
  originX, originY = originX or 0, originY or 0
  local G = love.graphics
  G.setColor(1, 1, 1, 1)
  local dx, dy = originX * Game3.TILE, originY * Game3.TILE
  local shifted = dx ~= 0 or dy ~= 0
  if shifted then
    G.push()
    G.translate(dx, dy)
  end
  local batch = self:tileWindow(image, map, x0, y0, x1, y1, topPass)
  if batch then G.draw(batch) end
  -- pokeruby DrawMetatile COVERED: after BG3, paint BG2 before sprites.
  -- A later covered pass can skip these if layerTop was nil at load.
  if not topPass then
    local ground = self:layersFor(map.tileset)
    if image == ground then
      self:drawCoveredTops(map, x0, y0, x1, y1, 0, 0)
    end
  end
  if shifted then G.pop() end
end

-- General picket fence / house walls (Route 111 Winstrate, etc.): dirt on
-- the bottom four tiles, fence on the top four, LAYER_COVERED. Painting
-- them here with the ground atlas's neighbor (the top PNG) keeps the
-- collision visible even when the overlay pass never runs.
function Game3:drawCoveredTops(map, x0, y0, x1, y1, originX, originY)
  if not map or x0 == nil then return end
  local bottom, top = self:layersFor(map.tileset)
  if not top or top == bottom then return end
  originX, originY = originX or 0, originY or 0
  local w = map.width or 0
  local h = map.height or 0
  local G = love.graphics
  local batch = self:tileBatch(top)
  if batch and batch.clear then batch:clear() end
  G.setColor(1, 1, 1, 1)
  for y = y0, y1 do
    for x = x0, x1 do
      if x >= 0 and y >= 0 and x < w and y < h then
        if self:layerTypeAt(map, x, y) == Game3.LAYER_COVERED then
          local mid = Game3.metatileOf(map.grid[y * w + x + 1])
          local px = (originX + x) * Game3.TILE
          local py = (originY + y) * Game3.TILE
          self:blitMetatile(top, mid, px, py, "full", batch)
        end
      end
    end
  end
  if batch then G.draw(batch) end
end

function Game3:drawConnections(which, topPass)
  local map = self.map
  if not map then return end
  self:eachConnectedMap(map, function(dest, ox, oy)
    if dest.grid then
      local x0, y0, x1, y1 = self:visibleRange(dest, ox, oy)
      if x0 then
        local bottom, top = self:layersFor(dest.tileset)
        local image = which == "top" and top or bottom
        self:drawLayer(image, dest, x0, y0, x1, y1, ox, oy, topPass)
      end
    end
  end)
end

function Game3.drawOrderLess(a, b)
  local sa, sb = a.sub, b.sub
  if sa or sb then
    sa = sa or Game3.DEFAULT_OBJ_SUBPRIORITY
    sb = sb or Game3.DEFAULT_OBJ_SUBPRIORITY
    if sa ~= sb then return sa > sb end
  end
  if a.y ~= b.y then return a.y < b.y end
  if a.x ~= b.x then return a.x < b.x end
  return false
end

function Game3:drawOneObject(o, npcs, originX, originY, map)
  local G = love.graphics
  local gid = self:resolveGraphicsId(o.graphicsId or 0)
  local spec = self:objectSpriteSpec(o, gid)
  local w = spec and spec.width or Game3.TILE
  local h = spec and spec.height or Game3.TILE
  local vx, vy = o.x, o.y
  local moving, t = false, 1
  if npcs then
    vx, vy = self:npcVisual(o)
    moving = ((o.cooldown or 0) > 0 or Game3.wanderDirs(o.movementType) == "place")
      and not o.lockAnim
    if moving and (o.cooldown or 0) > 0 then
      local dur = o.walkDuration or Game3.WALK_PERIOD
      if dur <= 0 then dur = Game3.WALK_PERIOD end
      t = 1 - o.cooldown / dur
    elseif moving then
      t = (o.placeT or 0) % 0.5 / 0.5
    end
  end
  local reflect = self:actorReflects(o.x, o.y, o.hideReflection, h, map, w,
    o.fromX, o.fromY)
  originX, originY = originX or 0, originY or 0
  vx = vx + originX
  vy = vy + originY
  local lift = o.levitate or 0
  local px, py = Game3.spriteDrawPos(vx, vy, w, h, lift)
  -- sub_805BD90 sprite x2/y2 (truck box bob / settle).
  px = px + (o.spriteX2 or 0)
  py = py + (o.spriteY2 or 0)
  local camX, camY = self.camX, self.camY
  local extra = reflect and h or 0
  local vw, vh = self:viewSize()
  if px + w < camX or px > camX + vw
      or py + h + extra < camY or py > camY + vh then
    return
  end
  local facing = o.facing or Game3.facingFromMovementType(o.movementType)
  local frameOverride = o.animFrame
  if o.berryStage and o.berryStage > 0 then
    frameOverride = Game3.berrySheetFrame(
      o.berryStage, spec and spec.frameCount, self.playSeconds)
  end
  local ox2, oy2 = o.spriteX2 or 0, o.spriteY2 or 0
  local function drawSprite(refl)
    if ox2 ~= 0 or oy2 ~= 0 then
      G.push()
      G.translate(ox2, oy2)
    end
    local ok = self:drawOwSprite(gid, vx, vy, facing, moving, t, lift, refl, frameOverride)
    if ox2 ~= 0 or oy2 ~= 0 then
      G.pop()
    end
    return ok
  end
  if self._owReflectionPass then
    if reflect then
      drawSprite(true)
    end
    return
  end
  if reflect and not self._tiltBillboard then
    drawSprite(true)
  end
  if not drawSprite(nil) then
    G.setColor(0.12, 0.10, 0.16, 1)
    G.rectangle("fill", px + 3, py + 3, 10, 13)
    G.setColor(
      0.25 + (gid % 5) * 0.12,
      0.35 + (math.floor(gid / 5) % 5) * 0.10,
      0.70 - (gid % 4) * 0.08,
      1)
    G.rectangle("fill", px + 4, py + 4, 8, 11)
  end
  self:drawEmoteAt(vx, vy, o.emote, lift)
end

function Game3:beginGrassRustle(x, y)
  if not Game3.isLandGrass(self:behaviorAt(self.map, x, y)) then return end
  x, y = math.floor(x or 0), math.floor(y or 0)
  self.grassRustle = self.grassRustle or {}
  local list = self.grassRustle
  for i = 1, #list do
    if list[i].x == x and list[i].y == y then
      list[i].t = Game3.GRASS_RUSTLE
      return
    end
  end
  list[#list + 1] = { x = x, y = y, t = Game3.GRASS_RUSTLE }
end

function Game3:stepGrassRustle(dt)
  local list = self.grassRustle
  if not list then return end
  local i = 1
  while i <= #list do
    list[i].t = (list[i].t or 0) - (dt or 0)
    if list[i].t <= 0 then
      list[i] = list[#list]
      list[#list] = nil
    else
      i = i + 1
    end
  end
end

function Game3:grassIsRustling(x, y)
  local list = self.grassRustle
  if not list then return false end
  x, y = math.floor(x or 0), math.floor(y or 0)
  for i = 1, #list do
    if list[i].x == x and list[i].y == y then return true end
  end
  return false
end

-- pokeruby FLDEFF_TALL_GRASS is a transparent 16x16. The ground metatile is
-- opaque, so a full 16x16 blit covers the body of a 16x32 OW sprite (only
-- the hat in the top 16px remains). Draw the bottom 8px over the feet.
-- ROM plays this once on step-in; standing in grass is static.
function Game3:drawGrassTuftAt(map, tileX, tileY, originX, originY)
  map = map or self.map
  if not (map and map.grid and self.layerBottom) then return end
  tileX = math.floor(tileX or 0)
  tileY = math.floor(tileY or 0)
  if not Game3.isLandGrass(self:behaviorAt(map, tileX, tileY)) then return end
  local w, h = map.width or 0, map.height or 0
  if tileX < 0 or tileY < 0 or tileX >= w or tileY >= h then return end
  local image = self.layerBottom
  if map.tileset and map.tileset ~= (self.map and self.map.tileset) then
    image = self:layersFor(map.tileset)
  end
  if not image then return end
  local mid = Game3.metatileOf(map.grid[tileY * w + tileX + 1])
  originX, originY = originX or 0, originY or 0
  local px = (originX + tileX) * Game3.TILE
  local py = (originY + tileY) * Game3.TILE
  local G = love.graphics
  local flip = self:tileAnimFlip()
  G.setColor(1, 1, 1, 1)
  for i = 2, 3 do
    local q = self:quadFor8(mid, i, image)
    local ox = (i % 2) * 8
    if flip then
      G.draw(image, q, px + ox + 8, py + 8, 0, -1, 1)
    else
      G.draw(image, q, px + ox, py + 8)
    end
  end
end

function Game3:drawStandingAt(px, py, sw, sh, body)
  local billboard = self._tiltBillboard
  if not billboard then
    body()
    return
  end
  local s = self._zoomS or 1
  local fx = (px + sw / 2 - (self.camX or 0)) * s
  local fy = (py + sh - (self.camY or 0)) * s
  billboard(fx, fy, function()
    local G = love.graphics
    G.push()
    G.scale(s, s)
    G.translate(-(self.camX or 0), -(self.camY or 0))
    body()
    G.pop()
  end)
end

function Game3:drawActors(overOverlay)
  overOverlay = overOverlay and true or false
  local map = self.map
  local npcs = self:npcsFor(map)
  local actors = {}
  local function addMapActors(src, ox, oy, live)
    ox, oy = ox or 0, oy or 0
    local list = live
    if not list then list = src and src.objects or {} end
    for i = 1, #list do
      local o = list[i]
      if o and not o.hidden and not o.invisible then
        local vx, vy = o.x, o.y
        if live then vx, vy = self:npcVisual(o) end
        local sub = o.fixedPriority and o.objSubpriority or nil
        actors[#actors + 1] = {
          kind = "npc", obj = o, x = vx + ox, y = vy + oy,
          ox = ox, oy = oy, npcs = live, map = src, sub = sub,
        }
      end
    end
  end
  addMapActors(map, 0, 0, npcs)
  -- Only the map the player is standing on. A neighbour's objects have
  -- never been arranged: its ON_TRANSITION is what runs setobjectxyperm,
  -- removeobject and the clearflags that decide where its NPCs stand and
  -- whether they exist yet, and that only runs when the player walks in.
  -- Drawing them anyway put NPCs at raw template positions -- Petalburg's
  -- gym boy at (12,15) instead of the (5,11) his transition moves him to
  -- -- and showed story NPCs that map's script would have removed. They
  -- then snapped into place the instant the player crossed over.
  --
  -- The cart never shows them: it only ever has the current map's object
  -- events loaded. Running a neighbour's transition to fix them up is not
  -- an option -- those scripts also set flags, add objects and start music.
  if not self.invisible then
    local px, py = self:visualTile()
    local sub = self.fixedPriority and self.objSubpriority or nil
    actors[#actors + 1] = { kind = "player", x = px, y = py, sub = sub }
  end
  table.sort(actors, Game3.drawOrderLess)
  for i = 1, #actors do
    local a = actors[i]
    if Game3.spriteDrawsOverOverlay(self:actorDrawElevation(a)) == overOverlay then
    local function body()
      if a.kind == "player" then
        self:drawPlayer()
        if not self.hopping and (self.levitate or 0) <= 0 then
          if self:grassIsRustling(self.playerX, self.playerY) then
            self:drawGrassTuftAt(map, self.playerX, self.playerY)
          end
          if (self.walkCooldown or 0) > 0
              and self:grassIsRustling(self.walkFromX, self.walkFromY) then
            self:drawGrassTuftAt(map, self.walkFromX, self.walkFromY)
          end
        end
      else
        self:drawOneObject(a.obj, a.npcs, a.ox, a.oy, a.map)
        if (a.obj.levitate or 0) <= 0 then
          if self:grassIsRustling(a.obj.x, a.obj.y) then
            self:drawGrassTuftAt(a.map or map, a.obj.x, a.obj.y, a.ox, a.oy)
          end
          if (a.obj.cooldown or 0) > 0
              and self:grassIsRustling(a.obj.fromX, a.obj.fromY) then
            self:drawGrassTuftAt(a.map or map, a.obj.fromX, a.obj.fromY,
              a.ox, a.oy)
          end
        end
      end
    end
    if not self._tiltBillboard then
      body()
    else
      local gid, spec, sw, sh, vx, vy, lift
      if a.kind == "player" then
        gid = self:playerGraphicsId()
        spec = Game3.spriteSpec(self.data and self.data.sprites, gid)
        sw = spec and spec.width or Game3.TILE
        sh = spec and spec.height or Game3.TILE
        vx, vy = self:visualTile()
        lift = self.levitate or 0
      else
        gid = self:resolveGraphicsId(a.obj.graphicsId or 0)
        spec = Game3.spriteSpec(self.data.sprites, gid)
        sw = spec and spec.width or Game3.TILE
        sh = spec and spec.height or Game3.TILE
        vx, vy = a.x, a.y
        lift = a.obj.levitate or 0
      end
      local px, py = Game3.spriteDrawPos(vx, vy, sw, sh, lift)
      self:drawStandingAt(px, py, sw, sh, body)
    end
    end
  end
end

function Game3:drawEmoteAt(tileX, tileY, emote, lift)
  if not emote then return end
  local spec = Game3.emoteSpec(self.data and self.data.sprites, emote)
  local img = spec and self:grabImage(spec.path)
  local G = love.graphics
  G.setColor(1, 1, 1, 1)
  if img then
    local px, py = Game3.emoteDrawPos(tileX, tileY, lift)
    G.draw(img, px, py)
    return
  end
  local glyph = Game3.EMOTE_GLYPH[emote]
  if not glyph then return end
  self:drawText(glyph, tileX * Game3.TILE + 4, tileY * Game3.TILE - 10 - (lift or 0))
end

function Game3:drawPlayer()
  local gid = self:playerGraphicsId()
  local spec = Game3.spriteSpec(self.data and self.data.sprites, gid)
  local sw = spec and spec.width or Game3.TILE
  local sh = spec and spec.height or Game3.TILE
  local vx, vy = self:visualTile()
  local moving = (self.walkCooldown or 0) > 0 and not self.lockAnim
  local lift = self.levitate or 0
  if self.hopping then
    local t = self:walkProgress()
    lift = lift + math.floor(8 * math.sin(t * math.pi) + 0.5)
  end
  local t = self:walkProgress()
  local frameOverride
  if self:fieldMovePosing() then
    frameOverride = self:fieldMovePoseFrame(spec)
    moving = false
  end
  local reflect = self:actorReflects(self.playerX, self.playerY,
    self.hideReflection, sh, self.map, sw, self.walkFromX, self.walkFromY)
  if self._owReflectionPass then
    if reflect then
      self:drawOwSprite(gid, vx, vy, self.facing or "south", moving, t, lift, true,
        frameOverride)
    end
    return
  end
  if reflect and not self._tiltBillboard then
    self:drawOwSprite(gid, vx, vy, self.facing or "south", moving, t, lift, true,
      frameOverride)
  end
  if not self:drawOwSprite(gid, vx, vy, self.facing or "south", moving, t, lift, nil,
      frameOverride) then
    local G = love.graphics
    local px = vx * Game3.TILE
    local py = vy * Game3.TILE - lift
    G.setColor(0.18, 0.12, 0.10, 1)
    G.rectangle("fill", px + 3, py + 4, 10, 12)
    G.setColor(0.93, 0.28, 0.22, 1)
    G.rectangle("fill", px + 4, py + 5, 8, 10)
    G.setColor(0.98, 0.82, 0.55, 1)
    G.rectangle("fill", px + 5, py + 3, 6, 6)
  end
  self:drawEmoteAt(vx, vy, self.emote, lift)
end

-- pokeruby SetFlashScanlineEffectWindowBoundaries: midpoint circle into
-- WIN0H (left<<8 | right). Unwritten rows stay closed (full black).
-- GBA WIN0H is u8 (0-255) over 160 scanlines. The overworld window is
-- drawn at zoomed window pixels, so pass that size or the hole is
-- clipped off-screen and a dark cave is pitch black.
function Game3.flashScanlineWindows(centerX, centerY, radius, screenW, screenH)
  local dest = {}
  local r = math.floor(tonumber(radius) or 0)
  if r < 1 then return dest end
  centerX = math.floor(tonumber(centerX) or 0)
  centerY = math.floor(tonumber(centerY) or 0)
  screenW = math.floor(tonumber(screenW) or Game3.SCREEN_W)
  screenH = math.floor(tonumber(screenH) or Game3.SCREEN_H)
  if screenW < 1 then screenW = Game3.SCREEN_W end
  if screenH < 1 then screenH = Game3.SCREEN_H end
  local maxX = 255
  if screenW > 255 then maxX = screenW end
  local function write(y, left, right)
    if y < 0 or y >= screenH then return end
    if left < 0 then left = 0 elseif left > maxX then left = maxX end
    if right < 0 then right = 0 elseif right > maxX then right = maxX end
    dest[y] = { left, right }
  end
  local v2, v3 = r, 0
  while r >= v3 do
    write(centerY - v3, centerX - r, centerX + r)
    write(centerY + v3, centerX - r, centerX + r)
    write(centerY - r, centerX - v3, centerX + v3)
    write(centerY + r, centerX - v3, centerX + v3)
    v2 = v2 - (v3 * 2) + 1
    v3 = v3 + 1
    if v2 < 0 then
      v2 = v2 + 2 * (r - 1)
      r = r - 1
    end
  end
  return dest
end

-- Sparkle tiles are not extracted; a twinkle at the script's map-local
-- tile (FldEff_Sparkle adds MAP_OFFSET 7 for the GBA sprite, which we skip).
-- Pokécenter / HoF balls are screen-space OBJs (drawPokecenterHealOverlay /
-- drawHofRecordOverlay) mapped through gbaScreenToWorld then drawStandingAt
-- so tilt/zoom plant them on the machine instead of the HUD letterbox.
function Game3:drawFieldEffects()
  local list = self.fieldEffects
  self:drawSurfBlob()
  self:drawOwCinema()
  if not list then return end
  local G = love.graphics
  local t = Game3.TILE
  for i = 1, #list do
    local fx = list[i]
    if fx.id == Game3.FLDEFF_SPARKLE then
      local dur = fx.dur or Game3.FLDEFF_SPARKLE_FRAMES
      local left = fx.left or 0
      local pulse = 0.35 + 0.65 * (left / dur)
      local cx = (fx.x or 0) * t + t / 2
      local cy = (fx.y or 0) * t + t / 2
      local r = 2 + 3 * pulse
      self:drawStandingAt(cx - r, cy - r, r * 2, r * 2, function()
        G.setColor(1, 1, 0.55, pulse)
        G.circle("fill", cx, cy, r)
        G.setColor(1, 1, 1, pulse)
        G.rectangle("fill", cx - 1, cy - r - 1, 2, r * 2 + 2)
        G.rectangle("fill", cx - r - 1, cy - 1, r * 2 + 2, 2)
      end)
    elseif fx.fieldMove then
      local dur = fx.dur or Game3.FLDEFF_FIELD_MOVE_POSE_FRAMES
      local left = fx.left or 0
      local progress = 1 - (left / math.max(dur, 1))
      if progress < 0 then progress = 0 elseif progress > 1 then progress = 1 end
      local gx = fx.gx or (fx.x or 0)
      local gy = fx.gy or (fx.y or 0)
      local cx = gx * t + t / 2
      local cy = gy * t + t / 2
      if fx.id == Game3.FLDEFF_USE_CUT_ON_TREE then
        -- Green slash across the target tile (FldEff_CutGrass / tree).
        local a = math.min(1, progress * 2) * (1 - math.max(0, progress - 0.55) * 2)
        local span = 4 + 10 * math.min(1, progress * 1.6)
        self:drawStandingAt(cx - span, cy - span, span * 2, span * 2, function()
          G.setColor(0.45, 0.95, 0.35, a)
          G.setLineWidth(2)
          G.line(cx - span, cy + span * 0.2, cx + span, cy - span * 0.35)
          G.line(cx - span * 0.7, cy + span * 0.45, cx + span * 0.85, cy - span * 0.1)
          G.setLineWidth(1)
        end)
      elseif fx.id == Game3.FLDEFF_USE_ROCK_SMASH then
        local a = math.min(1, progress * 2.5) * (1 - math.max(0, progress - 0.5) * 2)
        local scatter = 2 + 8 * progress
        self:drawStandingAt(cx - scatter - 4, cy - scatter - 4,
            scatter * 2 + 8, scatter * 2 + 8, function()
          G.setColor(0.55, 0.4, 0.28, a)
          G.rectangle("fill", cx - 3 - scatter * 0.4, cy - 2, 4, 4)
          G.rectangle("fill", cx + scatter * 0.5, cy - 3 - scatter * 0.3, 3, 3)
          G.rectangle("fill", cx - 1, cy + scatter * 0.45, 5, 3)
          G.setColor(0.75, 0.6, 0.4, a * 0.85)
          G.rectangle("fill", cx + 2 - scatter * 0.2, cy + 1, 3, 3)
        end)
      elseif fx.id == Game3.FLDEFF_USE_STRENGTH then
        local pulse = 0.25 + 0.75 * math.sin(progress * math.pi)
        local r = 3 + 5 * pulse
        self:drawStandingAt(cx - r - 2, cy - r - 2, r * 2 + 4, r * 2 + 4, function()
          G.setColor(1, 0.85, 0.25, pulse * 0.7)
          G.circle("line", cx, cy, r)
          G.setColor(1, 1, 0.7, pulse)
          G.circle("fill", cx, cy, 2)
        end)
      end
    end
  end
end

function Game3:drawGbaFieldSprite(img, sx, sy, srcx, srcy, sw, sh, pulse)
  if not img then return end
  local iw, ih = img:getDimensions()
  sw = sw or iw
  sh = sh or ih
  local wx, wy = self:gbaScreenToWorld(sx, sy)
  -- CreateSprite x/y is the sprite centre (sprite.c adds centerToCornerVec
  -- before OAM). drawStandingAt so a tilted overworld billboards these
  -- the way NPCs stand on the floor; the flat path is a no-op wrapper.
  self:drawStandingAt(wx - sw / 2, wy - sh / 2, sw, sh, function()
    self:withGlowPulse(pulse, function()
      self:drawSpriteCenter(img, wx, wy, srcx, srcy, sw, sh)
    end)
  end)
end

function Game3.ensureGlowPulseShader()
  if Game3._glowPulseShader ~= nil then return Game3._glowPulseShader end
  local G = love and love.graphics
  if not (G and G.newShader) then
    Game3._glowPulseShader = false
    return nil
  end
  local ok, sh = pcall(G.newShader, [[
    extern number f;
    vec4 effect(vec4 color, Image tex, vec2 texture_coords, vec2 screen_coords) {
      vec4 p = Texel(tex, texture_coords);
      p.r = p.r + (1.0 - p.r) * f;
      p.g = p.g + (1.0 - p.g) * f;
      return p * color;
    }
  ]])
  Game3._glowPulseShader = (ok and sh) or false
  return Game3._glowPulseShader
end

function Game3:withGlowPulse(factor, fn)
  factor = tonumber(factor) or 0
  if factor <= 0 then return fn() end
  local G = love.graphics
  local sh = Game3.ensureGlowPulseShader()
  if not sh then return fn() end
  sh:send("f", factor / 16)
  G.setShader(sh)
  fn()
  G.setShader()
end

function Game3:drawPokeballGlowBalls(pose)
  local img = self:cinemaPic("pokeballGlow")
  if not (img and pose and pose.balls) then return end
  local iw, ih = img:getDimensions()
  local pulse = pose.pulse or 0
  for i = 1, #pose.balls do
    local p = pose.balls[i]
    self:drawGbaFieldSprite(img, p[1], p[2], 0, 0, iw, ih, pulse)
  end
end

function Game3:drawHofRecordOverlay()
  local list = self.fieldEffects
  if not list then return end
  local left, dur
  for i = 1, #list do
    if list[i].id == Game3.FLDEFF_HALL_OF_FAME_RECORD then
      left, dur = list[i].left, list[i].dur
      break
    end
  end
  if not left then return end
  local n = #(self.party or {})
  if n < 1 then n = 1 end
  local elapsed = (dur or self:hofRecordFrames()) - left
  local pose = Game3.pokeballGlowPose(elapsed, n, Game3.HOF_BALL_X, Game3.HOF_BALL_Y)
  self:drawPokeballGlowBalls(pose)
  if pose.monitors then
    local big = self:cinemaPic("hofMonitorBig")
    local small = self:cinemaPic("hofMonitorSmall")
    local b = Game3.HOF_MONITOR_BIG
    self:drawGbaFieldSprite(big, b[1], b[2], 0, 0, 64, 16)
    for i = 1, #Game3.HOF_MONITOR_SMALL do
      local s = Game3.HOF_MONITOR_SMALL[i]
      self:drawGbaFieldSprite(small, s[1], s[2], 0, 0, 32, 16)
    end
  end
end

function Game3:drawPokecenterHealOverlay()
  local list = self.fieldEffects
  if not list then return end
  local left, dur
  for i = 1, #list do
    if list[i].id == Game3.FLDEFF_POKECENTER_HEAL then
      left, dur = list[i].left, list[i].dur
      break
    end
  end
  if not left then return end
  local n = #(self.party or {})
  if n < 1 then n = 1 end
  local elapsed = (dur or self:pokecenterHealFrames()) - left
  local pose = Game3.pokeballGlowPose(elapsed, n,
    Game3.POKECENTER_BALL_X, Game3.POKECENTER_BALL_Y)
  self:drawPokeballGlowBalls(pose)
  if pose.pcMonitor then
    local mon = self:cinemaPic("pokecenterMonitor")
    self:drawGbaFieldSprite(mon, Game3.POKECENTER_MONITOR_X,
      Game3.POKECENTER_MONITOR_Y, (pose.pcFrame or 0) * 24, 0, 24, 16)
  end
end

function Game3:drawRoute128Fade()
  local a = self:route128FadeAlpha()
  if a <= 0 then return end
  love.graphics.setColor(1, 1, 1, a)
  love.graphics.rectangle("fill", 0, 0, Game3.SCREEN_W, Game3.SCREEN_H)
end

-- Where the player actually is on screen, in view pixels before `scale`.
-- clampCamera's own focus minus the clamped camera: that is vw/2, vh/2 in
-- open ground and drifts off centre exactly as far as the clamp held the
-- camera back at a map edge.
function Game3:playerViewXY()
  local vx, vy = self:visualTile()
  local spec = Game3.spriteSpec(self.data and self.data.sprites,
    self:playerGraphicsId())
  local sw = spec and spec.width or Game3.TILE
  local sh = spec and spec.height or Game3.TILE
  local px, py = Game3.spriteDrawPos(vx, vy, sw, sh, self.levitate or 0)
  local focusX = px + sw / 2
  local focusY = py + sh / 2
  return focusX - (self.camX or 0), focusY - (self.camY or 0)
end

-- pokeruby WriteFlashScanlineEffectBuffer: a hard circle at 120,80, because
-- the cart never clamps the camera -- the player IS at 120,80 always, and it
-- tiles the border block over anything off-map instead. This engine does
-- clamp (a deliberate deviation, so the camera stops at the edge of the drawn
-- map), so at a map edge the player walks away from the screen centre while
-- the hole stayed nailed to it: the player ended up at the rim of the circle,
-- or outside it, and caves were unnavigable. Follow the player instead.
-- Drawn as WIN0H scanlines so a failed LÖVE stencil cannot hide the player.
-- vw/vh/scale are the overworld window (zoom); omit them for the 240×160
-- letterbox path.
function Game3:drawFlashOverlay(vw, vh, scale)
  local r = self:flashRadius()
  if r < 1 then return end
  vw = math.floor(tonumber(vw) or Game3.SCREEN_W)
  vh = math.floor(tonumber(vh) or Game3.SCREEN_H)
  if vw < 1 then vw = Game3.SCREEN_W end
  if vh < 1 then vh = Game3.SCREEN_H end
  local worldScale = tonumber(scale) or 1
  if worldScale <= 0 then worldScale = 1 end
  scale = self:flashOverlayScale(scale, vw)
  r = r * scale
  local G = love.graphics
  local pvx, pvy = self:playerViewXY()
  local cx, cy = pvx * worldScale, pvy * worldScale
  -- The zoom path draws the world into a gw x gh drawable centred in the
  -- window (drawWorld's translate adds (w - gw) / 2), so the hole has to
  -- carry the same offset or it sits at the window centre while the player
  -- sits at the drawable's.
  local gw, gh = tonumber(self._tiltGw), tonumber(self._tiltGh)
  if gw and gh and gw > 0 and gh > 0 then
    cx = cx + (vw - gw) / 2
    cy = cy + (vh - gh) / 2
  end
  -- The letterbox path passes no scale and draws 1px per world pixel, so the
  -- view coords are already the window's.
  if cx ~= cx or cy ~= cy then cx, cy = vw / 2, vh / 2 end
  local win = Game3.flashScanlineWindows(cx, cy, r, vw, vh)
  G.setColor(0, 0, 0, 1)
  for y = 0, vh - 1 do
    local row = win[y]
    local left, right = 0, 0
    if row then
      left, right = row[1], row[2]
    end
    if left > 0 then G.rectangle("fill", 0, y, left, 1) end
    if right < vw then
      G.rectangle("fill", right, y, vw - right, 1)
    end
  end
end

-- Orb tiles are not in the cart for this special; sub_808161C loads
-- pal 0 = 0x1F or pal 1 = 0x7C00 into OBJ pal 15, plus a WIN0 hole.
function Game3:drawOrbCutscene()
  local o = self.orb
  if not o then return end
  local G = love.graphics
  local r = o.r or Game3.ORB_OPEN_DEST_R
  local cx = o.cx or 120
  local cy = o.cy or 80
  local alpha = 1
  if o.stage == "close" then
    local left = o.left or 0
    alpha = math.max(0, math.min(1, left / Game3.ORB_CLOSE_FRAMES))
  end
  local win = Game3.flashScanlineWindows(cx, cy, r)
  G.setColor(0, 0, 0, alpha)
  for y = 0, Game3.SCREEN_H - 1 do
    local row = win[y]
    local left, right = 0, 0
    if row then
      left, right = row[1], row[2]
    end
    if left > 0 then G.rectangle("fill", 0, y, left, 1) end
    if right < Game3.SCREEN_W then
      G.rectangle("fill", right, y, Game3.SCREEN_W - right, 1)
    end
  end
  local pal = Game3.ORB_PAL_RED
  if (o.pal or 0) ~= 0 then pal = Game3.ORB_PAL_BLUE end
  local cr, cg, cb = Game3.rgb555(pal)
  G.setColor(cr, cg, cb, Game3.ORB_WASH_ALPHA * alpha)
  G.rectangle("fill", 0, 0, Game3.SCREEN_W, Game3.SCREEN_H)
  if o.stage == "open" or o.stage == "hold" then
    local pulse = 0.5 + 0.5 * math.sin((o.phase or 0) * math.pi)
    G.setColor(1, 1, 1, alpha * (0.25 + 0.35 * pulse))
    G.circle("fill", cx, cy, 10 + 6 * pulse)
    G.setColor(cr, cg, cb, alpha * (0.35 + 0.25 * pulse))
    G.circle("fill", cx, cy, 6 + 3 * pulse)
  end
end

function Game3:drawWeatherOverlay(vw, vh)
  self:drawWeatherTint(vw, vh)
  self:drawWeatherSprites(vw, vh)
end

-- Ground tiles (this map + touching connections + nearby void fill +
-- 2×2 border). Caller has already translated by -cam. Overlay tops
-- (roofs / BG1) draw after sprites on both the flat path and the tilt
-- billboard path.
function Game3:drawMapGround(includeOverlay)
  local map = self.map
  local x0, y0, x1, y1 = self:visibleRange()
  if self.layerBottom then
    self:drawVoidFill("bottom")
    self:drawBorderFill(self.layerBottom, map)
    self:drawLayer(self.layerBottom, map, x0, y0, x1, y1, 0, 0)
    self:drawConnections("bottom")
  else
    self:drawFallbackMap()
  end
  if self.layerTop then
    self:drawBorderFill(self.layerTop, map, "covered")
    self:drawLayer(self.layerTop, map, x0, y0, x1, y1, 0, 0, "covered")
    self:drawConnections("top", "covered")
  end
  if includeOverlay then
    self:drawMapOverlay()
  end
end

function Game3:drawMapOverlay()
  if not self.layerTop then return end
  local map = self.map
  local x0, y0, x1, y1 = self:visibleRange()
  self:drawBorderFill(self.layerTop, map, "overlay")
  self:drawLayer(self.layerTop, map, x0, y0, x1, y1, 0, 0, "overlay")
  self:drawConnections("top", "overlay")
end

function Game3:drawWorldStanding(overOverlay)
  -- field_door.c door_build_blockdef fills a metatile's first four tile
  -- entries -- the bottom layer -- and ZEROES the last four, so an open
  -- door has no BG1 content at all and the player walks in FRONT of it.
  -- Drawing the door after the actors hid the player behind the doorway.
  self:drawDoorAnim(overOverlay)
  self:drawActors(overOverlay)
  self:drawDecorPlacingCursor(overOverlay)
  self:drawFieldEffects()
  self:drawPokecenterHealOverlay()
  self:drawHofRecordOverlay()
  if not self._tiltBillboard then
    self:drawRotatingGates()
  end
end

function Game3:tiltMesh()
  local Renderer = require("src.render.Renderer")
  local shader = Renderer.tiltShader and Renderer:tiltShader()
  local mesh = Renderer.tiltMesh and Renderer:tiltMesh()
  if not (shader and mesh) then return nil end
  return mesh, shader
end

function Game3:ensureTiltCanvas(key, gw, gh)
  local canvas = self[key]
  if canvas and canvas.getWidth and canvas:getWidth() == gw
      and canvas.getHeight and canvas:getHeight() == gh then
    return canvas
  end
  if canvas and canvas.release then canvas:release() end
  local PixelCanvas = require("src.render.PixelCanvas")
  local ok, made = pcall(PixelCanvas.new, gw, gh, "linear")
  if not ok or not made then
    self[key] = nil
    return nil
  end
  self[key] = made
  return made
end

function Game3:paintTiltLayer(canvas, s, body)
  local G = love.graphics
  local previous = G.getCanvas()
  G.setCanvas(canvas)
  G.clear(0, 0, 0, 0)
  G.push()
  G.origin()
  G.scale(s, s)
  G.translate(-(self.camX or 0), -(self.camY or 0))
  body()
  G.pop()
  G.setCanvas(previous)
end

function Game3:projectTiltCanvas(canvas, mesh, shader, w, h, gw, gh)
  local G = love.graphics
  local Tilt = require("src.render.Tilt")
  mesh:setTexture(canvas)
  mesh:setVertices(Tilt.meshCorners(gw, gh))
  G.push()
  G.translate((w - gw) / 2, (h - gh) / 2)
  G.setColor(1, 1, 1, 1)
  G.setShader(shader)
  G.draw(mesh)
  G.setShader()
  G.pop()
end

-- Flat world at zoom scale s, in window pixels. Tiles are live (Gen 1
-- windowed SpriteBatch), so a larger view shows connected maps.
function Game3:drawWorldBody(s)
  local G = love.graphics
  G.push()
  G.scale(s, s)
  G.translate(-(self.camX or 0), -(self.camY or 0))
  self:drawMapGround(false)
  self:drawWorldStanding(false)
  self:drawMapOverlay()
  self:drawWorldStanding(true)
  G.pop()
end

-- Ground on the perspective mesh, people billboarded upright, then BG1
-- overlay (roofs) projected on top so sprites stay under buildings the
-- way GBA OBJ sits under BG1 — except elevation 4 (cycling road) which
-- is OAM pri 1, in front of BG1. Baking overlay into the ground capture
-- put the player on every roof.
function Game3:drawTilted(w, h, s, gw, gh)
  local mesh, shader = self:tiltMesh()
  if not mesh then
    self:drawWorldBody(s)
    return
  end
  local G = love.graphics
  local Tilt = require("src.render.Tilt")
  gw = gw or w
  gh = gh or h
  local ground = self:ensureTiltCanvas("tiltCanvas", gw, gh)
  if not ground then
    self:drawWorldBody(s)
    return
  end
  self:paintTiltLayer(ground, s, function()
    self:drawMapGround(false)
    self:drawRotatingGates()
    -- Reflections are ground-plane OBJs (south of the feet). Billboard
    -- them with the NPC and they stand upright on dirt; paint them here
    -- so tilt lays them on the water.
    self._owReflectionPass = true
    self:drawActors(false)
    self:drawActors(true)
    self._owReflectionPass = nil
  end)
  self:projectTiltCanvas(ground, mesh, shader, w, h, gw, gh)
  self._zoomS = s
  self._tiltBillboard = function(fx, fy, body)
    if not Tilt.onGround(fx, fy, gw, gh, 32 * s) then return end
    local sx, sy = Tilt.groundPoint(fx, fy, gw, gh)
    G.push()
    G.translate(sx - fx + (w - gw) / 2, sy - fy + (h - gh) / 2)
    body()
    G.pop()
  end
  self:drawWorldStanding(false)
  if self.layerTop then
    local overlay = self:ensureTiltCanvas("tiltOverlayCanvas", gw, gh)
    if overlay then
      self:paintTiltLayer(overlay, s, function()
        self:drawMapOverlay()
      end)
      self:projectTiltCanvas(overlay, mesh, shader, w, h, gw, gh)
    else
      G.push()
      G.scale(s, s)
      G.translate(-(self.camX or 0), -(self.camY or 0))
      self:drawMapOverlay()
      G.pop()
    end
  end
  self:drawWorldStanding(true)
  self._tiltBillboard = nil
end

function Game3:drawWorldFx(w, h, s)
  local G = love.graphics
  self:drawFlashOverlay(w, h, s)
  self:drawWeatherOverlay(w, h)
  if self:isUnderwater() then
    G.setColor(0, 0.12, 0.35, 0.28)
    G.rectangle("fill", 0, 0, w, h)
  end
  -- Cover the zoomed window. Putting this on the 240×160 HUD letterbox
  -- left a black rectangle in the centre with the map around the edges.
  self:drawScreenFade(w, h)
  G.setColor(1, 1, 1, 1)
end

function Game3:drawPlayHud()
  -- Veil first: a held TO_BLACK used to paint over the clock / bag and
  -- leave a dead black screen. Overworld fades still paint in drawWorldFx.
  if not self:fieldShowsWorld() then
    self:drawScreenFade()
  end
  if self.field then
    self:drawFieldOverlay()
  end
  -- Top-of-screen route/town name (map_name_popup.c). Independent of
  -- self.field: connection walks and warps arm it while the player is free.
  self:drawMapNamePopup()
  self:drawOrbCutscene()
  self:drawRoute128Fade()
  self:drawMoneyBox()
  self:drawCoinsBox()
end

function Game3:drawOverworldWindow(w, h)
  local G = love.graphics
  local Tilt = require("src.render.Tilt")
  local _, _, s, gw, gh = self:syncWorldView()
  local flashing = self:flashRadius() > 0
  -- GBA WIN0 is 24px on 240×160. Survey zoom OUT + tilt left a speck on
  -- the void (Dewford Granite). Flatten and FIT so the hole matches the cart.
  if flashing then
    s = self:flashOverlayScale(s, w)
    gw, gh = w, h
    self._zoomS = s
    self._tiltGw, self._tiltGh = gw, gh
    local vw = math.ceil(gw / s)
    local vh = math.ceil(gh / s)
    if vw % 2 ~= 0 then vw = vw + 1 end
    if vh % 2 ~= 0 then vh = vh + 1 end
    if vw < 2 then vw = 2 end
    if vh < 2 then vh = 2 end
    self.viewW, self.viewH = vw, vh
  end
  -- World:draw re-follows after sizing the view. Zoom/tilt change viewW
  -- here; a camera from the previous scale leaves the player off centre.
  self:clampCamera()
  if flashing then
    G.setColor(0, 0, 0, 1)
  else
    G.setColor(0.10, 0.22, 0.38, 1)
  end
  G.rectangle("fill", 0, 0, w, h)
  G.setColor(1, 1, 1, 1)
  local tilt = (not flashing) and Tilt.active() and self:tiltMesh() ~= nil
  if tilt then
    self:drawTilted(w, h, s, gw, gh)
  else
    self:drawWorldBody(s)
  end
  self:drawWorldFx(w, h, s)
end

function Game3:drawHudLetterbox(w, h)
  if not self:playHudActive() then return end
  local G = love.graphics
  local scale, ox, oy = letterbox(self, w, h)
  -- Paint the 240×160 UI into the window, not onto a canvas. A canvas
  -- cleared to (0,0,0,0) still blit as an opaque black plate on some
  -- Windows GL drivers (berry plant / yes-no over the zoomed map).
  G.push()
  G.translate(ox, oy)
  G.scale(scale, scale)
  self:drawPlayHud()
  G.pop()
end

-- 240×160 letterbox path (battles, boot, opaque field UIs).
function Game3:drawPlay()
  local G = love.graphics
  local saveW, saveH = self.viewW, self.viewH
  local saveCamX, saveCamY = self.camX, self.camY
  self.viewW, self.viewH = Game3.SCREEN_W, Game3.SCREEN_H
  -- Survey zoom leaves camX/camY aimed at a huge view. Cropping that into
  -- 240×160 showed tileset atlas / empty fill ("zoomed randomness").
  self:clampCamera()
  if self:flashRadius() > 0 then
    G.setColor(0, 0, 0, 1)
  else
    G.setColor(0.10, 0.22, 0.38, 1)
  end
  G.rectangle("fill", 0, 0, Game3.SCREEN_W, Game3.SCREEN_H)
  G.push()
  G.translate(-self.camX, -self.camY)
  self:drawMapGround(false)
  self:drawWorldStanding(false)
  self:drawMapOverlay()
  self:drawWorldStanding(true)
  G.pop()
  self.viewW, self.viewH = saveW, saveH
  self.camX, self.camY = saveCamX, saveCamY
  self:drawFlashOverlay()
  self:drawWeatherOverlay()
  if self:isUnderwater() then
    G.setColor(0, 0.12, 0.35, 0.28)
    G.rectangle("fill", 0, 0, Game3.SCREEN_W, Game3.SCREEN_H)
  end
  G.setColor(1, 1, 1, 1)
  self:drawPlayHud()
end

function Game3:drawScene()
  local G = love.graphics
  G.setColor(0.10, 0.22, 0.38, 1)
  G.rectangle("fill", 0, 0, Game3.SCREEN_W, Game3.SCREEN_H)
  G.setColor(0.93, 0.93, 0.86, 1)
  local info = GameVersion.info()
  local header = self.data.header or {}
  local constants = self.data.constants or {}
  if self.phase == "battle" then
    self:drawBattle()
    return
  end
  if self.phase == "battle_transition" and self.map then
    -- Wipe overlays the frozen field; reuse play draw then veil.
    self:drawPlay()
    self:drawBattleEntrance(Game3.SCREEN_W, Game3.SCREEN_H)
    return
  end
  if self.phase == "play" and self.map then
    self:drawPlay()
    return
  end
  if self.phase == "boot" then
    self:drawBoot()
    return
  end
  self:drawText("Internal species names", 16, 8)
  local rows = 10
  local start = self.scroll
  for i = 0, rows - 1 do
    local row = self.named[start + i]
    if not row then break end
    self:drawText(("%3d  %s"):format(row.id, row.name), 16, 28 + i * 12)
  end
  self:drawText("Up/Down  scroll    B  back", 16, 148)
  G.setColor(1, 1, 1, 1)
end

function Game3:ensureCanvas()
  if self.gbaCanvas then return self.gbaCanvas end
  local ok, canvas = pcall(PixelCanvas.new,
    Game3.SCREEN_W, Game3.SCREEN_H, "nearest")
  if not ok or not canvas then return nil end
  self.gbaCanvas = canvas
  return canvas
end

function Game3:draw()
  GameViewport.begin(3)
  GameViewport.setTarget()
  local G = love.graphics
  local w, h = GameViewport.dimensions()
  G.clear(0.02, 0.04, 0.07, 1)
  if (self.phase == "play" or self.phase == "battle_transition")
      and self.map and (self.phase == "battle_transition" or self:fieldShowsWorld()) then
    self:drawOverworldWindow(w, h)
    if self.phase == "battle_transition" then
      -- Full-window wipe over the zoomed composite (not just 240x160 HUD).
      self:drawBattleEntrance(w, h)
    else
      self:drawHudLetterbox(w, h)
    end
  else
    local scale, ox, oy = letterbox(self, w, h)
    local canvas = self:ensureCanvas()
    if canvas then
      local prev = GameViewport.target()
      -- Flash overlay uses G.stencil. LÖVE 11 requires stencil=true on the
      -- active Canvas (Dewford Gym setflashradius).
      if not pcall(G.setCanvas, { canvas, stencil = true }) then
        G.setCanvas(canvas)
      end
      G.origin()
      G.clear(0.10, 0.22, 0.38, 1)
      self:drawScene()
      G.setCanvas(prev)
      G.origin()
      G.setColor(1, 1, 1, 1)
      G.draw(canvas, ox, oy, 0, scale, scale)
    else
      G.push()
      G.translate(ox, oy)
      G.scale(scale, scale)
      self:drawScene()
      G.pop()
    end
  end
  GameViewport.finish(self)
  -- OS-window chrome: draw after companion composition so viewport layouts
  -- neither shrink nor cover the touch pad.
  TouchControls:draw()
end

function Game3:hotkey(key)
  if key == "1" then
    self:_cycleSpeed(1)
    return true
  end
  if key == "3" then
    local Tilt = require("src.render.Tilt")
    Tilt.cycle()
    self:persistDisplayOptions()
    return true
  end
  if not self:displayGateOK() then return false end
  local Zoom = require("src.render.Zoom")
  local fit = self:fitScale()
  if key == "-" or key == "kp-" then
    Zoom.step(-1, fit)
    self:persistDisplayOptions()
    return true
  elseif key == "=" or key == "kp+" then
    Zoom.step(1, fit)
    self:persistDisplayOptions()
    return true
  elseif key == "4" then
    Zoom.cycle(fit)
    self:persistDisplayOptions()
    return true
  end
  return false
end

function Game3:keypressed(key)
  if key == "escape" and self.phase == "battle" then
    self:endBattle()
    return
  elseif key == "escape" and (self.phase == "roster" or self.phase == "play") then
    self:clearTransientOverlay()
    self.phase = "boot"
    self:resetBoot()
    return
  elseif key == "escape" and self.onExit then
    self.onExit()
    return
  end
  -- Dev-only force-shiny toggle (Gen3 has no Gen1-style backtick console).
  local devMode = os.getenv("POKEPORT_DEV") == "1" or _G.POKEPORT_DEV_MODE == true
  if devMode and key == "`" then
    self.forceShiny = not self.forceShiny
    print(self.forceShiny and "forceShiny ON" or "forceShiny OFF")
    return
  end
  if self:hotkey(key) then return end
  Input:keypressed(key)
end

function Game3:keyreleased(key)
  Input:keyreleased(key)
end

function Game3:wheelmoved(_x, dy)
  if self:displayGateOK() and dy ~= 0 then
    local Zoom = require("src.render.Zoom")
    if dy > 0 then Zoom.step(1, self:fitScale())
    else Zoom.step(-1, self:fitScale()) end
    self:persistDisplayOptions()
    return
  end
  if dy > 0 then self:moveScroll(-1)
  elseif dy < 0 then self:moveScroll(1) end
end

function Game3:touchpressed(id, x, y)
  if TouchControls:touchpressed(id, x, y) then return end
end

function Game3:touchmoved(id, x, y)
  TouchControls:touchmoved(id, x, y)
end

function Game3:touchreleased(id, x, y)
  TouchControls:touchreleased(id, x, y)
end

function Game3:mousepressed(x, y, button, istouch)
  if istouch then return end
  if button == 1 then self:touchpressed("mouse", x, y) end
end

function Game3:mousemoved(x, y, dx, dy, istouch)
  if istouch then return end
  if love.mouse.isDown(1) then self:touchmoved("mouse", x, y) end
end

function Game3:mousereleased(x, y, button, istouch)
  if istouch then return end
  if button == 1 then self:touchreleased("mouse", x, y) end
end

-- LÖVE has no touchcancelled: a finger the OS takes away (an app switch, a
-- system gesture) never fires touchreleased and would strand its GBA button
-- held forever -- TouchControls:reset is the only thing that frees it.
function Game3:focus(f)
  Input:reset()
  TouchControls:reset()
  if f then Input:reconcile() end
end

function Game3:visible(v)
  if v then
    self:onResume()
  else
    Input:reset()
    TouchControls:reset()
  end
end

function Game3:onResume()
  Input:reset()
  TouchControls:reset()
  Input:reconcile()
end

function Game3:gamepadpressed(joystick, button)
  TouchControls:noteGamepad()
  local selectHeld = Input:isDown("select")
  if not selectHeld and joystick and joystick.isGamepadDown then
    local ok, down = pcall(function()
      return joystick:isGamepadDown("back")
    end)
    selectHeld = ok and down == true
  end
  if not selectHeld then
    if button == "rightshoulder" or button == "righttrigger" then
      self:_cycleSpeed(1)
      return
    elseif button == "leftshoulder" or button == "lefttrigger" then
      self:_cycleSpeed(-1)
      return
    end
  end
  Input:gamepadpressed(joystick, button)
end

function Game3:gamepadreleased(joystick, button)
  Input:gamepadreleased(joystick, button)
end

function Game3:gamepadaxis(joystick, axis, value)
  if math.abs(value) > 0.5 then TouchControls:noteGamepad() end
  Input:gamepadaxis(joystick, axis, value)
end

-- Phone accelerometers show up as joysticks on Android.  Treating them as a
-- controller hid the overlay the instant the phone moved, so a tap only
-- brought the pad back instead of pressing A (src/core/Game.lua:940).
function Game3:joystickpressed(joystick, button)
  if GamepadMap.isAccelerometer(joystick) then return end
  TouchControls:noteGamepad()
  Input:joystickpressed(joystick, button)
end

function Game3:joystickreleased(joystick, button)
  if GamepadMap.isAccelerometer(joystick) then return end
  Input:joystickreleased(joystick, button)
end

function Game3:joystickaxis(joystick, axis, value)
  if GamepadMap.isAccelerometer(joystick) then return end
  if math.abs(value) > 0.5 then TouchControls:noteGamepad() end
  Input:joystickaxis(joystick, axis, value)
end

function Game3:joystickhat(joystick, hat, direction)
  if GamepadMap.isAccelerometer(joystick) then return end
  if direction ~= "c" then TouchControls:noteGamepad() end
  Input:joystickhat(joystick, hat, direction)
end

function Game3:joystickadded()
  Input:reset()
  Input:reconcile()
  TouchControls:reset()
end

function Game3:joystickremoved()
  Input:reset()
  Input:reconcile()
  TouchControls:joystickremoved()
end

Game3Boot.attach(Game3)
Game3Pc.attach(Game3)
Game3PlayerPc.attach(Game3)
Game3WeatherFx.attach(Game3)
Game3Tv.attach(Game3)
Game3BattleTransition.attach(Game3)
Game3MoveAnim.attach(Game3)
Game3BattleFx.attach(Game3)

return Game3
